/*
 * Raspberry Pi 4 Model B – MLX91219 current sensor reader via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 VDD  -> 3.3 V (Pin 1)
 *   ADS1115 GND  -> GND   (Pin 6)
 *   ADS1115 SDA  -> GPIO2 (BCM 3, Pin 3)  / I2C bus 1
 *   ADS1115 SCL  -> GPIO3 (BCM 5, Pin 5)  / I2C bus 1
 *   ADS1115 ADDR -> GND   (I2C address 0x48)
 *   MLX91219 VCC -> 5 V (Pin 2/4) or 3.3 V (Pin 1)
 *   MLX91219 GND -> GND
 *   MLX91219 OUT -> ADS1115 AIN0 (Pin 1)
 *
 * Build:  gcc -O2 -Wall -o current_reader current_reader.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config-register bit fields */
#define ADS1115_CFG_OS_BEGIN    (1u << 15)   /* Operational status / single-shot start */
#define ADS1115_CFG_MUX_AIN0   (4u << 12)    /* AIN0 single-ended (MUX = 100) */
#define ADS1115_CFG_PGA_4_096  (1u << 9)     /* PGA = ±4.096 V */
#define ADS1115_CFG_MODE_SS    (1u << 8)     /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS  (4u << 5)     /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  (0x3 << 0)    /* Disable comparator */

#define ADS1115_PGA_4_096V     4.096f
#define ADS1115_MAX_COUNT      32767.0f     /* 16-bit signed positive max */
#define SAMPLE_PERIOD_US      500000       /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * The ADS1115 expects the most-significant byte first, so we
 * perform a single I2C write with the two bytes in the correct order.
 */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * The ADS1115 returns the two bytes in the order MSB first, so
 * we read 2 bytes and then swap them to get the correct value.
 */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg(0x%02X): write (reg select) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success, -1 on error.
 */
static int read_current(int fd, float *current)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for the conversion to complete (~8 ms at 128 SPS). */
    usleep(10000);

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    int16_t signed_raw = (int16_t)raw;
    *current = (signed_raw / ADS1115_MAX_COUNT) * ADS1115_PGA_4_096V;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADS1115 slave address. */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("ADS1115 (0x%02X) opened on %s. Reading current every 500 ms. "
           "Press Ctrl+C to exit.\n", ADS1115_ADDR, I2C_BUS);

    while (g_running) {
        float current;
        if (read_current(fd, &current) == 0) {
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current (sensor absent or bus error).\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

