#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define FLAME_SENSOR_PIN 4   /* BCM GPIO4  – digital output D0 */
#define MCP3008_CS_PIN   8   /* BCM GPIO8 – MCP3008 chip-select CE0 */

#define LOG_FILE         "flame_data.csv"
#define SAMPLE_INTERVAL  1   /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, or -1 on error.
 */
static int mcp3008_read(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       – start bit
     *   tx[1] = (0x08 | channel) << 4      – SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits
     *   tx[2] = 0x00                       – padding to clock out low data bits
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_temperature(int adc_value)
{
    /*
     * Placeholder linear approximation.
     * A real deployment requires a calibrated transfer function
     * derived from the specific flame sensor module and load resistor.
     */
    return (float)adc_value * 0.1f;
}

static int log_data(FILE *fp, int flame_detected, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

