#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define FLAME_SENSOR_PIN 4   /* BCM GPIO4  – digital output D0 */
#define MCP3008_CS_PIN   8   /* BCM GPIO8 – MCP3008 chip-select CE0 */

#define LOG_FILE         "flame_data.csv"
#define SAMPLE_INTERVAL  1   /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, or -1 on error.
 */
static int mcp3008_read(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       – start bit
     *   tx[1] = (0x08 | channel) << 4      – SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits
     *   tx[2] = 0x00                       – padding to clock out low data bits
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_temperature(int adc_value)
{
    /*
     * Placeholder linear approximation.
     * A real deployment requires a calibrated transfer function
     * derived from the specific flame sensor module and load resistor.
     */
    return (float)adc_value * 0.1f;
}

