        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,flame_detected,temperature_c\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

