        if (digital_value < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n", FLAME_SENSOR_PIN, strerror(errno));
            /* Skip this sample but keep running */
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        flame_detected = (digital_value == 1) ? 1 : 0;

        /* Read analog value from MCP3008 channel 0 */
        adc_value = mcp3008_read(spi_fd, 0);
