#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define HEAT_SENSOR_ADC_CHANNEL 0
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "fire_log.txt"
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 100000
#define BUZZER_DURATION_US 2000000
#define TEMP_THRESHOLD 60.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(float *temp) {
    if (i2c_fd < 0) return -1;
    if (i2c_write_reg16(i2c_fd, 0x01, 0x4003) < 0) return -1;
    usleep(10000);
    uint16_t raw;
    if (i2c_read_reg16(i2c_fd, 0x00, &raw) < 0) return -1;
    int16_t signed_raw = (int16_t)raw;
    *temp = (float)signed_raw * 0.0625f;
    return 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise buzzer state\n");
        cleanup();
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_event("System started");

    int last_flame = 0;
    int debounce_count = 0;

    while (running) {
        int flame = gpioRead(FLAME_SENSOR_PIN);
        if (flame < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            log_event("Error: flame sensor read failed");
            usleep(POLL_DELAY_US);
            continue;
        }

        if (flame != last_flame) {
            debounce_count++;
            if (debounce_count >= 2) {
                last_flame = flame;
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
        }

        float temp = 0.0f;
        if (read_temperature(&temp) < 0) {
            fprintf(stderr, "Failed to read temperature sensor\n");
            log_event("Error: temperature sensor read failed");
        }

        int fire = 0;
        if (flame && (temp > TEMP_THRESHOLD)) {
            fire = 1;
        }

        if (fire) {
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Failed to activate buzzer\n");
            }
            log_event("Fire detected!");
            usleep(BUZZER_DURATION_US);
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Failed to deactivate buzzer\n");
            }
        } else if (flame) {
            log_event("Flame detected!");
        } else if (temp > TEMP_THRESHOLD) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temp);
            log_event(msg);
        }

        usleep(POLL_DELAY_US);
    }

    log_event("System shutting down");
    gpioWrite(BUZZER_PIN, 0);
    cleanup();
    return 0;
}

