#define SPI_BITS         8
#define SPI_MODE         0

#define FAN_GPIO_LINE    18
#define GPIO_CHIP_NAME   "gpiochip4"
#define GPIO_CHIP_FALLBACK "gpiochip0"

#define CURRENT_THRESHOLD 100.0
#define LOG_FILE          "current_log.txt"
#define SAMPLE_INTERVAL   1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, then 10-bit result */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    /* Sensor-absent / bus fault detection */
    if (adc_value == 0x000 || adc_value == 0x3FF) {
        fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor absent or bus fault\n", adc_value);
        return -1;
    }

    return adc_value;
}

static void log_current(int adc_value, double current, const char *status)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, ADC: %d, Current: %.2f, Status: %s\n",
            timestamp, adc_value, current, status);
    fclose(fp);
}

