#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

/* Calibration constants for MICS-4514 (example values — calibrate for your specific module) */
#define R0 1000.0
#define SCALING_FACTOR 0.1
#define OFFSET 0.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 16-bit raw ADC value from the sensor (simulated via pigpio gpioRead) */
static int read_raw_adc(int handle, int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", pin, pigpio_error(val));
        return -1;
    }
    return (val * 2) - 1;
}

/* Convert raw ADC value to CO concentration in ppm using a logarithmic curve */
static float calculate_co_ppm(int raw_adc) {
    if (raw_adc < 0) return -1.0;
    float r = (float)raw_adc;
    float ratio = r / R0;
    if (ratio <= 0.0) return 0.0;
    float ppm = SCALING_FACTOR * powf(ratio, -1.0) + OFFSET;
    return ppm;
}

/* Log CO concentration with timestamp to file */
static int log_co_ppm(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f ppm\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    /* Simulated ADC on GPIO 4 (adjust to your ADC pin) */
    int adc_pin = 4;
    if (gpioSetMode(adc_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", adc_pin);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw_adc = read_raw_adc(i2c_handle, adc_pin);
            if (raw_adc >= 0) break;
            if (!running) break;
            fprintf(stderr, "I2C read attempt %d/%d failed, retrying...\n",
                    attempt + 1, MAX_RETRIES);
            sleep(1);
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Failed to read valid ADC value after %d attempts. "
                            "Sensor may be disconnected or bus error.\n", MAX_RETRIES);
            /* Continue running so the program can recover if the sensor reconnects */
            continue;
        }

        float co_ppm = calculate_co_ppm(raw_adc);
        if (co_ppm < 0) {
            fprintf(stderr, "Error calculating CO ppm from raw ADC value.\n");
        } else {
            if (log_co_ppm(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO ppm value.\n");
            } else {
                printf("CO: %.2f ppm\n", co_ppm);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

