/*
 * KY-026 Flame Sensor + MCP3008 ADC reader for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   KY-026 D0  -> GPIO 4  (flame presence digital output)
 *   MCP3008 CS -> GPIO 8  (CE0)
 *   MCP3008 CLK-> GPIO 11 (SCLK)
 *   MCP3008 DOUT-> GPIO 9  (MISO)
 *   MCP3008 DIN -> GPIO 10 (MOSI)
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CH0 -> KY-026 A0 analog output
 *
 * Build: gcc -O2 -Wall -o flame_reader flame_reader.c -lpigpio -lrt
 * Run:   sudo ./flame_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_GPIO        4
#define SPI_CHANNEL       0          /* CE0 */
#define SPI_SPEED         1000000    /* 1 MHz */
#define MCP3008_CHANNEL   0          /* A0 */
#define LOG_FILE          "flame_data.csv"
#define SAMPLE_PERIOD_US  1000000    /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/* Returns 0..1023 on success, -1 on error. */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in bits 7..6
     *   rx[2] = b7..0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(int flame_present, int temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", ts, flame_present, temperature) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- flame sensor GPIO --- */
    if (gpioSetMode(FLAME_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(FLAME_GPIO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(FLAME_GPIO, PI_PUD_DOWN);  /* idle low */

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl-C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        int flame_present = gpioRead(FLAME_GPIO);
        if (flame_present < 0) {
            fprintf(stderr, "gpioRead(FLAME_GPIO) failed\n");
            break;
        }

        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "MCP3008 read failed; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(flame_present, adc_value) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

