#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *co, uint16_t *no2) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *co = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *no2 = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float calculate_co_ppm(uint16_t co_raw) {
    /* Placeholder linear conversion; replace with sensor datasheet formula. */
    return (float)co_raw * 0.1f;
}

static int log_co_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    } else {
        fprintf(fp, "timestamp_error, %.2f\n", co_ppm);
    }
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", ALERT_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    } else {
        fprintf(fp, "timestamp_error, %.2f\n", co_ppm);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t co_raw = 0, no2_raw = 0;

        if (read_sensor_data(i2c_handle, &co_raw, &no2_raw) != 0) {
            fprintf(stderr, "Sensor read error; retrying in %d seconds.\n", READ_INTERVAL_SEC);
            gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
            continue;
        }

        float co_ppm = calculate_co_ppm(co_raw);

        if (log_co_data(co_ppm) != 0) {
            fprintf(stderr, "Failed to log CO data.\n");
        }

        if (co_ppm > CO_THRESHOLD) {
            if (log_alert(co_ppm) != 0) {
                fprintf(stderr, "Failed to log alert.\n");
            }
        }

        printf("CO: %.2f ppm, NO2: %u\n", co_ppm, no2_raw);

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nAir quality monitoring stopped.\n");
    return 0;
}

