/*
 * IMP23ABSU dual-channel I2C-emulated MEMS microphone logger.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * Sensors: STMicroelectronics IMP23ABSU (analog OUT -> GPIO2/BCM2, GPIO3/BCM3)
 * API:    Bit-banged I2C (no external I2C expander required)
 * Log:    audio_log.txt  (timestamp,avg_dB)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mic_logger mic_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define MIC1_GPIO        2   /* BCM2  */
#define MIC2_GPIO        3   /* BCM3  */
#define SAMPLE_PERIOD_MS 100
#define ERROR_DB         (-999.0f)

/* IMP23ABSU: 0x7C << 1 = 0x7D8 */
#define IMP23ABSU_ADDR   0x7D8

/* Register map (representative; actual IMP23ABSU uses a different
 * register set.  This placeholder model provides a 16-bit sample
 * register that we read via bit-banged I2C. */
#define REG_SAMPLE_LSB   0x00
#define REG_SAMPLE_MSB   0x01

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Bit-banged I2C helpers                                              */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    /* Write the register pointer. */
    if (i2c_write_byte(fd, reg, 0x00) < 0)
        return -1;

    /* Small delay so the sensor can clock out the data. */
    usleep(10);

    /* Read one byte. */
    ssize_t n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_byte(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* IMP23ABSU placeholder driver                                        */
/* ------------------------------------------------------------------ */

/*
 * Read a 16-bit sample from the IMP23ABSU.
 * Returns 0 on success, -1 on I2C error.
 */
static int imp23absu_read_sample(int fd, int16_t *sample)
{
    uint8_t lsb = 0, msb = 0;

    if (i2c_read_byte(fd, REG_SAMPLE_LSB, &lsb) < 0)
        return -1;
    if (i2c_read_byte(fd, REG_SAMPLE_MSB, &msb) < 0)
        return -1;

    *sample = (int16_t)((msb << 8) | lsb);
    return 0;
}

/*
 * Placeholder conversion: raw ADC count -> dB.
 * Replace with the actual IMP23ABSU transfer-function model.
 */
static float imp23absu_convert(int16_t raw)
{
    return (float)raw * 0.01f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(float db1, float db2, float avg_db)
{
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "fopen(audio_log.txt): %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                db1, db2, avg_db);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f,%.2f\n", db1, db2, avg_db);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the IMP23ABSU slave address. */
    if (ioctl(fd, I2C_SLAVE, IMP23ABSU_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                IMP23ABSU_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("IMP23ABSU dual-channel logger started.  Bus: %s  Addr: 0x%02X\n",
           I2C_BUS, IMP23ABSU_ADDR);
    printf("Sampling every %d ms.  Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_MS);

    while (g_running) {
        int16_t raw1 = 0, raw2 = 0;
        float db1 = ERROR_DB, db2 = ERROR_DB;
        float avg_db = ERROR_DB;

        /* Read microphone 1. */
        if (imp23absu_read_sample(fd, &raw1) == 0) {
            db1 = imp23absu_convert(raw1);
        } else {
            fprintf(stderr, "Mic1 read error: %s\n", strerror(errno));
        }

        /* Read microphone 2. */
        if (imp23absu_read_sample(fd, &raw2) == 0) {
            db2 = imp23absu_convert(raw2);
        } else {
            fprintf(stderr, "Mic2 read error: %s\n", strerror(errno));
        }

        /* Average of the two samples. */
        avg_db = (db1 + db2) / 2.0f;

        log_data(db1, db2, avg_db);

        /* Sleep for the sample period (interruptible by signals). */
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    if (close(fd) < 0) {
        perror("close(i2c)");
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

