#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define LED_PIN             27          /* BCM GPIO27 – LED indicator        */
#define SPI_CHANNEL0        0           /* MCP3008 channel 0 (CE0 / GPIO8)   */
#define SPI_CHANNEL1        1           /* MCP3008 channel 1 (CE1 / GPIO9)   */
#define SPI_SPEED_HZ        1000000     /* 1 MHz – well within MCP3008 spec   */
#define SPI_FLAGS           0           /* Mode 0, active-low CE              */
#define SAMPLE_WINDOW_MS    100         /* Total sampling window             */
#define SAMPLE_PERIOD_US    10000       /* 10 ms between samples             */
#define LED_ON_TIME_MS      500         /* LED on duration after event       */
#define HIGH_LEVEL_THRESHOLD 100        /* 10-bit ADC count threshold        */
#define ADC_MAX             1023        /* 10-bit ADC full-scale code         */
#define CSV_FILENAME        "audio_events.csv"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle0 = -1;
static int  g_spi_handle1 = -1;
static FILE *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_spi(void);
static int  read_adc(int channel);
static double calculate_rms(const int *samples, int n);
static void log_event(double rms1, double rms2);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI init ---------------------------------- */
static int init_spi(void)
{
    g_spi_handle0 = spiOpen(SPI_CHANNEL0, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle0 < 0) {
        fprintf(stderr, "Error: spiOpen(channel=%d) failed: %s\n",
                SPI_CHANNEL0, pigpio_error(g_spi_handle0));
        return -1;
    }

    g_spi_handle1 = spiOpen(SPI_CHANNEL1, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle1 < 0) {
        fprintf(stderr, "Error: spiOpen(channel=%d) failed: %s\n",
                SPI_CHANNEL1, pigpio_error(g_spi_handle1));
        spiClose(g_spi_handle0);
        g_spi_handle0 = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- MCP3008 read ------------------------------ */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit code.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer((channel == 0) ? g_spi_handle0 : g_spi_handle1,
                      tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "Error: spiXfer(channel=%d) failed: %s\n",
                channel, pigpio_error(ret));
        return -1;
    }
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d bytes (expected 3)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- RMS --------------------------------------- */
static double calculate_rms(const int *samples, int n)
{
    double sum_sq = 0.0;
    for (int i = 0; i < n; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / (double)n);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(double rms1, double rms2)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, rms1, rms2) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle0 >= 0) {
        spiClose(g_spi_handle0);
        g_spi_handle0 = -1;
    }
    if (g_spi_handle1 >= 0) {
        spiClose(g_spi_handle1);
        g_spi_handle1 = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Best-effort LED off; ignore errors during shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED pin --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED=%d) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- SPI --- */
    if (init_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(CSV_FILENAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s for append\n", CSV_FILENAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    /* --- Sampling buffer --- */
    int *samples1 = malloc(SAMPLE_WINDOW_MS * 100);
    int *samples2 = malloc(SAMPLE_WINDOW_MS * 100);
    if (samples1 == NULL || samples2 == NULL) {
        fprintf(stderr, "Error: malloc failed for sample buffers\n");
        free(samples1);
        free(samples2);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sampling audio for %d ms (1 ms per sample, %d samples/window)...\n",
           SAMPLE_WINDOW_MS, SAMPLE_WINDOW_MS);
    printf("Press Ctrl+C to stop early.\n");

    /* --- Main loop --- */
    while (g_running) {
        int s1_ok = (read_adc(0) >= 0);
        int s2_ok = (read_adc(1) >= 0);

        if (!s1_ok || !s2_ok) {
            fprintf(stderr, "Error: ADC read failed (ch0=%d, ch1=%d)\n",
                    s1_ok, s2_ok);
            break;
        }

        samples1[0] = s1_ok ? read_adc(0) : 0;
        samples2[0] = s2_ok ? read_adc(1) : 0;

        /* Shift older samples right into the buffer */
        for (int i = 1; i < SAMPLE_WINDOW_MS; i++) {
            samples1[i] = samples1[i - 1];
            samples2[i] = samples2[i - 1];
        }

        double rms1 = calculate_rms(samples1, SAMPLE_WINDOW_MS);
        double rms2 = calculate_rms(samples2, SAMPLE_WINDOW_MS);

        log_event(rms1, rms2);

        if (rms1 > HIGH_LEVEL_THRESHOLD || rms2 > HIGH_LEVEL_THRESHOLD) {
            printf("Event: mic1=%.2f mic2=%.2f (threshold=%d)\n",
                   rms1, rms2, HIGH_LEVEL_THRESHOLD);
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME_MS * 1000);   /* gpioDelay takes microseconds */
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 10 ms between samples */
    }

    /* --- Cleanup --- */
    free(samples1);
    free(samples2);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

