    printf("Sampling audio for %d ms (1 ms per sample, %d samples/window)...\n",
           SAMPLE_WINDOW_MS, SAMPLE_WINDOW_MS);
    printf("Press Ctrl+C to stop early.\n");

    /* --- Main loop --- */
    while (g_running) {
        int s1_ok = (read_adc(0) >= 0);
        int s2_ok = (read_adc(1) >= 0);

        if (!s1_ok || !s2_ok) {
            fprintf(stderr, "Error: ADC read failed (ch0=%d, ch1=%d)\n",
                    s1_ok, s2_ok);
            break;
        }

        samples1[0] = s1_ok ? read_adc(0) : 0;
        samples2[0] = s2_ok ? read_adc(1) : 0;

        /* Shift older samples right into the buffer */
        for (int i = 1; i < SAMPLE_WINDOW_MS; i++) {
            samples1[i] = samples1[i - 1];
            samples2[i] = samples2[i - 1];
        }

        double rms1 = calculate_rms(samples1, SAMPLE_WINDOW_MS);
        double rms2 = calculate_rms(samples2, SAMPLE_WINDOW_MS);

        log_event(rms1, rms2);

        if (rms1 > HIGH_LEVEL_THRESHOLD || rms2 > HIGH_LEVEL_THRESHOLD) {
            printf("Event: mic1=%.2f mic2=%.2f (threshold=%d)\n",
                   rms1, rms2, HIGH_LEVEL_THRESHOLD);
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME_MS * 1000);   /* gpioDelay takes microseconds */
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 10 ms between samples */
    }

    /* --- Cleanup --- */
    free(samples1);
    free(samples2);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

