/*
 * MLX91204 Current Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - Melexis MLX91204 Hall-effect current sensor (analog output)
 *   - ADS1115 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - Warning LED on GPIO17 (BCM)
 *
 * Behavior:
 *   - Samples A0 single-ended at 10 Hz
 *   - Stores current readings in a 100-element circular buffer
 *   - Lights LED when the buffer average exceeds 50.0 A
 *   - Clean shutdown on SIGINT
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* ADS1115 config: A0 single-ended | PGA ±4.096 V | single-shot | 128 SPS */
#define ADS1115_CFG_BASE     0x8000  /* OS bit — start a conversion */
#define ADS1115_CFG_MUX_A0   0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4V   0x0200  /* PGA = ±4.096 V */
#define ADS1115_CFG_MODE_SS  0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128  0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003 /* Disable comparator */

#define LED_PIN              17
#define CURRENT_THRESHOLD    50.0f   /* Amperes */
#define BUFFER_SIZE          100
#define SAMPLE_PERIOD_US     100000  /* 10 Hz */
#define CONV_TIMEOUT_MS      50

/* MLX91204 transfer function: Vout = 0.5 V/A + 0.1 V (offset) */
#define VOLTAGE_OFFSET       0.5f
#define VOLTAGE_SCALE       0.1f

/* ADS1115: 16-bit signed, PGA ±4.096 V → LSB = 4.096 / 32768 = 0.000125 V */
#define ADC_LSB_V            0.000125f

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  ads1115_init(int handle);
static int  ads1115_read_raw(int handle, int16_t *raw_out);
static float raw_to_current(int16_t raw);
static void buffer_add(float current);
static float buffer_average(void);
static void led_set(bool on);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers --------------------------- */
static int ads1115_init(int handle)
{
    uint16_t config = ADS1115_CFG_BASE
                    | ADS1115_CFG_MUX_A0
                    | ADS1115_CFG_PGA_4V
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (char)(config >> 8);
    cfg[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, cfg, 3) != 0) {
        fprintf(stderr, "[ERROR] Failed to write ADS1115 config register\n");
        return -1;
    }
    return 0;
}

/*
 * Trigger a single-shot conversion and read the result.
 * Returns 0 on success, -1 on I2C error, -2 on conversion timeout.
 */
static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    char reg = ADS1115_REG_CONFIG;
    char buf[2];

    /* Trigger a new conversion */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to select ADS1115 config register\n");
        return -1;
    }
    if (i2cWriteDevice(handle, (char *)&ADS1115_CFG_BASE, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to write conversion trigger\n");
        return -1;
    }

    /* Poll the OS bit (bit 15) until conversion completes or timeout */
    for (int i = 0; i < CONV_TIMEOUT_MS; i++) {
        if (i2cWriteDevice(handle, &reg, 1) != 0) {
            fprintf(stderr, "[ERROR] Failed to select config register\n");
            return -1;
        }
        char cfg[2];
        if (i2cReadDevice(handle, cfg, 2) != 2) {
            fprintf(stderr, "[ERROR] Failed to read ADS1115 config\n");
            return -1;
        }
        uint16_t cfg_val = ((uint16_t)(uint8_t)cfg[0] << 8) | (uint8_t)cfg[1];
        if (cfg_val & 0x8000) {
            break; /* Conversion complete */
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (!(g_i2c_handle & 0x8000)) {
        fprintf(stderr, "[ERROR] ADS1115 conversion timeout\n");
        return -2;
    }

    /* Read conversion result (2 bytes, big-endian) */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to select conversion register\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] Failed to read ADS1115 conversion\n");
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static float raw_to_current(int16_t raw)
{
    float voltage = (float)raw * ADC_LSB_V;
    return (voltage - VOLTAGE_OFFSET) / VOLTAGE_SCALE;
}

/* ----------------------------- Circular buffer --------------------------- */
static void buffer_add(float current)
{
    static float buf[BUFFER_SIZE];
    static int   idx = 0;
    buf[idx] = current;
    idx = (idx + 1) % BUFFER_SIZE;
}

static float buffer_average(void)
{
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buf[i];
    }
    return sum / (float)BUFFER_SIZE;
}

/* ----------------------------- LED control ------------------------------- */
static void led_set(bool on)
{
    gpioWrite(LED_PIN, on ? 1 : 0);
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_set(false);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d). "
                        "Check wiring and that the ADS1115 is present.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADS1115 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91204 current monitor running. Sampling at 10 Hz.\n");
    printf("Threshold: %.1f A | Buffer: %d samples | LED on GPIO%d\n",
           CURRENT_THRESHOLD, BUFFER_SIZE, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        int rc = ads1115_read_raw(g_i2c_handle, &raw);

        if (rc == 0) {
            float current = raw_to_current(raw);
            buffer_add(current);
            float avg = buffer_average();

            printf("Raw: %6d | Current: %7.3f A | Avg: %7.3f A",
                   raw, current, avg);

            if (avg > CURRENT_THRESHOLD) {
                printf("  *** WARNING ***");
                led_set(true);
            } else {
                led_set(false);
            }
            printf("\n");
        } else if (rc == -2) {
            /* Conversion timeout — sensor may be absent or bus stuck */
            fprintf(stderr, "[WARN] ADS1115 conversion timeout — "
                            "check wiring and sensor presence\n");
        } else {
            /* I2C read error */
            fprintf(stderr, "[WARN] I2C read error — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ----------------------------- Cleanup ------------------------------- */
    printf("\nShutting down...\n");
    led_set(false);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

