static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        tcs34725_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int file_exists(const char *path)
{
    FILE *f = fopen(path, "r");
    if (f) { fclose(f); return 1; }
    return 0;
}

static int write_header_if_new(void)
{
    if (file_exists(LOG_FILE))
        return 0;
    g_log_file = fopen(LOG_FILE, "w");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot create %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
    fflush(g_log_file);
    return 0;
}

static void log_data(uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%u,%u,%u,%u\n", ts, c, r, g, b);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = tcs34725_open(I2C_BUS, I2C_ADDR);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: tcs34725_open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: tcs34725_init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_header_if_new() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TCS34725 logging started. Press Ctrl+C to stop.\n");

    int consec_err = 0;

    while (g_running) {
        uint16_t c, r, g, b;

        int rc = tcs34725_read_raw_data(g_i2c_handle, &c, &r, &g, &b);
        if (rc != 0) {
            fprintf(stderr, "Warning: tcs34725_read_raw_data failed (rc=%d)\n", rc);
            consec_err++;
            if (consec_err >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Error: %d consecutive I2C failures, aborting.\n", MAX_CONSEC_ERR);
                break;
            }
        } else {
            consec_err = 0;
            log_data(c, r, g, b);
        }

        /* Sleep 1 s in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

