        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Cannot set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Cannot set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Cannot set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Moisture1,Moisture2\n");
        fflush(log_fp);
    }

    printf("Starting moisture monitoring. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture1 = read_mcp3008(spi_fd, MOISTURE_CHANNEL_1);
        int moisture2 = read_mcp3008(spi_fd, MOISTURE_CHANNEL_2);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Error reading moisture sensor data. Skipping log entry.\n");
        } else {
            log_data(log_fp, moisture1, moisture2);
            printf("Moisture1: %d, Moisture2: %d\n", moisture1, moisture2);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

