#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define ADC_CHANNEL      0
#define ADC_MAX_VALUE    1023.0
#define ADC_VREF         3.3

#define MOTOR_GPIO       17
#define OVERCURRENT_THRESHOLD 10.0
#define SAMPLE_INTERVAL  1
#define MAX_SPI_RETRIES  3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (spi_fd < 0) return -1;

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float adc_to_amperes(int adc_value) {
    return ((float)adc_value / ADC_MAX_VALUE) * ADC_VREF;
}

static int log_data(float current) {
    if (!log_file) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, current) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int log_overcurrent(float current) {
    if (!log_file) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,OVERCURRENT,%.2f\n", timestamp, current) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_GPIO);
    if (!motor_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(motor_line, "motor_shutdown", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip); chip = NULL; motor_line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        close(spi_fd); spi_fd = -1;
        return EXIT_FAILURE;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("fopen(current_log.csv)");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
        fflush(log_file);
    }

    printf("Monitoring current. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_SPI_RETRIES);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float current = adc_to_amperes(adc_value);

        if (log_data(current) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT DETECTED: %.2f A\n", current);
            if (gpiod_line_set_value(motor_line, 0) < 0) {
                perror("gpiod_line_set_value(0)");
            }
            if (log_overcurrent(current) < 0) {
                fprintf(stderr, "Failed to log overcurrent event\n");
            }
            sleep(1);
            if (gpiod_line_set_value(motor_line, 1) < 0) {
                perror("gpiod_line_set_value(1)");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

