#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x76
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_READ_ERRORS 10

/* MLX90817 16-bit pressure register (example – adjust if datasheet varies) */
#define PRESSURE_REG   0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_kPa)
{
    int raw = i2cReadWordData(g_i2c_handle, PRESSURE_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading pressure register 0x%02X: pigpio error %d\n",
                PRESSURE_REG, raw);
        return -1;
    }
    /* Convert raw 16-bit big-endian word to kPa (example scaling) */
    uint16_t word = (uint16_t)((raw >> 8) | (raw << 8));
    *pressure_kPa = (float)word * 0.1f;
    return 0;
}

static int log_pressure(float pressure_kPa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error writing header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_file) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    int consecutive_errors = 0;

    while (g_running) {
        float pressure_kPa;
        if (read_pressure(&pressure_kPa) == 0) {
            consecutive_errors = 0;
            if (log_pressure(pressure_kPa) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C read failures (%d). "
                                "Sensor may be absent or bus error. Exiting.\n",
                        consecutive_errors);
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

