code:
/*
 * MLX90834 pressure & NTC temperature monitor (ADS1115 I2C bridge)
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 * ADC:    ADS1115 at 0x48, AIN0 = pressure, AIN1 = NTC temp
 * LED:    GPIO17 (active-high warning when pressure > 105 kPa)
 *
 * Build:  gcc -O2 -Wall -o mlx90834 mlx90834.c -lpigpio -lrt
 * Run:    sudo ./mlx90834
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config word: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_PRES     0xC183  /* MUX=AIN0, PGA=4.096V, MODE=1, DR=128 */
#define ADS1115_CFG_TEMP     0xD183  /* MUX=AIN1, PGA=4.096V, MODE=1, DR=128 */

#define LED_GPIO             17
#define PRESSURE_THRESHOLD   105.0f   /* kPa */
#define SAMPLE_PERIOD_US     1000000  /* 1 s */
#define MAX_RETRIES          3
#define ADC_MAX_COUNT        32767.0f /* 16-bit signed, single-ended positive */
#define ADC_VREF             4.096f   /* ADS1115 PGA full-scale */
#define ADC_LSB_V           (ADC_VREF / ADC_MAX_COUNT)

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  ads1115_write_config(int handle, uint16_t cfg);
static int  ads1115_read_conversion(int handle, int16_t *raw);
static int  read_pressure(int handle, float *pressure_kPa);
static int  read_temperature(int handle, float *temp_c);
static void control_led(int gpio, float pressure_kPa);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers ---------------------------- */
static int ads1115_write_config(int handle, uint16_t cfg)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(cfg >> 8);
    buf[2] = (char)(cfg & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (config 0x%04X): %s\n",
                cfg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int handle, int16_t *raw)
{
    char reg = ADS1115_REG_CONV;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select): %s\n",
                strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice (conversion): %s\n",
                strerror(errno));
        return -1;
    }
    *raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                     (uint16_t)(uint8_t)buf[1]);
    return 0;
}

/* ----------------------------- Sensor reads ------------------------------- */
static int read_pressure(int handle, float *pressure_kPa)
{
    int16_t raw;
    int ok;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ok = ads1115_write_config(handle, ADS1115_CFG_PRES);
        if (ok < 0) {
            gpioDelay(10000);
            continue;
        }

        /* Wait for conversion (~8 ms at 128 SPS) */
        gpioDelay(10000);

        ok = ads1115_read_conversion(handle, &raw);
        if (ok < 0) {
            gpioDelay(10000);
            continue;
        }

        *pressure_kPa = ((float)raw / ADC_MAX_COUNT) * ADC_VREF * 1000.0f;
        return 0;
    }
    return -1;
}

static int read_temperature(int handle, float *temp_c)
{
    int16_t raw;
    int ok;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ok = ads1115_write_config(handle, ADS1115_CFG_TEMP);
        if (ok < 0) {
            gpioDelay(10000);
            continue;
        }

        /* Wait for conversion (~8 ms at 128 SPS) */
        gpioDelay(10000);

        ok = ads1115_read_conversion(handle, &raw);
        if (ok < 0) {
            gpioDelay(10000);
            continue;
        }

        /* NTC resistance (R) in kΩ = Vref / (raw / 32767) */
        float r_ntc = (ADC_VREF / ADC_MAX_COUNT) / ((float)raw / ADC_MAX_COUNT);
        /* Approximate MLX90834 NTC curve: T(°C) ≈ 1/0.00385 * R */
        *temp_c = 1.0f / 0.00385f * r_ntc;
        return 0;
    }
    return -1;
}

/* ----------------------------- LED control -------------------------------- */
static void control_led(int gpio, float pressure_kPa)
{
    int level = (pressure_kPa > PRESSURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d) failed: %s\n",
                gpio, strerror(errno));
    }
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT): %s\n",
                LED_GPIO, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT): %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM): %s\n", strerror(errno));
    }

    printf("MLX90834 monitoring started.  Pressure threshold: %.1f kPa\n",
           PRESSURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        float pressure_kPa = 0.0f;
        float temp_c       = 0.0f;

        if (read_pressure(g_i2c_handle, &pressure_kPa) < 0) {
            fprintf(stderr, "[ERROR] Pressure read failed after %d retries\n",
                    MAX_RETRIES);
        } else if (read_temperature(g_i2c_handle, &temp_c) < 0) {
