#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM 8)  */
#define SPI_SPEED        1000000    /* 1 MHz               */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 CH0 single-ended */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC            */
#define CURRENT_THRESHOLD 10.0      /* Amperes              */
#define OVERCURRENT_GPIO 27         /* BCM 27, active-high  */
#define SAMPLE_PERIOD_US 100000     /* 100 ms               */
#define LOG_FILE         "current_log.txt"

/* ----------------------------- Globals ---------------------------------- */
static int      spi_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize(void);
static void cleanup(void);
static int  read_adc(int channel);
static void log_current(int current);
static void check_overcurrent(int current);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

/* Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI error, -2 on invalid channel. */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -2;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: 0x01  (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * Byte 2: 0x00  (don't care, clocks out low 2 bits) */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return value;
}

/* Append a timestamped current reading to the log file. */
static void log_current(int current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s, Current: %d mA\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* Check current and drive OVERCURRENT_GPIO HIGH on threshold breach. */
static void check_overcurrent(int current)
{
    if (current > (int)(CURRENT_THRESHOLD * 1000.0)) {
        fprintf(stderr, "OVERCURRENT: %d mA exceeds %d mA threshold!\n",
                current, (int)(CURRENT_THRESHOLD * 1000.0));

        if (gpioWrite(OVERCURRENT_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", OVERCURRENT_GPIO);
        }

        if (log_file) {
            fprintf(log_file, "OVERCURRENT: %d mA exceeds %d mA threshold!\n",
                    current, (int)(CURRENT_THRESHOLD * 1000.0));
            fflush(log_file);
        }

        terminate = 1;
    } else {
        if (gpioWrite(OVERCURRENT_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to reset GPIO %d LOW\n", OVERCURRENT_GPIO);
        }
    }
}

/* Signal handler — set flag only; I/O cleanup happens in main(). */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Initialize pigpio, SPI, GPIO, and log file. */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* pigpio drives CE0 automatically when SPI channel 0 is opened. */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(OVERCURRENT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", OVERCURRENT_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(OVERCURRENT_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", OVERCURRENT_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Release all resources. */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure motor is off before terminating pigpio. */
    gpioWrite(OVERCURRENT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring current on MCP3008 CH0. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int current_ma = read_adc(ADC_CHANNEL);

        if (current_ma < 0) {
            if (current_ma == -1) {
                fprintf(stderr, "SPI read error — continuing\n");
            } else {
                fprintf(stderr, "Invalid ADC channel — continuing\n");
            }
        } else {
            int current_amps = current_ma / 1000;
            log_current(current_ma);
            check_overcurrent(current_ma);
            printf("Current: %d mA (%d A)\n", current_ma, current_amps);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

