/*
 * methane_monitor.c — Raspberry Pi 4 Model B
 *
 * Monitors a Honeywell MICROpeL 41000-020 Combustible Gas Sensor
 * (analog output) via an MCP3008 ADC on SPI bus 0, channel 0.
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 3.3 V  (pin 1)
 *   MCP3008 VREF -> Pi 3.3 V  (pin 1)
 *   MCP3008 AGND -> Pi GND   (pin 6)
 *   MCP3008 DGND -> Pi GND   (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> sensor analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o methane_monitor methane_monitor.c
 *
 * Run:
 *   ./methane_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 on SPI bus 0 (CE0)            */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 spec      */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8 bits/word   */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0       */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC full-scale code           */
#define THRESHOLD_PPM  1000       /* Leak alarm threshold (ppm)           */
#define SAMPLE_PERIOD  1          /* Seconds between samples              */
#define LOG_FILE       "methane_log.txt"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize(void);
static void cleanup(void);
static int  read_mcp3008(int channel, int *out_value);
static int  log_data(int methane_ppm);
static void signal_handler(int sig);

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    while (g_running) {
        int methane_ppm = -1;

        if (read_mcp3008(ADC_CHANNEL, &methane_ppm) != 0) {
            fprintf(stderr, "SPI read error — continuing.\n");
        } else {
            if (log_data(methane_ppm) != 0) {
                fprintf(stderr, "Log write error — continuing.\n");
            }
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    /* --- pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* --- Log file (append) --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- MCP3008 read ------------------------------- */
/*
 * Read a single-ended channel from the MCP3008.
 *
 * MCP3008 SPI protocol (3-byte transfer, mode 0, MSB-first):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response:
 *   rx[0] — ignored
 *   rx[1] — bits 9..2 of result in lower nibble
 *   rx[2] — bits 1..0 of result
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01;
    tx[1] = (char)((0x08 | channel) << 4);
    tx[2] = 0x00;

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "spiXfer returned %d (expected 3): %s\n",
                bytes, strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *out_value = raw;
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static int log_data(int methane_ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Methane: %d ppm\n", ts, methane_ppm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

