#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN_SINGLE_0 (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128_SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

#define ADC_MAX_VALUE 32767.0
#define VREF 4.096
#define P_MIN 0.0
#define P_MAX 100.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc_raw(int handle, int16_t *raw) {
    char config[3];
    char reg[1] = {ADS1115_REG_CONFIG};
    char conv[2];
    int16_t val;

    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_CONFIG_OS_BEGIN_SINGLE_0 | ADS1115_CONFIG_MUX_AIN0_GND |
                ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_CQUE_NONE;
    config[2] = 0x00;

    if (i2cWriteDevice(handle, config, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cWriteDevice(handle, reg, 1) < 0) {
            fprintf(stderr, "Error selecting ADS1115 conversion reg: %s\n", strerror(errno));
            return -1;
        }
        if (i2cReadDevice(handle, conv, 2) == 2) {
            val = (int16_t)((conv[0] << 8) | conv[1]);
            if (val >= 0 && val <= 32767) {
                *raw = val;
                return 0;
            }
            fprintf(stderr, "Invalid ADC value: %d\n", val);
            return -1;
        }
        fprintf(stderr, "Error reading ADS1115 conversion (attempt %d): %s\n", i + 1, strerror(errno));
        gpioDelay(10000);
    }
    fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
    return -1;
}

static float adc_to_pressure(int16_t raw) {
    float voltage = (float)raw / ADC_MAX_VALUE * VREF;
    return (voltage / VREF) * (P_MAX - P_MIN) + P_MIN;
}

static int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
