#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SERVER "smtp.example.com"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | (rx[2] & 0xFF);
}

static float read_humidity(void) {
    int raw = read_adc(ADC_CHANNEL);
    if (raw < 0) return -1.0;

    float humidity = (raw / 4095.0) * 100.0;
    if (humidity > 100.0) humidity = 100.0;
    if (humidity < 0.0) humidity = 0.0;
    return humidity;
}

static float read_temperature(void) {
    int raw = read_adc(ADC_CHANNEL);
    if (raw < 0) return -1.0;

    float temperature = ((raw / 4095.0) * 3.3 - 0.5) * 100.0;
    return temperature;
}

static void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

static void send_email_alert(float humidity, float temperature) {
    FILE *fp = popen("ssmtp " EMAIL_RECIPIENT, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open pipe to ssmtp\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "To: %s\n", EMAIL_RECIPIENT);
    fprintf(fp, "From: %s\n", EMAIL_SENDER);
    fprintf(fp, "Subject: Humidity Alert\n\n");
    fprintf(fp, "Alert: Humidity %.2f%% exceeds threshold %.2f%%\n", humidity, HUMIDITY_THRESHOLD);
    fprintf(fp, "Timestamp: %s\n", timestamp);
    fprintf(fp, "Temperature: %.2f C\n", temperature);

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: ssmtp command failed with status %d\n", status);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not set signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity = read_humidity();
        float temperature = read_temperature();

        if (humidity < 0.0 || temperature < -40.0) {
            fprintf(stderr, "Error: Sensor read failed, skipping logging and alert\n");
        } else {
            log_data(humidity, temperature);
            printf("Humidity: %.2f%%, Temperature: %.2f C\n", humidity, temperature);

            if (humidity > HUMIDITY_THRESHOLD) {
                send_email_alert(humidity, temperature);
            }
        }

        sleep(5);
    }

    printf("\nCleaning up...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

