/*
 * TMP36 temperature logger via MCP3208 ADC on Raspberry Pi 5.
 *
 * Wiring:
 *   MCP3208 VDD  -> 3.3 V (pin 1)
 *   MCP3208 VREF -> 3.3 V (pin 1)
 *   MCP3208 CLK  -> GPIO11 (BCM 23, SPI0 SCLK)
 *   MCP3208 DOUT -> GPIO9  (BCM 21, SPI0 MISO)
 *   MCP3208 DIN  -> GPIO10 (BCM 19, SPI0 MOSI)
 *   MCP3208 CS   -> GPIO8  (BCM 24, SPI0 CE0)
 *   MCP3208 DGND -> GND
 *   MCP3208 AGND -> GND
 *   TMP36 VCC   -> 3.3 V
 *   TMP36 GND   -> GND
 *   TMP36 OUT   -> MCP3208 CH0
 *
 * Build: gcc -O2 -Wall -o tmp36_logger tmp36_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define GPIO_CHIP_NAME    "gpiochip4"
#define GPIO_CS_LINE      24   /* BCM 24 = SPI0 CE0 */
#define LOG_FILE          "temperature_log.csv"
#define SAMPLE_PERIOD_US  1000000  /* 1 Hz */
#define ADC_CHANNEL       0
#define ADC_MAX_VALUE     4095.0   /* MCP3208 is 12-bit */
#define VREF              3.3
#define TMP36_OFFSET      0.5
#define TMP36_SCALE       100.0
#define TEMP_MIN_C        -40.0
#define TEMP_MAX_C        125.0

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, GPIO_CS_LINE);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                GPIO_CS_LINE, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "tmp36_logger", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        g_cs_line = NULL;
        return -1;
    }

    return 0;
}

/*
 * MCP3208 single-ended read (3-byte transfer):
 *   tx[0] = 0x00 (start bit)
 *   tx[1] = 0x80 | (channel << 4)  (single-ended + channel)
 *   tx[2] = 0x00 (clock out remaining bits)
 * Result: 12-bit value in rx[1] (lower 4 bits) and rx[2] (8 bits).
 */
static int mcp3208_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x00, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0): %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1): %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x0F) << 8) | rx[2];
    return value;
}

static float adc_to_temperature(int adc_value)
{
    float voltage = (adc_value / ADC_MAX_VALUE) * VREF;
    float temp_c  = (voltage - TMP36_OFFSET) * TMP36_SCALE;
    return temp_c;
}

static int log_temperature(float temp_c)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, temp_c) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_fp);
        if (sz == 0) {
            if (fprintf(g_log_fp, "timestamp,temperature_celsius\n") < 0 ||
                fflush(g_log_fp) != 0) {
                fprintf(stderr, "Failed to write CSV header\n");
                cleanup();
                return 1;
            }
        }
    } else {
        fprintf(stderr, "fseek: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("TMP36 logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int adc = mcp3208_read(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying next cycle.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float temp = adc_to_temperature(adc);

        if (temp < TEMP_MIN_C || temp > TEMP_MAX_C) {
            fprintf(stderr,
                    "Warning: temperature %.2f C out of range [%.0f, %.0f].\n",
                    temp, TEMP_MIN_C, TEMP_MAX_C);
        }

        if (log_temperature(temp) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return 0;
}

