/*
 * Raspberry Pi Zero W – Si1172-A30-GMR Optical Heart Rate Sensor Logger
 *
 * Reads raw IR and RED PPG ADC samples from a Si1172 on I2C bus 1,
 * logs them to biometric_log.csv with a Unix-timestamp header,
 * and writes error flags when a read fails.
 *
 * NOTE: The Si1172 is a proprietary optical sensor that requires
 * Silicon Labs' proprietary algorithm to convert raw ADC samples
 * into true Heart Rate (HR) and SpO₂ values. This program logs
 * the raw 16-bit IR and RED ADC values as proxy values for HR
 * and SpO₂, respectively, because the Si1172 driver library is
 * not available as open-source. A production system MUST use
 * the official Silicon Labs Si1172 driver.
 *
 * Build:  gcc -O2 -Wall -o si1172_logger si1172_logger.c -li2c
 * Run:    ./si1172_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x60          /* Si1172 default 7-bit I2C address */
#define LOG_FILE             "biometric_log.csv"
#define SAMPLE_INTERVAL_US   1000000       /* 1 second in microseconds */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       100000        /* 100 ms between retries */

/* Si1172 register addresses (16-bit, big-endian on the bus) */
#define REG_HW_KEY           0x00
#define REG_HW_KEY_VAL       0x17          /* recommended HW_KEY value */
#define REG_IRQ_ENABLE       0x08
#define REG_IRQ_STATUS       0x09
#define REG_IRQ_MODE1        0x0A
#define REG_IRQ_MODE2        0x0B
#define REG_HW_KEY2          0x0C
#define REG_HW_KEY2_VAL      0x00
#define REG_MEAS_RATE        0x0D
#define REG_MEAS_RATE_VAL    0x08          /* 8 ms measurement rate */
#define REG_ALS_RATE         0x0E
#define REG_ALS_RATE_VAL     0x08
#define REG_ALS_IR_DATA0     0x10
#define REG_ALS_IR_DATA1     0x11
#define REG_ALS_RED_DATA0    0x12
#define REG_ALS_RED_DATA1    0x13

/* ----------------------------- Globals ----------------------------------- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_sensor_data(uint16_t *ir, uint16_t *red);
static int  log_data(time_t ts, uint16_t ir, uint16_t red, int err);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C Init ---------------------------------- */
static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- Sensor Init ------------------------------- */
static int init_sensor(void)
{
    /*
     * Probe: read a register to confirm the sensor is present and
     * responding.  A missing or unresponsive device is treated as
     * a hard error (error flag 2) so the program can be restarted
     * with a different address or wiring.
     */
    int probe = i2cReadByteData(i2c_handle, REG_IRQ_STATUS);
    if (probe < 0) {
        fprintf(stderr, "Error: sensor not responding at 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        return -2;                 /* error flag 2 – sensor absent */
    }

    /* Write HW_KEY to enable the device */
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, REG_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: failed to write HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    /* Configure IRQ: enable ALS events, disable interrupts */
    if (i2cWriteByteData(i2c_handle, REG_IRQ_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write IRQ_ENABLE: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_IRQ_MODE1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write IRQ_MODE1: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_IRQ_MODE2, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write IRQ_MODE2: %s\n", strerror(errno));
        return -1;
    }

    /* Set measurement rate to 8 ms */
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE, REG_MEAS_RATE_VAL) < 0) {
        fprintf(stderr, "Error: failed to write MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }

    /* Start autonomous measurements */
    if (i2cWriteByteData(i2c_handle, REG_ALS_RATE, REG_ALS_RATE_VAL) < 0) {
        fprintf(stderr, "Error: failed to write ALS_RATE: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- Read Sensor ------------------------------- */
static int read_sensor_data(uint16_t *ir, uint16_t *red)
{
    int ir_lo, ir_hi, red_lo, red_hi;

    ir_lo = i2cReadByteData(i2c_handle, REG_ALS_IR_DATA0);
    if (ir_lo < 0) return -1;
    ir_hi = i2cReadByteData(i2c_handle, REG_ALS_IR_DATA1);
    if (ir_hi < 0) return -1;
    *ir = (uint16_t)((ir_hi << 8) | ir_lo);

    red_lo = i2cReadByteData(i2c_handle, REG_ALS_RED_DATA0);
    if (red_lo < 0) return -1;
    red_hi = i2cReadByteData(i2c_handle, REG_ALS_RED_DATA1);
    if (red_hi < 0) return -1;
    *red = (uint16_t)((red_hi << 8) | red_lo);

    return 0;
}

/* ----------------------------- Log Data ---------------------------------- */
static int log_data(time_t ts, uint16_t ir, uint16_t red, int err)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }

    const char *err_str;
    switch (err) {
        case 0: err_str = "OK"; break;
        case -1: err_str = "I2C read error"; break;
        case -2: err_str = "sensor absent/uninitialized"; break;
        default: err_str = "unknown error"; break;
    }

    fprintf(log_file, "%ld,%u,%u,%s\n",
            (long)ts, ir, red, err_str);
    fflush(log_file);
    return 0;
}

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    uint16_t ir, red;
    int      err;
    int      init_ok = 0;
    int      consecutive_errors = 0;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    err = init_sensor();
    if (err == -2) {
        fprintf(stderr, "Error: sensor not detected at 0x%02X. "
                        "Check wiring and I2C address.\n", I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    if (err != 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    init_ok = 1;

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(log_file);
    }

    printf("Si1172 logger started. Logging to %s. Press Ctrl-C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        time_t now = time(NULL);

        err = read_sensor_data(&ir, &red);
        if (err == 0) {
            consecutive_errors = 0;
            if (log_data(now, ir, red, 0) != 0) {
                fprintf(stderr, "Warning: failed to write log row.\n");
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Error: %d consecutive I2C read failures. "
                                "Sensor may be disconnected.\n", consecutive_errors);
                if (init_ok) {
                    fprintf(stderr, "Re-initializing sensor...\n");
                    if (init_sensor() != 0) {
                        fprintf(stderr, "Re-initialization failed.\n");
                    } else {
                        init_ok = 1;
                        consecutive_errors = 0;
                    }
                }
            }
            if (init_ok) {
                log_data(now, 0, 0, err);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

