/*
 * Raspberry Pi 4 Model B – Honeywell SpiroQuant A+ ES1-005 mass-flow sensor
 * via MCP3008 ADC on SPI0 (CE0 / GPIO8), channel 0.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lm -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 / GPIO8  */
#define SPI_SPEED        1000000    /* 1 MHz        */
#define SPI_FLAGS        0          /* mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 CH0  */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC   */
#define ADC_VREF         3.3        /* MCP3008 VDD  */
#define ADC_RESOLUTION   1024.0     /* 3.3 V / 1024 counts */
#define FLOW_MIN         0.0        /* L/min        */
#define FLOW_MAX         5.0        /* L/min        */
#define LOG_FILE         "flow_log.csv"
#define SAMPLE_PERIOD_US 1000000    /* 1 s           */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE  *g_log_fp = NULL;
static int    g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  read_mcp3008(int handle, int channel, int *out_value);
static double adc_to_flow_rate(int adc_value);
static int  log_flow_rate(FILE *fp, double flow_rate);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int handle, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);

    /* 0 or full-scale typically indicates sensor-absent / wiring fault */
    if (value == 0 || value == ADC_MAX_VALUE) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) – sensor absent or wiring fault\n", value);
        return -1;
    }

    *out_value = value;
    return 0;
}

/* ----------------------------- Flow conversion --------------------------- */
static double adc_to_flow_rate(int adc_value)
{
    double voltage = (adc_value / ADC_MAX_VALUE) * ADC_VREF;
    double flow_rate = (voltage / 3.3) * 5.0;   /* placeholder linear map */
    return flow_rate;
}

/* ----------------------------- CSV logging ------------------------------- */
static int log_flow_rate(FILE *fp, double flow_rate)
{
    if (fp == NULL) {
        fprintf(stderr, "Log file handle is NULL\n");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%06ld,%.4f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(fp);
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow logger started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double flow_rate = adc_to_flow_rate(adc_value);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Flow rate %.4f L/min out of range [%.1f, %.1f]\n",
                    flow_rate, FLOW_MIN, FLOW_MAX);
        } else {
            if (log_flow_rate(g_log_fp, flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

