#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x27
#define LOG_FILE       "environmental_data.csv"
#define SAMPLE_PERIOD  5
#define CONV_DELAY_MS  10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_icp10125(int fd, float *temp, float *press) {
    uint8_t cmd[2] = { 0x36, 0x00 };
    if (i2c_write_cmd(fd, 0x36) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;

    msleep(CONV_DELAY_MS / 1000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    uint32_t raw_p = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    uint32_t raw_t = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

    float t = (float)raw_t / 65536.0f;
    float p = (float)raw_p / 65536.0f;

    *temp = t * 0.5f - 40.0f;
    *press = p * 0.5f - 45000.0f;
    return 0;
}

static void log_data(FILE *f, float t, float p) {
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(f, "%s,%.2f,%.2f\n", ts, t, p);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float t, p;
        if (read_icp10125(g_i2c_fd, &t, &p) == 0) {
            log_data(g_log, t, p);
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", t, p);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    if (g_log) fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

