#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

#define SAMPLE_RATE 16000
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void noise_cancellation(int mic1_sample, int mic2_sample, int mic1_gain, int mic2_gain, int *canceled_sample) {
    *canceled_sample = mic1_sample * mic1_gain - mic2_sample * mic2_gain;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <mic1_gain> <mic2_gain>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int mic1_gain = atoi(argv[1]);
    int mic2_gain = atoi(argv[2]);

    if (mic1_gain <= 0 || mic2_gain <= 0) {
        fprintf(stderr, "Error: Gain values must be positive integers.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

