    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Sampling audio... Press Ctrl+C to exit.\n");

    while (running) {
        int mic1_sample = read_mcp3008(spi_handle, MIC1_CHANNEL);
        int mic2_sample = read_mcp3008(spi_handle, MIC2_CHANNEL);

