        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *adc_out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static double voltage_to_temperature(int adc) {
    if (adc < 0 || adc > ADC_MAX) return TEMP_ERROR;
    double v = (adc / (double)ADC_MAX) * VREF;
    double t = TEMP_OFFSET + (v - 0.5) * 15.0;
    return t;
}

static void log_data(int adc, double voltage, double compensated, double temp, int flame) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s,%d,%.3f,%.3f,%.2f,%d\n", ts, adc, voltage, compensated, temp, flame);
    fflush(log_fp);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open " SPI_DEVICE);
        return 1;
    }
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return 1;
    }
    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }
    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return 1;
    }

    double ambient = TEMP_OFFSET;
    if (read_ambient_temp(&ambient) < 0) {
        fprintf(stderr, "Using default ambient temperature %.1f C\n", ambient);
    }

    while (running) {
        int adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_mcp3008(FLAME_CHANNEL, &adc) == 0) break;
            usleep(10000);
        }
        if (adc < 0) {
            fprintf(stderr, "Error: ADC read failed after %d attempts\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (adc > ADC_MAX) {
            fprintf(stderr, "Error: ADC value %d out of range\n", adc);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        double voltage = (adc / (double)ADC_MAX) * VREF;
        double temp = ambient;
        double comp = voltage_to_temperature(adc);
        int flame = (comp > 1.0) ? 1 : 0;
        gpiod_line_set_value(buzzer_line, flame ? 1 : 0);
        log_data(adc, voltage, comp, temp, flame);
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

