#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define LED_PIN        17
#define HIGH_THRESHOLD 75.0
#define LOW_THRESHOLD  70.0
#define SAMPLE_PERIOD  5.0
#define JSON_FILE      "water_levels.json"
#define LOG_FILE       "water_level_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_json_fp   = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (don't care)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "spiXfer failed: %d\n", ret);
        return -1;
    }
    if (ret != 3) {
        fprintf(stderr, "spiXfer short transfer: %d bytes\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static double calculate_water_level_percentage(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (double)adc_value / 1023.0 * 100.0;
}

static void log_water_level(double percentage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_json_fp, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n",
            timestamp, percentage);
    fflush(g_json_fp);
}

static void log_error(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t rawtime;
        struct tm timeinfo;
        char ts[32];
        time(&rawtime);
        localtime_r(&rawtime, &timeinfo);
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        fprintf(fp, "%s, ERROR: %s\n", ts, message);
        fclose(fp);
    }
    fprintf(stderr, "ERROR: %s\n", message);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (g_json_fp) {
        fprintf(g_json_fp, "]\n");
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    g_json_fp = fopen(JSON_FILE, "w");
    if (!g_json_fp) {
        perror("fopen(" JSON_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_json_fp, "[\n");
    fflush(g_json_fp);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    int led_state = 0;
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            log_error("SPI read error");
            time_sleep(0.1);
            continue;
        }

        double percentage = calculate_water_level_percentage(adc_value);

        log_water_level(percentage);

        if (percentage > HIGH_THRESHOLD && !led_state) {
            gpioWrite(LED_PIN, 1);
            led_state = 1;
            printf("Water level high (%.2f%%), LED ON\n", percentage);
        } else if (percentage < LOW_THRESHOLD && led_state) {
            gpioWrite(LED_PIN, 0);
            led_state = 0;
            printf("Water level low (%.2f%%), LED OFF\n", percentage);
        }

        printf("Water level: %.2f%%\n", percentage);

        /* Sleep SAMPLE_PERIOD seconds, checking g_running every 100 ms */
        double remaining = SAMPLE_PERIOD;
        while (remaining > 0.0 && g_running) {
            time_sleep(0.1);
            remaining -= 0.1;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

