/*
 * Raspberry Pi Zero W - Honeywell AWM7300V Mass Airflow Sensor Logger
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0
 *     CE0  -> physical pin 24 (GPIO 8)
 *     SCLK -> physical pin 23 (GPIO 11)
 *     MOSI -> physical pin 19 (GPIO 10)
 *     MISO -> physical pin 21 (GPIO 9)
 *     VDD  -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
 *   - AWM7300V analog output -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c -lpigpio -lrt
 *   (pigpio must be installed and the user must be in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 (GPIO 8)  */
#define SPI_SPEED        1000000    /* 1 MHz          */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 CH0    */
#define SAMPLE_PERIOD_US 100000     /* 100 ms         */
#define LOG_FILE         "airflow_log.csv"

/* AWM7300V transfer function: 0 V -> 0 LPM, 5 V -> 100 LPM */
#define V_SUPPLY         5.0
#define V_MIN            0.0
#define FLOW_MIN         0.0
#define FLOW_MAX         100.0

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int    g_spi_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 Read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* --------------------------- Flow Conversion ----------------------------- */
static double convert_to_lpm(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    double voltage = ((double)adc_value / 1023.0) * V_SUPPLY;
    double flow   = FLOW_MIN + ((voltage - V_MIN) / (V_SUPPLY - V_MIN)) * (FLOW_MAX - FLOW_MIN);

    return flow;
}

/* --------------------------- Timestamp Helper ---------------------------- */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tmv);
}

/* --------------------------- CSV Logging --------------------------------- */
static int log_data(FILE *fp, const char *timestamp, double flow_rate)
{
    if (fprintf(fp, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }
    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append; create header if new) --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen failed");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) != 0) {
        perror("fseek failed");
        cleanup();
        return EXIT_FAILURE;
    }
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        if (fprintf(g_log_fp, "timestamp,flow_rate_lpm\n") < 0 || fflush(g_log_fp) != 0) {
            perror("failed to write CSV header");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow logger started. Logging to %s every 100 ms. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double flow_rate = convert_to_lpm(adc_value);

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        if (log_data(g_log_fp, timestamp, flow_rate) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

