#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_ADC 300
#define DEFAULT_MAX_ADC 700
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"

#define MAX_EMAIL_RECIPIENTS 10
#define MAX_MSMTP_CONFIG_PATH 256

typedef struct {
    int spi_channel;
    int adc_channel;
    int min_adc;
    int max_adc;
    float moisture_threshold;
    int logging_interval;
    char email_recipient[MAX_EMAIL_RECIPIENTS][64];
    int num_recipients;
    char msmtp_config_path[MAX_MSMTP_CONFIG_PATH];
} Config;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int result = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value, int min_adc, int max_adc) {
    if (max_adc <= min_adc) {
        fprintf(stderr, "Error: max_adc must be greater than min_adc\n");
        return -1.0f;
    }
    return 100.0f - ((float)(adc_value - min_adc) / (float)(max_adc - min_adc)) * 100.0f;
}

static int log_data(const char *filename, float moisture_level) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

static int send_email(const char *email_recipient, float moisture_level) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nMoisture level is below threshold: %.2f%%\" | msmtp -t %s",
             moisture_level, email_recipient);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not execute msmtp command: %s\n", strerror(errno));
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) config->spi_channel = atoi(value);
        else if (strcmp(key, "adc_channel") == 0) config->adc_channel = atoi(value);
        else if (strcmp(key, "min_adc") == 0) config->min_adc = atoi(value);
        else if (strcmp(key, "max_adc") == 0) config->max_adc = atoi(value);
        else if (strcmp(key, "moisture_threshold") == 0) config->moisture_threshold = atof(value);
        else if (strcmp(key, "logging_interval") == 0) config->logging_interval = atoi(value);
        else if (strcmp(key, "email_recipient") == 0) {
            if (config->num_recipients < MAX_EMAIL_RECIPIENTS) {
                strncpy(config->email_recipient[config->num_recipients], value, 63);
                config->email_recipient[config->num_recipients][63] = '\0';
                config->email_recipient[config->num_recipients + 1] = NULL;
                config->num_recipients++;
            }
        }
        else if (strcmp(key, "msmtprc_path") == 0) {
            strncpy(config->msmtprc_path, value, MAX_MSMTP_CONFIG_PATH - 1);
            config->msmtprc_path[MAX_MSMTP_CONFIG_PATH - 1] = '\0';
        }
    }
    fclose(fp);

    if (config->spi_channel < 0 || config->adc_channel < 0 ||
        config->min_adc < 0 || config->max_adc < 0 ||
        config->logging_interval < 0) {
        fprintf(stderr, "Error: Invalid configuration value in %s\n", filename);
        return -1;
    }
    if (config->max_adc <= config->min_adc) {
        fprintf(stderr, "Error: max_adc must be greater than min_adc in %s\n", filename);
        return -1;
    }
    if (config->num_recipients == 0) {
        fprintf(stderr, "Error: No email recipient specified in %s\n", filename);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    Config config = {
        .spi_channel = DEFAULT_SPI_CHANNEL,
        .adc_channel = DEFAULT_ADC_CHANNEL,
        .min_adc = DEFAULT_MIN_ADC,
        .max_adc = DEFAULT_MAX_ADC,
        .moisture_threshold = DEFAULT_MOISTURE_THRESHOLD,
        .logging_interval = DEFAULT_LOGGING_INTERVAL,
        .num_recipients = 0,
        .msmtprc_path = DEFAULT_MSMTP_CONFIG
    };

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--spi_channel") == 0 && i + 1 < argc) {
            config.spi_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--adc_channel") == 0 && i + 1 < argc) {
            config.adc_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--min_adc") == 0 && i + 1 < argc) {
            config.min_adc = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--max_adc") == 0 && i + 1 < argc) {
            config.max_adc = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--moisture_threshold") == 0 && i + 1 < argc) {
            config.moisture_threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "--logging_interval") == 0 && i + 1 < argc) {
            config.logging_interval = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--email_recipient") == 0 && i + 1 < argc) {
            if (config.num_recipients < MAX_EMAIL_RECIPIENTS) {
                strncpy(config.email_recipient[config.num_recipients], argv[++i], 63);
                config.email_recipient[config.num_recipients][63] = '\0';
                config.email_recipient[config.num_recipients + 1] = NULL;
                config.num_recipients++;
            }
        } else if (strcmp(argv[i], "--msmtprc_path") == 0 && i + 1 < argc) {
            strncpy(config.msmtp_config_path, argv[++i], MAX_MSMTP_CONFIG_PATH - 1);
            config.msmtp_config_path[MAX_MSMTP_CONFIG_PATH - 1] = '\0';
        } else {
            fprintf(stderr, "Usage: %s [--spi_channel <channel>] [--adc_channel <channel>] [--min_adc <min_adc>] [--max_adc <max_adc>] [--moisture_threshold <threshold>] [--logging_interval <interval>] [--email_recipient <email>] [--msmtprc_path <path>]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(0, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (load_config("config.txt", &config) != 0) {
        fprintf(stderr, "Error: Failed to load configuration. Exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d seconds.\n", config.logging_interval);
        } else {
            float moisture_level = calculate_moisture(adc_value, config.min_adc, config.max_adc);
            if (moisture_level < 0) {
                fprintf(stderr, "Error: Failed to calculate moisture level.\n");
            } else {
                if (log_data("plant_data.txt", moisture_level) != 0) {
                    fprintf(stderr, "Error: Failed to log data.\n");
                }

                if (moisture_level < config.moisture_threshold) {
                    for (int i = 0; i < config.num_recipients; i++) {
                        if (send_email(config.email_recipient[i], moisture_level) != 0) {
                            fprintf(stderr, "Error: Failed to send email to recipient %d.\n", i + 1);
                        }
                    }
                }
            }
        }
        sleep(config.logging_interval);
    }

    printf("\nCaught signal, cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

