        } else if (strcmp(argv[i], "--moisture_threshold") == 0 && i + 1 < argc) {
            config.moisture_threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "--logging_interval") == 0 && i + 1 < argc) {
            config.logging_interval = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--email_recipient") == 0 && i + 1 < argc) {
            if (config.num_recipients < MAX_EMAIL_RECIPIENTS) {
                strncpy(config.email_recipient[config.num_recipients], argv[++i], 63);
                config.email_recipient[config.num_recipients][63] = '\0';
                config.email_recipient[config.num_recipients + 1] = NULL;
                config.num_recipients++;
            }
        } else if (strcmp(argv[i], "--msmtprc_path") == 0 && i + 1 < argc) {
            strncpy(config.msmtp_config_path, argv[++i], MAX_MSMTP_CONFIG_PATH - 1);
            config.msmtp_config_path[MAX_MSMTP_CONFIG_PATH - 1] = '\0';
        } else {
            fprintf(stderr, "Usage: %s [--spi_channel <channel>] [--adc_channel <channel>] [--min_adc <min_adc>] [--max_adc <max_adc>] [--moisture_threshold <threshold>] [--logging_interval <interval>] [--email_recipient <email>] [--msmtprc_path <path>]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(0, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (load_config("config.txt", &config) != 0) {
        fprintf(stderr, "Error: Failed to load configuration. Exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d seconds.\n", config.logging_interval);
        } else {
            float moisture_level = calculate_moisture(adc_value, config.min_adc, config.max_adc);
            if (moisture_level < 0) {
                fprintf(stderr, "Error: Failed to calculate moisture level.\n");
            } else {
                if (log_data("plant_data.txt", moisture_level) != 0) {
                    fprintf(stderr, "Error: Failed to log data.\n");
                }

                if (moisture_level < config.moisture_threshold) {
                    for (int i = 0; i < config.num_recipients; i++) {
                        if (send_email(config.email_recipient[i], moisture_level) != 0) {
                            fprintf(stderr, "Error: Failed to send email to recipient %d.\n", i + 1);
                        }
                    }
                }
            }
        }
        sleep(config.logging_interval);
    }

    printf("\nCaught signal, cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

