/*
 * Raspberry Pi 4 Model B - MLX90823 Pressure Sensor Reader
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0
 *     CE0  -> GPIO8  (BCM)
 *     MISO -> GPIO9  (BCM)
 *     MOSI -> GPIO10 (BCM)
 *     SCLK -> GPIO11 (BCM)
 *   - MLX90823 analog output connected to MCP3008 CH0
 *
 * Build: gcc -O2 -Wall -o mlx90823_reader mlx90823_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz - well within MCP3008 spec */
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define ADC_VREF        3.3f       /* Reference voltage */

#define SAMPLE_INTERVAL_S 1
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: 0x80 | (channel << 4)  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocked out for data)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower 2 bits
     *   rx[2] = b7..b0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error: SPI transfer failed");
        return -1;
    }

    uint16_t value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    *out = value;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void)
{
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    install_signal_handlers();

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode 0 */
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI device: %s | Mode 0 | %u bits | %u Hz\n",
           SPI_DEVICE, bits, speed);
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: SPI read failed (attempt %d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Fatal: %d consecutive SPI errors. Aborting.\n",
                        consecutive_errors);
                goto cleanup;
            }
            sleep(1);
            continue;
        }

        consecutive_errors = 0;

        /* Convert ADC value to voltage */
        float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;

        /* Detect sensor-absent / fault conditions */
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 V - sensor may be absent or disconnected\n");
        } else if (adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC reads VREF - sensor may be shorted or disconnected\n");
        }

        /* Log reading with timestamp */
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("%s - ADC: %4u  Voltage: %.3f V\n", ts, adc_value, voltage);

        /* Sleep for the sample interval, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0)
        close(spi_fd);

    return rc;
}

