/*
 * Raspberry Pi Zero W – SEN0193 Capacitive Soil Moisture Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM 23, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 21, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 19, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 24, SPI0 CE0)
 *   MCP3008 CH0  -> SEN0193 analog out
 *   SEN0193 VCC  -> 3.3 V
 *   SEN0193 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 * Run:    ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 spec */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD_S 5          /* seconds between readings */
#define ADC_MAX         1023       /* 10-bit ADC full-scale code */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI                                                                 */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0  + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        printf("[unknown-time] ");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        printf("[unknown-time] ");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv) == 0) {
        printf("[unknown-time] ");
        return;
    }
    printf("%s ", buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0)
        return EXIT_FAILURE;

    printf("MCP3008 Soil Moisture Sensor Reader\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("ADC channel: %u\n", ADC_CHANNEL);
    printf("Period     : %d s\n", SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            print_timestamp();
            fprintf(stderr, "SPI read error – continuing.\n");
        } else if (adc == 0 || adc == ADC_MAX) {
            print_timestamp();
            fprintf(stderr,
                    "Warning: ADC saturated at %d – sensor absent, wiring fault, or dry/drowned.\n",
                    adc);
        } else {
            print_timestamp();
