/*
 * Raspberry Pi 3 Model B+ — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / bus 0, channel 0), 1 MHz, mode 0
 *     MOSI  -> GPIO10 (BCM 10)
 *     MISO  -> GPIO9  (BCM 9)
 *     SCLK  -> GPIO11 (BCM 11)
 *     CH0   <- Vegetronix VH400 analog output (single-ended)
 *   - 12 V water pump via relay on GPIO17 (BCM 17), active-high
 *
 * Behaviour:
 *   - Samples moisture every 5 s.
 *   - Pump ON  when reading < LOW_THRESHOLD (hysteresis).
 *   - Pump OFF when reading > HIGH_THRESHOLD.
 *   - Logs each sample + state change to a 20-entry circular buffer.
 *   - Prints buffer after each sample.
 *   - Graceful shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on SPI0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */

#define PUMP_GPIO        17         /* BCM 17 — relay control (active-high) */

#define MOISTURE_LOW    300        /* below this → pump ON  (hysteresis) */
#define MOISTURE_HIGH   600        /* above this → pump OFF (hysteresis) */

#define BUFFER_SIZE      20
#define SAMPLE_PERIOD_S  5          /* seconds between samples */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static bool     g_pigpio_inited = false;

/* Circular buffer — 20 entries of timestamp + moisture + pump_state */
typedef struct {
    time_t  timestamp;
    int     moisture;
    int     pump_state;
} log_entry_t;

static log_entry_t g_log_buffer[BUFFER_SIZE];
static int         g_log_head = 0;   /* next write slot */
static int         g_log_count = 0; /* entries currently stored */

/* --------------------------- Function prototypes ------------------------- */
static int  read_mcp3008(int channel);
static void control_pump(int moisture);
static void log_data(int moisture, int pump_state);
static void print_log_buffer(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MCP3008 --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  → 10-bit result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;  /* 0..1023 */
}

/* ------------------------------- Pump control ---------------------------- */
static void control_pump(int moisture)
{
    static int pump_state = 0;  /* 0 = off, 1 = on */

    if (moisture < MOISTURE_LOW && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump ON  (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to turn pump ON\n");
        }
    } else if (moisture > MOISTURE_HIGH && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to turn pump OFF\n");
        }
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(int moisture, int pump_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    g_log_buffer[g_log_head].timestamp  = now;
    g_log_buffer[g_log_head].moisture   = moisture;
    g_log_buffer[g_log_head].pump_state = pump_state;

    g_log_head = (g_log_head + 1) % BUFFER_SIZE;
    if (g_log_count < BUFFER_SIZE) g_log_count++;
}

static void print_log_buffer(void)
{
    printf("\n--- Log Buffer (%d entries) ---\n", g_log_count);
    for (int i = 0; i < g_log_count; i++) {
        int idx = (g_log_head - g_log_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&g_log_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "<unknown>");
        }
        printf("[%s] Moisture: %d  Pump: %s\n",
               ts, g_log_buffer[idx].moisture,
               g_log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_pigpio_inited) {
        gpioWrite(PUMP_GPIO, 0);  /* ensure pump is off */
        if (g_spi_handle >= 0) {
            spiClose(g_spi_handle);
            g_spi_handle = -1;
        }
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* pump off at startup */

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitor started.  Sampling every %d s.\n",
           SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "ADC read failed — skipping sample\n");
        } else {
            control_pump(moisture);
            int pump_state = gpioRead(PUMP_GPIO);
            log_data(moisture, pump_state);
            print_log_buffer();
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

