#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */
#define NUM_CHANNELS 3
#define LOG_INTERVAL_US 500000  /* 500 ms */
#define CSV_FILENAME "analog_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] bits 1:0  -> result bits 9:8
     *   rx[2]          -> result bits 7:0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(FILE *fp, int channel, int voltage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, channel, (double)voltage);
    fflush(fp);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open CSV file (append) --- */
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s\n", CSV_FILENAME);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Channel,Voltage\n");
        fflush(fp);
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Logging MCP3008 channels 0-2 to %s every 500 ms. Press Ctrl+C to stop.\n",
           CSV_FILENAME);

    /* --- Main sampling loop --- */
    while (g_running) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int voltage = read_mcp3008(ch);
            if (voltage >= 0) {
                log_data(fp, ch, voltage);
            } else {
                /* Log the error event to the CSV */
                time_t rawtime;
                struct tm timeinfo;
                char ts[32];
                time(&rawtime);
                gmtime_r(&rawtime, &timeinfo);
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);
                fprintf(fp, "%s,ERROR,READ_FAILED\n", ts);
                fflush(fp);
            }
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    fclose(fp);
    spiClose(g_spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

