#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01

#define RELAY_GPIO       17
#define DOOR_SENSOR_GPIO 27

#define LOG_FILE         "/var/log/door_events.log"
#define SAMPLE_PERIOD_MS 200
#define CALIBRATION_MS   50
#define RELAY_PULSE_MS   3000
#define CALIBRATION_SAMPLES 10

#define ADS1115_PGA_4_096V  0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS   0x0080
#define ADS1115_CQUE_NONE   0x0003
#define ADS1115_OS_BEGIN    0x8000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_start_conversion(int fd) {
    uint16_t cfg = ADS1115_OS_BEGIN | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE |
                   ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    return i2c_write16(fd, ADS1115_REG_CFG, cfg);
}

static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t cfg = ADS1115_OS_BEGIN | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE |
                   ADS1115_DR_128SPS | ADS1115_CQUE_NONE;
    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    usleep(10000);

    uint16_t conv;
    if (i2c_read16(fd, ADS1115_REG_CONV, &conv) < 0) return -1;

    *raw = (int16_t)conv;
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    int16_t raw;
    if (ads1115_read_raw(fd, &raw) < 0) return -1;
    *distance_mm = (int)raw;
    return 0;
}

static int calibrate_sensor(int fd, int *threshold_mm) {
    int sum = 0;
    int valid = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int d;
        if (read_distance(fd, &d) == 0) {
            sum += d;
            valid++;
        }
        usleep(CALIBRATION_MS * 1000);
    }
    if (valid == 0) return -1;
    *threshold_mm = sum / valid;
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

static void cleanup(int fd) {
    if (fd >= 0) close(fd);
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (ads1115_start_conversion(fd) < 0) {
        fprintf(stderr, "Error starting ADS1115 conversion: %s\n", strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }

    int threshold = 0;
    if (calibrate_sensor(fd, &threshold) < 0) {
        fprintf(stderr, "Sensor calibration failed (no valid readings)\n");
        close(fd);
        gpioTerminate();
        return 1;
    }
    printf("Calibration complete. Threshold: %d mm\n", threshold);

    while (g_running) {
        int distance;
        if (read_distance(fd, &distance) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (distance < threshold) {
            printf("Distance below threshold: %d mm\n", distance);
            gpioWrite(RELAY_GPIO, 1);
            usleep(RELAY_PULSE_MS * 1000);
            gpioWrite(RELAY_GPIO, 0);

            int door_open = (gpioRead(DOOR_SENSOR_GPIO) == 0);
            if (door_open) {
                log_event("door opened");
                printf("Door opened\n");
            } else {
                log_event("door not opened");
                printf("Door not opened\n");
            }
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    cleanup(fd);
    return 0;
}

