    if (gpio_desc_set_value((struct gpio_desc *)cs_pin, 0) < 0) {
        perror("gpio_desc_set_value(low)");
        return -1;
    }

    /* Small delay so the MCP3008 latches the command */
    usleep(10);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpio_desc_set_value((struct gpio_desc *)cs_pin, 1);
        return -1;
    }

    /* Deassert CS */
    if (gpio_desc_set_value((struct gpio_desc *)cs_pin, 1) < 0) {
        perror("gpio_desc_set_value(high)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int s1, int s2, int s3)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, s3) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void)
{
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    if (setup_gpio_cs(CS0_PIN) < 0) return EXIT_FAILURE;
    if (setup_gpio_cs(CS1_PIN) < 0) return EXIT_FAILURE;
    if (setup_gpio_cs(CS2_PIN) < 0) return EXIT_FAILURE;

    int spi_fd = setup_spi();
    if (spi_fd < 0)
        return EXIT_FAILURE;

    /* Check whether the log file exists / is empty so we can write a header */
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (!file_exists) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            perror("fprintf(header)");
            fclose(fp);
            close(spi_fd);
            return EXIT_FAILURE;
        }
        if (fflush(fp) != 0) {
            perror("fflush(header)");
            fclose(fp);
            close(spi_fd);
            return EXIT_FAILURE;
        }
    }

    printf("Logging soil moisture to %s every %d s. Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        int s1 = mcp3008_read(spi_fd, CS0_PIN, 0);
        int s2 = mcp3008_read(spi_fd, CS1_PIN, 0);
        int s3 = mcp3008_read(spi_fd, CS2_PIN, 0);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");

    if (fclose(fp) != 0)
        perror("fclose");

    if (close(spi_fd) < 0)
        perror("close(spi_fd)");

    return EXIT_SUCCESS;
}

