            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static float adc_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO %d\n", PUMP_GPIO);
        log_message("Error: Failed to write pump GPIO");
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "Pump set to %s", state ? "ON" : "OFF");
        log_message(msg);
    }
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold < 0.0f || threshold > 100.0f) {
                    fprintf(stderr, "Threshold must be between 0 and 100\n");
                    return 1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration <= 0) {
                    fprintf(stderr, "Pump duration must be positive\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        log_message("Error: SPI open failed");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
            log_message("Error: Failed to read ADC value");
            for (int i = 0; i < sleep_interval && running; i++) {
                gpioDelay(1000000);
            }
            continue;
        }

        float moisture = adc_to_percentage(adc_value);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %.2f%% (ADC: %d)", moisture, adc_value);
        log_message(msg);

        if (moisture < threshold) {
            log_message("Moisture below threshold, activating pump");
            control_pump(1);
            for (int i = 0; i < pump_duration && running; i++) {
                gpioDelay(1000000);
            }
            control_pump(0);
            log_message("Pump deactivated");
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }

    log_message("Shutting down irrigation system");
    cleanup();
    return 0;
}

