#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x48          /* ADS1115 default address (ADDR -> GND) */
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

/* Config: single-shot, AIN0 vs GND, +/-4.096 V, 128 SPS, continuous */
#define ADS1115_CFG_BASE      0x8000       /* OS bit: begin single conversion */
#define ADS1115_CFG_MUX_AIN0  0x4000       /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096 0x0200       /* PGA = +/-4.096 V */
#define ADS1115_CFG_DR_128   0x0080       /* 128 SPS */
#define ADS1115_CFG_MODE_SS  0x0100       /* Single-shot mode */
#define ADS1115_CFG_CQUE_NONE 0x0003      /* Disable comparator */

#define GPIO_SHUTDOWN        27
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     1000000       /* 1 Hz */
#define THRESHOLD_GAUSS      500.0f
#define ADC_MAX_COUNT        32767         /* 16-bit signed, positive range */
#define ADC_VREF             4.096f
#define SENSOR_VMIN          0.0f
#define SENSOR_VMAX          3.3f
#define SENSOR_SENSITIVITY   0.5f          /* Gauss per volt (typical SS49E) */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static int  ads1115_init(int handle);
static int  ads1115_read_raw(int handle, int16_t *raw_out);
static float raw_to_voltage(int16_t raw);
static float voltage_to_gauss(float v);
static void buffer_add(float gauss);
static float buffer_avg(void);
static void cleanup(void);

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers --------------------------- */
static int ads1115_init(int handle)
{
    uint16_t cfg = ADS1115_CFG_BASE
                 | ADS1115_CFG_MUX_AIN0
                 | ADS1115_CFG_PGA_4_096
                 | ADS1115_CFG_DR_128
                 | ADS1115_CFG_MODE_SS
                 | ADS1115_CFG_CQUE_NONE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(cfg >> 8);
    buf[2] = (char)(cfg & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        syslog(LOG_ERR, "ADS1115 config write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    char reg = ADS1115_REG_CONV;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "ADS1115 conv reg select failed: %s", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 conversion read failed: %s", strerror(errno));
        return -1;
    }
    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

static float raw_to_voltage(int16_t raw)
{
    return ((float)raw / (float)ADC_MAX_COUNT) * ADC_VREF;
}

static float voltage_to_gauss(float v)
{
    return v * SENSOR_SENSITIVITY;
}

/* ----------------------------- Circular buffer --------------------------- */
static void buffer_add(float gauss)
{
    static float buf[BUFFER_SIZE];
    static int   idx = 0;
    buf[idx] = gauss;
    idx = (idx + 1) % BUFFER_SIZE;
}

static float buffer_avg(void)
{
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++)
        sum += buf[i];
    return sum / (float)BUFFER_SIZE;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_SHUTDOWN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %s",
               I2C_BUS, I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ads1115_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "ADS1115 initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Hall sensor monitoring started (ADS1115 @ 0x%02X, GPIO %d)",
           I2C_ADDR, GPIO_SHUTDOWN);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_handle, &raw) != 0) {
            syslog(LOG_ERR, "ADC read error; skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        if (voltage < SENSOR_VMIN || voltage > SENSOR_VMAX) {
            syslog(LOG_ERR, "Voltage out of range: %.3f V", voltage);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        buffer_add(gauss);

        syslog(LOG_INFO, "Raw=%d  V=%.3f  B=%.3f G", raw, voltage, gauss);

        if (gauss > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Threshold exceeded (%.3f G > %.1f G) - shutting down",
                   gauss, THRESHOLD_GAUSS);
            gpioWrite(GPIO_SHUTDOWN, 1);
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

