#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define ADC_CHANNEL      0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO        18
#define WATERING_DURATION 10
#define LOG_FILE         "watering_events.txt"
#define SAMPLE_INTERVAL  60
#define MAX_VALID_READINGS 5
#define STUCK_THRESHOLD  2000

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel, int *out_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int status = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (status < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int control_pump(int state) {
    int status = gpioWrite(PUMP_GPIO, state);
    if (status < 0) {
        fprintf(stderr, "Failed to write GPIO %d: %d\n", PUMP_GPIO, status);
        return -1;
    }
    return 0;
}

static int log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture level: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    if (control_pump(0) < 0) {
        gpioTerminate();
        return 1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", g_spi_handle);
        control_pump(0);
        gpioTerminate();
        return 1;
    }

    int valid_readings = 0;
    int stuck_count = 0;

    while (g_running) {
        int moisture_level = 0;
        if (read_mcp3008(ADC_CHANNEL, &moisture_level) != 0) {
            fprintf(stderr, "Failed to read ADC channel %d\n", ADC_CHANNEL);
            sleep(1);
            continue;
        }

        if (moisture_level > STUCK_THRESHOLD) {
            stuck_count++;
            if (stuck_count >= MAX_VALID_READINGS) {
                fprintf(stderr, "ADC stuck or disconnected (last reading: %d). Aborting.\n", moisture_level);
                break;
            }
        } else {
            stuck_count = 0;
            valid_readings = 0;
        }

        valid_readings++;

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level %d below threshold %d. Watering...\n",
                   moisture_level, MOISTURE_THRESHOLD);

            if (control_pump(1) == 0) {
                for (int i = 0; i < WATERING_DURATION && g_running; i++) {
                    sleep(1);
                }
                if (control_pump(0) == 0) {
                    printf("Watering complete.\n");
                    if (log_event(moisture_level) != 0) {
                        fprintf(stderr, "Failed to log watering event.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to deactivate pump.\n");
                }
            } else {
                fprintf(stderr, "Failed to activate pump.\n");
            }
        } else {
            printf("Moisture level %d above threshold %d. Not watering.\n",
                   moisture_level, MOISTURE_THRESHOLD);
        }

        if (valid_readings >= MAX_VALID_READINGS && g_running) {
            printf("All valid readings received. Continuing.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

