/*
 * Rain sensor reader for Raspberry Pi 4 Model B
 * Sensor : YL-83 (analog) via MCP3008 ADC on SPI0 (CE0, channel 0)
 * SPI    : mode 0, 1 MHz, single-ended
 * Build  : gcc -O2 -Wall -Wextra -o rain_reader rain_reader.c -lpigpio -lrt
 * Run    : sudo ./rain_reader
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0          /* CE0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended CH0 */
#define ADC_MAX          1023       /* 10-bit, VDD = 3.3 V */
#define SAMPLE_PERIOD_S  1          /* seconds between readings */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 in single-ended mode.              */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static void log_data(int adc_value, float intensity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - ADC: %4d, Rainfall Intensity: %.2f\n",
           timestamp, adc_value, intensity);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 ----------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ------------------------------------ */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Rain sensor reader started. Press Ctrl-C to exit.\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
        } else {
            float intensity = (float)adc_value / (float)ADC_MAX;
            log_data(adc_value, intensity);
        }

        /* Sleep in 100 ms increments so SIGINT is noticed promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Graceful cleanup ------------------------------------------- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

