code:
/*
 * Raspberry Pi 4 Model B – Honeywell SS49E Hall sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E (linear Hall effect) -> ADS1115 AIN0 (single-ended)
 *   - ADS1115 on I2C bus 1, address 0x48
 *   - LED + 330 Ω resistor on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   OS=1 (start single conversion), MUX=100 (AIN0 vs GND),
 *   PGA=001 (4.096 V), MODE=1 (single-shot), DR=100 (128 SPS),
 *   COMP_QUE=11 (disable comparator).
 */
#define ADS1115_CFG_BASE     0x8483

#define LED_GPIO             17
#define DEFAULT_THRESHOLD    100.0f   /* Gauss */
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define BLINK_DURATION_US    1000000  /* 1 s  */
#define BLINK_HALF_PERIOD_US 50000    /* 50 ms */

/* ADS1115 full-scale range at PGA = 4.096 V */
#define ADS1115_PGA_4_096V   4.096f
#define ADS1115_MAX_COUNT   32767.0f  /* positive full-scale code */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static float g_threshold = DEFAULT_THRESHOLD;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "i2cWriteByte(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-ended conversion on AIN0 and read the raw count.
 * Returns 0 on success and stores the count in *raw, -1 on failure.
 */
static int ads1115_read_ain0(int handle, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_BASE | 0x8000; /* OS bit */

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &conv) < 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/*
 * Convert raw ADC count to Gauss.
 * SS49E sensitivity ~0.5 mV/Gauss => 1 count = 4.096 V / 32767 * 1000 / 1000 G.
 */
static float raw_to_gauss(int16_t raw)
{
    const float v_per_count = (ADS1115_PGA_4_096V / ADS1115_MAX_COUNT) * 1000.0f;
    return (float)raw * v_per_count / 1000.0f;
}

/* ------------------------------- Main ------------------------------------ */

int main(int argc, char *argv[])
{
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            g_threshold = (float)atof(optarg);
            if (g_threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive (got %.2f)\n",
                        (double)g_threshold);
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LED setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed: %s\n", LED_GPIO, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SS49E via ADS1115 (addr 0x%02X) on I2C bus %d...\n",
           ADS1115_ADDR, I2C_BUS);
    printf("Threshold: %.2f Gauss | LED on GPIO%d | sample period: %d ms\n",
           (double)g_threshold, LED_GPIO, SAMPLE_PERIOD_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(i2c_handle, &raw) < 0) {
            fprintf(stderr, "ADC read error – continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic field: %.2f Gauss\n", (double)gauss);

        if (gauss > g_threshold) {
            printf("Threshold exceeded! Blinking LED for 1 s...\n");
            gpioWrite(LED_GPIO, 1);
            gpioDelay(BLINK_HALF_PERIOD_US);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(BLINK_HALF_PERIOD_US);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

