#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define MCP3008_CHANNEL  0
#define PUMP_GPIO        17
#define MOISTURE_LOW     30
#define MOISTURE_HIGH    35
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC       "soil_moisture"
#define MQTT_CLIENT_ID   "rpi4_soil_moisture"
#define SAMPLE_INTERVAL  60
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
                return -1;
            }
            return adc_value;
        }
        syslog(LOG_ERR, "SPI transfer failed (attempt %d/%d): %s",
               attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    syslog(LOG_ERR, "SPI transfer failed after %d retries", MAX_RETRIES);
    return -1;
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write pump GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Pump set to %s", state ? "ON" : "OFF");
    return 0;
}

static void publish_moisture(int moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", moisture);
    int ret = mosquitto_publish(g_mosq, NULL, MQTT_TOPIC,
                                (int)strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %d%%", moisture);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message) {
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty MQTT message on %s", message->topic);
        return;
    }

    char payload[32];
    int len = message->payloadlen < (int)sizeof(payload) - 1
              ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(message->topic, MQTT_TOPIC) == 0) {
        syslog(LOG_INFO, "Received moisture data: %s", payload);
        return;
    }

    if (strcmp(message->topic, "pump_control") == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            control_pump(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            control_pump(0);
        } else {
            syslog(LOG_WARNING, "Unknown pump command: %s", payload);
        }
    } else {
        syslog(LOG_WARNING, "Unknown MQTT topic: %s", message->topic);
    }
}

static void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int ret = mosquitto_subscribe(mosq, NULL, "pump_control", 0);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(ret));
        } else {
            syslog(LOG_INFO, "Subscribed to pump_control");
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    (void)mosq;
    (void)userdata;
    if (rc == 0) {
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    } else {
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
    }
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_mosq != NULL) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set pump GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (g_mosq == NULL) {
        syslog(LOG_ERR, "mosquitto_new failed");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int ret = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    ret = mosquitto_loop_start(g_mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Soil moisture monitoring started");

    while (g_running) {
        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            syslog(LOG_INFO, "Moisture: %d%%", moisture);

            if (moisture < MOISTURE_LOW) {
                if (control_pump(1) == 0) {
                    publish_moisture(moisture);
                }
            } else if (moisture > MOISTURE_HIGH) {
                if (control_pump(0) == 0) {
                    publish_moisture(moisture);
                }
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

