#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_MODE_0_VAL  0
#define SPI_BITS        8
#define SPI_SPEED_HZ    1000000
#define ADC_CHANNEL     0
#define VDD             3.3
#define VREF            3.3
#define SAMPLE_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
