#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define VREF        3.3
#define CSV_FILE    "sensor_data.csv"
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, or -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower 2 bits
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double adc_to_voltage(int adc_value, double vref)
{
    return ((double)adc_value / 1023.0) * vref;
}

static int log_data(const char *filename, double v0, double v1, double v2)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, v0, v1, v2) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logging started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (!g_terminate) {
        int adc[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = read_mcp3008(spi_handle, i);
            if (adc[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
        }

        if (error) {
            /* Attempt to close SPI cleanly before retrying */
            spiClose(spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        double v0 = adc_to_voltage(adc[0], VREF);
        double v1 = adc_to_voltage(adc[1], VREF);
        double v2 = adc_to_voltage(adc[2], VREF);

        if (log_data(CSV_FILE, v0, v1, v2) != 0) {
            fprintf(stderr, "Error logging data\n");
            /* Attempt to close SPI cleanly before exiting */
            spiClose(spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("V0: %.3f V, V1: %.3f V, V2: %.3f V\n", v0, v1, v2);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S && !g_terminate; s++) {
            sleep(1);
        }
    }

    /* --- Clean shutdown --- */
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

