    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
