        } else if (sound_err < 0) {
            error_code = 2;
        }
        log_data(sound_level_db, light_level_lux, error_code);
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }
    cleanup();
    return 0;
