/*
 * Raspberry Pi 4 Model B — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / BCM 8), SPI mode 0, 1 MHz
 *   - Vegetronix VH400 analog output -> MCP3008 channel 0
 *   - Relay-driven water pump on BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 (BCM 8)  */
#define SPI_SPEED        1000000    /* 1 MHz        */
#define SPI_FLAGS        0          /* mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 CH0  */
#define PUMP_GPIO        17         /* BCM 17, active-high relay */
#define MOISTURE_THRESHOLD 30       /* percent */
#define SAMPLE_INTERVAL  60        /* seconds */
#define MAX_RETRIES      3
#define ADC_MAX          1023       /* 10-bit ADC full-scale code */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static int  read_moisture_percent(int channel, int *out_percent);
static void control_pump(int state);
static void log_data(int moisture_percent);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- MCP3008 ----------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

static int read_moisture_percent(int channel, int *out_percent)
{
    int raw = 0;
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (read_mcp3008(channel, &raw) == 0) {
            *out_percent = (int)(((float)raw / (float)ADC_MAX) * 100.0f);
            return 0;
        }
        fprintf(stderr, "ADC read attempt %d/%d failed\n", attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES) {
            gpioDelay(1000000); /* 1 s back-off */
        }
    }
    return -1;
}

/* ----------------------------- Pump control ------------------------------ */
static void control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", PUMP_GPIO, state);
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(int moisture_percent)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Moisture: %d%%\n", ts, moisture_percent);
    fflush(stdout);
}

/* ----------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Ensure pump is off */
    if (g_spi_handle >= 0) {
        control_pump(0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(0); /* start with pump off */

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitor started. Sampling every %d s. Ctrl-C to exit.\n",
           SAMPLE_INTERVAL);

    /* --- Main loop --- */
    while (g_running) {
        int moisture = 0;
        if (read_moisture_percent(ADC_CHANNEL, &moisture) == 0) {
            log_data(moisture);

            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture below threshold (%d%% < %d%%). Activating pump.\n",
                       moisture, MOISTURE_THRESHOLD);
                control_pump(1);
            } else {
                control_pump(0);
            }
        } else {
            fprintf(stderr, "Failed to read moisture after %d retries; skipping cycle.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; ++i) {
            gpioDelay(1000000); /* 1 s */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

