#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CO2_THRESHOLD 700.0
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL 5.0
#define ADC_MAX 1023.0
#define ADC_VREF 3.3
#define SENSOR_OFFSET 0.0
#define SENSOR_SCALE 0.5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return (adc_value / ADC_MAX) * ADC_VREF;
}

static float voltage_to_co2(float voltage) {
    return (voltage - SENSOR_OFFSET) / SENSOR_SCALE;
}

static void control_fan(float co2_ppm) {
    int state = (co2_ppm > CO2_THRESHOLD) ? 1 : 0;
    if (gpioWrite(FAN_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to fan GPIO %d\n", FAN_GPIO);
    }
}

static void log_data(float co2_ppm, int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co2_ppm, fan_state);
    } else {
        fprintf(fp, "timestamp,%.2f,%d\n", co2_ppm, fan_state);
    }

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %.0f seconds...\n", SAMPLE_INTERVAL);
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Error: Invalid ADC value %d (expected 0-1023)\n", adc_value);
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float co2_ppm = voltage_to_co2(voltage);
        control_fan(co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);
        log_data(co2_ppm, fan_state);

        printf("CO2: %.2f ppm, Fan: %s\n", co2_ppm, fan_state ? "ON" : "OFF");

        time_sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

