#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define GPIO_CHIP        "gpiochip0"
#define RELAY_LINE       17

#define ADC_CHANNEL      0
#define ADC_MAX_VALUE    1023
#define ADC_VREF         3.3f
#define ADC_RESOLUTION   1024.0f

#define DISTANCE_THRESHOLD_CM  20.0f
#define DEBOUNCE_DELAY_SEC     1.0
#define POLL_INTERVAL_MS       100

#define LOG_FILE "door_events.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_distance_cm(int adc_value) {
    if (adc_value < 0) return -1.0f;
    if (adc_value > ADC_MAX_VALUE) return 100.0f;

    float voltage = (adc_value / ADC_MAX_VALUE) * ADC_VREF;
    if (voltage < 0.4f) return 100.0f;
    if (voltage > 2.8f) return 10.0f;

    float distance = (1.0f / (0.4f + (voltage - 0.4f) * 0.3f)) - 1.0f;
    return distance * 100.0f;
}

static int log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Door opened\n", timestamp) < 0) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door-relay", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup_spi;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup_spi;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup_spi;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float distance = adc_to_distance_cm(adc_value);
        if (distance < 0.0f) {
            fprintf(stderr, "Invalid distance calculation, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            printf("Door opened!\n");

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("Failed to set relay HIGH");
            }

            if (log_event(LOG_FILE) < 0) {
                fprintf(stderr, "Failed to log event\n");
            }

            sleep((unsigned int)(DEBOUNCE_DELAY_SEC + 0.5));
            if (!program_running) break;

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("Failed to set relay LOW");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");

cleanup_spi:
    if (spi_fd >= 0) close(spi_fd);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

