#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define VALVE_GPIO       17
#define PWM_FREQUENCY    100
#define PWM_RANGE        100
#define NUM_SAMPLES      3
#define SAMPLE_DELAY_US  10000
#define LOG_INTERVAL_S   5
#define LOG_FILE         "irrigation.log"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (don't care)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static int set_valve_position(int gpio, int position)
{
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Invalid valve position %d\n", position);
        return -1;
    }
    if (gpioPWM(gpio, position) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, int s0, int s1, int s2, int avg, int pos)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, s0=%d, s1=%d, s2=%d, avg=%d, pos=%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, s0, s1, s2, avg, pos);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Initial gpioPWM failed for GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation controller started. Logging to %s every %d s.\n",
           LOG_FILE, LOG_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int sum = 0;
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int v = read_mcp3008(g_spi_handle, i);
            if (v < 0) {
                fprintf(stderr, "Sample %d read failed; skipping.\n", i);
                continue;
            }
            sum += v;
            valid++;
            if (i < NUM_SAMPLES - 1) {
                gpioDelay(SAMPLE_DELAY_US);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "All %d samples failed; skipping cycle.\n", NUM_SAMPLES);
        } else {
            int avg = sum / valid;
            int pos = avg;  /* simple proportional control: ADC value maps to 0-100 */
            if (set_valve_position(VALVE_GPIO, pos) != 0) {
                fprintf(stderr, "Failed to set valve position.\n");
            }
            log_data(g_log_file, (valid > 0) ? (i < NUM_SAMPLES ? (int)i : -1) : -1,
                     (valid > 1) ? (i < NUM_SAMPLES ? (int)(i + 1) : -1) : -1,
                     (valid > 2) ? (int)(i + 2) : -1, avg, pos);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int s = 0; s < LOG_INTERVAL_S * 10 && g_running; s++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

