/*
 * Theremin-like instrument for Raspberry Pi Zero W
 *
 * Hardware:
 *   - HC-SR04 ultrasonic sensor: Trig -> GPIO23 (BCM), Echo -> GPIO24 (BCM)
 *   - MCP3008 ADC on SPI0 (CE0 = GPIO8, SCLK = GPIO11, MOSI = GPIO10, MISO = GPIO9)
 *   - Photoresistor (LDR) on MCP3008 channel 0
 *   - PWM output on GPIO18 (BCM) via /sys/class/pwm/pwm0
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define CONFIG_FILE        "theremin_config.txt"
#define PWM_CHIP           "/sys/class/pwm/pwmchip0"
#define PWM_CHANNEL        0
#define PWM_PERIOD_NS      10000000ULL   /* 10 ms = 100 Hz base */
#define PWM_DUTY_MAX_NS    10000000ULL   /* 100 % duty */

#define TRIG_PIN           23
#define ECHO_PIN           24
#define LDR_CHANNEL        0

#define MAX_DISTANCE_CM    400.0
#define MIN_DISTANCE_CM    2.0
#define MAX_FREQUENCY_HZ   2000.0
#define MIN_FREQUENCY_HZ   200.0
#define MIN_VOLUME          0.1
#define MAX_VOLUME          1.0

#define ECHO_TIMEOUT_US    30000
#define SAMPLE_DELAY_MS    50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    double min_frequency;
    double max_frequency;
    double min_volume;
    double max_volume;
} calibration_t;

static calibration_t g_cal;
static double g_last_distance = MAX_DISTANCE_CM;
static double g_last_volume   = MAX_VOLUME;

static void load_calibration(void)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s; using defaults\n",
                CONFIG_FILE, strerror(errno));
        return;
    }
    if (fscanf(fp, "%lf %lf %lf %lf",
               &g_cal.min_frequency, &g_cal.max_frequency,
               &g_cal.min_volume, &g_cal.max_volume) != 4) {
        fprintf(stderr, "Warning: invalid config; using defaults\n");
        fclose(fp);
        return;
    }
    fclose(fp);
    printf("Calibration loaded: freq=[%.1f-%.1f] Hz, vol=[%.2f-%.2f]\n",
           g_cal.min_frequency, g_cal.max_frequency,
           g_cal.min_volume, g_cal.max_volume);
}

static void save_calibration(void)
{
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Warning: cannot save %s: %s\n",
                CONFIG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%.1f %.1f %.2f %.2f\n",
            g_cal.min_frequency, g_cal.max_frequency,
            g_cal.min_volume, g_cal.max_volume);
    fclose(fp);
    printf("Calibration saved to %s\n", CONFIG_FILE);
}

/* ------------------------------------------------------------------ */
/* GPIO / SPI helpers                                                */
/* ------------------------------------------------------------------ */

static int gpio_write(const char *path, const char *val)
{
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, val, strlen(val)) < 0) {
        fprintf(stderr, "write(%s, %s): %s\n", path, val, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read(const char *path, char *buf, size_t len)
{
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len - 1);
    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    return 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }
    uint32_t speed = 1000000;
    uint8_t  bits  = 8;
    uint8_t  mode  = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_ldr(int spi_fd)
{
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (LDR_CHANNEL << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = 1000000,
        .bits_per_word = 8,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* HC-SR04 distance                                                    */
/* ------------------------------------------------------------------ */

static double read_distance(int trig_fd, int echo_fd)
{
    /* Ensure trigger is low for >= 2 us */
    if (gpio_write(trig_fd, "0") < 0) return -1;
    usleep(5);

    /* 10 us trigger pulse */
    if (gpio_write(trig_fd, "1") < 0) return -1;
    usleep(10);
    if (gpio_write(trig_fd, "0") < 0) return -1;

    /* Wait for echo rising edge (timeout) */
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    char val;
    do {
        if (gpio_read(echo_fd, &val, 1) < 0) return -1;
        if (val == '1') break;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if ((t1.tv_sec - t0.tv_sec) * 1000000L +
            (t1.tv_nsec - t0.tv_nsec) / 1000L > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    } while (1);

    /* Measure echo pulse width (falling edge) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    do {
        if (gpio_read(echo_fd, &val, 1) < 0) return -1;
        if (val == '0') break;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if ((t1.tv_sec - t0.tv_sec) * 1000000L +
            (t1.tv_nsec - t0.tv_nsec) / 1000L > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    } while (1);
    struct timespec echo_ts = t1;

    double elapsed_us = (echo_ts.tv_sec - t0.tv_sec) * 1000000.0 +
                        (echo_ts.tv_nsec - t0.tv_nsec) / 1000.0;
    /* speed of sound ~343 m/s => 1 us = 0.0343 cm; round-trip / 2 */
    return elapsed_us / 58.0;
}

/* ------------------------------------------------------------------ */
/* PWM control                                                         */
/* ------------------------------------------------------------------ */

static int pwm_init(void)
{
    char path[128];
    snprintf(path, sizeof(path), "%s/export", PWM_CHIP);
    if (gpio_write(path, "0") < 0) return -1; /* ensure channel 0 exists */

    snprintf(path, sizeof(path), "%s/pwm0/period", PWM_CHIP);
    char buf[32];
    snprintf(buf, sizeof(buf), "%llu", PWM_PERIOD_NS);
    if (gpio_write(path, buf) < 0) return -1;

    snprintf(path, sizeof(path), "%s/pwm0/duty_cycle", PWM_CHIP);
    if (gpio_write(path, "0") < 0) return -1;

    snprintf(path, sizeof(path), "%s/pwm0/enable", PWM_CHIP);
    if (gpio_write(path, "1") < 0) return -1;
    return 0;
}

static void pwm_set_duty(double duty)
{
    if (duty < 0.0) duty = 0.0;
    if (duty > 1.0) duty = 1.0;
    unsigned long ns = (unsigned long)(PWM_PERIOD_NS * duty);
    char buf[32];
    snprintf(buf, sizeof(buf), "%llu", ns);
    gpio_write("%s/pwm0/duty_cycle", PWM_CHIP, buf);
}

static void pwm_stop(void)
{
    gpio_write("%s/pwm0/enable", PWM_CHIP, "0");
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    load_calibration();

    int spi_fd = spi_init("/dev/spidev0.0");
    if (spi_fd < 0) {
        fprintf(stderr, "SPI init failed; continuing without LDR\n");
    }

    if (gpio_write("/sys/class/gpio/gpio23/direction", "out") < 0) {
        fprintf(stderr, "Cannot set GPIO23 as output\n");
        goto cleanup;
    }
    if (gpio_write("/sys/class/gpio/gpio24/direction", "in") < 0) {
        fprintf(stderr, "Cannot set GPIO24 as input\n");
        goto cleanup;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "PWM init failed\n");
        goto cleanup;
    }

    printf("Theremin ready. Ctrl+C to exit.\n");

