#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define LOG_FILE        "alcohol_log.txt"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100
#define SENSOR_ABSENT_THRESHOLD 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(*fd);
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(*fd);
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(*fd);
        return -1;
    }

    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static const char *classify(int ppm) {
    if (ppm > 50) return "Alcohol detected! Limit exceeded.";
    if (ppm < 20) return "Sobriety confirmed.";
    return "Alcohol level within acceptable range.";
}

static int log_data(FILE *f, int ppm) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(f, "%s, ADC: %d, Alcohol: %d ppm, %s\n", ts, ppm, ppm, classify(ppm)) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(f) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

static void log_error(FILE *f, const char *msg) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(f, "%s, ERROR: %s\n", ts, msg) < 0) {
        perror("fprintf");
    }
    if (fflush(f) != 0) {
        perror("fflush");
    }
}

int main(void) {
    int spi_fd = -1;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (spi_init(&spi_fd) < 0) {
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(spi_fd);
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = -1;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            adc = read_mcp3008(spi_fd, ADC_CHANNEL);
            if (adc >= 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!ok) {
            log_error(g_log, "ADC read failed after retries");
            consecutive_errors++;
            if (consecutive_errors >= SENSOR_ABSENT_THRESHOLD) {
                log_error(g_log, "Sensor absent or wiring fault: ADC stuck at rail");
                consecutive_errors = 0;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        consecutive_errors = 0;

        if (adc == 0 || adc == ADC_MAX) {
            log_error(g_log, "Sensor absent or wiring fault: ADC at rail");
        } else {
            int ppm = (int)(((float)adc / ADC_MAX) * 100.0f);
            if (log_data(g_log, ppm) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");

    if (g_log != NULL) {
        if (fclose(g_log) != 0) {
            perror("fclose");
        }
        g_log = NULL;
    }

    if (spi_fd >= 0) {
        if (close(spi_fd) < 0) {
            perror("close");
        }
        spi_fd = -1;
    }

    printf("Alcohol sensor monitoring stopped.\n");
    return 0;
}

