/*
 * Raspberry Pi 4 Model B - Dual Adafruit Mini DC Motor Control
 * Reads two potentiometers via MCP3008 ADC (SPI0, CE0) and drives two
 * Adafruit Mini DC Motors with PWM via GPIO.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V, VREF -> 3.3V, AGND/DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   Motor 1 EN   -> GPIO18
 *   Motor 1 DIR  -> GPIO23
 *   Motor 2 EN   -> GPIO24
 *   Motor 2 DIR  -> GPIO25
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000          /* 1 MHz */
#define SPI_FLAGS        0                /* Mode 0, active-low CE */

#define MOTOR1_ENABLE    18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE    24
#define MOTOR2_DIRECTION 25

#define PWM_FREQUENCY    1000             /* 1 kHz */
#define PWM_RANGE        255              /* 8-bit resolution */

#define ACCELERATION_MS  1000
#define CONSTANT_SPEED_MS 2000
#define DECELERATION_MS  1000
#define PAUSE_MS         5000
#define LOOP_DELAY_MS    50

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static int  map_pot_to_speed(int pot_value);
static void set_motor_speed(int motor_enable, int motor_direction, int speed);
static void accelerate_motor(int motor_enable, int motor_direction);
static void decelerate_motor(int motor_enable, int motor_direction);
static void run_constant_speed(int motor_enable, int motor_direction);
static void reverse_direction(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- MCP3008 ----------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX: [0x01] [SGL|D2|D1|D0 | 0x00] [0x00]
 *   RX: [x]    [x]    [x & 0x03]
 *   10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

