#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_TIME_S 5
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Calibrating ambient noise for %d seconds...\n", CALIBRATION_TIME_S);
    time_t start_time = time(NULL);
    double sum = 0.0;
    int sample_count = 0;

    while (running && (time(NULL) - start_time) < CALIBRATION_TIME_S) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error reading MCP3008 during calibration\n");
            cleanup();
            return EXIT_FAILURE;
        }
        sum += sample;
        sample_count++;
        gpioDelay(1000);
    }

    if (!running) {
        cleanup();
        return EXIT_SUCCESS;
    }

    if (sample_count == 0) {
        fprintf(stderr, "Calibration failed: no samples read\n");
        cleanup();
        return EXIT_FAILURE;
    }

    double baseline = sum / sample_count;
    printf("Calibration complete. Baseline: %.2f\n", baseline);

    while (running) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error reading MCP3008\n");
            break;
        }

        if (sample > baseline) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(DEBOUNCE_DELAY_US);
            gpioWrite(LED_PIN, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

