    if (voltage >= curve.voltage_max) {
        return curve.airflow_max;
    }
    return curve.airflow_min +
           (voltage - curve.voltage_min) *
           (curve.airflow_max - curve.airflow_min) /
           (curve.voltage_max - curve.voltage_min);
