#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_CE0_OFFSET 8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_PERIOD_NS 1000000L  /* 1 ms -> 1000 Hz */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static int  g_gpio_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000U; /* 1 MHz */
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_gpio_fd = open(GPIO_CHIP, O_RDWR);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.line_offset = GPIO_CE0_OFFSET;
    req.default_value = 1; /* idle high (active low CS) */
    req.flags = 0;

    if (ioctl(g_gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        fprintf(stderr, "GPIO_GET_LINEHANDLE_IOCTL: %s\n", strerror(errno));
        close(g_gpio_fd); g_gpio_fd = -1;
        return -1;
    }
    g_gpio_fd = req.fd; /* line handle is returned in fd */

    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01  (start bit)
 *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
 *   tx[2] = 0x00  (clock out remaining bits)
 * Result: bits 9..0 in rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000U;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_sample(long long ts_ns, int adc)
{
    if (fprintf(g_log_fp, "%lld|%d\n", ts_ns, adc) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_gpio_fd >= 0) {
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec next;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &next) < 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int adc = mcp3008_read(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &now) < 0) {
            fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
            break;
        }

        long long ts_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        if (log_sample(ts_ns, adc) < 0) {
            break;
        }

        next.tv_sec  += 1;
        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec  += 1;
            next.tv_nsec -= 1000000000L;
        }

        if (nanosleep(&next, &next) < 0) {
            if (errno == EINTR) {
                continue; /* signal received — re-check g_running */
            }
            fprintf(stderr, "nanosleep: %s\n", strerror(errno));
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

