        if (log_sample(ts_ns, adc) < 0) {
            break;
        }

        next.tv_sec  += 1;
        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec  += 1;
            next.tv_nsec -= 1000000000L;
        }

        if (nanosleep(&next, &next) < 0) {
            if (errno == EINTR) {
                continue; /* signal received — re-check g_running */
            }
            fprintf(stderr, "nanosleep: %s\n", strerror(errno));
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

