#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* pigpio SPI channel 0 maps to CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8 bits/word */

#define ADC_CHANNELS     3          /* X, Y, Z channels on MCP3008 */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC */
#define ADC_VREF         3.3f       /* Reference voltage */

#define SAMPLE_PERIOD_US 100000     /* 10 Hz sampling */

/* Kalman filter parameters (tuned for ADXL335 / MCP3008) */
#define Q_PROCESS_NOISE   0.01f
#define R_MEASUREMENT_NOISE 0.1f
#define K_GAIN            0.1f

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Kalman State ----------------------------- */
typedef struct {
    float x;
    float p;
} KalmanState;

/* ----------------------------- Signal Handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 Helpers -------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int handle, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed on channel %u (returned %d)\n",
                channel, bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- Kalman Filter ---------------------------- */
static KalmanState kalman_init(void)
{
    KalmanState s = { 0.0f, 1.0f };
    return s;
}

static KalmanState kalman_update(KalmanState s, float measurement)
{
    float y = measurement - s.x;
    float s_pred = s.p + Q_PROCESS_NOISE;
    float k = s_pred / (s_pred + R_MEASUREMENT_NOISE);
    s.x += k * y;
    s.p = (1.0f - k) * s_pred;
    return s;
}

/* ----------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 via MCP3008 — Kalman-filtered acceleration (10 Hz)\n");
    printf("Press Ctrl+C to exit.\n");

    KalmanState x_state = kalman_init();
    KalmanState y_state = kalman_init();
    KalmanState z_state = kalman_init();

    while (g_running) {
        int x_raw = mcp3008_read(g_spi_handle, 0);
        int y_raw = mcp3008_read(g_spi_handle, 1);
        int z_raw = mcp3008_read(g_spi_handle, 2);

        if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw 10-bit ADC value to g (approximate linear model) */
        float x_g = (float)x_raw * ADC_VREF / (float)ADC_MAX_VALUE * 0.3f;
        float y_g = (float)y_raw * ADC_VREF / (float)ADC_MAX_VALUE * 0.3f;
        float z_g = (float)z_raw * ADC_VREF / (float)ADC_MAX_VALUE * 0.3f;

        /* Kalman filter */
        x_state = kalman_update(x_state, x_g);
        y_state = kalman_update(y_state, y_g);
        z_state = kalman_update(z_state, z_g);

        printf("X: %+.2f g  Y: %+.2f g  Z: %+.2f g\n",
               x_state.x, y_state.x, z_state.x);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

