#define VOLTAGE_LOW 0.0
#define MAX_MILLITESLA 100.0
#define MIN_MILLITESLA -100.0
#define NUM_SENSORS 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/*
 * Convert a digital GPIO state (0 or 1) to a magnetic field strength in
 * milliteslas.  HIGH is treated as 3.3 V and LOW as 0.0 V.
 */
static double gpio_to_millitesla(int gpio_state) {
    double voltage = (gpio_state == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    return voltage * 1000.0;  /* 1 V = 1000 mT */
}

/*
 * Read a GPIO pin and return its current digital state (0 or 1).
 * Returns -1 on error.
 */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

/*
 * Log the three magnetic field values to the log file in CSV format.
 * Returns 0 on success, -1 on error.
 */
static int log_data(double m1, double m2, double m3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%.2f,%.2f,%.2f\n", m1, m2, m3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    int pins[NUM_SENSORS] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Magnetic sensor logging started. Press Ctrl+C to exit.\n");
    printf("Logging to: %s\n", LOG_FILE);

    while (program_running) {
        double m1 = 0.0, m2 = 0.0, m3 = 0.0;
        int read_ok = 1;

        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            read_ok = 0;
        } else {
            m1 = gpio_to_millitesla(s1);
            m2 = gpio_to_millitesla(s2);
            m3 = gpio_to_millitesla(s3);
        }

        /* Validate computed values are within reasonable range */
        if (m1 < MIN_MILLITESLA || m1 > MAX_MILLITESLA ||
            m2 < MIN_MILLITESLA || m2 > MAX_MILLITESLA ||
            m3 < MIN_MILLITESLA || m3 > MAX_MILLITESLA) {
            fprintf(stderr,
                    "Warning: computed values out of range: "
                    "s1=%.2f mT, s2=%.2f mT, s3=%.2f mT\n",
                    m1, m2, m3);
            read_ok = 0;
        }

        if (read_ok) {
            if (log_data(m1, m2, m3) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        /* Sleep for 100 ms using pigpio's microsecond delay */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    printf("pigpio terminated.\n");

    return EXIT_SUCCESS;
}

