#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel requested");
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        log_event("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_event("Failed to write pump GPIO");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_pump(0) != 0) {
        fprintf(stderr, "Failed to initialise pump to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        log_event("SPI open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Watering system started");

    int pump_state = 0;
    int consecutive_errors = 0;

    while (running) {
        int moisture = read_mcp3008(0);

        if (moisture < 0) {
            consecutive_errors++;
            if (consecutive_errors > 5) {
                log_event("Too many consecutive ADC read failures, aborting");
                break;
            }
        } else {
            consecutive_errors = 0;

            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d%%", moisture);
            log_event(msg);

            if (moisture < MOISTURE_THRESHOLD && pump_state == 0) {
                if (control_pump(1) == 0) {
                    pump_state = 1;
                    log_event("Pump turned ON");
                }
            } else if (moisture >= MOISTURE_THRESHOLD && pump_state == 1) {
                if (control_pump(0) == 0) {
                    pump_state = 0;
                    log_event("Pump turned OFF");
                }
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    control_pump(0);
    gpioTerminate();
    log_event("Watering system stopped");
    return EXIT_SUCCESS;
}

