#include <syslog.h>
#include <pigpio.h>

#include "mqtt_client.h"
#include "json_parser.h"

#define MQTT_BROKER_ADDRESS "tcp://mqtt.eclipseprojects.io:1883"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_LED 17
#define MAX_RECONNECT_DELAY 60
#define JSON_KEY_LED_STATE "led_state"

static volatile sig_atomic_t g_running = 1;
static int g_reconnect_delay = 1;
static mqtt_client_t *g_mqtt_client = NULL;

static void signal_handler(int signal) {
    (void)signal;
    g_running = 0;
}

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
    syslog(LOG_ERR, "%s", message);
}

static void led_control(bool led_state) {
    if (gpioWrite(GPIO_LED, led_state ? 1 : 0) != 0) {
        log_message("Failed to write to GPIO pin");
    }
}

static void on_connect(void *context, char *client_id, int reason_code) {
    (void)context;
    (void)client_id;
    if (reason_code == MQTTCONNACK_SUCCESS) {
        log_message("Connected to MQTT broker");
        if (mqtt_subscribe(g_mqtt_client, MQTT_TOPIC, 0) != 0) {
            log_message("Failed to subscribe to topic");
        }
    } else {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Connection to MQTT broker failed with code: %d", reason_code);
        log_message(error_message);
    }
}

static void on_disconnect(void *context, int reason_code) {
    (void)context;
    if (reason_code != MQTTDISCONNECT_SUCCESS) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Unexpected MQTT disconnect with code: %d", reason_code);
        log_message(error_message);
    }
}

static void on_message(void *context, char *topic_name, int topic_name_length, char *message, int message_length) {
    (void)context;
    (void)topic_name_length;

    if (message_length < 2) {
        log_message("Message too short to contain JSON key");
        return;
    }

    char *key = message;
    char *value = message + 1;
    int key_length = 1;
    int value_length = message_length - 1;

    while (*value != '\0' && key_length < message_length) {
        if (*value == ':') {
            break;
        }
        value++;
        key_length++;
    }

    if (*value == '\0') {
        log_message("JSON payload does not contain a colon");
        return;
    }

    char *endptr;
    long val = strtol(value, &endptr, 10);
    if (*endptr != '\0') {
        log_message("JSON value is not an integer");
        return;
    }

    if (strcmp(key, JSON_KEY_LED_STATE) == 0) {
        led_control((bool)val);
    } else {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Unexpected key in JSON: %s", key);
        log_message(error_message);
    }
}

static void on_subscribe(void *context, int reason_code, char *topic_name, int topic_name_length) {
    (void)context;
    (void)reason_code;
    (void)topic_name_length;
    if (reason_code != 0) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Subscribe failed with code: %d", reason_code);
        log_message(error_message);
    }
}

static void on_unsubscribe(void *context, int reason_code, char *topic_name, int topic_name_length) {
    (void)context;
    (void)reason_code;
    (void)topic_name_length;
}

static void cleanup(void) {
    if (g_mqtt_client != NULL) {
        mqtt_disconnect(g_mqtt_client);
        g_mqtt_client = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("rpi_led_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        log_message("Failed to set GPIO mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_LED, 0) != 0) {
        log_message("Failed to initialize GPIO pin to LOW");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_mqtt_client = mqtt_create_client();
    if (g_mqtt_client == NULL) {
        log_message("Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_set_client_id(g_mqtt_client, MQTT_CLIENT_ID) != 0) {
        log_message("Failed to set MQTT client ID");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mqtt_set_on_connect_callback(g_mqtt_client, on_connect) != 0) {
        log_message("Failed to set on_connect callback");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mqtt_set_on_disconnect_callback(g_mqtt_client, on_disconnect) != 0) {
        log_message("Failed to set on_disconnect callback");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mqtt_set_on_message_callback(g_mqtt_client, on_message) != 0) {
        log_message("Failed to set on_message callback");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mqtt_set_on_subscribe_callback(g_mqtt_client, on_subscribe) != 0) {
        log_message("Failed to set on_subscribe callback");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mqtt_set_on_unsubscribe_callback(g_mqtt_client, on_unsubscribe) != 0) {
        log_message("Failed to set on_unsubscribe callback");
        cleanup();
        return EXIT_FAILURE;
    }

    if (mqtt_connect(g_mqtt_client, MQTT_BROKER_ADDRESS) != 0) {
        log_message("Failed to connect to MQTT broker");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int rc = mqtt_loop(g_mqtt_client, g_reconnect_delay);
        if (rc != 0) {
            char error_message[128];
            snprintf(error_message, sizeof(error_message), "MQTT loop failed with code: %d", rc);
            log_message(error_message);
            if (g_reconnect_delay < MAX_RECONNECT_DELAY) {
                g_reconnect_delay *= 2;
            }
            if (g_reconnect_delay > MAX_RECONNECT_DELAY) {
                g_reconnect_delay = MAX_RECONNECT_DELAY;
            }
            sleep(g_reconnect_delay);
        } else {
            g_reconnect_delay = 1;
        }
    }

    log_message("Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

