#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO    18
#define POLL_DELAY_US     100000   /* 100 ms */
#define ALARM_HOLD_US     1000000  /* 1 s   */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sound sensor input --- */
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure alarm LED output --- */
    if (gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure alarm starts OFF --- */
    if (gpioWrite(ALARM_LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize alarm LED state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started (DO=GPIO%d, LED=GPIO%d).\n",
           SOUND_SENSOR_GPIO, ALARM_LED_GPIO);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(SOUND_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read sound sensor on GPIO%d.\n",
                    SOUND_SENSOR_GPIO);
            break;
        }

        printf("Sound level: %d\n", level);

        if (level == 0) {
            /* KY-038 DO goes LOW when sound exceeds threshold */
            if (gpioWrite(ALARM_LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED.\n");
                break;
            }
            gpioDelay(ALARM_HOLD_US);
            if (gpioWrite(ALARM_LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED.\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(ALARM_LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

