#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* BMP280 I2C address (0x76 when SDO grounded) */
#define BMP280_I2C_ADDR 0x76

/* BMP280 register addresses */
#define BMP280_REG_ID       0xD0
#define BMP280_REG_RESET    0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG   0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_CALIB    0x88

/* Expected chip ID */
#define BMP280_CHIP_ID      0x58

/* Oversampling x1 for both temperature and pressure */
#define BMP280_OSS 1

/* Sea-level pressure in Pa (101325 Pa = 1013.25 hPa) */
#define SEA_LEVEL_PRESSURE 101325.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* Calibration coefficients */
static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration_data(void) {
    uint8_t data[24];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP280_REG_CALIB, (char *)data, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data from BMP280.\n");
        return -1;
    }
    dig_T1 = (uint16_t)(data[0]  | (data[1]  << 8));
    dig_T2 = (int16_t)(data[2]  | (data[3]  << 8));
    dig_T3 = (int16_t)(data[4]  | (data[5]  << 8));
    dig_P1 = (uint16_t)(data[6]  | (data[7]  << 8));
    dig_P2 = (int16_t)(data[8]  | (data[9]  << 8));
    dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int init_bmp280(void) {
    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (pigpio error %d).\n",
                BMP280_I2C_ADDR, g_i2c_handle);
        return -1;
    }

    int chip_id = i2cReadByteData(g_i2c_handle, BMP280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error: Failed to read chip ID (pigpio error %d).\n", chip_id);
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present or wrong part.\n",
                chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (read_calibration_data() != 0) {
        return -1;
    }

    /* config: t_sb=0.5ms (000), filter=off (000), spi3w_en=0 */
    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register.\n");
        return -1;
    }

    /* ctrl_meas: osrs_t=x1 (001), osrs_p=x1 (001), normal mode (11) */
    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_CTRL_MEAS, (BMP280_OSS << 5) | (BMP280_OSS << 2) | 0x03) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register.\n");
        return -1;
    }

    return 0;
}

static int read_raw_data(int32_t *raw_pressure, int32_t *raw_temperature) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw pressure and temperature data.\n");
        return -1;
    }
    *raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_temperature) {
    double var1 = ((double)raw_temperature / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temperature / 131072.0 - (double)dig_T1 / 8192.0) *
                  ((double)raw_temperature / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    double t_fine = var1 + var2;
    return t_fine / 5120.0;
}

static double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1 = (t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)dig_P4 * 65536.0);
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) {
        return 0.0;
    }
    double p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;
    return p;
}

static double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_PRESSURE, 0.1903));
}

static int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(g_log_file, "%s, %.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (init_bmp280() != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen("altitude_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error: Failed to open altitude_log.txt");
        cleanup();
        return 1;
    }

    printf("BMP280 initialized. Logging altitude to altitude_log.txt every 5 seconds. Press Ctrl+C to exit.\n");

    while (g_running) {
        int32_t raw_pressure, raw_temperature;
        double temperature, pressure, altitude;

        if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);
            altitude = calculate_altitude(pressure);

            if (log_altitude(altitude) != 0) {
                fprintf(stderr, "Warning: Failed to log altitude.\n");
            } else {
                printf("Altitude: %.2f meters\n", altitude);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < 5 && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

