        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure flame sensor pin as input with pull-down */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on BCM pin %d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_PIN);

    while (g_running) {
        int state = gpioRead(FLAME_SENSOR_PIN);
        if (state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", FLAME_SENSOR_PIN);
            break;
        }

        if (log_event(FLAME_SENSOR_PIN, state) != 0) {
            fprintf(stderr, "Failed to log event; continuing.\n");
        }

        if (state == 1) {
            printf("ALARM: Flame detected on pin %d!\n", FLAME_SENSOR_PIN);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean up GPIO resources */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

