#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL    0          /* CE0 on GPIO 8 */
#define SPI_SPEED      500000     /* 500 kHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define I2C_BUS        1          /* /dev/i2c-1 on GPIO 2/3 */
#define I2C_ADDR       0x60       /* MCP4725 default address */
#define MCP3008_CHANNEL 0         /* TMP36 on CH0 */
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_US      500000     /* 0.5 s */
#define MAX_RETRIES    3

/* Globals for cleanup */
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 channel (single-ended)                                 */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            return adc;
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Convert TMP36 voltage to degrees Celsius                           */
/* TMP36:  Vout = (Temp_C - 0) * 100 / 1024  (0 V at 0 °C, 1.0 V at 100 °C) */
/* ------------------------------------------------------------------ */
static float adc_to_celsius(int adc)
{
    if (adc < 0) return -999.0f;
    float voltage = (adc * 3.3f) / 1024.0f;
    return (voltage * 100.0f) - 50.0f;
}

/* ------------------------------------------------------------------ */
/* Write MCP4725 DAC: 12-bit value (0–4095)                             */
/* ------------------------------------------------------------------ */
static int write_mcp4725(int value)
{
    if (value < 0 || value > 4095) {
        fprintf(stderr, "Error: DAC value %d out of range (0–4095)\n", value);
        return -1;
    }

    /* MCP4725: write 2 bytes, MSB first
     *   byte 0 = 0x00 (DAC input, no EEPROM)
     *   byte 1 = (value << 4) | 0x00  (upper nibble = value, lower nibble = 0)
     * Result: DAC output = (value << 8) / 4095
     */
    char buf[2] = { 0x00, (char)((value << 4) & 0xF0) };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = i2cWriteDevice(i2c_handle, buf, 2);
        if (ret == 0) return 0;
        fprintf(stderr, "Warning: I2C write to MCP4725 failed (attempt %d/%d, ret=%d)\n",
                attempt + 1, MAX_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log one reading                                                     */
/* ------------------------------------------------------------------ */
static void log_reading(int adc, float temp_c, float dac_v)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };

    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    fprintf(log_file, "%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n",
            ts, adc, temp_c, dac_v);
    fflush(log_file);

    printf("%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n",
           ts, adc, temp_c, dac_v);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (bus %d, addr 0x%02X)\n",
                I2C_BUS, I2C_ADDR);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");
    printf("SPI: channel %d @ %d Hz | I2C: bus %d addr 0x%02X | Log: %s\n",
           SPI_CHANNEL, SPI_SPEED, I2C_BUS, I2C_ADDR, LOG_FILE);

    /* Main loop */
    while (!terminate) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "Error: failed to read MCP3008 channel %d after %d retries\n",
                    MCP3008_CHANNEL, MAX_RETRIES);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float temp_c = adc_to_celsius(adc);
        float dac_v = (temp_c / 100.0f) * 3.3f;

        if (write_mcp4725((int)(dac_v / 3.3f * 4095.0f)) != 0) {
            fprintf(stderr, "Error: failed to write MCP4725 after %d retries\n",
                    MAX_RETRIES);
        }

        log_reading(adc, temp_c, dac_v);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

