#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define NUM_RELAYS 4
#define RELAY_ON_TIME_US 1000000  /* 1 second in microseconds */
#define RELAY_OFF_TIME_US 1000000 /* 1 second in microseconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Active-high relay: LOW = OFF, HIGH = ON */
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void)
{
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(pins[i], 0); /* ensure relay is OFF */
    }
    gpioTerminate();
}

static void activate_relay(int pin)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to activate relay on GPIO %d.\n", pin);
    }
}

static void deactivate_relay(int pin)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay on GPIO %d.\n", pin);
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            activate_relay(RELAY1_PIN + i);
            gpioDelay(RELAY_ON_TIME_US);
            deactivate_relay(RELAY1_PIN + i);
            gpioDelay(RELAY_OFF_TIME_US);
        }
    }

    cleanup_gpio();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

