        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set IN1 pin mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set IN2 pin mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor\n");
        } else {
            log_rain_level(rain_level);
            control_window(rain_level);
        }
        gpioDelay(1000000);
    }

    printf("\nCleaning up...\n");
    motor_stop();
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

