#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN 26
#define LED_PIN 16

#define CLAP_THRESHOLD 100
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000
#define ADC_MAX 1023

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input.\n", MIC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_PIN %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_adc(void) {
    int value = 0;
    for (int i = 0; i < 10; i++) {
        value += gpioRead(MIC_PIN);
        gpioDelay(100);
    }
    return (value / 10) * (ADC_MAX / 10);
}

static void clap_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);

    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn on LED.\n");
    }
    gpioDelay(LED_ON_MS * 1000);
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED.\n");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool last_clap = false;
    uint32_t last_clap_tick = 0;

    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed.\n");
            break;
        }

        if (adc_value > CLAP_THRESHOLD) {
            uint32_t now = gpioTick();
            if (!last_clap || (now - last_clap_tick) > (DEBOUNCE_MS * 1000)) {
                clap_event();
                last_clap = true;
                last_clap_tick = now;
            }
        } else {
            last_clap = false;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

