#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_gpio_value(int gpio_fd) {
    if (ioctl(gpio_fd, GPIO_GET_LINE_VALUE, GPIO_LINE) < 0) {
        return -1;
    }
    return (int)ioctl(gpio_fd, GPIO_GET_LINE_VALUE, GPIO_LINE);
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int gpio_fd = open(GPIO_CHIP, O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_REQUEST_LINE, GPIO_LINE) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        close(gpio_fd);
        return 1;
    }

    printf("Feeder monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = read_gpio_value(gpio_fd);

        if (distance < 0) {
            fprintf(stderr, "Error reading GPIO value: %s. Retrying in 1 second.\n", strerror(errno));
            sleep(1);
            continue;
        }

        if (log_distance(distance) < 0) {
            fprintf(stderr, "Error logging distance. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    if (ioctl(gpio_fd, GPIO_RELEASE_LINE, GPIO_LINE) < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(errno));
    }

    if (close(gpio_fd) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
    }

    printf("Feeder monitoring stopped.\n");
    return 0;
}

