    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        moisture_level = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level\n");
        } else if (moisture_level > 1023) {
            fprintf(stderr, "Invalid moisture level: %d\n", moisture_level);
        } else {
            moisture_level = 100 - (moisture_level * 100 / 1023);

            if (moisture_level < MOISTURE_THRESHOLD && pump_state == 0) {
                if (control_pump(PUMP_GPIO, 1) == 0) {
                    pump_state = 1;
                    printf("Moisture level below threshold. Activating pump.\n");
                }
            } else if (moisture_level >= MOISTURE_THRESHOLD && pump_state == 1) {
                if (control_pump(PUMP_GPIO, 0) == 0) {
                    pump_state = 0;
                    printf("Moisture level above threshold. Deactivating pump.\n");
                }
            }

            if (log_data(log_file, moisture_level, pump_state) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    control_pump(PUMP_GPIO, 0);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

