#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define GPIO_CHIP_NAME   "gpiochip0"
#define CS_LINE_OFFSET   8   /* BCM 8  -> gpiochip0 line 8 */

#define ADC_CHANNEL      0
#define ADC_MAX          1023
#define ADC_VREF         3.3f
#define ADC_VDD          3.3f

#define LOG_FILE         "magnetic_log.txt"
#define SAMPLE_PERIOD_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    return raw;
}

static float raw_to_magnetic_field(int raw)
{
    float voltage = ((float)raw / (float)ADC_MAX) * ADC_VREF;
    /* DRV5055-A1: B ~ 0.5 mT at VOUT ~ 0.5 V, slope ~ 0.5 mT/V */
    return (voltage / ADC_VDD) * 0.5f;
}

static int log_data(FILE *fp, float magnetic_field)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld,%.2f\n", (long)now, magnetic_field) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() < 0)
        goto cleanup;

    if (spi_init(&spi_fd) < 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Magnetic field logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int raw = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
        } else {
            float field = raw_to_magnetic_field(raw);
            if (log_data(log_fp, field) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Magnetic Field: %.2f mT\n", field);
            }
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ms += 10)
            usleep(10000);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);
    if (spi_fd >= 0)
        close(spi_fd);
    return ret;
}

