/*
 * DRV5055VA Hall-effect sensor reader via MCP3008 ADC on Raspberry Pi Zero W.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   DRV5055VA OUT -> MCP3008 CH0
 *   LED anode    -> GPIO21 (via ~330 ohm resistor) -> GND
 *
 * Build: gcc -O2 -Wall -o magnetic_reader magnetic_reader.c -lpigpio -lrt
 * Run:   sudo ./magnetic_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                         */
#define SPI_SPEED        1000000    /* 1 MHz                                    */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words       */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0           */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC full-scale code               */

#define LED_GPIO         21         /* BCM GPIO21 (active-high LED)             */

#define THRESHOLD_MT     10.0f      /* Magnetic field threshold in millitesla  */
#define SAMPLE_PERIOD_US 100000     /* 100 ms between samples                   */

#define LOG_FILE         "magnetic_log.txt"

/* DRV5055VA transfer function: B = m * Vout + c
 *  Vout = 3.3 V,  Vref = 3.3 V  ->  m = 1 V/mT,  c = 0 V
 *  1 mT = 1.0 mT
 */
#define VREF             3.3f
#define MT_PER_V         (1.0f / VREF)   /* mT per volt                          */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static bool g_pigpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize(void);
static void cleanup(void);
static void signal_handler(int sig);
static int  read_adc_channel(int channel, int *out_value);
static float adc_to_magnetic_field(int adc_value);
static void log_data(float magnetic_field);
static void control_led(float magnetic_field);

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Graceful shutdown on Ctrl+C / SIGTERM */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = 0;
        if (read_adc_channel(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s.\n");
            gpioDelay(1000000);
            continue;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);
        log_data(magnetic_field);
        control_led(magnetic_field);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    /* --- pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    g_pigpio_inited = true;

    /* --- SPI bus (MCP3008 on SPI0 CE0) --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): pigpio error %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        g_spi_handle = -1;
        return -1;
    }

    /* --- LED on BCM GPIO21 --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_GPIO);
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADC read ----------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, Mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_adc_channel(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "spiXfer failed: returned %d (pigpio error %d)\n",
                bytes, bytes);
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *out_value = raw;
    return 0;
}

/* ----------------------------- Conversion --------------------------------- */
static float adc_to_magnetic_field(int adc_value)
{
    return (float)adc_value * MT_PER_V;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_data(float magnetic_field)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Magnetic Field: %.2f mT\n", timestamp, magnetic_field);
    fclose(fp);
}

/* ----------------------------- LED control -------------------------------- */
static void control_led(float magnetic_field)
{
    int level = (magnetic_field > THRESHOLD_MT) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", LED_GPIO, level);
    }
}

