    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (moisture_level >= 0) {
        fprintf(fp, "%s %d\n", timestamp, moisture_level);
    } else {
        fprintf(fp, "%s -1\n", timestamp);
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

