    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(ADC_CHANNEL);

        if (moisture_level >= 0) {
            printf("Moisture level: %d\n", moisture_level);
        } else {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        }

        log_data(moisture_level);

        if (running) {
            sleep(SAMPLE_INTERVAL);
        }
    }

    printf("\nCleaning up...\n");

    if (spi_handle >= 0) {
        if (spiClose(spi_handle) != 0) {
            fprintf(stderr, "Warning: spiClose failed\n");
        }
        spi_handle = -1;
    }

    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

