#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17

#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define VREF            5.0
#define SENSOR_MV_PER_A 100.0

#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void)
{
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.flags = 0;
    req.consumer_label = "mlx91209";
    req.request_type = 1; /* output */

    struct gpiohandle_config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.flags = 0;
    cfg.channels = (unsigned char[]) { GPIO_LINE };
    cfg.values  = (unsigned char[]) { 1 };

    if (ioctl(fd, GPIO_GET_LINE_COUNT, NULL) < 0) {
        fprintf(stderr, "GPIO_GET_LINE_COUNT: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_STATUS, NULL) < 0) {
        fprintf(stderr, "GPIO_GET_LINE_STATUS: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_INFO, NULL) < 0) {
        fprintf(stderr, "GPIO_GET_LINE_INFO: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_REQUEST, &req) < 0) {
        fprintf(stderr, "GPIO_REQUEST: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_current(int adc_value)
{
    return (adc_value / (double)ADC_MAX) * VREF * 1000.0 / SENSOR_MV_PER_A;
}

static int log_data(FILE *fp, double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.4f\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    int gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MLX91209 current logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
        } else {
            double current = adc_to_current(adc);
            if (log_data(g_log_fp, current) < 0) {
                fprintf(stderr, "Logging failed.\n");
            }
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

