#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static volatile sig_atomic_t running = 1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;
    spi_tx_buf[1] = (0x08 | channel) << 4;
    spi_tx_buf[2] = 0x00;

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed: %d\n", spi_handle);
        return -1;
    }

    int result = spiXfer(spi_handle, (char *)spi_tx_buf, (char *)spi_rx_buf, 3);

    spiClose(spi_handle);

    if (result != 3) {
        fprintf(stderr, "Error: spiXfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
