/*
 * Raspberry Pi 4 Model B - HC-SR501 PIR Motion-triggered Camera
 *
 * Hardware:
 *   - HC-SR501 PIR sensor
 *     VCC  -> 5V (Pin 2 or 4)
 *     GND  -> GND (Pin 6)
 *     OUT  -> GPIO17 (Pin 11, BCM 17)
 *
 * Software:
 *   - libcamera (Raspberry Pi OS Bookworm)
 *   - syslog for logging
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o security_cam security_cam.c
 *
 * Run:
 *   sudo ./security_cam
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <sys/sysmacros.h>

#define PIR_GPIO_PIN        17
#define DEBOUNCE_DELAY_MS   200
#define POLL_INTERVAL_MS    50
#define CAPTURE_DIR         "/home/pi/security_cam"
#define LOG_FILE            "/var/log/security_cam.log"
#define MAX_CMD_LEN         512
#define MAX_PATH_LEN        512

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(int priority, const char *message)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

/* ------------------------------------------------------------------ */
/* Filesystem helpers                                                  */
/* ------------------------------------------------------------------ */
static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat('%s') failed: %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) == -1) {
        syslog(LOG_ERR, "mkdir('%s') failed: %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* libcamera capture via fork/exec                                     */
/* ------------------------------------------------------------------ */
static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid == -1) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child process */
        execlp("libcamera-still", "libcamera-still",
               "-o", (char *)filename,
               "--nopreview", "--timeout", "2000",
               (char *)NULL);
        /* If exec returns, it failed */
        syslog(LOG_ERR, "execlp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }

    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) == -1) {
        if (errno == EINTR) {
            if (!g_running)
                break;
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still exited with status %d",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (ensure_directory(CAPTURE_DIR) != 0)
        return EXIT_FAILURE;

    /* Ensure log file exists so syslog() can append */
    FILE *log_check = fopen(LOG_FILE, "a");
    if (!log_check) {
        syslog(LOG_ERR, "Cannot touch log file '%s': %s",
               LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }
    fclose(log_check);

    /* Open log file for local logging */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        syslog(LOG_ERR, "Cannot open log file '%s': %s",
               LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Write startup banner to log file */
    fprintf(log_fp, "--- security_cam starting ---\n");
    fflush(log_fp);

    log_message(LOG_INFO, "security_cam starting");

    /* Read initial PIR state */
    int pir_state = gpioRead(PIR_GPIO_PIN);
    if (pir_state < 0) {
        log_message(LOG_ERR, "gpioRead failed on GPIO17");
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Initial PIR state: %d", pir_state);

    /* Main polling loop */
    while (g_running) {
        int current_state = gpioRead(PIR_GPIO_PIN);
        if (current_state < 0) {
            log_message(LOG_ERR, "gpioRead failed on GPIO17");
            break;
        }

        if (current_state != pir_state) {
            /* Debounce: wait, then re-read */
            usleep(DEBOUNCE_DELAY_MS * 1000);
            int confirmed = gpioRead(PIR_GPIO_PIN);
            if (confirmed < 0) {
                log_message(LOG_ERR, "gpioRead failed on GPIO17 during debounce");
                pir_state = current_state;
                continue;
            }

            if (confirmed == current_state) {
                pir_state = current_state;

                /* Build timestamped filename */
                time_t rawtime = time(NULL);
                if (rawtime == (time_t)-1) {
                    log_message(LOG_ERR, "time() failed: %s", strerror(errno));
                    continue;
                }

                struct tm timeinfo;
                if (localtime_r(&rawtime, &timeinfo) == NULL) {
                    log_message(LOG_ERR, "localtime_r failed");
                    continue;
                }

                char timestamp[32];
                if (strftime(timestamp, sizeof(timestamp),
                             "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
                    log_message(LOG_ERR, "strftime failed");
                    continue;
                }

                char filename[MAX_PATH_LEN];
                if (snprintf(filename, sizeof(filename),
                             "%s/motion_%s.jpg",
                             CAPTURE_DIR, timestamp) >= (int)sizeof(filename)) {
                    log_message(LOG_ERR, "Filename too long");
                    continue;
                }

                /* Build command */
                char command[MAX_CMD_LEN];
                if (snprintf(command, sizeof(command),
                             "libcamera-still -o %s --nopreview --timeout 2000",
                             filename) >= (int)sizeof(command)) {
                    log_message(LOG_ERR, "Command too long");
                    continue;
                }

                /* Log capture request */
                char log_buf[MAX_PATH_LEN + 64];
                snprintf(log_buf, sizeof(log_buf),
                         "Motion detected on GPIO17. Capturing %s",
                         filename);
                fprintf(log_fp, "%s\n", log_buf);
                fflush(log_fp);
                syslog(LOG_INFO, "%s", log_buf);

                /* Execute capture */
                if (capture_image(filename) == 0) {
                    fprintf(log_fp, "Capture successful: %s\n", filename);
                    fflush(log_fp);
                    syslog(LOG_INFO, "Capture successful: %s", filename);
                } else {
                    fprintf(log_fp, "Capture failed: %s\n", filename);
                    fflush(log_fp);
                    syslog(LOG_ERR, "Capture failed: %s", filename);
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    log_message(LOG_INFO, "security_cam stopping");
    fclose(log_fp);

    return EXIT_SUCCESS;
}

