#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define MAX_BUFFERS 4
#define FRAME_SIZE 640 * 480 * 3
#define MAP_SIZE (FRAME_SIZE * MAX_BUFFERS)

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    buffer_t *buffers = NULL;
    int n_buffers = 0;
    int fd_val = -1;

    fd_val = open(VIDEO_DEVICE, O_RDWR);
    if (fd_val < 0) {
        perror("Error opening video device");
        return -1;
    }

    if (xioctl(fd_val, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        goto fail_close;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd_val, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        goto fail_close;
    }

    memset(&req, 0, sizeof(req));
    req.count = MAX_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd_val, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        goto fail_close;
    }

    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("Error allocating memory for buffers");
        goto fail_close;
    }

    n_buffers = req.count;

    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd_val, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            goto fail_free;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd_val, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            goto fail_free;
        }
    }

    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd_val, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            goto fail_unmap;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd_val, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        goto fail_unmap;
    }

    *fd = fd_val;
    return 0;

fail_unmap:
    for (int i = 0; i < n_buffers; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }
fail_free:
    free(buffers);
fail_close:
    close(fd_val);
    return -1;
}

static void uninit_camera(int fd) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
    }
}

static void log_timestamp(FILE *log_file) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        return;
    }
    fprintf(log_file, "%ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
    fflush(log_file);
}

int main(void) {
    int fd = -1;
    FILE *log_file = NULL;
    buffer_t *buffers = NULL;
    int n_buffers = 0;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (init_camera(&fd) < 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        goto fail_camera;
    }

    buffers = calloc(MAX_BUFFERS, sizeof(buffer_t));
    if (!buffers) {
        perror("Error allocating memory for buffer array");
        goto fail_log;
    }

    n_buffers = MAX_BUFFERS;

    while (!stop_flag) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error in select()");
            break;
        } else if (r == 0) {
            fprintf(stderr, "Error: select() timeout\n");
            break;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("Error dequeuing buffer");
            break;
        }

        log_timestamp(log_file);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }
    }

    ret = 0;

    if (buffers) {
        for (int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
    }

fail_log:
    if (log_file) {
        fclose(log_file);
    }

fail_camera:
    uninit_camera(fd);

    return ret;
}

