static int send_udp_packet(int sockfd, const struct sockaddr_in *addr, int frame_idx, int frag_idx, int total_frags, const unsigned char *data, int data_len) {
    int sent = 0;
    while (sent < data_len) {
        int remaining = data_len - sent;
        int to_send = (remaining > MAX_DGRAM_SIZE) ? MAX_DGRAM_SIZE : remaining;
        ssize_t bytes = sendto(sockfd, data + sent, to_send, 0, (const struct sockaddr *)addr, sizeof(*addr));
        if (bytes < 0) {
            perror("sendto");
            return -1;
        }
        sent += bytes;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <frame_index>\n", argv[0]);
        return 1;
    }

    int frame_idx = atoi(argv[1]);
    if (frame_idx < 0) {
        fprintf(stderr, "Invalid frame index\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(TARGET_PORT);
    if (inet_pton(AF_INET, TARGET_IP, &addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return 1;
    }

    buffer_t buffers[NUM_BUFFERS];
    int fd = init_camera(buffers, NUM_BUFFERS);
    if (fd < 0) {
        close(sockfd);
        return 1;
    }

    printf("Starting video stream to %s:%d (frame %d)\n", TARGET_IP, TARGET_PORT, frame_idx);

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            break;
        }

        int data_len = buf.bytesused;
        if (data_len > MAX_DGRAM_SIZE) {
            fprintf(stderr, "Frame too large: %d bytes\n", data_len);
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        int total_frags = 1;
        int frag_idx = 0;
        unsigned char *fragments[MAX_DGRAM_SIZE / 1024];
        int num_fragments = 0;
        int fragment_size = data_len;

        while (data_len > 0 && running) {
            int to_copy = (data_len > fragment_size) ? fragment_size : data_len;
            fragments[num_fragments] = malloc(to_copy);
            if (fragments[num_fragments] == NULL) {
                perror("malloc");
                xioctl(fd, VIDIOC_QBUF, &buf);
                goto cleanup;
            }
            memcpy(fragments[num_fragments], buf.data, to_copy);
            num_fragments++;
            data_len -= to_copy;
            if (data_len > 0) {
                fragment_size = (data_len > fragment_size) ? fragment_size : data_len;
            }
        }

        for (int i = 0; i < num_fragments; i++) {
            if (send_udp_packet(sockfd, &addr, frame_idx, i, total_frags, fragments[i], fragment_size) < 0) {
                free(fragments[i]);
                goto cleanup;
            }
            free(fragments[i]);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

cleanup:
    uninit_camera(fd, buffers, NUM_BUFFERS);
    close(sockfd);
    printf("Video stream stopped.\n");
    return 0;
}

