#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffers[NUM_BUFFERS];
    size_t buf_sizes[NUM_BUFFERS];
    int n_buffers = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 192;
    fmt.fmt.pix.height = 108;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    buffers = malloc(req.count * sizeof(unsigned char *));
    if (!buffers) {
        perror("malloc");
        goto cleanup;
    }

    buf_sizes = malloc(req.count * sizeof(size_t));
    if (!buf_sizes) {
        perror("malloc");
        goto cleanup;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buf_sizes[n_buffers] = buf.length;
        buffers[n_buffers] = malloc(buf.length);
        if (!buffers[n_buffers]) {
            perror("malloc");
            goto cleanup;
        }
    }

    for (int i = 0; i < n_buffers; i++) {
        if (mmap(&((unsigned char *)buffers[i]), buf_sizes[i], PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.offset) == MAP_FAILED) {
            perror("mmap");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused <= 0) {
        fprintf(stderr, "No valid frame data in buffer\n");
        goto cleanup;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen(" IMAGE_FILE ")");
        goto cleanup;
    }

    size_t written = fwrite(buffers[buf.index], 1, buf.bytesused, fp);
    if (written != (size_t)buf.bytesused) {
        fprintf(stderr, "Short write to %s\n", IMAGE_FILE);
        goto cleanup;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        goto cleanup;
    }

    printf("Saved %zu bytes to %s\n", written, IMAGE_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i]) {
                munmap(buffers[i], buf_sizes[i]);
            }
        }
        close(fd);
    }
    free(buffers);
    free(buf_sizes);
    return ret;
}

