/*
 * Pan-tilt camera mount controller for Raspberry Pi.
 *
 * Servos:  pan  -> GPIO4  (BCM)
 *          tilt -> GPIO5  (BCM)
 * Buttons: tilt-up   -> GPIO6 (BCM)  active-low
 *          tilt-down -> GPIO7 (BCM)  active-low
 *          pan-left  -> GPIO8 (BCM)  active-low
 *          pan-right -> GPIO9 (BCM)  active-low
 *
 * PWM:  50 Hz software PWM on the GPIO software PWM bus.
 *       Pulse width: 1-2 ms  -> duty 50-100 / 1000.
 *       Period: 20 ms (50 Hz).
 *
 * Build: gcc -O2 -Wall -Wextra -o pan_tilt pan_tilt.c -lpigpio -lrt
 * Run:   sudo ./pan_tilt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define TILT_UP_PIN        6
#define TILT_DOWN_PIN      7
#define PAN_LEFT_PIN       8
#define PAN_RIGHT_PIN      9

#define MIN_PULSE_WIDTH    1000   /* 1 ms  -> 50 Hz */
#define MAX_PULSE_WIDTH    2000   /* 2 ms  -> 50 Hz */
#define MID_PULSE_WIDTH    1500   /* 1.5 ms -> 66.67 Hz (not used) */
#define SERVO_RANGE        1000   /* 0-1000 -> 0-2 ms */
#define MIN_POSITION       25
#define MAX_POSITION       125
#define POSITION_STEP      5
#define POLL_DELAY_US      50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Map a value in [min, max] to a pulse width in [MIN_PULSE_WIDTH, MAX_PULSE_WIDTH].
 * Returns -1 on invalid input.
 */
static int position_to_pulse(int position)
{
    if (position < MIN_POSITION || position > MAX_POSITION)
        return -1;
    return MIN_PULSE_WIDTH + (position - MIN_POSITION) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_POSITION - MIN_POSITION);
}

/*
 * Map a pulse width to a position in [MIN_POSITION, MAX_POSITION].
 * Returns -1 on invalid pulse width.
 */
static int pulse_to_position(int pulse)
{
    if (pulse < MIN_PULSE_WIDTH || pulse > MAX_PULSE_WIDTH)
        return -1;
    return MIN_POSITION + (pulse - MIN_PULSE_WIDTH) * (MAX_POSITION - MIN_POSITION) / (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);
}

/*
 * Software PWM: generate a single 50 Hz period on the given GPIO pin.
 * pulse_us: pulse width in microseconds (1-2000 us).
 * Returns 0 on success, -1 on failure.
 */
static int software_pwm(int pin, int pulse_us)
{
    if (pulse_us < 0 || pulse_us > 2000000)
        return -1;

    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
        return -1;
    }

    gpioDelay(pulse_us);

    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
        return -1;
    }

    gpioDelay(20000); /* 20 ms remainder of 20 ms period */
    return 0;
}

/*
 * Set a servo to the given position (0-100).
 * Returns 0 on success, -1 on failure.
 */
static int set_servo(int pin, int position)
{
    int pulse = position_to_pulse(position);
    if (pulse < 0) {
        fprintf(stderr, "Invalid position %d for pin %d\n", position, pin);
        return -1;
    }

    if (software_pwm(pin, pulse) != 0)
        return -1;

    return 0;
}

/*
 * Adjust the given axis by step while clamping to [MIN_POSITION, MAX_POSITION].
 * Returns 0 on success, -1 on failure.
 */
static int adjust_axis(int *position, int step)
{
    *position += step;
    if (*position < MIN_POSITION)
        *position = MIN_POSITION;
    else if (*position > MAX_POSITION)
        *position = MAX_POSITION;
    return 0;
}

/*
 * Read a button with internal pull-up. Returns 0 (pressed), 1 (released), or -1 on error.
 */
static int read_button(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return level;
}

int main(void)
{
    int pan_position = 75;
    int tilt_position = 75;
    int pan_step = 0;
    int tilt_step = 0;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) != 0 ||
        gpioSetMode(TILT_DOWN_PIN, PI_INPUT) != 0 ||
        gpioSetMode(PAN_LEFT_PIN, PI_INPUT) != 0 ||
        gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-ups on button GPIOs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize servos to mid-position --- */
    if (set_servo(PAN_SERVO_PIN, pan_position) != 0 ||
        set_servo(TILT_SERVO_PIN, tilt_position) != 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt controller ready. Press Ctrl+C to exit.\n");

    /* --- Main control loop --- */
    while (g_running) {
        /* --- Tilt axis --- */
        int tilt_up  = read_button(TILT_UP_PIN);
        int tilt_down = read_button(TILT_DOWN_PIN);

        if (tilt_up == 0) {
            if (adjust_axis(&tilt_position, -tilt_step) == 0)
                tilt_step = 5;
        } else if (tilt_up == 1 && tilt_down == 0) {
            if (adjust_axis(&tilt_position, tilt_step) == 0)
                tilt_step = 5;
        } else if (tilt_down == 0) {
            if (adjust_axis(&tilt_position, tilt_step) == 0)
                tilt_step = 5;
        } else if (tilt_down == 1) {
            if (adjust_axis(&tilt_position, -tilt_step) == 0)
                tilt_step = 5;
        } else {
            tilt_step = 5;
        }

        if (set_servo(TILT_SERVO_PIN, tilt_position) != 0) {
            fprintf(stderr, "Failed to set tilt servo\n");
            break;
        }

        /* --- Pan axis --- */
        int pan_left  = read_button(PAN_LEFT_PIN);
        int pan_right = read_button(PAN_RIGHT_PIN);

        if (pan_left == 0) {
            if (adjust_axis(&pan_position, -pan_step) == 0)
                pan_step = 5;
        } else if (pan_left == 1 && pan_right == 0) {
            if (adjust_axis(&pan_position, pan_step) == 0)
                pan_step = 5;
        } else if (pan_right == 0) {
            if (adjust_axis(&pan_position, pan_step) == 0)
                pan_step = 5;
        } else if (pan_right == 1) {
            if (adjust_axis(&pan_position, -pan_step) == 0)
                pan_step = 5;
        } else {
            pan_step = 5;
        }

        if (set_servo(PAN_SERVO_PIN, pan_position) != 0) {
            fprintf(stderr, "Failed to set pan servo\n");
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    set_servo(PAN_SERVO_PIN, 75);
    set_servo(TILT_SERVO_PIN, 75);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

