#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <stdint.h>

#define VIDEO_DEVICE "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define JPEG_QUALITY 75
#define NUM_BUFFERS 4

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    int fd_val = open(VIDEO_DEVICE, O_RDWR);
    if (fd_val < 0) {
        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }
    *fd = fd_val;

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(*fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(*fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Error: device does not support YUYV format\n");
        close(*fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    if (req.count < 2) {
        fprintf(stderr, "Error: insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (unsigned int i = 0; i < req.count; i++) {
        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %u: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }
        void *map = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (map == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }
        buf.m.map = map;
        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %u: %s\n", i, strerror(errno));
            munmap(buf.m.map, buf.length);
            close(*fd);
            return -1;
        }
    }
    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, unsigned char **frame, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }
    *frame = (unsigned char *)buf.m.map;
    *frame_size = buf.bytesused;
    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int uninit_camera(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error unqueuing buffer %u: %s\n", i, strerror(errno));
            return -1;
        }
    }
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buf.m.map, buf.length) < 0) {
            fprintf(stderr, "Error unmapping buffer %u: %s\n", i, strerror(errno));
            return -1;
        }
    }
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing camera: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    if (width * height * 3 != (size_t)(width * height * 2)) {
        fprintf(stderr, "Error: insufficient buffer for RGB conversion\n");
        return -1;
    }
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j += 2) {
            int idx = (i * width + j) * 2;
            int y1 = yuyv[idx];
            int u = yuyv[idx + 1];
            int y2 = yuyv[idx + 2];
            int v = yuyv[idx + 3];
            int r1 = y1 + (int)(133.0 * (v - 128));
            int g1 = y1 - (int)(77.0 * (u - 128));
            int b1 = y1 + (int)((-37.0) * (u - 128));
            int r2 = y2 + (int)(133.0 * (v - 128));
            int g2 = y2 - (int)(77.0 * (u - 128));
            int b2 = y2 + (int)((-37.0) * (u - 128));
            rgb[(i * width + j) * 3 + 0] = (unsigned char)(r1 < 0 ? 0 : (r1 > 255 ? 255 : r1));
            rgb[(i * width + j) * 3 + 1] = (unsigned char)(g1 < 0 ? 0 : (g1 > 255 ? 255 : g1));
            rgb[(i * width + j) * 3 + 2] = (unsigned char)(b1 < 0 ? 0 : (b1 > 255 ? 255 : b1));
            if (j + 1 < width) {
                rgb[(i * width + (j + 1)) * 3 + 0] = (unsigned char)(r2 < 0 ? 0 : (r2 > 255 ? 255 : r2));
                rgb[(i * width + (j + 1)) * 3 + 1] = (unsigned char)(g2 < 0 ? 0 : (g2 > 255 ? 255 : g2));
                rgb[(i * width + (j + 1)) * 3 + 2] = (unsigned char)(b2 < 0 ? 0 : (b2 > 255 ? 255 : b2));
            }
        }
    }
    return 0;
}

static int blur_filter(unsigned char *rgb, int width, int height) {
    int kernel_size = 5;
    int kernel_radius = kernel_size / 2;
    unsigned char *kernel = (unsigned char *)malloc((kernel_size * kernel_size) * sizeof(unsigned char));
    if (!kernel) {
        fprintf(stderr, "Error allocating kernel memory\n");
        return -1;
    }
    for (int i = 0; i < kernel_size; i++) {
        for (int j = 0; j < kernel_size; j++) {
            kernel[i * kernel_size + j] = 1 / (kernel_size * kernel_size);
        }
    }
    unsigned char *temp = (unsigned char *)malloc((width * height * 3) * sizeof(unsigned char));
    if (!temp) {
        fprintf(stderr, "Error allocating temp memory\n");
        free(kernel);
        return -1;
    }
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int k = -kernel_radius; k <= kernel_radius; k++) {
                for (int l = -kernel_radius; l <= kernel_radius; l++) {
                    int x = j + l;
                    int y = i + k;
                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        int idx = (y * width + x) * 3;
                        sum_r += rgb[idx] * kernel[kernel_size + l];
                        sum_g += rgb[idx + 1] * kernel[kernel_size + l];
                        sum_b += rgb[idx + 2] * kernel[kernel_size + l];
                    }
                }
            }
            int idx = (i * width + j) * 3;
            temp[idx] = (unsigned char)sum_r;
            temp[idx + 1] = (unsigned char)sum_g;
            temp[idx + 2] = (unsigned char)sum_b;
        }
    }
    memcpy(rgb, temp, (width * height * 3) * sizeof(unsigned char));
    free(temp);
    free(kernel);
    return 0;
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }
    unsigned char quality = JPEG_QUALITY;
    if (jpeg_set_defaults(fp) != 0) {
        fprintf(stderr, "Error setting JPEG defaults\n");
        fclose(fp);
        return -1;
    }
    jpeg_set_quality(fp, quality, TRUE);
    jpeg_stdio_header(fp, &width, &height);
    jpeg_write_raw_data(fp, rgb, width * height * 3);
    jpeg_finish_output(fp);
    fclose(fp);
    return 0;
}

static int generate_filename(char *filename, size_t size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    if (strftime(filename, size, "capture_%Y%m%d_%H%M%S.jpg", timeinfo) == 0) {
        fprintf(stderr, "Error formatting filename\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd;
    if (init_camera(&fd) < 0) {
        return 1;
    }

    if (start_streaming(fd) < 0) {
        uninit_camera(fd);
        return 1;
    }

    unsigned char *frame = NULL;
    size_t frame_size = 0;
    unsigned char *rgb = NULL;
    char filename[64];

    while (g_running) {
        if (capture_frame(fd, &frame, &frame_size) == 0) {
            rgb = (unsigned char *)malloc((size_t)(frame_size * 3));
            if (!rgb) {
                fprintf(stderr, "Error allocating RGB buffer\n");
                break;
            }
            if (yuyv_to_rgb24(frame, rgb, CAPTURE_WIDTH, CAPTURE_HEIGHT) < 0) {
                free(rgb);
                break;
            }
            if (blur_filter(rgb, CAPTURE_WIDTH, CAPTURE_HEIGHT) < 0) {
                free(rgb);
                break;
            }
            if (generate_filename(filename, sizeof(filename)) < 0) {
                free(rgb);
                break;
            }
            if (encode_jpeg(rgb, CAPTURE_WIDTH, CAPTURE_HEIGHT, filename) < 0) {
                free(rgb);
                break;
            }
            printf("Saved %s\n", filename);
            free(rgb);
        } else if (errno != EINTR) {
            fprintf(stderr, "Error capturing frame: %s\n", strerror(errno));
            break;
        }
    }

    if (stop_streaming(fd) < 0) {
        uninit_camera(fd);
        return 1;
    }
    uninit_camera(fd);
    return 0;
}

