/*
 * v4l2-camera-summary.c
 *
 * Prints a human-readable summary of a V4L2 camera's capabilities:
 *   - Supported frame sizes (width x height)
 *   - Supported frame intervals (frames per second) for each size
 *   - Autofocus support (V4L2_CID_FOCUS_AUTO)
 *
 * Build:  gcc -O2 -Wall -Wextra -o v4l2-camera-summary v4l2-camera-summary.c
 * Run:    ./v4l2-camera-summary /dev/video0
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define MAX_FRAME_SIZES 64
#define MAX_FRAME_INTERVALS 16

/* ------------------------------------------------------------------ */
/* Helper: print a human-readable frame size string                    */
/* ------------------------------------------------------------------ */
static void print_frame_size(const struct v4l2_frmsize_discrete *f)
{
    printf("%ux%u\n", f->width, f->height);
}

/* ------------------------------------------------------------------ */
/* Helper: print a human-readable frame interval string                */
/* ------------------------------------------------------------------ */
static void print_frame_interval(const struct v4l2_frmival_discrete *f)
{
    printf("  %u.%02u fps\n", f->numerator, f->denominator);
