/*
 * pan_tilt_servo.c — Raspberry Pi pan-tilt servo control with button input.
 *
 * Build:  gcc -O2 -Wall -Wextra -o pan_tilt_servo pan_tilt_servo.c -lpigpio -lrt
 * Run:    sudo ./pan_tilt_servo
 *
 * Wiring (BCM numbering):
 *   GPIO4  — pan servo signal (hardware PWM0)
 *   GPIO5  — tilt servo signal (hardware PWM1)
 *   GPIO6  — UP button to GND (internal pull-up)
 *   GPIO7  — DOWN button to GND (internal pull-up)
 *   GPIO8  — LEFT button to GND (internal pull-up)
 *   GPIO9  — RIGHT button to GND (internal pull-up)
 *
 * Servo: 50 Hz, 1000–2000 µs pulse, center = 1500 µs.
 * Each iteration: pulse += 10 µs, delay 50 ms.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE  1000   /* µs */
#define SERVO_MAX_PULSE  2000   /* µs */
#define SERVO_CENTER     1500   /* µs */
#define PULSE_STEP       10     /* µs per iteration */
#define LOOP_DELAY_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int set_servo_pulse(int pin, int pulse_us)
{
    if (pulse_us < SERVO_MIN_PULSE) pulse_us = SERVO_MIN_PULSE;
    if (pulse_us > SERVO_MAX_PULSE) pulse_us = SERVO_MAX_PULSE;
    return gpioServo(pin, pulse_us);
}

static void center_servo(int pin)
{
    if (gpioServo(pin, SERVO_CENTER) != 0)
        fprintf(stderr, "Warning: gpioServo(%d, %d) failed\n",
                pin, SERVO_CENTER);
}

/* ------------------------------------------------------------------ */
/* Button helpers                                                      */
/* ------------------------------------------------------------------ */
static int is_button_pressed(int pin)
{
    return (gpioRead(pin) == 0);   /* active-low */
}

static void handle_button(int up, int down, int left, int right,
                          int *pan, int *tilt)
{
    if (up && !down)  *pan += PULSE_STEP;
    if (down && !up)  *pan -= PULSE_STEP;
    if (left && !right) *tilt += PULSE_STEP;
    if (right && !left) *tilt -= PULSE_STEP;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM on both servo pins */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pan_pulse = SERVO_CENTER;
    int tilt_pulse = SERVO_CENTER;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-up */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Error: failed to set button pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0)
    {
        fprintf(stderr, "Error: failed to set pull-up resistors.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pins as hardware PWM outputs */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Error: failed to set servo pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    center_servo(PAN_SERVO_PIN);
    center_servo(TILT_SERVO_PIN);

    install_signal_handlers();

    printf("Pan-tilt servo control started.\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  UP  : GPIO%d\n", UP_BUTTON_PIN);
    printf("  DOWN: GPIO%d\n", DOWN_BUTTON_PIN);
    printf("  LEFT : GPIO%d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("  Center = %d µs. Press Ctrl+C to exit.\n", SERVO_CENTER);
    fflush(stdout);

    while (g_running) {
        int up = is_button_pressed(UP_BUTTON_PIN);
        int down = is_button_pressed(DOWN_BUTTON_PIN);
        int left = is_button_pressed(LEFT_BUTTON_PIN);
        int right = is_button_pressed(RIGHT_BUTTON_PIN);

        handle_button(up, down, left, right, &pan_pulse, &tilt_pulse);

        if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) != 0)
            fprintf(stderr, "Warning: gpioServo(pan) failed\n");
        if (set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) != 0)
            fprintf(stderr, "Warning: gpioServo(tilt) failed\n");

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

