#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <gpiod.h>

#define PIR_PIN 17
#define DEBOUNCE_MS 50
#define LOG_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define CAPTURE_CMD \
    "avconv -o %s -w 640 -h 480 -q 85 -t 2 -nopreview -i /dev/video0 %s"
#define MAX_FILENAME_LEN 128
#define MAX_CMD_LEN 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[MAX_CMD_LEN];
    int ret = snprintf(command, sizeof(command), CAPTURE_CMD, filename, filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        perror("Error executing capture command");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: capture command failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int generate_filename(char *filename, size_t size) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    int millis = tm.tm_sec * 1000 + tm.tm_min * 60000 + tm.tm_hour * 3600000;
    return snprintf(filename, size, "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, millis);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handlers");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening gpiochip0");
        log_message("Error opening gpiochip0");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("Error getting GPIO line 17");
        log_message("Error getting GPIO line 17");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir_sensor") < 0) {
        perror("Error requesting falling edge events on GPIO 17");
        log_message("Error requesting falling edge events on GPIO 17");
        goto cleanup;
    }

    printf("Motion detection started on GPIO 17. Press Ctrl+C to exit.\n");
    log_message("Motion detection started");

    while (running) {
        struct timespec ts = {1, 0}; /* 1 second timeout for event polling */
        int ev = gpiod_line_event_wait(pir_line, &ts);

        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("Error waiting for GPIO event");
            log_message("Error waiting for GPIO event");
            break;
        }
        if (ev == 0) continue; /* timeout */

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("Error reading GPIO event");
            log_message("Error reading GPIO event");
            break;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        usleep(DEBOUNCE_MS * 1000);
        if (!running) break;

        if (gpiod_line_get_value(pir_line) != 0) {
            continue;
        }

        char filename[MAX_FILENAME_LEN];
        if (generate_filename(filename, sizeof(filename)) < 0) {
            fprintf(stderr, "Error: filename generation failed\n");
            log_message("Error: filename generation failed");
            continue;
        }

        char filepath[MAX_FILENAME_LEN];
        snprintf(filepath, sizeof(filepath), "%s/%s", LOG_DIR, filename);

        if (capture_image(filepath) == 0) {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Motion detected, image saved: %s", filepath);
            printf("%s\n", log_msg);
            log_message(log_msg);
        } else {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Motion detected, but capture failed: %s", filepath);
            fprintf(stderr, "%s\n", log_msg);
            log_message(log_msg);
        }
    }

    ret = 0;

cleanup:
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    printf("Exiting.\n");
    return ret;
}

