    if (written != (size_t)(CROP_WIDTH * CROP_HEIGHT * 2)) {
        perror("fwrite");
        free(dst);
        fclose(fp);
        goto cleanup;
    }

    if (fclose(fp) == EOF) {
        perror("fclose");
        free(dst);
        goto cleanup;
    }

    printf("Cropped %s written (%d x %d)\n", FILENAME, CROP_WIDTH, CROP_HEIGHT);
    ret = EXIT_SUCCESS;

