    if (fp) fclose(fp);
    if (buffer && buffer != MAP_FAILED) munmap(buffer, buf_size);
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    free(dst);
    return ret;
}

