/*
 * Raspberry Pi 4 Model B — Dual SG90 Servo Control via GPIO Hardware PWM
 *
 * Reads arrow-key presses and 'q' from stdin.  Drives two SG90 servos:
 *   - Pan  servo on GPIO17 (BCM)
 *   - Tilt servo on GPIO18 (BCM)
 *   - 50 Hz hardware PWM, 20 ms period (50000 us)
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_control servo_control.c -lpigpio -lrt
 * Run:    sudo ./servo_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      17
#define TILT_SERVO_PIN     18

#define SERVO_MIN_PULSE_US 1000   /* SG90 0°   -> 1000 us */
#define SERVO_MAX_PULSE_US 2000   /* SG90 180° -> 2000 us */
#define SERVO_NEUTRAL_US   1500   /* 90° center */

#define PWM_FREQUENCY      50     /* Hz */
#define PWM_RANGE          100000 /* 100 counts across 0–2000 us */

#define STEP_DEGREES       5
#define STEP_DELAY_US      100000 /* 100 ms between commands */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_us(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return SERVO_MIN_PULSE_US +
           (int)((long)angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / 180);
}

static int set_servo_angle(int pin, int angle)
{
    int pulse = angle_to_pulse_us(angle);
    if (pulse < 0 || pulse > 2000) {
        fprintf(stderr, "Error: angle %d out of range (0–180) on GPIO %d\n",
                angle, pin);
        return -1;
    }

    if (gpioPWM(pin, pulse) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d (pulse %d us)\n",
                pin, pulse);
        return -1;
    }
    return 0;
}

static int set_servo_neutral(int pin)
{
    return set_servo_angle(pin, 90);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on both pins --- */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set PWM frequency and range --- */
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO %d\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO %d\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO %d\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO %d\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start at neutral --- */
    if (set_servo_neutral(PAN_SERVO_PIN) != 0 ||
        set_servo_neutral(TILT_SERVO_PIN) != 0) {
        fprintf(stderr, "Error: failed to set initial servo positions.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control ready.\n");
    printf("  Pan  servo: GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  Controls:  up/down arrow  -> tilt  (0–180)
 *          left/right arrow  -> pan   (0–180)
 *          'q'               -> quit\n");
    printf("Press 'q' or Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int c = getchar();

        if (c == 'q' || c == EOF) {
            printf("\nExiting...\n");
            break;
        }

        if (c == '\n' || c == '\r') {
            continue;
        }

        if (c == 'q') {
            break;
        }

        if (c == 'w') {
            if (set_servo_angle(TILT_SERVO_PIN, 180) == 0) {
                printf("Tilt -> 180°\n");
            }
        } else if (c == 's') {
            if (set_servo_angle(TILT_SERVO_PIN, 0) == 0) {
                printf("Tilt -> 0°\n");
            }
        } else if (c == 'a') {
            if (set_servo_angle(PAN_SERVO_PIN, 0) == 0) {
                printf("Pan -> 0°\n");
            }
        } else if (c == 'd') {
            if (set_servo_angle(PAN_SERVO_PIN, 180) == 0) {
                printf("Pan -> 180°\n");
            }
        } else {
            /* ignore other characters */
        }

        usleep(STEP_DELAY_US);
    }

    /* --- Cleanup --- */
    set_servo_neutral(PAN_SERVO_PIN);
    set_servo_neutral(TILT_SERVO_PIN);
    gpioTerminate();
    printf("Cleanup complete. Goodbye.\n");
    return EXIT_SUCCESS;
}

