#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define OLED_WIDTH  128
#define OLED_HEIGHT 64
#define OLED_ADDR   0x3C
#define I2C_BUS     "/dev/i2c-1"

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define CPU_USAGE_PATH "/proc/stat"

#define SSD1306_DISPLAYOFF 0xAE
#define SSD1306_SETDISPLAYCLOCKDIV 0xD5
#define SSD1306_SETMULTIPLEX 0xA8
#define SSD1306_SETDISPLAYOFFSET 0xD3
#define SSD1306_SETSTARTLINE 0x40
#define SSD1306_CHARGEPUMP 0x8D
#define SSD1306_MEMORYMODE 0x20
#define SSD1306_SEGREMAP 0xA0
#define SSD1306_COMSCANDEC 0xC8
#define SSD1306_SETCOMPINS 0xDA
#define SSD1306_SETCONTRAST 0x81
#define SSD1306_SETPRECHARGE 0xD9
#define SSD1306_SETVCOMDETECT 0xDB
#define SSD1306_DISPLAYALLON_RESUME 0xA4
#define SSD1306_NORMALDISPLAY 0xA6
#define SSD1306_DISPLAYON 0xAF
#define SSD1306_SETPIXELFORMAT 0x81
#define SSD1306_SETLEFTRIGHT 0xA0
#define SSD1306_PAGEADDR 0xB0
#define SSD1306_COLUMNADDR 0x21

#define SSD1306_PAGES 8
#define SSD1306_PAGESIZE 8

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int oled_init(int fd) {
    uint8_t init_cmds[] = {
        SSD1306_DISPLAYOFF,
        SSD1306_SETDISPLAYCLOCKDIV,
        0xF0,
        SSD1306_SETMULTIPLEX, OLED_HEIGHT - 1,
        SSD1306_SETDISPLAYOFFSET, 0,
        SSD1306_SETSTARTLINE | 0x00,
        SSD1306_CHARGEPUMP, 0x14,
        SSD1306_MEMORYMODE, 0x00,
        SSD1306_SEGREMAP | 0x01,
        SSD1306_COMSCANDEC,
        SSD1306_SETCOMPINS, 0x12,
        SSD1306_SETCONTRAST, 0x7F,
        SSD1306_SETPRECHARGE, 0xF2,
        SSD1306_SETVCOMDETECT, 0x40,
        SSD1306_DISPLAYALLON_RESUME,
        SSD1306_NORMALDISPLAY,
        SSD1306_DISPLAYON,
        SSD1306_SETPIXELFORMAT, 0x00,
        SSD1306_SETLEFTRIGHT, 0x00,
        SSD1306_PAGEADDR, 0x00, SSD1306_PAGES - 1,
        SSD1306_COLUMNADDR, 0x00, OLED_WIDTH - 1
    };
    return i2c_write(fd, init_cmds, sizeof(init_cmds));
}

static int oled_clear(int fd) {
    uint8_t buf[1 + OLED_WIDTH];
    buf[0] = 0x40;
    memset(&buf[1], 0x00, OLED_WIDTH);
    return i2c_write(fd, buf, sizeof(buf));
}

static int oled_set_cursor(int fd, int page, int col) {
    uint8_t buf[4];
    buf[0] = SSD1306_PAGEADDR | (page & 0x07);
    buf[1] = SSD1306_COLUMNADDR | (col & 0x0F);
    buf[2] = SSD1306_COLUMNADDR | ((col >> 4) & 0x0F);
    buf[3] = 0x00;
    return i2c_write(fd, buf, sizeof(buf));
}

static int oled_write_string(int fd, int page, int col, const char *str) {
    if (oled_set_cursor(fd, page, col) < 0) return -1;
    for (size_t i = 0; str[i] != '\0'; i++) {
        uint8_t c = (uint8_t)str[i];
        if (c < 32 || c > 126) c = '?';
        uint8_t buf[1 + 6];
        buf[0] = 0x40;
        buf[1] = 0x00;
        buf[2] = 0x00;
        buf[3] = 0x00;
        buf[4] = 0x00;
        buf[5] = (uint8_t)c;
        if (i2c_write(fd, buf, sizeof(buf)) < 0) return -1;
    }
    return 0;
}

static int oled_draw_image(int fd, int page, int col, const uint8_t *img, int w, int h) {
    if (oled_set_cursor(fd, page, col) < 0) return -1;
    size_t total = (size_t)w * h;
    uint8_t buf[1 + OLED_WIDTH];
    buf[0] = 0x40;
    for (size_t i = 0; i < total; i++) {
        buf[1 + i] = img[i];
    }
    if (i2c_write(fd, buf, total + 1) < 0) return -1;
    return 0;
}

static int read_cpu_temp(float *temp) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", CPU_TEMP_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int read_cpu_usage(int *total, int *idle, int *io, int *irq, int *soft) {
    FILE *fp = fopen(CPU_USAGE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", CPU_USAGE_PATH, strerror(errno));
        return -1;
    }
    int prev_idle, prev_total, prev_io, prev_irq, prev_soft;
    if (fscanf(fp, "%*s %d %d %d %d %d", &prev_idle, &prev_total, &prev_io, &prev_irq, &prev_soft) != 5) {
        fprintf(stderr, "Failed to parse CPU usage from %s\n", CPU_USAGE_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *total = prev_total;
    *idle = prev_idle;
    *io = prev_io;
    *irq = prev_irq;
    *soft = prev_soft;
    return 0;
}

static int calculate_cpu_usage(int *total, int *idle, int *io, int *irq, int *soft) {
    static int prev_total = 0, prev_idle = 0, prev_io = 0, prev_irq = 0, prev_soft = 0;
    if (*total == prev_total && *idle == prev_idle && *io == prev_io && *irq == prev_irq && *soft == prev_soft) return 0;
    prev_total = *total;
    prev_idle = *idle;
    prev_io = *io;
    prev_irq = *irq;
    prev_soft = *soft;
    int used = *total - *idle - *io - *irq - *soft;
    if (used < 0) used = 0;
    int total_cpu = *total;
    if (total_cpu < 0) total_cpu = 0;
    return (int)(((float)used / (float)total_cpu) * 100.0f + 0.5f);
}

static void render_data(int fd, float cpu_temp, int cpu_usage) {
    oled_clear(fd);
    oled_write_string(fd, 0, 0, "CPU Temp: ");
    char temp_str[16];
    snprintf(temp_str, sizeof(temp_str), "%.2f C", cpu_temp);
    oled_write_string(fd, 0, 20, temp_str);
    oled_write_string(fd, 1, 0, "CPU Usage: ");
    char usage_str[16];
    snprintf(usage_str, sizeof(usage_str), "%d%%", cpu_usage);
    oled_write_string(fd, 1, 20, usage_str);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, OLED_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OLED_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (oled_init(fd) < 0) {
        fprintf(stderr, "OLED initialization failed\n");
        close(fd);
        return 1;
    }
    printf("OLED initialized successfully.\n");

    while (running) {
        float cpu_temp;
        int cpu_total, cpu_idle, cpu_io, cpu_irq, cpu_soft;
        if (read_cpu_temp(&cpu_temp) < 0) {
            oled_clear(fd);
            oled_write_string(fd, 0, 0, "CPU Temp: ERROR");
            oled_write_string(fd, 1, 0, "Read failed");
            usleep(1000000);
            continue;
        }
        if (read_cpu_usage(&cpu_total, &cpu_idle, &cpu_io, &cpu_irq, &cpu_soft) < 0) {
            oled_clear(fd);
            oled_write_string(fd, 0, 0, "CPU Usage: ERROR");
            oled_write_string(fd, 1, 0, "Read failed");
            usleep(1000000);
            continue;
        }
        int cpu_usage = calculate_cpu_usage(&cpu_total, &cpu_idle, &cpu_io, &cpu_irq, &cpu_soft);
        render_data(fd, cpu_temp, cpu_usage);
        usleep(1000000);
    }
    oled_clear(fd);
    oled_write_string(fd, 0, 0, "Shutting down");
    oled_write_string(fd, 1, 0, "Press Ctrl+C");
    usleep(500000);
    close(fd);
    printf("Program terminated.\n");
    return 0;
}

