#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE1 0x80
#define LCD_LINE2 0xC0
#define E_DELAY_US 500
#define E_PULSE_US 1
#define POLL_DELAY_US 10000
#define LOG_INTERVAL_S 1
#define LCD_UPDATE_S 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_send_byte(uint8_t val, uint8_t mode) {
    if (i2c_handle < 0) return;
    if (val & 0x08) {
        gpioWrite(18, 1);
        gpioWrite(23, 0);
    } else {
        gpioWrite(18, 0);
        gpioWrite(23, 1);
    }
    gpioWrite(19, val & 0x04);
    gpioWrite(20, val & 0x02);
    gpioWrite(21, val & 0x01);
    gpioDelay(E_DELAY_US);
    gpioWrite(18, 0);
    gpioWrite(19, 0);
    gpioWrite(20, 0);
    gpioWrite(21, 0);
    gpioDelay(E_PULSE_US);
    if (mode == LCD_CMD) {
        gpioDelay(50);
    }
}

static void lcd_send_command(uint8_t cmd) {
    lcd_send_byte(cmd, LCD_CMD);
}

static void lcd_send_data(uint8_t data) {
    lcd_send_byte(data, LCD_CHR);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_send_command(0x33);
    lcd_send_command(0x32);
    lcd_send_command(0x28);
    lcd_send_command(0x0C);
    lcd_send_command(0x06);
    lcd_send_command(0x01);
    gpioDelay(2000);
}

static void lcd_clear(void) {
    lcd_send_command(0x01);
    gpioDelay(2000);
}

static void lcd_set_cursor(uint8_t line) {
    lcd_send_command(line);
}

static void lcd_write_string(const char *str) {
    while (*str) {
        lcd_send_data((uint8_t)*str++);
    }
}

static void lcd_update(float flow_rate, float total_volume) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];
    snprintf(line1, sizeof(line1), "Flow: %.2f L/s", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f m3", total_volume);
    lcd_clear();
    lcd_set_cursor(LCD_LINE1);
    lcd_write_string(line1);
    lcd_set_cursor(LCD_LINE2);
    lcd_write_string(line2);
}

static void log_data(float flow_rate, float total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Flow Rate: %.2f L/s, Total Volume: %.2f m3\n", timestamp, flow_rate, total_volume);
    fflush(stdout);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();
    lcd_clear();

    uint32_t last_tick = 0;
    uint32_t last_log_tick = gpioTick();
    uint32_t last_lcd_tick = gpioTick();
    float total_volume = 0.0f;
    int pulse_count = 0;

    while (running) {
        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_tick;
        last_tick = now;

        if (elapsed >= 1000000) {
            float flow_rate = (float)pulse_count / (elapsed / 1000000.0f);
            total_volume += flow_rate * (elapsed / 1000000.0f);
            log_data(flow_rate, total_volume);
            pulse_count = 0;
        }

        if ((now - last_log_tick) >= (uint32_t)(LOG_INTERVAL_S * 1000000)) {
            log_data(0.0f, total_volume);
            last_log_tick = now;
        }

        if ((now - last_lcd_tick) >= (uint32_t)(LCD_UPDATE_S * 1000000)) {
            lcd_update(0.0f, total_volume);
            last_lcd_tick = now;
        }

        if (gpioRead(FLOW_SENSOR_GPIO) == 0) {
            pulse_count++;
            last_tick = now;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

