/*
 * Wind monitor for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - Anemometer: pulse input on GPIO17 (BCM), rising-edge interrupt.
 *   - Wind vane: direction sensor on MCP3008 channel 0 (SPI0/CE0, mode 0).
 *   - LCD: 16x2 via PCF8574 I2C backpack on bus 1.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o wind_monitor wind_monitor.c \
 *       -lpigpio -lrt -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define ANEMOMETER_GPIO        17
#define SPI_BAUD              1000000          /* 1 MHz */
#define SPI_CHANNEL           0                /* /dev/spidev0.0 */
#define I2C_BUS               1                /* /dev/i2c-1 */
#define I2C_ADDR              0x3F             /* PCF8574 default */
#define MCP3008_CHANNEL       0
#define SAMPLE_WINDOW_US      500000           /* 500 ms */
#define PULSES_PER_REV        10               /* 10 pulses per revolution */
#define ADC_MAX               1023             /* 10-bit ADC */
#define ADC_STUCK_THRESHOLD   5                /* consecutive stuck readings */
#define LCD_COLS              16
#define LCD_ROWS              2

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_pulse_count = 0;
static volatile uint32_t    g_last_tick   = 0;
static int                   g_spi_fd      = -1;
static int                   g_i2c_fd      = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  read_mcp3008(int fd, int channel);
static int  read_wind_direction(void);
static int  calculate_wind_speed(uint32_t pulses);
static int  update_lcd(int fd, const char *line1, const char *line2);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Interrupt handler -------------------------- */

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)userdata;

    if (tick >= g_last_tick) {
        g_pulse_count++;
        g_last_tick = tick;
    }
}

/* ----------------------------- MCP3008 read ------------------------------- */

static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_BAUD,
        .bits_per_word = 8,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ----------------------------- Wind direction ----------------------------- */

static int read_wind_direction(void)
{
    int adc = read_mcp3008(g_spi_fd, MCP3008_CHANNEL);
    if (adc < 0) {
        return -1;
    }

    if (adc == 0 || adc == ADC_MAX) {
        fprintf(stderr, "Warning: ADC reading stuck at %d (sensor absent or wiring fault?)\n", adc);
        return -1;
    }

    return adc;
}

/* ----------------------------- Wind speed --------------------------------- */

static int calculate_wind_speed(uint32_t pulses)
{
    double revolutions = (double)pulses / (double)PULSES_PER_REV;
    double seconds     = (double)SAMPLE_WINDOW_US / 1.0e6;
    double speed      = (revolutions / seconds) * 60.0;   /* km/h */
    return (int)(speed + 0.5);
}

/* ----------------------------- LCD update --------------------------------- */

static int update_lcd(int fd, const char *line1, const char *line2)
{
    /*
     * PCF8574 bit-bang via pigpio gpioWrite / gpioRead on the 4 control lines.
     * Each command / data byte is repeated for the LCD's internal refresh.
     */
    static const char *cmd_table[] = {
        "0x38", "0x01", "0x06", "0x0C", "0x0E", "0x80", "0x94", "0x88",
        "0x8C", "0x84", "0x8E", "0x86", "0x00", "0x02", "0x03", "0x09",
        "0x0A", "0x0B", "0x08", "0x30", "0x31", "0x32", "0x33", "0x34",
        "0x35", "0x36", "0x37", "0x38", "0x39", "0x3A", "0x3B", "0x3C",
        "0x3D", "0x3E", "0x3F", "0x40", "0x41", "0x42", "0x43", "0x44",
        "0x45", "0x46", "0x47", "0x48", "0x49", "0x51", "0x52", "0x53",
        "0x54", "0x55", "0x56", "0x57", "0x58", "0x59", "0x5A", "0x5B",
        "0x5C", "0x5D", "0x5E", "0x5F", "0x60", "0x61", "0x62", "0x63",
        "0x64", "0x65", "0x66", "0x67", "0x68", "0x69", "0x6A", "0x6B",
        "0x6C", "0x6D", "0x6E", "0x6F", "0x70", "0x71", "0x72", "0x73",
        "0x74", "0x75", "0x76", "0x77", "0x78", "0x79", "0x7A", "0x7B",
        "0x7C", "0x7D", "0x7E", "0x7F", "0x80", "0x81", "0x82", "0x83",
        "0x84", "0x85", "0x86", "0x87", "0x88", "0x89", "0x8A", "0x8B",
        "0x8C", "0x8D", "0x8E", "0x8F", "0x90", "0x91", "0x92", "0x93",
        "0x94", "0x95", "0x96", "0x97", "0x98", "0x99", "0x9A", "0x9B",
        "0x9C", "0x9D", "0x9E", "0x9F", "0xA0", "0xA1", "0xA2", "0xA3",
        "0xA4", "0xA5", "0xA6", "0xA7", "0xA8", "0xA9", "0xAA", "0xAB",
        "0xAC", "0xAD", "0xAE", "0xAF", "0xB0", "0xB1", "0xB2", "0xB3",
        "0xB4", "0xB5", "0xB6", "0xB7", "0xB8", "0xB9", "0xBA", "0xBB",
        "0xBC", "0xBD", "0xBE", "0xBF", "0xC0", "0xC1", "0xC2", "0xC3",
        "0xC4", "0xC5", "0xC6", "0xC7", "0xC8", "0xC9", "0xCA", "0xCB",
        "0xCC", "0xCD", "0xCE", "0xCF", "0xD0", "0xD1", "0xD2", "0xD3",
        "0xD4", "0xD5", "0xD6", "0xD7", "0xD8", "0xD9", "0xDA", "0xDB",
        "0xDC", "0xDD", "0xDE", "0xDF", "0xE0", "0xE1", "0xE2", "0xE3",
        "0xE4", "0xE5", "0xE6", "0xE7", "0xE8", "0xE9", "0xEA", "0xEB",
        "0xEC", "0xED", "0xEE", "0xEF", "0xF0", "0xF1", "0xF2", "0xF3",
        "0xF4", "0xF5", "0xF6", "0xF7", "0xF8", "0xF9", "0xFA", "0xFB",
        "0xFC", "0xFD", "0xFE", "0xFF"
    };

    static uint8_t g_lcd_state[4] = {0, 0, 0, 0};
    static int     g_lcd_row      = 0;

    /* Send command to select the current row */
    uint8_t cmd = (uint8_t)strtol(line1, NULL, 0);
    if (cmd >= (int)sizeof(cmd_table) / sizeof(cmd_table[0])) {
        fprintf(stderr, "Invalid LCD command: %s\n", line1);
        return -1;
    }
    uint8_t c = (uint8_t)strtol(line2, NULL, 0);
    if (c > 0x7F) {
        fprintf(stderr, "Invalid LCD data: %s\n", line2);
        return -1;
    }

    /* Send command byte */
    uint8_t mask = 0x01;                       /* RS = 0 (command) */
    uint8_t data = (uint8_t)strtol(line1, NULL, 0);
    if (data >= (int)sizeof(cmd_table) / sizeof(cmd_table[0])) {
        fprintf(stderr, "Invalid LCD command: %s\n", line1);
        return -1;
    }
    uint8_t cmd_byte = (uint8_t)strtol(line2, NULL, 0);
    if (cmd_byte > 0x7F) {
        fprintf(stderr, "Invalid LCD data: %s\n", line2);
        return -1;
    }

    uint8_t cmd_code = (uint8_t)strtol(line1, NULL, 0);
    if (cmd_code >= (int)sizeof(cmd_table) / sizeof(cmd_table[0])) {
        fprintf(stderr, "Invalid LCD command: %s\n", line1);
        return -1;
    }

    uint8_t cmd_val = (uint8_t)strtol(line2, NULL, 0);
    if (cmd_val > 0x7F) {
        fprintf(stderr, "Invalid LCD data: %s\n", line2);
        return -1;
    }

    uint8_t rs = (c > 0x7F) ? 0x02 : 0x00;     /* RS = 1 (data) */
    uint8_t data_val = (uint8_t)cmd_val;

    /* Send command byte (control line 0 = command, 1 = data) */
    g_lcd_state[0] = (g_lcd_state[0] & 0xF8) | ((cmd_code - 0x38) & 0x07);
    g_lcd_state[1] = cmd_table[cmd_code][0];
    g_lcd_state[2] = cmd_table[cmd_code][1];
    g_lcd_state[3] = 0x00;

    /* Send data byte (control line 0 = command, 1 = data) */
    g_lcd_state[0] = (g_lcd_state[0] & 0xF8) | 0x04;   /* RS = 1, mode 1 */
    g_lcd_state[1] = rs;
    g_lcd_state[2] = data_val;
    g_lcd_state[3] = 0x00;

    /* Bit-bang the 4-byte transfer for each row */
    for (int i = 0; i < 4; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            g_lcd_state[1] = rs;
            g_lcd_state[2] = data_val;
            g_lcd_state[3] = 0x00;

            /* Control line 0 = command (0), control line 1 = data (1) */
            g_lcd_state[0] = (g_lcd_state[0] & 0xF8) | 0x04;

            if (g_lcd_state[i] & (1 << bit)) {
                g_lcd_state[1] = 0x02;   /* RS = 1 (data) */
                g_lcd_state[2] = 0x01;   /* data bit = 1 */
            } else {
                g_lcd_state[1] = 0x00;   /* RS = 0 (command) */
                g_lcd_state[2] = 0x00;   /* data bit = 0 */
            }

            /* Write the 4-byte group */
            if (i2cWriteDevice(fd, (char *)g_lcd_state, 4) < 0) {
                fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
                return -1;
            }

            gpioDelay(1);                 /* 1 us delay */
        }
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = spi0SPIOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (g_spi_fd < 0) {
        fprintf(stderr, "spi0SPIOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C device */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure anemometer GPIO */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN);
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Wind monitor started. Press Ctrl+C to exit.\n");

    uint32_t stuck_count = 0;

    while (g_running) {
        /* Sample anemometer pulses over the 500 ms window */
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        int speed = calculate_wind_speed(pulses);

        /* Read wind direction */
        int direction = read_wind_direction();

        /* Update LCD */
        char line1[LCD_COLS + 1];
        char line2[LCD_COLS + 1];

        if (direction >= 0) {
            snprintf(line1, sizeof(line1), "Spd: %d km/h", speed);
            snprintf(line2, sizeof(line2), "Dir: %d deg", direction);
        } else {
            snprintf(line1, sizeof(line1), "Spd: %d km/h", speed);
            snprintf(line2, sizeof(line2), "Dir:  ERR  ");
        }

        if (update_lcd(g_i2c_fd, line1, line2) < 0) {
            fprintf(stderr, "LCD update failed\n");
        }

        /* Sensor-absent detection: stuck ADC readings */
        if (direction >= 0) {
            stuck_count = 0;
        } else {
            stuck_count++;
            if (stuck_count >= ADC_STUCK_THRESHOLD) {
                fprintf(stderr, "Warning: %d consecutive sensor read failures. "
                                "Check wiring and sensor presence.\n", stuck_count);
            }
        }

        gpioDelay(SAMPLE_WINDOW_US);
    }

    printf("\nShutting down...\n");
