#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE1 0x80
#define LCD_LINE2 0xC0
#define E_DELAY_US 500
#define E_PULSE_US 1
#define SAMPLE_INTERVAL_SEC 1
#define MAX_CONSECUTIVE_ZEROES 10

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static volatile bool pigpio_initialized = false;
static volatile bool i2c_handle_valid = false;
static volatile bool lcd_handle_valid = false;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        pulse_count++;
        last_pulse_tick = tick;
    }
}

static void lcd_byte(int bits, int mode) {
    int high = mode | (bits & 0xF0) | 0x04;
    int low = mode | ((bits << 4) & 0xF0) | 0x04;
    if (i2c_handle_valid) {
        if (i2cWriteByte(i2c_handle, high) < 0) {
            fprintf(stderr, "Error writing high nibble to LCD\n");
        }
        if (i2cWriteByte(i2c_handle, low) < 0) {
            fprintf(stderr, "Error writing low nibble to LCD\n");
        }
    }
    gpioDelay(E_DELAY_US);
    gpioDelay(E_PULSE_US);
}

static void lcd_init(void) {
    if (i2c_handle_valid) {
        i2cWriteByte(i2c_handle, 0x33);
        gpioDelay(5000);
        i2cWriteByte(i2c_handle, 0x32);
        gpioDelay(5000);
        lcd_byte(0x28, LCD_CMD);
        lcd_byte(0x0C, LCD_CMD);
        lcd_byte(0x06, LCD_CMD);
        lcd_byte(0x01, LCD_CMD);
        gpioDelay(2000);
    }
}

static void lcd_clear(void) {
    if (i2c_handle_valid) {
        lcd_byte(0x01, LCD_CMD);
        gpioDelay(2000);
    }
}

static void lcd_string(const char *s) {
    if (i2c_handle_valid) {
        while (*s) {
            lcd_byte((uint8_t)*s++, LCD_CHR);
        }
    }
}

static void lcd_set_cursor(int line) {
    if (i2c_handle_valid) {
        lcd_byte(line, LCD_CMD);
    }
}

static void display_flow_rate(float flow_rate) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];
    snprintf(line1, sizeof(line1), "Flow Rate:");
    snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate);
    lcd_clear();
    lcd_set_cursor(LCD_LINE1);
    lcd_string(line1);
    lcd_set_cursor(LCD_LINE2);
    lcd_string(line2);
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL);
        gpioTerminate();
        pigpio_initialized = false;
    }
    if (i2c_handle_valid) {
        i2cClose(i2c_handle);
        i2c_handle_valid = false;
    }
    if (lcd_handle_valid) {
        i2cClose(lcd_handle);
        lcd_handle_valid = false;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    pigpio_initialized = true;

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, LCD_ADDR);
        cleanup();
        return 1;
    }
    i2c_handle_valid = true;

    lcd_init();
    lcd_handle_valid = true;

    uint32_t last_sample_tick = gpioTick();
