#include <pigpio.h>

#define DELAY_US 800
#define NUM_PINS 8

static const int row_pins[NUM_PINS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_PINS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, int level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        safe_write(row_pins[i], 0);
        safe_write(col_pins[i], 1);
    }
}

static void display_frame(const int frame[NUM_PINS]) {
    clear_matrix();
    for (int i = 0; i < NUM_PINS; i++) {
        if (frame[i]) {
            safe_write(row_pins[i], 1);
            safe_write(col_pins[i], 0);
        }
    }
    gpioDelay(DELAY_US);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) != 0 ||
            safe_set_mode(col_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int frame1[NUM_PINS] = {0};
    int frame2[NUM_PINS] = {0};
    int pos1 = 0, pos2 = 7;

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            frame1[i] = (i >= pos1);
            frame2[i] = (i <= pos2);
        }
        display_frame(frame1);
        display_frame(frame2);
        pos1 = (pos1 + 1) % NUM_PINS;
        pos2 = (pos2 - 1 + NUM_PINS) % NUM_PINS;
    }

    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

