#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8

/* BCM GPIO numbers for row anodes (common anode matrix: HIGH = ON) */
static const int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
/* BCM GPIO numbers for column cathodes (LOW = ON, HIGH = OFF) */
static const int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) < 0) return -1;
        if (safe_write(row_pins[i], 0) < 0) return -1;
    }

    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) < 0) return -1;
        if (safe_write(col_pins[i], 1) < 0) return -1;
    }

    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_write(row_pins[i], 0) < 0) return;
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_write(col_pins[i], 1) < 0) return;
    }
}

static void display_wave(void) {
    clear_matrix();

    for (int col = 0; col < NUM_COLS && running; col++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            if (safe_write(row_pins[row], 1) < 0) return;
            if (safe_write(col_pins[col], 0) < 0) return;
            gpioDelay(150000); /* 150 ms */
        }
        if (safe_write(col_pins[col], 1) < 0) return;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        display_wave();
    }

    /* Clean shutdown: turn off all LEDs and release lines */
    clear_matrix();
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(col_pins[i], 1);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

