/*
 * VL53L3CX multi-target ToF sensor reader for Raspberry Pi 3 Model B+
 * I2C bus 1, 100 ms polling interval.
 *
 * NOTE: The VL53L3CX is a complex, vendor-proprietary ToF sensor.
 * The full firmware download and initialization sequence is NOT
 * implemented here (it requires a vendor-provided SDK and firmware
 * binary). This program provides the I2C communication and error
 * handling framework, along with a stubbed initialization sequence
 * that verifies the sensor is present and responds to the model ID
 * register read. Replace the stubbed sections with the actual SDK
 * calls once the vendor SDK is available.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L3CX_ADDR  0x29
#define POLL_MS        100

/* VL53L3CX register addresses (16-bit, big-endian on the bus) */
#define REG_MODEL_ID          0x010F
#define REG_FIRMWARE_VERSION  0x010A
#define REG_RANGE_STATUS      0x0089
#define REG_RESULT__DISTANCE  0x0096
#define REG_RESULT__NUM_TARG  0x0098

#define EXPECTED_MODEL_ID     0xEA

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 8-bit value via a 2-byte transfer. */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read an 8-bit value from a 16-bit register address. */
static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C addr write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, value, sizeof(*value)) != (ssize_t)sizeof(*value)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address. */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value)
{
    uint8_t addr[2];
    uint8_t data[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C addr write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/*
 * Stubbed proprietary initialization sequence.
 * Replace this with the actual vendor SDK calls once the SDK is available.
 */
static int vl53l3cx_init(int fd)
{
    /*
     * In a real application, this would download the firmware and
     * perform the complex proprietary initialization sequence
