#define I2C_BUS "/dev/i2c-1"
#define MLX75031_ADDR 0x48
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t cmd = reg;
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_sensor(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_distance(int16_t *distance) {
    if (i2c_fd < 0) {
        return -1;
    }
    if (i2c_read_reg16(i2c_fd, 0x01, distance) < 0) {
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, int16_t distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp);
}

