    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Distance\n");
        fflush(log_fp);
    }

    while (running) {
        int16_t distance;
        if (read_distance(&distance) < 0) {
            fprintf(stderr, "Failed to read distance. Attempting to re-initialize I2C.\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            sleep(1);
            if (init_sensor() < 0) {
                fprintf(stderr, "Re-initialization failed. Continuing to log -1.\n");
            }
            distance = -1;
        }
        log_data(log_fp, distance);
        usleep(SAMPLE_INTERVAL_US);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    printf("Program terminated gracefully.\n");
    return 0;
}

