#include <pigpio.h>

/* Si1145 I2C address (7-bit) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_REV_ID       0x01
#define SI1145_REG_SEQ_ID       0x02
#define SI1145_REG_INT_CFG      0x03
#define SI1145_REG_IRQ_ENABLE   0x04
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_ALS_RATE     0x0A
#define SI1145_REG_PS_RATE      0x0B
#define SI1145_REG_ALS_IR_ADCMUX 0x0C
#define SI1145_REG_PS1_ADCMUX   0x0D
#define SI1145_REG_ALS_VIS_ADCMUX 0x0E
#define SI1145_REG_PS_ADC_GAIN  0x0F
#define SI1145_REG_ALS_ADC_GAIN 0x10
#define SI1145_REG_PS1_ADC_GAIN 0x11
#define SI1145_REG_PS2_ADC_GAIN 0x12
#define SI1145_REG_PS3_ADC_GAIN 0x13
#define SI1145_REG_PS_LED21     0x14
#define SI1145_REG_PS_LED3      0x15
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_ALS_IR_DATA1  0x25
#define SI1145_REG_PS1_DATA0     0x26
#define SI1145_REG_PS1_DATA1     0x27
#define SI1145_REG_COMMAND       0x30

/* Si1145 command codes */
#define SI1145_CMD_RESET        0x01
#define SI1145_CMD_ALS_FORCE    0x06
#define SI1145_CMD_PS_FORCE     0x05
#define SI1145_CMD_PSALS_FORCE  0x07
#define SI1145_CMD_NOP          0x00

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID          0x45

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1145 driver                                                       */
/* ------------------------------------------------------------------ */
static int si1145_init(int handle)
{
    uint8_t part_id = 0;

    /* Verify sensor identity */
    if (i2c_read_byte(handle, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    /* Software reset */
    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Write mandatory HW_KEY (required after reset per datasheet) */
    if (i2c_write_byte(handle, SI1145_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Configure measurement rates */
    if (i2c_write_byte(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_ALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1145_REG_PS_RATE, 0x00) < 0) return -1;

    /* Enable ALS and PS channels */
    if (i2c_write_byte(handle, SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;

    /* Start autonomous measurements */
    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0)
        return -1;

    return 0;
}

static int si1145_read_proximity(int handle, uint16_t *prox)
{
    return i2c_read_word(handle, SI1145_REG_PS1_DATA0, prox);
}

static int si1145_read_ambient_light(int handle, uint16_t *als)
{
    return i2c_read_word(handle, SI1145_REG_ALS_VIS_DATA0, als);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Call API call() for proper sensor shutdown */
    if (i2c_handle >= 0) {
        i2c_write_byte(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_NOP);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1145 address */
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %m\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %m\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1145 data to biometric_data.log (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t proximity = 0;
        uint16_t ambient_light = 0;

        int p_rc = si1145_read_proximity(i2c_handle, &proximity);
        int a_rc = si1145_read_ambient_light(i2c_handle, &ambient_light);

        if (p_rc == 0 && a_rc == 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Sensor read error — skipping sample\n");
        }

        gpioDelay(1000000); /* 1 second */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

