#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms */
#define LOOP_INTERVAL_S   60
#define MIN_DISTANCE_CM   2.0
#define MAX_DISTANCE_CM   400.0
#define PLANT_THRESHOLD_CM 15.0
#define LOG_FILE_NAME     "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04: 10 µs high pulse on TRIGGER_PIN                 */
/* ------------------------------------------------------------------ */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure distance in cm.  Returns >= 0 on success, -1.0 on error.     */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* --- Wait for echo to rise (sensor responds) --- */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0;
        }
        gpioDelay(20); /* 20 µs poll interval */
    }
    start_tick = gpioTick();

    /* --- Wait for echo to fall (pulse complete) --- */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (stuck high)\n");
            return -1.0;
        }
        gpioDelay(20);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* speed of sound ~343 m/s => 1 cm = 29.1 µs round-trip */
    float distance_cm = (float)pulse_us / 29.1f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f-%.1f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance_cm;
}

