#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_I2C_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_US 100000

/* APDS-9960 register addresses */
#define APDS9960_ENABLE  0x80
#define APDS9960_ATIME   0x81
#define APDS9960_WTIME   0x83
#define APDS9960_PPULSE  0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x8D
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID      0x92
#define APDS9960_STATUS  0x93
#define APDS9960_CDATAL  0x94
#define APDS9960_CDATAH  0x95
#define APDS9960_RDATAL  0x96
#define APDS9960_RDATAH  0x97
#define APDS9960_GDATAL  0x98
#define APDS9960_GDATAH  0x99
#define APDS9960_BDATAL  0x9A
#define APDS9960_BDATAH  0x9B
#define APDS9960_PDATA   0x9C

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int apds9960_write_byte(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(g_i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int apds9960_read_byte(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(g_i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int apds9960_read_word(uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(g_i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

static int apds9960_init(void) {
    uint8_t id = 0;

    if (apds9960_read_byte(APDS9960_ID, &id) < 0) {
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Unexpected APDS9960 ID: 0x%02X (expected 0xAB)\n", id);
        return -1;
    }

    if (apds9960_write_byte(APDS9960_ENABLE, 0x00) < 0) return -1;
    if (apds9960_write_byte(APDS9960_ATIME, 0xFF) < 0) return -1;
    if (apds9960_write_byte(APDS9960_WTIME, 0xFF) < 0) return -1;
    if (apds9960_write_byte(APDS9960_PPULSE, 0x40) < 0) return -1;
    if (apds9960_write_byte(APDS9960_CONTROL, 0x03) < 0) return -1;
    if (apds9960_write_byte(APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (apds9960_write_byte(APDS9960_CONFIG2, 0x00) < 0) return -1;
    if (apds9960_write_byte(APDS9960_ENABLE, 0x0E) < 0) return -1;

    return 0;
}

static int log_data(uint16_t r, uint16_t g, uint16_t b, uint16_t p) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_file, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, p) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, APDS9960_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(g_log_file);
    }

    printf("APDS9960 initialized. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        uint16_t r, g, b, p;

        if (apds9960_read_word(APDS9960_RDATAL, &r) < 0 ||
            apds9960_read_word(APDS9960_GDATAL, &g) < 0 ||
            apds9960_read_word(APDS9960_BDATAL, &b) < 0 ||
            apds9960_read_word(APDS9960_PDATA, &p) < 0) {
            fprintf(stderr, "I2C read error. Re-initializing sensor...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000);
            g_i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", g_i2c_handle);
                break;
            }
            if (apds9960_init() < 0) {
                fprintf(stderr, "Re-initialization failed\n");
                break;
            }
            continue;
        }

        if (p > PROXIMITY_THRESHOLD) {
            if (log_data(r, g, b, p) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

