#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define REG_PROX_DATA  0x0A
#define SAMPLE_MS      100
#define CSV_FILE       "heartrate.csv"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    return i2c_read_reg16(fd, REG_PROX_DATA, prox);
}

static int calculate_bpm(uint16_t prox) {
    /* Placeholder: real algorithm uses peaks over time window */
    return (int)(prox * 10);
}

static int log_data(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (!localtime_r(&t, &tm)) return -1;
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) return -1;
    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) return -1;
    if (fflush(fp) != 0) return -1;
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        goto cleanup;
    }

    while (running) {
        uint16_t prox;
        if (read_proximity(fd, &prox) != 0) {
            fprintf(stderr, "Warning: I2C read failed: %s\n", strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }
        int bpm = calculate_bpm(prox);
        if (log_data(fp, bpm) != 0) {
            fprintf(stderr, "Warning: CSV write failed: %s\n", strerror(errno));
        }
        usleep(SAMPLE_MS * 1000);
    }

    rc = 0;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

