/*
 * VL53L0X Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C and GPIO control.
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO 2 (I2C bus 1 SDA)
 *   VL53L0X SCL -> GPIO 3 (I2C bus 1 SCL)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *   VL53L0X XSHUT -> GPIO 17 (BCM), 3.3 V tolerant
 *
 * Build: gcc -O2 -Wall -o vl53l0x_logger vl53l0x_logger.c -lpigpio -lrt
 * Run:   sudo ./vl53l0x_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L0X register map (16-bit addresses, big-endian on bus) ---- */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID      0x010F
#define VL53L0X_REG_SYSTEM_MODE_START            0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS      0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS          0x0089
#define VL53L0X_REG_RESULT_DISTANCE              0x0096
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR       0x0086
#define VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L0X_REG_GPIO_HV_MUX_CTRL             0x0030
#define VL53L0X_REG_GPIO_TIO_HV_STATUS           0x0031
#define VL53L0X_REG_SYSTEM_INTERMEASUREMENT      0x0008
#define VL53L0X_REG_SYSTEM_THRESH_HIGH           0x0009
#define VL53L0X_REG_SYSTEM_THRESH_LOW            0x000A
#define VL53L0X_REG_SYSTEM_SEQUENCE_CONFIG       0x000B
#define VL53L0X_REG_SYSTEM_FRESH_OUT_OF_RESET    0x0000
#define VL53L0X_REG_SYSTEM_RANGE_CONFIG          0x005D
#define VL53L0X_REG_SYSTEM_RANGE_START           0x0000

#define VL53L0X_MODEL_ID                         0xEA
#define VL53L0X_EXPECTED_MODEL_ID                0xEA
#define I2C_BUS                                  1
#define TRIGGER_PIN                              17
#define LOG_FILE                                 "distance_log.txt"
#define POLL_TIMEOUT_MS                          100
#define MEASUREMENT_PERIOD_S                     1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Low-level I2C helpers ---- */

static int vl53l0x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l0x_read16(int handle, uint16_t reg, uint8_t *data, int len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)data, len) != len)
        return -1;
    return 0;
}

/* ---- Sensor initialization ---- */

static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify sensor identity */
    if (vl53l0x_read16(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }

    /* Clear reset bit and let the sensor settle */
    if (vl53l0x_write16(handle, VL53L0X_REG_SYSTEM_FRESH_OUT_OF_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to clear reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Configure GPIO 17 as falling-edge interrupt input */
    if (vl53l0x_write16(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) {
        fprintf(stderr, "Error: failed to configure GPIO interrupt.\n");
        return -1;
    }

    /* Enable pull-up on GPIO 17 (active-low interrupt) */
    if (vl53l0x_write16(handle, VL53L0X_REG_GPIO_HV_MUX_CTRL, 0x20) < 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO 17.\n");
        return -1;
    }

    /* Clear any pending interrupt */
    if (vl53l0x_write16(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt.\n");
        return -1;
    }

    /* Start continuous ranging (bit 0 = start measurement) */
    if (vl53l0x_write16(handle, VL53L0X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/* ---- Read a single distance measurement ---- */

static int vl53l0x_read_distance(int handle, uint8_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist   = 0;
    int     elapsed = 0;

    /* Poll RESULT_INTERRUPT_STATUS until data-ready bit (bit 0) is set */
    while (elapsed < POLL_TIMEOUT_MS) {
        if (vl53l0x_read16(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read interrupt status.\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }

    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: measurement timeout (no data-ready within %d ms).\n",
                POLL_TIMEOUT_MS);
        return -1;
    }

    /* Read distance (2 bytes, big-endian) */
    if (vl53l0x_read16(handle, VL53L0X_REG_RESULT_DISTANCE, &dist, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance register.\n");
        return -1;
    }

    *distance_mm = dist;
    return 0;
}

/* ---- Logging ---- */

static void log_distance(FILE *fp, uint8_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

/* ---- Signal handler ---- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L0X default address (0x29) */
    g_i2c_handle = i2cOpen(I2C_BUS, 0x29, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L0X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L0X logger started. Press Ctrl+C to stop.\n");

    /* Main loop: wait for falling edge, read distance, log */
    while (g_running) {
        /* Wait for falling edge on GPIO 17 */
        if (gpioWait(0, (1 << TRIGGER_PIN), 1000000) < 0) {
            fprintf(stderr, "Error: gpioWait failed.\n");
            break;
        }

        uint8_t distance_mm = 0;
        if (vl53l0x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Error: distance read failed.\n");
            continue;
        }

        log_distance(g_log_file, distance_mm);
        printf("Distance: %u mm\n", distance_mm);

        /* Sleep for the remainder of the measurement period */
        gpioDelay(MEASUREMENT_PERIOD_S * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

