#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define TRIGGER_CMD    0x80
#define SAMPLE_US      50000   /* 50 ms measurement wait */
#define SAMPLE_PERIOD  200000  /* 200 ms between samples */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single command byte to the CH101.
 * Returns 0 on success, -1 on failure.
 */
static int ch101_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian distance value from the CH101.
 * Returns 0 on success and stores the distance in *out_mm,
 * or -1 on failure.
 */
static int ch101_read_distance(int handle, uint16_t *out_mm)
{
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed\n");
        return -1;
    }

    *out_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Append a timestamped distance reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }

    printf("%s, %u\n", ts, distance_mm);
    return 0;
}

int main(void)
{
    int i2c_handle = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_i2c;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        if (ch101_write_cmd(i2c_handle, TRIGGER_CMD) != 0) {
            /* I2C error: skip this sample, keep running */
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        gpioDelay(SAMPLE_US);  /* 50 ms measurement wait */

        uint16_t distance_mm = 0;
        if (ch101_read_distance(i2c_handle, &distance_mm) != 0) {
            /* I2C error: skip this sample, keep running */
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        if (log_distance(log_fp, distance_mm) != 0) {
            /* Logging error: keep running, but report it */
            fprintf(stderr, "Warning: logging failed for this sample\n");
        }

        gpioDelay(SAMPLE_PERIOD);  /* 200 ms between samples */
    }

    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (log_fp != NULL) {
        fclose(log_fp);
    }
cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioTerminate();

    if (rc == EXIT_SUCCESS) {
        printf("\nExiting gracefully...\n");
    }
    return rc;
}

