/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ultrasonic ToF distance reader
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode     -> GPIO 17 (BCM) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_distance icu20201_distance.c -lpigpio -lrt
 *   (pigpio must be installed and the user must be in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x49          /* ICU-20201 default 7-bit I2C address */
#define GPIO_LED             17            /* BCM pin for the LED */
#define DISTANCE_THRESHOLD   20.0          /* cm – LED on when distance < this */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between readings */
#define LOG_FILE             "distance_log.txt"

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_PRODUCT_ID       0x00
#define REG_DISTANCE         0x0A
#define REG_STATUS           0x0B
#define REG_COMMAND          0x0C
#define REG_MEAS_RATE        0x0D
#define REG_RANGE_CONFIG     0x0E
#define REG_ECHO_CONFIG      0x0F
#define REG_INT_CFG          0x10
#define REG_INT_STATUS       0x11
#define REG_INT_CLEAR        0x12
#define REG_RESET            0x13

#define CMD_START_MEAS       0x01          /* start a single measurement */
#define CMD_STOP_MEAS        0x00          /* stop measurement */
#define CMD_RESET            0x80          /* software reset */

#define EXPECTED_PRODUCT_ID  0x2020        /* ICU-20201 product ID */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Sensor helpers ------------------------------ */
/* Write a 16-bit value to a 16-bit register (big-endian on the bus). */
static int sensor_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from a 16-bit register (big-endian on the bus). */
static int sensor_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose on log failed: %s\n", strerror(errno));
}

/* --------------------------- Sensor init --------------------------------- */
static int sensor_init(int handle)
{
    uint16_t product_id = 0;
    if (sensor_read_reg16(handle, REG_PRODUCT_ID, &product_id) < 0) {
        fprintf(stderr, "Failed to read PRODUCT_ID register: %s\n",
                strerror(errno));
        return -1;
    }
    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr,
                "Unexpected PRODUCT_ID 0x%04X (expected 0x%04X) – wrong sensor?\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }

    /* Software reset */
    if (sensor_write_reg16(handle, REG_RESET, CMD_RESET) < 0) {
        fprintf(stderr, "Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* Stop any running measurement */
    if (sensor_write_reg16(handle, REG_COMMAND, CMD_STOP_MEAS) < 0) {
        fprintf(stderr, "Failed to stop measurement: %s\n", strerror(errno));
        return -1;
    }

    /* Measurement rate: 0 = single-shot mode (manual triggers) */
    if (sensor_write_reg16(handle, REG_MEAS_RATE, 0x0000) < 0) {
        fprintf(stderr, "Failed to set MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }

    /* Range config: 0 = 0–100 cm, 1 = 100–200 cm, 2 = 200–400 cm, 3 = 400–800 cm */
    if (sensor_write_reg16(handle, REG_RANGE_CONFIG, 0x0000) < 0) {
        fprintf(stderr, "Failed to set RANGE_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Echo config: 0 = 0–100 cm, 1 = 100–200 cm, 2 = 200–400 cm, 3 = 400–800 cm */
    if (sensor_write_reg16(handle, REG_ECHO_CONFIG, 0x0000) < 0) {
        fprintf(stderr, "Failed to set ECHO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Interrupt config: 0 = no interrupts */
    if (sensor_write_reg16(handle, REG_INT_CFG, 0x0000) < 0) {
        fprintf(stderr, "Failed to set INT_CFG: %s\n", strerror(errno));
        return -1;
    }

    /* Clear any pending interrupt status */
    if (sensor_write_reg16(handle, REG_INT_CLEAR, 0x0001) < 0) {
        fprintf(stderr, "Failed to clear INT_STATUS: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* --------------------------- Read distance ------------------------------- */
static int read_distance(int handle, float *distance_out)
{
    uint16_t status = 0;
    int attempts = 0;

    /* Trigger a single measurement */
    if (sensor_write_reg16(handle, REG_COMMAND, CMD_START_MEAS) < 0) {
        fprintf(stderr, "Failed to start measurement: %s\n", strerror(errno));
        return -1;
    }

    /* Poll STATUS register for data-ready (bit 0) with timeout */
    do {
        if (sensor_read_reg16(handle, REG_STATUS, &status) < 0) {
            fprintf(stderr, "Failed to read STATUS register: %s\n",
                    strerror(errno));
            return -1;
        }
        if (++attempts > 100) {
            fprintf(stderr, "Timeout waiting for measurement (STATUS=0x%04X)\n",
                    status);
            return -1;
        }
        gpioDelay(1000);  /* 1 ms */
    } while ((status & 0x0001) == 0);

    uint16_t distance_raw = 0;
    if (sensor_read_reg16(handle, REG_DISTANCE, &distance_raw) < 0) {
        fprintf(stderr, "Failed to read DISTANCE register: %s\n",
                strerror(errno));
        return -1;
    }

    /* Convert raw 16-bit value to distance in cm */
    *distance_out = (float)distance_raw / 2.0f;

    /* Clear interrupt so the next measurement can signal ready */
    if (sensor_write_reg16(handle, REG_INT_CLEAR, 0x0001) < 0) {
        fprintf(stderr, "Warning: failed to clear INT_STATUS: %s\n",
                strerror(errno));
    }

    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Stop any measurement before closing */
        (void)i2cWriteDevice(g_i2c_handle, (char[]){ REG_COMMAND, CMD_STOP_MEAS, 0x00, 0x00 }, 4);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed – check wiring and address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance reader started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float distance = 0.0f;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            fprintf(stderr, "Read failed – continuing\n");
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

