#define DISTANCE_THRESHOLD   20.0          /* cm – LED on when distance < this */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between readings */
#define LOG_FILE             "distance_log.txt"

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_PRODUCT_ID       0x00
#define REG_DISTANCE         0x0A
#define REG_STATUS           0x0B
#define REG_COMMAND          0x0C
#define REG_MEAS_RATE        0x0D
#define REG_RANGE_CONFIG     0x0E
#define REG_ECHO_CONFIG      0x0F
#define REG_INT_CFG          0x10
#define REG_INT_STATUS       0x11
#define REG_INT_CLEAR        0x12
#define REG_RESET            0x13

#define CMD_START_MEAS       0x01          /* start a single measurement */
#define CMD_STOP_MEAS        0x00          /* stop measurement */
#define CMD_RESET            0x80          /* software reset */

