/* --------------------------- Sensor helpers ------------------------------ */
/* Write a 16-bit value to a 16-bit register (big-endian on the bus). */
static int sensor_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from a 16-bit register (big-endian on the bus). */
static int sensor_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose on log failed: %s\n", strerror(errno));
}

/* --------------------------- Sensor init --------------------------------- */
static int sensor_init(int handle)
{
    uint16_t product_id = 0;
    if (sensor_read_reg16(handle, REG_PRODUCT_ID, &product_id) < 0) {
