                "Unexpected PRODUCT_ID 0x%04X (expected 0x%04X) – wrong sensor?\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }

    /* Software reset */
    if (sensor_write_reg16(handle, REG_RESET, CMD_RESET) < 0) {
