    if (sensor_write_reg16(handle, REG_MEAS_RATE, 0x0000) < 0) {
        fprintf(stderr, "Failed to set MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }

    /* Range config: 0 = 0–100 cm, 1 = 100–200 cm, 2 = 200–400 cm, 3 = 400–800 cm */
    if (sensor_write_reg16(handle, REG_RANGE_CONFIG, 0x0000) < 0) {
