    if (sensor_write_reg16(handle, REG_INT_CFG, 0x0000) < 0) {
        fprintf(stderr, "Failed to set INT_CFG: %s\n", strerror(errno));
        return -1;
    }

    /* Clear any pending interrupt status */
    if (sensor_write_reg16(handle, REG_INT_CLEAR, 0x0001) < 0) {
        fprintf(stderr, "Failed to clear INT_STATUS: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

