#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1182 I2C address (7-bit) */
#define SI1182_ADDR 0x60

/* Si1182 register addresses */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE0   0x08
#define SI1182_REG_MEAS_RATE1   0x09
#define SI1182_REG_PS_LED21     0x0F
#define SI1182_REG_PS_LED3      0x10
#define SI1182_REG_PS1_DATA0    0x22
#define SI1182_REG_PS1_DATA1    0x23
#define SI1182_REG_ALS_VIS_DATA0 0x26
#define SI1182_REG_ALS_VIS_DATA1 0x27

/* Expected PART_ID for Si1182 */
#define SI1182_PART_ID_EXPECTED 0x82

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Globals for signal-handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a Si1182 register; returns 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a Si1182 register; returns 0 on success, -1 on error*/
/* ------------------------------------------------------------------ */
static int si1182_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1182 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1182_init(void)
{
    uint8_t part_id = 0;

    /* Verify sensor identity */
    if (si1182_read_reg(SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Cannot read PART_ID – sensor may be absent.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* Write HW_KEY required value (0x00) per datasheet */
    if (si1182_write_reg(SI1182_REG_HW_KEY, 0x00) != 0)
        return -1;

    /* Configure measurement rate: 0x00 = 1 sample per 1 ms (fastest) */
    if (si1182_write_reg(SI1182_REG_MEAS_RATE0, 0x00) != 0)
        return -1;
    if (si1182_write_reg(SI1182_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    /* Configure LED current for proximity (LED1 = 0x0F, LED2 = 0x0F) */
    if (si1182_write_reg(SI1182_REG_PS_LED21, 0x0F) != 0)
        return -1;
    if (si1182_write_reg(SI1182_REG_PS_LED3, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                            */
/* ------------------------------------------------------------------ */
static int si1182_read_16bit(uint8_t reg_low, uint8_t reg_high, uint16_t *out)
{
    uint8_t lo = 0, hi = 0;
    if (si1182_read_reg(reg_low, &lo) != 0)
        return -1;
    if (si1182_read_reg(reg_high, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data with retry logic                                   */
/* ------------------------------------------------------------------ */
static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (si1182_read_16bit(SI1182_REG_PS1_DATA0, SI1182_REG_PS1_DATA1, proximity) == 0 &&
            si1182_read_16bit(SI1182_REG_ALS_VIS_DATA0, SI1182_REG_ALS_VIS_DATA1, ambient_light) == 0)
            return 0;

        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                         */
/* ------------------------------------------------------------------ */
static int log_data(uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
