#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICU-20201 I2C configuration */
#define I2C_BUS        1
#define I2C_ADDR       0x49   /* ICU-20201 default 7-bit I2C address */

/* GPIO configuration */
#define LED_GPIO       17     /* BCM 17 */

/* Register addresses (from ICU-20201 datasheet) */
#define REG_WHO_AM_I   0x0F
#define REG_SYS_CFG    0x10
#define REG_MEAS_CFG   0x11
#define REG_DIST_MSB   0x12
#define REG_DIST_LSB   0x13

/* Expected WHO_AM_I value for ICU-20201 */
#define WHO_AM_I_VAL   0x49

/* Default threshold distance in mm */
#define DEFAULT_THRESHOLD 100

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] I2C write reg 0x%02X val 0x%02X failed (rc=%d)\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(handle, REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I – sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Software reset via SYS_CFG */
    if (i2c_write_reg8(handle, REG_SYS_CFG, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Software reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Configure measurement: enable continuous mode, 50 ms period */
    if (i2c_write_reg8(handle, REG_MEAS_CFG, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Measurement config failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (mm)                                                  */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, int *distance_mm)
{
    uint8_t msb = 0, lsb = 0;

    if (i2c_read_reg8(handle, REG_DIST_MSB, &msb) != 0)
        return -1;
    if (i2c_read_reg8(handle, REG_DIST_LSB, &lsb) != 0)
        return -1;

    *distance_mm = ((int)msb << 8) | (int)lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log distance with timestamp                                         */
/* ------------------------------------------------------------------ */
static void log_distance(int distance_mm)
{
    FILE *fp = fopen("tof_log.txt", "a");
    if (!fp) {
        perror("[ERROR] fopen tof_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    } else {
        fprintf(fp, "Timestamp error, Distance: %d mm\n", distance_mm);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold = DEFAULT_THRESHOLD;
    int distance_mm;

    /* Parse command-line threshold */
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "[WARN] Invalid threshold '%s', using default %d mm\n",
                    argv[1], DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance monitor running. Threshold: %d mm. Press Ctrl+C to exit.\n",
           threshold);

    /* Main loop */
    while (g_running) {
        if (read_distance(g_i2c_handle, &distance_mm) == 0) {
            printf("Distance: %d mm\n", distance_mm);

            if (distance_mm < threshold) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }

            log_distance(distance_mm);
        } else {
            fprintf(stderr, "[WARN] Read failed – continuing\n");
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(50000); /* 50 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

