                gpioWrite(LED_GPIO, 0);
            }

            log_distance(distance_mm);
        } else {
            fprintf(stderr, "[WARN] Read failed – continuing\n");
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(50000); /* 50 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

