#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x50
#define LOG_FILE       "intrusion_log.txt"
#define DISTANCE_THRESHOLD_MM 1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_US 100000
#define MEAS_DELAY_US  10000
#define LOOP_DELAY_US  100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {0x01, 0x02, 0x03, 0x04};
    uint8_t resp[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read_data(fd, resp, sizeof(resp)) < 0)
        return -1;

    if (resp[0] != 0x05) {
        fprintf(stderr, "Unexpected response header: 0x%02X\n", resp[0]);
        return -1;
    }

    uint16_t raw = ((uint16_t)resp[11] << 8) | resp[12];
    *distance_mm = (int)raw;
    return 0;
}

static int log_intrusion(FILE *fp, int distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    int distances[NUM_SAMPLES];
    int error_count = 0;

    while (g_running) {
        int valid_samples = 0;
        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                distances[valid_samples] = dist;
                valid_samples++;
            } else {
                error_count++;
            }
            usleep(SAMPLE_DELAY_US);
        }

        if (valid_samples == 0) {
            fprintf(stderr, "All samples failed; retrying next cycle.\n");
            usleep(LOOP_DELAY_US);
            continue;
        }

        int sum = 0;
        for (int i = 0; i < valid_samples; i++)
            sum += distances[i];
        int avg = sum / valid_samples;

        if (avg < DISTANCE_THRESHOLD_MM) {
            if (log_intrusion(log_fp, avg) < 0)
                fprintf(stderr, "Logging failed.\n");
        }

        printf("Valid samples: %d, Average distance: %d mm\n",
               valid_samples, avg);
        usleep(LOOP_DELAY_US);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (log_fp) fclose(log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

