#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L0X register addresses (16-bit, big-endian on the bus) */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID      0x00C0
#define VL53L0X_REG_SYSTEM_MODE_START            0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS      0x0044
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

#define VL53L0X_MODEL_ID_VALUE 0xEA
#define I2C_BUS 1
#define POLL_TIMEOUT_MS 100
#define POLL_DELAY_US 1000
#define SAMPLE_PERIOD_US 500000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte of data using a single I2C write. */
static int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%04X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting at a 16-bit register address. */
static int vl53l0x_read_bytes(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "Error setting read address 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading %u bytes from reg 0x%04X: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    if (vl53l0x_read_bytes(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0)
        return -1;

    if (model_id != VL53L0X_MODEL_ID_VALUE) {
        fprintf(stderr, "VL53L0X not detected (model ID = 0x%02X, expected 0x%02X)\n",
                model_id, VL53L0X_MODEL_ID_VALUE);
        return -1;
    }

    /* Start continuous back-to-back ranging mode */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_MODE_START, 0x00) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    return 0;
}

static int vl53l0x_read_distance(int handle, int *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};

    /* Poll RESULT_INTERRUPT_STATUS until data-ready bit (bit 0) is set */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (vl53l0x_read_bytes(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(POLL_DELAY_US);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for VL53L0X data-ready\n");
        return -1;
    }

    if (vl53l0x_read_bytes(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 0)
        return -1;

    *distance_mm = (data[0] << 8) | data[1];
    return 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm *timeinfo;
    char buf[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s ", buf);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, 0x29, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x29: %s\n",
                I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X initialized. Reading distance every 500 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance = 0;

        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %d mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: distance read failed, will retry next cycle\n");
        }

        /* Sleep 500 ms in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 5 && g_running; i++)
            gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    vl53l0x_write_byte(g_i2c_handle, VL53L0X_REG_SYSTEM_MODE_START, 0x01);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

