            printf("Distance: %d mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: distance read failed, will retry next cycle\n");
        }

        /* Sleep 500 ms in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 5 && g_running; i++)
            gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    vl53l0x_write_byte(g_i2c_handle, VL53L0X_REG_SYSTEM_MODE_START, 0x01);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

