/*
 * Si1182 Proximity Reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Silicon Labs Si1182 (16-bit proximity data register)
 *
 * Build: gcc -O2 -Wall -o si1182_prox si1182_prox.c -li2c
 * Run:   sudo ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60          /* Si1182 default 7-bit I2C address */
#define SI1182_REG_PROX 0x0A          /* 16-bit proximity data register */
#define POLL_MS        500           /* 500 ms sampling interval */
#define MAX_RETRIES    3             /* consecutive error limit before exit */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register via the Linux I2C ioctl.   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register from the Si1182.               */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t n = write(fd, &reg_buf, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg16: write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    uint8_t data[2];
    n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "i2c_read_reg16: read(0x%02X) failed: %s (got %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the I2C bus ---- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire the Si1182 slave address ---- */
    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Probe: attempt a register write to confirm the sensor is present ---- */
    if (i2c_write_reg8(fd, SI1182_REG_PROX, 0x00) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: NACK or bus error.\n",
                SI1182_ADDR);
        goto cleanup;
    }

    printf("Si1182 proximity reader started on %s (addr 0x%02X).\n",
           I2C_BUS, SI1182_ADDR);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    /* ---- Main polling loop ---- */
    while (g_running) {
        uint16_t prox = 0;

        if (i2c_read_reg16(fd, SI1182_REG_PROX, &prox) == 0) {
            printf("Proximity: %u\n", prox);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors (%d) reached. Exiting.\n",
                        MAX_RETRIES);
                goto cleanup;
            }
        }

        /* Sleep 500 ms; usleep is interruptible by signals. */
        for (int ms = 0; ms < POLL_MS && g_running; ms += 50)
            usleep(50 * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);

    return rc;
}

