static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to a 16-bit register address */
static int opt3101_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit register address */
static int opt3101_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Initialize the OPT3101 sensor */
static int opt3101_init(int handle) {
    uint16_t device_id = 0;
    int ret;

    /* Read device ID to verify sensor presence */
    ret = opt3101_read_reg16(handle, REG_DEVICE_ID, &device_id);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read device ID (I2C bus error).\n");
        return -1;
    }
    if (device_id != OPT3101_DEVICE_ID) {
        fprintf(stderr, "Error: Unexpected device ID 0x%04X (expected 0x%04X).\n",
                device_id, OPT3101_DEVICE_ID);
        return -1;
    }

    /* Reset the device */
    ret = opt3101_write_reg16(handle, REG_COMMAND, CMD_RESET);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to reset device.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset to complete */

    /* Configure range and ADC settings */
    ret = opt3101_write_reg16(handle, REG_RANGE_CONFIG, 0x0001);
    if (ret < 0) return -1;
    ret = opt3101_write_reg16(handle, REG_ADC_GAIN, 0x0001);
    if (ret < 0) return -1;
    ret = opt3101_write_reg16(handle, REG_ADC_MISC, 0x0000);
    if (ret < 0) return -1;
    ret = opt3101_write_reg16(handle, REG_SYSTEM_CONFIG, 0x0001);
    if (ret < 0) return -1;

    /* Start continuous measurement */
    ret = opt3101_write_reg16(handle, REG_COMMAND, CMD_START_MEASUREMENT);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }

    return 0;
}

/* Read distance and ambient light data from the OPT3101 */
static int opt3101_read_data(int handle, uint16_t *distance, uint16_t *ambient) {
    uint16_t dist = 0, amb = 0;
    int ret;

    /* Read distance from channel 0 */
    ret = opt3101_read_reg16(handle, REG_RESULT_CH0, &dist);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    /* Read ambient light */
    ret = opt3101_read_reg16(handle, REG_RESULT_AMBIENT, &amb);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read ambient light.\n");
        return -1;
    }

    *distance = dist;
    *ambient = amb;
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x48 */
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the OPT3101 sensor */
    if (opt3101_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: OPT3101 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("OPT3101 ToF sensor initialized. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t distance = 0, ambient = 0;
        int ret = opt3101_read_data(i2c_handle, &distance, &ambient);

        if (ret == 0) {
            printf("Distance: %u, Ambient: %u\n", distance, ambient);
        } else {
            fprintf(stderr, "Error: Failed to read data.\n");
        }

        gpioDelay(500000); /* 500 ms delay */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

