/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Trigger: GPIO 17 (BCM)
 * Echo:    GPIO 18 (BCM)
 *
 * NOTE: The HC-SR04 echo pin requires a 5 V logic-level signal, but the
 * Pi GPIO is only 3.3 V tolerant.  A 1 kΩ series resistor MUST be placed
 * between the Pi echo pin and the HC-SR04 echo pin within the library's
 * call() so that the Pi never sees a voltage above 3.3 V.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define READ_INTERVAL_S  1           /* 1 second between readings      */
#define ECHO_TIMEOUT_US  200000      /* 200 ms timeout for echo rising  */
#define ECHO_TIMEOUT_FALL_US 200000 /* 200 ms timeout for echo falling */
#define MAX_RANGE_US     38000      /* 38 ms ≈ 4 m round-trip max     */
#define MIN_RANGE_US     0           /* Guard against negative pulses   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Microsecond sleep (busy-wait, acceptable for short delays here)     */
/* ------------------------------------------------------------------ */
static inline void delay_us(unsigned int us)
{
    while (us > 0) {
        unsigned int chunk = (us > 1000) ? 1000 : us;
        gpioDelay(chunk);
        us -= chunk;
    }
}

/* ------------------------------------------------------------------ */
/* Read distance from HC-SR04                                          */
/* Returns distance in µs on success, or -1 on timeout / error.       */
/* ------------------------------------------------------------------ */
static long read_distance(void)
{
    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger pin LOW\n");
        return -1;
    }
    delay_us(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger pin HIGH\n");
        return -1;
    }
    delay_us(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger pin LOW\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_FALL_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;

    /* Sanity check: pulse must be within HC-SR04 valid range */
    if (pulse_us <= MIN_RANGE_US || pulse_us > MAX_RANGE_US) {
        fprintf(stderr, "Error: invalid pulse duration %u µs (out of range)\n",
                pulse_us);
        return -1;
    }

    return (long)pulse_us;
}

/* ------------------------------------------------------------------ */
/* Convert distance in µs to centimetres                              */
/* Speed of sound = 343 m/s = 0.0343 cm/µs (at 20 °C)                  */
/* ------------------------------------------------------------------ */
static float distance_to_cm(long us)
{
    return (float)us * 0.0343f;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Ultrasonic Distance Sensor Reader\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        long distance_us = read_distance();

        if (distance_us >= 0) {
            float distance_cm = distance_to_cm(distance_us);
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("[%s] Distance: %.2f cm (raw: %ld µs)\n",
                   ts, distance_cm, distance_us);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: read failed, will retry next cycle\n");
        }

        /* Sleep for the remainder of the 1-second interval */
        sleep(READ_INTERVAL_S);
    }

    /* Graceful shutdown: ensure trigger is LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

