/*
 * Raspberry Pi 3 Model B+ - IWR1443 mmWave Radar Intrusion Detector
 *
 * Reads range-profile frames over UART (/dev/serial0), detects targets
 * within 1.0 m, logs to intrusion_log.csv, and pulses an alert LED on GPIO 17.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_intrusion radar_intrusion.c
 * Run:    ./radar_intrusion
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>

#define UART_DEVICE      "/dev/serial0"
#define GPIO_LED         17
#define DISTANCE_THRESHOLD_M 1.0f
#define NUM_RANGE_BINS   64
#define FRAME_SIZE       (8 + (NUM_RANGE_BINS * 2))   /* 8-byte magic + 64 x 2 bytes */
#define LOG_FILE         "intrusion_log.csv"
#define POLL_TIMEOUT_SEC 1
#define POLL_TIMEOUT_USEC 0
#define LED_ON_SEC       2
#define LED_ON_USEC      0

/* IWR1443 range-profile frame magic word (8 bytes, little-endian) */
static const uint8_t MAGIC_WORD[8] = {
    0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static int  g_led_fd  = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* UART initialization                                                 */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open(UART)");
        return -1;
    }

    /* Clear O_NONBLOCK for blocking reads */
    if (fcntl(fd, F_SETFL, 0) == -1) {
        perror("fcntl(F_SETFL)");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    /* 115200 baud, 8N1, raw mode */
    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);

    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  (CLOCAL | CREAD | CS8);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;   /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* GPIO LED control                                                   */
/* ------------------------------------------------------------------ */
static int init_led(void)
{
    /* pigpio library is not required; we use the POSIX sysfs GPIO */
    /* interface (gpio) if available, else fall back to a simple sysfs */
    /* approach.  pigpio is not a system library, so we keep it out. */

    /* Check if we have /sys/class/gpio/gpiochip0/gpio17 */
    if (access("/sys/class/gpio/gpiochip0/gpio17", F_OK | W_OK | X_OK) != 0) {
        /* Not available - fall back to a simple sysfs write */
        /* (avoids pigpio dependency) */
        return -1;
    }

    FILE *fp = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (!fp) {
        perror("fopen(direction)");
        return -1;
    }
    if (fprintf(fp, "out") < 0) {
        perror("fprintf(direction)");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    fp = fopen("/sys/class/gpio/gpio17/value", "w");
    if (!fp) {
        perror("fopen(value)");
        return -1;
    }
    if (fprintf(fp, "0") < 0) {
        perror("fprintf(value init)");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    return 0;
}

static void led_on(void)
{
    FILE *fp = fopen("/sys/class/gpio/gpio17/value", "w");
    if (fp) {
        if (fprintf(fp, "1") < 0)
            perror("fprintf(value on)");
        fclose(fp);
    }
}

static void led_off(void)
{
    FILE *fp = fopen("/sys/class/gpio/gpio17/value", "w");
    if (fp) {
        if (fprintf(fp, "0") < 0)
            perror("fprintf(value off)");
        fclose(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Frame processing                                                   */
/* ------------------------------------------------------------------ */
static bool find_magic_word(const uint8_t *buf, size_t len)
{
    if (len < 8)
        return false;

    for (size_t i = 0; i <= len - 8; i++) {
        if (memcmp(buf + i, MAGIC_WORD, 8) == 0)
            return true;
    }
    return false;
}

/*
 * Parse 64 little-endian 16-bit distance bins.
 * Returns true if any bin is within DISTANCE_THRESHOLD_M.
 */
static bool detect_intrusion(const uint8_t *frame, size_t len)
{
    if (len < FRAME_SIZE)
        return false;

    const uint16_t *bins = (const uint16_t *)(frame + 8);

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        float distance = (float)bins[i] * 0.0323f; /* ~3.23 cm per bin */
        if (distance < DISTANCE_THRESHOLD_M)
            return true;
    }
    return false;
}

static void log_intrusion(float distance_m)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(intrusion_log.csv)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", ts, distance_m) < 0)
        perror("fprintf(log)");

    if (fclose(fp) != 0)
        perror("fclose(log)");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (init_led() == -1) {
        fprintf(stderr, "Warning: GPIO LED initialization failed (sysfs). "
                        "Continuing without LED.\n");
    }

    printf("Radar intrusion detection started. Press Ctrl+C to exit.\n");

    uint8_t frame[FRAME_SIZE];
    size_t  frame_len = 0;

    while (g_running) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(g_uart_fd, &rfds);

        struct timeval tv = { .tv_sec = POLL_TIMEOUT_SEC, .tv_usec = POLL_TIMEOUT_USEC };

        int rv = select(g_uart_fd + 1, &rfds, NULL, NULL, &tv);
        if (rv == -1) {
            if (errno == EINTR)
                continue;
            perror("select");
            break;
        }
        if (rv == 0)
            continue;   /* timeout - no data */

        ssize_t n = read(g_uart_fd, frame + frame_len, FRAME_SIZE - frame_len);
        if (n == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                /* No data available right now */
            } else if (errno == EINTR) {
                continue;
            } else {
                perror("read(UART)");
                break;
            }
        } else if (n == 0) {
            /* EOF on UART (should not happen on a serial port) */
            fprintf(stderr, "UART read returned 0 (EOF)\n");
            break;
        }

        frame_len += (size_t)n;

        /* Try to parse as many complete frames as we have data */
        while (frame_len >= FRAME_SIZE) {
            if (!find_magic_word(frame, frame_len)) {
                /* Discard partial data without magic word */
                memmove(frame, frame + 1, frame_len - 1);
                frame_len -= 1;
                continue;
            }

            /* Shift to start of frame */
            memmove(frame, frame + 8, frame_len - 8);
            frame_len -= 8;

            if (detect_intrusion(frame, frame_len)) {
                float distance = (float)frame[8] * 0.0323f;
                printf("Intrusion detected! Distance: %.2f m\n", distance);
                log_intrusion(distance);
                led_on();
                /* Keep LED on for 2 seconds (interruptible) */
                for (int s = 0; s < LED_ON_SEC && g_running; s++)
                    sleep(1);
                led_off();
            }
        }

        /* If we have partial data without a full frame, keep it */
        if (frame_len > 0 && frame_len < FRAME_SIZE)
            memmove(frame, frame + FRAME_SIZE - frame_len, frame_len);
    }

    /* Cleanup */
    if (g_uart_fd != -1) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_led_fd != -1) {
        led_off();
        close(g_led_fd);
        g_led_fd = -1;
    }

    printf("Radar intrusion detection stopped.\n");
    return EXIT_SUCCESS;
}

