/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance logger
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2 (I2C bus 1 SDA, physical pin 3)
 *   ICU-20201 SCL  -> GPIO 3 (I2C bus 1 SCL, physical pin 5)
 *   ICU-20201 VDD  -> 3.3 V (physical pin 1)
 *   ICU-20201 GND  -> GND  (physical pin 6)
 *   Alert output   -> GPIO 17 (physical pin 11) via a logic-level MOSFET
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_logger distance_logger.c -lpigpio -lrt
 *   (pigpio must be installed and the program run as root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x28          /* ICU-20201 default 7-bit address   */
#define ALERT_GPIO           17            /* BCM pin for the alert output      */
#define DISTANCE_THRESHOLD   10.0f         /* cm – alert when distance < this   */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between readings           */
#define LOG_FILE             "distance_log.txt"

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_PRODUCT_ID       0x00
#define REG_DISTANCE_MSB     0x04
#define REG_DISTANCE_LSB     0x05
#define REG_STATUS           0x06
#define REG_COMMAND          0x07
#define REG_MEAS_RATE        0x08
#define REG_POWER_MODE       0x09

#define CMD_START_MEAS       0x01          /* start a single measurement cycle  */
#define CMD_STOP_MEAS        0x00          /* stop the measurement engine       */
#define CMD_RESET            0x80          /* software reset                    */

#define EXPECTED_PRODUCT_ID  0x2020        /* ICU-20201 product ID               */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  init_sensor(void);
static int  read_distance(float *distance_cm);
static int  log_distance(float distance_cm);
static void trigger_alert(float distance_cm);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor init / reset -------------------------- */
static int init_sensor(void)
{
    /* Software reset */
    if (i2cWriteByteData(g_i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "[ERROR] Sensor reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(20000);  /* 20 ms settle after reset */

    /* Verify product ID */
    int product_id = i2cReadByteData(g_i2c_handle, REG_PRODUCT_ID);
    if (product_id < 0) {
        fprintf(stderr, "[ERROR] Failed to read product ID: %s\n", strerror(errno));
        return -1;
    }
    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr, "[ERROR] Unexpected product ID 0x%02X (expected 0x%02X) – wrong sensor?\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }

    /* Power mode: normal operation (0x00) */
    if (i2cWriteByteData(g_i2c_handle, REG_POWER_MODE, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set power mode: %s\n", strerror(errno));
        return -1;
    }

    /* Measurement rate: 0x00 → default / continuous */
    if (i2cWriteByteData(g_i2c_handle, REG_MEAS_RATE, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set measurement rate: %s\n", strerror(errno));
        return -1;
    }

    /* Start a single measurement cycle so we have a valid reading */
    if (i2cWriteByteData(g_i2c_handle, REG_COMMAND, CMD_START_MEAS) < 0) {
        fprintf(stderr, "[ERROR] Failed to start measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(50000);  /* 50 ms for first measurement to complete */
    return 0;
}

/* --------------------------- Read distance -------------------------------- */
static int read_distance(float *distance_cm)
{
    if (distance_cm == NULL) {
        return -1;
    }

    /* Trigger a new single measurement */
    if (i2cWriteByteData(g_i2c_handle, REG_COMMAND, CMD_START_MEAS) < 0) {
        fprintf(stderr, "[ERROR] Failed to trigger measurement: %s\n", strerror(errno));
        return -1;
    }

    /* Poll the status register (0x06) for completion */
    for (int i = 0; i < 50; i++) {
        int status = i2cReadByteData(g_i2c_handle, REG_STATUS);
        if (status < 0) {
            fprintf(stderr, "[ERROR] Failed to read status: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x01) != 0) {  /* bit 0 = measurement complete */
            break;
        }
        gpioDelay(2000);  /* 2 ms */
    }

    if ((i2cReadByteData(g_i2c_handle, REG_STATUS) & 0x01) == 0) {
        fprintf(stderr, "[WARN] Measurement did not complete within timeout\n");
        return -1;
    }

    /* Read 16-bit distance (MSB at 0x04, LSB at 0x05) */
    int msb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "[ERROR] Failed to read distance MSB: %s\n", strerror(errno));
        return -1;
    }
    int lsb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "[ERROR] Failed to read distance LSB: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | (uint16_t)lsb;
    /* ICU-20201 distance register: 0 = no object, 1 = object detected,
     * 2 = out of range, 3 = reserved, 4–65535 = distance in mm */
    if (raw == 0) {
        *distance_cm = -1.0f;
        return 0;
    }
    if (raw == 0xFFFF) {
        *distance_cm = -2.0f;
        return 0;
    }
    /* Distance register is in mm; convert to cm */
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

/* --------------------------- Log distance --------------------------------- */
static int log_distance(float distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Trigger alert -------------------------------- */
static void trigger_alert(float distance_cm)
{
    if (distance_cm < 0.0f) {
        return;  /* no valid reading – no alert */
    }
    if (distance_cm < DISTANCE_THRESHOLD) {
        if (gpioWrite(ALERT_GPIO, 1) != 0) {
            fprintf(stderr, "[ERROR] gpioWrite(%d, 1) failed\n", ALERT_GPIO);
        }
    } else {
        if (gpioWrite(ALERT_GPIO, 0) != 0) {
            fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        }
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    /* Stop the measurement engine */
    if (g_i2c_handle >= 0) {
        (void)i2cWriteByteData(g_i2c_handle, REG_COMMAND, CMD_STOP_MEAS);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Release GPIO */
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed – check wiring and I2C address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Distance logger started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* Main loop */
    while (g_running) {
        float distance_cm = 0.0f;

        if (read_distance(&distance_cm) != 0) {
            fprintf(stderr, "[WARN] Read failed – will retry next cycle\n");
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "[WARN] Logging failed\n");
            }
            trigger_alert(distance_cm);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

