{
    FILE *fp = fopen(path, "r");
    if (fp != NULL) {
        fclose(fp);
        return 0;                       /* file already exists */
    }

    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error creating log file '%s': %s\n",
                path, strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp,distance_mm\n");
    fclose(fp);
    return 0;
}

