/*
 * Raspberry Pi 4 Model B – TDK InvenSense CH201 ultrasonic ToF sensor reader.
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   CH201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode  -> GPIO 18 (BCM) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201_reader ch201_reader.c -lpigpio -lrt
 * Run:    sudo ./ch201_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1          /* /dev/i2c-1 on RPi 4 */
#define CH201_ADDR           0x28       /* CH201 default 7-bit I2C address */
#define LED_GPIO             18         /* BCM pin for the LED */
#define SAMPLE_PERIOD_US     100000     /* 100 ms between samples */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000      /* 10 ms between retries */
#define LED_HALF_PERIOD_US   1000       /* 1 ms half-period for fast blink */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_PRODUCT_ID  0x00
#define CH201_REG_DISTANCE    0x0A
#define CH201_REG_LED_FREQ    0x0B
#define CH201_REG_MODE        0x0C
#define CH201_REG_INT_STATUS  0x0D

#define CH201_PRODUCT_ID      0x2010    /* expected product ID */
#define CH201_MODE_CONTINUOUS 0x01      /* bit 0: continuous measurement */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(reg 0x%02X) failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char wbuf[1] = { (char)reg };
    char rbuf[2] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteDevice(handle, wbuf, 1) != 0) {
            fprintf(stderr, "[WARN] i2cWriteDevice(reg 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(handle, rbuf, 2) == 2) {
            *out = ((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice(reg 0x%02X) failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* --------------------------- Sensor operations --------------------------- */
static int ch201_init(int handle)
{
    uint16_t product_id = 0;
    if (i2c_read_reg16(handle, CH201_REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read CH201 product ID – sensor absent or bus error.\n");
        return -1;
    }
    if (product_id != CH201_PRODUCT_ID) {
        fprintf(stderr, "[ERROR] Unexpected product ID 0x%04X (expected 0x%04X).\n",
                product_id, CH201_PRODUCT_ID);
        return -1;
    }
    printf("[INFO] CH201 detected (product ID 0x%04X).\n", product_id);

    /* Start continuous measurement mode */
    if (i2c_write_reg16(handle, CH201_REG_MODE, CH201_MODE_CONTINUOUS) != 0) {
        fprintf(stderr, "[ERROR] Failed to set continuous mode.\n");
        return -1;
    }
    gpioDelay(10000);  /* allow first measurement to complete */
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t raw = 0;
    if (i2c_read_reg16(handle, CH201_REG_DISTANCE, &raw) != 0) {
        fprintf(stderr, "[ERROR] Failed to read distance register.\n");
        return -1;
    }
    *distance_mm = raw;
    return 0;
}

/* --------------------------- LED control --------------------------------- */
static void led_set(int gpio, int on)
{
    if (gpioWrite(gpio, on ? 1 : 0) != 0)
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed: %s\n",
                gpio, on, strerror(errno));
}

/* --------------------------- Main loop ----------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                LED_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_set(LED_GPIO, 0);  /* start with LED off */

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus %d, addr 0x%02X) failed: %s\n",
                I2C_BUS, CH201_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] CH201 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("[INFO] Sampling every %d ms. Press Ctrl+C to exit.\n", SAMPLE_PERIOD_US / 1000);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t distance = 0;
        if (ch201_read_distance(g_i2c_handle, &distance) != 0) {
            /* Keep LED off on read failure for safety */
            led_set(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Map distance to LED frequency: closer -> faster blink */
        int led_freq_hz = 1000;  /* max 1 kHz */
        if (distance > 0) {
            /* 100 mm -> 1 kHz, 200 mm -> 500 Hz, 300 mm -> 200 Hz, 400 mm -> 100 Hz */
            led_freq_hz = 1000 - (int)((distance / 100.0) * 900.0);
            if (led_freq_hz < 100)
                led_freq_hz = 100;
            if (led_freq_hz > 1000)
                led_freq_hz = 1000;
        }

        /* Blink exactly one half-cycle per iteration for smooth timing */
        led_set(LED_GPIO, 1);
        gpioDelay(LED_HALF_PERIOD_US * 2 / led_freq_hz);
        led_set(LED_GPIO, 0);
        gpioDelay(SAMPLE_PERIOD_US - (LED_HALF_PERIOD_US * 2 / led_freq_hz));

        /* Timestamped output */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Distance: %u mm  |  LED freq: %d Hz\n",
               ts, distance, led_freq_hz);
        fflush(stdout);
    }

    /* --- Cleanup --- */
    printf("\n[INFO] Shutting down...\n");
    led_set(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

