#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "proximity_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms  */
#define DEBOUNCE_DELAY_US 50000 /* 50 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one CSV line: timestamp,sensor_id,event_type                 */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(int sensor_id, const char *event_type)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor with software debounce                               */
/* Returns 1 if obstacle detected (HIGH), 0 if clear (LOW), -1 error. */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio_pin)
{
    int first, second;

    first = gpioRead(gpio_pin);
    if (first < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n",
                gpio_pin, pigpio_error(first));
        return -1;
    }

    gpioDelay(DEBOUNCE_DELAY_US);

    second = gpioRead(gpio_pin);
    if (second < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n",
                gpio_pin, pigpio_error(second));
        return -1;
    }

    /* Only log on a confirmed state change */
    if (first == second)
        return first;

    return first;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if init failed                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Best-effort release of GPIO resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state_1 = -1, last_state_2 = -1;
    int ret;

    /* ---- Install signal handlers ---- */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "signal(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "signal(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", pigpio_error(ret));
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Proximity monitoring started. Logging to %s\n", LOG_FILE);

    /* ---- Main polling loop ---- */
    while (program_running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 >= 0) {
            if (s1 != last_state_1) {
                if (log_event(1, s1 == 1 ? "DETECTED" : "CLEARED") != 0)
                    fprintf(stderr, "Failed to log event for sensor 1\n");
                last_state_1 = s1;
            }
        } else {
            fprintf(stderr, "Sensor 1 read error — skipping cycle\n");
        }

        if (s2 >= 0) {
            if (s2 != last_state_2) {
                if (log_event(2, s2 == 1 ? "DETECTED" : "CLEARED") != 0)
                    fprintf(stderr, "Failed to log event for sensor 2\n");
                last_state_2 = s2;
            }
        } else {
            fprintf(stderr, "Sensor 2 read error — skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    fprintf(stdout, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

