#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

#define VL53L5CX_SOFT_RESET 0x000B
#define VL53L5CX_SYSTEM_START 0x0087
#define VL53L5CX_SYSTEM_CONFIG 0x0088
#define VL53L5CX_RANGE_CONFIG_A 0x0089
#define VL53L5CX_RANGE_CONFIG_B 0x008A
#define VL53L5CX_RANGE_START 0x008E
#define VL53L5CX_RESULT_RANGE_STATUS 0x0089
#define VL53L5CX_RESULT_DISTANCE 0x0096

#define VL53L5CX_RANGE_STATUS_DATA_READY 0x01

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value) {
    uint8_t buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

static int vl53l5cx_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, 0x010F, &part_id) != 0) {
        return -1;
    }
    if (part_id != 0xEA) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0xEA)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, VL53L5CX_SOFT_RESET, 0x00) != 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, VL53L5CX_SOFT_RESET, 0x01) != 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, VL53L5CX_SYSTEM_START, 0x00) != 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, VL53L5CX_RANGE_CONFIG_A, 0x0A) != 0) return -1;
    if (i2c_write_reg8(fd, VL53L5CX_RANGE_CONFIG_B, 0x00) != 0) return -1;

    if (i2c_write_reg8(fd, VL53L5CX_SYSTEM_CONFIG, 0x00) != 0) return -1;

    if (i2c_write_reg8(fd, VL53L5CX_RANGE_START, 0x01) != 0) return -1;

    return 0;
}

static int vl53l5cx_read_data(int fd, uint16_t *distances) {
    uint8_t status;
    uint16_t timeout = 100;
    while (timeout-- > 0) {
        if (i2c_read_reg8(fd, VL53L5CX_RESULT_RANGE_STATUS, &status) != 0) {
            return -1;
        }
        if (status & VL53L5CX_RANGE_STATUS_DATA_READY) {
            break;
        }
        usleep(1000);
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    for (int i = 0; i < 64; i++) {
        if (i2c_read_reg16(fd, VL53L5CX_RESULT_DISTANCE + (uint16_t)(i * 2), &distances[i]) != 0) {
            return -1;
        }
    }
    return 0;
}

int main(void) {
    int fd = -1;
    uint16_t distances[64];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (vl53l5cx_init(fd) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(fd);
        return 1;
    }

    printf("VL53L5CX initialized. Reading 64-zone data every 500ms. Press Ctrl+C to exit.\n");

    while (running) {
        if (vl53l5cx_read_data(fd, distances) == 0) {
            printf("Distances: ");
            for (int i = 0; i < 64; i++) {
                printf("%u ", distances[i]);
            }
            printf("\n");
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read data\n");
        }
        usleep(500000);
    }

    printf("\nExiting...\n");
    i2c_write_reg8(fd, VL53L5CX_RANGE_START, 0x00);
    close(fd);
    return 0;
}

