#include <signal.h>
#include <unistd.h>
#include <string.h>

/* MLX75030 I2C address (7-bit) */
#define MLX75030_ADDR 0x48

/* Register addresses (16-bit, big-endian on the bus) */
#define MLX75030_REG_DISTANCE 0x0001
#define MLX75030_REG_STATUS   0x0002
#define MLX75030_REG_CONFIG   0x0003

/* Status register bits */
#define MLX75030_STATUS_BUSY  0x01
#define MLX75030_STATUS_ERROR 0x02

/* Configuration: enable distance measurement, 100 ms period */
#define MLX75030_CONFIG_VALUE 0x0001

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling period in microseconds (100 ms) */
