            gpioDelay(10000);
            continue;
        }

        /* Read distance */
        if (read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error: failed to read distance measurement.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
