#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L4CX register addresses (16-bit, big-endian on the bus) */
#define VL53L4CX_REG_SOFT_RESET              0x000B
#define VL53L4CX_REG_I2C_SLAVE_DEVICE_MODEL  0x001E
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS 0x0088
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK  0x0096

#define VL53L4CX_MODEL_ID                   0xEA
#define VL53L4CX_SOFT_RESET_VALUE            0x00
#define VL53L4CX_SOFT_RESET_RELEASE         0x01
#define VL53L4CX_POLL_DELAY_US              500000
#define VL53L4CX_MAX_RETRIES                3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit register address (pigpio i2cWriteWordData uses
 * little-endian byte order; the VL53L4CX expects big-endian, so we swap). */
static int vl53l4cx_write_reg16(uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(g_i2c_handle, (char *)buf, 4);
}

/* Read a 16-bit value from a 16-bit register address. */
static int vl53l4cx_read_reg16(uint16_t reg, uint16_t *value)
{
    uint8_t reg_buf[2];
    uint8_t data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, (char *)reg_buf, 2) < 0)
        return -1;

    if (i2cReadDevice(g_i2c_handle, (char *)data_buf, 2) != 2)
        return -1;

    *value = ((uint16_t)data_buf[0] << 8) | data_buf[1];
    return 0;
}

static int vl53l4cx_init(void)
{
    uint16_t model_id = 0;

    if (vl53l4cx_read_reg16(VL53L4CX_REG_I2C_SLAVE_DEVICE_MODEL, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register\n");
        return -1;
    }

    if (model_id != VL53L4CX_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, VL53L4CX_MODEL_ID);
        return -1;
    }

    if (vl53l4cx_write_reg16(VL53L4CX_REG_SOFT_RESET, VL53L4CX_SOFT_RESET_VALUE) < 0) {
        fprintf(stderr, "Error: failed to write soft reset value\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms settle */

    if (vl53l4cx_write_reg16(VL53L4CX_REG_SOFT_RESET, VL53L4CX_SOFT_RESET_RELEASE) < 0) {
        fprintf(stderr, "Error: failed to release soft reset\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int vl53l4cx_read_distance(uint16_t *distance_mm)
{
    uint16_t status = 0;
    int retries = 0;

    while (retries < VL53L4CX_MAX_RETRIES) {
        if (vl53l4cx_read_reg16(VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Warning: I2C read error (status), retry %d/%d\n",
                    retries + 1, VL53L4CX_MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if ((status & 0x01) == 0) {
            gpioDelay(VL53L4CX_POLL_DELAY_US);
            retries++;
            continue;
        }

        if (vl53l4cx_read_reg16(VL53L4CX_REG_RESULT_FINAL_CROSSTALK, distance_mm) < 0) {
            fprintf(stderr, "Warning: I2C read error (distance), retry %d/%d\n",
                    retries + 1, VL53L4CX_MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (vl53l4cx_write_reg16(VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Warning: I2C write error (clear interrupt), retry %d/%d\n",
                    retries + 1, VL53L4CX_MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Error: failed to read distance after %d retries\n", VL53L4CX_MAX_RETRIES);
    return -1;
}

static void log_distance(uint16_t distance_mm)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("Timestamp: %s.%06ld, Distance: %u mm\n",
           timestamp, ts.tv_nsec / 1000, (unsigned)distance_mm);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, 0x29, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l4cx_init() < 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("VL53L4CX sensor initialised. Polling every %d ms...\n",
           VL53L4CX_POLL_DELAY_US / 1000);

    while (g_running) {
        uint16_t distance = 0;

        if (vl53l4cx_read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Warning: distance read failed, skipping cycle\n");
        }

        gpioDelay(VL53L4CX_POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

