                    retries + 1, VL53L4CX_MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if ((status & 0x01) == 0) {
            gpioDelay(VL53L4CX_POLL_DELAY_US);
            retries++;
            continue;
        }

        if (vl53l4cx_read_reg16(VL53L4CX_REG_RESULT_FINAL_CROSSTALK, distance_mm) < 0) {
            fprintf(stderr, "Warning: I2C read error (distance), retry %d/%d\n",
                    retries + 1, VL53L4CX_MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (vl53l4cx_write_reg16(VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Warning: I2C write error (clear interrupt), retry %d/%d\n",
                    retries + 1, VL53L4CX_MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Error: failed to read distance after %d retries\n", VL53L4CX_MAX_RETRIES);
    return -1;
}

static void log_distance(uint16_t distance_mm)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("Timestamp: %s.%06ld, Distance: %u mm\n",
           timestamp, ts.tv_nsec / 1000, (unsigned)distance_mm);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, 0x29, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l4cx_init() < 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("VL53L4CX sensor initialised. Polling every %d ms...\n",
           VL53L4CX_POLL_DELAY_US / 1000);

    while (g_running) {
        uint16_t distance = 0;

        if (vl53l4cx_read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Warning: distance read failed, skipping cycle\n");
        }

        gpioDelay(VL53L4CX_POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

