#define VL53L1X_SYSTEM_MODE 0x80
#define VL53L1X_RESULT_RANGE_STATUS 0x00
#define VL53L1X_RESULT_DISTANCE 0x96

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
