static int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) return -1;
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_byte(handle, VL53L1X_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write_byte(handle, VL53L1X_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write_byte(handle, VL53L1X_SYSTEM_MODE, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    int timeout = 0;
