#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG -90
#define MAX_ANGLE_DEG  90
#define SERVO_PULSE_US 500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US 200000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output\n", SERVO_PIN);
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        return -1;
    }
    gpioDelay(5);

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * Uses busy-wait with microsecond resolution; pigpio's gpioTick
 * wraps every ~72 minutes so the loop condition is checked every
 * iteration to avoid a 2^32 wraparound stall.
 */
static double read_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start;

    trigger_sensor();

    /* Wait for echo rising edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_duration = (double)(end_tick - start_tick);
    double distance = (pulse_duration * SPEED_OF_SOUND_CM_PER_S) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }

    return distance;
}

static int map_distance_to_angle(double distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double angle = ((distance - MIN_DISTANCE_CM) /
                    (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) *
                   (MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG;

    return (int)(angle + 0.5);
}

static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: servo angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    int pulse_width = (int)((angle - MIN_ANGLE_DEG) *
                            (SERVO_PULSE_US / (MAX_ANGLE_DEG - MIN_ANGLE_DEG)));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void log_data(double distance)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open sensor_data.log: %s\n",
                strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "Timestamp Error, Distance: %.2f cm\n", distance);
    }

    fclose(fp);
}

static void cleanup(void)
{
    /* Ensure servo is stopped before releasing pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = read_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: sensor read timeout or error\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Warning: failed to set servo angle\n");
            }
            log_data(distance);
            printf("Distance: %.2f cm, Angle: %d deg\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking assist system stopped.\n");
    return 0;
}

