#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ID     0x0001
#define VL53L1X_REG_SYSTEM_MODE_START      0x0008
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK  0x0096
#define VL53L1X_REG_RESULT_DISTANCE_SD0    0x009A
#define VL53L1X_REG_RESULT_RANGE_STATUS    0x0089

#define VL53L1X_DEV_ID                      0xEA
#define VL53L1X_SOFT_RESET_VALUE            0x00
#define VL53L1X_SYSTEM_MODE_START_SINGLE    0x01
#define VL53L1X_RESULT_INTERRUPT_CLEAR      0x01
#define VL53L1X_RESULT_RANGE_OK             0x00

#define I2C_BUS                             1
#define I2C_ADDR                            0x29
#define BUZZER_GPIO                         23
#define DISTANCE_THRESHOLD_MM               100
#define POLL_DELAY_US                       50000
#define TIMING_BUDGET_MS                    50

#define MM_TO_CM 0.1f

/* VL53L1X register map (16-bit addresses, 8-bit data) */
static const uint8_t reg_map[][2] = {
    {VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE},
    {VL53L1X_REG_I2C_SLAVE_DEVICE_ID, VL53L1X_DEV_ID},
    {VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_SYSTEM_MODE_START_SINGLE},
    {VL53L1X_REG_RESULT_INTERRUPT_STATUS, 0x00},
    {VL53L1X_REG_RESULT_RANGE_STATUS, 0x00},
    {VL53L1X_REG_RESULT_FINAL_CROSSTALK, 0x00},
    {VL53L1X_REG_RESULT_DISTANCE_SD0, 0x00},
};

#define REG_MAP_SIZE (sizeof(reg_map) / sizeof(reg_map[0]))

/* VL53L1X driver state */
typedef struct {
    int i2c_fd;
    uint8_t *mem;
    size_t mem_len;
    volatile sig_atomic_t running;
} vl53l1x_state_t;

static volatile sig_atomic_t g_running = 1;
static int mq_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val) {
    uint8_t buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int vl53l1x_write_reg(vl53l1x_state_t *st, uint16_t reg, uint8_t val) {
    if (i2c_write_reg8(st->i2c_fd, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg8(vl53l1x_state_t *st, uint16_t reg, uint8_t *val) {
    if (i2c_read_reg8(st->i2c_fd, reg, val) < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(vl53l1x_state_t *st) {
    st->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (st->i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(st->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(st->i2c_fd);
        st->i2c_fd = -1;
        return -1;
    }

    /* Probe sensor by reading the device ID register */
    uint8_t id = 0;
    if (i2c_read_reg8(st->i2c_fd, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, &id) < 0) {
        fprintf(stderr, "VL53L1X not detected at address 0x%02X\n", I2C_ADDR);
        close(st->i2c_fd);
        st->i2c_fd = -1;
        return -1;
    }
    if (id != VL53L1X_DEV_ID) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X)\n", id, VL53L1X_DEV_ID);
        close(st->i2c_fd);
        st->i2c_fd = -1;
        return -1;
    }

    /* Soft reset */
    if (vl53l1x_write_reg(st, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE) < 0) {
        close(st->i2c_fd);
        st->i2c_fd = -1;
        return -1;
    }
    usleep(10000);

    /* Write all registers from the pre-defined map */
    for (size_t i = 0; i < REG_MAP_SIZE; i++) {
        if (vl53l1x_write_reg(st, reg_map[i][0], reg_map[i][1]) < 0) {
            close(st->i2c_fd);
            st->i2c_fd = -1;
            return -1;
        }
    }

    return 0;
}

static int vl53l1x_read_distance(vl53l1x_state_t *st, int *distance_mm) {
    uint8_t status = 0;
    uint8_t dist = 0;

    /* Start a single measurement */
    if (vl53l1x_write_reg(st, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_SYSTEM_MODE_START_SINGLE) < 0) {
        return -1;
    }

    /* Poll for completion with a timeout */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read_reg8(st, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            return -1;
        }
        if ((status & VL53L1X_RESULT_INTERRUPT_CLEAR) != 0) {
            break;
        }
        usleep(1000);
    }

    if ((status & VL53L1X_RESULT_INTERRUPT_CLEAR) == 0) {
        fprintf(stderr, "Timeout waiting for VL53L1X measurement\n");
        return -1;
    }

    if (vl53l1x_read_reg8(st, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
        return -1;
    }
    if (status != VL53L1X_RESULT_RANGE_OK) {
        fprintf(stderr, "VL53L1X range status error: 0x%02X\n", status);
        return -1;
    }

    if (vl53l1x_read_reg8(st, VL53L1X_REG_RESULT_DISTANCE_SD0, &dist) < 0) {
        return -1;
    }

    *distance_mm = (int)dist;
    return 0;
}

static void cleanup(vl53l1x_state_t *st) {
    if (st->i2c_fd >= 0) {
        close(st->i2c_fd);
        st->i2c_fd = -1;
    }
    if (st->mem != NULL && st->mem_len > 0) {
        munmap(st->mem, st->mem_len);
        st->mem = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
    if (mq_fd >= 0) {
        close(mq_fd);
        mq_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    vl53l1x_state_t sensor;
    memset(&sensor, 0, sizeof(sensor));
    sensor.running = 1;

    if (vl53l1x_init(&sensor) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup(&sensor);
        return 1;
    }

    /* Map the sensor's register block */
    uint8_t *map = NULL;
    sensor.mem = map = mmap(NULL, 0x1000, PROT_READ | PROT_WRITE, MAP_SHARED, sensor.i2c_fd, 0);
    if (map == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(sensor.i2c_fd);
        sensor.i2c_fd = -1;
        cleanup(&sensor);
        return 1;
    }
    sensor.mem_len = 0x1000;

    mq_fd = mq_open("/distance_queue", O_CREAT | O_RDWR, 0666, NULL);
    if (mq_fd < 0) {
        fprintf(stderr, "mq_open failed: %s\n", strerror(errno));
        munmap(map, sensor.mem_len);
        close(sensor.i2c_fd);
        sensor.i2c_fd = -1;
        cleanup(&sensor);
        return 1;
    }

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance = 0;
        if (vl53l1x_read_distance(&sensor, &distance) == 0) {
            char msg[32];
            snprintf(msg, sizeof(msg), "%d", distance);
            if (mq_send(mq_fd, msg, strlen(msg) + 1, 0) == -1) {
                fprintf(stderr, "mq_send failed: %s\n", strerror(errno));
            } else {
                printf("Distance: %d mm\n", distance);
            }

            if (distance < DISTANCE_THRESHOLD_MM) {
                gpioWrite(BUZZER_GPIO, 1);
                usleep(500000);
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup(&sensor);
    return 0;
}

