/*
 * Parking sensor using HC-SR04 ultrasonic sensor and a buzzer.
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained; NOT wiringPi)
 *
 * Wiring (BCM numbering):
 *   GPIO 17 -> HC-SR04 TRIG
 *   GPIO 27 -> HC-SR04 ECHO
 *   GPIO 22 -> Buzzer (active-high)
 *
 * Build:  gcc -Wall -Wextra -O2 -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

/* ---- Timing constants ---- */
#define TRIGGER_PULSE_US  10          /* 10 µs HIGH pulse on TRIG */
#define ECHO_TIMEOUT_US   30000       /* 30 ms max echo wait (~5 m round trip) */
#define POLL_INTERVAL_US  100000      /* 100 ms between measurements */
#define BUZZER_THRESHOLD_CM 30.0      /* buzzer ON below this distance */

/* ---- Distance limits ---- */
#define MIN_VALID_CM 2.0
#define MAX_VALID_CM 400.0

/* ---- Speed of sound (cm/s) at ~20 °C ---- */
#define SOUND_SPEED_CM_S 34300.0

/* ---- Shared state between callback and main thread ---- */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_running    = true;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Echo callback (runs in pigpio thread)                               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_echo_seen = true;
    }
    /* level == 2 indicates a watchdog timeout; ignored here */
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04: 10 µs HIGH pulse on TRIG                        */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIG, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIG, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from a 32-bit tick delta                     */
/* Handles pigpio's 32-bit microsecond tick wraparound.                */
/* ------------------------------------------------------------------ */
static double tick_to_cm(uint32_t start, uint32_t end)
{
    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    int32_t diff = (int32_t)(end - start);          /* unsigned wraparound */
    if (diff <= 0) {
        return -1.0;                                /* invalid / no echo */
    }
    /* distance = (time * speed) / 2  (round trip) */
    return ((double)diff * SOUND_SPEED_CM_S) / 2.0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                            */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG) failed.\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed.\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed.\n");
        return -1;
    }

    /* Ensure known initial states */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) init failed.\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER, 0) init failed.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn off buzzer first for safety */
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(BUZZER, 0) during cleanup failed\n");
    }
    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Register echo interrupt callback */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started.  TRIG=GPIO%d  ECHO=GPIO%d  BUZZER=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main measurement loop */
    while (g_running) {
        /* Reset shared state for this cycle */
        g_echo_seen = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        trigger_sensor();

        /* Wait up to ECHO_TIMEOUT_US for the echo callback to set g_echo_seen */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);   /* 100 µs granularity */
            waited += 100;
        }

        if (!g_echo_seen) {
            /* No echo received within timeout -> sensor absent or no object */
            double distance = -1.0;
            printf("Distance:  [timeout]  (sensor absent or no echo)\n");
        } else {
            /* Compute distance from the recorded tick delta */
            double distance = tick_to_cm(g_start_tick, g_end_tick);

            if (distance < 0.0) {
                printf("Distance:  [invalid]  (out of range)\n");
            } else if (distance < MIN_VALID_CM || distance > MAX_VALID_CM) {
                printf("Distance:  %.2f cm  [out of range: %.1f–%.1f cm]\n",
                       distance, MIN_VALID_CM, MAX_VALID_CM);
            } else {
                printf("Distance:  %.2f cm\n", distance);
            }
        }

        /* Activate buzzer while distance < BUZZER_THRESHOLD_CM */
        if (distance >= 0.0 && distance < BUZZER_THRESHOLD_CM) {
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Warning: gpioWrite(BUZZER, 1) failed\n");
            }
        } else {
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Warning: gpioWrite(BUZZER, 0) failed\n");
            }
        }

        /* 100 ms polling interval */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

