#define SERVO_RANGE          20000       /* 20 ms period */
#define DISTANCE_THRESHOLD   20          /* cm */
#define LOG_FILE             "gate_log.txt"
#define POLL_DELAY_US        100000      /* 100 ms */
#define I2C_RETRY_DELAY_US   100000      /* 100 ms */
#define MAX_I2C_RETRIES      3

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_SOFT_RESET              0x000B
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ID     0x010F
#define VL53L1X_REG_SYSTEM_MODE_START      0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS    0x0089
#define VL53L1X_REG_RESULT_DISTANCE        0x0096

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static void log_event(const char *msg);
static void signal_handler(int sig);
static int  i2c_write16(int h, uint16_t reg, uint8_t val);
static int  i2c_read16(int h, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(void);
static int  vl53l1x_read_distance(uint16_t *distance_mm);
static void control_servo(int angle);
static void open_gate(void);
static void close_gate(void);
static void remote_callback(int driver, int command, int data);

/* ---- Logging ---- */
static void log_event(const char *msg)
{
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

/* ---- I2C helpers ---- */
static int i2c_write16(int h, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(h, buf, 3);
}

static int i2c_read16(int h, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(h, cmd, 2) < 0) return -1;
    return i2cReadDevice(h, (char *)buf, len);
}

/* ---- VL53L1X ---- */
static int vl53l1x_init(void)
{
    uint8_t id = 0;
    int rc;

    /* Software reset */
    rc = i2c_write16(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00);
    if (rc < 0) { log_event("VL53L1X soft reset write failed"); return -1; }
    gpioDelay(1000); /* 1 ms */

    rc = i2c_write16(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x01);
    if (rc < 0) { log_event("VL53L1X soft reset release failed"); return -1; }
    gpioDelay(1000);

    /* Wait for device ID register to be readable (~1 ms) */
    rc = i2c_read16(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, &id, 1);
    if (rc < 0) { log_event("VL53L1X not responding"); return -1; }

    /* Start ranging (mode 1: back-to-back) */
    rc = i2c_write16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01);
    if (rc < 0) { log_event("VL53L1X start ranging failed"); return -1; }
    gpioDelay(1000);

    log_event("VL53L1X initialized");
    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status = 0, data[2] = {0, 0};
    int rc;

    rc = i2c_read16(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1);
    if (rc < 0) { log_event("VL53L1X range status read failed"); return -1; }

    if ((status & 0x01) == 0) {
        /* No new data yet */
        return 1;
    }
    if (status & 0x02) {
        log_event("VL53L1X out-of-range");
        return -2;
    }

    rc = i2c_read16(i2c_handle, VL53L1X_REG_RESULT_DISTANCE, data, 2);
    if (rc < 0) { log_event("VL53L1X distance read failed"); return -1; }

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ---- Servo ---- */
static void control_servo(int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse = (int)(500000 + (angle * 1000) / 180);
    gpioServo(SERVO_PIN, pulse);
}

static void open_gate(void)
{
    control_servo(90);
    log_event("Gate opened");
}

static void close_gate(void)
{
    control_servo(0);
    log_event("Gate closed");
}

/* ---- Remote control (v2 callback) ---- */
static void remote_callback(int driver, int command, int data)
{
    (void)driver;
    if (command == 1) {
        open_gate();
    } else if (command == 2) {
        close_gate();
    } else if (command == 3) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Status: %d cm", data);
        log_event(msg);
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Main ---- */
int main(void)
{
    int distance;
    uint16_t dist_mm;
    int rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Failed to open I2C device");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init() < 0) {
        log_event("VL53L1X init failed, continuing with retries");
    }

    /* Configure servo pin */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ_HZ);
    gpioSetPWMrange(SERVO_PIN, SERVO_RANGE);
    close_gate();

    /* Register remote control callback (v2) */
    if (gpioSetAlertFuncEx(SERVO_PIN, remote_callback, NULL) != 0) {
        log_event("Failed to register alert callback");
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate control system started");

    /* Main loop */
    while (running) {
        rc = vl53l1x_read_distance(&dist_mm);
        if (rc == 0) {
            int dist_cm = dist_mm / 10;
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d cm", dist_cm);
            log_event(msg);

            if (dist_cm <= DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        } else if (rc == -2) {
            /* Out-of-range — keep gate closed for safety */
            close_gate();
        } else {
            /* Read error — close gate for safety */
            close_gate();
            gpioDelay(I2C_RETRY_DELAY_US);
            vl53l1x_init();
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    log_event("Shutting down");
    close_gate();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

