/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO 23 (physical pin 16)
 *   ECHO -> GPIO 24 (physical pin 18)
 *
 * NOTE: The HC-SR04 echo pin is 5 V; the Raspberry Pi GPIO pins are 3.3 V.
 *       A level-shifter or voltage divider MUST be used on the ECHO line
 *       before connecting it to the Pi.  A 1:2 divider (5 V -> 2.5 V) is
 *       acceptable; a 1:10 divider (5 V -> 0.5 V) is safer but still
 *       suboptimal.  Use a dedicated 3.3 V supply for the sensor if
 *       possible.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN        23
#define ECHO_PIN        24

#define TRIG_PULSE_US   10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_US 200000     /* 200 ms between measurements    */
#define MIN_PULSE_US     100        /* reject noise < 100 µs          */
#define MAX_PULSE_US     30000      /* reject timeout / no-object > 30 ms */
#define ECHO_TIMEOUT_US  60000      /* warn if no echo within 60 ms    */
#define LOG_FILE         "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between the main thread and the alert callback         */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen    = false;
static volatile bool     g_running      = true;

static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio's notification thread)        */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rising_tick = tick;
        g_echo_seen   = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_falling_tick = tick;
        g_echo_seen    = true;
    }
    /* level == 2 indicates a watchdog timeout; ignore here */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~72 minutes.
 * Compute (b - a) modulo 2^32 so wraparound is handled correctly.
 */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* unsigned subtraction wraps correctly */
}

static void log_distance(float distance_mm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s  Distance: %.2f mm\n", ts, distance_mm);
    fflush(stdout);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%.2f\n", ts, distance_mm);
        fflush(g_log_fp);
    }
}

static void log_warning(const char *msg)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "%s  WARNING: %s\n", ts, msg);
    fflush(stderr);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,WARNING,%s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* gpioTerminate() releases all resources; safe to call once. */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure TRIG as output, ECHO as input with pull-down ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG pin %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on ECHO pin %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure TRIG starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIG pin %d LOW.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50);  /* let sensor settle */

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for both edges ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO pin %d.\n", ECHO_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d | ECHO: GPIO %d | Log: %s\n",
           TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("  Sampling at 5 Hz.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset shared state for this cycle */
        g_rising_tick   = 0;
        g_falling_tick  = 0;
        g_echo_seen     = false;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) < 0) {
            log_warning("TRIG write HIGH failed");
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) < 0) {
            log_warning("TRIG write LOW failed");
        }

        /* Wait for echo or timeout (poll every 1 ms) */
        uint32_t start_wait = gpioTick();
        bool     got_echo   = false;

        while (g_running && !got_echo) {
            if (tick_diff(start_wait, gpioTick()) > ECHO_TIMEOUT_US) {
                log_warning("Echo timeout: no pulse received within 60 ms");
                break;
            }
            gpioDelay(1000);  /* 1 ms */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            /* No echo received — skip this sample */
            continue;
        }

        /* Compute pulse width with wraparound handling */
        uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);

        if (pulse_us < MIN_PULSE_US) {
            log_warning("Pulse too short (noise / out of range)");
        } else if (pulse_us > MAX_PULSE_US) {
            log_warning("Pulse too long (timeout / no object)");
        } else {
            /* distance = pulse_us * 0.0343 mm/µs (HC-SR04 datasheet) */
            float distance_mm = (float)pulse_us * 0.0343f;
            log_distance(distance_mm);
        }

        /* Wait for the remainder of the 200 ms sample period */
        uint32_t elapsed = tick_diff(start_wait, gpioTick());
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    cleanup();
    return EXIT_SUCCESS;
}

