/*
 * Smart Parking Gate - Raspberry Pi 4 Model B
 * Sensor : VL53L1X time-of-flight (I2C bus 1, GPIO2/SDA, GPIO3/SCL)
 * Gate   : Servo motor on GPIO18 (hardware PWM)
 * Control: Shutdown line on GPIO23, interrupt on GPIO24
 *
 * Build  : gcc -O2 -Wall -o parking_gate parking_gate.c -lpigpio -lrt
 * Run    : sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define VL53L1X_INT_PIN      24          /* GPIO24 - VL53L1X interrupt */
#define VL53L1X_SHUTDOWN_PIN 23          /* GPIO23 - VL53L1X shutdown */
#define SERVO_PIN            18          /* GPIO18 - hardware PWM for servo */
#define SERVO_FREQ_HZ        50          /* 50 Hz servo control */
#define SERVO_RANGE          20000       /* 20 ms period in microseconds */
#define SERVO_OPEN_ANGLE     1500        /* 1500 us -> open gate */
#define SERVO_CLOSE_ANGLE    1000        /* 1000 us -> close gate */
#define DISTANCE_THRESHOLD   50          /* cm - open gate when object < 50 cm */
#define DISTANCE_HYSTERESIS   60          /* cm - close gate when > 60 cm */
#define LOG_FILE             "parking_log.txt"
#define POLL_DELAY_US        100000      /* 100 ms between measurements */
#define MAX_RETRIES          3

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_DISTANCE          0x0096

/* Expected model ID for the VL53L1X */
#define VL53L1X_MODEL_ID  0xEA

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static int  servo_set_angle(int gpio, int angle);
static int  log_event(int gate_state, int distance_cm);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (addr) for reg 0x%04X failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X init ------------------------------- */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Read and verify model ID */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "[ERROR] Cannot read VL53L1X model ID - sensor absent or bus error\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "[ERROR] Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Start ranging (bit 0 = 1) */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Failed to start ranging on VL53L1X\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Distance read ------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 50; i++) {
        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "[WARN] VL53L1X data-ready timeout\n");
        return -1;
    }

    /* Read 2-byte distance (mm) from RESULT_DISTANCE */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ----------------------------- Servo control ------------------------------ */
static int servo_set_angle(int gpio, int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 20000) angle = 20000;

    /* Map angle [0..20000] to period [1000..20000 us] */
    int period_us = SERVO_RANGE - angle;
    if (gpioServo(gpio, period_us) != 0) {
        fprintf(stderr, "[ERROR] gpioServo failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static int log_event(int gate_state, int distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s - Gate: %s, Distance: %d cm\n",
                timestamp,
                gate_state ? "OPEN" : "CLOSED",
                distance_cm) < 0) {
        fprintf(stderr, "[ERROR] Failed to write to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure servo is in a safe position */
    gpioServo(SERVO_PIN, 15000); /* 15000 us -> stop */
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    int gate_state = 0;          /* 0 = closed, 1 = open */
    int distance_cm = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Configure GPIO pins */
    if (gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Cannot set GPIO %d as output\n", VL53L1X_SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VL53L1X_SHUTDOWN_PIN, 1) != 0) { /* power on */
        fprintf(stderr, "[FATAL] Cannot write to GPIO %d\n", VL53L1X_SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(100000); /* 100 ms for sensor to boot */

    if (gpioSetMode(VL53L1X_INT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "[FATAL] Cannot set GPIO %d as input\n", VL53L1X_INT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Cannot set GPIO %d as output\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C bus to VL53L1X */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Parking Gate started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[WARN] Distance read failed - retrying\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        distance_cm = distance_mm / 10;

        /* Hysteresis control */
        if (distance_cm < DISTANCE_THRESHOLD && gate_state == 0) {
            if (servo_set_angle(SERVO_PIN, SERVO_OPEN_ANGLE) == 0) {
                gate_state = 1;
                printf("Gate OPEN  - Distance: %d cm\n", distance_cm);
            }
        } else if (distance_cm > DISTANCE_HYSTERESIS && gate_state == 1) {
            if (servo_set_angle(SERVO_PIN, SERVO_CLOSE_ANGLE) == 0) {
                gate_state = 0;
                printf("Gate CLOSED - Distance: %d cm\n", distance_cm);
            }
        }

        if (log_event(gate_state, distance_cm) != 0) {
            fprintf(stderr, "[WARN] Logging failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

