/*
 * Raspberry Pi 4 Model B - VL53L1X Gate Controller
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (address 0x29)
 *   - Gate control: GPIO 18 (HIGH = open, LOW = closed)
 *                 : GPIO 19 (HIGH = closed, LOW = open)
 *
 * Behaviour:
 *   Polls the VL53L1X every 500 ms.  Opens the gate when an object is
 *   within 200 mm of the sensor and closes it otherwise.  Logs each
 *   transition to gate_events.log with an ISO 8601 UTC timestamp.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_controller gate_controller.c \
 *       -li2c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
