#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define GATE_PIN_OPEN        18
#define GATE_PIN_CLOSED      19
#define DISTANCE_THRESHOLD   200   /* mm */
#define POLL_INTERVAL_US     500000 /* 500 ms */
#define LOG_FILE             "gate_events.log"

/* VL53L1X 16-bit register addresses (from ST UAPI) */
#define VL53L1X_REG_SOFT_RESET              0x000B
#define VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x000C
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD  0x000E
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG          0x0014
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO  0x0016
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR       0x0017
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS      0x0018
#define VL53L1X_REG_RESULT_RANGE_STATUS          0x0019
#define VL53L1X_REG_RESULT_DISTANCE              0x0096

/* ----------------------------- Globals ----------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *value);
static int  vl53l1x_read16u(int handle, uint16_t reg, uint16_t *value);
static int  vl53l1x_init(int handle);
static int  vl53l1x_start_ranging(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void log_event(const char *event);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */
/* Write a single byte to a 16-bit VL53L1X register. */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a single byte from a 16-bit VL53L1X register. */
static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

/* Read a 16-bit unsigned value from a 16-bit VL53L1X register. */
static int vl53l1x_read16u(int handle, uint16_t reg, uint16_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ----------------------------- Sensor init ------------------------------- */
static int vl53l1x_init(int handle)
{
    uint8_t  id;
    uint16_t firmware_rev;

    /* Verify sensor identity */
    if (vl53l1x_read16(handle, VL53L1X_REG_SOFT_RESET, &id) < 0) {
        fprintf(stderr, "Error: cannot read SOFT_RESET register (sensor absent or bus error).\n");
        return -1;
    }
    if (id != 0x01) {
        fprintf(stderr, "Error: unexpected SOFT_RESET value 0x%02X (expected 0x01).\n", id);
        return -1;
    }

    /* Read firmware revision */
    if (vl53l1x_read16u(handle, VL53L1X_REG_SOFT_RESET, &firmware_rev) < 0) {
        fprintf(stderr, "Error: cannot read firmware revision.\n");
        return -1;
    }
    printf("VL53L1X detected (firmware rev 0x%04X).\n", firmware_rev);

    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms */

    /* Wait for boot to complete (poll SOFT_RESET until 0x01) */
    for (int i = 0; i < 10; i++) {
        uint8_t status;
        if (vl53l1x_read16(handle, VL53L1X_REG_SOFT_RESET, &status) < 0) {
            fprintf(stderr, "Error: soft-reset poll failed.\n");
            return -1;
        }
        if (status == 0x01)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if (status != 0x01) {
        fprintf(stderr, "Error: sensor did not complete boot.\n");
        return -1;
    }

    /* Set timing budget: 50 ms (0x0032) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x0032) < 0) {
        fprintf(stderr, "Error: setting timing budget failed.\n");
        return -1;
    }

    /* Set inter-measurement period: 500 ms (0x0062) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x0062) < 0) {
        fprintf(stderr, "Error: setting inter-measurement period failed.\n");
        return -1;
    }

    /* Configure GPIO interrupt: new sample ready (bit 0) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x01) < 0) {
        fprintf(stderr, "Error: configuring GPIO interrupt failed.\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Ranging ----------------------------------- */
static int vl53l1x_start_ranging(int handle)
{
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: clearing interrupt failed.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t  status;
    uint8_t  int_status;
    uint16_t dist;

    /* Poll for data-ready (bit 0 of RESULT_INTERRUPT_STATUS) */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &int_status) < 0)
            return -1;
        if (int_status & 0x01)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if (!(int_status & 0x01)) {
        fprintf(stderr, "Error: ranging data not ready.\n");
        return -1;
    }

    /* Read distance (16-bit, big-endian) */
    if (vl53l1x_read16u(handle, VL53L1X_REG_RESULT_DISTANCE, &dist) < 0)
        return -1;

    /* Read range status */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
        return -1;

    /* Clear interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Validate status bits (0x07 = valid data) */
    if ((status & 0x07) != 0x07) {
        fprintf(stderr, "Warning: range status 0x%02X (data not valid).\n", status);
        return -1;
    }

    *distance_mm = dist;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event)
{
    if (!log_file)
        return;

    time_t     now = time(NULL);
    struct tm  utc;
    char       ts[32];

    gmtime_r(&now, &utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &utc);

    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_PIN_OPEN, 0);
    gpioWrite(GATE_PIN_CLOSED, 1);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

