    if (i2c_handle < 0) {
        fprintf(stderr, "Error: opening I2C bus %d at addr 0x%02X failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start ranging */
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error: starting ranging failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure gate pins */
    gpioSetMode(GATE_PIN_OPEN, PI_OUTPUT);
    gpioSetMode(GATE_PIN_CLOSED, PI_OUTPUT);
    gpioWrite(GATE_PIN_OPEN, 0);
    gpioWrite(GATE_PIN_CLOSED, 1);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate controller running.  Press Ctrl+C to exit.\n");

    bool gate_open = false;

    while (!terminate) {
        uint16_t distance;

        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error: reading distance failed.\n");
            log_event("ERROR: distance read failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        bool object_detected = (distance > 0 && distance < DISTANCE_THRESHOLD);

        if (object_detected && !gate_open) {
            gpioWrite(GATE_PIN_OPEN, 1);
            gpioWrite(GATE_PIN_CLOSED, 0);
            gate_open = true;
            log_event("Gate opened");
        } else if (!object_detected && gate_open) {
            gpioWrite(GATE_PIN_OPEN, 0);
            gpioWrite(GATE_PIN_CLOSED, 1);
            gate_open = false;
            log_event("Gate closed");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

