#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

/* VL53L1X I2C address (default 0x29 on SA0 low) */
#define VL53L1X_ADDR 0x29

/* VL53L1X register addresses */
#define VL53L1X_SOFT_RESET       0x0003
#define VL53L1X_SYSTEM_START     0x0000
#define VL53L1X_RESULT_STATUS    0x0089
#define VL53L1X_RESULT_DISTANCE  0x0096

/* GPIO pin definitions (BCM numbering) */
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24

/* Distance thresholds (mm) */
#define DISTANCE_THRESHOLD_NEAR 100
#define DISTANCE_THRESHOLD_FAR  300

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global state */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X helpers                                                     */
/* ------------------------------------------------------------------ */

/* Write a 16-bit register address + 1 byte of data using pigpio's
 * i2cWriteI2CBlockData, which sends (reg_hi, reg_lo, data) as a single
 * SMBus-style transaction. */
static int vl53l1x_write_reg16(uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    int rc = i2cWriteI2CBlockData(i2c_handle, buf[0], &buf[1], 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting at a 16-bit register address.
 * i2cReadI2CBlockData sends the register address as a single byte
 * followed by a repeated-start read of up to 32 bytes. */
static int vl53l1x_read_reg16(uint16_t reg, uint8_t *data, uint8_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    int rc = i2cWriteI2CBlockData(i2c_handle, reg_buf[0], &reg_buf[1], 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    rc = i2cReadI2CBlockData(i2c_handle, reg_buf[0], (char *)data, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if ((uint8_t)rc != len) {
        fprintf(stderr, "I2C read from reg 0x%04X short: got %d, expected %d\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* Soft reset: write 0x00, wait 1 ms, write 0x01. */
static int vl53l1x_soft_reset(void)
{
    if (vl53l1x_write_reg16(VL53L1X_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms */
    if (vl53l1x_write_reg16(VL53L1X_SOFT_RESET, 0x01) < 0)
        return -1;
    return 0;
}

/* Start a single measurement. */
static int vl53l1x_start_measurement(void)
{
    return vl53l1x_write_reg16(VL53L1X_SYSTEM_START, 0x01);
}

/* Check data-ready status. Returns 1 if ready, 0 if not, -1 on error. */
static int vl53l1x_data_ready(void)
{
    uint8_t status = 0;
    if (vl53l1x_read_reg16(VL53L1X_RESULT_STATUS, &status, 1) < 0)
        return -1;
    return (status & 0x01) ? 1 : 0;
}

/* Read 16-bit distance in mm. Returns -1 on error. */
static int vl53l1x_read_distance(void)
{
    uint8_t data[2] = {0};
    if (vl53l1x_read_reg16(VL53L1X_RESULT_DISTANCE, data, 2) < 0)
        return -1;
    return (int)((data[0] << 8) | data[1]);
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* ISR                                                                 */
/* ------------------------------------------------------------------ */
static void distance_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user;

    int distance = vl53l1x_read_distance();
    if (distance < 0) {
        fprintf(stderr, "Error reading distance, stopping motor.\n");
        motor_stop();
        return;
    }

    printf("Distance: %d mm\n", distance);

    if (distance < DISTANCE_THRESHOLD_NEAR) {
        motor_forward();
    } else if (distance > DISTANCE_THRESHOLD_FAR) {
        motor_backward();
    } else {
        motor_stop();
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Best-effort cleanup of the VL53L1X */
        (void)vl53l1x_write_reg16(VL53L1X_SYSTEM_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (pigpio_initialized) {
        motor_stop();
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    /* Open I2C bus 1 at the VL53L1X address */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor: soft reset, then start a measurement */
    if (vl53l1x_soft_reset() < 0) {
        fprintf(stderr, "VL53L1X soft reset failed. Check wiring and sensor presence.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);

    /* Ensure motor is stopped initially */
    motor_stop();

    /* Register ISR on rising edge of TRIGGER_PIN */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, distance_isr, NULL) < 0) {
        fprintf(stderr, "Error setting ISR on GPIO %d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    /* Main loop: sleep until signal received */
    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

