/*
 * MPR121 Proximity-Triggered LED Art Installation
 * Board:  Raspberry Pi 3 Model B+
 * I2C:    /dev/i2c-1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * LEDs:   GPIO 17, 18, 27, 22 (4-bit output)
 * Sensor: MPR121 12-electrode capacitive touch controller
 *
 * Build:  gcc -O2 -Wall -o mpr121_art mpr121_art.c -lpigpio -lrt
 * Run:    sudo ./mpr121_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            "/dev/i2c-1"
#define MPR121_ADDR        0x24          /* MPR121 default 7-bit I2C address */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS 0x00          /* 12-bit touch status, bits 11..0 */
#define MPR121_ECR         0x5E          /* Electrode Configuration Register */
#define MPR121_SOFTRESET   0x80          /* Soft reset command */

/* LED GPIO pins (BCM numbering) */
#define LED_BIT0_PIN       17
#define LED_BIT1_PIN       18
#define LED_BIT2_PIN       27
#define LED_BIT3_PIN       22

/* Polling interval (microseconds) */
#define POLL_INTERVAL_US   50000         /* 50 ms */

/* ----------------------------- Globals ---------------------------------- */
static int           g_i2c_fd   = -1;
static FILE         *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  mpr121_write_reg(uint8_t reg, uint8_t value);
static int  mpr121_read_reg(uint8_t reg, uint8_t *value);
static int  mpr121_init(void);
static int  mpr121_read_touch_status(uint16_t *status);
static void set_led_pattern(uint4_t pattern);
static void log_event(uint16_t touch_status);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers -------------------------------- */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "[I2C] write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, value, 1) != 1) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 init -------------------------------- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* Verify sensor is present by reading back ECR */
    uint8_t ecr_val = 0;
    if (mpr121_read_reg(MPR121_ECR, &ecr_val) < 0)
        return -1;
    if (ecr_val == 0x00) {
        fprintf(stderr, "[MPR121] sensor not responding (ECR=0x00)\n");
        return -1;
    }
    printf("[MPR121] detected, ECR=0x%02X\n", ecr_val);

    /*
     * Minimal configuration for 12-electrode touch mode:
     *   ECR[7:4] = 0x0  (baseline tracking off)
     *   ECR[3:2] = 0x0  (debounce off)
     *   ECR[1:0] = 0x0  (auto-config off)
     *   ECR[7:0] = 0x0  (all electrodes enabled, 0uA charge current)
     */
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0)
        return -1;

    gpioDelay(1000);  /* 1 ms settle */
    return 0;
}

/* ----------------------------- Touch read --------------------------------- */
static int mpr121_read_touch_status(uint16_t *status)
{
    uint8_t lo = 0, hi = 0;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS, &lo) < 0)
        return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS + 1, &hi) < 0)
        return -1;
    *status = ((uint16_t)(hi & 0x0F) << 8) | (uint16_t)lo;
    return 0;
}

/* ----------------------------- LED control -------------------------------- */
static void set_led_pattern(uint4_t pattern)
{
    uint8_t val = (uint8_t)pattern;
    gpioWrite(LED_BIT0_PIN,  (val >> 0) & 0x01);
    gpioWrite(LED_BIT1_PIN,  (val >> 1) & 0x01);
    gpioWrite(LED_BIT2_PIN,  (val >> 2) & 0x01);
    gpioWrite(LED_BIT3_PIN,  (val >> 3) & 0x01);
}

/* ----------------------------- Logging ------------------------------------ */
static void log_event(uint16_t touch_status)
{
    time_t     rawtime;
    struct tm *timeinfo;
    char       timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_file, "%s - Touch Status: 0x%03X\n", timestamp, touch_status);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    /* Turn off LEDs */
    gpioWrite(LED_BIT0_PIN, 0);
    gpioWrite(LED_BIT1_PIN, 0);
    gpioWrite(LED_BIT2_PIN, 0);
    gpioWrite(LED_BIT3_PIN, 0);

    /* Release GPIO lines */
    gpioSetMode(LED_BIT0_PIN, PI_INPUT);
    gpioSetMode(LED_BIT1_PIN, PI_INPUT);
    gpioSetMode(LED_BIT2_PIN, PI_INPUT);
    gpioSetMode(LED_BIT3_PIN, PI_INPUT);

    /* Close I2C */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    uint16_t touch_status = 0;
    uint4_t  led_pattern  = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("mpr121_art.log", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIOs as outputs */
    gpioSetMode(LED_BIT0_PIN, PI_OUTPUT);
    gpioSetMode(LED_BIT1_PIN, PI_OUTPUT);
    gpioSetMode(LED_BIT2_PIN, PI_OUTPUT);
    gpioSetMode(LED_BIT3_PIN, PI_OUTPUT);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 art installation running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        if (mpr121_read_touch_status(&touch_status) < 0) {
