#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x60
#define LED_GPIO 27
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_F 0x2F
#define MPR121_NHD_F 0x30
#define MPR121_NCL_F 0x31
#define MPR121_FDL_F 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG3 0x5D
#define MPR121_AFE_CONFIG1 0x5E
#define MPR121_AFE_CONFIG2 0x5F
#define MPR121_AFE_CONFIG3 0x60
#define MPR121_UPLIMIT 0x61
#define MPR121_LPLIMIT 0x62
#define MPR121_TL 0x63
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FFI 0x5D
#define MPR121_SFI 0x5E
#define MPR121_ESI 0x5F

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0TTH, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG3, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG3, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_UPLIMIT, 0xC8) < 0) return -1;
    if (mpr121_write_reg(MPR121_LPLIMIT, 0x32) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_TOUCHTH_0, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_RELEASETH_0, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FFI, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_SFI, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_ESI, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0xFF) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x02) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;
    return 0;
}

static int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading touch status: %d\n", rc);
        return -1;
    }
    *touch_status = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity event detected\n", s);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int device_id = i2cReadByteData(i2c_handle, 0x5D);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        cleanup();
        return 1;
    }
    if (device_id != 0x24) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x24)\n", device_id);
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                printf("Proximity event detected!\n");
                gpioWrite(LED_GPIO, 1);
                log_proximity_event();
                gpioDelay(1000000);
                gpioWrite(LED_GPIO, 0);
            }
        }
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

