    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                printf("Proximity event detected!\n");
                gpioWrite(LED_GPIO, 1);
                log_proximity_event();
                gpioDelay(1000000);
                gpioWrite(LED_GPIO, 0);
            }
        }
