/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi Zero W
 * TRIG: GPIO17 (BCM), ECHO: GPIO18 (BCM) via 1k/2k voltage divider
 * Logs distance (cm) + timestamp to distance_log.txt once per second.
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define MEASURE_PERIOD_S 1.0         /* 1 second between measurements  */
#define LOG_FILE         "distance_log.txt"

/* HC-SR04 timing sanity bounds (round-trip, 1 cm -> 4 m) */
#define MIN_PULSE_US     58          /* ~1.08 m round-trip            */
#define MAX_PULSE_US     25000       /* ~4.23 m round-trip            */

/* pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min */
#define TICKS_PER_US     1

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_gating     = false;   /* echo in flight */

static FILE *g_log_fp = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* ISR: called on every edge of ECHO_PIN                               */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
        g_gating     = true;
    } else if (level == 0 && g_gating) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_echo_seen = true;
        g_gating    = false;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler: request graceful shutdown                           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Convert pigpio tick delta to microseconds, handling wrap-around     */
/* ------------------------------------------------------------------ */
static uint32_t tick_delta_us(uint32_t start, uint32_t end)
{
    return (end >= start) ? (end - start) : (0xFFFFFFFFu - start + end + 1u);
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the TRIG pin                                */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from a valid pulse width in microseconds     */
/* Returns -1.0 on invalid pulse.                                     */
/* ------------------------------------------------------------------ */
static float calculate_distance(uint32_t pulse_us)
{
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US)
        return -1.0f;

    /* speed of sound 343 m/s => 0.0343 cm/us; round-trip / 2 */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file               */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (distance_cm < 0.0f)
        fprintf(g_log_fp, "%s, ERROR: invalid pulse width\n", ts);
    else
        fprintf(g_log_fp, "%s, %.2f cm\n", ts, distance_cm);

    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* pigpio cleanup helper                                                */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR before touching GPIO */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50 * 1000);  /* 50 ms settle */

    /* ---- Register ISR on ECHO pin (both edges) ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed; continuing.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed; continuing.\n");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n", TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        g_echo_seen = false;
        g_gating    = false;

        trigger_sensor();

        /* Wait for echo with 1 s timeout (poll every 10 ms) */
        uint32_t waited = 0;
        while (g_running && !g_echo_seen && waited < (uint32_t)(MEASURE_PERIOD_S * 1e6)) {
            gpioDelay(10000);  /* 10 ms */
            waited += 10000;
        }

        if (!g_running)
            break;

        if (!g_echo_seen) {
            fprintf(g_log_fp, "ERROR: echo timeout\n");
            fflush(g_log_fp);
            continue;
        }

        uint32_t pulse_us = tick_delta_us(g_start_tick, g_end_tick);
        float distance_cm = calculate_distance(pulse_us);

        log_distance(distance_cm);

        printf("Distance: %.2f cm\n", distance_cm);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

