        fprintf(stderr, "Warning: sigaction(SIGTERM) failed; continuing.\n");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n", TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        g_echo_seen = false;
        g_gating    = false;

        trigger_sensor();

        /* Wait for echo with 1 s timeout (poll every 10 ms) */
        uint32_t waited = 0;
        while (g_running && !g_echo_seen && waited < (uint32_t)(MEASURE_PERIOD_S * 1e6)) {
