/*
 * VL53L1X time-of-flight distance sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X XSHUT-> GPIO27 (BCM), active-low: HIGH = enabled
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_reader vl53l1x_reader.c -lvnl1x -lrt
 *
 * Run:
 *   sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#include <vnl1x.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x29
#define XSHUT_GPIO       27
#define POLL_MS          100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Read a 16-bit big-endian register from the VL53L1X.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed: %s",
               reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read (reg 0x%04X) failed: %s",
               reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Write a 16-bit big-endian value to a VL53L1X register.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_write_reg16(int fd, uint16_t reg, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(val >> 8);
    buf[3] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, 4) != 4) {
        syslog(LOG_ERR, "I2C write (reg 0x%04X <- 0x%04X) failed: %s",
               reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read the distance in millimetres from the VL53L1X.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint16_t status = 0;
    int rc;

    rc = vl53l1x_read_reg16(fd, 0x001E, &status);
    if (rc != 0)
        return -1;

    if ((status & 0x07FF) == 0) {
        /* No new data available yet */
        return 1;
    }

    *distance_mm = (uint16_t)(status & 0x07FF);
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    struct vnl1x_context *ctx = NULL;
    int ret = EXIT_FAILURE;

    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    install_signal_handlers();

    /* --- Open I2C bus --- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Cannot open %s: %s", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        syslog(LOG_ERR, "Cannot set I2C slave address 0x%02X: %s",
               VL53L1X_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Initialize VL53L1X driver --- */
    ctx = vnl1x_context_create();
    if (ctx == NULL) {
        syslog(LOG_ERR, "vnl1x_context_create() failed");
        goto cleanup;
    }

    if (vnl1x_context_init(ctx, i2c_fd) != 0) {
        syslog(LOG_ERR, "vnl1x_context_init() failed");
        goto cleanup;
    }

    /* --- Configure XSHUT pin (active-low) --- */
    if (gpioSetMode(XSHUT_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d) failed", XSHUT_GPIO);
        goto cleanup;
    }
    if (gpioWrite(XSHUT_GPIO, 1) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, 1) failed", XSHUT_GPIO);
        goto cleanup;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(i2c_fd, &distance);

        if (rc == 0) {
            struct timeval tv;
            gettimeofday(&tv, NULL);
            time_t now = tv.tv_sec;
            struct tm tm_info;
            localtime_r(&now, &tm_info);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            syslog(LOG_INFO,
                   "%s Distance: %u mm, Status: 0x%04X",
                   ts, distance, (uint16_t)(status & 0x07FF));
        } else if (rc < 0) {
            syslog(LOG_ERR, "Failed to read distance");
        }

        sleep_ms(POLL_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (ctx != NULL)
        vnl1x_context_destroy(ctx);
    if (i2c_fd >= 0)
        close(i2c_fd);

    syslog(LOG_INFO, "Exiting");
    closelog();
    return ret;
}

