#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, message);
    fflush(log_file);
}

static int init_vl53l1x(void) {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance_cm(void) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, 0x88, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: rc=%d\n", rc);
        return -1;
    }
    int raw = (buf[0] << 8) | buf[1];
    return (int)(raw / 10);
}

static void control_gate(int distance_cm) {
    static int gate_state = 0;
    if (distance_cm < DISTANCE_THRESHOLD_CM && gate_state == 0) {
        if (gpioWrite(GATE_GPIO, 1) == 0) {
            gate_state = 1;
            log_message("Gate opened");
        } else {
            log_message("Error: failed to set GPIO24 high");
        }
    } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_state == 1) {
        if (gpioWrite(GATE_GPIO, 0) == 0) {
            gate_state = 0;
            log_message("Gate closed");
        } else {
            log_message("Error: failed to set GPIO24 low");
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() != 0) {
        log_message("Sensor initialization failed");
        cleanup();
        return 1;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_message("Error: failed to set GPIO24 as output");
        cleanup();
        return 1;
    }
    gpioWrite(GATE_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    while (!terminate) {
        int distance = read_distance_cm();
        if (distance >= 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance);
            log_message(msg);
            control_gate(distance);
        } else {
            log_message("Error: failed to read distance");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

