#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <pigpio.h>

#define SI1102_I2C_ADDR_DEFAULT 0x60
#define SI1102_REG_IRQ_STATUS 0x00
#define SI1102_REG_IRQ_ENABLE 0x01
#define SI1102_REG_PROX_DATA 0x02
#define SI1102_REG_COMMAND 0x18
#define SI1102_CMD_RESET 0x01
#define SI1102_CMD_START 0x11
#define SI1102_CMD_PROX_FORCE 0x0B
#define SI1102_REG_HW_KEY 0x17
#define SI1102_HW_KEY_VAL 0x17
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define DEFAULT_THRESHOLD 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int i2c_address = SI1102_I2C_ADDR_DEFAULT;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t data_ready = 0;
static volatile int proximity_value = 0;
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)data_buf[0];
    return 0;
}

static int init_si1102(void) {
    if (i2c_write_reg(SI1102_REG_HW_KEY, SI1102_HW_KEY_VAL) != 0) return -1;
    if (i2c_write_reg(SI1102_REG_COMMAND, SI1102_CMD_RESET) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg(SI1102_REG_COMMAND, SI1102_CMD_START) != 0) return -1;
    if (i2c_write_reg(SI1102_REG_IRQ_ENABLE, 0x01) != 0) return -1;
    return 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    data_ready = 1;
}

static void *data_processing_thread(void *arg) {
    (void)arg;
    while (program_running) {
        if (data_ready) {
            data_ready = 0;
            pthread_mutex_lock(&data_mutex);
            int val = proximity_value;
            pthread_mutex_unlock(&data_mutex);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            const char *status = (val <= threshold) ? "SAFE" : "ALERT";
            fprintf(log_file, "%s, %d, %s\n", timestamp, val, status);
            fflush(log_file);
        }
        gpioDelay(10000);
    }
    return NULL;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", i2c_address, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (init_si1102() != 0) {
        fprintf(stderr, "Si1102 initialisation failed\n");
        cleanup();
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", GPIO_PIN);
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    pthread_t processing_thread;
    if (pthread_create(&processing_thread, NULL, data_processing_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create data processing thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    while (program_running) {
        sleep(1);
    }
    pthread_join(processing_thread, NULL);
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    cleanup();
    return 0;
}

