/*
 * HC-SR04 Ultrasonic Distance Sensor -> Theremin-like Speaker
 * Board:  Raspberry Pi Zero W
 * Pins:    TRIG = GPIO23 (BCM), ECHO = GPIO24 (BCM), PWM = GPIO18 (BCM)
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  200.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define ECHO_TIMEOUT_US  200000           /* 200 ms */
#define TRIGGER_PULSE_US 10
#define PWM_DUTY         500000           /* 50 % of 1 000 000 */
#define PWM_RANGE        1000000
#define SAMPLE_PERIOD_US 50000            /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read distance from HC-SR04.
 * Returns distance in cm on success, or -1.0 on timeout / error.
 */
static float read_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

