/*
 * theremin.c — Raspberry Pi 3 Model B+
 *
 * HC-SR04 ultrasonic distance sensor  ->  piezo buzzer pitch
 *
 * Wiring (BCM numbering):
 *   GPIO18 (PWM0)  -> piezo buzzer (via transistor or driver)
 *   GPIO23         -> HC-SR04 TRIG (3.3 V logic-level output)
 *   GPIO24         -> HC-SR04 ECHO (3.3 V, 5 V tolerant; use divider if
 *                     your HC-SR04 echo is 5 V)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US  100000      /* 100 ms max echo wait */
#define LOOP_DELAY_US    10000       /* 10 ms between readings */
#define MIN_DISTANCE_CM  5.0
#define MAX_DISTANCE_CM  50.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 helpers                                                    */
/* ------------------------------------------------------------------ */

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse width in microseconds
 *   -1   : timeout (no echo received within ECHO_TIMEOUT_US)
 *   -2   : GPIO read error
 */
static long read_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo to go HIGH (rising edge) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* timeout */
    }
    start_tick = gpioTick();

    /* Wait for echo to go LOW (falling edge) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* timeout */
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Compute distance in cm from pulse width in microseconds.
 * Speed of sound = 343 m/s = 0.0343 cm/us  (round-trip, no temperature
 * compensation applied here — acceptable for a theremin-like demo).
 */
static double pulse_to_cm(long pulse_us)
{
    return (double)pulse_us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                     */
/* ------------------------------------------------------------------ */

/*
 * Generate a continuous tone on the buzzer pin using pigpio's hardware
 * PWM.  Returns 0 on success, -1 on failure.
 */
static int set_buzzer_frequency(int frequency_hz)
{
    if (frequency_hz < MIN_FREQUENCY_HZ || frequency_hz > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Frequency %d Hz out of range [%d, %d]\n",
                frequency_hz, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
        return -1;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency_hz) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", frequency_hz);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {   /* 50 % duty cycle */
        fprintf(stderr, "Failed to start PWM on GPIO%d\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static void stop_buzzer(void)
{
    gpioPWM(BUZZER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);                       /* 1 ms settle */

    /* Verify modes were accepted */
    if (gpioGetMode(TRIGGER_PIN) != PI_OUTPUT ||
        gpioGetMode(ECHO_PIN)   != PI_INPUT  ||
        gpioGetMode(BUZZER_PIN) != PI_OUTPUT) {
        fprintf(stderr, "GPIO mode verification failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    double last_valid_distance = 0.0;
    int last_valid_status = 1;             /* 1 = valid, 0 = error */

    while (g_running) {
        /* Trigger the HC-SR04: 10 us high pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        long pulse_us = read_echo_us();

        if (pulse_us < 0) {
            if (pulse_us == -1) {
                fprintf(stderr, "Echo timeout — sensor out of range or not responding\n");
            } else {
                fprintf(stderr, "GPIO read error on echo pin\n");
            }
            last_valid_distance = last_valid_status ? last_valid_distance : 0.0;
            last_valid_status = 0;
        } else {
            double distance = pulse_to_cm(pulse_us);
            last_valid_distance = distance;
            last_valid_status = 1;

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Distance %.2f cm out of practical range [%.1f, %.1f]\n",
                        distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
                distance = (distance < MIN_DISTANCE_CM) ? MIN_DISTANCE_CM : MAX_DISTANCE_CM;
            }

            int frequency = (int)(200.0 + (distance - MIN_DISTANCE_CM) *
                                  (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
            if (set_buzzer_frequency(frequency) != 0) {
                fprintf(stderr, "Failed to set buzzer frequency\n");
            }

            printf("Distance: %.2f cm  Frequency: %d Hz\n", distance, frequency);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    stop_buzzer();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

