/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   GPIO17 -> HC-SR04 TRIG (3.3 V logic level)
 *   GPIO18 <- HC-SR04 ECHO (3.3 V logic level, via 1 kΩ divider if using 5 V VCC)
 *   GND    -> HC-SR04 GND
 *   3.3 V  -> HC-SR04 VCC
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10          /* HC-SR04 requires >= 10 µs */
#define ECHO_TIMEOUT_US   50000       /* 50 ms max echo wait */
#define LOOP_DELAY_US     500000      /* 500 ms between measurements */
#define MIN_VALID_CM      2.0f
#define MAX_VALID_CM      400.0f
#define TOO_CLOSE_CM      10.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Measure the echo pulse duration in microseconds.
 * Returns the pulse width on success, or -1 on timeout / error.
 */
static long measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* --- Wait for echo rising edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance_cm(long pulse_us)
{
    /* Speed of sound at 20 °C ≈ 343 m/s  ->  0.0343 cm/µs */
    return (float)pulse_us * 0.0343f / 2.0f;
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: cannot initialise TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(100000);  /* 100 ms */

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: BCM GPIO%d | Echo: BCM GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        /* --- Issue 10 µs trigger pulse --- */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: cannot set TRIGGER_PIN high\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: cannot set TRIGGER_PIN low\n");
            break;
        }

        /* --- Measure echo --- */
        long pulse_us = measure_echo_us();

        if (pulse_us < 0) {
            fprintf(stderr, "Error: echo measurement failed (timeout)\n");
        } else {
            float distance = calculate_distance_cm(pulse_us);

            if (distance < MIN_VALID_CM || distance > MAX_VALID_CM) {
                printf("Invalid reading: %.2f cm\n", distance);
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < TOO_CLOSE_CM) {
                    printf("  [Too close!]");
                }
                printf("\n");
            }
            fflush(stdout);
        }

        /* --- Wait before next measurement --- */
        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

