#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* mode 0, active-low CS */
#define CS_PIN         8        /* BCM GPIO8 = CE0 */
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_DELAY_US 100000  /* 100 ms */
#define MAX_RETRIES    3

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_PRODUCT_ID      0x00
#define REG_RANGE_STATUS    0x01
#define REG_DISTANCE_MSB    0x02
#define REG_DISTANCE_LSB    0x03
#define REG_CONFIG          0x0A

#define EXPECTED_PRODUCT_ID 0x2020

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address                          */
/* ------------------------------------------------------------------ */
static int icu_write_reg(uint8_t reg, uint8_t value)
{
    char tx[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    char rx[2] = { 0, 0 };

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "CS low failed\n");
        return -1;
    }

    int rc = spiXfer(g_spi_handle, tx, rx, 2);
    if (rc < 0) {
        fprintf(stderr, "SPI write failed (reg 0x%02X): %d\n", reg, rc);
        gpioWrite(CS_PIN, 1);
        return -1;
    }

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "CS high failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit register address                        */
/* ------------------------------------------------------------------ */
static int icu_read_reg(uint8_t reg, uint8_t *value)
{
    char tx[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    char rx[2] = { 0, 0 };

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "CS low failed\n");
        return -1;
    }

    int rc = spiXfer(g_spi_handle, tx, rx, 2);
    if (rc < 0) {
        fprintf(stderr, "SPI read failed (reg 0x%02X): %d\n", reg, rc);
        gpioWrite(CS_PIN, 1);
        return -1;
    }

    *value = (uint8_t)rx[1];
    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "CS high failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ICU-20201 sensor                                     */
/* ------------------------------------------------------------------ */
static int icu_init(void)
{
    uint8_t product_id = 0;

    if (icu_read_reg(REG_PRODUCT_ID, &product_id) < 0) {
        fprintf(stderr, "Cannot read PRODUCT_ID — sensor absent or SPI bus error\n");
        return -1;
    }
    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr, "Unexpected PRODUCT_ID: 0x%02X (expected 0x%02X)\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }

    /* Minimal configuration: enable measurement, set range 200–5000 mm */
    if (icu_write_reg(REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres (200–5000 mm)                          */
/* ------------------------------------------------------------------ */
static int icu_read_distance(void)
{
    uint8_t msb = 0, lsb = 0;
    int distance = -1;

    if (icu_read_reg(REG_DISTANCE_MSB, &msb) < 0) return -1;
    if (icu_read_reg(REG_DISTANCE_LSB, &lsb) < 0) return -1;

    distance = ((int)msb << 8) | (int)lsb;
    if (distance < 200 || distance > 5000) {
        fprintf(stderr, "Distance out of range: %d mm\n", distance);
        return -1;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log                         */
/* ------------------------------------------------------------------ */
static void log_data(int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%d\n", timestamp, distance);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup — close SPI, release GPIO, close log file                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(CS_PIN, 1);
    gpioTerminate();
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure CS pin as output and deassert (high) */
    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(CS_PIN, 1);

    /* Open SPI channel */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (icu_init() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int distance = -1;
        int retries = 0;

        /* Retry on transient SPI errors */
        while (retries < MAX_RETRIES && g_running) {
            distance = icu_read_distance();
            if (distance >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read error, retry %d/%d\n", retries, MAX_RETRIES);
                gpioDelay(10000); /* 10 ms backoff */
            }
        }

        if (distance >= 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

