#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

/* Si1120 I2C address (7-bit) */
#define SI1120_ADDR 0x60

/* Si1120 register addresses */
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_HW_KEY  0x07
#define SI1120_REG_COMMAND 0x30
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_PS1_DATA0 0x26

/* Si1120 command codes */
#define SI1120_CMD_RESET 0x01
#define SI1120_CMD_ALS_FORCE 0x06
#define SI1120_CMD_PS_FORCE 0x05

/* Expected part ID */
#define SI1120_PART_ID 0x0D

/* HW_KEY value for Si1120 */
#define SI1120_HW_KEY_VAL 0x17

/* Retry parameters */
#define I2C_RETRIES 3
#define RETRY_DELAY_US 10000

/* Sampling interval */
#define SAMPLE_INTERVAL_US 500000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a register with retry */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result;
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        if (attempt < I2C_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/* Read a byte from a register with retry */
static int read_register(int handle, uint8_t reg) {
    int result;
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        }
        fprintf(stderr, "Warning: I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        if (attempt < I2C_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

/* Initialize the Si1120 sensor */
static int initialize_sensor(int handle) {
    /* Verify part ID */
    int part_id = read_register(handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Error: Unexpected part ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    /* Write HW_KEY */
    if (write_register(handle, SI1120_REG_HW_KEY, SI1120_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY\n");
        return -1;
    }

    /* Send reset command */
    if (write_register(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Error: Failed to send reset command\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay after reset */

    return 0;
}

/* Read ALS (ambient light) data */
static int read_als(int handle) {
    int als_low = read_register(handle, SI1120_REG_ALS_VIS_DATA0);
    if (als_low < 0) {
        return -1;
    }
    int als_high = read_register(handle, SI1120_REG_ALS_VIS_DATA0 + 1);
    if (als_high < 0) {
        return -1;
    }
    return (als_high << 8) | als_low;
}

/* Read proximity data */
static int read_proximity(int handle) {
    int prox_low = read_register(handle, SI1120_REG_PS1_DATA0);
    if (prox_low < 0) {
        return -1;
    }
    int prox_high = read_register(handle, SI1120_REG_PS1_DATA0 + 1);
    if (prox_high < 0) {
        return -1;
    }
    return (prox_high << 8) | prox_low;
}

/* Log data to file */
static int log_data(FILE *fp, int als, int proximity) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: Failed to convert time\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s, ALS: %d, Proximity: %d\n", timestamp, als, proximity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }
    return 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si1120 address */
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X: %s\n",
                SI1120_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    /* Main loop */
    while (!terminate) {
        /* Trigger ALS and proximity measurements */
        if (write_register(i2c_handle, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) {
            fprintf(stderr, "Error: Failed to trigger ALS measurement\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        gpioDelay(10000); /* 10 ms conversion time */

        int als = read_als(i2c_handle);
        int proximity = read_proximity(i2c_handle);

        if (als >= 0 && proximity >= 0) {
            if (log_data(log_file, als, proximity) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

