#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include "si1145.h"

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int init_si1145(void) {
    if (si1145_init() != 0) {
        fprintf(stderr, "Error: Failed to initialize Si1145 driver.\n");
        return -1;
    }
    return 0;
}

static int read_proximity(uint16_t *proximity) {
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = si1145_read_proximity();
        if (result == 0) {
            *proximity = (uint16_t)((result >> 8) | (result << 8));
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d), retrying...\n",
                    retries, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %u\n", timestamp, proximity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n",
                SI1145_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Si1145 proximity logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity;

        if (read_proximity(&proximity) == 0) {
            if (log_data(proximity) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read proximity data.\n");
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

