            fprintf(stderr, "Error: timeout waiting for echo.\n");
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;
        double distance = calculate_distance_cm(pulse_width);

        printf("Distance: %.2f cm\n", distance);

