/*
 * Parking Assist System — Raspberry Pi Zero W
 *
 * HC-SR04 ultrasonic sensor:
 *   Trigger -> GPIO4  (BCM)
 *   Echo    -> GPIO17 (BCM)
 *
 * SG90 servo motor:
 *   Control line -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lservo
 *
 * Run:
 *   ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <servo.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  4
#define ECHO_PIN     17
#define SERVO_PIN    18

/* ---- HC-SR04 timing constants ---- */
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms (~5 m round-trip max) */
#define ECHO_TIMEOUT_CM  500.0   /* beyond this distance echo never arrives */
#define SAMPLE_PERIOD_MS 100

/* ---- SG90 servo pulse-width mapping ---- */
#define SERVO_MIN_US  500   /* 0°   */
#define SERVO_MAX_US  2500  /* 180° */
#define SERVO_MIN_CM  200.0
#define SERVO_MAX_CM  110.0

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void trigger_sensor(void)
{
    if (servoTrigger(TRIGGER_PIN) < 0)
        fprintf(stderr, "Warning: servoTrigger failed on pin %d\n", TRIGGER_PIN);
}

/*
 * Measure echo pulse width in microseconds.
 * Returns:
 *   > 0  — pulse width in microseconds
 *   -1.0 — timeout (no echo received within ECHO_TIMEOUT_US)
 */
static double measure_echo_us(void)
{
    struct timespec t0, t1;

    /* Wait for echo rising edge */
    if (clock_gettime(CLOCK_MONOTONIC, &t0) != 0) {
        perror("clock_gettime (rising edge)");
        return -1.0;
    }

    /* Poll until echo goes high or timeout */
    while (servoRead(ECHO_PIN) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &t1) != 0) {
            perror("clock_gettime (poll rising)");
            return -1.0;
        }
        if ((t1.tv_sec - t0.tv_sec) * 1000000U +
            (t1.tv_nsec - t0.tv_nsec) / 1000U > ECHO_TIMEOUT_US)
            return -1.0;
    }

    /* Record rising edge */
    if (clock_gettime(CLOCK_MONOTONIC, &t0) != 0) {
        perror("clock_gettime (rising edge)");
        return -1.0;
    }

    /* Wait for echo falling edge */
    while (servoRead(ECHO_PIN) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &t1) != 0) {
            perror("clock_gettime (poll falling)");
            return -1.0;
        }
        if ((t1.tv_sec - t0.tv_sec) * 1000000U +
            (t1.tv_nsec - t0.tv_nsec) / 1000U > ECHO_TIMEOUT_US)
            return -1.0;
    }

    /* Record falling edge */
    if (clock_gettime(CLOCK_MONOTONIC, &t1) != 0) {
        perror("clock_gettime (falling edge)");
        return -1.0;
    }

    return (double)(t1.tv_sec - t0.tv_sec) * 1000000.0 +
           (double)(t1.tv_nsec - t0.tv_nsec) / 1000.0;
}

/* ------------------------------------------------------------------ */
/* Distance conversion                                                */
/* ------------------------------------------------------------------ */
static double echo_us_to_cm(double us)
{
    /* Speed of sound ~343 m/s => 0.0343 cm/µs, round-trip */
    return us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
/* Servo angle mapping                                                 */
/* ------------------------------------------------------------------ */
static int distance_to_angle(double distance_cm)
{
    if (distance_cm <= SERVO_MAX_CM)
        return (int)(SERVO_MAX_US - (distance_cm - SERVO_MAX_CM) *
                     (SERVO_MAX_US - SERVO_MIN_US) /
                     (SERVO_MAX_CM - SERVO_MIN_CM));
    if (distance_cm >= SERVO_MIN_CM)
        return (int)(SERVO_MIN_US + (distance_cm - SERVO_MIN_CM) *
                     (SERVO_MAX_US - SERVO_MIN_US) /
                     (SERVO_MAX_CM - SERVO_MIN_CM));
    return SERVO_MIN_US;  /* exact — return minimum */
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize servo library ---- */
    if (servoInit() < 0) {
        fprintf(stderr, "Error: servoInit failed. "
                        "Is the servo library loaded?\n");
        return EXIT_FAILURE;
    }

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        servoTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");
    printf("Trigger=GPIO%d  Echo=GPIO%d  Servo=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, SERVO_PIN);
    printf("Distance range: %.0f–%.0f cm  Servo: 0°–180°\n",
           SERVO_MIN_CM, SERVO_MAX_CM);
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        trigger_sensor();
        double us = measure_echo_us();

        if (us > 0.0) {
            double cm = echo_us_to_cm(us);
            int angle = distance_to_angle(cm);

            printf("Distance: %6.2f cm  |  Servo: %3d°\n", cm, angle);
            if (servoSetAngle(SERVO_PIN, angle) < 0)
                fprintf(stderr, "Warning: servoSetAngle failed on pin %d\n",
                        SERVO_PIN);
        } else {
            fprintf(stderr, "Error: echo timeout (no object detected)\n");
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ms++)
            sleep_us(1000U);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    servoStop(SERVO_PIN);
    servoTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

