#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* VL53L1X I2C default address (SDA=GPIO2, SCL=GPIO3 on RPi 3B+) */
#define VL53L1X_ADDR 0x29

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP  0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_MODEL_ID 0xEA

/* Gate control GPIO (BCM 18, hardware PWM capable) */
#define GATE_GPIO 18

/* Distance thresholds (mm) with hysteresis */
#define DISTANCE_FAR 250
#define DISTANCE_NEAR 200

/* PWM pulse widths (µs) */
#define PWM_OPEN 1000
#define PWM_CLOSED 2000

/* Timing budget (ms) */
#define TIMING_BUDGET_MS 100

/* Polling interval (ms) */
#define POLL_INTERVAL_MS 50

/* Log file path */
#define LOG_FILE "gate_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify model ID */
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Start ranging (bit 0 = 1) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};

    /* Poll range status: bit 0 = new data ready */
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Warning: ranging data not ready\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian) */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gate control                                                        */
/* ------------------------------------------------------------------ */
static void gate_open(void)
{
    gpioPWM(GATE_GPIO, PWM_OPEN);
}

static void gate_close(void)
{
    gpioPWM(GATE_GPIO, PWM_CLOSED);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL)
        return;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_file) {
        fprintf(g_log_file, "%s: %s\n", timestamp, event);
        fflush(g_log_file);
    }
    printf("%s: %s\n", timestamp, event);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioPWM(GATE_GPIO, 0);
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t distance = 0;
    int gate_opening = 0;
    int gate_closing = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X default address */
    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure gate GPIO for hardware PWM */
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GATE_GPIO, 50);
    gpioSetPWMrange(GATE_GPIO, 1000);
    gpioPWM(GATE_GPIO, PWM_CLOSED);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        /* Hysteresis control */
        if (distance > DISTANCE_FAR && !gate_opening) {
            gate_open();
            gate_opening = 1;
            log_event("Gate opened");
        } else if (distance < DISTANCE_NEAR && !gate_closing) {
            gate_close();
            gate_closing = 1;
            log_event("Gate closed");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

