 *     Signal  -> GPIO18 (physical pin 12)
 *     VCC     -> 5 V (external supply recommended; do NOT power the
 *                Pi 5V pin and the servo from the same source)
 *     GND     -> common ground with the Pi
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

/* ---- SG90 pulse-width constants (microseconds) ---- */
#define SERVO_MIN_US  500   /* 0 degrees   */
#define SERVO_MAX_US  2500  /* 180 degrees */

/* ---- HC-SR04 timing ---- */
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000   /* 50 ms max echo wait */
#define CYCLE_DELAY_US    100000  /* 100 ms between measurements */

/* ---- Distance mapping ---- */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_ANGLE_DEG    0.0f
#define MAX_ANGLE_DEG    180.0f
#define MIN_VALID_CM     2.0f
#define MAX_VALID_CM     400.0f
#define THRESHOLD_CM     20.0f
#define OUT_OF_RANGE_CM  1000.0f

/* ---- Error sentinel ---- */
#define DISTANCE_ERROR   (-1.0f)

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   DISTANCE_ERROR on timeout or error,
 *   a value in [MIN_DISTANCE_CM, MAX_DISTANCE_CM] on success.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Issue a 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return DISTANCE_ERROR;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return DISTANCE_ERROR;
    }

    /* Wait for echo rising edge (timeout 50 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return DISTANCE_ERROR;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 50 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return DISTANCE_ERROR;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* speed of sound = 343 m/s = 0.0343 cm/us; round-trip => divide by 2 */
    float distance_cm = (float)pulse_us * 0.0343f / 2.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.1f, %.1f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return DISTANCE_ERROR;
    }
    return distance_cm;
}

/* ------------------------------------------------------------------ */
/* Servo angle mapping                                                 */
/* ------------------------------------------------------------------ */
static float distance_to_angle(float distance_cm)
{
    if (distance_cm < MIN_VALID_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance_cm > MAX_VALID_CM) {
        return MAX_ANGLE_DEG;
    }
    if (distance_cm <= THRESHOLD_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance_cm >= OUT_OF_RANGE_CM) {
        return MAX_ANGLE_DEG;
    }

    float frac = (distance_cm - MIN_VALID_CM) /
                 (MAX_VALID_CM - MIN_VALID_CM);
    return MIN_ANGLE_DEG + frac * (MAX_ANGLE_DEG - MIN_ANGLE_DEG);
}

/* ------------------------------------------------------------------ */
/* Servo control via pigpio API                                        */
/* ------------------------------------------------------------------ */
static int set_servo_angle(int angle_deg)
{
    if (angle_deg < MIN_ANGLE_DEG || angle_deg > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle_deg, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    float pulse_us = SERVO_MIN_US +
                     (float)angle_deg * (SERVO_MAX_US - SERVO_MIN_US) /
                     (MAX_ANGLE_DEG - MIN_ANGLE_DEG);

    if (gpioServo(SERVO_PIN, (int)pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %u) failed\n",
                SERVO_PIN, (unsigned)pulse_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo PWM signal */
    gpioServo(SERVO_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(500000);  /* 500 ms */

    printf("HC-SR04 + SG90 servo running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance == DISTANCE_ERROR) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
        } else {
            float angle = distance_to_angle(distance);
            if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
                fprintf(stderr, "Invalid angle %.2f after mapping from %.2f cm\n",
                        angle, distance);
            } else {
                printf("Distance: %.2f cm  ->  Angle: %.2f degrees\n",
                       distance, angle);
                if (set_servo_angle((int)angle) < 0) {
                    fprintf(stderr, "Failed to set servo angle.\n");
                }
            }
        }

        /* 100 ms cycle delay (interruptible by signals) */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(10000);  /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

