/*
 * Si7005 humidity & temperature sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si7005 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   Si7005 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   Si7005 VDD  -> 3.3 V
 *   Si7005 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7005 si7005.c -li2c
 *
 * Run:
 *   ./si7005
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7005_ADDR    0x40          /* Si7005 default I2C address (A0=A1=GND) */

/* Si7005 register addresses */
#define REG_CONFIG     0x01
#define REG_TEMP_HUM   0x06          /* 16-bit: [temp_hi:3][temp_lo:3][hum_hi:5][hum_lo:5] */

/* CONFIG register bits */
#define CFG_RESET      0x80          /* bit 7: write 1 to reset the device */
#define CFG_MEAS_1HZ   0x00          /* bits 6:0 = 0x00 -> 1 Hz measurement rate */

#define POLL_INTERVAL_S 2
#define CONV_WAIT_MS   10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Open the I2C bus and claim the Si7005 slave address.
 * Returns a valid file descriptor on success, or -1 on failure.
 */
static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7005_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SI7005_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a single byte to a Si7005 register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian value from a Si7005 register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    /* Point to the register we want to read */
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "write(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read two bytes back */
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "read(reg=0x%02X): %s\n",
                reg, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

/*
 * Initialize the Si7005: write CONFIG to reset the device and set 1 Hz
 * measurement rate, then wait for the first conversion to complete.
 * Returns 0 on success, -1 on failure.
 */
static int si7005_init(int fd)
{
    if (i2c_write_reg8(fd, REG_CONFIG, CFG_RESET) < 0)
        return -1;

    usleep(CONV_WAIT_MS * 1000);

    /* After reset, the device is ready; no further wait needed. */
    return 0;
}

/*
 * Read temperature (°C) and humidity (%RH) from the Si7005.
 * Returns 0 on success, -1 on failure.
 */
static int si7005_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw;

    /* Trigger a measurement by writing the register address */
    if (i2c_write_reg8(fd, REG_TEMP_HUM, 0x00) < 0)
        return -1;

    usleep(CONV_WAIT_MS * 1000);

    /* Read the 16-bit result */
    if (i2c_read_reg16(fd, REG_TEMP_HUM, &raw) < 0)
        return -1;

    /* Humidity: bits 11:5, 12-bit left-justified in 16-bit field */
    uint16_t hum_raw = (raw >> 5) & 0x0FFF;
    *humidity = (float)hum_raw / 16383.0f * 100.0f;

    /* Temperature: bits 14:12, 10-bit left-justified in 16-bit field */
    uint16_t temp_raw = (raw >> 12) & 0x07FF;
    *temperature = (float)temp_raw / 1023.0f * 165.0f - 40.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus and claim the Si7005 address */
    fd = i2c_open();
    if (fd < 0)
        return EXIT_FAILURE;

    /* Initialize the sensor */
    if (si7005_init(fd) < 0) {
        fprintf(stderr, "Si7005 initialization failed.\n");
        goto cleanup;
    }

    printf("Si7005 initialized on %s (addr 0x%02X). Logging every %d s.\n",
           I2C_BUS, SI7005_ADDR, POLL_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (si7005_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%RH\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "I2C read error — attempting recovery.\n");
            close(fd);
            fd = -1;

            /* Brief pause before retry to avoid bus hammering */
            usleep(500 * 1000);

            fd = i2c_open();
            if (fd < 0) {
                fprintf(stderr, "Recovery failed: cannot re-open I2C bus.\n");
                goto cleanup;
            }

            if (si7005_init(fd) < 0) {
                fprintf(stderr, "Recovery failed: Si7005 re-init failed.\n");
                goto cleanup;
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);

    printf("\nExiting gracefully.\n");
    return rc;
}

