/*
 * MPU-6050 raw data reader for Raspberry Pi 3 Model B+
 * I2C bus 1 (SDA=GPIO2, SCL=GPIO3, BCM numbering)
 *
 * Build:  gcc -O2 -Wall -o mpu6050_raw mpu6050_raw.c -li2c
 * Run:    sudo ./mpu6050_raw
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ---- MPU-6050 register map (datasheet) ---- */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG     0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1 0x6B

#define MPU6050_WHO_AM_I_VAL 0x68

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers (pigpio via /dev/i2c-1) ---- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, len) != len)
        return -1;
    return 0;
}

