    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit, then wait for oscillator */
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms */

    /* Sample rate = 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: writing SMPLRT_DIV: %s\n", strerror(errno));
        return -1;
    }

    /* Gyro full-scale ±250 °/s (FS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: writing GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Accel full-scale ±2 g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
