        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 ready on /dev/i2c-1 (0x68). Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (mpu6050_read(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
