/*
 * SHT40 temperature/humidity sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SHT40 VDD  -> Pi 3V3  (pin 1)
 *   SHT40 GND  -> Pi GND  (pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40 sht40.c
 * Run:    ./sht40
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x0C   /* Adafruit SHT40 default I2C address */
#define MEASURE_CMD    0x2C   /* High repeatability, clock-stretching */
#define MEASURE_DELAY  10000  /* microseconds (10 ms) */
#define POLL_INTERVAL  5      /* seconds */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, initial value 0x00 (Sensirion convention) */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Open the I2C bus and claim the SHT40 slave address.
 * Returns a valid file descriptor on success, or -1 on failure.
 */
static int sht_open_bus(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SHT40_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read one measurement from the SHT40.
 * Returns 0 on success, -1 on I2C/CRC error.
 */
static int sht_read(int fd, float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(measure cmd): %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY);

    uint8_t data[6];
    ssize_t r = read(fd, data, sizeof(data));
    if (r != (ssize_t)sizeof(data)) {
        fprintf(stderr, "read(data): got %zd of %zu bytes (%s)\n",
                r, sizeof(data), r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht_crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on humidity word\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = sht_open_bus();
    if (fd < 0)
        return EXIT_FAILURE;

    printf("SHT40 reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, SHT40_ADDR);

    while (g_running) {
        float temperature, humidity;

        if (sht_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; re-opening I2C bus.\n");
            close(fd);
            fd = -1;
            for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
                usleep(100000);
                fd = sht_open_bus();
                if (fd >= 0)
                    break;
            }
            if (fd < 0) {
                fprintf(stderr, "Recovery failed after %d attempts; exiting.\n",
                        MAX_RETRIES);
                return EXIT_FAILURE;
            }
        }

        for (int s = 0; s < POLL_INTERVAL && g_running; s++)
            sleep(1);
    }

    if (fd >= 0)
        close(fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

