#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_I2C_ADDR 0x5A
#define MLX90614_TA 0x06
#define MLX90614_TO 0x07
#define LOG_FILE "temperature_log.csv"
#define I2C_BUS "/dev/i2c-1"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_temperature(int fd, float *ambient, float *object) {
    int16_t raw_ta, raw_to;
    if (i2c_read_reg16(fd, MLX90614_TA, &raw_ta) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, MLX90614_TO, &raw_to) < 0) {
        return -1;
    }
    *ambient = (float)raw_ta * 0.02 - 273.15;
    *object = (float)raw_to * 0.02 - 273.15;
    return 0;
}

static int log_data(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        if (read_temperature(i2c_fd, &ambient, &object) == 0) {
            if (log_data(log_file, ambient, object) != 0) {
                fprintf(stderr, "Error logging data: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        }
        sleep(READ_INTERVAL);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

