#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x77
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_temperature(float *temperature) {
    char cmd[2] = {0x36, 0x2F};
    char buf[3];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "I2C write failed (attempt %d): %d", attempt + 1, result);
            log_error(msg);
            gpioDelay(1000000);
            continue;
        }

        gpioDelay(20000);

        result = i2cReadDevice(i2c_handle, buf, 3);
        if (result != 3) {
            char msg[128];
            snprintf(msg, sizeof(msg), "I2C read failed (attempt %d): got %d bytes", attempt + 1, result);
            log_error(msg);
            gpioDelay(1000000);
            continue;
        }

        int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
        *temperature = (float)raw_temp / 200.0f;
        return 0;
    }

    return -1;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);

    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at address 0x%02X: %d", STS30_ADDR, i2c_handle);
        log_error(msg);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature to file");
            }
        } else {
            log_error("Failed to read temperature after retries");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    cleanup();
    return 0;
}

