#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* SDP810-125Pa default I2C address */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  1000          /* 1 ms measurement wait */

/* SDP810 continuous measurement command (MSB first) */
static const uint8_t CMD_CONT_MEAS[3] = {0x36, 0x2F, 0x06};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00) per Sensirion SDP810 datasheet     */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the log file; write header if it is a new/empty file           */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    FILE *fp = fopen(LOG_FILE, "r");
    int needs_header = 0;

    if (fp == NULL) {
        needs_header = 1;
    } else {
        /* Check if the file is empty */
        if (fseek(fp, 0, SEEK_END) != 0) {
            fclose(fp);
            needs_header = 1;
        } else {
            long sz = ftell(fp);
            fclose(fp);
            if (sz <= 0) needs_header = 1;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (needs_header) {
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
        fflush(fp);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row: ISO-8601 UTC timestamp, pressure, temperature   */
/* ------------------------------------------------------------------ */
static int log_data(float pressure, float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP810                  */
/* Returns 0 on success, -1 on I/O or CRC error                        */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[3] = CMD_CONT_MEAS;
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 3) != 0) {
        fprintf(stderr, "i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for the first conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Issue a dummy read to trigger a fresh measurement */
    if (i2cWriteByte(handle, 0x00) != 0) {
        fprintf(stderr, "i2cWriteByte trigger failed\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: dp_raw(2)+crc, t_raw(2)+crc, dp_scale(2)+crc, t_scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "i2cReadDevice failed\n");
        return -1;
    }

    /* CRC validation for each 2-byte data word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on differential pressure word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on differential pressure scale word\n");
        return -1;
    }
    if (crc8(&buf[9], 2) != buf[11]) {
        fprintf(stderr, "CRC error on temperature scale word\n");
        return -1;
    }

    int16_t dp_raw    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t t_raw     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t dp_scale  = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t t_scale   = (int16_t)((buf[9] << 8) | buf[10]);

    if (dp_scale == 0 || t_scale == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)dp_raw / (float)dp_scale;
    *temperature = (float)t_raw / (float)t_scale;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP810 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP810 monitoring started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

