#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21          /* SDP31 default I2C address */
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000        /* 100 ms */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  1000          /* 1 ms measurement delay */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; do NOT call non-async-signal-safe   */
/* functions here.                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 6-byte measurement frame from the SDP31.                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_sdp31(int handle, float *pressure_pa, float *temp_c)
{
    uint8_t cmd[1] = { 0x36 };          /* continuous measurement, avg */
    uint8_t buf[6];
    int     retries = 0;
    int     delay_us = 1000;

    while (retries < MAX_RETRIES) {
        /* Send trigger command */
        if (i2cWriteDevice(handle, (char *)cmd, 1) != 0) {
            fprintf(stderr, "[SDP31] i2cWriteDevice failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }

        /* Wait for measurement to be ready */
        gpioDelay(MEAS_DELAY_US);

        /* Read 6 bytes: pressure(2)+crc, temperature(2)+crc */
        int n = i2cReadDevice(handle, (char *)buf, 6);
        if (n != 6) {
            fprintf(stderr, "[SDP31] i2cReadDevice returned %d (expected 6): %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }

        /* CRC checks */
        if (sensirion_crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[SDP31] pressure CRC mismatch\n");
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }
        if (sensirion_crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[SDP31] temperature CRC mismatch\n");
            retries++;
            gpioDelay(delay_us);
            delay_us *= 2;
            continue;
        }

        /* Convert raw values to physical units */
        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure_pa = (float)raw_pressure / 60.0f;   /* Pa per LSB */
        *temp_c      = (float)raw_temp / 200.0f;       /* °C per LSB */

        return 0;
    }

    fprintf(stderr, "[SDP31] read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped CSV line to the log file.                      */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure_pa, float temp_c)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[LOG] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temp_c) < 0) {
        fprintf(stderr, "[LOG] fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if some resources were never    */
/* initialised.                                                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus 1 at SDP31 address 0x21 ----------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- main sampling loop ----------------------------------------- */
    while (g_running) {
        float pressure_pa = 0.0f;
        float temp_c      = 0.0f;

        if (read_sdp31(g_i2c_handle, &pressure_pa, &temp_c) == 0) {
            if (log_data(g_log_file, pressure_pa, temp_c) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep 100 ms in 10 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(10000);
    }

    /* --- graceful shutdown ------------------------------------------ */
    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

