#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x0C
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000   /* 5 s */
#define MEASURE_US     20000     /* 20 ms max per measurement */

/* Si7015 No Hold Master commands (datasheet) */
#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5
#define CMD_RESET      0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single-byte command to the Si7015 and read back `len` bytes. */
static int si7015_write_read(int handle, uint8_t cmd, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    gpioDelay(1000); /* command processing time */

    int bytes_read = i2cReadDevice(handle, (char *)buf, len);
    if (bytes_read != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice for cmd 0x%02X: got %d, expected %u: %s\n",
                cmd, bytes_read, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit measurement (MSB first) from the Si7015. */
static int si7015_read_measurement(int handle, uint8_t cmd, uint16_t *out)
{
    uint8_t buf[2];
    if (si7015_write_read(handle, cmd, buf, sizeof(buf)) < 0)
        return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int handle, float *temp_c)
{
    uint16_t raw;
    if (si7015_read_measurement(handle, CMD_TEMP_HOLD, &raw) < 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *rh)
{
    uint16_t raw;
    if (si7015_read_measurement(handle, CMD_HUM_HOLD, &raw) < 0)
        return -1;
    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static void log_data(FILE *fp, float temp_c, float rh)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp_c, rh);
    fflush(fp);
    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp_c, rh);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Reset the sensor to a known state */
    if (i2cWriteByte(g_i2c_handle, CMD_RESET) < 0) {
        fprintf(stderr, "[ERROR] Sensor reset failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(15000); /* allow reset to complete */

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (read_temperature(g_i2c_handle, &temp_c) < 0) {
            fprintf(stderr, "[WARN] Temperature read failed; retrying next cycle.\n");
        } else if (read_humidity(g_i2c_handle, &rh) < 0) {
            fprintf(stderr, "[WARN] Humidity read failed; retrying next cycle.\n");
        } else {
            log_data(fp, temp_c, rh);
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        uint32_t remaining = SAMPLE_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    if (fp != NULL) fclose(fp);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

