/*
 * SDP800-500Pa differential-pressure logger for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o airflow airflow.c
 *
 * Run:
 *   ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25          /* SDP800 default I2C address */
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD_MS 100
#define MEAS_DELAY_MS   45           /* first conversion after trigger */

/* SDP800 continuous-measurement trigger command (MSB first) */
static const uint8_t TRIGGER_CMD[3] = {0x36, 0x2F, 0x06};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP8xx */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Read one 9-byte measurement frame from the SDP800.
 * Layout: [P_msb P_lsb P_crc] [T_msb T_lsb T_crc] [S_msb S_lsb S_crc]
 * Returns 0 on success, -1 on I/O or CRC error.
 */
static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t buf[9];

    if (i2c_read(fd, buf, sizeof(buf)) < 0)
        return -1;

