/*
 * Raspberry Pi Zero W – Sensirion STS30-DIS temperature logger
 *
 * Wiring:
 *   STS30-DIS SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   STS30-DIS SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   STS30-DIS VDD  -> 3.3 V (pin 1)
 *   STS30-DIS GND  -> GND  (pin 6)
 *
 * I2C address: 0x80 (default for STS30-DIS)
 * Measurement command: 0x3608  (single shot, high repeatability, clock stretching disabled)
 * Conversion time: ~15 ms
 * CRC-8: polynomial 0x31, initial value 0xFF
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS              1
#define STS30_ADDR           0x80
#define MEASURE_CMD_HIGH     0x36
#define MEASURE_CMD_LOW      0x08
#define CONVERSION_DELAY_US  15000   /* 15 ms */
#define SAMPLE_INTERVAL_S    5
#define LOG_FILE             "enclosure_temp_log.txt"
#define ERROR_LOG_FILE       "error_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;
static FILE *g_err_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp) {
        fprintf(stderr, "[ERROR] %s (errno=%d: %s)\n",
                msg, errno, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(g_err_fp, "[ERROR] %s (timestamp unavailable)\n", msg);
    } else {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(g_err_fp, "[ERROR] %s at %s\n", msg, ts);
    }
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sts30(float *temperature)
{
    uint8_t cmd[2] = { MEASURE_CMD_HIGH, MEASURE_CMD_LOW };
    uint8_t buf[3];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        log_error("I2C write failed (measurement command)");
        return -1;
    }

    /* Wait for conversion */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 3 bytes: MSB, LSB, CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed (sensor response)");
        return -1;
    }

    /* Validate CRC */
    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC mismatch on temperature data");
        return -1;
    }

    /* Convert raw 16-bit value to Celsius */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw / 200.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        log_error("localtime_r failed in log_temperature");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(g_log_fp, "%s, %.2f\n", ts, temperature) < 0) {
        log_error("fprintf to log file failed");
    } else {
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, STS30_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open error log file */
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", ERROR_LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction(SIGTERM) failed");
    }

    printf("STS30-DIS logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (g_running) {
        float temperature;
        if (read_sts30(&temperature) == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            log_error("Sensor read failed; will retry next cycle");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

