#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE       60
#define MAX_RETRIES       3
#define READ_INTERVAL_S   2
#define FAN_SETTLE_US     10000

#define CMD_MEASURE_TEMP  0xE3
#define CMD_READ_TEMP     0xE0

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_reading(time_t ts, float temp) {
    temperature_buffer[buffer_index].timestamp = ts;
    temperature_buffer[buffer_index].temperature = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Temperature Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char tbuf[32];
