#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR             0x61
#define I2C_BUS                1
#define LOG_FILE               "air_quality.log"
#define READ_INTERVAL_US       5000000  /* 5 s  */
#define FIRST_READ_DELAY_US    1000000  /* 1 s  */
#define MAX_RETRIES            3

/* SCD4x command set (datasheet rev 2.1) */
#define CMD_START_PERIODIC     0x21
#define CMD_STOP_PERIODIC      0x22
#define CMD_GET_DATA_READY     0x36
#define CMD_READ_MEASUREMENT   0x3F

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/*  Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  CRC-8 (Sensirion polynomial 0x31, init 0x00)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/*  Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int scd40_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_block(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %d, got %d\n", len, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int scd40_start_periodic(int handle)
{
    if (scd40_write_cmd(handle, CMD_START_PERIODIC) < 0)
        return -1;
    /* Datasheet: max 30 ms startup; 50 ms is safe */
    gpioDelay(50000);
    return 0;
}

static int scd40_stop_periodic(int handle)
{
    if (scd40_write_cmd(handle, CMD_STOP_PERIODIC) < 0)
        return -1;
    gpioDelay(50000);
    return 0;
}

/*
 * Read the 9-byte measurement block.
 * Layout (datasheet rev 2.1):
 *   bytes 0-1  CO2  (ppm),  CRC byte 2
 *   bytes 3-4  T    (deg C), CRC byte 5
 *   bytes 6-7  RH   (%%RH), CRC byte 8
 */
static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temperature, float *humidity)
{
    uint8_t buf[9];

    if (scd40_write_cmd(handle, CMD_READ_MEASUREMENT) < 0)
        return -1;

    /* SCD4x clock-stretches the read; give a small margin */
    gpioDelay(2000);

    if (scd40_read_block(handle, buf, sizeof(buf)) < 0)
        return -1;

    /* CRC checks on each 2-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    *co2        = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    *humidity   = (float)((buf[6] << 8) | buf[7]) / 1000.0f;

    return 0;
}

static int scd40_data_ready(int handle)
{
    if (scd40_write_cmd(handle, CMD_GET_DATA_READY) < 0)
        return -1;

    gpioDelay(2000);

    uint8_t buf[3];
    if (scd40_read_block(handle, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Data-ready CRC mismatch\n");
        return -1;
    }

    return (buf[0] == 0x1) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/*  Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t co2, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/*  Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_stop_periodic(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure sensor has ambient light for photoacoustic measurement */
    gpioDelay(2000000);  /* 2 s */

    if (scd40_start_periodic(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioDelay(FIRST_READ_DELAY_US);

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int ready = scd40_data_ready(g_i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "[WARN] Data-ready check failed; retrying\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        if (ready == 0) {
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        uint16_t co2;
        float temperature, humidity;

        if (scd40_read_measurement(g_i2c_handle, &co2, &temperature, &humidity) < 0) {
            fprintf(stderr, "[WARN] Read measurement failed; retrying\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        log_data(g_log_file, co2, temperature, humidity);
        printf("CO2: %u ppm  T: %.2f C  RH: %.2f %%\n",
               co2, temperature, humidity);

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

