        if (scd40_read_measurement(g_i2c_handle, &co2, &temperature, &humidity) < 0) {
            fprintf(stderr, "[WARN] Read measurement failed; retrying\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        log_data(g_log_file, co2, temperature, humidity);
        printf("CO2: %u ppm  T: %.2f C  RH: %.2f %%\n",
               co2, temperature, humidity);

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

