/*
 * SCD40 CO2 / RH / Temp logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   CO2 warning LED anode -> GPIO17 (BCM) via 330 ohm resistor
 *   CO2 warning LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_logger scd40_logger.c -lpigpio -lrt
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SCD40_ADDR           0x81          /* SCD40 default I2C address */
#define GPIO_LED             17            /* BCM pin for CO2 warning LED */
#define CO2_THRESHOLD_PPM    1000
#define BUFFER_SIZE          20
#define SAMPLE_INTERVAL_S    5             /* seconds between readings */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       100000        /* 100 ms between retries */

/* SCD40 command codes (16-bit, big-endian on the bus) */
#define CMD_START_PERIODIC   0x0010        /* start continuous measurement */
#define CMD_STOP_PERIODIC    0x0104        /* stop continuous measurement */
#define CMD_GET_DATA         0x0202        /* read measurement data */
#define CMD_SOFT_RESET       0x0300        /* soft reset */

/* ------------------------------- Types ---------------------------------- */
typedef struct {
    uint16_t co2;          /* ppm, 0–40000 */
    float    temperature;  /* °C, -40–85 */
    float    humidity;     /* %RH, 0–100 */
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;              /* next write slot */
    int count;             /* valid entries */
} circular_buffer_t;

/* --------------------------- Global state ------------------------------- */
static int           i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Prototypes --------------------------------- */
static uint8_t  crc8(const uint8_t *data, int len);
static int      init_i2c(void);
static int      init_scd40(void);
static int      read_scd40(sensor_data_t *out);
static void     update_buffer(circular_buffer_t *cb, const sensor_data_t *d);
static void     check_co2_threshold(const sensor_data_t *d);
static void     signal_handler(int sig);
static void     cleanup(void);

/* ------------------------------ CRC-8 ----------------------------------- */
/* Sensirion CRC-8 polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- I2C helpers -------------------------------- */
static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[I2C] write cmd 0x%04X failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[I2C] read %d bytes, expected %d\n", n, len);
        return -1;
    }
    return 0;
}

/* --------------------------- SCD40 driver -------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[I2C] open failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_scd40(void)
{
    /* Soft reset */
    if (i2c_write_cmd(i2c_handle, CMD_SOFT_RESET) != 0)
        return -1;
    gpioDelay(20000);  /* 20 ms settle after reset */

    /* Start continuous measurement (periodic mode, 1 s interval) */
    if (i2c_write_cmd(i2c_handle, CMD_START_PERIODIC) != 0)
        return -1;
    gpioDelay(20000);  /* 20 ms for first measurement to start */

    return 0;
}

static int read_scd40(sensor_data_t *out)
{
    uint8_t buf[9];

    /* Request measurement data */
    if (i2c_write_cmd(i2c_handle, CMD_GET_DATA) != 0)
        return -1;

    /* Datasheet: read 9 bytes: 3 words + 3 CRC bytes */
    gpioDelay(20000);  /* 20 ms processing time */
    if (i2c_read_block(i2c_handle, buf, 9) != 0)
        return -1;

    /* Validate CRC on each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[SCD40] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw  = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t temp_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t rh_raw   = (uint16_t)((buf[6] << 8) | buf[7]);

    out->co2          = co2_raw;
    out->temperature  = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    out->humidity     = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* --------------------------- Circular buffer ----------------------------- */
static void update_buffer(circular_buffer_t *cb, const sensor_data_t *d)
{
    cb->data[cb->head] = *d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void print_buffer(const circular_buffer_t *cb)
{
    printf("\n--- Circular buffer (%d entries) ---\n", cb->count);
    int start = (cb->count == BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] CO2=%5u ppm  T=%.2f C  RH=%.1f %%\n",
               idx, cb->data[idx].co2,
               cb->data[idx].temperature,
               cb->data[idx].humidity);
    }
    printf("-----------------------------------\n");
}

/* --------------------------- CO2 threshold -------------------------------- */
static void check_co2_threshold(const sensor_data_t *d)
{
    if (d->co2 > CO2_THRESHOLD_PPM) {
        gpioWrite(GPIO_LED, 1);
        printf("[ALERT] CO2 %u ppm exceeds threshold %d ppm\n",
               d->co2, CO2_THRESHOLD_PPM);
    } else {
        gpioWrite(GPIO_LED, 0);
    }
}

/* --------------------------- Signal / cleanup ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2c_write_cmd(i2c_handle, CMD_STOP_PERIODIC);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[GPIO] setMode %d failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* Initialize I2C and sensor */
    if (init_i2c() != 0 || init_scd40() != 0) {
        fprintf(stderr, "[SCD40] init failed — check wiring/address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize buffer */
    buffer.head  = 0;
    buffer.count = 0;

    printf("SCD40 logger started. Sampling every %d s. Press Ctrl-C to stop.\n",
           SAMPLE_INTERVAL_S);

    sensor_data_t sample;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_scd40(&sample) == 0) {
            consecutive_errors = 0;
            update_buffer(&buffer, &sample);
            check_co2_threshold(&sample);
            print_buffer(&buffer);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[SCD40] read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[SCD40] too many consecutive errors — aborting.\n");
                break;
            }
        }

        /* Sleep SAMPLE_INTERVAL_S but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && !terminate; s++)
            sleep(1);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

