#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_fp);
    }
}

static void log_temperature(float temp) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
        fflush(g_log_fp);
    }
}

static void log_error(const char *msg) {
    char buf[256];
    snprintf(buf, sizeof(buf), "ERROR: %s", msg);
    log_message(buf);
}

static void log_sensor_failure(void) {
    log_message("SENSOR MALFUNCTION");
}

/*
 * Measure the high-pulse width (TH) and total cycle width (T) of the
 * TMP05 PWM-style output on the given GPIO pin using a busy-wait loop
 * with microsecond-resolution timestamps from pigpio's call() API.
 *
 * Returns 0 on success (TH and T populated), -1 on timeout, -2 on
 * pigpio initialization failure.
 */
static int measure_pulse_width(int gpio, uint32_t *th, uint32_t *t) {
    if (!th || !t) return -1;

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t elapsed = 0;

    /* Wait for a falling edge (start of a new cycle) */
    while (g_running) {
        int level = gpioRead(gpio);
        if (level < 0) return -1;
        if (level == 0) break;
        elapsed = 0;
        while (g_running && elapsed < TIMEOUT_US) {
            gpioDelay(1);
            elapsed++;
        }
        if (!g_running) return -1;
        if (elapsed >= TIMEOUT_US) return -1; /* timeout */
    }
    if (!g_running) return -1;

    start_tick = gpioTick();

    /* Wait for a rising edge (end of low time, start of high time) */
    while (g_running) {
        int level = gpioRead(gpio);
        if (level < 0) return -1;
        if (level == 1) break;
        elapsed = 0;
        while (g_running && elapsed < TIMEOUT_US) {
            gpioDelay(1);
            elapsed++;
        }
        if (!g_running) return -1;
        if (elapsed >= TIMEOUT_US) return -1;
    }
    if (!g_running) return -1;

    end_tick = gpioTick();

    /* Wait for a falling edge (end of high time, end of cycle) */
    while (g_running) {
        int level = gpioRead(gpio);
        if (level < 0) return -1;
        if (level == 0) break;
        elapsed = 0;
        while (g_running && elapsed < TIMEOUT_US) {
            gpioDelay(1);
            elapsed++;
        }
        if (!g_running) return -1;
        if (elapsed >= TIMEOUT_US) return -1;
    }
    if (!g_running) return -1;

    uint32_t cycle_tick = gpioTick();

    *th = end_tick - start_tick;
    *t = cycle_tick - start_tick;
    return 0;
}

static float calculate_temperature(uint32_t th, uint32_t t) {
    if (t == 0) return -1000.0f;
    float tl = (float)th / (float)t;
    float vout = 3.3f * tl;
    float temp = (vout - 0.5f) * 100.0f;
    return temp;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    int consecutive_errors = 0;

    while (g_running) {
        uint32_t th = 0, t = 0;
        int rc = measure_pulse_width(GPIO_PIN, &th, &t);

        if (rc != 0) {
            if (rc == -2) {
                log_error("pigpio initialization failed");
            } else {
                log_error("Timeout waiting for TMP05 edge");
            }
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_sensor_failure();
                consecutive_errors = 0;
            }
        } else {
            float temp = calculate_temperature(th, t);
            if (temp < -40.0f || temp > 150.0f) {
                log_error("Temperature out of valid range");
                consecutive_errors++;
                if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                    log_sensor_failure();
                    consecutive_errors = 0;
                }
            } else {
                log_temperature(temp);
                consecutive_errors = 0;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    log_message("Program stopped");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

