#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x38
#define MEASURE_CMD_MSB 0x2F
#define MEASURE_CMD_LSB 0x08
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define MEASUREMENT_DELAY_US 15000
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void simulate_greenhouse(float *temperature, float *humidity) {
    time_t now = time(NULL);
    double hour = (double)(now % 3600) / 3600.0;
    *temperature += 2.0f * sinf(2.0 * M_PI * hour);
    *humidity += 5.0f * sinf(2.0 * M_PI * hour);
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (code %d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    int retry;

    while (running) {
        retry = 0;
        while (retry < RETRY_COUNT && running) {
            if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
                simulate_greenhouse(&temperature, &humidity);
                log_data(log_file, temperature, humidity);
                break;
            }
            retry++;
            if (retry < RETRY_COUNT) {
                fprintf(stderr, "Warning: Retry %d/%d.\n", retry, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Error: Max retries reached. Logging NaN values.\n");
            log_data(log_file, NAN, NAN);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

