/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 * Continuous measurement command: 0x361F
 * Conversion time: ~45 ms
 * 9-byte response: [pressure_msb, pressure_lsb, pressure_crc,
 *                   temp_msb,   temp_lsb,   temp_crc,
 *                   scale_msb,  scale_lsb,  scale_crc]
 *
 * Pressure (Pa) = (raw_pressure - 32768) * scale_factor / 65536
 * Temperature (°C) = (raw_temp - 32768) / 256
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define CSV_FILENAME   "airflow.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_TIME_MS   45         /* conversion time per datasheet */

/* SDP810 CRC-8: polynomial 0x31, init 0xFF, no reflection */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion)                                                   */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a 2-byte command to the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "write(cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data parsing                                                 */
/* ------------------------------------------------------------------ */
typedef struct {
    int16_t pressure;     /* Pa */
    int16_t temperature;  /* °C */
    int16_t scale_factor; /* scale factor for pressure */
} sensor_data_t;

static int parse_sensor_data(const uint8_t *raw, sensor_data_t *out)
{
    if (sdp_crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "pressure CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "temperature CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "scale-factor CRC mismatch\n");
        return -1;
    }

    out->pressure     = (int16_t)((raw[0] << 8) | raw[1]);
    out->temperature  = (int16_t)((raw[3] << 8) | raw[4]);
    out->scale_factor = (int16_t)((raw[6] << 8) | raw[7]);
    return 0;
}

static float convert_pressure(int16_t raw, int16_t scale)
{
    /* Pressure (Pa) = (raw - 32768) * scale / 65536 */
    return ((float)raw - 32768.0f) * (float)scale / 65536.0f;
}

static float convert_temperature(int16_t raw)
{
    /* Temperature (°C) = raw / 256 */
    return (float)raw / 256.0f;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, SDP810_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* Start continuous measurement */
    if (sdp_write_cmd(g_i2c_fd, 0x361F) < 0) {
        fprintf(stderr, "Failed to start continuous measurement.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Wait for first conversion to complete */
    usleep(CONV_TIME_MS * 1000);

    printf("SDP810 logging to %s (Ctrl+C to stop)\n", CSV_FILENAME);

    while (g_running) {
        uint8_t raw[9];
        sensor_data_t sd;

        if (sdp_read_bytes(g_i2c_fd, raw, sizeof(raw)) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (parse_sensor_data(raw, &sd) < 0) {
            fprintf(stderr, "Sensor data parse error; continuing.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float pressure = convert_pressure(sd.pressure, sd.scale_factor);
        float temperature = convert_temperature(sd.temperature);

        if (log_data(CSV_FILENAME, pressure, temperature) < 0)
            fprintf(stderr, "Logging failed; continuing.\n");

        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    if (g_i2c_fd >= 0) {
        /* Send stop measurement command */
        (void)sdp_write_cmd(g_i2c_fd, 0x3FF9);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

