/*
 * SHT35-DIS-B temperature/humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT35 VDD  -> Pi 3V3  (pin 1)
 *   SHT35 GND  -> Pi GND  (pin 9)
 *   SHT35 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SHT35 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * I2C bus 1, address 0x49 (SHT35-DIS-B default).
 * Single-shot high-repeatability measurement, clock-stretching disabled.
 * Sample interval: 5 s.  CRC-8 validation per Sensirion spec.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49
#define CSV_FILE       "environment.csv"
#define SAMPLE_US      5000000   /* 5 s */
#define MEASURE_US     15000     /* 15 ms measurement wait */
#define MAX_RETRIES    3

/* SHT35 single-shot, high repeatability, clock-stretching disabled */
static const uint8_t CMD_MSB = 0x2C;
static const uint8_t CMD_LSB = 0x06;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0x00)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio code %d): %s\n",
                g_i2c_handle, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one measurement                                                */
/* ------------------------------------------------------------------ */
static int read_measurement(float *temperature, float *humidity)
{
    uint8_t cmd[2] = { CMD_MSB, CMD_LSB };
    uint8_t data[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion (datasheet: typ 12.1 ms, max 15 ms) */
    gpioDelay(MEASURE_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* CRC validation */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    /* Check whether file exists / is empty so we can write a header */
    int need_header = 0;
    FILE *check = fopen(CSV_FILE, "r");
    if (!check) {
        need_header = 1;            /* file does not exist yet */
    } else {
        fseek(check, 0, SEEK_END);
        if (ftell(check) == 0)
            need_header = 1;
        fclose(check);
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started.  Logging to %s every 5 s.  Ctrl-C to stop.\n",
           CSV_FILE);

    while (g_running) {
        float temperature, humidity;

        if (read_measurement(&temperature, &humidity) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0)
                fprintf(stderr, "Warning: logging failed for this sample\n");
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }

        /* Sleep in 100 ms chunks so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

