/*
 * Greenhouse environmental monitor — Raspberry Pi Zero W
 * Sensor : Adafruit Si7021 (I2C address 0x40, bus 1)
 * Bus    : GPIO 2 (SDA) / GPIO 3 (SCL)
 * Log    : environment.log  (CSV: timestamp,temperature_C,humidity_percent)
 *
 * Build  : gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEASURE_TIMEOUT_MS 100     /* max wait for a conversion */

/* Si7021 commands (16-bit, big-endian on the bus) */
#define CMD_READ_TEMP_HOLD   0xE3
#define CMD_READ_HUM_HOLD    0xE5
#define CMD_RESET            0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si7021 CRC-8 (polynomial 0x31, init 0x00, no final XOR) — per datasheet */
/* ------------------------------------------------------------------ */
static uint8_t si7021_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int si7021_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) != 0)
        return -1;
    usleep(15000);  /* datasheet: wait >= 15 ms after reset */
    return 0;
}

/*
 * Trigger a measurement, wait for data-ready, read 3 bytes (MSB, LSB, CRC),
 * verify CRC, and return the 16-bit value.
 * Returns 0 on success, -1 on error.
 */
static int si7021_read_measurement(int fd, uint8_t cmd, uint16_t *out)
{
    if (i2c_write_cmd(fd, cmd) != 0)
        return -1;

    /* Si7021 conversion time: ~7 ms for T, ~12 ms for RH (max 100 ms) */
    for (int waited = 0; waited < MEASURE_TIMEOUT_MS; waited += 5) {
        usleep(5000);
        uint8_t buf[3];
        if (i2c_read_bytes(fd, buf, 3) != 0)
            return -1;
        if (si7021_crc8(buf, 2) == buf[2]) {
            *out = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
    }

    fprintf(stderr, "Si7021 measurement timeout (cmd 0x%02X)\n", cmd);
    return -1;
}

static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (si7021_read_measurement(fd, CMD_READ_TEMP_HOLD, &raw) != 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *rh)
{
    uint16_t raw;
    if (si7021_read_measurement(fd, CMD_READ_HUM_HOLD, &raw) != 0)
        return -1;
    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
        fflush(fp);
    }
    return 0;
}

static void log_sample(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fflush(fp);
    fclose(fp);
}

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Quick presence check: issue a reset and verify the device NACKs */
    if (i2c_write_cmd(g_i2c_fd, CMD_RESET) != 0) {
        fprintf(stderr, "Si7021 not responding at 0x%02X\n", SI7021_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) != 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh;

        if (si7021_reset(g_i2c_fd) != 0) {
            log_error("Sensor reset failed; will retry next cycle.");
        } else {
            if (read_temperature(g_i2c_fd, &temp_c) != 0) {
                log_error("Temperature read failed.");
            } else if (read_humidity(g_i2c_fd, &rh) != 0) {
                log_error("Humidity read failed.");
            } else {
                log_sample(temp_c, rh);
                printf("T=%.2f C  RH=%.2f %%\n", temp_c, rh);
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

