#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CONV_TIME_US 10000
#define SAMPLE_INTERVAL_US 1000000
#define FILENAME "airflow.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SDP810_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(float *pressure, float *temperature) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Failed to read 9 bytes from sensor (got %d): %s\n", rc, strerror(errno));
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static void log_data(FILE *f, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, f) != 1) {
        fprintf(stderr, "Failed to write pressure: %s\n", strerror(errno));
    }
    if (fwrite(&temperature, sizeof(float), 1, f) != 1) {
        fprintf(stderr, "Failed to write temperature: %s\n", strerror(errno));
    }
    fflush(f);
}

static void cleanup(void) {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s: %s\n", FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        float pressure, temperature;
        if (read_measurement(&pressure, &temperature) == 0) {
            log_data(fp, pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

