    return 0;
}

static void control_fan(float pressure_pa)
{
    int duty = (int)((pressure_pa / 100.0f) * (float)PWM_RANGE);
    if (duty < 0)   duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(FILE *fp, float pressure_pa)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure_pa);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(FAN_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float pressure_pa;
        if (read_pressure(g_i2c_handle, &pressure_pa) == 0) {
            control_fan(pressure_pa);
            log_data(g_log_file, pressure_pa);
        } else {
            fprintf(stderr, "Sensor read error — fan left at current duty\n");
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

