#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/*
 * STLM75 register map (datasheet rev 1.0):
 *   0x00  Temperature MSB (read-only, 2 bytes, 0.125 °C / LSB)
 *   0x01  Temperature LSB
 *   0x02  Point of interest (POI) register, write-only
 *   0x03  Configuration register (0x00 = power-down, 0x01 = active)
 *
 * To read the temperature: write 0x00 to 0x03 to set active mode,
 * wait, then read 2 bytes from 0x00.
 */
static int read_temperature(int handle, float *out_temp) {
    if (handle < 0) return -1;
    if (out_temp == NULL) return -1;

    /* Wake the sensor (active mode) */
    if (i2cWriteByteData(handle, 0x03, 0x01) < 0) {
        fprintf(stderr, "Error: failed to set STLM75 active mode\n");
        return -1;
    }

    /* Allow conversion to complete (~5.5 ms at 14-bit resolution) */
    gpioDelay(6000);

    /* Read MSB and LSB */
    int msb = i2cReadByteData(handle, 0x00);
    if (msb < 0) {
        fprintf(stderr, "Error: failed to read STLM75 MSB\n");
        return -1;
    }
    int lsb = i2cReadByteData(handle, 0x01);
    if (lsb < 0) {
        fprintf(stderr, "Error: failed to read STLM75 LSB\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | (uint16_t)lsb;
    /* 14-bit two's-complement, 0.125 °C / LSB */
    int16_t temp14 = (int16_t)(raw >> 2);
    *out_temp = (float)temp14 * 0.125f;

    /* Put sensor back to power-down to save power */
    if (i2cWriteByteData(handle, 0x03, 0x00) < 0) {
        fprintf(stderr, "Warning: failed to set STLM75 power-down\n");
    }

    return 0;
}

int main(void) {
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", GPIO_LED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- circular buffer --- */
    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    printf("STLM75 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping iteration\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        cb_add(&temp_buffer, temperature);
        float avg = cb_average(&temp_buffer);

        printf("Temperature: %.2f °C | Average: %.2f °C\n", temperature, avg);

        if (avg > TEMP_THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- cleanup --- */
    gpioWrite(GPIO_LED, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

