#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_MEASUREMENT_INTERVAL 5
#define SCD30_DATA_READY_TIMEOUT 60
#define SCD30_CO2_HIGH_THRESHOLD 1200
#define SCD30_CO2_LOW_THRESHOLD 800
#define LOG_FILE "air_quality.log"

/* SCD30 commands (16-bit, big-endian on the wire) */
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define SCD30_CMD_GET_DATA_READY_STATUS 0x0202
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_SERIAL_NUMBER 0x0600

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int scd30_write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int scd30_read_bytes(int handle, char *buf, int count) {
    int bytes_read = i2cReadDevice(handle, buf, count);
    if (bytes_read != count) {
        return -1;
    }
    return 0;
}

static int scd30_read_u16_le(int handle, uint16_t *value) {
    char buf[2];
    if (scd30_read_bytes(handle, buf, 2) != 0) {
        return -1;
    }
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int scd30_read_u32_le(int handle, uint32_t *value) {
    char buf[4];
    if (scd30_read_bytes(handle, buf, 4) != 0) {
        return -1;
    }
    *value = (uint32_t)((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]);
    return 0;
}

static int scd30_read_u16_le_with_crc(int handle, uint16_t *value, uint8_t *crc) {
    char buf[3];
    if (scd30_read_bytes(handle, buf, 3) != 0) {
        return -1;
    }
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    *crc = (uint8_t)buf[2];
    return 0;
}

static int scd30_init(int handle) {
    if (scd30_write_command(handle, SCD30_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        return -1;
    }
    return 0;
}

static int scd30_get_data_ready_status(int handle, int *ready) {
    if (scd30_write_command(handle, SCD30_CMD_GET_DATA_READY_STATUS) != 0) {
        return -1;
    }
    char buf[3];
    if (scd30_read_bytes(handle, buf, 3) != 0) {
        return -1;
    }
    uint16_t status;
    uint8_t crc;
    if (scd30_read_u16_le_with_crc(handle, &status, &crc) != 0) {
        return -1;
    }
    if (crc != 0xFF) {
        fprintf(stderr, "Warning: CRC mismatch on data-ready status (crc=0x%02X).\n", crc);
    }
    *ready = (status & 0x07FF) != 0;
    return 0;
}

static int scd30_read_measurement(int handle, sensor_data_t *data) {
    if (scd30_write_command(handle, SCD30_CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    char buf[18];
    if (scd30_read_bytes(handle, buf, 18) != 0) {
        return -1;
    }
    uint32_t co2_raw;
    uint16_t temp_raw;
    uint16_t hum_raw;
    if (scd30_read_u32_le(handle, &co2_raw) != 0) {
        return -1;
    }
    if (scd30_read_u16_le(handle, &temp_raw) != 0) {
        return -1;
    }
    if (scd30_read_u16_le(handle, &hum_raw) != 0) {
        return -1;
    }
    data->co2 = (int)co2_raw;
    data->temperature = -45.0f + (float)temp_raw / 100.0f;
    data->humidity = (float)hum_raw / 100.0f;
    return 0;
}

static void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    fprintf(fp, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    fprintf(fp, "%s,ERROR,%s\n", timestamp, message);
    fflush(fp);
}

static void ventilation_control(int co2_level) {
    if (co2_level < SCD30_CO2_LOW_THRESHOLD) {
        printf("Ventilation: OFF\n");
    } else if (co2_level < SCD30_CO2_HIGH_THRESHOLD) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        if (scd30_write_command(g_i2c_handle, SCD30_CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
            fprintf(stderr, "Warning: Failed to stop periodic measurement during cleanup.\n");
        }
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (addr=0x%02X). Is the SCD30 connected?\n", SCD30_I2C_ADDR);
        gpioTerminate();
        return 0;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (scd30_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: SCD30 initialisation failed.\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int data_ready = 0;
    int consecutive_errors = 0;

    while (g_running) {
        if (scd30_get_data_ready_status(g_i2c_handle, &data_ready) != 0) {
            log_error(g_log_file, "Failed to get data ready status");
            consecutive_errors++;
        } else if (data_ready) {
            if (scd30_read_measurement(g_i2c_handle, &sensor_data) != 0) {
                log_error(g_log_file, "Failed to read measurement");
                consecutive_errors++;
            } else {
                log_data(g_log_file, sensor_data);
                ventilation_control(sensor_data.co2);
                consecutive_errors = 0;
            }
        } else {
            if (consecutive_errors > SCD30_DATA_READY_TIMEOUT) {
                log_error(g_log_file, "Sensor data not ready after timeout");
                consecutive_errors = 0;
            }
            sleep(1);
        }
        sleep(SCD30_MEASUREMENT_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

