/*
 * SDP32 differential-pressure reader for Raspberry Pi 3 Model B+
 * Bus : I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Addr: 0x25 (SDP32 default 7-bit address)
 * Read: 9 bytes (pressure + temp + scale-factor, each with CRC-8)
 *       Byte layout: [P_msb P_lsb P_crc T_msb T_lsb T_crc S_msb S_lsb S_crc]
 *       CRC-8 polynomial 0x31, init 0xFF, no reflection.
 * Build: gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define SDP32_ADDR        0x25
#define I2C_BUS           1
#define READ_LEN          9
#define SAMPLE_MS         1000
#define MAX_RETRIES       3
#define CRC8_POLY         0x31
#define CRC8_INIT         0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no reflection)              */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tmv;
    char buf[32];
    if (localtime_r(&now, &tmv) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv) > 0)
        printf("[%s] ", buf);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                bus, addr, pigpio_error(h));
        return -1;
    }
    return h;
}

/*
 * Read 9 bytes from the SDP32.
 * Returns 0 on success, -1 on I/O error, +1 if the sensor is
 * definitely absent (no ACK on the first byte).
 */
static int sdp32_read(int handle, float *pressure_pa, float *temp_c)
{
    uint8_t buf[READ_LEN];
    int rc = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (rc != READ_LEN) {
        if (rc < 0)
            fprintf(stderr, "I2C read error (pigpio code %d): %s\n",
                    rc, pigpio_error(rc));
        else
            fprintf(stderr, "I2C short read: got %d of %d bytes\n", rc, READ_LEN);
        return -1;
    }

    /* Detect sensor-absent: no ACK on the first byte */
    if (rc == 0) {
        fprintf(stderr, "Sensor not responding (no ACK on first byte).\n");
        return 1;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc=0x%02X got=0x%02X).\n",
                crc8(&buf[0], 2), buf[2]);
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X got=0x%02X).\n",
                crc8(&buf[3], 2), buf[5]);
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch (calc=0x%02X got=0x%02X).\n",
                crc8(&buf[6], 2), buf[8]);
        return -1;
    }

    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0) – sensor data invalid.\n");
        return -1;
    }

    *pressure_pa = (float)raw_p / (float)scale;
    *temp_c      = (float)raw_t / 200.0f;   /* SDP32: 0.5 °C / LSB */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval_ms = SAMPLE_MS;

    install_signal_handlers();

    int opt;
    while ((opt = getopt(argc, argv, "i:")) != -1) {
        switch (opt) {
        case 'i':
            interval_ms = atoi(optarg);
            if (interval_ms <= 0) {
                fprintf(stderr, "Invalid interval '%s'; using default %d ms.\n",
                        optarg, SAMPLE_MS);
                interval_ms = SAMPLE_MS;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-i interval_ms]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2c_open(I2C_BUS, SDP32_ADDR);
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started on I2C bus %d, addr 0x%02X, interval %d ms.\n",
           I2C_BUS, SDP32_ADDR, interval_ms);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float pressure_pa, temp_c;
        int rc = sdp32_read(g_i2c_handle, &pressure_pa, &temp_c);

        if (rc == 0) {
            print_timestamp();
            printf("Pressure: %.2f Pa | Temperature: %.2f C\n",
                   pressure_pa, temp_c);
            consecutive_errors = 0;
        } else if (rc == 1) {
            /* Sensor absent – report and keep trying */
            print_timestamp();
            fprintf(stderr, "Sensor absent – check wiring and address.\n");
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            print_timestamp();
            fprintf(stderr, "Read failed (attempt %d/%d).\n",
                    consecutive_errors, MAX_RETRIES);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached – exiting.\n");
                break;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int ms = 0; ms < interval_ms && g_running; ms += 100)
            gpioDelay(100000);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

