/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   VDD  -> 3V3 (Pin 1)
 *   GND  -> GND (Pin 9)
 *   SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * I2C bus 1, address 0x24 (SDP810 default).
 * Reads 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc, scale(2)+crc.
 * Conversion time ~45 ms; samples every 1 s.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x24
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_TIME_US   45000      /* 45 ms conversion wait */
#define READ_LEN       9          /* 3 words × (2 data + 1 CRC) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte sample from the SDP810                              */
/* ------------------------------------------------------------------ */
static bool read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[READ_LEN];

    /* Trigger a measurement by writing a zero-length command byte. */
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte (trigger) failed: %s\n",
                strerror(errno));
        return false;
    }

    usleep(CONV_TIME_US);

    int rd = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (rd != READ_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d): %s\n",
                rd, READ_LEN, rd < 0 ? strerror(errno) : "short read");
        return false;
    }

    /* Word 0: differential pressure (Pa) */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on pressure word\n");
        return false;
    }

    /* Word 1: temperature (°C) */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature word\n");
        return false;
    }

    /* Word 2: scale factor 1 (pressure) */
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on scale-factor word 1\n");
        return false;
    }

    /* Word 3: scale factor 2 (temperature) */
    /* (Optional; present only on some SDP8xx variants.) */

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure / 240.0f;   /* Pa */
    *temperature = (float)raw_temp     / 200.0f;   /* °C */

    return true;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature)) {
            printf("Pressure: %7.2f Pa  |  Temperature: %6.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal. */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

