#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define CONVERSION_DELAY_MS 20
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_init(int fd) {
    /* Point to the temperature sensor (default power-on state) */
    if (i2c_write_byte(fd, 0x00) < 0) return -1;
    usleep(5000);
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity) {
    uint8_t buf[4];

    /* Trigger a 14-bit temperature and humidity conversion */
    if (i2c_write_byte(fd, 0x30) < 0) return -1;

    usleep(CONVERSION_DELAY_MS * 1000);

    /* Read 4 bytes: T_MSB, T_LSB, H_MSB, H_LSB */
    if (i2c_read_bytes(fd, buf, 4) < 0) return -1;

    uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t hum_raw  = ((uint16_t)buf[2] << 8) | buf[3];

    *temperature = ((float)temp_raw / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)hum_raw  / 65536.0f) * 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor may be absent)\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized. Logging every %d seconds. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (hdc1000_read(g_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
