#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49
#define READ_INTERVAL  5
#define MAX_RETRIES    3

/* Si7051 commands */
#define CMD_TEMP_HOLD   0xE3
#define CMD_TEMP_NOHOLD 0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read temperature in degrees Celsius from the Si7051.
 * Returns 0 on success, -1 on error. */
static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        /* Trigger a temperature measurement (no hold master mode). */
        result = i2cWriteByte(handle, CMD_TEMP_NOHOLD);
        if (result < 0) {
            fprintf(stderr, "Error: i2cWriteByte failed (trigger): %d\n", result);
            retries++;
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        /* Wait for conversion to complete (max ~36.65 ms for 14-bit). */
        gpioDelay(45000); /* 45 ms */

        /* Read 2 bytes of temperature data. */
        result = i2cReadDevice(handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n", result);
            retries++;
            gpioDelay(100000);
            continue;
        }

        /* Convert raw data to temperature in degrees Celsius.
         * Si7051: 14-bit two's complement, 0.0625 °C per LSB. */
        int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
        raw_temp >>= 2; /* Right-align 14-bit value */

        *temperature = (float)raw_temp * 0.0625f;
        return 0;
    }

    fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    float temperature;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to the Si7051 sensor. */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle: %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7051 Temperature Sensor Reader\n");
    printf("I2C Bus: %d, Address: 0x%02X\n", I2C_BUS, I2C_ADDR);
    printf("Logging every %d seconds. Press Ctrl+C to exit.\n\n", READ_INTERVAL);

    /* Main loop: read temperature and log to console. */
    while (g_running) {
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: Temperature read failed. Retrying next cycle.\n");
        }

        /* Sleep for the read interval, checking g_running every second for responsiveness. */
        for (int i = 0; i < READ_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean up resources on exit. */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

