#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x76
#define READ_INTERVAL  500000   /* microseconds (500 ms) */
#define MAX_RETRIES    3

/* MLX90833 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB  0x00
#define REG_PRESSURE_LSB  0x01
#define REG_TEMP_MSB     0x02
#define REG_TEMP_LSB     0x03
#define REG_MEAS_CFG     0x0A
#define REG_RESET        0x0B

/* Measurement configuration: start continuous conversion, 1 Hz, no interrupts */
#define MEAS_CFG_VAL     0x0001

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char wbuf[1] = { (char)reg };
    char rbuf[2];

    if (i2cWriteDevice(handle, wbuf, 1) < 0)
        return -1;
    if (i2cReadDevice(handle, rbuf, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
    return 0;
}

static int read_pressure(int handle, float *pressure)
{
    uint16_t raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, REG_PRESSURE_MSB, &raw) == 0) {
            /* 16-bit two's-complement, 0.1 hPa per LSB */
            int16_t signed_raw = (int16_t)raw;
            *pressure = (float)signed_raw * 0.1f;
            return 0;
        }
        retries++;
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

static void log_data(float pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Pressure: %.2f hPa\n", timestamp, pressure);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Software reset */
    if (i2c_write_reg16(g_i2c_handle, REG_RESET, 0x0001) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Configure measurement */
    if (i2c_write_reg16(g_i2c_handle, REG_MEAS_CFG, MEAS_CFG_VAL) < 0) {
        fprintf(stderr, "Error configuring measurement\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float pressure;
        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            log_data(pressure);
        } else {
            fprintf(stderr, "Error reading pressure after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(READ_INTERVAL);
    }

    /* Clean shutdown */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

