#define ICP10101_MEAS_CFG_MEAS_TRIG 0x01
#define ICP10101_MEAS_CFG_RESET 0x80

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_calibration_data(uint16_t calib[64]) {
    for (int i = 0; i < 64; i++) {
        int msb = i2cReadByteData(g_i2c_handle, ICP10101_REG_CALIB_0 + i * 2);
        if (msb < 0) {
            fprintf(stderr, "Error reading calibration data register 0x%02X: %d\n",
                    ICP10101_REG_CALIB_0 + i * 2, msb);
            return -1;
        }
        int lsb = i2cReadByteData(g_i2c_handle, ICP10101_REG_CALIB_0 + i * 2 + 1);
        if (lsb < 0) {
            fprintf(stderr, "Error reading calibration data register 0x%02X: %d\n",
                    ICP10101_REG_CALIB_0 + i * 2 + 1, lsb);
            return -1;
        }
        calib[i] = ((uint16_t)msb << 8) | (uint16_t)lsb;
    }
    return 0;
}

static int read_sensor_data(float *temperature, float *pressure) {
    int status = i2cWriteByteData(g_i2c_handle, ICP10101_REG_MEAS_CFG,
                                  ICP10101_MEAS_CFG_MEAS_TRIG);
    if (status < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", status);
        return -1;
    }

    gpioDelay(7000);

    int temp_msb = i2cReadByteData(g_i2c_handle, ICP10101_REG_TEMP_MSB);
    if (temp_msb < 0) {
        fprintf(stderr, "Error reading temperature MSB: %d\n", temp_msb);
        return -1;
    }
    int temp_lsb = i2cReadByteData(g_i2c_handle, ICP10101_REG_TEMP_LSB);
    if (temp_lsb < 0) {
        fprintf(stderr, "Error reading temperature LSB: %d\n", temp_lsb);
        return -1;
    }
    int press_msb = i2cReadByteData(g_i2c_handle, ICP10101_REG_PRESS_MSB);
    if (press_msb < 0) {
        fprintf(stderr, "Error reading pressure MSB: %d\n", press_msb);
        return -1;
    }
    int press_lsb = i2cReadByteData(g_i2c_handle, ICP10101_REG_PRESS_LSB);
    if (press_lsb < 0) {
        fprintf(stderr, "Error reading pressure LSB: %d\n", press_lsb);
        return -1;
    }
    int press_xlsb = i2cReadByteData(g_i2c_handle, ICP10101_REG_PRESS_XLSB);
    if (press_xlsb < 0) {
        fprintf(stderr, "Error reading pressure XLSB: %d\n", press_xlsb);
        return -1;
    }

    if (temp_msb == 0xFF && temp_lsb == 0xFF &&
        press_msb == 0xFF && press_lsb == 0xFF &&
        press_xlsb == 0xFF) {
        fprintf(stderr, "Sensor absent or not responding (all 0xFF)\n");
        return -1;
    }

    *temperature = ((float)temp_msb << 8 | (float)temp_lsb) / 100.0f;
    *pressure = ((float)press_msb << 16 | (float)press_lsb << 8 | (float)press_xlsb) / 64.0f;

    return 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("%s - ", buffer);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t calib[64];
    if (read_calibration_data(calib) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    float temperature, pressure;
    while (g_running) {
        if (read_sensor_data(&temperature, &pressure) == 0) {
            print_timestamp();
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n",
                   temperature, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(5000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

