#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x48
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] ", buf);
}

/*
 * Read a 16-bit big-endian value from the MLX90819.
 * Returns 0 on success, -1 on error.
 */
static int read_pressure(int fd, float *pressure_out)
{
    uint8_t reg = 0x00;          /* pressure register */
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        print_timestamp();
        fprintf(stderr, "Error: I2C write (reg select) failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Small delay so the sensor can clock out the data */
    usleep(1000);

    if (read(fd, buf, 2) != 2) {
        print_timestamp();
        fprintf(stderr, "Error: I2C read (pressure data) failed: %s\n",
                strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *pressure_out = (float)raw / 100.0f;   /* raw / 100 = Pa */
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    install_signal_handlers();

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        print_timestamp();
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        print_timestamp();
        fprintf(stderr, "Error: cannot set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure;

        if (read_pressure(fd, &pressure) == 0) {
            print_timestamp();
            printf("Pressure: %.2f Pa\n", pressure);
            fflush(stdout);
        } else {
            print_timestamp();
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);

    printf("\nExiting cleanly.\n");
    return rc;
}

