#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_DELAY_US 1000000  /* 1 second */
#define MEAS_DELAY_US   8000     /* 8 ms  */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * SDP800 continuous measurement: write 0x36 0x2F 0x08, then read 3 bytes
 * (MSB, LSB, CRC).  Returns 0 on success and fills *pressure_pa.
 */
static int sdp800_read(int fd, float *pressure_pa)
{
    uint8_t cmd[3] = { 0x36, 0x2F, 0x08 };
    ssize_t w = write(fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "write trigger: %s\n", strerror(errno));
        return -1;
    }
    usleep(MEAS_DELAY_US);

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read data: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_pa = (float)raw / 60.0f;   /* SDP800-500Pa: 1 Pa = 60 counts */
    return 0;
}

static int log_open(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (fp) {
        fclose(fp);
        return 0;                       /* file exists, append */
    }
    if (errno != ENOENT) {
        fprintf(stderr, "stat(%s): %s\n", path, strerror(errno));
        return -1;
    }
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "create(%s): %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp,pressure_pa\n");
    fclose(fp);
    return 0;
}

static void log_line(const char *path, float pressure)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "append(%s): %s\n", path, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0)
        return 1;

    if (log_open(LOG_FILE) < 0) {
        close(g_i2c_fd);
        return 1;
    }

    printf("SDP800 airflow logger started.  Ctrl-C to stop.\n");

    while (g_running) {
        float pressure;
        if (sdp800_read(g_i2c_fd, &pressure) == 0) {
            log_line(LOG_FILE, pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

