#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x76
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define SAFE_MIN_KPA   200.0
#define SAFE_MAX_KPA   250.0
#define MAX_RETRIES    2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and return a valid handle or -1 on failure          */
/* ------------------------------------------------------------------ */
static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure from the sensor (kPa). Returns 0 on success.          */
/* ------------------------------------------------------------------ */
static int read_pressure(float *pressure_kpa)
{
    char buf[2];
    int  bytes_read;

    bytes_read = i2cReadDevice(g_i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: got %d bytes, expected 2 (%s)\n",
                bytes_read, bytes_read < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Convert raw 16-bit big-endian value to kPa.
     * MLX90821 datasheet: pressure = raw * 0.01 kPa (example scaling). */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *pressure_kpa = (float)raw * 0.01f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped pressure reading to the CSV log.               */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure_kpa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kpa);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Check if pressure is within the safe tire range.                    */
/* ------------------------------------------------------------------ */
static void check_safe_range(float pressure_kpa)
{
    if (pressure_kpa < SAFE_MIN_KPA || pressure_kpa > SAFE_MAX_KPA) {
        fprintf(stderr,
                "[WARNING] Pressure %.2f kPa outside safe range [%.0f-%.0f] kPa\n",
                pressure_kpa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ------------------------------------------------ */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        float pressure_kpa;

        if (read_pressure(&pressure_kpa) == 0) {
            log_pressure(pressure_kpa);
            check_safe_range(pressure_kpa);
        } else {
            fprintf(stderr, "[ERROR] Pressure read failed; re-opening I2C bus.\n");
            /* Attempt recovery: close, reopen, retry once */
            if (open_i2c() != 0) {
                fprintf(stderr, "[FATAL] I2C recovery failed; exiting.\n");
                break;
            }
            if (read_pressure(&pressure_kpa) != 0) {
                fprintf(stderr, "[FATAL] Second read attempt failed; exiting.\n");
                break;
            }
            log_pressure(pressure_kpa);
            check_safe_range(pressure_kpa);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

