            }
            if (read_pressure(&pressure_kpa) != 0) {
                fprintf(stderr, "[FATAL] Second read attempt failed; exiting.\n");
                break;
            }
            log_pressure(pressure_kpa);
            check_safe_range(pressure_kpa);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

