#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define HIH6130_ADDR   0x40
#define LOG_FILE       "environmental_data.log"
#define MAX_LOG_SIZE   1048576  /* 1 MB */
#define MEAS_DELAY_US  40000    /* 40 ms conversion time */
#define SAMPLE_PERIOD  5        /* seconds between samples */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                ts, temperature, humidity) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from the HIH6130                      */
/* Returns 0 on success, -1 on I2C error, -2 on sensor status error   */
/* ------------------------------------------------------------------ */
static int read_hih6130(float *temperature, float *humidity)
{
    uint8_t buf[4];
    int rc;

    /* Trigger a measurement by writing a zero byte to the device */
    rc = i2cWriteByte(g_i2c_handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte (trigger) failed: %s\n", pigpio_error(rc));
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);  /* 40 ms conversion time */

    /* Read 4 bytes: [status, T_msb, T_lsb, RH_msb, RH_lsb, RH_tiny] */
    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 4);
    if (rc != 4) {
        fprintf(stderr, "i2cReadDevice failed: expected 4 bytes, got %d (%s)\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    /* Check status bits (bits 7:6 of byte 0) */
    uint8_t status = (buf[0] >> 6) & 0x03;
    if (status != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X (converting or stale)\n", status);
        return -2;
    }

    /* Convert raw values to physical units */
    uint16_t raw_t = ((uint16_t)(buf[1] & 0x3F) << 8) | buf[2];
    uint16_t raw_rh = (uint16_t)buf[3];

    *temperature = -46.85f + 175.72f * (float)raw_t / 65536.0f;

    /* Handle negative temperatures (HIH6130 is not strictly -40 to +125) */
    if (*temperature < -40.0f) {
        *temperature = -40.0f;
    } else if (*temperature > 125.0f) {
        *temperature = 125.0f;
    }

    *humidity = 100.0f * (float)raw_rh / 16383.0f;

    /* Clamp humidity to valid range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Check if the log file exceeds MAX_LOG_SIZE; if so, truncate it       */
/* ------------------------------------------------------------------ */
static int check_log_size(void)
{
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        /* File does not exist yet — nothing to check */
        return 0;
    }

    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        fclose(fp);
        return 0;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose (size check) failed: %s\n", strerror(errno));
        return 0;
    }

    if (pos > MAX_LOG_SIZE) {
        if (unlink(LOG_FILE) != 0) {
            fprintf(stderr, "Warning: could not truncate %s: %s\n",
                    LOG_FILE, strerror(errno));
        }
    }
    return 0;
}

