{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to HIH6130 */
    g_i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure log file is small enough before starting */
    check_log_size();

    float temperature, humidity;

    while (g_running) {
        int rc = read_hih6130(&temperature, &humidity);

        if (rc == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else if (rc == -1) {
            fprintf(stderr, "I2C communication error — continuing\n");
        } else {
            fprintf(stderr, "Sensor status error — continuing\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

