/*
 * MLX90824 SENT pressure sensor reader for Raspberry Pi 3 Model B+
 * Protocol: SENT single-wire, 3 us tick time, 4 nibbles (status, 3 data, checksum)
 * Valid nibble range: 12-271 ticks (36-813 us)
 * Synchronization pulse: 56 ticks
 * Log format: YYYY-MM-DD HH:MM:SS, Pressure: XXXX.XX Pa
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "pressure_log.txt"
#define TIMEOUT_US 1000000  /* 1 second timeout for SENT sync pulse */
#define TICK_US 3           /* 3 us tick time */
#define MIN_NIBBLE 12
#define MAX_NIBBLE 271
#define SYNC_TICKS 56

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a SENT nibble from the GPIO line.
 * Returns the nibble value (0-15) on success, or -1 on timeout/error.
 */
static int read_nibble(int gpio_pin) {
    uint32_t start_tick, end_tick, pulse_width;
    int level, count;

    /* Wait for the falling edge (sync pulse start) */
    count = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1);
        if (++count > TIMEOUT_US) {
            fprintf(stderr, "Error: SENT sync pulse timeout (line stuck high)\n");
            return -1;
        }
    }

    /* Measure the sync pulse width (falling edge to falling edge) */
    start_tick = gpioTick();
    count = 0;
    while (gpioRead(gpio_pin) == 0) {
        gpioDelay(1);
        if (++count > TIMEOUT_US) {
            fprintf(stderr, "Error: SENT sync pulse timeout (line stuck low)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    /* Validate sync pulse width */
    if (pulse_width < (SYNC_TICKS * TICK_US) - 10 || pulse_width > (SYNC_TICKS * TICK_US) + 10) {
        fprintf(stderr, "Error: SENT sync pulse out of range (%u us)\n", pulse_width);
        return -1;
    }

    /* Wait for the rising edge (end of sync pulse) */
    count = 0;
    while (gpioRead(gpio_pin) == 0) {
        gpioDelay(1);
        if (++count > TIMEOUT_US) {
            fprintf(stderr, "Error: SENT sync pulse timeout (line stuck low)\n");
            return -1;
        }
    }

    /* Measure the data nibble pulse width (rising edge to falling edge) */
    start_tick = gpioTick();
    count = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1);
        if (++count > TIMEOUT_US) {
            fprintf(stderr, "Error: SENT data pulse timeout (line stuck high)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    /* Validate data nibble pulse width */
    if (pulse_width < (MIN_NIBBLE * TICK_US) - 10 || pulse_width > (MAX_NIBBLE * TICK_US) + 10) {
        fprintf(stderr, "Error: SENT data nibble out of range (%u us)\n", pulse_width);
        return -1;
    }

    /* Convert pulse width to nibble value (12-271 ticks maps to 0-15) */
    return (pulse_width / TICK_US) - 12;
}

/*
 * Read 4 SENT nibbles and validate the checksum.
 * Returns 0 on success, -1 on error.
 */
static int read_sent_data(int gpio_pin, float *pressure) {
    int nibbles[4];
    int sum;

    for (int i = 0; i < 4; i++) {
        nibbles[i] = read_nibble(gpio_pin);
        if (nibbles[i] < 0) {
            return -1;
        }
    }

    /* Validate nibble ranges */
    for (int i = 0; i < 4; i++) {
        if (nibbles[i] < 0 || nibbles[i] > 15) {
            fprintf(stderr, "Error: SENT nibble %d out of range\n", i);
            return -1;
        }
    }

    /* Calculate checksum */
    sum = nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3];

    /* Checksum validation: (nibbles[0] + nibbles[1] + nibbles[2]) should equal nibbles[3] */
    if (sum != nibbles[3]) {
        fprintf(stderr, "Error: SENT checksum mismatch (calculated: %d, received: %d)\n", sum, nibbles[3]);
        return -1;
    }

    /* Extract pressure data nibbles (nibbles 1, 2, 3) */
    int data_nibbles[3] = {nibbles[1], nibbles[2], nibbles[3]};

    /* Convert nibbles to pressure (example linear mapping) */
    *pressure = (data_nibbles[0] * 100.0f) + (data_nibbles[1] * 50.0f) + (data_nibbles[2] * 10.0f);

    return 0;
}

static void log_pressure(float pressure) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[20];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        return;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: Failed to convert time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        return;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    float pressure;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin as input */
    gpioSetMode(GPIO_PIN, PI_INPUT);

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 SENT pressure sensor reader started on GPIO%d.\n", GPIO_PIN);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main loop */
    while (running) {
        if (read_sent_data(GPIO_PIN, &pressure) == 0) {
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Warning: Failed to read valid SENT data\n");
        }

        /* Sleep 1 second between readings */
        sleep(1);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    printf("Program terminated.\n");

    return EXIT_SUCCESS;
}

