#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5

#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01
#define TMP117_CONFIG_DEFAULT 0x0000

#define LOG_FILE "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static CircularBuffer g_buffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, time_t ts, float temp) {
    buf->readings[buf->head].timestamp = ts;
    buf->readings[buf->head].temperature = temp;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_flush(CircularBuffer *buf, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return;
    }
    int start = (buf->count == BUFFER_SIZE) ? buf->head : 0;
    int n = buf->count;
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (fwrite(&buf->readings[idx], sizeof(TemperatureReading), 1, fp) != 1) {
            perror("fwrite");
            break;
        }
    }
    if (fclose(fp) != 0) perror("fclose");
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val) {
    char buf[3] = {reg, (char)(val & 0xFF), (char)((val >> 8) & 0xFF)};
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val) {
    char reg_buf[1] = {reg};
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int read_temperature(int handle, float *temp) {
    uint16_t raw;
    if (i2c_read_reg16(handle, TMP117_REG_TEMP, &raw) < 0) return -1;
    *temp = (float)raw * 0.0078125f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", TMP117_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg16(g_i2c_handle, TMP117_REG_CONFIG, TMP117_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to configure TMP117\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        float temperature;
        time_t now = time(NULL);
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            buffer_add(&g_buffer, now, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    buffer_flush(&g_buffer, LOG_FILE);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

