/*
 * SHTC3 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHTC3 VDD  -> Pin 1 (3.3 V)
 *   SHTC3 VSS  -> Pin 2 (GND)
 *   SHTC3 SDA  -> Pin 3 (GPIO2 / I2C1 SDA)
 *   SHTC3 SCL  -> Pin 4 (GPIO3 / I2C1 SCL)
 *
 * Build:  gcc -O2 -Wall -Wextra -o shtc3_logger shtc3_logger.c -li2c -lm
 * Run:    sudo ./shtc3_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHTC3_ADDR     0x49
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_DELAY_US  14000      /* 14 ms worst-case conversion time */

/* SHTC3 commands (16-bit, big-endian on the bus) */
#define CMD_MEASURE_T_RH  0x2C06   /* single measurement, clock stretching disabled */
#define CMD_SLEEP         0x00FF   /* soft reset / sleep (write 0x00FF then power down) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0x00)                         */
/* ------------------------------------------------------------------ */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write cmd 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[I2C] read %zu bytes failed: %s\n", len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHTC3 measurement                                                   */
/* ------------------------------------------------------------------ */
typedef struct {
    float temperature;
    float humidity;
    bool  valid;
} shtc3_data_t;

static shtc3_data_t shtc3_read(int fd)
{
    shtc3_data_t d = { NAN, NAN, false };

    if (i2c_write_cmd(fd, CMD_MEASURE_T_RH) < 0)
        return d;

    usleep(CONV_DELAY_US);

    uint8_t data[6];
    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return d;

    /* CRC checks: bytes 0-1, 3-4, 5-6 */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHTC3] temperature CRC mismatch\n");
        return d;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHTC3] humidity CRC mismatch\n");
        return d;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    /* Temperature: 7-bit signed, 0.01 °C / LSB */
    int16_t t_signed = (int16_t)t_raw;
    d.temperature = t_signed * 0.01f;

    /* Humidity: 14-bit signed, 0.01 %RH / LSB */
    int16_t h_signed = (int16_t)h_raw;
    d.humidity = h_signed * 0.01f;

    /* Sanity range checks */
    if (isnan(d.temperature) || isnan(d.humidity) ||
        d.temperature < -40.0f || d.temperature > 125.0f ||
        d.humidity < 0.0f   || d.humidity > 100.0f) {
        fprintf(stderr, "[SHTC3] out-of-range: T=%.2f C, H=%.2f %%\n",
                d.temperature, d.humidity);
        return d;
    }

    d.valid = true;
    return d;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    } else {
        fprintf(fp, "(time-error),%.2f,%.2f\n", temp, rh);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "[LOG] error closing %s: %s\n", LOG_FILE, strerror(errno));
}

static void print_data(float temp, float rh)
{
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, rh);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Best-effort soft reset / power-down */
        (void)i2c_write_cmd(g_i2c_fd, CMD_SLEEP);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[I2C] cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHTC3_ADDR) < 0) {
        fprintf(stderr, "[I2C] ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SHTC3_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Soft reset / power-down to a known state */
    (void)i2c_write_cmd(g_i2c_fd, CMD_SLEEP);

    printf("SHTC3 logger started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        shtc3_data_t d = shtc3_read(g_i2c_fd);

        if (d.valid) {
            log_data(d.temperature, d.humidity);
            print_data(d.temperature, d.humidity);
        } else {
            fprintf(stderr, "[SHTC3] read failed; will retry next cycle.\n");
        }

        /* Sleep in 1 s increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

