                SHTC3_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Soft reset / power-down to a known state */
    (void)i2c_write_cmd(g_i2c_fd, CMD_SLEEP);

    printf("SHTC3 logger started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        shtc3_data_t d = shtc3_read(g_i2c_fd);

        if (d.valid) {
            log_data(d.temperature, d.humidity);
            print_data(d.temperature, d.humidity);
        } else {
            fprintf(stderr, "[SHTC3] read failed; will retry next cycle.\n");
        }

        /* Sleep in 1 s increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

