#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x60
#define SI7202_REG_SPEED 0x00
#define SI7202_REG_TEMP 0x02
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SI7202_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *speed, float *temperature) {
    char buf[2];

    if (i2cReadI2CBlockData(i2c_handle, SI7202_REG_SPEED, buf, 2) != 2) {
        fprintf(stderr, "Error reading speed data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_speed = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *speed = (float)raw_speed / 100.0f;

    if (i2cReadI2CBlockData(i2c_handle, SI7202_REG_TEMP, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

static int log_data(float speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, speed, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int create_log_file(void) {
    FILE *check = fopen(LOG_FILE, "r");
    if (check != NULL) {
        fclose(check);
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n") < 0) {
        fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file after header: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (create_log_file() != 0) {
        cleanup();
        return 1;
    }

    float speed, temperature;

    while (running) {
        if (read_sensor_data(&speed, &temperature) == 0) {
            if (log_data(speed, temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Logging NaN values.\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Error logging NaN values.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

