#define MAX_RETRIES    3
#define SAMPLE_US      1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_c)
{
    int raw = i2cReadWordData(g_i2c_handle, TMP117_REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }

    /* TMP117 returns data in two's-complement format; pigpio returns
       the word as (msb << 8) | lsb, so the value is already signed. */
    int16_t signed_raw = (int16_t)raw;
    *temp_c = (float)signed_raw * 0.0078125f;
    return 0;
}

static void log_temperature(float temp_c)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temp_c);
    fclose(fp);
}

