                fprintf(stderr, "Max consecutive failures (%d) reached. Exiting.\n",
                        MAX_RETRIES);
                break;
            }
            fprintf(stderr, "Retrying I2C initialization (%d/%d)...\n",
                    consecutive_failures, MAX_RETRIES);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
