#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "I2C read failed: expected 4 bytes, got %d: %s\n",
                bytes_read, strerror(errno));
        return -1;
    }
    return 0;
}

static int process_sensor_data(const uint8_t *data, float *flow, float *temperature) {
    uint16_t raw_flow = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temp = ((uint16_t)data[2] << 8) | data[3];

    *flow = (float)raw_flow / 65535.0f * 25.0f;
    *temperature = (float)raw_temp / 4095.0f * 165.0f - 40.0f;
    return 0;
}

static int log_data(float flow, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, flow, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    uint8_t sensor_data[4];
    float flow, temperature;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting airflow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensor_data(sensor_data) == 0) {
            consecutive_errors = 0;
            if (process_sensor_data(sensor_data, &flow, &temperature) == 0) {
                if (log_data(flow, temperature) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error processing sensor data.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading sensor data (consecutive: %d).\n", consecutive_errors);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors reached. Attempting I2C re-initialization.\n");
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

