#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>

/* DHT11 timing constants (microseconds) */
#define DHT11_START_LOW_US   20000   /* 20 ms low start signal  */
#define DHT11_START_HIGH_US  30      /* 30 us release           */
#define DHT11_RESP_LOW_US    80      /* 80 us response low      */
#define DHT11_RESP_HIGH_US   80      /* 80 us response high     */
#define DHT11_BIT_LOW_US     50      /* 50 us low preamble      */
#define DHT11_TIMEOUT_US     200     /* per-phase timeout       */
#define DHT11_BIT_THRESHOLD  50      /* >50 us high = '1'       */

/* DHT11 timing guard bands (microseconds) */
#define DHT11_LOW_GUARD_US   40      /* guard below 50 us low   */
#define DHT11_HIGH_GUARD_US  40      /* guard below 50 us high  */

/* DHT11 bit timing */
#define DHT11_BIT_COUNT      40
#define DHT11_DATA_BITS      5

/* DHT11 timing margin */
#define DHT11_MARGIN_US      10

/* DHT11 sampling interval */
#define DHT11_SAMPLE_INTERVAL_S 2

/* DHT11 file paths */
#define DHT11_READINGS_FILE  "dht11_readings.txt"
#define DHT11_ERRORS_FILE   "dht11_errors.log"

/* Error codes */
#define DHT11_OK             0
#define DHT11_ERROR_TIMEOUT  1
#define DHT11_ERROR_CHECKSUM 2
#define DHT11_ERROR_GPIO     3
#define DHT11_ERROR_SENSOR   4

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_gpio_initialized = 0;
static FILE *g_readings_fp     = NULL;
static FILE *g_errors_fp       = NULL;

/* ------------------------------------------------------------------ */
/* Microsecond delay helper (busy-wait, acceptable for 1 Hz sampling) */
/* ------------------------------------------------------------------ */
static inline void delay_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = (time_t)(us / 1000000U);
    ts.tv_nsec = (long)((us % 1000000U) * 1000L);
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers (bit-bang via library primitives)                     */
/* ------------------------------------------------------------------ */
static int gpio_write(int pin, int level)
{
    if (gpio_write(pin, level) != 0) {
        fprintf(stderr, "gpio_write(pin=%d, level=%d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int gpio_read(int pin)
{
    int v = gpio_read(pin);
    if (v < 0) {
        fprintf(stderr, "gpio_read(pin=%d) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* DHT11 read with full error handling                                */
/* ------------------------------------------------------------------ */
static int dht11_read(int pin, float *temperature, float *humidity)
{
    uint8_t data[DHT11_BIT_COUNT];
    int     i, bit;
    int     level;
    uint32_t start_tick, now_tick;
    int     prev_level = -1;

    /* ---- Start signal: pull low for >= 18 ms, then release ---- */
    if (gpio_write(pin, 0) != 0) return DHT11_ERROR_GPIO;
    delay_us(DHT11_START_LOW_US);
    if (gpio_write(pin, 1) != 0) return DHT11_ERROR_GPIO;
    delay_us(DHT11_START_HIGH_US);

    /* ---- Sensor response: 80 us low then 80 us high ---- */
    start_tick = (uint32_t)(clock() * 1000U);   /* ms since epoch */
    do {
        level = gpio_read(pin);
        if (level < 0) return DHT11_ERROR_GPIO;
        if (level != prev_level) {
            now_tick = (uint32_t)(clock() * 1000U);
            if ((now_tick - start_tick) > DHT11_TIMEOUT_US)
                return DHT11_ERROR_TIMEOUT;
            prev_level = level;
        }
    } while (level == 0);
    /* Wait for response high to end (sensor may hold >80 us) */
    do {
        level = gpio_read(pin);
        if (level < 0) return DHT11_ERROR_GPIO;
        if (level != prev_level) {
            now_tick = (uint32_t)(clock() * 1000U);
            if ((now_tick - start_tick) > DHT11_TIMEOUT_US)
                return DHT11_ERROR_TIMEOUT;
            prev_level = level;
        }
    } while (level == 1);

    /* ---- Read 40 data bits ---- */
    for (bit = 0; bit < DHT11_BIT_COUNT; bit++) {
        /* Low preamble: 50 us */
        start_tick = (uint32_t)(clock() * 1000U);
        do {
            level = gpio_read(pin);
            if (level < 0) return DHT11_ERROR_GPIO;
            if (level != prev_level) {
                now_tick = (uint32_t)(clock() * 1000U);
                if ((now_tick - start_tick) > DHT11_TIMEOUT_US)
                    return DHT11_ERROR_TIMEOUT;
                prev_level = level;
            }
        } while (level == 1);

        /* High duration: ~26-28 us = '0', ~70 us = '1' */
        start_tick = (uint32_t)(clock() * 1000U);
        do {
            level = gpio_read(pin);
            if (level < 0) return DHT11_ERROR_GPIO;
            if (level != prev_level) {
                now_tick = (uint32_t)(clock() * 1000U);
                if ((now_tick - start_tick) > DHT11_TIMEOUT_US)
                    return DHT11_ERROR_TIMEOUT;
                prev_level = level;
            }
        } while (level == 0);

        /* Measure high duration to decide bit value */
        start_tick = (uint32_t)(clock() * 1000U);
        do {
            level = gpio_read(pin);
            if (level < 0) return DHT11_ERROR_GPIO;
            if (level != prev_level) {
                now_tick = (uint32_t)(clock() * 1000U);
                if ((now_tick - start_tick) > DHT11_TIMEOUT_US)
                    return DHT11_ERROR_TIMEOUT;
                prev_level = level;
            }
        } while (level == 1);

        uint32_t high_us = (uint32_t)(clock() * 1000U) - start_tick;
        data[bit] = (high_us > DHT11_BIT_THRESHOLD) ? 1 : 0;
    }

    /* ---- Checksum ---- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: calc=0x%02X recv=0x%02X\n",
                checksum, data[4]);
        return DHT11_ERROR_CHECKSUM;
    }

    /* ---- Convert ---- */
    uint16_t raw_humidity    = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temperature = ((uint16_t)data[2] << 8) | data[3];

    *humidity    = (float)raw_humidity    / 10.0f;
    *temperature = (float)raw_temperature / 10.0f;

    return DHT11_OK;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                    */
/* ------------------------------------------------------------------ */
static void log_reading(float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (g_readings_fp) {
        fprintf(g_readings_fp, "%s,%.1f,%.1f\n", ts, temperature, humidity);
        fflush(g_readings_fp);
    }
    printf("%s  T=%.1f C  H=%.1f %%\n", ts, temperature, humidity);
}

static void log_error(int code, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (g_errors_fp) {
        fprintf(g_errors_fp, "%s,ERROR,%d,%s\n", ts, code, msg);
        fflush(g_errors_fp);
    }
    fprintf(stderr, "%s,ERROR,%d,%s\n", ts, code, msg);
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_gpio_initialized) {
        gpio_cleanup();
        g_gpio_initialized = 0;
    }
    if (g_readings_fp) {
        fclose(g_readings_fp);
        g_readings_fp = NULL;
    }
    if (g_errors_fp) {
        fclose(g_errors_fp);
        g_errors_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open error log */
    g_errors_fp = fopen(DHT11_ERRORS_FILE, "a");
    if (!g_errors_fp) {
        perror("fopen(" DHT11_ERRORS_FILE ")");
        return EXIT_FAILURE;
    }

    /* Open readings file (append) */
    g_readings_fp = fopen(DHT11_READINGS_FILE, "a");
    if (!g_readings_fp) {
        perror("fopen(" DHT11_READINGS_FILE ")");
        fclose(g_errors_fp);
        g_errors_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Initialize GPIO via library */
    if (gpio_init() != 0) {
        log_error(DHT11_ERROR_GPIO, "gpio_init failed");
        cleanup();
        return EXIT_FAILURE;
    }
    g_gpio_initialized = 1;

    /* Configure GPIO4 as input */
    if (gpio_configure(4, GPIO_INPUT) != 0) {
        log_error(DHT11_ERROR_GPIO, "gpio_configure failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("DHT11 reader started on GPIO4. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int rc = dht11_read(4, &temperature, &humidity);

        if (rc == DHT11_OK) {
            log_reading(temperature, humidity);
        } else {
            const char *msg;
            switch (rc) {
                case DHT11_ERROR_TIMEOUT:  msg = "timeout"; break;
                case DHT11_ERROR_CHECKSUM: msg = "checksum"; break;
                case DHT11_ERROR_GPIO:    msg = "GPIO";     break;
                case DHT11_ERROR_SENSOR:  msg = "sensor";   break;
                default:                   msg = "unknown";  break;
            }
            log_error(rc, msg);
        }

        /* Sleep DHT11 minimum interval (1 s) between reads */
        sleep(DHT11_SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

