    g_errors_fp = fopen(DHT11_ERRORS_FILE, "a");
    if (!g_errors_fp) {
        perror("fopen(" DHT11_ERRORS_FILE ")");
        return EXIT_FAILURE;
    }

    /* Open readings file (append) */
    g_readings_fp = fopen(DHT11_READINGS_FILE, "a");
    if (!g_readings_fp) {
        perror("fopen(" DHT11_READINGS_FILE ")");
        fclose(g_errors_fp);
        g_errors_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Initialize GPIO via library */
    if (gpio_init() != 0) {
        log_error(DHT11_ERROR_GPIO, "gpio_init failed");
        cleanup();
        return EXIT_FAILURE;
    }
    g_gpio_initialized = 1;

    /* Configure GPIO4 as input */
    if (gpio_configure(4, GPIO_INPUT) != 0) {
        log_error(DHT11_ERROR_GPIO, "gpio_configure failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("DHT11 reader started on GPIO4. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int rc = dht11_read(4, &temperature, &humidity);

        if (rc == DHT11_OK) {
            log_reading(temperature, humidity);
        } else {
            const char *msg;
            switch (rc) {
                case DHT11_ERROR_TIMEOUT:  msg = "timeout"; break;
                case DHT11_ERROR_CHECKSUM: msg = "checksum"; break;
                case DHT11_ERROR_GPIO:    msg = "GPIO";     break;
                case DHT11_ERROR_SENSOR:  msg = "sensor";   break;
                default:                   msg = "unknown";  break;
            }
            log_error(rc, msg);
        }

        /* Sleep DHT11 minimum interval (1 s) between reads */
        sleep(DHT11_SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

