#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x49
#define MEASURE_CMD    0x2C
#define LOG_FILE       "sht31d_data.log"
#define READ_INTERVAL  5
#define MAX_RETRIES    3
#define MEASURE_DELAY  20000  /* microseconds (20 ms) */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 polynomial 0x31, initial value 0x00 (Sensirion spec) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sht31d(int handle, sensor_data_t *data) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (rc < 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", attempt + 1, rc);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASURE_DELAY);

        rc = i2cReadDevice(handle, (char *)buf, 6);
        if (rc < 0) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", attempt + 1, rc);
            gpioDelay(100000);
            continue;
        }
        if (rc != 6) {
            fprintf(stderr, "I2C short read (attempt %d): got %d bytes\n", attempt + 1, rc);
            gpioDelay(100000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
        uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

        data->temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
        data->humidity    = 100.0f * (float)h_raw / 65535.0f;
        return 0;
    }

    return -1;
}

static int log_data(FILE *fp, float temp, float hum) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed in error log\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    sensor_data_t sensor_data;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT31-D logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, READ_INTERVAL);

    while (!terminate) {
        if (read_sht31d(i2c_handle, &sensor_data) == 0) {
            if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; logging error.\n", MAX_RETRIES);
            log_error(log_file, "sensor_read_failed");
        }

        for (int i = 0; i < READ_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

