/*
 * ADPD105 Dual-Channel Photometric Front-End — Color Temperature Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensors: 2 × ADPD105 (each at 0x48, 0x49) — 16-bit RGB data registers
 * Output:  cct_log.csv  (Timestamp,Average_CCT)
 *
 * Build:  gcc -O2 -Wall -Wextra -o cct_logger cct_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    2
#define LOG_FILE       "cct_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MAX_RETRIES    3          /* consecutive failures before abort */

/* ADPD105 register addresses (16-bit data registers, big-endian on bus) */
#define ADPD105_REG_DATA0 0x00A8  /* Red   data (2 bytes, big-endian) */
#define ADPD105_REG_DATA1 0x00AA  /* Green data (2 bytes, big-endian) */
#define ADPD105_REG_DATA2 0x00AC  /* Blue  data (2 bytes, big-endian) */

#define ADPD105_ADDR_0 0x48
#define ADPD105_ADDR_1 0x49

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("open(I2C bus)");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a 16-bit value to a 16-bit-indexed ADPD105 register.
 * The ADPD105 expects big-endian register addressing and data.
 */
static int adpd105_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        perror("write(reg16)");
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from a 16-bit-indexed ADPD105 register.
 * The ADPD105 returns data in big-endian format.
 */
static int adpd105_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    uint8_t data[2];

    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        perror("write(reg16 addr)");
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        perror("read(reg16 data)");
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                 */
/* ------------------------------------------------------------------ */

typedef struct {
    int  fd;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    int    valid;
} sensor_t;

static sensor_t sensors[NUM_SENSORS];

static int init_sensors(void)
{
    uint8_t addrs[NUM_SENSORS] = { ADPD105_ADDR_0, ADPD105_ADDR_1 };

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].fd = -1;
        sensors[i].valid = 0;

        sensors[i].fd = i2c_open(I2C_BUS, addrs[i]);
        if (sensors[i].fd < 0) {
            fprintf(stderr, "Failed to open I2C device at 0x%02X\n", addrs[i]);
            continue;
        }

        /* Probe: attempt a register read to confirm the device is present */
        uint16_t dummy;
        if (adpd105_read_reg16(sensors[i].fd, ADPD105_REG_DATA0, &dummy) < 0) {
            fprintf(stderr, "No ADPD105 detected at 0x%02X\n", addrs[i]);
            close(sensors[i].fd);
            sensors[i].fd = -1;
            continue;
        }

        sensors[i].valid = 1;
        printf("ADPD105 at 0x%02X initialized\n", addrs[i]);
    }

    return 0;
}

static int read_sensor_data(int idx)
{
    if (sensors[idx].fd < 0 || !sensors[idx].valid)
        return -1;

    if (adpd105_read_reg16(sensors[idx].fd, ADPD105_REG_DATA0, &sensors[idx].red) < 0)
        return -1;
    if (adpd105_read_reg16(sensors[idx].fd, ADPD105_REG_DATA1, &sensors[idx].green) < 0)
        return -1;
    if (adpd105_read_reg16(sensors[idx].fd, ADPD105_REG_DATA2, &sensors[idx].blue) < 0)
        return -1;

    return 0;
}

static double calculate_cct(const sensor_t *s1, const sensor_t *s2)
{
    /*
     * Simplified linear interpolation of color temperature.
     * A real application would use a calibrated lookup table or
     * a physically-accurate model based on the sensor's spectral
     * responsivity and the illuminant's spectrum.
     */
    double r1 = (double)s1->red / 65535.0;
    double g1 = (double)s1->green / 65535.0;
    double b1 = (double)s1->blue / 65535.0;

    double r2 = (double)s2->red / 65535.0;
    double g2 = (double)s2->green / 65535.0;
    double b2 = (double)s2->blue / 65535.0;

    double t1 = 6504.0 + 1831.0 * g1 - 383.0 * b1;
    double t2 = 6504.0 + 1831.0 * g2 - 383.0 * b2;

    return t1 + (t2 - t1) * 0.5;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_data(double cct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, cct);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_sensors() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Create log file with header if it does not exist */
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Average_CCT\n");
            fclose(fp);
        } else {
            perror("fopen(log, create)");
            return EXIT_FAILURE;
        }
    } else {
        fclose(fp);
    }

    int consecutive_failures = 0;

    while (g_running) {
        int read_ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_sensor_data(i) < 0) {
                fprintf(stderr, "Read failed for sensor %d\n", i);
                read_ok = 0;
            }
        }

        if (!read_ok) {
            consecutive_failures++;
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive failures reached. Exiting.\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }

        consecutive_failures = 0;

        double cct = 0.0;
        int valid_count = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (sensors[i].valid) {
                cct += calculate_cct(&sensors[i], &sensors[(i + 1) % NUM_SENSORS]);
                valid_count++;
            }
        }

        if (valid_count == NUM_SENSORS) {
            double avg_cct = cct / NUM_SENSORS;
            if (log_data(avg_cct) < 0) {
                fprintf(stderr, "Logging failed.\n");
            } else {
                printf("Average CCT: %.2f K\n", avg_cct);
            }
        } else {
            fprintf(stderr, "Not all sensors valid. Skipping log entry.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Clean up: close I2C handles and close log file */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].fd >= 0) {
            close(sensors[i].fd);
            sensors[i].fd = -1;
        }
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

