#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x76
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/* MLX90824 register addresses (16-bit, big-endian on the bus) */
#define MLX90824_REG_PRESSURE 0x00
#define MLX90824_REG_TEMP     0x02
#define MLX90824_REG_MEAS_CFG 0x08
#define MLX90824_REG_RESET    0x0F

#define MLX90824_RESET_CMD    0x01
#define MLX90824_MEAS_CFG_DEFAULT 0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (char)reg;
    if (i2cWriteDevice(handle, buf, 1) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_mlx90824(int handle) {
    if (i2c_write_reg16(handle, MLX90824_REG_RESET, MLX90824_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset MLX90824 (pigpio error %d)\n", pigpio_error(handle));
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset settling */

    if (i2c_write_reg16(handle, MLX90824_REG_MEAS_CFG, MLX90824_MEAS_CFG_DEFAULT) < 0) {
        fprintf(stderr, "Error: Failed to configure measurement on MLX90824\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for config to take effect */
    return 0;
}

static int read_mlx90824(int handle, float *pressure, float *temperature) {
    uint16_t raw_pressure, raw_temp;

    if (i2c_read_reg16(handle, MLX90824_REG_PRESSURE, &raw_pressure) < 0) {
        fprintf(stderr, "Error: Failed to read pressure register\n");
        return -1;
    }

    if (i2c_read_reg16(handle, MLX90824_REG_TEMP, &raw_temp) < 0) {
        fprintf(stderr, "Error: Failed to read temperature register\n");
        return -1;
    }

    /* Convert raw values to physical units (example scaling factors) */
    *pressure    = (float)raw_pressure    * 0.1f;
    *temperature = (float)raw_temp        * 0.01f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    fprintf(fp, "%s, ERROR: %s\n", timestamp, msg);
    fflush(fp);
}

int main(void) {
    float pressure, temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mlx90824(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MLX90824 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90824 pressure logger started. Logging to %s every %d seconds.\n", LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_mlx90824(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            log_error(g_log_file, "Sensor read failed");
            fprintf(stderr, "Warning: Sensor read failed, logged error.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

