#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define SAMPLE_INTERVAL_US  1000000
#define MAX_RETRIES       3

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
