/*
 * SDP810-500Pa differential-pressure monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_monitor sdp810_monitor.c
 * Run:    ./sdp810_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* SDP810 default 7-bit address */
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms first-measurement wait */
#define READ_LEN       9             /* 3 words × (2 data + 1 CRC) */
#define PRESSURE_THRESHOLD 5.0f      /* Pa */

/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF, no reflection */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

typedef struct {
    float pressure;     /* Pa */
    float temperature;  /* °C */
} sensor_data_t;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(sensor_data_t *data)
{
    uint8_t cmd[2] = { 0x36, 0x2E };   /* continuous measurement, no averaging */
    uint8_t buf[READ_LEN];

    /* Issue the measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the first conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale_factor(2)+crc */
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "I2C read failed (got %d bytes, expected %d): %s\n",
                n, READ_LEN, strerror(errno));
        return -1;
    }

    /* CRC validation */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale-factor word\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    data->pressure    = (float)raw_pressure    / 60.0f;   /* Pa  */
    data->temperature = (float)raw_temperature / 200.0f;  /* °C  */
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(const sensor_data_t *data)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data->pressure, data->temperature);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# SDP810-500Pa monitoring session started\n");
    fprintf(g_log_file, "timestamp,differential_pressure_Pa,temperature_C\n");
    fflush(g_log_file);

    while (g_running) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            log_data(&data);
            if (data.pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr,
                        "WARNING: differential pressure %.2f Pa exceeds threshold %.2f Pa\n",
                        data.pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

