static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    return i2cWriteDevice(handle, buf, 1);
}

static int i2c_read_bytes(int handle, uint8_t *buf, int count)
{
    return i2cReadDevice(handle, (char *)buf, count);
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int sensor_present(int handle)
{
    uint8_t id[8];
    int rc;

    rc = i2c_write_cmd(handle, CMD_READ_ID);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to write ID command (rc=%d)\n", rc);
        return 0;
    }
    gpioDelay(MEAS_DELAY_US);

    rc = i2c_read_bytes(handle, id, 8);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to read ID (rc=%d)\n", rc);
        return 0;
    }
    if (rc != 8) {
        fprintf(stderr, "[ERROR] Short ID read: got %d bytes\n", rc);
        return 0;
    }

    uint16_t rev = ((uint16_t)id[0] << 8) | id[1];
    uint16_t sn  = ((uint16_t)id[2] << 8) | id[3];
    uint16_t snb = ((uint16_t)id[4] << 8) | id[5];
    uint16_t snh = ((uint16_t)id[6] << 8) | id[7];

    fprintf(stderr, "[INFO] Si7021 ID: rev=0x%04X sn=0x%04X%04X%04X\n",
            rev, sn, snb, snh);
    return 1;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C)                                               */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temp_c)
{
    uint8_t buf[3];
    int rc;

    rc = i2c_write_cmd(handle, CMD_READ_TEMP_PREV_RH);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Temp write failed (rc=%d)\n", rc);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    rc = i2c_read_bytes(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Temp read failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "[ERROR] Temp read short: got %d bytes\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read humidity (%RH)                                                 */
/* ------------------------------------------------------------------ */
static int read_humidity(int handle, float *rh)
{
    uint8_t buf[3];
    int rc;

    rc = i2c_write_cmd(handle, CMD_MEASURE_RH_NO_HOLD);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] RH write failed (rc=%d)\n", rc);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    rc = i2c_read_bytes(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] RH read failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "[ERROR] RH read short: got %d bytes\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *line)
{
    if (g_log_file) {
        fputs(line, g_log_file);
        fflush(g_log_file);
    }
    fputs(line, stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!sensor_present(g_i2c_handle)) {
        time_t now = time(NULL);
        struct tm tmv;
        char ts[32];
        localtime_r(&now, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        fprintf(stderr, "[FATAL] Si7021 not detected at 0x%02X — "
                        "check wiring and I2C address\n", I2C_ADDR);
        log_line(ts);
        log_line("ERROR,Sensor absent,0,0\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "[INFO] Logging to %s every %d s. Press Ctrl-C to stop.\n",
            LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temp_c, rh;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_temperature(g_i2c_handle, &temp_c) == 0 &&
                read_humidity(g_i2c_handle, &rh) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] I2C attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(1000000); /* 1 s back-off */
        }

        if (ok) {
            time_t now = time(NULL);
            struct tm tmv;
            char ts[32];
            localtime_r(&now, &tmv);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
            char line[128];
            snprintf(line, sizeof(line), "%s,%.2f,%.2f\n", ts, temp_c, rh);
            log_line(line);
        } else {
            time_t now = time(NULL);
            struct tm tmv;
            char ts[32];
            localtime_r(&now, &tmv);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
            log_line(ts);
            log_line("ERROR,Sensor read failed,0,0\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; ++s)
            sleep(1);
    }

    fprintf(stderr, "\n[INFO] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

