#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_HUMIDITY 0x00
#define HDC1080_CONFIG 0x02
#define HDC1080_CONFIG_DEFAULT 0x1000
#define HDC1080_CONV_DELAY_US 25000
#define LOG_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(int handle) {
    if (i2cWriteWordData(handle, HDC1080_CONFIG, HDC1080_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register.\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read(int handle, float *temperature, float *humidity) {
    if (i2cWriteByteData(handle, HDC1080_TEMP_HUMIDITY, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to trigger temperature/humidity measurement.\n");
        return -1;
    }
    gpioDelay(HDC1080_CONV_DELAY_US);

    char data[4];
    if (i2cReadDevice(handle, data, 4) != 4) {
        fprintf(stderr, "Error: Failed to read 4 bytes from HDC1080.\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    uint16_t raw_hum  = ((uint16_t)(uint8_t)data[2] << 8) | (uint8_t)data[3];

    *temperature = -46.85f + 175.72f * (float)raw_temp / 65536.0f;
    *humidity    = 100.0f * (float)raw_hum  / 65536.0f;
    return 0;
}

static void log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open enviro_log.txt for appending.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    } else {
        fprintf(fp, "timestamp,%.2f,%.2f\n", temperature, humidity);
    }

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", HDC1080_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hdc1080_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    while (running) {
        if (hdc1080_read(i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Warning: Skipping log entry due to read failure.\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

