#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 50000

static int i2c_handle = -1;
static FILE *log_file = NULL;
