#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SCD40_I2C_ADDR 0x61
#define BUFFER_SIZE 100
#define LOGGING_INTERVAL 60
#define MEASUREMENT_INTERVAL 5
#define CSV_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define I2C_DEVICE "/dev/i2c-1"

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_READ_MEASUREMENT 0x0202

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_fd = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = (crc << 1);
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(i2c_fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int start_periodic_measurement() {
    if (i2c_write_cmd(CMD_START_PERIODIC_MEASUREMENT) < 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

static int stop_periodic_measurement() {
    if (i2c_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT) < 0) {
        log_error("Failed to stop periodic measurement");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[9];
    if (i2c_read_data(buf, 9) < 0) {
        log_error("Failed to read sensor data");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC check failed");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC check failed");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC check failed");
        return -1;
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    data->humidity = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    data->timestamp = time(NULL);
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOGGING_INTERVAL);
        if (!running) break;
        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        int tail = buffer.tail;
        pthread_mutex_unlock(&buffer.mutex);
        if (count > 0) {
            char filename[256];
            snprintf(filename, sizeof(filename), "%s/scd40_data_%ld.csv", CSV_DIR, (long)time(NULL));
            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                log_error("Failed to open CSV file for writing");
            } else {
                fprintf(fp, "timestamp,co2,temperature,humidity\n");
                pthread_mutex_lock(&buffer.mutex);
                for (int i = 0; i < count; i++) {
                    int idx = (tail + i) % BUFFER_SIZE;
                    fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                            buffer.data[idx].timestamp,
                            buffer.data[idx].co2,
                            buffer.data[idx].temperature,
                            buffer.data[idx].humidity);
                }
                pthread_mutex_unlock(&buffer.mutex);
                fclose(fp);
            }
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup() {
    if (i2c_fd >= 0) {
        stop_periodic_measurement();
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_lock(&buffer.mutex);
    pthread_mutex_unlock(&buffer.mutex);
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    struct stat st = {0};
    if (stat(CSV_DIR, &st) == -1) {
        mkdir(CSV_DIR, 0755);
    }
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/scd40_data_flush.csv", CSV_DIR);
    FILE *fp = fopen(filename, "w");
    if (fp != NULL) {
        pthread_mutex_lock(&buffer.mutex);
        for (int i = 0; i < buffer.count; i++) {
            int idx = (buffer.tail + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);
        fclose(fp);
    }
}

int main() {
    if (init_i2c() < 0) {
        return 1;
    }
    buffer_init(&buffer);
    if (start_periodic_measurement() < 0) {
        cleanup();
        return 1;
    }
    struct timespec ts = {1, 0};
    nanosleep(&ts, NULL);
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("Failed to register SIGINT handler");
        cleanup();
        return 1;
    }
    sensor_data_t sensor_data;
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            buffer_add(&buffer, sensor_data);
        }
        struct timespec sleep_ts = {MEASUREMENT_INTERVAL, 0};
        nanosleep(&sleep_ts, NULL);
    }
    cleanup();
    return 0;
}

