            snprintf(filename, sizeof(filename), "%s/scd40_data_%ld.csv", CSV_DIR, (long)time(NULL));
            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                log_error("Failed to open CSV file for writing");
            } else {
                fprintf(fp, "timestamp,co2,temperature,humidity\n");
                pthread_mutex_lock(&buffer.mutex);
                for (int i = 0; i < count; i++) {
                    int idx = (tail + i) % BUFFER_SIZE;
                    fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                            buffer.data[idx].timestamp,
                            buffer.data[idx].co2,
                            buffer.data[idx].temperature,
                            buffer.data[idx].humidity);
                }
                pthread_mutex_unlock(&buffer.mutex);
                fclose(fp);
            }
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup() {
    if (i2c_fd >= 0) {
        stop_periodic_measurement();
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_lock(&buffer.mutex);
    pthread_mutex_unlock(&buffer.mutex);
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    struct stat st = {0};
    if (stat(CSV_DIR, &st) == -1) {
        mkdir(CSV_DIR, 0755);
    }
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/scd40_data_flush.csv", CSV_DIR);
    FILE *fp = fopen(filename, "w");
    if (fp != NULL) {
        pthread_mutex_lock(&buffer.mutex);
        for (int i = 0; i < buffer.count; i++) {
            int idx = (buffer.tail + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%u,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);
        fclose(fp);
    }
}

int main() {
    if (init_i2c() < 0) {
        return 1;
    }
    buffer_init(&buffer);
    if (start_periodic_measurement() < 0) {
        cleanup();
        return 1;
    }
    struct timespec ts = {1, 0};
    nanosleep(&ts, NULL);
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("Failed to register SIGINT handler");
        cleanup();
        return 1;
    }
    sensor_data_t sensor_data;
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            buffer_add(&buffer, sensor_data);
        }
        struct timespec sleep_ts = {MEASUREMENT_INTERVAL, 0};
        nanosleep(&sleep_ts, NULL);
    }
    cleanup();
    return 0;
}

