/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* SDP810 default 7-bit I2C address */
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms measurement wait */

/* SDP810 CRC-8: polynomial 0x31, initial value 0xFF, no reflection */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion)                                                   */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP810                  */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /*
     * Trigger a single measurement by writing a zero-length frame.
     * The SDP810 starts a conversion on the next clock edge after
     * the master releases the bus (write with no data).
     */
    if (i2cWriteDevice(handle, (char *)buf, 0) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (trigger) failed: %s\n",
                strerror(errno));
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);          /* 45 ms — well within the 45 ms max */

    int rd = i2cReadDevice(handle, (char *)buf, sizeof(buf));
    if (rd != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %zu): %s\n",
                rd, sizeof(buf), strerror(errno));
        return -1;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Scale factor is zero — invalid data\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;   /* 0.5 °C / count */

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("SDP810 logger started.  Logging to %s  (Ctrl-C to stop)\n", LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                fprintf(stderr, "[WARN] Logging failed — continuing\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed — continuing\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

