#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP_10110_ADDR 0x50
#define TRIGGER_CMD 0x80
#define MEAS_DELAY_US 10000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    char cmd = TRIGGER_CMD;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing trigger command to I2C device: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    char buf[6];
    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Error reading data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)(uint8_t)buf[0] << 16) |
                            ((uint32_t)(uint8_t)buf[1] << 8)  |
                            (uint32_t)(uint8_t)buf[2];
    uint32_t raw_temperature = ((uint32_t)(uint8_t)buf[3] << 16) |
                               ((uint32_t)(uint8_t)buf[4] << 8)  |
                               (uint32_t)(uint8_t)buf[5];

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f, %.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s, %.2f, %.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", ICP_10110_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        fclose(fp);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float pressure, temperature;
    while (running) {
        if (read_sensor(handle, &pressure, &temperature) == 0) {
            log_data(fp, pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fclose(fp);
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

