/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure monitor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   ICP-10125 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   LED anode      -> GPIO17 (BCM) through 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125_mon icp10125_mon.c -lpigpio -lrt
 * Run:    sudo ./icp10125_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define I2C_ADDR         0x50          /* ICP-10125 default 7-bit address */
#define GPIO_LED         17            /* BCM pin for the warning LED */
#define PRESSURE_THRESHOLD_PA 95000.0f  /* Pa – below this → 5 Hz blink */
#define POLL_INTERVAL_US  1000000      /* 1 s between reads */
#define MEAS_DELAY_US     20000        /* 20 ms conversion time */
#define LED_HALF_PERIOD_US 500000      /* 500 ms → 1 Hz blink */
#define LED_QUARTER_PERIOD_US 100000   /* 100 ms → 5 Hz blink */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  read_sensor_data(int fd, uint8_t *buf, size_t len);
static bool verify_crc(const uint8_t *data);
static float convert_pressure(const uint8_t *data);
static void set_led_frequency(int freq_hz);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Open I2C ---- */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);   /* start with LED off */

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t data[6];

        if (read_sensor_data(g_i2c_fd, data, sizeof(data)) != 0) {
            fprintf(stderr, "Warning: sensor read failed; retrying next cycle.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (!verify_crc(data)) {
            fprintf(stderr, "Warning: CRC mismatch – data may be corrupted.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float pressure = convert_pressure(data);

        if (pressure < PRESSURE_THRESHOLD_PA) {
            set_led_frequency(5);
        } else {
            set_led_frequency(1);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint8_t *buf, size_t len)
{
    /*
     * ICP-10125: a read of 6 bytes returns
     *   [0:1] pressure (16-bit, big-endian)
     *   [2:3] temperature (16-bit, big-endian)
     *   [4:5] CRC (16-bit, big-endian)
     *
     * i2cReadDevice returns the number of bytes read, or < 0 on error.
     */
    int n = i2cReadDevice(fd, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected %zu).\n",
                n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static bool verify_crc(const uint8_t *data)
{
    /*
     * CRC-8 polynomial 0x31, init 0x00, no final XOR.
     * pigpio's i2cReadDevice already returns raw bytes, so we compute
     * the CRC over the 4 data bytes and compare with the received byte.
     */
    uint8_t crc = 0x00;
    for (int i = 0; i < 4; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == data[4]);
}

/* ------------------------------------------------------------------ */
static float convert_pressure(const uint8_t *data)
{
    /*
     * Raw 16-bit pressure value (big-endian).
     * Pa = raw * 100 / 65536  (per datasheet scaling).
     */
    uint16_t raw = (uint16_t)((data[0] << 8) | data[1]);
    return (float)raw * 100.0f / 65536.0f;
}

/* ------------------------------------------------------------------ */
static void set_led_frequency(int freq_hz)
{
    /*
     * 1 Hz  → 500 ms on, 500 ms off
     * 5 Hz  → 100 ms on, 100 ms off
     */
    int half_period_us = 500000 / freq_hz;
    gpioWrite(GPIO_LED, 1);
    gpioDelay(half_period_us);
    gpioWrite(GPIO_LED, 0);
    gpioDelay(half_period_us);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

