#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x49
#define MEASURE_CMD 0x2C
#define MEASURE_DELAY_MS 10
#define READ_LEN 6
#define MAX_RETRIES 3
#define PORT 8080
#define HTML_PAGE "sht40.html"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += n;
    }
    return 0;
}

static int read_sht40(int fd, float *temp, float *hum) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }
        usleep(MEASURE_DELAY_MS * 1000);

        uint8_t data[READ_LEN];
        if (i2c_read_bytes(fd, data, READ_LEN) < 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }

        uint16_t t_raw = (data[0] << 8) | data[1];
        uint16_t h_raw = (data[3] << 8) | data[4];

        *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *hum = 100.0f * (float)h_raw / 65535.0f;
        if (*hum > 100.0f) *hum = 100.0f;
        if (*hum < 0.0f) *hum = 0.0f;
        return 0;
    }
    return -1;
}

static int send_html(int sock, const char *page) {
    size_t len = strlen(page);
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(sock, page + sent, len - sent, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        sent += n;
    }
    return 0;
}

