    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "setsockopt failed: %s\n", strerror(errno));
        close(server_fd);
        close(i2c_fd);
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        close(server_fd);
        close(i2c_fd);
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        close(server_fd);
        close(i2c_fd);
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }

        float temp, hum;
        if (read_sht40(i2c_fd, &temp, &hum) == 0) {
            char html[1024];
            snprintf(html, sizeof(html),
                     "HTTP/1.1 200 OK\r\n"
                     "Content-Type: text/html\r\n"
                     "Connection: close\r\n"
                     "\r\n"
                     "<html><body><h1>SHT40 Sensor Data</h1>"
                     "<p>Temperature: %.2f &deg;C</p>"
                     "<p>Humidity: %.2f %%</p></body></html>",
                     temp, hum);
            send_html(client_fd, html);
        } else {
            const char *err = "HTTP/1.1 500 Internal Server Error\r\n"
                              "Content-Type: text/html\r\n"
                              "Connection: close\r\n"
                              "\r\n"
                              "<html><body><h1>Error</h1><p>Failed to read sensor data.</p></body></html>";
            send_html(client_fd, err);
        }

        close(client_fd);
    }

    close(server_fd);
    close(i2c_fd);
    printf("\nServer shut down cleanly.\n");
    return 0;
}

