#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x48
#define TMP102_REG_TEMP 0x00
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static int read_temperature(int handle, float *temperature)
{
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, TMP102_REG_TEMP, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw / 4.0f;
    return 0;
}

static int log_temperature(float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int handle;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (g_running) {
        if (read_temperature(handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log entry\n");
        }

        if (g_running) {
            sleep(SAMPLE_PERIOD);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

