#define HDC2010_ADDR 0x40

/* HDC2010 register addresses */
#define REG_TEMP_LOW      0x00
#define REG_TEMP_HIGH     0x01
#define REG_HUM_LOW       0x02
#define REG_HUM_HIGH      0x03
#define REG_MEAS_CFG      0x0E

/* MEASUREMENT_CONFIG register bits */
#define MEAS_CFG_MEAS_TRIG 0x01  /* Bit 0: start measurement */

/* Timing constants */
#define MEAS_TIMEOUT_MS   500
#define POLL_INTERVAL_US  10000   /* 10 ms */
#define SAMPLE_PERIOD_S   5
#define MAX_RETRIES       3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level register helpers                                          */
/* ------------------------------------------------------------------ */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int reg_read(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* HDC2010 helpers                                                     */
/* ------------------------------------------------------------------ */
static int hdc2010_init(int handle)
{
    /* Software reset: write 0x00 to MEASUREMENT_CONFIG */
    if (reg_write(handle, REG_MEAS_CFG, 0x00) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* Configure: 14-bit temp + 14-bit humidity, 1.1 Hz ODR */
    /* 0x0000 = 14-bit temp, 14-bit humidity, ODR = 1.1 Hz, no heater */
    if (reg_write(handle, REG_MEAS_CFG, 0x00) < 0)
        return -1;

    return 0;
}

/*
 * Trigger a measurement and wait for completion.
 * Returns 0 on success, -1 on timeout or I2C error.
 */
static int hdc2010_trigger_and_wait(int handle)
{
    uint8_t cfg;
    int elapsed = 0;

    /* Trigger a measurement by setting MEAS_TRIG */
    if (reg_write(handle, REG_MEAS_CFG, MEAS_CFG_MEAS_TRIG) < 0)
        return -1;

    /* Poll until MEAS_TRIG is cleared (bit 0 reads 0) or timeout */
    do {
        if (reg_read(handle, REG_MEAS_CFG, &cfg) < 0)
            return -1;
        if (elapsed >= MEAS_TIMEOUT_MS) {
            fprintf(stderr, "[ERROR] HDC2010 measurement timeout (%d ms)\n", elapsed);
            return -1;
        }
        gpioDelay(POLL_INTERVAL_US);
        elapsed += (POLL_INTERVAL_US / 1000);
    } while (cfg & MEAS_CFG_MEAS_TRIG);

    return 0;
}

static int hdc2010_read(int handle, float *temperature, float *humidity)
{
    uint8_t t_low, t_high, h_low, h_high;

    if (hdc2010_trigger_and_wait(handle) < 0)
        return -1;

    /* Read temperature registers */
    if (reg_read(handle, REG_TEMP_LOW, &t_low) < 0)
        return -1;
    if (reg_read(handle, REG_TEMP_HIGH, &t_high) < 0)
        return -1;

    /* Read humidity registers */
    if (reg_read(handle, REG_HUM_LOW, &h_low) < 0)
        return -1;
    if (reg_read(handle, REG_HUM_HIGH, &h_high) < 0)
        return -1;

