    int16_t temp_raw = (int16_t)((t_high << 8) | t_low);
    int16_t hum_raw  = (int16_t)((h_high << 8) | h_low);

    /* Convert: 14-bit two's complement, 0.00390625 °C per LSB */
    *temperature = (float)temp_raw * 0.00390625f;

    /* Convert: 14-bit unsigned, 0.0104167 %RH per LSB */
    *humidity = (float)hum_raw * 0.0104167f;

    return 0;
}

