/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define MEAS_DELAY_MS  45          /* SDP800 needs ~45 ms for a measurement */
#define LOOP_DELAY_MS  500         /* 500 ms between readings */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, initial value 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one measurement frame from the SDP800.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sdp800_read(int fd, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[6];

    if (write(fd, buf, 0) < 0) {
        /* No data to write — just start a measurement by reading (dummy) */
        /* Some sensors return the previous measurement; the SDP800 does not. */
        /* A zero-length write is not strictly valid, but it is harmless here. */
    }

    /* Trigger a measurement by writing a zero-length frame (dummy write). */
    if (write(fd, buf, 0) < 0) {
        fprintf(stderr, "I2C trigger write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the measurement to complete */
    usleep(MEAS_DELAY_MS * 1000);

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, sizeof(buf));
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -2;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("SDP800-500Pa reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, SDP800_ADDR);

    while (g_running) {
        int16_t pressure = 0, temperature = 0;
        int status = -1;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            status = sdp800_read(fd, &pressure, &temperature);
            if (status == 0)
                break;
            if (status == -1) {
                /* I/O error — brief back-off before retry */
                usleep(10 * 1000);
            }
            /* CRC mismatch is not recoverable; skip this cycle */
        }

        if (status == 0) {
            printf("Pressure: %6d Pa, Temperature: %6d °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts.\n", MAX_RETRIES);
        }

        /* Sleep LOOP_DELAY_MS, but wake early on signal */
        for (int ms = 0; ms < LOOP_DELAY_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

