/*
 * PID-Controlled Reflow Oven for Raspberry Pi 3 Model B+
 * MAX6675 thermocouple amplifier on SPI0 (CE0), solid-state relay on GPIO17.
 *
 * Build: gcc -O2 -Wall -o reflow_oven reflow_oven.c -lpigpio -lrt -lm
 * Run:   sudo ./reflow_oven
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define SSR_GPIO         17         /* BCM 17 */
#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"
#define SAMPLE_PERIOD_S  1.0        /* seconds between PID updates */
#define LOOP_PERIOD_S    0.1        /* seconds between samples */
#define MAX_SPI_RETRIES  3
#define MAX_TEMP_ERR     1000.0     /* sentinel for hard sensor failure */

/* PID gains (tune for your oven) */
#define KP  1.0
#define KI  0.1
#define KD  0.01

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static int  spi_init(void);
static int  read_max6675(int spi_handle, float *temperature);
static int  load_profile(const char *filename, float **profile,
                          int *profile_size);
static void control_ssr(int gpio, float pid_output);
static void log_data(FILE *fp, float temperature, float pid_output);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI -------------------------------------- */
static int spi_init(void)
{
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", handle);
        return -1;
    }
    return handle;
}

/*
 * Read temperature from MAX6675.
 * Returns 0 on success, -1 on SPI error, -2 on sensor-absent / bus error.
 */
static int read_max6675(int spi_handle, float *temperature)
{
    char tx[3] = {0x00, 0x00, 0x00};
    char rx[3] = {0, 0, 0};

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int rc = spiXfer(spi_handle, tx, rx, 3);
        if (rc == 3) {
            /* D13 low (bit 0 of rx[1]) => thermocouple connected */
            if (rx[1] & 0x80) {
                int16_t raw = ((int16_t)(rx[2] & 0x0F) << 8) | (uint8_t)rx[1];
                *temperature = raw * 0.25f;
                return 0;
            }
            /* D13 high => sensor absent or bus error */
            return -2;
        }
        fprintf(stderr, "Warning: spiXfer returned %d (attempt %d/%d)\n",
                rc, attempt + 1, MAX_SPI_RETRIES);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ----------------------------- Profile ----------------------------------- */
static int load_profile(const char *filename, float **profile,
                        int *profile_size)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for reading\n", filename);
        return -1;
    }

    /* Count lines */
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] != '#' && line[0] != '\n' && line[0] != '\0') {
            count++;
        }
    }
    if (ferror(fp)) {
        fprintf(stderr, "Error: reading %s failed\n", filename);
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (count == 0) {
        fprintf(stderr, "Error: %s is empty\n", filename);
        return -1;
    }

    *profile_size = count;
    *profile = (float *)malloc((size_t)*profile_size * sizeof(float));
    if (!*profile) {
        fprintf(stderr, "Error: malloc failed for profile (%d elements)\n",
                *profile_size);
        return -1;
    }

    fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot reopen %s for reading\n", filename);
        free(*profile);
        *profile = NULL;
        return -1;
    }

    int idx = 0;
    while (fgets(line, sizeof(line), fp) && idx < *profile_size) {
        float t, T;
        if (sscanf(line, "%f,%f", &t, &T) == 2) {
            (*profile)[idx] = T;
            idx++;
        } else {
            fprintf(stderr, "Warning: malformed line %d in %s\n",
                    idx, filename);
        }
    }
    fclose(fp);

    if (idx != *profile_size) {
        fprintf(stderr, "Warning: loaded %d/%d points from %s\n",
                idx, *profile_size, filename);
    }
    return 0;
}

/* ----------------------------- SSR --------------------------------------- */
static void control_ssr(int gpio, float pid_output)
{
    if (pid_output < 0.0f)   pid_output = 0.0f;
    if (pid_output > 1.0f)   pid_output = 1.0f;

    int duty = (int)(pid_output * 255.0f);
    if (gpioWrite(gpio, (duty > 0) ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on GPIO %d\n", gpio);
    }
    printf("SSR duty: %d/255 (%.2f%%)\n", duty, pid_output * 100.0f);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(FILE *fp, float temperature, float pid_output)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, pid_output);
    fflush(fp);
}

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure SSR is off before terminating pigpio */
    gpioWrite(SSR_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SSR GPIO */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SSR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SSR_GPIO, 0);

    /* Initialize SPI */
    int spi_handle = spi_init();
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Load profile */
    float *profile = NULL;
    int profile_size = 0;
    if (load_profile(PROFILE_FILE, &profile, &profile_size) != 0) {
        fprintf(stderr, "Error: failed to load profile from %s\n",
                PROFILE_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_c,pid_output\n");
        fflush(g_log_fp);
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reflow oven started. Target profile has %d points.\n",
           profile_size);
    printf("Press Ctrl+C to stop.\n");

    /* PID state */
    float integral = 0.0f;
    float prev_error = 0.0f;

    /* Main loop */
    while (!g_terminate) {
        float temperature = 0.0f;
        int rc = read_max6675(spi_handle, &temperature);

        if (rc == 0) {
            /* PID */
            float target = 0.0f;
            if (profile_size > 0) {
                time_t now = time(NULL);
                struct tm tm_buf;
                struct tm *t = localtime_r(&now, &tm_buf);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

                /* Find closest profile point */
                float best_diff = 1e9f;
                int best_idx = -1;
                for (int i = 0; i < profile_size; i++) {
                    float diff = fabsf((float)t - profile[i]);
                    if (diff < best_diff) {
                        best_diff = diff;
                        best_idx = i;
                    }
                }
                if (best_idx >= 0) {
                    target = profile[best_idx];
                }
            }

            float error = target - temperature;
            integral += error * SAMPLE_PERIOD_S;
            float derivative = (error - prev_error) / SAMPLE_PERIOD_S;
            float pid_output = KP * error + KI * integral + KD * derivative;

            control_ssr(SSR_GPIO, pid_output);
            log_data(g_log_fp, temperature, pid_output);
            prev_error = error;
        } else {
            fprintf(stderr, "Error: MAX6675 read failed (rc=%d). "
                            "Temperature set to sentinel (%.2f C).\n",
                    rc, MAX_TEMP_ERR);
            temperature = MAX_TEMP_ERR;
            integral = 0.0f;
            prev_error = 0.0f;
            gpioWrite(SSR_GPIO, 0);
            log_data(g_log_fp, temperature, 0.0f);
        }

        /* Sleep for the remainder of the sample period */
        double remaining = (SAMPLE_PERIOD_S - LOOP_PERIOD_S);
        if (remaining > 0.0) {
            struct timespec ts = {
                .tv_sec  = (time_t)remaining,
                .tv_nsec = (long)(remaining * 1e9)
            };
            nanosleep(&ts, NULL);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Reflow oven stopped.\n");
    return EXIT_SUCCESS;
}

