/*
 * PID-Controlled Reflow Oven for Raspberry Pi 3 Model B+
 * MAX6675 thermocouple amplifier on SPI0 (CE0), solid-state relay on GPIO17.
 *
 * Build: gcc -O2 -Wall -o reflow_oven reflow_oven.c -lpigpio -lrt -lm
 * Run:   sudo ./reflow_oven
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define SSR_GPIO         17         /* BCM 17 */
#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"
#define SAMPLE_PERIOD_S  1.0        /* seconds between PID updates */
#define LOOP_PERIOD_S    0.1        /* seconds between samples */
#define MAX_SPI_RETRIES  3
#define MAX_TEMP_ERR     1000.0     /* sentinel for hard sensor failure */

/* PID gains (tune for your oven) */
#define KP  1.0
#define KI  0.1
#define KD  0.01

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static int  spi_init(void);
static int  read_max6675(int spi_handle, float *temperature);
static int  load_profile(const char *filename, float **profile,
                          int *profile_size);
static void control_ssr(int gpio, float pid_output);
static void log_data(FILE *fp, float temperature, float pid_output);
static void signal_handler(int sig);
