    sigaction(SIGTERM, &sa, NULL);

    printf("Reflow oven started. Target profile has %d points.\n",
           profile_size);
    printf("Press Ctrl+C to stop.\n");

    /* PID state */
    float integral = 0.0f;
    float prev_error = 0.0f;

    /* Main loop */
    while (!g_terminate) {
        float temperature = 0.0f;
        int rc = read_max6675(spi_handle, &temperature);

        if (rc == 0) {
            /* PID */
            float target = 0.0f;
            if (profile_size > 0) {
                time_t now = time(NULL);
                struct tm tm_buf;
                struct tm *t = localtime_r(&now, &tm_buf);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

