#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <wiringPi.h>

#define DS18B20_GPIO 4
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_SENSORS 4

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int pwm_fd = -1;

typedef struct {
    float Kp, Ki, Kd;
    float integral, prev_error;
} PIDParams;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int gpio, float *temp_out) {
    char path[256];
    char buf[256];
    int fd = -1;
    int ret = -1;

    snprintf(path, sizeof(path), "/sys/bus/w1/devices/w1_bus_0/%s/w1_slave", gpio);
    if (access(path, F_OK) != 0) {
        fprintf(stderr, "Error: %s not found\n", path);
        return -1;
    }

    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);

    char *line1 = strstr(buf, "YES");
    if (!line1) {
        fprintf(stderr, "Error: DS18B20 CRC check failed\n");
        return -1;
    }

    char *t_str = strstr(buf, "t=");
    if (!t_str) {
        fprintf(stderr, "Error: temperature field not found\n");
        return -1;
    }

    long t = strtol(t_str + 2, NULL, 10);
    if (t == 0 && errno == EINVAL) {
        fprintf(stderr, "Error: invalid temperature value\n");
        return -1;
    }

    *temp_out = (float)t / 1000.0f;
    return 0;
}

static int set_relay(int state) {
    if (wiringPiWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing relay GPIO %d\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static int set_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (pwm_fd >= 0) {
        if (ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, duty) < 0) {
            fprintf(stderr, "Error setting PWM duty: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static float pid_compute(PIDParams *p, float setpoint, float actual) {
    float error = setpoint - actual;
    p->integral += error;
    float derivative = error - p->prev_error;
    float out = p->Kp * error + p->Ki * p->integral + p->Kd * derivative;
    p->prev_error = error;
    return out;
}

static void log_data(float avg_temp, float setpoint, float pid_out, int duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    if (log_fp) {
        fprintf(log_fp, "%s,%.2f,%.2f,%.2f,%d\n", ts, avg_temp, setpoint, pid_out, duty);
        fflush(log_fp);
    }
}

static void cleanup(void) {
    if (pwm_fd >= 0) {
        set_pwm(0);
        close(pwm_fd);
        pwm_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (wiringPiInitialised()) {
        set_relay(0);
        wiringPiTerminate();
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint_C> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);
    float Kd = atof(argv[4]);

    if (Kp <= 0 || Ki <= 0 || Kd <= 0) {
        fprintf(stderr, "Error: PID gains must be positive\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiInitialise() < 0) {
        fprintf(stderr, "Error: wiringPiInitialise failed\n");
        return 1;
    }

    if (wiringPiSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: setting relay GPIO mode\n");
        cleanup();
        return 1;
    }
    if (wiringPiSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: setting PWM GPIO mode\n");
        cleanup();
        return 1;
    }

    if (wiringPiSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: setting PWM frequency\n");
        cleanup();
        return 1;
    }
    if (wiringPiSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: setting PWM range\n");
        cleanup();
        return 1;
    }

    pwm_fd = open("/dev/pwmchip0", O_RDWR);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error opening /dev/pwmchip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    PIDParams pid = {Kp, Ki, Kd, 0.0f, 0.0f};

    while (running) {
        float temps[MAX_SENSORS];
        int n = 0;
        float sum = 0.0f;

        for (int i = 0; i < MAX_SENSORS; i++) {
            char path[256];
            snprintf(path, sizeof(path), "/sys/bus/w1/devices/w1_bus_0/%s/w1_slave", DS18B20_GPIO);
            if (access(path, F_OK) != 0) {
                fprintf(stderr, "Warning: sensor %d absent, skipping\n", i);
                continue;
            }
            float t;
            if (read_temperature(DS18B20_GPIO, &t) == 0) {
                temps[n++] = t;
                sum += t;
            } else {
                fprintf(stderr, "Warning: read failed for sensor %d\n", i);
            }
        }

