#define I2C_BUS          "/dev/i2c-1"
#define AHT20_ADDR       0x38
#define DEHUMIDIFIER_PIN  17
#define HUMIDITY_HIGH    60.0f
#define HUMIDITY_LOW     55.0f
#define POLL_INTERVAL_S  5
#define MEAS_DELAY_US    80000   /* 80 ms */
#define RETRY_DELAY_US   10000   /* 10 ms */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an AHT20 register (command byte + 1 data byte). */
static int aht20_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "AHT20 write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read `len` bytes starting at `reg` using a repeated-start sequence. */
static int aht20_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "AHT20 write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "AHT20 read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* Trigger a measurement and read back the 6-byte result. */
static int aht20_read_humidity(int fd, float *humidity_out)
{
    uint8_t data[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (aht20_write_reg(fd, 0xB6, 0x00) != 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        if (aht20_read_reg(fd, 0xAC, data, 6) != 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (data[0] & 0x80) {
            fprintf(stderr, "AHT20 busy after measurement (attempt %d)\n",
                    attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint32_t raw_humidity = ((uint32_t)data[1] << 12) |
                               ((uint32_t)data[2] << 4)  |
                               ((uint32_t)data[3] >> 4);
        *humidity_out = (float)raw_humidity / 1048576.0f * 100.0f;
        return 0;
    }

    fprintf(stderr, "AHT20 read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void log_humidity(float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    } else {
        printf("[unknown] Humidity: %.2f%%\n", humidity);
    }
    fflush(stdout);
}

int main(void)
{
    int i2c_fd = -1;
    int gpio_ok = 0;
    int rc = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_ok = 1;

    if (gpioSetMode(DEHUMIDIFIER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", DEHUMIDIFIER_PIN);
        rc = 1;
        goto cleanup;
    }
    gpioWrite(DEHUMIDIFIER_PIN, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        rc = 1;
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        rc = 1;
        goto cleanup;
    }

    printf("AHT20 humidity monitor started (bus %s, addr 0x%02X, pin %d)\n",
           I2C_BUS, AHT20_ADDR, DEHUMIDIFIER_PIN);
    printf("Thresholds: ON > %.1f%%, OFF < %.1f%%\n", HUMIDITY_HIGH, HUMIDITY_LOW);
    fflush(stdout);

    while (g_running) {
        float humidity = 0.0f;

        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            log_humidity(humidity);

            if (humidity > HUMIDITY_HIGH) {
                gpioWrite(DEHUMIDIFIER_PIN, 1);
                printf("Humidity above %.1f%% — dehumidifier ON\n",
                       HUMIDITY_HIGH);
            } else if (humidity < HUMIDITY_LOW) {
                gpioWrite(DEHUMIDIFIER_PIN, 0);
                printf("Humidity below %.1f%% — dehumidifier OFF\n",
                       HUMIDITY_LOW);
            }
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        for (int s = 0; s < POLL_INTERVAL_S && g_running; s++) {
            sleep(1);
        }
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_ok) {
        gpioWrite(DEHUMIDIFIER_PIN, 0);
        gpioTerminate();
    }
    printf("\nShutdown complete.\n");
    return rc;
}

