#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTTP_SERVER "http://api.example.com/humidity"
#define POLL_INTERVAL_SEC 60

#define CMD_MEASURE_RH 0xE5
#define CMD_READ_TEMP 0xF3
#define CMD_SOFT_RESET 0xFE

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "I2C read: unexpected EOF (sensor may be absent)");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int htu21d_read_raw(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_byte(fd, cmd) < 0) return -1;

    usleep(50000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;

    if (buf[0] & 0x80) {
        syslog(LOG_ERR, "HTU21D CRC mismatch (cmd=0x%02X)", cmd);
        return -1;
    }

    *raw = ((uint16_t)buf[1] << 8) | buf[2];
    return 0;
}

static int htu21d_read_humidity(int fd, float *humidity) {
    uint16_t raw;
