#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *c) {
    uint8_t data[BMP280_CALIB_LEN];
    if (i2cReadI2CBlockData(handle, BMP280_CALIB_START, (char *)data, BMP280_CALIB_LEN) != BMP280_CALIB_LEN) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    c->dig_T1 = (uint16_t)(data[0] | (data[1] << 8));
    c->dig_T2 = (int16_t)(data[2] | (data[3] << 8));
    c->dig_T3 = (int16_t)(data[4] | (data[5] << 8));
    c->dig_P1 = (uint16_t)(data[6] | (data[7] << 8));
    c->dig_P2 = (int16_t)(data[8] | (data[9] << 8));
    c->dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    c->dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    c->dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    c->dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    c->dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    c->dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    c->dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)calib.dig_P4) << 16);
    var1 = (((calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - adc_P) - (var2 >> 12))) * 3125);
    if (p < 0x80000000) p = (p << 1) / ((uint32_t)var1);
    else p = (p / (uint32_t)var1) << 1;
    var1 = (((int32_t)calib.dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
