    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, float *pressure) {
    char data[6];
    int32_t raw_pressure, raw_temperature;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
            fprintf(stderr, "Error writing to CTRL_MEAS_REG\n");
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
            continue;
        }
        if (i2cWriteByteData(handle, BMP280_CONFIG_REG, 0x14) < 0) {
            fprintf(stderr, "Error writing to CONFIG_REG\n");
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
            continue;
        }
        gpioDelay(CONVERSION_DELAY_US);

        if (i2cReadI2CBlockData(handle, BMP280_PRESS_MSB_REG, data, 6) != 6) {
            fprintf(stderr, "Error reading pressure data\n");
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
            continue;
