static int read_bmp280(int handle, float *pressure) {
    char data[6];
    int32_t raw_pressure, raw_temperature;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
            fprintf(stderr, "Error writing to CTRL_MEAS_REG\n");
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
            continue;
        }
        if (i2cWriteByteData(handle, BMP280_CONFIG_REG, 0x14) < 0) {
            fprintf(stderr, "Error writing to CONFIG_REG\n");
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
            continue;
        }
        gpioDelay(CONVERSION_DELAY_US);

        if (i2cReadI2CBlockData(handle, BMP280_PRESS_MSB_REG, data, 6) != 6) {
            fprintf(stderr, "Error reading pressure data\n");
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
            continue;
        }

        raw_pressure = (int32_t)(((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | ((uint32_t)data[2] >> 4));
        raw_temperature = (int32_t)(((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | ((uint32_t)data[5] >> 4));

        *pressure = (float)compensate_pressure(raw_pressure) / 100.0;
        return 0;
    }
    return -1;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float pressure;
        if (read_bmp280(i2c_handle, &pressure) == 0) {
            if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                log_pressure(pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

