/*
 * Raspberry Pi 4B data logger
 *   TMP117 temperature sensor  -> /dev/i2c-1, address 0x48
 *   AHT20 humidity sensor      -> /dev/i2c-1, address 0x38
 *   PIR motion sensor          -> GPIO17 (gpiochip4, line 17)
 *
 * Logs to daily CSV files: 2024-07-26_00.csv, 2024-07-26_01.csv, ...
 * Fields: Timestamp,Temperature(C),Humidity(%),MotionDetected
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define TMP117_ADDR      0x48
#define AHT20_ADDR       0x38
#define PIR_CHIP         "gpiochip4"
#define PIR_LINE         17
#define LOG_DIR          "data"
#define SAMPLE_INTERVAL  1
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, unsigned char addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg8(int fd, unsigned char reg, unsigned char *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, unsigned char reg, unsigned int *val)
{
    unsigned char buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = ((unsigned int)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 temperature                                                   */
/* ------------------------------------------------------------------ */

static int read_tmp117(int fd, float *temp_c)
{
    unsigned char cfg;
    unsigned int raw;
    int retries;

    /* Point to the temperature register (0x00) */
    if (write(fd, (unsigned char[]){0x00}, 1) != 1) {
        fprintf(stderr, "TMP117: failed to set temp register: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read the 16-bit result (MSB first) */
    if (i2c_read_reg16(fd, 0x00, &raw) < 0)
        return -1;

    /* TMP117: 13-bit two's complement, left-justified in 16 bits */
    int16_t t = (int16_t)raw;
    t >>= 3;                       /* right-justify */
    *temp_c = (float)t * 0.0078125f; /* 1/128 °C per LSB */
    return 0;
}

/* ------------------------------------------------------------------ */
/* AHT20 humidity                                                      */
/* ------------------------------------------------------------------ */

static int read_aht20(int fd, float *humidity)
{
    unsigned char data[6];
    unsigned int raw_h;
    int retries;

    /* Soft reset: write 0x08, then read 6 bytes */
    if (write(fd, (unsigned char[]){0x08}, 1) != 1) {
        fprintf(stderr, "AHT20: soft reset write failed: %s\n",
                strerror(errno));
        return -1;
    }
    usleep(80000);                 /* 80 ms settle */

    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "AHT20: read failed: %s\n", strerror(errno));
        return -1;
    }

    /* CRC check: bytes 0,1,3,4,5, CRC byte 2 */
    unsigned char crc = 0;
    for (int i = 0; i < 5; i++)
        crc += data[i];
    if (crc != data[2]) {
        fprintf(stderr, "AHT20: CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc, data[2]);
        return -1;
    }

    /* Humidity: 14-bit, 0.1 %RH per LSB */
    raw_h = ((unsigned int)data[3] << 8) | data[4];
    *humidity = (float)raw_h * 0.1f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PIR motion sensor (gpiod)                                           */
/* ------------------------------------------------------------------ */

static int read_pir(struct gpiod_line *line, int *motion)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR: gpiod_line_get_value failed: %s\n",
                strerror(errno));
        return -1;
    }
    *motion = (val == 1) ? 1 : 0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d_%H", &tm);
}

static void get_full_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d_%H:%M:%S", &tm);
}

static int ensure_log_file(const char *filename)
{
    FILE *f = fopen(filename, "r");
    if (f) {
        fclose(f);
        return 0;                 /* file already exists */
    }
    if (errno != ENOENT) {
        fprintf(stderr, "ensure_log_file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(const char *filename,
                    float temp_c, float humidity, int motion)
{
    FILE *f = fopen(filename, "a");
    if (!f) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(f, "%s,%.2f,%.2f,%d\n",
            filename, temp_c, humidity, motion);
    fclose(f);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open log directory */
    if (mkdir(LOG_DIR, 0755) < 0 && errno != EEXIST) {
        fprintf(stderr, "mkdir(%s) failed: %s\n", LOG_DIR, strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    int i2c_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Warning: TMP117 not detected at 0x%02X; continuing.\n",
                TMP117_ADDR);
    }

    int aht20_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (aht20_fd < 0) {
        fprintf(stderr, "Warning: AHT20 not detected at 0x%02X; continuing.\n",
                AHT20_ADDR);
    }

    /* Open PIR GPIO line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "Warning: gpiod_chip_open(%s) failed: %s\n",
                PIR_CHIP, strerror(errno));
    } else {
        struct gpiod_line *line = gpiod_chip_get_line(chip, PIR_LINE);
        if (!line) {
            fprintf(stderr, "Warning: gpiod_chip_get_line(%d) failed: %s\n",
                    PIR_LINE, strerror(errno));
            gpiod_chip_close(chip);
        } else {
            if (gpiod_line_request_input(line, "pir_logger") < 0) {
                fprintf(stderr, "Warning: gpiod_line_request_input failed: %s\n",
                        strerror(errno));
                gpiod_line_release(line);
                gpiod_chip_close(chip);
            }
        }
    }

    char ts[32];
    char full_ts[32];
    get_timestamp(ts, sizeof(ts));

    while (g_running) {
        float temp_c = 0.0f, humidity = 0.0f;
        int motion = 0;
        int ok = 0;

        if (i2c_fd >= 0) {
            if (read_tmp117(i2c_fd, &temp_c) == 0) ok = 1;
        }
        if (aht20_fd >= 0) {
            if (read_aht20(aht20_fd, &humidity) == 0) ok = 1;
        }
        if (ok) {
            if (read_pir((struct gpiod_line *)NULL, &motion) == 0) {
                ok = 1;
            }
        }

        if (ok) {
            get_full_timestamp(full_ts, sizeof(full_ts));
            if (log_data(full_ts, temp_c, humidity, motion) < 0)
                fprintf(stderr, "log_data failed\n");
        } else {
            fprintf(stderr, "Sensor read failed; skipping log entry.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    /* Cleanup */
    if (i2c_fd >= 0) close(i2c_fd);
    if (aht20_fd >= 0) close(aht20_fd);
    if (chip) gpiod_chip_close(chip);

    printf("Logger stopped.\n");
    return 0;
}

