#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_SEC  2
#define MOTOR_RUN_SEC      5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioSetMode(%u, %u) failed: %s",
                 pin, mode, strerror(errno));
        log_message(buf);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite(%u, %u) failed: %s",
                 pin, level, strerror(errno));
        log_message(buf);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud)
{
    if (gpioSetPullUpDown(pin, pud) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioSetPullUpDown(%u, %u) failed: %s",
                 pin, pud, strerror(errno));
        log_message(buf);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    if (safe_set_mode(RAIN_SENSOR_PIN, PI_INPUT) < 0) return -1;
    if (safe_set_mode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) return -1;

    if (safe_set_pull(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) return -1;

    /* Ensure motor is stopped before anything else */
    if (safe_write(MOTOR_ENA_PIN, 0) < 0) return -1;
    if (safe_write(MOTOR_IN1_PIN, 0) < 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return -1;

    return 0;
}

static void stop_motor(void)
{
    safe_write(MOTOR_ENA_PIN, 0);
    safe_write(MOTOR_IN1_PIN, 0);
    safe_write(MOTOR_IN2_PIN, 0);
}

static void close_window(void)
{
    log_message("Closing window...");

    /* Forward direction: IN1=1, IN2=0, ENA=1 */
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) return;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) { safe_write(MOTOR_IN1_PIN, 0); return; }
    if (safe_write(MOTOR_ENA_PIN, 1) < 0) { safe_write(MOTOR_IN1_PIN, 0); safe_write(MOTOR_IN2_PIN, 0); return; }

    /* Run for the configured duration, checking g_running every second */
    for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++)
        sleep(1);

    stop_motor();
    log_message("Window closed.");
}

static void cleanup(void)
{
    stop_motor();
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        log_message("GPIO initialization failed, exiting");
        return EXIT_FAILURE;
    }

    log_message("Rain sensor monitoring started (GPIO17, active-low).");

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            char buf[128];
            snprintf(buf, sizeof(buf), "gpioRead(%d) failed: %s", RAIN_SENSOR_PIN, strerror(errno));
            log_message(buf);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain == 0) {
            log_message("Rain detected!");
            close_window();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_message("Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

