#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN, red) < 0) {
        fprintf(stderr, "gpioPWM(RED) failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        fprintf(stderr, "gpioPWM(GREEN) failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        fprintf(stderr, "gpioPWM(BLUE) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_cpu_load(float *load)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Failed to read /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 9) {
        fprintf(stderr, "Failed to parse CPU stats\n");
        return -1;
    }

    static unsigned long long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0, prev_iowait = 0, prev_irq = 0, prev_softirq = 0, prev_steal = 0, prev_guest = 0, prev_guest_nice = 0;
    static int have_prev = 0;

    unsigned long long prev_idle_total = prev_idle + prev_iowait;
    unsigned long long curr_idle_total = idle + iowait;

    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal;
    unsigned long long curr_non_idle = user + nice + system + irq + softirq + steal;

    unsigned long long prev_total = prev_idle_total + prev_non_idle;
    unsigned long long curr_total = curr_idle_total + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle_total - prev_idle_total;

    if (totald == 0) {
        *load = 0.0f;
        return 0;
    }

    *load = (float)(totald - idled) / (float)totald * 100.0f;

    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;
    have_prev = 1;

    return 0;
}

static void map_load_to_color(float load, int *red, int *green, int *blue)
{
    if (load < 0.0f) load = 0.0f;
    if (load > 100.0f) load = 100.0f;

    if (load < 50.0f) {
        *red = (int)(load / 50.0f * 255.0f);
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = (int)((100.0f - load) / 50.0f * 255.0f);
        *blue = 0;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RED_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(GREEN_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BLUE_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(RED_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(GREEN_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(BLUE_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(RED_PIN, 0) < 0) {
        fprintf(stderr, "gpioPWM(RED_PIN, 0) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(GREEN_PIN, 0) < 0) {
        fprintf(stderr, "gpioPWM(GREEN_PIN, 0) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(BLUE_PIN, 0) < 0) {
        fprintf(stderr, "gpioPWM(BLUE_PIN, 0) failed\n");
        gpioTerminate();
        return 1;
    }

    float cpu_load = 0.0f;
    int prev_load = -1;

    while (g_running) {
        if (read_cpu_load(&cpu_load) < 0) {
            fprintf(stderr, "Failed to read CPU load\n");
            break;
        }

        int red, green, blue;
        map_load_to_color(cpu_load, &red, &green, &blue);

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "Failed to set LED color\n");
            break;
        }

        if (prev_load >= 0 && prev_load != cpu_load) {
            float diff = (float)(prev_load - cpu_load);
            if (diff < 0) diff = 0;
            if (diff > 100) diff = 100;
            if (cpu_load < 50) {
                red = (int)(diff / 50.0f * 255.0f);
                green = 255;
                blue = 0;
            } else {
                red = 255;
                green = (int)((100.0f - diff) / 50.0f * 255.0f);
                blue = 0;
            }
            set_led_color(red, green, blue);
        }
        prev_load = cpu_load;

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    return 0;
}

