#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS 1
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define SAMPLE_INTERVAL_S 5

/* BMP280 register addresses */
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG    0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_ID        0xD0

/* Calibration coefficients */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_udp_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration(int handle, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, 0x88, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error reading calibration block: %s\n", strerror(errno));
        return -1;
    }
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t t_fine;

static int32_t compensate_temperature(int32_t adc_T, const bmp280_calib_t *cal) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)cal->dig_T1)) * ((adc_T >> 4) - ((int32_t)cal->dig_T1))) >> 12) *
            ((int32_t)cal->dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P, const bmp280_calib_t *cal) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)cal->dig_P6);
    var2 = var2 + ((var1 * ((int32_t)cal->dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)cal->dig_P4) << 16);
    var1 = (((cal->dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) +
             ((((int32_t)cal->dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)cal->dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1 << 31) - adc_P) - (var2 >> 3))) * 6250U) / (uint32_t)var1;
    var1 = (((int32_t)cal->dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)cal->dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + cal->dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, float *temperature, float *pressure) {
    uint8_t data[6];
    bmp280_calib_t cal;

    if (read_calibration(handle, &cal) != 0) return -1;

    /* ctrl_meas: osrs_t=001 (x1), osrs_p=001 (x1), mode=01 (normal) -> 0x27 */
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas: %s\n", strerror(errno));
        return -1;
    }

    /* config: t_sb=000 (0.5ms), filter=000 (off), spi3w_en=0 -> 0xA0 */
    if (i2cWriteByteData(handle, BMP280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error writing config: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for measurement to complete (max ~5.5ms for x1 oversampling) */
    gpioDelay(6000);

    /* Read raw data */
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    int32_t adc_P = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    int32_t adc_T = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));

    int32_t temp_int = compensate_temperature(adc_T, &cal);
    uint32_t press_int = compensate_pressure(adc_P, &cal);

    *temperature = (float)temp_int / 100.0f;
    *pressure = (float)press_int / 100.0f;

    return 0;
}

static int send_udp_packet(int sock, float temperature, float pressure) {
    char json_string[128];
    struct timeval tv;
    char timestamp[32];

    tv = gettimeofday();
    struct tm *tm_info = localtime(&tv.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    snprintf(json_string, sizeof(json_string),
             "{\"timestamp\":\"%s\",\"temperature\":%.2f,\"pressure\":%.2f}",
             timestamp, temperature, pressure);

    if (send(sock, json_string, strlen(json_string), 0) < 0) {
        fprintf(stderr, "Error sending UDP packet: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Verify sensor presence by reading the ID register */
    int id = i2cReadByteData(g_i2c_handle, BMP280_REG_ID);
    if (id != 0x58) {
        fprintf(stderr, "BMP280 not detected (ID=0x%02X, expected 0x58)\n", id);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", UDP_IP);
        close(g_udp_socket);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        float temperature, pressure;
        if (read_bmp280(g_i2c_handle, &temperature, &pressure) == 0) {
            if (send_udp_packet(g_udp_socket, temperature, pressure) != 0) {
                fprintf(stderr, "Failed to send UDP packet\n");
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "Shutting down...\n");
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    if (g_udp_socket >= 0) close(g_udp_socket);
    gpioTerminate();
    return 0;
}

