/* ---- Configuration ---- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)  */
#define SPI_SPEED        500000     /* 500 kHz, mode 0   */
#define SPI_FLAGS        0          /* main SPI, active-low CE */
#define FAN_GPIO         18         /* hardware PWM on BCM 18 */
#define PWM_FREQUENCY    1000       /* 1 kHz               */
#define PWM_RANGE        255        /* duty 0-255          */
#define BUFFER_SIZE      20
#define SAMPLE_PERIOD_US 1000000    /* 1 second            */

/* ---- MAX31855 fault codes ---- */
#define MAX31855_OK      0
#define MAX31855_FAULT   1
#define MAX31855_READ_ERR 2

/* ---- Fan curve thresholds (°C) ---- */
#define TEMP_LOW         25.0f
#define TEMP_MED         40.0f
#define TEMP_HIGH        60.0f

/* ---- Circular buffer ---- */
typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} log_entry_t;

static log_entry_t log_buffer[BUFFER_SIZE];
static int         buffer_index = 0;

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static bool pigpio_initialized = false;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static int  read_max31855(int spi_handle, float *temperature);
static int  calculate_pwm_duty(float temperature);
static void add_to_buffer(time_t ts, float temp, int duty);
static void print_buffer(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = true;

    /* ---- Configure fan GPIO for hardware PWM ---- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    /* Start with fan off */
    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO %d.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open SPI ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MAX31855 fan controller started.  SPI ch%d @ %d Hz, fan PWM on GPIO%d.\n",
           SPI_CHANNEL, SPI_SPEED, FAN_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (running) {
        float temperature;

        int rc = read_max31855(spi_handle, &temperature);
        if (rc != MAX31855_OK) {
            fprintf(stderr, "Warning: MAX31855 read returned %d; skipping fan update.\n",
                    rc);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int duty = calculate_pwm_duty(temperature);
        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed for duty %d.\n", duty);
        }

        add_to_buffer(time(NULL), temperature, duty);
        print_buffer();

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MAX31855 via SPI.                          */
/* Returns MAX31855_OK (0) on success, MAX31855_FAULT (1) on fault,   */
/* MAX31855_READ_ERR (2) on SPI transfer error.                        */
/* ------------------------------------------------------------------ */
static int read_max31855(int spi_handle, float *temperature)
{
    if (temperature == NULL) {
        return MAX31855_READ_ERR;
    }

    /* MAX31855 SPI frame: 4 bytes, MSB first, read-only */
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int bytes = spiXfer(spi_handle, tx, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 4).\n", bytes);
        return MAX31855_READ_ERR;
    }

    /* Byte 0: fault bit (D0) in bit 0 of byte 1 */
    uint8_t fault = (uint8_t)rx[1] & 0x01;
    if (fault) {
        fprintf(stderr, "Error: MAX31855 fault detected (rx[1]=0x%02X).\n",
                (uint8_t)rx[1]);
        return MAX31855_FAULT;
    }

    /* Byte 1: fault code (D1..D7) */
    uint8_t fault_code = (uint8_t)rx[1] & 0x7F;
    if (fault_code != 0) {
        fprintf(stderr, "Error: MAX31855 fault code 0x%02X.\n", fault_code);
        return MAX31855_FAULT;
    }

    /* Byte 2: thermocouple temperature, 14-bit signed */
    int16_t raw_temp = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[3]);
    raw_temp >>= 2;                       /* keep only 14 bits */
    *temperature = (float)raw_temp * 0.25f;

    return MAX31855_OK;
}

/* ------------------------------------------------------------------ */
/* Piecewise fan curve: 0% < 25 C, 50% @ 40 C, 200% @ 60 C, 100% > 60 C */
/* ------------------------------------------------------------------ */
static int calculate_pwm_duty(float temperature)
{
    if (temperature < TEMP_LOW) return 0;
    if (temperature < TEMP_MED) return (int)((temperature - TEMP_LOW) *
                                              50.0f / (TEMP_MED - TEMP_LOW));
    if (temperature < TEMP_HIGH) return (int)((temperature - TEMP_MED) *
                                               150.0f / (TEMP_HIGH - TEMP_MED) + 50);
    return 200;
}

/* ------------------------------------------------------------------ */
static void add_to_buffer(time_t ts, float temp, int duty)
{
    log_buffer[buffer_index].timestamp  = ts;
    log_buffer[buffer_index].temperature = temp;
    log_buffer[buffer_index].pwm_duty    = duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void)
{
    printf("\n--- Log Buffer (%d entries) ---\n", BUFFER_SIZE);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char tbuf[32];
        struct tm tm_info;
        localtime_r(&log_buffer[idx].timestamp, &tm_info);
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%3d] %s  T=%.2f C  PWM=%3d/%d\n",
               idx, tbuf, log_buffer[idx].temperature, log_buffer[idx].pwm_duty, PWM_RANGE);
    }
    printf("--------------------------------\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (pigpio_initialized) {
        gpioPWM(FAN_GPIO, 0);   /* ensure fan is off */
        gpioTerminate();
        pigpio_initialized = false;
    }
}

