#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4
#define BMP180_CMD_PRESSURE3 0xF4
#define OSS 3
#define GPIO_PIN 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int b = i2cReadByte(handle);
    if (b < 0) return -1;
    *val = (uint8_t)b;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    return (i2cWriteByteData(handle, reg, val) < 0) ? -1 : 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *val) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(handle, reg, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, reg + 1, &lsb) < 0) return -1;
    *val = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int i2c_read_reg16u(int handle, uint8_t reg, uint16_t *val) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(handle, reg, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, reg + 1, &lsb) < 0) return -1;
    *val = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int read_calibration_data(int handle) {
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (i2c_read_reg16u(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2c_write_reg8(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int16_t raw;
    if (i2c_read_reg16(handle, BMP180_REG_MSB, &raw) < 0) return -1;
    *ut = (int32_t)raw;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    uint8_t cmd = BMP180_CMD_PRESSURE0 + (OSS << 6);
    if (i2c_write_reg8(handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(handle, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(handle, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static double calculate_temperature(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    uint32_t x4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b4 = ((uint32_t)ac3 * (uint32_t)(b6 + 32768)) >> 13;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("Program started. Press Ctrl+C to exit.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up, b5;
            if (read_raw_temperature(i2c_handle, &ut) < 0) {
                fprintf(stderr, "Error reading temperature\n");
            } else if (read_raw_pressure(i2c_handle, &up) < 0) {
                fprintf(stderr, "Error reading pressure\n");
            } else {
                double temperature = calculate_temperature(ut, &b5);
                double pressure = calculate_pressure(up, b5);
                log_data(temperature, pressure);
            }
        }
        gpioDelay(1000000);
    }
    printf("\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

