#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0
#define LOG_FILE         "rtd_log.csv"
#define READ_INTERVAL_S  5
#define MAX_RETRIES      3

#define RTD_R0           100.0
#define RTD_A            0.0039083
#define RTD_B            (-5.775e-7)
#define RTD_C            0.0
#define RTD_RREF         4300.0
#define RTD_N            3
#define RTD_RTD_FAULT    0x0001
#define RTD_VBIAS_FAULT  0x0002
#define RTD_OPEN_FAULT   0x0004
#define RTD_SHORT_FAULT  0x0008
#define RTD_GND_FAULT    0x0010
#define RTD_FAULT_MASK   0x001F

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_rtd_data(int fd, uint8_t *data) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (spi_transfer(fd, tx, rx, 4) < 0) {
        return -1;
    }

    memcpy(data, rx, 4);
    return 0;
}

static int read_rtd_temperature(int fd, float *temperature) {
    uint8_t data[4];
    if (read_rtd_data(fd, data) < 0) {
        return -1;
    }

    uint16_t rtd_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t fault = data[3] & RTD_FAULT_MASK;

    if (fault) {
        fprintf(stderr, "RTD fault detected: 0x%04X\n", fault);
        if (fault & RTD_RTD_FAULT) {
            fprintf(stderr, "  RTD sensor absent or disconnected\n");
        }
        return -1;
    }

    uint16_t rtd_code = rtd_raw & 0x07FF;
    if (rtd_code == 0) {
        fprintf(stderr, "RTD code is zero, sensor absent or disconnected\n");
        return -1;
    }

    float rtd_resistance = (float)rtd_code * RTD_RREF / 32768.0f;
    float r0_over_rtd = RTD_R0 / rtd_resistance;
    float z = RTD_N * r0_over_rtd;
    float a = RTD_A;
    float b = RTD_B;
    float c = RTD_C;

    float temp = (a + b * z + c * z * z) / (1.0f + b * z + c * z * z);
    *temperature = temp;
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature\n");
        fflush(g_log_fp);
    }

    printf("Starting RTD temperature logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_rtd_temperature(g_spi_fd, &temperature) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (success) {
            if (log_temperature(g_log_fp, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        }

        if (g_running) {
            sleep(READ_INTERVAL_S);
        }
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return 0;
}

