#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 50000
#define PRESSURE_THRESHOLD 5.0f

typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

typedef struct {
    PressureData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static CircularBuffer pressure_buffer;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_i2c_word(uint8_t reg, int16_t *out) {
    int hi = i2cReadByteData(i2c_handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(i2c_handle, reg + 1);
    if (lo < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int read_i2c_uword(uint8_t reg, uint16_t *out) {
    int hi = i2cReadByteData(i2c_handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(i2c_handle, reg + 1);
    if (lo < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_calibration_data(void) {
    if (read_i2c_word(BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_i2c_uword(BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_i2c_uword(BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_i2c_uword(BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int16_t val;
    if (read_i2c_word(BMP180_REG_MSB, &val) < 0) return -1;
    *raw_temp = val;
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4) + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, time_t ts, float pressure) {
    buf->data[buf->head].timestamp = ts;
    buf->data[buf->head].pressure = pressure;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static float buffer_average(const CircularBuffer *buf) {
    if (buf->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buf->count; i++) sum += buf->data[i].pressure;
    return sum / (float)buf->count;
}

static void check_pressure_alert(float current_pressure, float average_pressure) {
    if (current_pressure > (average_pressure + PRESSURE_THRESHOLD) ||
        current_pressure < (average_pressure - PRESSURE_THRESHOLD)) {
        fprintf(stderr, "Pressure alert: current=%.2f hPa, average=%.2f hPa\n",
                current_pressure, average_pressure);
        gpioWrite(ALERT_GPIO, 1);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error reading temperature from BMP180\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading pressure from BMP180\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    time_t now = time(NULL);
    buffer_add(&pressure_buffer, now, pressure);
    float avg = buffer_average(&pressure_buffer);
    check_pressure_alert(pressure, avg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data from BMP180\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    buffer_init(&pressure_buffer);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_US, timer_callback) != 0) {
        fprintf(stderr, "Error setting up timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFunc(0, 0, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

