#define BMP280_I2C_ADDR_DEFAULT 0x76
#define BMP280_I2C_ADDR_ALT     0x77
#define BMP280_REG_ID           0xD0
#define BMP280_REG_RESET        0xE0
#define BMP280_REG_CTRL_MEAS    0xF4
#define BMP280_REG_CONFIG       0xF5
#define BMP280_REG_PRESS_MSB    0xF7
#define BMP280_REG_TEMP_MSB     0xFA
#define BMP280_REG_CALIB_00     0x88
#define BMP280_REG_CALIB_26     0xE1
#define BMP280_CHIP_ID          0x58
#define BMP280_RESET_CMD        0xB6
#define LOG_FILE               "weather_data.txt"
#define SAMPLE_INTERVAL_SEC    5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_regs(fd, BMP280_REG_ID, &id, 1) != 0) return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) return -1;
    usleep(2000);
    uint8_t ctrl = (0x05 << 5) | (0x02 << 2) | 0x03;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, ctrl) != 0) return -1;
    uint8_t cfg = (0x04 << 5) | (0x02 << 2);
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, cfg) != 0) return -1;
    return 0;
}

static int bmp280_read_calib(int fd, uint16_t *calib) {
    uint8_t buf[24];
    if (i2c_read_regs(fd, BMP280_REG_CALIB_00, buf, 24) != 0) return -1;
    calib[0] = (buf[1] << 8) | buf[0];
    calib[1] = (buf[3] << 8) | buf[2];
    calib[2] = (buf[5] << 8) | buf[4];
    calib[3] = (buf[7] << 8) | buf[6];
    calib[4] = (buf[9] << 8) | buf[8];
    calib[5] = (buf[11] << 8) | buf[10];
    calib[6] = (buf[13] << 8) | buf[12];
