    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)calib[4] << 1))) * ((int32_t)calib[2] >> 2));
    var2 = (((((raw_t >> 5) - ((int32_t)calib[5] << 1)) * ((raw_t >> 5) - ((int32_t)calib[5] << 1))) >> 12) * ((int32_t)calib[3] >> 4));
