        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose on log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

