static int log_data(float temp, float press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose on log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }
    int addr = BMP280_I2C_ADDR_DEFAULT;
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", addr, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd) != 0) {
        fprintf(stderr, "BMP280 init failed at 0x%02X\n", addr);
        close(fd);
        return 1;
    }
    uint16_t calib[12];
    if (bmp280_read_calib(fd, calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X\n", addr);
    while (g_running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
        } else {
            int32_t t = bmp280_compensate_temp(raw_t, calib);
            uint32_t p = bmp280_compensate_press(raw_p, raw_t, calib);
            float temp = t / 100.0f;
            float press = p / 256.0f / 100.0f;
            if (log_data(temp, press) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            printf("T=%.2f °C, P=%.2f hPa\n", temp, press);
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }
    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

