#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          1
#define LM75_ADDR        0x48
#define GPIO_LED         18
#define TEMP_THRESHOLD   28.0f
#define BUFFER_SIZE      60
#define SAMPLE_PERIOD_S  1
#define I2C_REINIT_DELAY 2

#define LM75_REG_TEMP    0x00
#define LM75_REG_CONFIG  0x01
#define LM75_CONFIG_DEFAULT 0x00

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static CircularBuffer g_cb;
static pthread_t g_led_thread;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select)");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

static int init_lm75(int fd) {
    if (i2c_write_reg(fd, LM75_REG_CONFIG, LM75_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to configure LM75\n");
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint8_t val;
    if (i2c_read_reg(fd, LM75_REG_TEMP, &val) < 0) {
        return -1;
    }
    int16_t raw = (int16_t)((val << 8) | val);
    *temp = (float)raw / 16.0f;
    return 0;
}

static void cb_init(CircularBuffer *cb) {
    memset(cb, 0, sizeof(*cb));
    pthread_mutex_init(&cb->mutex, NULL);
}

static void cb_add(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float cb_average(const CircularBuffer *cb) {
    float sum = 0.0f;
    int   count = 0;
    pthread_mutex_lock(&cb->mutex);
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
        count++;
    }
    pthread_mutex_unlock(&cb->mutex);
    return (count > 0) ? (sum / count) : 0.0f;
}

static void *led_thread_fn(void *arg) {
    (void)arg;
    while (g_running) {
        float avg = cb_average(&g_cb);
        int   led_state = (avg > TEMP_THRESHOLD) ? 1 : 0;
        if (gpioWrite(GPIO_LED, led_state) < 0) {
            fprintf(stderr, "gpioWrite failed\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }
    return NULL;
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioSetMode(GPIO_LED, PI_INPUT);
    gpioTerminate();
    pthread_cancel(g_led_thread);
    pthread_join(g_led_thread, NULL);
    pthread_mutex_destroy(&g_cb.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    if (init_lm75(g_i2c_fd) < 0) {
        fprintf(stderr, "LM75 init failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    cb_init(&g_cb);

    if (pthread_create(&g_led_thread, NULL, led_thread_fn, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) == 0) {
            cb_add(&g_cb, temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Temperature read failed; re-initializing I2C\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(I2C_REINIT_DELAY);
            g_i2c_fd = i2c_open();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-open failed; exiting\n");
                break;
            }
            if (init_lm75(g_i2c_fd) < 0) {
                fprintf(stderr, "LM75 re-init failed; exiting\n");
                break;
            }
        }
        sleep(SAMPLE_PERIOD_S);
    }

    cleanup();
    return 0;
}

