/*
 * PID heater controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - MAX31865 32-bit SPI RTD thermometer on SPI0 CE0 (mode 1, 500 kHz)
 *   - PT100 RTD via 430 ohm reference resistor
 *   - MOSFET heater driver on GPIO18 (hardware PWM, 1 kHz, range 1000)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_pid heater_pid.c -lpigpio -lrt -lm
 *   (pigpio must be installed and running as root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define CONFIG_FILE        "heater_config.json"
#define DEFAULT_TARGET_TEMP 25.0f
#define DEFAULT_KP         1.0f
#define DEFAULT_KI         0.1f
#define DEFAULT_KD         0.01f
#define DEFAULT_MAX_TEMP   80.0f
#define DEFAULT_PWM_FREQ   1000
#define DEFAULT_PWM_RANGE  1000
#define DEFAULT_PID_DT     0.1f
#define DEFAULT_PID_SAMPLE 100

#define SPI_CHANNEL        0
#define SPI_SPEED          500000
#define SPI_FLAGS          0
#define MAX31865_VREF      3.3f
#define R_REF              430.0f
#define PT100_NOM          100.0f
#define PT100_ALPHA        0.00385f

#define HEATER_GPIO        18
#define PWM_FREQ           DEFAULT_PWM_FREQ
#define PWM_RANGE          DEFAULT_PWM_RANGE

#define LOG_FILE           "heater_log.txt"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static float g_target_temp = DEFAULT_TARGET_TEMP;
static float g_kp = DEFAULT_KP;
static float g_ki = DEFAULT_KI;
static float g_kd = DEFAULT_KD;
static int   g_max_temp = (int)DEFAULT_MAX_TEMP;
static int   g_pwm_freq = DEFAULT_PWM_FREQ;
static int   g_pwm_range = DEFAULT_PWM_RANGE;
static float g_pid_dt = DEFAULT_PID_DT;
static int   g_pid_sample = DEFAULT_PID_SAMPLE;

static int  g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void log_error(const char *msg);
static void log_msg(const char *msg);
static void load_config(void);
static int  read_rtd(float *temp_c);
static float pid_update(float setpoint, float actual, float *integral,
                        float *prev_err, float dt);
static void set_pwm_duty(int duty);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "[%s] ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

static void log_msg(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

/* ----------------------------- Config ------------------------------------ */

static void load_config(void)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s; using defaults.\n",
                CONFIG_FILE);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;

        if (*p == '\0' || *p == '#') continue;

        char *eq = strchr(p, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = p;
        char *val = eq + 1;
        while (*key == ' ' || *key == '\t') key++;
        size_t klen = strlen(key);
        while (klen > 0 && (key[klen - 1] == ' ' || key[klen - 1] == '\t')) key[--klen] = '\0';
        while (*val == ' ' || *val == '\t') val++;
        size_t vlen = strlen(val);
        while (vlen > 0 && (val[vlen - 1] == ' ' || val[vlen - 1] == '\t')) val[--vlen] = '\0';

        if      (strcmp(key, "target_temp")    == 0) g_target_temp = strtof(val, NULL);
        else if (strcmp(key, "kp")             == 0) g_kp = strtof(val, NULL);
        else if (strcmp(key, "ki")             == 0) g_ki = strtof(val, NULL);
        else if (strcmp(key, "kd")             == 0) g_kd = strtof(val, NULL);
        else if (strcmp(key, "max_temp")       == 0) g_max_temp = atoi(val);
        else if (strcmp(key, "pwm_freq")       == 0) g_pwm_freq = atoi(val);
        else if (strcmp(key, "pwm_range")      == 0) g_pwm_range = atoi(val);
        else if (strcmp(key, "pid_dt")         == 0) g_pid_dt = strtof(val, NULL);
        else if (strcmp(key, "pid_sample")     == 0) g_pid_sample = atoi(val);
    }
    fclose(fp);

    printf("Config: target=%.2f Kp=%.3f Ki=%.3f Kd=%.3f max=%.0f "
           "PWM=%d Hz range=%d dt=%.2f sample=%d\n",
           g_target_temp, g_kp, g_ki, g_kd,
           g_max_temp, g_pwm_freq, g_pwm_range,
           g_pid_dt, g_pid_sample);
}

/* ----------------------------- RTD read ---------------------------------- */

/*
 * MAX31865 32-bit read (mode 1, MSB-first):
 *   D[31:18] = 4 × R_thermocouple (counts, 0.25 °C/ct)
 *   D[17]    = fault bit
 *   D[16:4]  = 4 × R_internal (counts, 0.25 °C/ct)
 *   D[3]     = open-circuit fault
 *   D[2]     = short-to-GND fault
 *   D[1]     = short-to-VCC fault
 *   D[0]     = open-circuit fault (redundant)
 *
 * Returns 0 on success, -1 on SPI error, -2 on sensor fault.
 */
static int read_rtd(float *temp_c)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    /* MAX31865 mode 1: write 0x00, read 4 bytes back */
    if (spiXfer(g_spi_handle, tx, rx, 4) != 4) {
        log_error("SPI transfer failed");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        /* Fault bit (D17) set */
        if (raw & 0x00000004) log_error("MAX31865 open-circuit fault");
        if (raw & 0x00000002) log_error("MAX31865 short-to-GND fault");
        if (raw & 0x00000001) log_error("MAX31865 short-to-VCC fault");
        return -2;
    }

    /* R_thermocouple = raw[31:18] * 0.25 °C */
    uint32_t r_counts = (raw >> 18) & 0x3FFFF;
    float r_thermocouple = r_counts * 0.25f;

    /* PT100: R = R0 * (1 + alpha * T) */
    *temp_c = (r_thermocouple - R_REF) / (PT100_NOM * PT100_ALPHA);
    return 0;
}

/* ----------------------------- PID --------------------------------------- */

static float pid_update(float setpoint, float actual, float *integral,
                        float *prev_err, float dt)
{
