static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "[%s] ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

static void log_msg(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

/* ----------------------------- Config ------------------------------------ */

static void load_config(void)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s; using defaults.\n",
                CONFIG_FILE);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;

        if (*p == '\0' || *p == '#') continue;

        char *eq = strchr(p, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = p;
        char *val = eq + 1;
        while (*key == ' ' || *key == '\t') key++;
        size_t klen = strlen(key);
        while (klen > 0 && (key[klen - 1] == ' ' || key[klen - 1] == '\t')) key[--klen] = '\0';
        while (*val == ' ' || *val == '\t') val++;
        size_t vlen = strlen(val);
        while (vlen > 0 && (val[vlen - 1] == ' ' || val[vlen - 1] == '\t')) val[--vlen] = '\0';

        if      (strcmp(key, "target_temp")    == 0) g_target_temp = strtof(val, NULL);
        else if (strcmp(key, "kp")             == 0) g_kp = strtof(val, NULL);
        else if (strcmp(key, "ki")             == 0) g_ki = strtof(val, NULL);
        else if (strcmp(key, "kd")             == 0) g_kd = strtof(val, NULL);
        else if (strcmp(key, "max_temp")       == 0) g_max_temp = atoi(val);
        else if (strcmp(key, "pwm_freq")       == 0) g_pwm_freq = atoi(val);
        else if (strcmp(key, "pwm_range")      == 0) g_pwm_range = atoi(val);
        else if (strcmp(key, "pid_dt")         == 0) g_pid_dt = strtof(val, NULL);
        else if (strcmp(key, "pid_sample")     == 0) g_pid_sample = atoi(val);
    }
    fclose(fp);

    printf("Config: target=%.2f Kp=%.3f Ki=%.3f Kd=%.3f max=%.0f "
           "PWM=%d Hz range=%d dt=%.2f sample=%d\n",
           g_target_temp, g_kp, g_ki, g_kd,
           g_max_temp, g_pwm_freq, g_pwm_range,
           g_pid_dt, g_pid_sample);
}

/* ----------------------------- RTD read ---------------------------------- */

/*
 * MAX31865 32-bit read (mode 1, MSB-first):
 *   D[31:18] = 4 × R_thermocouple (counts, 0.25 °C/ct)
 *   D[17]    = fault bit
 *   D[16:4]  = 4 × R_internal (counts, 0.25 °C/ct)
 *   D[3]     = open-circuit fault
 *   D[2]     = short-to-GND fault
 *   D[1]     = short-to-VCC fault
 *   D[0]     = open-circuit fault (redundant)
 *
 * Returns 0 on success, -1 on SPI error, -2 on sensor fault.
 */
static int read_rtd(float *temp_c)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    /* MAX31865 mode 1: write 0x00, read 4 bytes back */
    if (spiXfer(g_spi_handle, tx, rx, 4) != 4) {
        log_error("SPI transfer failed");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        /* Fault bit (D17) set */
        if (raw & 0x00000004) log_error("MAX31865 open-circuit fault");
        if (raw & 0x00000002) log_error("MAX31865 short-to-GND fault");
        if (raw & 0x00000001) log_error("MAX31865 short-to-VCC fault");
        return -2;
    }

    /* R_thermocouple = raw[31:18] * 0.25 °C */
    uint32_t r_counts = (raw >> 18) & 0x3FFFF;
    float r_thermocouple = r_counts * 0.25f;

    /* PT100: R = R0 * (1 + alpha * T) */
    *temp_c = (r_thermocouple - R_REF) / (PT100_NOM * PT100_ALPHA);
    return 0;
}

/* ----------------------------- PID --------------------------------------- */

static float pid_update(float setpoint, float actual, float *integral,
                        float *prev_err, float dt)
{
    float err = setpoint - actual;
