    int on_us = (duty * 1000000) / g_pwm_range;
    int off_us = 1000000 - on_us;
    if (on_us > 0) {
        gpioPWM(HEATER_GPIO, duty);
    } else {
        gpioPWM(HEATER_GPIO, 0);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    set_pwm_duty(0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
