#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    return i2c_read_bytes(fd, reg, val, 1);
}

static int bmp180_read_calibration(int fd, int16_t *ac1, int16_t *ac2, uint16_t *ac3, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, buf, 22) < 0) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (uint16_t)((buf[4] << 8) | buf[5]);
    *b1 = (int16_t)((buf[6] << 8) | buf[7]);
    *b2 = (int16_t)((buf[8] << 8) | buf[9]);
    *mb = (int16_t)((buf[10] << 8) | buf[11]);
    *mc = (int16_t)((buf[12] << 8) | buf[13]);
    *md = (int16_t)((buf[14] << 8) | buf[15]);
    return 0;
}

static int bmp180_read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp180_read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    *up >>= (8 - 0);
    return 0;
}

static int32_t compute_b5(int32_t ut, int16_t ac1, int16_t ac2, int16_t ac3) {
    int32_t x1 = ((ut - (int32_t)ac1) * (int32_t)ac2) >> 15;
    int32_t x2 = ((int32_t)ac3 * (int32_t)ut) >> 15;
    return x1 + x2;
}

static float bmp180_compute_temperature(int32_t ut, int16_t ac1, int16_t ac2, int16_t ac3) {
    int32_t b5 = compute_b5(ut, ac1, ac2, ac3);
    int32_t t = (b5 + 8) >> 4;
    return (float)t / 10.0f;
}

static float bmp180_compute_pressure(int32_t up, int32_t ut, int16_t ac1, int16_t ac2, int16_t ac3, int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md) {
    int32_t b5 = compute_b5(ut, ac1, ac2, ac3);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)mc * (x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void log_breach(const char *timestamp, float temp, float press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    fprintf(fp, "%s, Temp: %.2f C, Pressure: %.2f hPa\n", timestamp, temp, press);
    fclose(fp);
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    if (bmp180_read_calibration(fd, &ac1, &ac2, &ac3, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t ut, up;
        int retries = 0;
        int ok = 0;

        while (retries < MAX_RETRIES && running) {
            if (bmp180_read_raw_temp(fd, &ut) == 0 && bmp180_read_raw_pressure(fd, &up) == 0) {
                ok = 1;
