        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    if (bmp180_read_calibration(fd, &ac1, &ac2, &ac3, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t ut, up;
        int retries = 0;
        int ok = 0;

        while (retries < MAX_RETRIES && running) {
            if (bmp180_read_raw_temp(fd, &ut) == 0 && bmp180_read_raw_pressure(fd, &up) == 0) {
                ok = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
            sleep(1);
            continue;
        }

        float temp = bmp180_compute_temperature(ut, ac1, ac2, ac3);
        float press = bmp180_compute_pressure(up, ut, ac1, ac2, ac3, b1, b2, mb, mc, md);

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            log_breach(ts, temp, press);
        }

        sleep(1);
    }

    close(fd);
    return 0;
}

