/*
 * BMP180 I2C temperature & pressure monitor with fan control.
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: BMP180 at 0x77
 * Fan:    GPIO18 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (datasheet) ---- */
#define BMP180_ADDR        0x77
#define BMP180_REG_CAL     0xAA   /* 22 bytes: 11 words */
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA    0xF6
#define BMP180_CMD_TEMP    0x2E
#define BMP180_CMD_PRESS   0x34   /* OSS = 0 */
#define BMP180_TEMP_CONV   5      /* ms */
#define BMP180_PRESS_CONV  5      /* ms */

/* ---- Application constants ---- */
#define FAN_GPIO           18
#define TEMP_THRESHOLD     30.0f
#define BUFFER_SIZE        60
#define SAMPLE_PERIOD_US   500000  /* 500 ms */

/* ---- Data structures ---- */
typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int           i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t buffer;

/* ---- Calibration coefficients ---- */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ---- Prototypes ---- */
static int  bmp180_read_calibration(void);
static int  bmp180_read_raw_temperature(int32_t *raw);
static int  bmp180_read_raw_pressure(int32_t *raw);
static float bmp180_compute_temperature(int32_t raw);
static float bmp180_compute_pressure(int32_t raw_temp, int32_t raw_press);
static void buffer_init(circular_buffer_t *cb);
static void buffer_add(circular_buffer_t *cb, const sensor_data_t *d);
static void buffer_print(const circular_buffer_t *cb);
static void fan_set(int on);
static void timer_callback(void *userdata);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_set(0);

    /* I2C open */
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Calibration */
    if (bmp180_read_calibration() != 0) {
        fprintf(stderr, "BMP180 calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Timer (500 ms) */
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signals */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Buffer */
    buffer_init(&buffer);

    printf("BMP180 monitoring started (500 ms interval). Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* Cleanup */
    fan_set(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static int bmp180_read_calibration(void)
{
    char buf[22];

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL, buf, 22) != 22) {
        fprintf(stderr, "Failed to read calibration block\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity: AC1 should never be 0 or 0xFFFF on a real BMP180 */
    if (ac1 == 0 || ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "BMP180 calibration data invalid (AC1=0x%04X)\n", (uint16_t)ac1);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int bmp180_read_raw_temperature(int32_t *raw)
{
    char cmd = BMP180_CMD_TEMP;
    char buf[2];

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &cmd, 1) != 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(BMP180_TEMP_CONV);

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_DATA, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    *raw = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int bmp180_read_raw_pressure(int32_t *raw)
{
    char cmd = BMP180_CMD_PRESS;
    char buf[3];

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &cmd, 1) != 0) {
        fprintf(stderr, "Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(BMP180_PRESS_CONV);

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_DATA, buf, 3) != 3) {
        fprintf(stderr, "Failed to read pressure data\n");
        return -1;
    }
    *raw = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - 0);
    return 0;
}

/* ------------------------------------------------------------------ */
static float bmp180_compute_temperature(int32_t raw)
{
    int32_t x1 = ((raw - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

/* ------------------------------------------------------------------ */
static float bmp180_compute_pressure(int32_t raw_temp, int32_t raw_press)
{
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_press - b3) * (50000 >> 0);

    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p;
}

/* ------------------------------------------------------------------ */
static void buffer_init(circular_buffer_t *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(circular_buffer_t *cb, const sensor_data_t *d)
{
    cb->data[cb->head] = *d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void buffer_print(const circular_buffer_t *cb)
{
    printf("\n--- Circular buffer (%d entries) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&cb->data[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] T=%.2f C  P=%.2f Pa\n",
               ts, cb->data[idx].temperature, cb->data[idx].pressure);
    }
    printf("-------------------------------------\n");
}

/* ------------------------------------------------------------------ */
static void fan_set(int on)
{
    if (gpioWrite(FAN_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", FAN_GPIO);
    }
}

/* ------------------------------------------------------------------ */
static void timer_callback(void *userdata)
{
    (void)userdata;

    int32_t raw_temp = 0, raw_press = 0;

    if (bmp180_read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Temperature read failed; skipping sample\n");
        return;
    }
    if (bmp180_read_raw_pressure(&raw_press) != 0) {
        fprintf(stderr, "Pressure read failed; skipping sample\n");
        return;
    }

    float temperature = bmp180_compute_temperature(raw_temp);
    float pressure    = bmp180_compute_pressure(raw_temp, raw_press);

    sensor_data_t data;
    data.timestamp = time(NULL);
    data.temperature = temperature;
    data.pressure = pressure;

    buffer_add(&buffer, &data);

    printf("T=%.2f C  P=%.2f Pa\n", temperature, pressure);

    if (temperature > TEMP_THRESHOLD) {
        fan_set(1);
    } else {
        fan_set(0);
    }
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

