    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Buffer */
    buffer_init(&buffer);

    printf("BMP180 monitoring started (500 ms interval). Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* Cleanup */
    fan_set(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
