/*
 * Raspberry Pi 3 Model B+ — MAX31855 thermocouple reader + PWM heater controller
 *
 * Wiring:
 *   MAX31855  VCC  -> 3V3 (pin 1)
 *   MAX31855  GND  -> GND (pin 9)
 *   MAX31855  SCLK -> GPIO11 (pin 23, SPI0 SCLK)
 *   MAX31855  CS   -> GPIO8  (pin 24, SPI0 CE0)
 *   MAX31855  DO   -> GPIO9  (pin 21, SPI0 MISO)
 *   Relay     IN   -> GPIO17 (pin 11) via NPN transistor / relay module
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater heater.c -lpigpio -lrt -lm
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                         */
#define SPI_SPEED        2000000    /* 2 MHz — well within MAX31855 5 MHz limit  */
#define SPI_FLAGS        0          /* Mode 0, active-low CS, 3-wire off         */
#define HEATER_GPIO      17         /* Relay control pin                        */
#define PWM_FREQUENCY    1000       /* 1 kHz carrier for relay PWM              */
#define PWM_RANGE        100        /* 0–100 % duty cycle                       */
#define TARGET_TEMP      25.0       /* Default target temperature (°C)          */
#define MAX_DUTY         80.0       /* Safe maximum duty cycle (percent)         */
#define SAMPLE_PERIOD_S  1.0        /* Sampling interval (seconds)              */
#define LOG_FILE         "heater_log.csv"
#define ERROR_TEMP       -1000.0     /* sentinel for read failure                */

/* PI controller gains */
#define KP                2.0
#define KI                0.1

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize(void);
static void cleanup(void);
static void signal_handler(int sig);
static int  read_max31855(double *temp_c, double *fault);
static double calculate_duty(double temp, double target);
static void set_relay_duty(double duty);
static void log_data(double temp, double duty, const char *status);
static void log_error(const char *msg);

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    double temp = 0.0, duty = 0.0;

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Graceful shutdown on Ctrl-C / SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int rc = read_max31855(&temp, NULL);   /* no fault path yet — see below */

        if (rc != 0) {
            /* SPI read failure — set heater off and log the error */
            duty = 0.0;
            set_relay_duty(0.0);
            log_error("SPI read failure");
            time_sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* PI controller with anti-windup */
        double integral = 0.0;
        double error = temp - TARGET_TEMP;
        duty = KP * error + KI * integral;

        if (duty < 0.0) {
            duty = 0.0;
            integral += error;
        } else if (duty > MAX_DUTY) {
            duty = MAX_DUTY;
            integral += error;
        } else {
            integral += error;
        }

        set_relay_duty(duty);
        log_data(temp, duty, "OK");
        time_sleep(SAMPLE_PERIOD_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Initialization ------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(g_spi_handle));
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", HEATER_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d) failed\n", HEATER_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange(%d) failed\n", HEATER_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }

    /* Start with heater off */
    if (gpioPWM(HEATER_GPIO, 0) != 0) {
        fprintf(stderr, "gpioPWM(%d, 0) failed\n", HEATER_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,temperature_c,duty_percent,status\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        gpioPWM(HEATER_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MAX31855 read -------------------------------- */
/*
 * Reads 4 bytes from the MAX31855 and decodes the 14-bit signed thermocouple
 * temperature, as well as the fault bits.
 *
 * Returns  0 on success (temp set to valid value),
 *         -1 on SPI transfer failure,
 *         -2 on any fault condition (open, short to GND, short to VCC).
 */
static int read_max31855(double *temp, double *fault)
{
    char rx[4] = {0, 0, 0, 0};

    int rc = spiRead(g_spi_handle, rx, 4);
    if (rc != 4) {
        fprintf(stderr, "spiRead failed: returned %d (%s)\n",
                rc, pigpio_error(rc));
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit is D16 (bit 16 of the 32-bit word) */
    if (raw & 0x00010000) {
        if (fault) *fault = "MAX31855 fault";
        return -2;
    }

    /*
     * Thermocouple temperature: D31..D18 (14-bit signed, 0.25 °C / LSB).
     * Bits D15..D4 are reserved / unused; D3 is the sign bit.
     */
    int16_t thermocouple = (int16_t)(raw >> 18);   /* sign-extends automatically */

    /* Convert 14-bit signed value to double */
    *temp = (double)thermocouple * 0.25;

    return 0;
}

/* --------------------------- PI controller -------------------------------- */
static double calculate_duty(double temp, double target)
{
    double error = temp - target;
    static double integral = 0.0;

    double duty = KP * error + KI * integral;

    if (duty < 0.0) {
        duty = 0.0;
        integral += error;
    } else if (duty > MAX_DUTY) {
        duty = MAX_DUTY;
        integral += error;
    } else {
        integral += error;
    }

    return duty;
}

/* --------------------------- Relay PWM ----------------------------------- */
static void set_relay_duty(double duty)
{
    if (duty < 0.0) duty = 0.0;
    if (duty > 100.0) duty = 100.0;

    int pwm = (int)(duty + 0.5);   /* round to nearest integer */
    if (gpioPWM(HEATER_GPIO, pwm) != 0) {
        fprintf(stderr, "gpioPWM(%d) failed\n", HEATER_GPIO);
    }
}

/* --------------------------- Logging ------------------------------------- */
static void log_data(double temp, double duty, const char *status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%.2f,%s\n", ts, temp, duty, status);
    fflush(g_log_file);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_file, "%s,ERROR,%s,%s\n", ts, msg, "ERROR");
    fflush(g_log_file);
}

