#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE  255
#define POLL_SEC   0.5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int set_pwm(int pin, int value)
{
    if (value < 0 || value > PWM_RANGE) {
        fprintf(stderr, "Error: PWM value %d out of range for pin %d\n", value, pin);
        return -1;
    }
    int duty = PWM_RANGE - value; /* common-anode: 0 = full on, 255 = off */
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d (duty %d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: failed to read temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: read error on %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

static void set_led_color(int red, int green, int blue)
{
    set_pwm(RED_PIN, red);
    set_pwm(GREEN_PIN, green);
    set_pwm(BLUE_PIN, blue);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return 1;
    }

    /* Set PWM range for all three pins */
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure LED is off at start */
    set_led_color(0, 0, 0);

    while (program_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping cycle\n");
        } else {
            int mdegC = temp;
            int red, green, blue;
            if (mdegC < 40000) {
                red = 0; green = 0; blue = 255;
            } else if (mdegC < 60000) {
                red = 0; green = 255; blue = 0;
            } else {
                red = 255; green = 0; blue = 0;
            }
            set_led_color(red, green, blue);
            printf("CPU Temperature: %d m°C, RGB: (%d, %d, %d)\n",
                   mdegC, red, green, blue);
            fflush(stdout);
        }
        sleep(1);
    }

    /* Graceful shutdown: turn off LED and release GPIO */
    set_led_color(0, 0, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

