#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define API_ENDPOINT "/api/humidity"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_state = PI_HIGH;
    int counter = 0;
    int j = 0;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(2000);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    for (i = 0; i < 85; i++) {
        counter = 0;
        while (gpioRead(gpio) == last_state) {
            counter++;
            gpioDelay(1);
            if (counter == 255) break;
        }
        last_state = gpioRead(gpio);

        if (counter == 255) break;

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16)
                data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) {
        fprintf(stderr, "DHT22: insufficient data (%d bits)\n", j);
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: checksum error\n");
        return -2;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

static int post_data(const char *server_ip, const char *api_endpoint, float temperature, float humidity) {
    int sockfd = -1;
    struct sockaddr_in servaddr;
    char request[512];
    char json[128];
    int ret = -1;

    snprintf(json, sizeof(json), "{\"temperature\":%.1f,\"humidity\":%.1f}", temperature, humidity);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        perror("Invalid address");
        goto cleanup;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect failed");
        goto cleanup;
    }

    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             api_endpoint, server_ip, strlen(json), json);

    if (write(sockfd, request, strlen(request)) < 0) {
        perror("write failed");
        goto cleanup;
    }

    char response[1024] = {0};
    ssize_t bytes = read(sockfd, response, sizeof(response) - 1);
    if (bytes > 0) {
        printf("Server response: %s\n", response);
    } else if (bytes < 0) {
        perror("read failed");
    }

    ret = 0;

cleanup:
    if (sockfd >= 0) close(sockfd);
    return ret;
}

int main(void) {
    float temperature, humidity;
    int retries;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success && running) {
            int rc = read_dht22(DHT22_GPIO, &temperature, &humidity);
            if (rc == 0) {
                success = 1;
            } else {
                fprintf(stderr, "DHT22 read failed (rc=%d), retry %d/%d\n", rc, retries + 1, MAX_RETRIES);
                retries++;
                if (retries < MAX_RETRIES) gpioDelay(2000000);
            }
        }

        if (success) {
            if (post_data(SERVER_IP, API_ENDPOINT, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to post data to server\n");
            }
        } else {
            fprintf(stderr, "DHT22 read failed after %d retries\n", MAX_RETRIES);
        }

        if (running) sleep(READ_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

