#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BUTTON_GPIO 4
#define I2C_BUS 1
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_US 200000
#define BMP180_CONV_DELAY_US 26000

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

static volatile sig_atomic_t logging_enabled = false;
static volatile sig_atomic_t running = true;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_handle = -1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t diff = tick - last_interrupt_tick;
    if (diff < DEBOUNCE_US) return;
    last_interrupt_tick = tick;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    fflush(stdout);
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int read_calibration(bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_reg(BMP180_REG_CAL_AC1, buf, 22) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (cal->ac1 == 0 || cal->ac1 == -1) {
        fprintf(stderr, "Invalid calibration data (sensor absent?)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temp(int32_t *ut) {
    if (i2c_write_reg(BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2c_write_reg(BMP180_REG_CONTROL, 0x34) != 0) return -1;
    gpioDelay(BMP180_CONV_DELAY_US);
    uint8_t buf[3];
    if (i2c_read_reg(BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - 3);
    return 0;
}

static int32_t compute_b5(const bmp180_cal_t *cal, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static int32_t compute_pressure(const bmp180_cal_t *cal, int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << 3) + 2) >> 2);
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (uint32_t)50000;
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void log_pressure(int32_t pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %d hPa\n", ts, pressure / 100);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = false;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (addr 0x%02X)\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    bmp180_cal_t cal;
    if (read_calibration(&cal) != 0) {
        fprintf(stderr, "BMP180 calibration read failed\n");
        cleanup();
        return 1;
    }
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", BUTTON_GPIO);
        cleanup();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("BMP180 pressure logger ready. Press Ctrl+C to exit.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up, b5, pressure;
            if (read_raw_temp(&ut) != 0 || read_raw_pressure(&up) != 0) {
                fprintf(stderr, "Sensor read error\n");
            } else {
                b5 = compute_b5(&cal, ut);
                pressure = compute_pressure(&cal, up, b5);
                log_pressure(pressure);
            }
        }
        gpioDelay(2000000);
    }
    cleanup();
    return 0;
}

