#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <getopt.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define READ_INTERVAL 10
#define DHT22_TIMEOUT_US 1000000
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_BIT_THRESHOLD_US 50

#define DHT22_OK 0
#define DHT22_ERROR_CHECKSUM -1
#define DHT22_ERROR_TIMEOUT -2
#define DHT22_ERROR_GPIO -3

typedef struct {
    float humidity;
    int error_code;
} DHT22Data;

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-librarys-api-call.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, long timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpioRead(gpio) != level) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22_data(DHT22Data *data) {
    data->error_code = DHT22_OK;
    data->humidity = -1.0f;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) {
            syslog(LOG_ERR, "DHT22: gpioSetMode output failed: %s", strerror(errno));
            data->error_code = DHT22_ERROR_GPIO;
            goto retry;
        }
        if (gpioWrite(DHT22_GPIO, 0) < 0) {
            syslog(LOG_ERR, "DHT22: gpioWrite low failed: %s", strerror(errno));
            data->error_code = DHT22_ERROR_GPIO;
            goto retry;
        }
        usleep(DHT22_START_LOW_US);

        if (gpioWrite(DHT22_GPIO, 1) < 0) {
            syslog(LOG_ERR, "DHT22: gpioWrite high failed: %s", strerror(errno));
            data->error_code = DHT22_ERROR_GPIO;
            goto retry;
        }
        usleep(DHT22_START_HIGH_US);

        if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) {
            syslog(LOG_ERR, "DHT22: gpioSetMode input failed: %s", strerror(errno));
            data->error_code = DHT22_ERROR_GPIO;
            goto retry;
        }

        if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) {
            syslog(LOG_ERR, "DHT22: timeout waiting for response low");
            data->error_code = DHT22_ERROR_TIMEOUT;
            goto retry;
        }
        if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) {
            syslog(LOG_ERR, "DHT22: timeout waiting for response high");
            data->error_code = DHT22_ERROR_TIMEOUT;
            goto retry;
        }
        if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) {
            syslog(LOG_ERR, "DHT22: timeout waiting for data start");
            data->error_code = DHT22_ERROR_TIMEOUT;
            goto retry;
        }

        int bits = 0;
        for (int i = 0; i < 40; i++) {
            if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) {
                syslog(LOG_ERR, "DHT22: timeout waiting for bit %d high", i);
                data->error_code = DHT22_ERROR_TIMEOUT;
                goto retry;
            }
            long high_start, high_end;
            clock_gettime(CLOCK_MONOTONIC, &high_start);
            while (gpioRead(DHT22_GPIO) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &high_end);
                long elapsed = (high_end.tv_sec - high_start.tv_sec) * 1000000 + (high_end.tv_nsec - high_start.tv_nsec) / 1000;
                if (elapsed > DHT22_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22: timeout measuring bit %d high pulse", i);
                    data->error_code = DHT22_ERROR_TIMEOUT;
                    goto retry;
                }
            }
            long pulse_width = (high_end.tv_sec - high_start.tv_sec) * 1000000 + (high_end.tv_nsec - high_start.tv_nsec) / 1000;
            if (pulse_width > DHT22_BIT_THRESHOLD_US) {
                bits |= (1 << (39 - i));
            }
        }

        int raw_humidity = (bits >> 16) & 0xFFFF;
        int raw_temperature = bits & 0xFFFF;

        if (((raw_humidity + raw_temperature) & 0xFFFF) != (bits >> 8) & 0xFFFF) {
            syslog(LOG_ERR, "DHT22: checksum error (raw=%d, byte=%d)", bits >> 8, bits >> 16);
            data->error_code = DHT22_ERROR_CHECKSUM;
            goto retry;
        }

        float humidity = (float)raw_humidity / 10.0f;
        data->humidity = humidity;
        return 0;

    retry:
        if (attempt < MAX_RETRIES - 1) {
            syslog(LOG_WARNING, "DHT22: retry %d/%d", attempt + 1, MAX_RETRIES);
            sleep(2);
        }
    }

    syslog(LOG_ERR, "DHT22: max retries reached");
    return -1;
}

static int post_humidity_data(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json_string[128];
    snprintf(json_string, sizeof(json_string), "{\"humidity\":%.2f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, api_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = 0;
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        ret = -1;
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code < 200 || http_code >= 300) {
            syslog(LOG_ERR, "HTTP request failed with code %ld", http_code);
            ret = -1;
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init failed");
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        DHT22Data data;
        if (read_dht22_data(&data) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", data.humidity);
            if (post_humidity_data(data.humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "DHT22 read failed (code %d)", data.error_code);
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

