#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

#define TEMP_ERROR -1
#define FAN_ERROR -1
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return TEMP_ERROR;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return TEMP_ERROR;
    }

    fclose(fp);
    return temp;
}

static int read_max_fan_state(void) {
    FILE *fp = fopen(FAN_MAX_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_STATE_FILE, strerror(errno));
        return FAN_ERROR;
    }

    int max_state = -1;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_MAX_STATE_FILE);
        fclose(fp);
        return FAN_ERROR;
    }

    fclose(fp);
    return max_state;
}

static int set_fan_speed(int speed) {
    FILE *fp = fopen(FAN_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_FILE, strerror(errno));
        return FAN_ERROR;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_FILE, strerror(errno));
        fclose(fp);
        return FAN_ERROR;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_FILE, strerror(errno));
        return FAN_ERROR;
    }

    return 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

static int map_temp_to_speed(int temp_celsius) {
    if (temp_celsius >= 65) return 3;
    if (temp_celsius >= 65) return 2;
    if (temp_celsius >= 55) return 1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int max_state = read_max_fan_state();
    if (max_state == FAN_ERROR) {
        fprintf(stderr, "Failed to read max_fan_state. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (max_state < 0 || max_state > 3) {
        fprintf(stderr, "Invalid max_state (%d). Exiting.\n", max_state);
        return EXIT_FAILURE;
    }

    printf("Fan control started. Max state: %d\n", max_state);

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp == TEMP_ERROR) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int speed = map_temp_to_speed(temp / 1000);
        if (speed > max_state) {
            fprintf(stderr, "Requested speed %d exceeds max_state %d. Clamping.\n", speed, max_state);
            speed = max_state;
        }

        if (speed != 0) {
            if (set_fan_speed(speed) == 0) {
                char log_msg[128];
                snprintf(log_msg, sizeof(log_msg), "Fan set to speed %d", speed);
                log_event(log_msg);
                printf("Fan set to speed %d\n", speed);
            } else {
                fprintf(stderr, "Failed to set fan speed. Retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            }
        } else {
            if (set_fan_speed(0) == 0) {
                char log_msg[128];
                snprintf(log_msg, sizeof(log_msg), "Fan set to speed 0 (off)");
                log_event(log_msg);
                printf("Fan set to speed 0 (off)\n");
            } else {
                fprintf(stderr, "Failed to set fan to off. Retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (set_fan_speed(0) == 0) {
        log_event("Fan control shutting down, setting fan to speed 0");
    } else {
        fprintf(stderr, "Failed to set fan to off during shutdown.\n");
    }

    return EXIT_SUCCESS;
}

