static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure heater is off before terminating pigpio */
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Logging ---------------------------------- */
static void log_message(const char *msg) {
    if (!g_log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

static void log_data(double temperature, int duty, double pid_output, const char *status) {
    if (!g_log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%.2f,%d,%.2f,%s\n", ts, temperature, duty, pid_output, status);
    fflush(g_log_file);
}

/* ----------------------------- MAX31855 --------------------------------- */
/*
 * MAX31855 32-bit SPI frame (big-endian):
 *   D31..D18 : thermocouple temperature, 14-bit signed, 0.25 °C / count
 *   D17      : reserved (0)
 *   D16      : fault bit
 *   D15..D4  : internal reference junction, 12-bit signed, 0.0625 °C / count
 *   D3       : reserved (0)
 *   D2       : fault bit
 *   D1       : reserved (0)
 *   D0       : fault bit
 *
 * Fault codes (D16, D2, D0):
 *   0x0000 = no fault
 *   0x0001 = open circuit
 *   0x0002 = short to GND
 *   0x0003 = short to VCC
 */
static int read_max31855(double *temperature, char *fault_str, size_t fault_len) {
    char rx[4] = {0, 0, 0, 0};

    /* MAX31855 is read-only; a dummy write (0 bytes) is sufficient to clock data out. */
    int bytes = spiXfer(g_spi_handle, rx, rx, 4);
    if (bytes != 4) {
        snprintf(fault_str, fault_len, "SPI transfer failed (returned %d)", bytes);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit is D16 (bit 16 of 32-bit word) */
    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            snprintf(fault_str, fault_len, "Open circuit");
        } else if (raw & 0x00000002) {
            snprintf(fault_str, fault_len, "Short to GND");
        } else if (raw & 0x00000004) {
            snprintf(fault_str, fault_len, "Short to VCC");
        } else {
            snprintf(fault_str, fault_len, "Unknown fault");
        }
        return -2;  /* fault detected */
    }

    /* Thermocouple temperature: bits D31..D18, 14-bit signed, 0.25 °C / count */
    int16_t therm_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (therm_raw & 0x2000) {
        therm_raw |= 0xC000;  /* sign-extend */
    }
    *temperature = therm_raw * 0.25;
    return 0;
}

/* ----------------------------- PID -------------------------------------- */
static double calculate_pid(double setpoint, double actual, PIDState *state) {
    double error = setpoint - actual;
    state->integral += error;
    /* Anti-windup clamp */
    if (state->integral > 100.0) state->integral = 100.0;
    if (state->integral < 0.0)   state->integral = 0.0;
    double derivative = error - state->previous_error;
    double output = KP * error + KI * state->integral + KD * derivative;
    state->previous_error = error;
    return output;
}

/* ----------------------------- PWM -------------------------------------- */
static int set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty) != 0) {
        log_message("Failed to set PWM duty cycle");
        return -1;
    }
    return 0;
}

/* ----------------------------- Init -------------------------------------- */
static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Heater GPIO: PWM mode */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    /* Start with heater off */
    if (gpioPWM(HEATER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM duty on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return -1;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,temperature,duty,pid_output,status\n");
        fflush(g_log_file);
    }

    log_message("Heater controller started");
    return 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    PIDState pid_state = {0.0, 0.0};
    char fault_str[64] = {0};

    while (g_running) {
        double temperature = 0.0;
        int duty = 0;
        bool fault = false;
        const char *status = "OK";

        int rc = read_max31855(&temperature, fault_str, sizeof(fault_str));
        if (rc == -1) {
            /* SPI transfer error — log and keep heater off */
            log_message("SPI transfer error");
            set_pwm_duty(0);
            duty = 0;
        } else if (rc == -2) {
            /* Thermocouple fault — disable heater, reset PID, log */
            log_message(fault_str);
            set_pwm_duty(0);
            duty = 0;
            pid_state.integral = 0.0;
            pid_state.previous_error = 0.0;
            status = "FAULT";
        } else {
            /* Normal reading */
            if (temperature < MIN_TEMPERATURE || temperature > MAX_TEMPERATURE) {
                log_message("Temperature out of range — heater OFF (failsafe)");
                set_pwm_duty(0);
                duty = 0;
                status = "FAILSAFE";
            } else {
                double pid_output = calculate_pid(TARGET_TEMPERATURE, temperature, &pid_state);
                int pwm_duty = (int)(pid_output + 0.5);  /* round */
                if (pwm_duty < 0) pwm_duty = 0;
                if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;
                if (set_pwm_duty(pwm_duty) != 0) {
                    log_message("PWM duty cycle set failed");
                }
                duty = pwm_duty;
            }
        }

        log_data(temperature, duty, 0.0, status);  /* pid_output unused when fault */
        sleep(SAMPLE_INTERVAL_S);
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

