#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define PWM_FREQUENCY     25000   /* Hz — Noctua 5V PWM fans natively support 25 kHz */
#define PWM_RANGE         255     /* 8-bit resolution */
#define TEMP_LOW          40.0f
#define TEMP_HIGH         70.0f
#define POLL_INTERVAL_S   5
#define LOG_FILE          "cooling_log.csv"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Temperature reading                                                 */
/* ------------------------------------------------------------------ */
static float read_cpu_temperature(void)
{
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1.0f;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature value\n");
        fclose(fp);
        return -1.0f;
    }

    fclose(fp);
    return (float)temp_milli / 1000.0f;
}

/* ------------------------------------------------------------------ */
/* PWM control                                                          */
/* ------------------------------------------------------------------ */
static int set_fan_speed(float temperature)
{
    float duty = 0.0f;

    if (temperature <= TEMP_LOW) {
        duty = 0.0f;
    } else if (temperature >= TEMP_HIGH) {
        duty = 100.0f;
    } else {
        duty = ((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW)) * 100.0f;
    }

    int pwm_value = (int)(duty + 0.5f);
    if (pwm_value < 0)   pwm_value = 0;
    if (pwm_value > 255) pwm_value = 255;

    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM value to %d\n", pwm_value);
        return -1;
    }

    printf("Temperature: %.2f °C, PWM duty: %d%%\n", temperature, pwm_value);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, int pwm_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, pwm_value);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure fan is off before terminating */
    if (gpioInitialise() >= 0) {
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO18 as PWM output */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error setting PWM range to %d\n", PWM_RANGE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure fan is off initially */
    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting initial PWM value\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new/empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        if (fp == NULL) {
            fp = fopen(LOG_FILE, "w");
            if (fp != NULL) {
                fprintf(fp, "timestamp,temperature_c,pwm_duty_percent\n");
                fclose(fp);
            } else {
                fprintf(stderr, "Error creating log file '%s': %s\n", LOG_FILE, strerror(errno));
            }
        } else {
            fclose(fp);
        }
    }

    printf("Fan control started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main polling loop */
    while (g_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0.0f) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", POLL_INTERVAL_S);
        } else {
            if (set_fan_speed(temperature) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }

            if (log_data(temperature, 0) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

