#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR_1     0x48
#define I2C_ADDR_2     0x49
#define LOG_FILE       "flow_log.txt"
#define MAX_RETRIES    3
#define READ_INTERVAL  1.0

static volatile sig_atomic_t g_running = 1;
static int g_handle1 = -1;
static int g_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_sensor(int handle, float *flow_out) {
    char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int n = i2cReadDevice(handle, buf, 3);
        if (n == 3) {
            uint8_t *u = (uint8_t *)buf;
            if (crc8(u, 2) == u[2]) {
                int16_t raw = (int16_t)((u[0] << 8) | u[1]);
                *flow_out = (float)raw / 1000.0f;
                return 0;
            }
        }
        retries++;
        if (retries < MAX_RETRIES) time_sleep(0.01);
    }
    return -1;
}

static void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f\n", ts, flow1, flow2);
    fclose(fp);
}

