/*
 * Magnetic Rotary Encoder Monitor (Raspberry Pi 4 Model B)
 * Sensors: 2x TMAG5110A1 Hall-Effect latch sensors
 *   - Channel A -> GPIO17 (physical pin 11)
 *   - Channel B -> GPIO18 (physical pin 12)
 *
 * Wiring:
 *   TMAG5110A1 VCC  -> 3.3 V (pin 1)
 *   TMAG5110A1 GND  -> GND   (pin 9)
 *   TMAG5110A1 SDA  -> GPIO2 / I2C1 SDA (pin 3)
 *   TMAG5110A1 SCL  -> GPIO3 / I2C1 SCL (pin 5)
 *   TMAG5110A1 AOUT -> GPIO17 (pin 11)
 *   TMAG5110A1 BOUT -> GPIO18 (pin 12)
 *
 * The TMAG5110A1 is an open-drain Hall sensor; the Pi GPIO pins are
 * configured as open-drain outputs with internal pull-ups enabled.
 *
 * Build:  gcc -O2 -Wall -Wextra -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:    sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define GPIO_A          17
#define GPIO_B          18

#define PULSES_PER_REV  360          /* 360 degrees / 1 revolution            */
#define LOG_FILE        "encoder_log.txt"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static int  init_gpio(void);
static int  read_encoder(int *out_state);
static double calculate_angle(int state);
static int  log_position(double angle);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* gpioTerminate() also releases any resources held by pigpio. */
    gpioTerminate();
}

/* ----------------------------- GPIO Init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* Configure GPIO17 and GPIO18 as outputs (open-drain + pull-up). */
    if (gpioSetMode(GPIO_A, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GPIO_A);
        return -1;
    }
    if (gpioSetMode(GPIO_B, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GPIO_B);
        return -1;
    }

    /* Enable internal pull-up resistors (open-drain style). */
    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", GPIO_A);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", GPIO_B);
        return -1;
    }

    /* Drive both lines LOW (idle state). */
    if (gpioWrite(GPIO_A, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", GPIO_A);
        return -1;
    }
    if (gpioWrite(GPIO_B, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", GPIO_B);
        return -1;
    }

    return 0;
}

/* ----------------------------- Encoder Read ------------------------------ */
/*
 * Reads the 2-bit quadrature state of the TMAG5110A1 sensors.
 * Returns 0 on success, -1 on GPIO error.
 */
static int read_encoder(int *out_state)
{
    int a = gpioRead(GPIO_A);
    int b = gpioRead(GPIO_B);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error: GPIO read failed (A=%d, B=%d).\n", a, b);
        return -1;
    }

    /* TMAG5110A1 is open-drain: LOW = magnet present, HIGH = no magnet. */
    *out_state = ((a == 0) << 1) | (b == 0);
    return 0;
}

/* ----------------------------- Angle Calc ------------------------------- */
static double calculate_angle(int state)
{
    /* 2-bit state: 00, 01, 10, 11  -> 0°, 45°, 135°, 225° */
    return ((double)state / 3.0) * 360.0;
}

/* ----------------------------- Log Position ------------------------------ */
static int log_position(double angle)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    int      current_state = 0;
    int      previous_state = 0;
    double   angle          = 0.0;

    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO. */
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started.  GPIO A=%d, GPIO B=%d.  Press Ctrl+C to exit.\n",
           GPIO_A, GPIO_B);

    /* Main loop: poll encoder state and log position changes. */
    while (g_running) {
        if (read_encoder(&current_state) != 0) {
            /* GPIO error: back off briefly and retry. */
            gpioDelay(100000); /* 100 ms */
            continue;
        }

        /* Detect state transitions. */
        if (current_state != previous_state) {
            angle = calculate_angle(current_state);

            if (log_position(angle) != 0) {
                fprintf(stderr, "Warning: failed to log position.\n");
            }

            previous_state = current_state;
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

