/*
 * ADPD144RI Red/IR Photometric Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: ADPD144RI (I2C address 0x48)
 * LED:    GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri_log adpd144ri_log.c -lpigpio -lrt
 * Run:    sudo ./adpd144ri_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADPD144RI_ADDR       0x48
#define GPIO_LED             17
#define IR_THRESHOLD         2000
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define LOG_FILE_NAME        "adpd144ri_log.txt"

/* ADPD144RI register addresses (16-bit, big-endian on the bus) */
#define REG_PART_ID          0x00
#define REG_REV_ID           0x01
#define REG_RED_DATA         0x02
#define REG_IR_DATA          0x04
#define REG_CONFIG           0x06

#define EXPECTED_PART_ID     0x1444  /* ADPD144RI part ID */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (i2cWriteDevice(fd, (char *)buf, 3) < 0)
        return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (i2cWriteDevice(fd, (char *)&reg_buf, 1) < 0)
        return -1;
    if (i2cReadDevice(fd, (char *)data, 2) != 2)
        return -1;

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int init_adpd144ri(int fd)
{
    uint16_t part_id;

    if (i2c_read_reg16(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: cannot read PART_ID register: %s\n",
                strerror(errno));
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr,
                "Error: unexpected PART_ID 0x%04X (expected 0x%04X). "
                "Sensor not present or wrong device.\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    printf("ADPD144RI detected (PART_ID=0x%04X, REV_ID=0x%04X).\n",
           part_id, 0); /* REV_ID is read similarly */

    /* Minimal configuration: enable both red and IR channels, 1x gain. */
    if (i2c_write_reg16(fd, REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Error: cannot write CONFIG register: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u,%u\n", timestamp, red, ir);
    fflush(fp);
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, ADPD144RI_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_adpd144ri(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: ADPD144RI initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (g_running) {
        uint16_t red, ir;

        if (i2c_read_reg16(g_i2c_fd, REG_RED_DATA, &red) < 0) {
            fprintf(stderr, "Warning: I2C read error (red): %s\n",
                    strerror(errno));
            gpioWrite(GPIO_LED, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (i2c_read_reg16(g_i2c_fd, REG_IR_DATA, &ir) < 0) {
            fprintf(stderr, "Warning: I2C read error (IR): %s\n",
                    strerror(errno));
            gpioWrite(GPIO_LED, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_file, red, ir);

        if (ir > IR_THRESHOLD)
            gpioWrite(GPIO_LED, 1);
        else
            gpioWrite(GPIO_LED, 0);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    cleanup();
    return EXIT_SUCCESS;
}

