#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x48
#define GPIO_CHIP       "gpiochip4"
#define LED_PIN         17
#define THRESHOLD       2000
#define LOG_FILE        "adpd144ri_log.txt"
#define SAMPLE_DELAY_MS 100

/* ADPD144RI register addresses (16-bit, big-endian on the bus) */
#define REG_PART_ID      0x00
#define REG_REV_ID       0x01
#define REG_HW_ID        0x02
#define REG_SEQ_ID       0x03
#define REG_INT_CFG      0x04
#define REG_INT_EN       0x05
#define REG_INT_STATUS   0x06
#define REG_DATA_CFG     0x07
#define REG_DATA_OUT     0x08
#define REG_COMMAND      0x0A
#define REG_RESPONSE     0x0B

#define CMD_RESET        0x01
#define CMD_START        0x02
#define CMD_STOP         0x03
#define CMD_READ_DATA    0x04

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int adpd144ri_init(int fd) {
    uint16_t part_id;
    if (i2c_read_reg16(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x1444) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%04X (expected 0x1444)\n", part_id);
        return -1;
    }
    if (i2c_write_reg16(fd, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg16(fd, REG_COMMAND, CMD_START) < 0) {
        fprintf(stderr, "Error: Failed to start sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir) {
    uint16_t data;
    if (i2c_read_reg16(fd, REG_DATA_OUT, &data) < 0) {
        fprintf(stderr, "Error: Failed to read DATA_OUT: %s\n", strerror(errno));
        return -1;
    }
    *red = data & 0x07FF;
    *ir  = (data >> 11) & 0x07FF;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADPD144RI initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Error: Failed to request LED line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (read_sensor_data(i2c_fd, &red, &ir) == 0) {
            log_data(log_fp, red, ir);
