#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *filename, int level) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set GAIN_SELECT_PIN LOW to select 60 dB gain */
    if (gpioWrite(GAIN_SELECT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    int last_level = 0;

    while (program_running) {
        int level = gpioRead(AUDIO_INPUT_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", AUDIO_INPUT_PIN);
            break;
        }

        /* Detect rising edge: transition from LOW to HIGH */
        if (level == 1 && last_level == 0) {
            if (log_event(LOG_FILE, level) != 0) {
                fprintf(stderr, "Failed to log event\n");
                break;
            }
        }

        last_level = level;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();

    printf("Audio monitoring stopped.\n");
    return EXIT_SUCCESS;
}

