#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000  /* 1 s */
#define READ_BYTES     3
#define CRC_POLY       0x31
#define CRC_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Open the log file once and keep it open for the program lifetime     */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    /* Write CSV header only if file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_uL_min\n");
        fflush(g_log_file);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 3-byte measurement frame from the SLF3S-4000B               */
/* Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[READ_BYTES];

    if (i2cWriteByte(handle, 0x36) != 0) {  /* soft-reset command */
        fprintf(stderr, "[ERROR] i2cWriteByte(0x36) failed\n");
        return -1;
    }
    gpioDelay(1000);  /* command processing time */

    int n = i2cReadDevice(handle, (char *)buf, READ_BYTES);
    if (n != READ_BYTES) {
        fprintf(stderr, "[ERROR] i2cReadDevice: got %d of %d bytes\n",
                n, READ_BYTES);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 1000.0f;  /* SLF3S-4000B: 1 LSB = 1 uL/min */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row                                                    */
/* ------------------------------------------------------------------ */
static void log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, flow_rate);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    if (open_log_file() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-4000B on I2C bus %d, addr 0x%02X. "
           "Logging to %s. Press Ctrl-C to stop.\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        float flow_rate;
        int rc = read_flow_rate(g_i2c_handle, &flow_rate);

        if (rc == 0) {
            log_flow_rate(g_log_file, flow_rate);
            printf("Flow rate: %.2f uL/min\n", flow_rate);
        } else if (rc == -2) {
            /* CRC error: skip this sample, keep running */
            fprintf(stderr, "[WARN] CRC error, skipping sample\n");
        } else {
            /* I/O error: attempt recovery on next iteration */
            fprintf(stderr, "[WARN] I2C read error, will retry next cycle\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

