#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5

/* MICS-VZ-89TE register addresses (16-bit, big-endian on the bus) */
#define REG_PART_ID    0x00
#define REG_REV_ID     0x01
#define REG_SEQ_ID     0x02
#define REG_INT_CFG    0x03
#define REG_INT_STATUS 0x04
#define REG_DATA       0x05
#define REG_COMMAND    0x06

#define CMD_RESET      0x01
#define CMD_READ_DATA  0x03

#define TVOC_MASK      0x0000
#define ECO2_MASK      0x0001

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val)
{
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0)
        return -1;
    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;
    *val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2)
{
    uint16_t part_id = 0;

    if (i2c_read_reg16(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != 0x89) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%04X (expected 0x89).\n", part_id);
        return -1;
    }

    if (i2c_write_reg16(handle, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Error: failed to send reset command.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset settling */

    if (i2c_write_reg16(handle, REG_COMMAND, CMD_READ_DATA) != 0) {
        fprintf(stderr, "Error: failed to trigger read-data command.\n");
        return -1;
    }

    gpioDelay(20000); /* 20 ms conversion time */

    if (i2c_read_reg16(handle, REG_DATA, tvoc) != 0) {
        fprintf(stderr, "Error: failed to read TVOC register.\n");
        return -1;
    }
    if (i2c_read_reg16(handle, REG_DATA, eco2) != 0) {
        fprintf(stderr, "Error: failed to read eCO2 register.\n");
        return -1;
    }

    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2)
{
    /* Simplified linear IAQ model: higher TVOC + eCO2 = worse air quality */
    return (float)tvoc + (float)eco2;
}

static void log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%u,%u\n", ts, iaq, tvoc, eco2);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(g_log_file);
    }

    printf("MICS-VZ-89TE air quality monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t tvoc = 0, eco2 = 0;

        if (read_sensor_data(g_i2c_handle, &tvoc, &eco2) == 0) {
            float iaq = calculate_iaq(tvoc, eco2);
            log_data(g_log_file, iaq, tvoc, eco2);
            printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f\n", tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Warning: sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    if (g_log_file != NULL)
        fclose(g_log_file);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

