            if (elapsed >= INTRUSION_THRESHOLD_S) {
                printf("Intrusion detected! Sensor touched for %d seconds.\n", elapsed);
                fflush(stdout);
                start_time = current_time;
            }
        } else {
            start_time = current_time;
        }

        struct timespec sleep_ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");
    return ret;
}

