#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 2
#define BUFFER_SIZE 1024
#define FILENAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int line) {
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "1");
    if (write(fd, buf, len) < 0) {
        perror("gpio export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int line, const char *dir) {
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char path[64];
    int plen = snprintf(path, sizeof(path), "/line%d", line);
    if (plen < 0 || (size_t)plen >= sizeof(path)) {
        fprintf(stderr, "Path too long\n");
        close(fd);
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%s %s", dir, path);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "Buffer too small\n");
        close(fd);
        return -1;
    }
    if (write(fd, buf, len) < 0) {
        perror("gpio set direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int line, int value) {
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        perror("open gpiochip");
        return -1;
    }
    char path[64];
    int plen = snprintf(path, sizeof(path), "/line%d", line);
    if (plen < 0 || (size_t)plen >= sizeof(path)) {
        fprintf(stderr, "Path too long\n");
        close(fd);
        return -1;
    }
    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%s %d", path, value);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "Buffer too small\n");
        close(fd);
        return -1;
    }
    if (write(fd, buf, len) < 0) {
        perror("gpio set value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int init_i2s(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open I2S device");
        return -1;
    }
    int format = AF_FORMAT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        perror("set format");
        close(fd);
        return -1;
    }
    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        perror("set channels");
        close(fd);
        return -1;
    }
    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        perror("set rate");
        close(fd);
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: requested %d Hz, got %d Hz\n", SAMPLE_RATE, rate);
    }
    return fd;
}

static int read_audio(int fd, short *buffer, int num_samples) {
    int bytes = num_samples * sizeof(short);
    ssize_t n = read(fd, buffer, bytes);
    if (n < 0) {
        perror("read audio");
        return -1;
    }
    if ((size_t)n != bytes) {
        fprintf(stderr, "Short read: got %zd, expected %d\n", n, bytes);
        return -1;
    }
    return 0;
}

static int write_audio_file(const char *filename, const short *buffer, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen audio file");
        return -1;
    }
    size_t written = fwrite(buffer, sizeof(short), num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Short write: wrote %zu, expected %d\n", written, num_samples);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose audio file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpio_export(GPIO_LINE) < 0) {
        return 1;
    }
    if (gpio_set_direction(GPIO_LINE, "output") < 0) {
        return 1;
    }
    if (gpio_set_value(GPIO_LINE, 0) < 0) {
        return 1;
    }

    int fd = init_i2s();
    if (fd < 0) {
        gpio_set_value(GPIO_LINE, 0);
        return 1;
    }

    short *buffer = malloc(BUFFER_SIZE * sizeof(short));
    if (!buffer) {
        perror("malloc");
        close(fd);
        gpio_set_value(GPIO_LINE, 0);
        return 1;
    }

    printf("Capturing audio. Press Ctrl+C to stop.\n");

    while (running) {
        if (gpio_set_value(GPIO_LINE, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO value\n");
            break;
        }
        if (read_audio(fd, buffer, BUFFER_SIZE) < 0) {
            fprintf(stderr, "Read error, continuing\n");
            continue;
        }
        if (write_audio_file(FILENAME, buffer, BUFFER_SIZE) < 0) {
            fprintf(stderr, "Write error, continuing\n");
        }
    }

    free(buffer);
    close(fd);
    gpio_set_value(GPIO_LINE, 0);
    printf("\nAudio capture stopped.\n");
    return 0;
}

