#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define SENSOR_TIMEOUT_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file);
    }
    printf("%s - %s\n", timestamp, event_type);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM to 0\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor pin\n");
        return -1;
    }
    return value;
}

static void control_fan(int state) {
    if (state == 1) {
        if (gpioPWM(FAN_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error starting fan PWM\n");
        }
    } else {
        if (gpioPWM(FAN_PIN, 0) != 0) {
            fprintf(stderr, "Error stopping fan PWM\n");
        }
    }
}

static void cleanup(void) {
    control_fan(0);
    gpioWrite(FLAME_SENSOR_PIN, 0);
    gpioTerminate();
    if (log_file != NULL) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Program started");

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    int last_stable_state = 0;
    uint32_t last_debounce_time = 0;
    int sensor_timeout_count = 0;

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            sensor_timeout_count++;
            if (sensor_timeout_count > 10) {
                log_event("Sensor read timeout - sensor absent or wiring fault");
                break;
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        sensor_timeout_count = 0;

        uint32_t current_time = gpioTick();
        if (current_time == 0) {
            current_time = 1;
        }

        if (sensor_value != last_stable_state) {
            last_debounce_time = current_time;
        }

        if ((current_time - last_debounce_time) > DEBOUNCE_DELAY_US) {
            if (sensor_value != last_stable_state) {
                last_stable_state = sensor_value;
            }
        }

        if (last_stable_state == 0) {
            log_event("Flame detected");
            control_fan(1);
        } else {
            control_fan(0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

