#define LOG_FILE         "radar_data.log"
#define FRAME_SIZE       32768
#define HEATMAP_BYTES    32768
#define NUM_FRAMES       10
#define MAX_FRAME_DELAY  100000

#define MAGIC_WORD       0x4144

typedef struct {
    float start_freq;
    float end_freq;
    int   num_chirps;
    int   num_samples;
} radar_config_t;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_init(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int gpio_init(void) {
    if (gpioSetMode(FRAME_TRIGGER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FRAME_TRIGGER);
        return -1;
    }
    if (gpioSetMode(DATA_READY, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", DATA_READY);
        return -1;
    }
    if (gpioWrite(FRAME_TRIGGER, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", FRAME_TRIGGER);
        return -1;
    }
    return 0;
}

static int log_header(FILE *f, const radar_config_t *cfg) {
    uint32_t magic = MAGIC_WORD;
    uint64_t ts = (uint64_t)time(NULL);
    uint32_t cfg_hash = (uint32_t)(uintptr_t)cfg;
    uint32_t num_frames = NUM_FRAMES;
    uint32_t frame_delay = MAX_FRAME_DELAY;

    if (fwrite(&magic, sizeof(magic), 1, f) != 1) return -1;
    if (fwrite(&ts, sizeof(ts), 1, f) != 1) return -1;
    if (fwrite(&cfg_hash, sizeof(cfg_hash), 1, f) != 1) return -1;
    if (fwrite(&num_frames, sizeof(num_frames), 1, f) != 1) return -1;
    if (fwrite(&frame_delay, sizeof(frame_delay), 1, f) != 1) return -1;
    if (fwrite(&cfg->start_freq, sizeof(cfg->start_freq), 1, f) != 1) return -1;
    if (fwrite(&cfg->end_freq, sizeof(cfg->end_freq), 1) != 1) return -1;
    if (fwrite(&cfg->num_chirps, sizeof(cfg->num_chirps), 1, f) != 1) return -1;
    if (fwrite(&cfg->num_samples, sizeof(cfg->num_samples), 1, f) != 1) return -1;
    return 0;
}

static int log_frame(FILE *f, uint32_t frame_num, uint64_t timestamp) {
    uint32_t magic = MAGIC_WORD;
    if (fwrite(&magic, sizeof(magic), 1, f) != 1) return -1;
    if (fwrite(&timestamp, sizeof(timestamp), 1, f) != 1) return -1;
    if (fwrite(&frame_num, sizeof(frame_num), 1, f) != 1) return -1;
    return 0;
}

static int read_frame(uint8_t *data, int len) {
    int bytes_read = spiRead(spi_handle, (char *)data, len);
    if (bytes_read != len) {
        fprintf(stderr, "SPI read error: expected %d bytes, got %d\n", len, bytes_read);
        return -1;
    }
    return 0;
}

static int process_frame(const uint8_t *data, int len, uint64_t timestamp) {
    printf("Frame %d: %d bytes, timestamp: %llu\n", 0, len, (unsigned long long)timestamp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpio_init() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    radar_config_t config = {
        .start_freq = 77.0f,
        .end_freq   = 79.0f,
        .num_chirps = 64,
        .num_samples = 256
    };

    if (log_header(log_file, &config) != 0) {
        fprintf(stderr, "Error writing log header\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t *frame_data = malloc(HEATMAP_BYTES);
    if (!frame_data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint32_t frame_num = 0;
    uint64_t timestamp = 0;
    int ready = 0;

    while (!terminate) {
        if (gpioWrite(FRAME_TRIGGER, 1) != 0) {
            fprintf(stderr, "Error setting trigger high\n");
            break;
        }
        gpioDelay(1000);
        if (gpioWrite(FRAME_TRIGGER, 0) != 0) {
            fprintf(stderr, "Error setting trigger low\n");
            break;
        }

        ready = 0;
        for (int i = 0; i < 100 && !terminate; i++) {
            if (gpioRead(DATA_READY) == 1) {
                ready = 1;
                break;
            }
            gpioDelay(1000);
        }

        if (!ready) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue;
        }

        timestamp = (uint64_t)time(NULL);
        if (read_frame(frame_data, HEATMAP_BYTES) != 0) {
            fprintf(stderr, "Frame read failed\n");
            continue;
        }

        if (process_frame(frame_data, HEATMAP_BYTES, timestamp) != 0) {
            fprintf(stderr, "Frame processing failed\n");
        }

        if (log_frame(log_file, frame_num, timestamp) != 0) {
            fprintf(stderr, "Error writing frame header\n");
            break;
        }
        frame_num++;

        gpioDelay(MAX_FRAME_DELAY);
    }

    free(frame_data);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

