#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE_NAME "flame_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int get_iso8601_timestamp(char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_flame_event(const char *timestamp, int state) {
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int last_state = -1;
    int current_state;
    char timestamp[32];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d\n", FLAME_SENSOR_GPIO);
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    while (program_running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_flame_event(timestamp, current_state) != 0) {
                    fprintf(stderr, "Failed to log flame event\n");
                } else {
                    printf("Flame detected: %s\n", timestamp);
                }
            } else {
                fprintf(stderr, "Failed to generate timestamp\n");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return EXIT_SUCCESS;
}

