#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x48
#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

/* OPT3001 register addresses */
#define REG_RESULT 0x00
#define REG_CONFIG 0x01

/* Configuration: continuous conversion, automatic range, no interrupt */
#define CONFIG_VALUE 0x0000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(int handle) {
    char buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF;
    buf[2] = CONFIG_VALUE & 0xFF;

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing config to OPT3001\n");
        return -1;
    }
    return 0;
}

static int read_lux(int handle, float *lux_out) {
    char reg = REG_RESULT;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error selecting result register\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading result register\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    /* Clear RNV (range valid) bit to check conversion status */
    if (raw & 0x0002) {
        fprintf(stderr, "OPT3001 conversion not complete\n");
        return -1;
    }

    /* Lux = raw / 1.2 */
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, OPT3001_ADDR, i2c_handle);
