    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, OPT3001_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_config(i2c_handle) != 0) {
        fprintf(stderr, "Failed to configure OPT3001. Check wiring and sensor presence.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

