                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                    gpioDelay(10000);
                }
            }
        }

        if (success) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

