/*
 * SainSmart IR Flame Detection Sensor Module reader for Raspberry Pi 3 B+
 * Uses the Linux GPIO Character Device (gpiod) v2 API.
 *
 * Wiring:
 *   - Sensor DOUT  -> GPIO17 (BCM 17, physical pin 11)
 *   - Sensor VCC   -> 3.3 V (physical pin 1)
 *   - Sensor GND   -> GND  (physical pin 9)
 *   - Sensor OUT   -> 3.3 V (physical pin 1) or GND (physical pin 9)
 *
 * The sensor DOUT line is active-low: it reads 0 when a flame is
 * detected and 1 when no flame is present.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 *
 * Run:
 *   ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO controller on Pi 3 B+ */
#define GPIO_LINE_OFFSET 17           /* BCM 17 */
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Print a timestamped flame status line to stdout                     */
/* ------------------------------------------------------------------ */
static void log_flame_status(int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s Flame Detected: %s\n", timestamp,
           (value == 0) ? "YES" : "NO");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure the line as input with pull-up bias ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* ---- Configure the specific line offset ---- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, GPIO_LINE_OFFSET, 1,
                                            settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request the line with consumer label ---- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value failed: %s\n",
                    strerror(errno));
            /* Brief pause before retrying to avoid log flooding */
            sleep(1);
            continue;
        }

        log_flame_status(value);
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL)
        gpiod_line_request_release(request);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

