#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown on Ctrl+C / terminate */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure the eight TTP226 OUT pins as inputs with pull-down resistors */
    const int pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Main sampling loop */
    while (g_running) {
        int levels[NUM_CHANNELS];
        int rc = gpioReads(pins, NUM_CHANNELS, levels);

        if (rc != 0) {
            fprintf(stderr, "Error: gpioReads failed (rc=%d).\n", rc);
            break;
        }

        printf("[%+d ms] ", (int)(gpioTick() / 1000));
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d", i + 1, levels[i]);
            if (i < NUM_CHANNELS - 1) {
                putchar(' ');
            }
        }
        putchar('\n');
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: invoke the library's API function during teardown */
    gpioTerminate();
    return EXIT_SUCCESS;
}

