/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 29)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND  (physical pin 9)
 *   (External pull-up resistors required on the sensor OUT pins.)
 *
 * The TMAG5110 output is open-drain; with pull-ups, an unasserted
 * output reads HIGH and a magnet-detected assertion reads LOW.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown (Ctrl+C)                          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin.  Returns 1 (HIGH), 0 (LOW), or -1 on error.     */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (rc=%d)\n",
                gpio, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio driver ---------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs ------------------------------ */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Enable internal pull-ups (external pull-ups also present) --- */
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n",
                SENSOR1_GPIO);
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n",
                SENSOR2_GPIO);
    }

    /* --- Install signal handler for clean shutdown ------------------ */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Sensor 1: BCM GPIO%d | Sensor 2: BCM GPIO%d\n",
           SENSOR1_GPIO, SENSOR2_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);

        if (s1 >= 0) {
            printf("Sensor 1 (GPIO%d): %s\n",
                   SENSOR1_GPIO, s1 ? "HIGH" : "LOW");
        } else {
            printf("Sensor 1 (GPIO%d): READ ERROR\n", SENSOR1_GPIO);
        }

        if (s2 >= 0) {
            printf("Sensor 2 (GPIO%d): %s\n",
                   SENSOR2_GPIO, s2 ? "HIGH" : "LOW");
        } else {
            printf("Sensor 2 (GPIO%d): READ ERROR\n", SENSOR2_GPIO);
        }

        printf("---\n");
        fflush(stdout);

        /* Sleep 500 ms; pigpio's gpioDelay is non-busy (microseconds) */
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

