 *   GND  -> GND (pin 6)
 *   OUT1 -> BCM 2  (physical pin 3)
 *   OUT2 -> BCM 3  (physical pin 5)
 *   OUT3 -> BCM 4  (physical pin 7)
 *   OUT4 -> BCM 17 (physical pin 11)
 *   OUT5 -> BCM 27 (physical pin 13)
 *   OUT6 -> BCM 22 (physical pin 15)
 *   OUT7 -> BCM 10 (physical pin 19)
 *   OUT8 -> BCM 9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lpigpio -lrt
 * Run:    sudo ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define TIMESTAMP_LEN 32

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tmv);
}

static void log_data(const int states[NUM_CHANNELS])
{
    char ts[TIMESTAMP_LEN];
    get_timestamp(ts, sizeof(ts));
    printf("%s,%d,%d,%d,%d,%d,%d,%d\n",
           ts,
           states[0], states[1], states[2], states[3],
           states[4], states[5], states[6], states[7]);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup_lines(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioGetMode(touch_pins[i]) == PI_INPUT) {
            gpioSetMode(touch_pins[i], PI_INPUT);
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* --- configure touch pins as inputs ----------------------------- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM %d: %s\n",
                    touch_pins[i], strerror(errno));
            cleanup_lines();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* Disable pull-up/pull-down so the sensor drives the line. */
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Warning: gpioSetPullUpDown failed for BCM %d: %s\n",
                    touch_pins[i], strerror(errno));
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    printf("Timestamp,CH1,CH2,CH3,CH4,CH5,CH6,CH7,CH8\n");
    fflush(stdout);

    /* --- main polling loop ------------------------------------------ */
    while (g_running) {
        int states[NUM_CHANNELS];
        int read_failed = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpioRead(touch_pins[i]);
            if (v < 0) {
                fprintf(stderr, "Error: gpioRead failed for BCM %d: %s\n",
                        touch_pins[i], strerror(errno));
                read_failed = 1;
                break;
            }
            states[i] = v;
        }

        if (read_failed) {
            /* Brief pause to avoid log flooding on a bus error. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        log_data(states);
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup_lines();
    gpioTerminate();
    return EXIT_SUCCESS;
}

