#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4          /* BCM pin 7 */
#define POLL_DELAY_US    100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int rc;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with internal pull-up --- */
    rc = gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d (code %d).\n",
                TILT_SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO%d (code %d).\n",
                TILT_SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    int prev_state = -1;   /* force initial log */

    while (g_running) {
        int level = gpioRead(TILT_SENSOR_GPIO);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO%d (code %d).\n",
                    TILT_SENSOR_GPIO, level);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (level != prev_state) {
            if (level == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            prev_state = level;
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

