#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0 0x24
#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_UVINDEX0 0x26
#define SI1145_REG_UVINDEX1 0x27
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE 0x20
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_PART_ID_VAL 0x45

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != SI1145_PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Error writing RESET command: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_UCOEF0, 0x77) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF5, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF8, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF9, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF10, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF11, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF12, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF13, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF14, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF15, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF16, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF17, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF18, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF19, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF20, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF21, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF22, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF23, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF24, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF25, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF26, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF27, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF28, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF29, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF30, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_UCOEF31, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, 0x0F) < 0) {
        fprintf(stderr, "Error writing ALS_FORCE command: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    return 0;
}

static int read_si1145_data(int fd, float *uv_index, uint16_t *als_visible) {
    uint8_t resp;
    if (i2c_read_reg8(fd, SI1145_REG_RESPONSE, &resp) < 0) {
        fprintf(stderr, "Error reading RESPONSE register: %s\n", strerror(errno));
        return -1;
    }
    if (resp != 0x0F) {
        fprintf(stderr, "Unexpected RESPONSE value: 0x%02X\n", resp);
        return -1;
    }

    if (i2c_read_reg16(fd, SI1145_REG_UVINDEX0, (uint16_t *)uv_index) < 0) {
        fprintf(stderr, "Error reading UV index: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, als_visible) < 0) {
        fprintf(stderr, "Error reading ALS visible data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void log_data(FILE *fp, float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing Si1145 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
        fflush(log_file);
    }

    while (running) {
        float uv_index;
        uint16_t als_visible;

        if (read_si1145_data(i2c_fd, &uv_index, &als_visible) == 0) {
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
            log_data(log_file, uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

