#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define SENSOR1_ADDR     0x60
#define SENSOR2_ADDR     0x61
#define ALARM_GPIO       17
#define FLOW_THRESHOLD   0.5f
#define LOG_FILE         "flow_log.txt"
#define START_CMD        0x3608
#define MEASURE_CMD      0x3608
#define MEAS_DELAY_US    100000
#define LOOP_DELAY_US    1000000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("I2C read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out)
{
    uint8_t buf[3];

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_data(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 1000.0f;
    return 0;
}

static void log_data(FILE *fp, float f1, float f2, float avg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Sensor1: %.3f ml/min, Sensor2: %.3f ml/min, Average: %.3f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2, avg);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("ioctl SENSOR1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("ioctl SENSOR2");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_cmd(g_i2c_fd, START_CMD) < 0) {
        log_error(g_log_fp, "Failed to start sensors");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(100000);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int   v1 = 0, v2 = 0;

        if (read_flow_rate(g_i2c_fd, &f1) == 0) {
            v1 = 1;
        } else {
            log_error(g_log_fp, "Sensor 1 read failed");
        }

        if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
            perror("ioctl SENSOR2");
            log_error(g_log_fp, "I2C slave switch failed");
            v2 = 0;
        } else if (read_flow_rate(g_i2c_fd, &f2) == 0) {
            v2 = 1;
        } else {
            log_error(g_log_fp, "Sensor 2 read failed");
        }

        if (v1 + v2 > 0) {
            float avg = (v1 ? f1 : 0.0f) + (v2 ? f2 : 0.0f);
            if (v1 && v2) avg /= 2.0f;

            log_data(g_log_fp, f1, f2, avg);

            if (avg < FLOW_THRESHOLD) {
                gpioWrite(ALARM_GPIO, 1);
            } else {
                gpioWrite(ALARM_GPIO, 0);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    log_error(g_log_fp, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

