#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int    obstacle_detected;
} ObstacleEvent;

static ObstacleEvent event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: set flag only                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a detection record to the circular buffer                    */
/* ------------------------------------------------------------------ */
static void log_event(time_t ts, int detected)
{
    event_buffer[buffer_index].timestamp   = ts;
    event_buffer[buffer_index].obstacle_detected = detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ------------------------------------------------------------------ */
/* Dump the buffer contents in chronological order                     */
/* ------------------------------------------------------------------ */
static void dump_buffer(void)
{
    printf("\n--- Obstacle Detection Log (sorted) ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;

        if (localtime_r(&event_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "unknown");
        }

        printf("[%s] Obstacle %s\n",
               time_str,
               event_buffer[idx].obstacle_detected ? "DETECTED" : "clear");
    }
    printf("--- End of Log ---\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio driver ---------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pin as input with pull-up ---------------- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown -------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    fflush(stdout);

    /* --- Main polling loop ------------------------------------------ */
    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-033 drives LOW when an obstacle is detected */
        int detected = (level == 0) ? 1 : 0;

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time()");
        } else {
            log_event(now, detected);
            if (detected) {
                printf("Obstacle detected!\n");
                fflush(stdout);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    dump_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

