#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x10
#define D7S_REG_MODE   0x00
#define D7S_REG_XL     0x04
#define D7S_REG_XH     0x05
#define D7S_REG_YL     0x06
#define D7S_REG_YH     0x07
#define D7S_REG_ZL     0x08
#define D7S_REG_ZH     0x09
#define D7S_MODE_ACTIVE 0x01
#define D7S_MODE_SLEEP  0x00
#define CSV_FILE       "fan_health.csv"
#define POLL_DELAY_MS  500
#define ACTIVATION_MS  1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_byte(fd, D7S_REG_MODE, D7S_MODE_SLEEP) < 0)
        return -1;
    usleep(10000);
    if (i2c_write_byte(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0)
        return -1;
    usleep(1000000);
    return 0;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t d[6];
    if (i2c_read_block(fd, D7S_REG_XL, d, 6) < 0)
        return -1;
    *x = (int16_t)((d[1] << 8) | d[0]);
    *y = (int16_t)((d[3] << 8) | d[2]);
    *z = (int16_t)((d[5] << 8) | d[4]);
    return 0;
}

static int csv_write_header(FILE *fp) {
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
        return -1;
    }
    long sz = ftell(fp);
    if (sz < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (sz == 0) {
        if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            return -1;
        }
        fflush(fp);
    }
    return 0;
}

static void timestamp_iso(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00+0000");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tmv);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", D7S_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (d7s_init(fd) < 0) {
        fprintf(stderr, "D7S initialization failed.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    if (csv_write_header(fp) < 0) {
        fclose(fp);
        close(fd);
        return 1;
    }

    printf("D7S vibration sensor logging to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (g_running) {
        usleep(100000);
        if (i2c_write_byte(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0) {
            fprintf(stderr, "Failed to set active mode; retrying.\n");
            continue;
        }
        usleep(1000000);

        int active = 0;
        for (int i = 0; i < ACTIVATION_MS / POLL_DELAY_MS && g_running; i++) {
            uint8_t mode;
            if (i2c_read_block(fd, D7S_REG_MODE, &mode, 1) < 0) {
                fprintf(stderr, "Failed to read mode; retrying.\n");
                continue;
            }
            if ((mode & D7S_MODE_ACTIVE) != 0) {
                active = 1;
                break;
            }
            usleep(POLL_DELAY_MS * 1000);
        }

        if (!active) {
            fprintf(stderr, "D7S did not become active within %d ms.\n", ACTIVATION_MS);
            break;
        }

        int16_t x, y, z;
        if (d7s_read_xyz(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read XYZ data; retrying.\n");
            continue;
        }

        char ts[32];
        timestamp_iso(ts, sizeof(ts));
        if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
            fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        } else {
            fflush(fp);
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    return 0;
}

