#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_CONFIRMATION_TIME 2
#define LOG_FILE "stall_log.txt"
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"
#define TIMESTAMP_BUFFER_SIZE 32

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int is_stall_confirmed(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

static int log_stall_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp != NULL) {
        char buffer[TIMESTAMP_BUFFER_SIZE];
        char line[256];
        int found = 0;
        while (fgets(line, sizeof(line), fp) != NULL) {
            if (strncmp(line, timestamp, TIMESTAMP_BUFFER_SIZE) == 0) {
                found = 1;
                break;
            }
        }
        fclose(fp);
        if (found) {
            return 0;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int get_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp_buffer, buffer_size, TIMESTAMP_FORMAT, timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (is_stall_confirmed(sensor1_value, sensor2_value)) {
            char timestamp[TIMESTAMP_BUFFER_SIZE];
            if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                printf("Stall confirmed at: %s\n", timestamp);

                if (log_stall_event(timestamp) != 0) {
                    fprintf(stderr, "Failed to log stall event\n");
                }
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }

            gpioDelay(STALL_CONFIRMATION_TIME * 1000000);
        } else {
            gpioDelay(100000);
        }
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return EXIT_SUCCESS;
}

