/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO 2 (I2C bus 1 SDA, pin 3)
 *   TMAG5170 SCL  -> GPIO 3 (I2C bus 1 SCL, pin 5)
 *   TMAG5170 VDD  -> 3.3 V (pin 1)
 *   TMAG5170 GND  -> GND   (pin 6)
 *   TMAG5170 XOUT -> (unused; sensor provides digital data over I2C)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_log mag_log.c -lti-damw -lm
 * Run:    ./mag_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#include <ti/damw/ti_damw.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x60          /* TMAG5170 default 7-bit I2C address */
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_PERIOD_US 100000      /* 100 ms */

/* TMAG5170 register addresses */
#define REG_DEVICE_CONFIG 0x00
#define REG_SENSOR_CONFIG 0x01
#define REG_XOUT_L        0x02
#define REG_XOUT_H        0x03
#define REG_YOUT_L        0x04
#define REG_YOUT_H        0x05
#define REG_ZOUT_L        0x06
#define REG_ZOUT_H        0x07

/* Device configuration: continuous conversion, 50 mT range, 1 kHz ODR */
#define DEV_CFG_VAL      0x0000

/* Sensor configuration: enable X, Y, Z axes, 50 mT range */
#define SENSOR_CFG_VAL   0x0FFF

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        ti_damw_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register (little-endian on wire)  */
/* ------------------------------------------------------------------ */
static int reg_write16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);          /* LSB first */
    buf[2] = (char)((value >> 8) & 0xFF);   /* MSB second */

    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register                        */
/* ------------------------------------------------------------------ */
static int reg_read16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)((uint8_t)data[0]) | ((uint16_t)((uint8_t)data[1]) << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TMAG5170 sensor                                      */
/* ------------------------------------------------------------------ */
static int sensor_init(int handle)
{
    if (reg_write16(handle, REG_DEVICE_CONFIG, DEV_CFG_VAL) < 0)
        return -1;
    if (reg_write16(handle, REG_SENSOR_CONFIG, SENSOR_CFG_VAL) < 0)
        return -1;

    /* Allow the sensor to settle after configuration */
    gpioDelay(10000);  /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetic field data (X, Y, Z)                                  */
/* ------------------------------------------------------------------ */
static int read_magnetic_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (reg_read16(handle, REG_XOUT_L, &x_raw) < 0) return -1;
    if (reg_read16(handle, REG_YOUT_L, &y_raw) < 0) return -1;
    if (reg_read16(handle, REG_ZOUT_L, &z_raw) < 0) return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV file                                                */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TMAG5170 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (sensor_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] TMAG5170 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "timestamp,x,y,z\n");
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "[WARN] fseek failed: %s\n", strerror(errno));
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");
    printf("Logging to: %s\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        if (read_magnetic_data(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

