    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (g_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            log_event("ERROR: Failed to read sensor, re-initializing GPIO in 60 seconds");
            sleep(REINIT_DELAY_SEC);
            continue;
        }

        if (sensor_value == 1) {
            printf("Water detected!\n");
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

