#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_PERIOD_S 1          /* seconds between logged samples */

/* ------------------------------------------------------------------ */
/* Shared state between the alert callback and the main thread        */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_pulse_count = 0;
static FILE                 *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — just flip the flag so the main loop can exit      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of SENSOR_PIN           */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {                       /* rising edge */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted in the last SAMPLE_PERIOD_S seconds*/
/* ------------------------------------------------------------------ */
static double calculate_rpm(uint32_t pulses)
{
    return (double)pulses * 60.0 / (double)SAMPLE_PERIOD_S;
}

/* ------------------------------------------------------------------ */
/* Append one timestamped RPM line to the log file and stdout          */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_fp != NULL) {
        if (fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        }
    }

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* pigpio cleanup — safe to call even if init failed                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input with pull-up --------------- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d) failed\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback on both edges -------------------- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    printf("Logging to %s\n", LOG_FILE);

    /* ---- Main sampling loop --------------------------------------- */
    while (g_running) {
        sleep(SAMPLE_PERIOD_S);

        if (!g_running) {
            break;
        }

        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        log_rpm(calculate_rpm(pulses));
    }

    /* ---- Graceful shutdown ---------------------------------------- */
    printf("\nShutting down...\n");

    /* Disable callback before tearing down pigpio */
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);

    cleanup();
    return EXIT_SUCCESS;
}

