    while (program_running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");

    /* Unregister interrupt handlers */
    gpioSetAlertFuncEx(SENSOR_A_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, NULL, NULL);

    /* Close log file */
    if (shared_state.log_file != NULL) {
        fclose(shared_state.log_file);
        shared_state.log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();

    pthread_mutex_destroy(&shared_state.mutex);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;

cleanup_all:
    if (shared_state.log_file != NULL) {
        fclose(shared_state.log_file);
        shared_state.log_file = NULL;
    }
    gpioTerminate();
cleanup_gpio:
    pthread_mutex_destroy(&shared_state.mutex);
    return EXIT_FAILURE;
}

