#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO          18
#define POLL_DELAY_US     50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", LED_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED state on GPIO%d", LED_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor monitoring started (GPIO%d input, GPIO%d output)", TOUCH_SENSOR_GPIO, LED_GPIO);

    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor on GPIO%d", TOUCH_SENSOR_GPIO);
        } else if (touch_state == 1) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                syslog(LOG_ERR, "Failed to turn on LED on GPIO%d", LED_GPIO);
            } else {
                syslog(LOG_INFO, "Touch detected on GPIO%d, LED on GPIO%d turned on", TOUCH_SENSOR_GPIO, LED_GPIO);
            }
        } else {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                syslog(LOG_ERR, "Failed to turn off LED on GPIO%d", LED_GPIO);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

