#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 17
#define LED_GPIO          18
#define DEBOUNCE_DELAY_US 50000  /* 50 ms in microseconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor line as input with rising-edge events --- */
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN);

    if (gpioSetAlertFunc(TOUCH_SENSOR_GPIO, touch_callback) != 0) {
        fprintf(stderr, "Error: failed to register alert function on GPIO %d.\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED line as output, initially LOW --- */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED GPIO %d LOW.\n", LED_GPIO);
        gpioSetAlertFunc(TOUCH_SENSOR_GPIO, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO%d. LED on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_GPIO, LED_GPIO);

    /* --- Main loop: sleep until signal received --- */
    while (g_running) {
        sleep(1);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");

    /* Disable event callback before tearing down */
    gpioSetAlertFunc(TOUCH_SENSOR_GPIO, NULL);

    /* Ensure LED is off */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED during shutdown.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    return EXIT_SUCCESS;
}

/* --- Alert callback: toggles LED on rising edge --- */
