#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22

#define BUFFER_SIZE 100
#define DEBOUNCE_US 50000  /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} Event;

static Event event_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;
static int overflow_count = 0;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

static void print_buffer(void) {
    printf("\n--- Event Log (%d entries, %d overflow) ---\n",
           buffer_count, overflow_count);
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_head;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        localtime_r(&event_buffer[idx].timestamp, &tm_info);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%d] Pin=%d  State=%d  Timestamp=%s\n",
               i, event_buffer[idx].sensor_pin,
               event_buffer[idx].state, time_str);
    }
    printf("--- End of Log ---\n");
}

static void add_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed\n");
        return;
    }

    Event ev;
    ev.sensor_pin = sensor_pin;
    ev.timestamp  = now;
    ev.state      = state;

    event_buffer[buffer_head] = ev;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        overflow_count++;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED1 state\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED2 state\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Sensor 1: GPIO%d | Sensor 2: GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("  LED 1:    GPIO%d | LED 2:    GPIO%d\n", LED_1_PIN, LED_2_PIN);
    printf("  Buffer:   %d entries | Debounce: %d us\n",
           BUFFER_SIZE, DEBOUNCE_US);
    printf("Press Ctrl+C to exit.\n");

    int prev_s1 = gpioRead(SENSOR_1_PIN);
    int prev_s2 = gpioRead(SENSOR_2_PIN);
    if (prev_s1 < 0 || prev_s2 < 0) {
        fprintf(stderr, "Error: initial gpioRead failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d s2=%d)\n", s1, s2);
            break;
        }

        if (s1 != prev_s1) {
            if (s1 == 1) {
                gpioWrite(LED_1_PIN, 1);
                add_event(SENSOR_1_PIN, 1);
            } else {
                gpioWrite(LED_1_PIN, 0);
                add_event(SENSOR_1_PIN, 0);
            }
            prev_s1 = s1;
        }

        if (s2 != prev_s2) {
            if (s2 == 1) {
                gpioWrite(LED_2_PIN, 1);
                add_event(SENSOR_2_PIN, 1);
            } else {
                gpioWrite(LED_2_PIN, 0);
                add_event(SENSOR_2_PIN, 0);
            }
            prev_s2 = s2;
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    print_buffer();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

