#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to the log file.                       */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (g_log_fp == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (fprintf(g_log_fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with internal pull-up --- */
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Allow pull-up to settle --- */
    gpioDelay(100000);  /* 100 ms */

    /* --- Read initial state --- */
    int last_state = gpioRead(RAIN_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "gpioRead(%d) failed during initial read\n",
                RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log the initial state --- */
    if (log_event(last_state == 0 ? "Rain Detected" : "No Rain") != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           RAIN_SENSOR_GPIO);

    /* --- Main polling loop --- */
    while (g_running) {
        int current_state = gpioRead(RAIN_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", RAIN_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                printf("Rain Detected\n");
                log_event("Rain Detected");
            } else {
                printf("No Rain\n");
                log_event("No Rain");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

