                RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log the initial state --- */
    if (log_event(last_state == 0 ? "Rain Detected" : "No Rain") != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           RAIN_SENSOR_GPIO);

    /* --- Main polling loop --- */
    while (g_running) {
        int current_state = gpioRead(RAIN_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", RAIN_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                printf("Rain Detected\n");
                log_event("Rain Detected");
            } else {
                printf("No Rain\n");
                log_event("No Rain");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

