/*
 * Raspberry Pi 4 Model B – Si1182 I2C optical sensor reader
 *
 * Reads heart-rate (HR) and SpO2 data from a Silicon Labs Si1182 sensor
 * on I2C bus 1, logs each reading to biometric_log.txt, and exits
 * cleanly on SIGINT (Ctrl-C).
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_log si1182_log.c -li2c
 * Run:    ./si1182_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <i2c.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60          /* Si1182 default 7-bit I2C address */
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */

/* ------------------------------------------------------------------ */
/* Globals for signal-handler cleanup                                 */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits and cleans up         */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately      */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int heart_rate, int spo2)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n",
                timestamp, heart_rate, spo2) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from a Si1182 register             */
/* ------------------------------------------------------------------ */
static int read_si1182_word(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (i2c_read_device(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the I2C bus ---- */
    g_i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2c_open(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2c_close(g_i2c_handle);
        g_i2c_handle = -1;
        return EXIT_FAILURE;
    }

    printf("Si1182 logging started.  Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t hr_raw, spo2_raw;

        if (read_si1182_word(g_i2c_handle, 0x00, &hr_raw) != 0) {
            /* Skip this sample but keep running */
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (read_si1182_word(g_i2c_handle, 0x02, &spo2_raw) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        log_data(g_log_file, (int)hr_raw, (int)spo2_raw);
        printf("HR: %d BPM, SpO2: %d%%\n", (int)hr_raw, (int)spo2_raw);

        sleep(SAMPLE_PERIOD);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2c_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

