#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27
#define LOG_FILE     "bridge_integrity.log"
#define POLL_DELAY_US 100000   /* 100 ms */
#define ALARM_THRESHOLD_S 2    /* 2 seconds */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped line to the log file.                */
/* ------------------------------------------------------------------ */
static void log_event(const char *event_type, int sensor1, int sensor2)
{
    time_t now;
    struct tm tm_info;
    char ts[32];

    time(&now);
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s - %s - Sensor1: %d, Sensor2: %d\n",
                ts, event_type, sensor1, sensor2);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Activate the alarm (active-high).                                  */
/* ------------------------------------------------------------------ */
static void activate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set alarm pin HIGH\n");
    }
}

/* ------------------------------------------------------------------ */
/* Deactivate the alarm.                                              */
/* ------------------------------------------------------------------ */
static void deactivate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set alarm pin LOW\n");
    }
}

/* ------------------------------------------------------------------ */
/* Read a tilt sensor via the pigpio API.                              */
/* Returns 0 or 1 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_tilt_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n", pin, v);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;
    int alarm_active = 0;
    time_t alarm_start = 0;
    int last_s1 = -1, last_s2 = -1;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (rc=%d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs with pull-down ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor pin %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor pin %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm pin as output, initial LOW ---- */
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for alarm pin %d\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    deactivate_alarm();

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started", -1, -1);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = read_tilt_sensor(SENSOR_1_PIN);
        int s2 = read_tilt_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — log and keep alarm in safe state */
            deactivate_alarm();
            log_event("Sensor read error", s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Tilt-start event */
        if (s1 == 1 || s2 == 1) {
            if (last_s1 == 0 && last_s2 == 0) {
                log_event("Tilt start", s1, s2);
            }
        }

        /* Threshold exceeded — alarm on */
        if (s1 == 1 || s2 == 1) {
            if (!alarm_active) {
                activate_alarm();
                alarm_active = 1;
                alarm_start = time(NULL);
                log_event("Alarm activated", s1, s2);
            }
        }

        /* Tilt-end event */
        if (s1 == 0 && s2 == 0) {
            if (last_s1 == 1 || last_s2 == 1) {
                log_event("Tilt end", s1, s2);
            }
        }

        /* Deactivate alarm when both sensors return LOW */
        if (s1 == 0 && s2 == 0 && alarm_active) {
            deactivate_alarm();
            alarm_active = 0;
            log_event("Alarm deactivated", s1, s2);
        }

        last_s1 = s1;
        last_s2 = s2;

        /* Check if one sensor has been HIGH for the threshold duration */
        if (alarm_active) {
            if (s1 == 1) {
                if (difftime(time(NULL), alarm_start) >= ALARM_THRESHOLD_S) {
                    log_event("Threshold exceeded (Sensor1)", s1, s2);
                }
            } else if (s2 == 1) {
                if (difftime(time(NULL), alarm_start) >= ALARM_THRESHOLD_S) {
                    log_event("Threshold exceeded (Sensor2)", s1, s2);
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    log_event("Program stopped", -1, -1);
    deactivate_alarm();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

