/*
 * seismic.c — Omron D7S-A0011 seismic sensor monitor for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -o seismic seismic.c -lm -lrt
 * Run:    ./seismic
 *
 * Wiring:
 *   D7S-A0011 SDA  -> GPIO2  (BCM 2, I2C bus 1)
 *   D7S-A0011 SCL  -> GPIO3  (BCM 3, I2C bus 1)
 *   Alert LED anode -> GPIO17 (BCM 17) via ~330 Ω resistor
 *   D7S-A0011 VCC  -> 3.3 V
 *   D7S-A0011 GND  -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x50          /* D7S-A0011 default 7-bit address   */
#define ALERT_LED_GPIO       17
#define VIBRATION_THRESHOLD  500.0f        /* raw magnitude threshold          */
#define POLL_INTERVAL_US     100000        /* 100 ms                            */
#define ALERT_PULSE_US       1000000       /* 1 s LED pulse                     */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register addresses (16-bit, big-endian on the bus) */
#define REG_CTRL1            0x00
#define REG_CTRL2            0x01
#define REG_STATUS           0x02
#define REG_VIB_X_MSB        0x03
#define REG_VIB_X_LSB        0x04
#define REG_VIB_Y_MSB        0x05
#define REG_VIB_Y_LSB        0x06
#define REG_VIB_Z_MSB        0x07
#define REG_VIB_Z_LSB        0x08

/* CTRL1 bit fields */
#define CTRL1_PD             0x01          /* power-down / standby             */
#define CTRL1_MODE           0x02          /* measurement mode                */

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_reg16(uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg, uint16_t *out)
{
    char wbuf[1] = { (char)reg };
    char rbuf[2];

    if (i2cWriteDevice(i2c_handle, wbuf, 1) < 0)
        return -1;
    if (i2cReadDevice(i2c_handle, rbuf, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int init_sensor(void)
{
    uint16_t ctrl1;

    /* Verify sensor presence by reading CTRL1 */
    if (i2c_read_reg16(REG_CTRL1, &ctrl1) < 0) {
        fprintf(stderr, "Error: D7S-A0011 not responding on I2C bus %d addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit and set measurement mode */
    ctrl1 &= ~CTRL1_PD;
    ctrl1 |=  CTRL1_MODE;
    if (i2c_write_reg16(REG_CTRL1, ctrl1) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1\n");
        return -1;
    }

    /* Read back and confirm */
    if (i2c_read_reg16(REG_CTRL1, &ctrl1) < 0) {
        fprintf(stderr, "Error: failed to read back CTRL1\n");
        return -1;
    }
    if ((ctrl1 & CTRL1_PD) != 0 || (ctrl1 & ~CTRL1_MODE) != 0) {
        fprintf(stderr, "Error: sensor did not accept init configuration\n");
        return -1;
    }

    printf("D7S-A0011 initialised (CTRL1=0x%04X). Measurement mode active.\n", ctrl1);
    return 0;
}

/* --------------------------- Read vibration ------------------------------ */
static int read_vibration(float *x, float *y, float *z)
{
    uint16_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (i2c_read_reg16(REG_VIB_X_MSB, &x_msb) < 0) return -1;
    if (i2c_read_reg16(REG_VIB_X_LSB, &x_lsb) < 0) return -1;
    if (i2c_read_reg16(REG_VIB_Y_MSB, &y_msb) < 0) return -1;
    if (i2c_read_reg16(REG_VIB_Y_LSB, &y_lsb) < 0) return -1;
    if (i2c_read_reg16(REG_VIB_Z_MSB, &z_msb) < 0) return -1;
    if (i2c_read_reg16(REG_VIB_Z_LSB, &z_lsb) < 0) return -1;

    *x = (float)((int16_t)((x_msb << 8) | x_lsb));
    *y = (float)((int16_t)((y_msb << 8) | y_lsb));
    *z = (float)((int16_t)((z_msb << 8) | z_lsb));
    return 0;
}

/* --------------------------- Threshold check ----------------------------- */
static int check_threshold(float x, float y, float z, float threshold)
{
    float mag = sqrtf(x * x + y * y + z * z);
    return (mag > threshold);
}

/* --------------------------- Logging ------------------------------------- */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, magnitude);
    fflush(log_file);
    printf("[%s] Event: magnitude=%.2f\n", timestamp, magnitude);
}

/* --------------------------- Alert LED ----------------------------------- */
static void trigger_alert(void)
{
    gpioWrite(ALERT_LED_GPIO, 1);
    gpioDelay(ALERT_PULSE_US);
    gpioWrite(ALERT_LED_GPIO, 0);
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_LED_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    float x, y, z, magnitude;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_sensor() < 0) {
        fprintf(stderr, "Error: sensor initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- GPIO setup --- */
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_LED_GPIO, 0);

    printf("Seismic monitor running. Threshold=%.0f, poll=%d ms, alert=%d s\n",
           VIBRATION_THRESHOLD, POLL_INTERVAL_US / 1000, ALERT_PULSE_US / 1000000);

    /* --- Main loop --- */
    while (!terminate) {
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_vibration(&x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Warning: I2C read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000); /* 10 ms back-off */
        }

        if (!ok) {
            fprintf(stderr, "Error: sensor read failed after %d attempts; retrying in 1 s\n",
                    MAX_RETRIES);
            gpioDelay(1000000);
            continue;
        }

        if (check_threshold(x, y, z, VIBRATION_THRESHOLD)) {
            magnitude = sqrtf(x * x + y * y + z * z);
            log_event(magnitude);
            trigger_alert();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

