/*
 * flame_monitor.c — KY-026 flame sensor monitor for Raspberry Pi 3 Model B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Wiring (KY-026 digital OUT -> BCM GPIO):
 *   Sensor 1 -> GPIO 2 (pin 3)
 *   Sensor 2 -> GPIO 3 (pin 5)
 *   Sensor 3 -> GPIO 4 (pin 7)
 *   Sensor 4 -> GPIO 17 (pin 11)
 *   Sensor 5 -> GPIO 27 (pin 13)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS   5
#define LOG_FILE      "/var/log/flame_events.log"
#define POLL_INTERVAL_US 1000000   /* 1 second  */
#define DEBOUNCE_MS    50
#define CHIP_NAME      "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    int fd = fileno(fp);
    if (fd < 0) {
        syslog(LOG_ERR, "fileno() failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX): %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor %d (GPIO %u): %s\n",
                ts, sensor_id, sensor_pins[sensor_id - 1], message) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
    }

    if (flock(fd, LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN): %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitor (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    int lines_acquired = 0;
    int lines_requested = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_acquired++;
        lines_requested++;
    }

    syslog(LOG_INFO, "Monitoring %d flame sensors on %s",
           NUM_SENSORS, CHIP_NAME);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        goto cleanup;
    }

    int prev_state[NUM_SENSORS];
    int cur_state[NUM_SENSORS];

    for (int i = 0; i < NUM_SENSORS; i++) {
        prev_state[i] = gpiod_line_get_value(lines[i]);
        if (prev_state[i] < 0) {
