/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   TTP226 OUT0..OUT7  -> BCM GPIO 5, 6, 13, 19, 26, 12, 16, 20
 *   TTP226 VCC        -> 3.3 V (pin 1)
 *   TTP226 GND        -> GND   (pin 9)
 *   TTP226 A0         -> GND   (optional, selects channel 0 offset)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o ttp226 ttp226.c -lgpiod
 *
 * Run:
 *   ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

/* BCM GPIO numbers for OUT0..OUT7 */
static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        printf("[unknown-time] ");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        printf("[unknown-time] ");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        printf("[unknown-time] ");
        return;
    }
    printf("%s ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk bulk;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve the eight touch lines */
    gpiod_line_bulk_init(&bulk);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&bulk, lines[i]);
    }

    /* Request all lines as inputs in a single bulk request */
    if (gpiod_line_request_bulk_input(&bulk, "ttp226-touch") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Read initial states */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read initial value on GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_states[i] = val;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u (pin %u): %s\n",
                        touch_pins[i], touch_pins[i], strerror(errno));
                goto cleanup;
            }

            if (val != prev_states[i]) {
                print_timestamp();
                printf("Channel %d (BCM %u): %s\n",
                       i, touch_pins[i],
                       val ? "TOUCHED" : "released");
                fflush(stdout);
                prev_states[i] = val;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (chip != NULL) {
        gpiod_line_release_bulk(&bulk);
        gpiod_chip_close(chip);
    }
    return ret;
}

