code:
/*
 * Adaptive grow light controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - VEML7700 ambient light sensor on I2C bus 1 (address 0x48)
 *   - Grow light LED on GPIO18 (BCM), hardware PWM at 1000 Hz
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o grow_light grow_light.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VEML7700_ADDR        0x48
#define VEML7700_ALS_CONF    0x00
#define VEML7700_ALS_DATA    0x04
#define PWM_GPIO             18
#define PWM_FREQUENCY        1000   /* Hz */
#define PWM_RANGE            100    /* duty 0-100 */
#define SAMPLE_INTERVAL_S    1
#define LOG_FILE             "grow_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static int   init_i2c(void);
static int   init_pwm(void);
static int   read_lux(int *lux_out);
static int   set_brightness(int lux);
static int   log_data(int lux, int brightness, int error_code);
static void  cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, VEML7700_ADDR, strerror(errno));
        return -1;
    }

    /* VEML7700 ALS_CONF: power on, 1x gain, 100 ms integration, no shutdown */
    if (i2cWriteWordData(g_i2c_handle, VEML7700_ALS_CONF, 0x0001) < 0) {
        fprintf(stderr, "Error configuring VEML7700: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- PWM init ----------------------------------- */
static int init_pwm(void)
{
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                PWM_GPIO, strerror(errno));
        return -1;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n",
                PWM_GPIO, strerror(errno));
        return -1;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n",
                PWM_GPIO, strerror(errno));
        return -1;
    }

    /* Start with LED off */
    if (gpioPWM(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Error setting initial PWM duty on GPIO %d: %s\n",
                PWM_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- Lux read ----------------------------------- */
static int read_lux(int *lux_out)
{
    if (lux_out == NULL) {
        return -1;
    }

    int raw = i2cReadWordData(g_i2c_handle, VEML7700_ALS_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading VEML7700 ALS data: %s\n", strerror(errno));
        return -1;
    }

    /* Clear the ALS_CONF bit (bit 0) to get the 16-bit raw value */
    raw &= 0xFFFF;

    /* VEML7700 resolution: ~0.23 lux per LSB at 1x gain */
    *lux_out = (int)(raw * 0.23);
    return 0;
}

/* ----------------------------- Brightness set ----------------------------- */
static int set_brightness(int lux)
{
    int duty;

    if (lux < 100) {
        duty = 100;
    } else if (lux < 500) {
        duty = 75;
    } else if (lux < 1000) {
        duty = 50;
    } else {
        duty = 25;
    }

    if (gpioPWM(PWM_GPIO, duty) < 0) {
        fprintf(stderr, "Error setting PWM duty on GPIO %d: %s\n",
                PWM_GPIO, strerror(errno));
        return -1;
    }

    return duty;
}

/* ----------------------------- Log write ---------------------------------- */
static int log_data(int lux, int brightness, int error_code)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Lux: %d, Brightness: %d, Error: %d\n",
                timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    /* Turn off LED before closing resources */
    if (g_i2c_handle >= 0) {
        gpioPWM(PWM_GPIO, 0);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    struct sigaction sa;

    /* Install signal handlers for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
