#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define POLL_INTERVAL_US 50000

static const unsigned int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_lines[NUM_CHANNELS];
    struct gpiod_line *led_line = NULL;
    int prev_state[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = NULL;
        prev_state[i] = 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!touch_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed\n", touch_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_input_flags(touch_lines[i], "ttp226-touch",
                                            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
            fprintf(stderr, "gpiod_line_request_input_flags(%u) failed\n", touch_pins[i]);
            goto cleanup;
        }
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(LED_PIN)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "ttp226-led", 0) < 0) {
        perror("gpiod_line_request_output(LED_PIN)");
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(touch_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u) failed\n", touch_pins[i]);
                goto cleanup;
            }

            if (val == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) == 0) {
                    printf("Channel %d touched\n", i + 1);
                }
                any_touched = 1;
            }
            prev_state[i] = val;
        }

        if (gpiod_line_set_value(led_line, any_touched) < 0) {
            perror("gpiod_line_set_value(led)");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (touch_lines[i]) {
            gpiod_line_release(touch_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

