#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define OPT3001_ADDR   0x48
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1.0   /* seconds between samples */
#define SETTLE_MS      100   /* ms after config write before reading */

/* OPT3001 register addresses (16-bit, big-endian on the bus) */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01

/* Config register bits (16-bit, big-endian on the bus) */
#define CFG_RANGE_0_1  (0x0000)  /* 0.1 lux range, 1 LSB = 0.01 lux */
#define CFG_MODE_CONT (0x0000)  /* Continuous conversion mode */
#define CFG_INT_EN    (0x0000)  /* Interrupt disabled */
#define CFG_DEFAULT   (CFG_RANGE_0_1 | CFG_MODE_CONT | CFG_INT_EN)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit big-endian value to a 16-bit register address.
 * pigpio i2cWriteWordData sends the address then the data word
 * (little-endian on the wire), so we must swap bytes first. */
static int opt3001_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    uint16_t swapped = ((value >> 8) & 0xFF) | ((value & 0xFF) << 8);
    int rc = i2cWriteWordData(handle, reg, swapped);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteWordData(reg=0x%04X, val=0x%04X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* Read a 16-bit big-endian value from a 16-bit register address.
 * pigpio i2cReadWordData returns a little-endian word, so we swap. */
static int opt3001_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint16_t swapped = ((rc >> 8) & 0xFF) | ((rc & 0xFF) << 8);
    *out = swapped;
    return 0;
}

/* Read the current lux value from the OPT3001.
 * Returns 0 on success and stores the lux value in *lux_out;
 * returns -1 on I2C error. */
static int opt3001_read_lux(int handle, float *lux_out)
{
    uint16_t raw;
    if (opt3001_read_reg16(handle, REG_RESULT, &raw) < 0)
        return -1;

    /* Result register: bits [15:12] = exponent, bits [11:0] = mantissa */
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * (0.01f * (float)(1 << exponent));
    return 0;
}

static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to %s failed: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush(%s) failed: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
