        }

        /* Sleep for the remainder of the sample period */
        double remaining = SAMPLE_PERIOD;
        while (remaining > 0.0 && g_running) {
            double chunk = (remaining > 0.2) ? 0.2 : remaining;
            time_sleep(chunk);
            remaining -= chunk;
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
