#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define LOG_FILE_NAME "touch_log.txt"
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit and clean up.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped event line to the log file.                   */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(FILE *fp, const char *event_type)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state = -1;   /* unknown initial state forces first read */
    int first_read = 1;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO4 as input with pull-down ---- */
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file in append mode ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO%d. "
           "Press Ctrl+C to exit.\n", TOUCH_SENSOR_GPIO);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int current_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (first_read) {
            last_state = current_state;
            first_read = 0;
        } else if (current_state != last_state) {
            if (current_state == 1) {
                if (log_event(g_log_file, "Touch Detected") != 0) {
                    fprintf(stderr, "Failed to log touch detection.\n");
                }
                printf("Touch Detected\n");
            } else {
                if (log_event(g_log_file, "Touch Released") != 0) {
                    fprintf(stderr, "Failed to log touch release.\n");
                }
                printf("Touch Released\n");
            }
            last_state = current_state;
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

