/*
 * Raspberry Pi Zero W – Sensirion SLF3S-1300F Liquid Flow Sensor monitor
 *
 * Wiring:
 *   Sensor SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   Sensor SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   Sensor VDD  -> 3.3 V (pin 1)
 *   Sensor GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o cooling_monitor cooling_monitor.c
 *
 * Run:
 *   ./cooling_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x48          /* SLF3S-1300F default I2C address */
#define LOG_FILE             "cooling_log.csv"
#define SAMPLE_INTERVAL_US   1000000       /* 1 second */
#define SENSOR_DELAY_US      2000          /* 2 ms command / conversion delay */
#define FLOW_MIN             0.0f
#define FLOW_MAX             100.0f
#define FLOW_INVALID         (-1.0f)

/* SLF3S-1300F: continuous measurement, mass flow rate, 3 bytes */
#define SENSOR_CMD_MSB       0x36
#define SENSOR_CMD_LSB       0x08

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- CRC-8 (Sensirion) --------------------------- */
/* Polynomial 0x31, initial value 0xFF, no reflection */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_open(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                bus, addr, strerror(errno));
        return -1;
    }
    return h;
}

static int i2c_write_cmd(int handle, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X%02X) failed: %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, (int)len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes, got %d: %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor read --------------------------------- */
/*
 * Returns:
 *   0  – success, flow_out set to ml/min
 *  -1  – I2C read error
 *  -2  – CRC mismatch
 *  -3  – flow out of plausible range
 */
static int read_sensor(int handle, float *flow_out)
{
    uint8_t buf[3];

    if (i2c_write_cmd(handle, SENSOR_CMD_MSB, SENSOR_CMD_LSB) != 0)
        return -1;

    gpioDelay(SENSOR_DELAY_US);

    if (i2c_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC covers the two data bytes */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch: calc=0x%02X recv=0x%02X\n",
                sensirion_crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    float flow = (float)raw / 1000.0f;   /* SLF3S-1300F: 1 ml/min = 1 count */

    if (flow < FLOW_MIN || flow > FLOW_MAX) {
        fprintf(stderr, "[WARN] Flow %.2f ml/min out of range [%.1f, %.1f]\n",
                flow, FLOW_MIN, FLOW_MAX);
        return -3;
    }

    *flow_out = flow;
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_data(FILE *fp, float flow, int status)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    const char *status_str;
    switch (status) {
        case 0:  status_str = "OK";    break;
        case -1: status_str = "ERROR"; break;
        case -2: status_str = "CRC_ERR"; break;
        case -3: status_str = "INVALID"; break;
        default: status_str = "UNKNOWN"; break;
    }

    fprintf(fp, "%s,%.2f,%d,%s\n", ts, flow, status, status_str);
    fflush(fp);
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2c_open(I2C_BUS, I2C_ADDR);
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file (append); write header if empty --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_file);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Coolant flow monitoring started.  Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        float flow = FLOW_INVALID;
        int status = read_sensor(g_i2c_handle, &flow);

        if (status == 0) {
            log_data(g_log_file, flow, 0);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed (status=%d)\n", status);
            log_data(g_log_file, FLOW_INVALID, status);

            /* Attempt I2C recovery */
            if (g_i2c_handle >= 0) {
                i2cClose(g_i2c_handle);
                g_i2c_handle = -1;
            }
            gpioDelay(100000);   /* 100 ms back-off */
            g_i2c_handle = i2c_open(I2C_BUS, I2C_ADDR);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

