#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE "path_log.csv"
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[3] = { LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN };
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Warning: gpioRead failed on pin %d.\n", pin);
        return -1;
    }
    return v;
}

static void log_data(FILE *fp, int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,left,middle,right\n") < 0) {
            fprintf(stderr, "Error: cannot write CSV header.\n");
            fclose(g_log_fp);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "Warning: fflush header failed.\n");
        }
    }

    while (g_running) {
        int left  = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Warning: sensor read error, skipping sample.\n");
        } else {
            log_data(g_log_fp, left, middle, right);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Warning: fclose failed on log file.\n");
        }
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

