/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 *   DO   -> GPIO17 (BCM, physical pin 11)
 * Buzzer : active buzzer, control line -> GPIO18 (BCM, physical pin 12)
 *
 * Build  : gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run    : ./flame_alert
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN  17
#define BUZZER_PIN        18
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_S 2
#define BUZZER_ON_MS      200
#define BUZZER_OFF_MS     100
#define LOG_MSG_LEN       128

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log, const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
