/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Sensors: 3x TMAG5110A1 (open-drain output, active-low when magnet present)
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1 latch output is open-drain: it pulls the line LOW
 * when a south pole (magnet) is present and releases it HIGH when the
 * magnet is removed.  This means that a rising edge on the GPIO line
 * indicates a magnet arrival and a falling edge indicates departure.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals for signal-handler access                                  */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped entry to the log file and stdout                 */
/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    if (fp) {
        fprintf(fp, "%s %s\n", ts, msg);
        fflush(fp);
    }
    printf("%s %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0/1 or -1 on error                       */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, strerror(errno));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pins[3] = { SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO };
    int prev[3] = { -1, -1, -1 };          /* -1 = uninitialized */
    int first_read[3] = { 1, 1, 1 };       /* treat first read as baseline */
    int i;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pins as inputs with pull-up ---- */
    for (i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(%d, INPUT) failed\n", pins[i]);
            goto cleanup;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d, UP) failed\n", pins[i]);
            goto cleanup;
        }
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, %d, %d.  Ctrl+C to exit.\n",
           SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO);

    /* ---- main polling loop ---- */
    while (g_running) {
        for (i = 0; i < 3; i++) {
            int v = read_sensor(pins[i]);
            if (v < 0) {
                /* sensor read error — log and keep going */
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "ERROR: sensor %d (GPIO%d) read failed",
                         i + 1, pins[i]);
                log_event(g_log_fp, msg);
                continue;
            }

            /* detect state change (rising = magnet arrives, falling = departs) */
            if (v != prev[i]) {
                if (first_read[i]) {
                    /* first read — record baseline, do not log */
                    prev[i] = v;
                    first_read[i] = 0;
                } else {
                    const char *state = (v == 1) ? "magnet_removed" : "magnet_present";
                    char msg[128];
                    snprintf(msg, sizeof(msg),
                             "Sensor %d (GPIO%d): %s",
                             i + 1, pins[i], state);
                    log_event(g_log_fp, msg);
                }
            }
            prev[i] = v;
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");

cleanup:
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

