/*
 * touch_counter.c — 8-channel TTP226 capacitive touch counter for Raspberry Pi Zero W
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 *
 * Wiring (TTP226 OUT1..OUT8 -> Pi BCM 5..12, VCC 3V3, GND GND):
 *   OUT1 -> BCM 5   OUT2 -> BCM 6   OUT3 -> BCM 7   OUT4 -> BCM 8
 *   OUT5 -> BCM 9   OUT6 -> BCM 10  OUT7 -> BCM 11  OUT8 -> BCM 12
 *   VCC  -> 3V3     GND -> GND
 *   Counter bits: bit0=BCM17, bit1=BCM18, bit2=BCM19, bit3=BCM20,
 *                 bit4=BCM21, bit5=BCM22, bit6=BCM23, bit7=BCM24
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define NUM_COUNTER_BITS 8
#define POLL_INTERVAL_MS 10
#define STABILIZE_DELAY_MS 200
#define LOG_FILE "touch_log.txt"

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_COUNTER_BITS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_touch_event(int channel, int counter_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static void print_touch_event(int channel, int counter_value)
{
    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_COUNTER_BITS];
    int prev_counter = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = NULL;
        counter_lines[i] = NULL;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire touch sensor input lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!touch_lines[i]) {
            fprintf(stderr, "Failed to get touch line BCM %u: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(touch_lines[i], "touch_counter") < 0) {
            fprintf(stderr, "Failed to request touch line BCM %u as input: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Acquire counter output lines */
    for (int i = 0; i < NUM_COUNTER_BITS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "Failed to get counter line BCM %u: %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "Failed to request counter line BCM %u as output: %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Touch counter started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Allow sensors to stabilize after power-up */
    usleep(STABILIZE_DELAY_MS * 1000);

    /* Main polling loop */
    while (g_running) {
        int counter_value = 0;
        int error_occurred = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(touch_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading touch line BCM %u: %s\n", touch_pins[i], strerror(errno));
                error_occurred = 1;
                continue;
            }

            if (val == 1) {
                counter_value |= (1 << i);
            }
        }

        if (error_occurred) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (counter_value != 0 && counter_value != prev_counter) {
            prev_counter = counter_value;
            for (int i = 0; i < NUM_COUNTER_BITS; i++) {
                if (gpiod_line_set_value(counter_lines[i], (counter_value >> i) & 1) < 0) {
                    fprintf(stderr, "Error writing counter line BCM %u: %s\n", counter_pins[i], strerror(errno));
                }
            }
            log_touch_event(1 + (counter_value % NUM_CHANNELS), counter_value);
            print_touch_event(1 + (counter_value % NUM_CHANNELS), counter_value);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all counter outputs to 0 on exit */
    for (int i = 0; i < NUM_COUNTER_BITS; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
            gpiod_line_release(counter_lines[i]);
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (touch_lines[i]) {
            gpiod_line_release(touch_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

