static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_number) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
