            perror("gpiod_line_get_value failed for sensor 1");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }
        if (val2 < 0) {
            perror("gpiod_line_get_value failed for sensor 2");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val1 != prev1) {
            if (val1 == 0 && prev1 == 1) {
                log_event(1);
            }
            prev1 = val1;
        }

        if (val2 != prev2) {
            if (val2 == 0 && prev2 == 1) {
                log_event(2);
            }
            prev2 = val2;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("Tilt sensor monitoring stopped.\n");
    return ret;
}

