#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LED_PIN     22
#define LOG_FILE    "obstacle_log.csv"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a TCRT5000 reflectance channel (active-low: 0 = obstacle)     */
/* Returns 0 or 1 on success, -1 on read error.                        */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Drive the LED (1 = on, 0 = off)                                     */
/* ------------------------------------------------------------------ */
static void set_led(int on)
{
    int rc = gpioWrite(LED_PIN, on ? 1 : 0);
    if (rc < 0)
        fprintf(stderr, "gpioWrite failed on LED pin %d: %s\n",
                LED_PIN, pigpio_error(rc));
}

/* ------------------------------------------------------------------ */
/* Log one CSV row                                                    */
/* ------------------------------------------------------------------ */
static void log_sample(int s1, int s2, int led)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));

    if (fflush(g_log_fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    set_led(0);
    gpioTerminate();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for sensor 1 (pin %d)\n",
                SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for sensor 2 (pin %d)\n",
                SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for LED (pin %d)\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    set_led(0);

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,sensor1,sensor2,led_state\n");
        fflush(g_log_fp);
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Obstacle-avoidance system running.  Ctrl+C to exit.\n");
    printf("  Sensor 1: GPIO%d  |  Sensor 2: GPIO%d  |  LED: GPIO%d\n",
           SENSOR_1_PIN, SENSOR_2_PIN, LED_PIN);
    printf("  Logging to: %s\n", LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
        } else {
            /* Active-low: 0 = obstacle detected */
            int led = (s1 == 0 && s2 == 0) ? 1 : 0;
            set_led(led);
            log_sample(s1, s2, led);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

