#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN      4
#define LED_PIN      17
#define SAMPLE_US    125          /* 8 kHz sampling */
#define LED_ON_US    100000       /* 100 ms LED on */
#define POLL_DELAY   0.001        /* 1 ms between polls */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld", buf, ts.tv_nsec / 1000000L);
}

int main(void)
{
    /* --- pigpio init -------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ------------------------------------------ */
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input.\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_PIN %d LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICS-40180 sound peak detector running. Press Ctrl+C to exit.\n");

    /* --- main sampling loop ------------------------------------------ */
    while (g_running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on pin %d.\n", MIC_PIN);
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (level == 1) {
            print_timestamp_ms();
            printf(" - Sound peak detected!\n");
            fflush(stdout);

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite HIGH failed on LED_PIN %d.\n", LED_PIN);
            }
            gpioDelay(LED_ON_US);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite LOW failed on LED_PIN %d.\n", LED_PIN);
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- clean shutdown ---------------------------------------------- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

