#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* Si1175 I2C address (7-bit) */
#define SI1175_ADDR 0x60

/* Si1175 register addresses */
#define SI1175_REG_ALS_VIS_DATA0 0x14
#define SI1175_REG_ALS_VIS_DATA1 0x15

/* pigpio I2C handle */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single byte from a Si1175 register; returns 0 on success, -1 on error */
static int read_si1175_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* Read the 16-bit visible ALS data from the Si1175 */
static int read_als_data(int handle, uint16_t *als_data) {
    uint8_t lsb, msb;

    if (read_si1175_register(handle, SI1175_REG_ALS_VIS_DATA0, &lsb) != 0) {
        return -1;
    }
    if (read_si1175_register(handle, SI1175_REG_ALS_VIS_DATA1, &msb) != 0) {
        return -1;
    }

    *als_data = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1175 address */
    i2c_handle = i2cOpen(1, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (pigpio error %d).\n",
                SI1175_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    printf("Si1175 ALS sensor reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t als_data = 0;

        if (read_als_data(i2c_handle, &als_data) == 0) {
            printf("Raw ALS Data: %u\n", als_data);
        } else {
            fprintf(stderr, "Error: Failed to read ALS data from Si1175.\n");
        }

        /* Sleep for 100 ms using pigpio's microsecond delay */
        gpioDelay(100000);
    }

    /* Clean resource release on exit */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

