#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define LEFT_PIN   2
#define MIDDLE_PIN 3
#define RIGHT_PIN  4
#define POLL_MS    100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_line(int fd, unsigned int offset, int *value)
{
    struct gpiochip *chip = gpiochip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "gpiochip_open_by_number failed: %s\n", strerror(errno));
        return -1;
    }

    struct gpio_line *line = gpiochip_get_line(chip, offset);
    if (!line) {
        fprintf(stderr, "gpiochip_get_line(%u) failed: %s\n", offset, strerror(errno));
        gpiochip_close(chip);
        return -1;
    }

    int ret = gpio_get_value(line);
    gpio_line_release(line);
    gpiochip_close(chip);

    if (ret < 0) {
        fprintf(stderr, "gpio_get_value(%u) failed: %s\n", offset, strerror(errno));
        return -1;
    }

    *value = ret;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int left_fd = open("/dev/gpiochip0", O_RDWR);
    if (left_fd < 0) {
        perror("open /dev/gpiochip0");
        return EXIT_FAILURE;
    }

    int middle_fd = open("/dev/gpiochip0", O_RDWR);
    if (middle_fd < 0) {
        perror("open /dev/gpiochip0");
        close(left_fd);
        return EXIT_FAILURE;
    }

    int right_fd = open("/dev/gpiochip0", O_RDWR);
    if (right_fd < 0) {
        perror("open /dev/gpiochip0");
        close(left_fd);
        close(middle_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        int left_val, middle_val, right_val;
        int err = 0;

        if (read_line(left_fd, LEFT_PIN, &left_val) < 0) err = 1;
        if (read_line(middle_fd, MIDDLE_PIN, &middle_val) < 0) err = 1;
        if (read_line(right_fd, RIGHT_PIN, &right_val) < 0) err = 1;

        if (err) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_MS * 1000);
    }

    close(left_fd);
    close(middle_fd);
    close(right_fd);
    return EXIT_SUCCESS;
}

