/*
 * TTP226 8-channel capacitive touch sensor poller for Raspberry Pi 3 Model B+.
 *
 * Wiring (BCM numbering):
 *   TP1 -> GPIO5   TP2 -> GPIO6   TP3 -> GPIO13  TP4 -> GPIO19
 *   TP5 -> GPIO26  TP6 -> GPIO12  TP7 -> GPIO16  TP8 -> GPIO20
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_poll touch_poll.c -lrt
 * Run:    ./touch_poll   (Ctrl-C to exit)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200
#define CONSUMER_NAME "ttp226-poll"

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
    } else {
        printf("[?time?] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_acquired[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
        line_acquired[i] = 0;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], CONSUMER_NAME) < 0) {
            fprintf(stderr, "gpiod_line_request_input(%u): %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired[i] = 1;
    }

    printf("TTP226 touch sensor polling started. Press Ctrl-C to exit.\n");

    while (g_running) {
        int values[NUM_CHANNELS];
        int read_failed = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u): %s\n",
                        touch_pins[i], strerror(errno));
                read_failed = 1;
                break;
            }
            values[i] = v;
        }

        if (read_failed) {
            break;
        }

        print_timestamp();
        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        /* Sleep for the poll interval, but wake early on signal */
        for (int ms = 0; ms < POLL_INTERVAL_MS && g_running; ms += 10) {
            usleep(10 * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines in reverse order so indices match */
    for (int i = NUM_CHANNELS - 1; i >= 0; i--) {
        if (line_acquired[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

