#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define LED_PIN        17
#define RED_THRESHOLD  200
#define POLL_DELAY_MS  200

/* TCS34725 registers */
#define TCS34725_COMMAND_BIT  0x80
#define TCS34725_ENABLE       0x00
#define TCS34725_ATIME        0x01
#define TCS34725_ID           0x12
#define TCS34725_CDATAL        0x14
#define TCS34725_CDATAH        0x15
#define TCS34725_RDATAL        0x16
#define TCS34725_RDATAH        0x17
#define TCS34725_GDATAL        0x18
#define TCS34725_GDATAH        0x19
#define TCS34725_BDATAL        0x1A
#define TCS34725_BDATAH        0x1B

#define TCS34725_ENABLE_PON   0x01
#define TCS34725_ENABLE_AEN   0x02
#define TCS34725_ID_VALUE     0x44

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    uint8_t buf[2];
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 ID mismatch: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

static void control_led(struct gpiod_line *line, uint16_t red) {
    int val = (red > RED_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        tcs34725_powerdown(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        tcs34725_powerdown(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        tcs34725_powerdown(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Polling every %d ms. Press Ctrl+C to exit.\n", POLL_DELAY_MS);

    while (g_running) {
        uint16_t r, g, b, c;
        if (tcs34725_read(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Read failed, re-initializing sensor...\n");
            usleep(100000);
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed, retrying in 1 s...\n");
                sleep(1);
                continue;
            }
            continue;
        }

        control_led(led, r);
        printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    tcs34725_powerdown(fd);
    close(fd);
    return EXIT_SUCCESS;
}

static void tcs34725_powerdown(int fd) {
    (void)i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
}

