/*
 * Raspberry Pi 4 Model B – BH1750 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750FVI on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x23
 *   - WS2812B LED strip on GPIO18 (BCM 18, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            "/dev/i2c-1"
#define BH1750_ADDR        0x23
#define BH1750_PWR_ON      0x01
#define BH1750_RESET       0x07
#define BH1750_CONT_HRES   0x10   /* Continuous high-resolution mode (1 lux, ~120 ms) */
#define BH1750_MEASURE_MS  180    /* Max conversion time for high-res mode */

#define LED_COUNT          10
#define LED_GPIO           18     /* BCM 18 – hardware PWM0 */

#define PWM_FREQ_HZ        800000 /* 800 kHz – WS2812B timing */
#define PWM_DUTY_MAX       255    /* 8-bit resolution */

#define LOOP_DELAY_MS      100
#define MAX_RETRIES        3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* --------------------------- BH1750 -------------------------------------- */
static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_RESET)   < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;

    /* Wait for conversion to complete (high-res mode ~120 ms) */
    struct timespec ts = { 0, BH1750_MEASURE_MS * 1000000L };
    nanosleep(&ts, NULL);

    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) return -1;

    /* Convert raw ADC value to lux (high-resolution mode) */
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* --------------------------- WS2812B via hardware PWM --------------------- */
/*
 * WS2812B timing (800 kHz, 24-bit per LED):
 *   T0H = 0.4 µs, T0L = 0.8 µs
 *   T1H = 0.8 µs, T1L = 0.4 µs
 *   We use a 1 µs granularity and drive the line high/low for the required
 *   pulse widths using the hardware PWM peripheral on GPIO18.
 *
 * pigpio does not expose the raw PWM registers directly, so we use the
 * pigpio hardware PWM API (gpioHardwarePWM) to generate the bitstream.
 * This is more reliable and accurate than bit-banging the timing.
 */

/*
 * Encode one 24-bit RGB value into a pigpio hardware PWM pattern.
 * Each bit is represented by a 1 µs high pulse (1 = '1', 0 = '0').
 * The total pattern length is 24 bits × 2 pulses/edge × 1 µs = 48 µs.
 */
static void encode_led(uint8_t r, uint8_t g, uint8_t b,
                       uint32_t *pattern, int *pattern_len)
{
    int len = 0;
    for (int i = 23; i >= 0; i--) {
        uint8_t mask = (1u << i);
        if (r & mask) pattern[len++] = 1; else pattern[len++] = 0;
        if (g & mask) pattern[len++] = 1; else pattern[len++] = 0;
        if (b & mask) pattern[len++] = 1; else pattern[len++] = 0;
    }
}

/*
 * Send the encoded pattern to the WS2812B strip using pigpio hardware PWM.
 * We drive the line high for the pulse width, then low for the remainder
 * of the 1 µs period.  This is equivalent to the WS2812B timing.
 */
static void send_led_strip(uint32_t *pattern, int len)
{
    if (len == 0) return;

    /* Set PWM frequency to 800 kHz and duty cycle to 50 % */
    if (gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 128) < 0) {
        fprintf(stderr, "gpioHardwarePWM setup failed\n");
        return;
    }

    /* Send the bitstream: high for pulse width, low for remainder */
    for (int i = 0; i < len; i++) {
        if (pattern[i] == 1) {
            gpioDelay(1);                 /* 1 µs high */
            gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 255); /* full high */
        } else {
            gpioDelay(1);                 /* 1 µs low */
            gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 0);   /* full low */
        }
    }

    /* Ensure line is low after transmission */
    gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 0);
    gpioDelay(1);
}

/* --------------------------- Mapping -------------------------------------- */
static uint8_t map_lux_to_brightness(float lux)
{
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 1000.0f) lux = 1000.0f;

    /* Logarithmic mapping: 0 lux → 0, 1000 lux → 255 */
    float log_lux = log10f(lux + 1.0f);
    float norm = log_lux / log10f(1001.0f);
    return (uint8_t)(norm * 255.0f);
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize BH1750 */
    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialisation failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allocate WS2812B bitstream buffer */
    uint32_t *led_pattern = malloc((size_t)LED_COUNT * 24 * sizeof(uint32_t));
    if (!led_pattern) {
        fprintf(stderr, "Memory allocation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting BH1750 → WS2812B light-to-LED mapping. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float lux = 0.0f;
        bool read_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (bh1750_read_lux(g_i2c_fd, &lux) == 0) {
                read_ok = true;
                break;
            }
            fprintf(stderr, "BH1750 read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                struct timespec ts = { 0, 10000000L }; /* 10 ms back-off */
                nanosleep(&ts, NULL);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "BH1750 read failed after %d attempts; continuing\n", MAX_RETRIES);
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        uint8_t brightness = map_lux_to_brightness(lux);
        uint8_t r = brightness;
        uint8_t g = brightness;
        uint8_t b = brightness;

        encode_led(r, g, b, led_pattern, (int)led_pattern[0]);

        send_led_strip(led_pattern, (int)led_pattern[0]);

        printf("Lux: %.2f  Brightness: %u\n", lux, brightness);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioHardwarePWM(LED_GPIO, PWM_FREQ_HZ, 0);
    free(led_pattern);
    close(g_i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

