/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Hardware:
 *   - BH1750FVI on /dev/i2c-1, address 0x23 (ADDR pin tied to GND)
 *   - APA102 LED strip on /dev/spidev0.0 (SPI0, CE0), 800 kHz SPI clock
 *
 * Build:  gcc -O2 -Wall -o light_led light_led.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS            "/dev/i2c-1"
#define BH1750_ADDR        0x23
#define BH1750_PWR_ON      0x01
#define BH1750_RESET       0x07
#define BH1750_CONV_MS     120          /* max conversion time, ms            */
#define BH1750_CONV_US     (BH1750_CONV_MS * 1000)

#define SPI_DEVICE         "/dev/spidev0.0"
#define SPI_SPEED_HZ       1000000      /* 1 MHz – APA102 supports up to 1.6 MHz */
#define SPI_BITS           8
#define SPI_DELAY_US       0

#define NUM_LEDS           10
#define LED_BRIGHTNESS     0x1F         /* 0–31 → 0.0625 % of 255                 */
#define LED_BLUE           0x1F
#define LED_GREEN          0x1F
#define LED_RED            0x1F

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_spi_fd   = -1;

/* --------------------------- Forward declarations ------------------------ */

static void  signal_handler(int sig);
static int   init_i2c(void);
static int   init_spi(void);
static int   read_light_level(uint16_t *lux_out);
static void  set_led_color(uint8_t brightness, uint8_t blue,
                           uint8_t green, uint8_t red);
static void  send_apa102_frame(const uint8_t *frame, size_t len);
static void  cleanup(void);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ I2C init --------------------------------- */

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Power on and reset the sensor */
    uint8_t cmd;
    cmd = BH1750_PWR_ON;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 power-on write: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    usleep(10000);                       /* 10 ms settle                       */

    cmd = BH1750_RESET;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 reset write: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    usleep(10000);                       /* 10 ms settle                       */

    return 0;
}

/* ------------------------------ SPI init --------------------------------- */

static int init_spi(void)
{
    uint8_t mode  = SPI_MODE_0;
    uint8_t bits  = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* --------------------- Read BH1750 light level ---------------------------- */

static int read_light_level(uint16_t *lux_out)
{
    if (g_i2c_fd < 0) {
        fprintf(stderr, "I2C not initialised\n");
        return -1;
    }

    /* Trigger a one-time conversion (no wait needed, but we wait for safety) */
    uint8_t cmd = 0x10;                 /* CONTINUOUS_HIGH_RES_MODE */
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 trigger write: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_US);

    uint8_t buf[2];
    ssize_t n = read(g_i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *lux_out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* --------------------- Build & send APA102 frame -------------------------- */

static void set_led_color(uint8_t brightness, uint8_t blue,
                          uint8_t green, uint8_t red)
{
    uint8_t frame[NUM_LEDS * 4 + 4];
    size_t  idx = 0;

    /* Start frame: 32 zero bits */
    memset(&frame[idx], 0x00, 32);
    idx += 32;

    /* LED frames: B, G, R, fill */
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[idx++] = LED_BRIGHTNESS;          /* brightness (0–31)        */
        frame[idx++] = blue;                     /* blue                      */
        frame[idx++] = green;                    /* green                     */
        frame[idx++] = red;                      /* red                       */
    }

    /* End frame: 32 zero bits */
    memset(&frame[idx], 0x00, 32);
    idx += 32;

    send_apa102_frame(frame, idx);
}

static void send_apa102_frame(const uint8_t *frame, size_t len)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI not initialised\n");
        return;
    }

    size_t remaining = len;
    while (remaining > 0) {
        size_t chunk = (remaining > 4096) ? 4096 : remaining;
        ssize_t w = write(g_spi_fd, frame, chunk);
        if (w < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "SPI write: %s\n", strerror(errno));
            return;
        }
        remaining -= (size_t)w;
        frame += w;
    }
}

/* ------------------------------ Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        /* Turn off all LEDs (0 brightness) */
        uint8_t off[NUM_LEDS * 4 + 4];
        memset(off, 0x00, sizeof(off));
        send_apa102_frame(off, sizeof(off));
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------------- main ----------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Light sensor (BH1750) → LED strip (APA102) running. Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t lux = 0;
        if (read_light_level(&lux) < 0) {
            fprintf(stderr, "Light read error – continuing\n");
            usleep(100000);
            continue;
        }

        /* Scale 1–65535 lux to 0–31 brightness */
        float brightness = (float)lux / 65535.0f;
        if (brightness > 1.0f) brightness = 1.0f;
        if (brightness < 0.0f) brightness = 0.0f;

        uint8_t b = (uint8_t)(brightness * LED_BRIGHTNESS);
        set_led_color(b, LED_BLUE, LED_GREEN, LED_RED);

        printf("Lux: %5u  Brightness: %3u/31\n", lux, b);
        usleep(100000);                    /* 100 ms loop period              */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

