#define LED_GREEN          0x1F
#define LED_RED            0x1F

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_spi_fd   = -1;

/* --------------------------- Forward declarations ------------------------ */

static void  signal_handler(int sig);
