code:
/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light sensor → APA102 LED strip brightness control.
 *
 * Hardware:
 *   - Three BH1750FVI light sensors on I2C bus 1 (BCM pins 2/3 = SDA/SCL).
 *   - APA102 LED strip on hardware SPI (BCM GPIO10 = MOSI, BCM GPIO11 = SCLK).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lbcm2835 -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR_1        0x23
#define BH1750_ADDR_2        0x25
#define BH1750_ADDR_3        0x24
#define BH1750_CONV_MS       180          /* max conversion time (ms)          */
#define NUM_SENSORS          3
#define NUM_LEDS            100
#define SPI_BAUD            1000000      /* 1 MHz — well within APA102 spec      */
#define SPI_FLAGS           0            /* mode 0, active-low CE, 8 bits      */
#define FADE_MS             500          /* brightness fade duration (ms)     */
#define LOOP_DELAY_MS       100          /* main-loop delay (ms)              */
#define MAX_READ_ERRORS     5            /* consecutive errors before giving up */

/* APA102 timing (microseconds) */
#define APA102_T0H_US       1
#define APA102_T0L_US       1
#define APA102_T1H_US       1
#define APA102_T1L_US       1
#define APA102_RESET_US     60
#define APA102_EOH_US       1
#define APA102_EDL_US       1
#define APA102_BIT_US       1
#define APA102_NBITS        4
#define APA102_FRAME_US     (APA102_RESET_US + APA102_EOH_US + APA102_EDL_US + \
                            (NUM_LEDS * (APA102_RESET_US + APA102_NBITS * (APA102_T0H_US + APA102_T0L_US))) + 8)

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[NUM_SENSORS];
static int g_spi_handle = -1;
static int g_pigpio_inited = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_bh1750s(void);
static int  read_bh1750(int handle, uint16_t *out);
static int  init_apa102(void);
static void set_apa102_brightness(int brightness);
static void cleanup(void);
static void msleep(unsigned ms);

/* ----------------------------- Helpers ----------------------------------- */
static void msleep(unsigned ms)
{
    if (ms > 0) {
        gpioDelay(ms * 1000);          /* gpioDelay takes microseconds */
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        /* Turn off all LEDs (data line low) */
        unsigned char off[4] = {0, 0, 0, 0};
        for (int i = 0; i < NUM_LEDS; i++) {
            off[i * 4 + 0] = 0x00;
            off[i * 4 + 1] = 0x00;
            off[i * 4 + 2] = 0x00;
            off[i * 4 + 3] = 0x00;
        }
        if (spiWrite(g_spi_handle, (char *)off, NUM_LEDS * 4) < 0) {
            fprintf(stderr, "Warning: failed to write off frame during cleanup\n");
        }
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }

    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = 0;
    }
}

/* ----------------------------- BH1750 ------------------------------------ */
static int init_bh1750s(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_handles[i] = -1;
    }

    int addrs[NUM_SENSORS] = { BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_3 };

    for (int i = 0; i < NUM_SENSORS; i++) {
        int addr = addrs[i];
        g_i2c_handles[i] = i2cOpen(I2C_BUS, addr, 0);
        if (g_i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: i2cOpen failed for addr 0x%02X (err=%d)\n",
                    addr, g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
            continue;
        }
        /* Power on / reset command (0x01) */
        if (i2cWriteByte(g_i2c_handles[i], 0x01) < 0) {
            fprintf(stderr, "Warning: failed to power on BH1750 at 0x%02X\n", addr);
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    return 0;
}

static int read_bh1750(int handle, uint16_t *out)
{
    if (handle < 0 || out == NULL) {
        return -1;
    }

    /* BH1750 one-time high-resolution mode: issue measurement command, wait,
     * then read 2 bytes. */
    if (i2cWriteByte(handle, 0x10) < 0) {
        return -1;
    }
    msleep(BH1750_CONV_MS);

    char buf[2] = {0, 0};
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ----------------------------- APA102 ------------------------------------ */
static int init_apa102(void)
{
    /*
     * pigpio spiOpen drives the hardware SPI pins (GPIO10 = MOSI, GPIO11 = SCLK,
     * GPIO8  = CE0).  The APA102 LED strip expects the data line to be held low
     * during reset, then clocked out bit-by-bit, so we use mode 0 and 8-bit
     * words.
     */
    g_spi_handle = spiOpen(0, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (err=%d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static void set_apa102_brightness(int brightness)
{
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;

    unsigned char frame[NUM_LEDS * 4];
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[i * 4 + 0] = 0xE0 | (brightness << 1);   /* global brightness + B */
        frame[i * 4 + 1] = 0x00;                        /* R */
        frame[i * 4 + 2] = 0x00;                        /* G */
        frame[i * 4 + 3] = 0x00;                        /* blue (unused) */
    }

    /* APA102 requires an exact multiple of 4 bytes per frame, so pad if needed. */
    int len = NUM_LEDS * 4;
    if (len % 4 != 0) {
        len += 4 - (len % 4);
    }
    unsigned char *p = malloc(len);
    if (!p) {
        fprintf(stderr, "Error: malloc failed for APA102 frame\n");
        return;
    }
    memset(p, 0, len);
    memcpy(p, frame, NUM_LEDS * 4);

    int bytes = spiWrite(g_spi_handle, (char *)p, len);
    free(p);

    if (bytes < 0) {
        fprintf(stderr, "Error: spiWrite failed (err=%d)\n", bytes);
    } else if ((size_t)bytes != len) {
        fprintf(stderr, "Error: spiWrite short write (%d/%zu bytes)\n", bytes, len);
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = 1;

    if (init_bh1750s() != 0) {
        fprintf(stderr, "Warning: one or more BH1750 sensors not detected; "
                        "continuing with available sensors.\n");
    }

    if (init_apa102() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int valid_handles = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            valid_handles++;
        }
    }

    if (valid_handles == 0) {
        fprintf(stderr, "Error: no BH1750 sensors available; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t readings[NUM_SENSORS];
        int read_ok = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_i2c_handles[i] < 0) {
                continue;
            }
            if (read_bh1750(g_i2c_handles[i], &readings[i]) == 0) {
                read_ok++;
            } else {
                fprintf(stderr, "Warning: read failed on handle %d\n", g_i2c_handles[i]);
            }
        }

        if (read_ok == 0) {
            fprintf(stderr, "Warning: no valid sensor readings; skipping cycle.\n");
            msleep(LOOP_DELAY_MS);
            continue;
        }

        uint32_t sum = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
