#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define VEML7700_ADDR  0x29
#define VEML7700_CONF  0x00
#define VEML7700_ALS   0x04
#define ALS_GAIN_1X    0x00
#define ALS_INT_1024  0x08
#define ALS_PERS_1    0x00
#define ALS_MODE_CONT 0x00
#define NUM_LEDS      10
#define GPIO_PIN      18
#define GAMMA_TABLE_SIZE 256
#define MAX_RETRIES  3
#define RETRY_DELAY_US 100000
#define LOOP_DELAY_US  200000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_initialized = 0;

static uint8_t gamma_table[GAMMA_TABLE_SIZE];
static uint8_t led_data[NUM_LEDS * 3];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

static void generate_gamma_table(void) {
    for (int i = 0; i < GAMMA_TABLE_SIZE; i++) {
        float linear = (float)i / (GAMMA_TABLE_SIZE - 1);
        float gamma_corrected = 255.0f * powf(linear, 0.45f);
        gamma_table[i] = (uint8_t)(gamma_corrected + 0.5f);
    }
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = { reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int veml7700_init(int fd) {
    uint16_t conf = ALS_GAIN_1X | ALS_INT_1024 | ALS_PERS_1 | ALS_MODE_CONT;
    if (i2c_write_reg16(fd, VEML7700_CONF, conf) == -1) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int fd, float *lux) {
    uint16_t raw;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, VEML7700_ALS, &raw) == 0) {
            *lux = (float)raw / 1000.0f;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed: %s\n", attempt + 1, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void set_led_brightness(uint8_t brightness) {
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i * 3] = brightness;
        led_data[i * 3 + 1] = brightness;
        led_data[i * 3 + 2] = brightness;
    }
}

static void ws2812b_send_data(void) {
    for (int i = 0; i < NUM_LEDS; i++) {
        for (int j = 11; j >= 0; j--) {
            int bit = (led_data[i * 3 + 1] >> j) & 1;
            gpioWrite(GPIO_PIN, bit);
            usleep(1);
            gpioWrite(GPIO_PIN, 0);
            usleep(1);
        }
    }
}

static void cleanup(void) {
    if (gpio_initialized) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        gpio_initialized = 0;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    install_signal_handlers();
    generate_gamma_table();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_PIN, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (veml7700_init(i2c_fd) == -1) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        cleanup();
        return 1;
    }

    while (running) {
        float lux;
        if (veml7700_read_lux(i2c_fd, &lux) == 0) {
            uint8_t brightness = (uint8_t)(lux * 255.0f);
            if (brightness > 255) brightness = 255;
            if (brightness < 0) brightness = 0;
            set_led_brightness(brightness);
            ws2812b_send_data();
            printf("Lux: %.2f, Brightness: %u\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
        }
        usleep(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

