#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR      0x23
#define BH1750_PWR_ON    0x01
#define BH1750_CONT_HRES 0x10
#define LED_GPIO         17
#define BUFFER_SIZE      60
#define MAX_LUX          1000.0f
#define MIN_FREQ_HZ      0.5f
#define MAX_FREQ_HZ      5.0f
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_led_line = NULL;

static float lux_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0)
        return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0)
        return -1;
    return 0;
}

static int read_bh1750(int fd, float *lux_out)
{
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0)
        return -1;

    struct timespec ts = {0, 180000000}; /* 180 ms */
    nanosleep(&ts, NULL);

    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0)
        return -1;

    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void update_circular_buffer(float lux)
{
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static float calculate_average_lux(void)
{
    if (buffer_count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++)
        sum += lux_buffer[i];
    return sum / (float)buffer_count;
}

static float calculate_frequency(float lux)
{
    float freq = MIN_FREQ_HZ + (lux / MAX_LUX) * (MAX_FREQ_HZ - MIN_FREQ_HZ);
    if (freq < MIN_FREQ_HZ) freq = MIN_FREQ_HZ;
    if (freq > MAX_FREQ_HZ) freq = MAX_FREQ_HZ;
    return freq;
}

static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        cleanup();
        return 1;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_led_line = gpiod_chip_get_line(g_chip, LED_GPIO);
    if (!g_led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_led_line, "bh1750_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("BH1750 light sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (read_bh1750(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed, skipping sample.\n");
        } else {
            update_circular_buffer(lux);
            float avg = calculate_average_lux();
            float freq = calculate_frequency(avg);

            printf("Lux: %.2f  Avg: %.2f  Freq: %.2f Hz\n", lux, avg, freq);

            struct timespec half_period_ns = {0, (long)(500000000.0f / freq / 2.0f)};
            int val = 0;
            while (g_running) {
                val = val ? 0 : 1;
                if (gpiod_line_set_value(g_led_line, val) < 0) {
                    fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
                    break;
                }
                nanosleep(&half_period_ns, NULL);
            }
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

