    while (g_running) {
        float lux = 0.0f;
        if (read_bh1750(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed, skipping sample.\n");
        } else {
            update_circular_buffer(lux);
            float avg = calculate_average_lux();
            float freq = calculate_frequency(avg);

            printf("Lux: %.2f  Avg: %.2f  Freq: %.2f Hz\n", lux, avg, freq);

