#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define ON_TIME_US 500000
#define OFF_TIME_US 500000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
}

static void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        int bit = (data >> (7 - i)) & 1;
        gpioWrite(DATA_PIN, bit);
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1);
    }
}

static void display_digit(unsigned char digit) {
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1);
    shift_out(digit);
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    while (running) {
        display_digit(0x5F);
        gpioDelay(ON_TIME_US);
        if (!running) break;
        gpioWrite(LATCH_PIN, 0);
        gpioDelay(1);
        shift_out(0x00);
        gpioWrite(LATCH_PIN, 1);
        gpioDelay(1);
        gpioDelay(OFF_TIME_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

