#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CONSUMER   "blink_button"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Install SIGINT handler for graceful shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (the main GPIO controller on Raspberry Pi) */
    chip = gpiod_chip_open_by_number(0);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    /* Get the LED line (GPIO17) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line(LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line (GPIO18) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (button_line == NULL) {
        perror("gpiod_chip_get_line(BUTTON)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* Request button line as input with pull-up and falling-edge event detection */
    ret = gpiod_line_request_input_flags(button_line, CONSUMER,
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
                                          GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d. Press button on GPIO%d to stop.\n",
           LED_PIN, BUTTON_PIN);
    printf("Press Ctrl-C to exit.\n");

    /* Main loop: blink LED while waiting for button press */
    while (running) {
        /* Turn LED on */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(LED on)");
            break;
        }
        usleep(1000000); /* 1 second */

        if (!running) break;

        /* Turn LED off */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(LED off)");
            break;
        }
        usleep(1000000); /* 1 second */

        /* Poll for button press event with 100 ms timeout */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){0, 100000000});
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout, no event — loop back and check running flag */
            continue;
        }

        /* Read the event to clear it */
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }
    }

    /* Turn LED off before exiting */
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
    }

    printf("\nButton pressed! Exiting.\n");

cleanup:
    /* Release lines and close chip */
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (button_line != NULL) {
        gpiod_line_release(button_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

