#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define BLINK_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode, const char *label)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed for %s\n",
                pin, mode, label);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level, const char *label)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed for %s\n",
                pin, level, label);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin, const char *label)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed for %s\n", pin, label);
        return -1;
    }
    return v;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(LED_PIN, PI_OUTPUT, "LED_PIN") != 0 ||
        safe_set_mode(BUTTON_PIN, PI_INPUT, "BUTTON_PIN") != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (safe_write(LED_PIN, 0, "LED_PIN") != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on button pin */
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u) failed\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int led_state = 0;
    int prev_button = 0;

    while (g_running) {
        int button = safe_read(BUTTON_PIN, "BUTTON_PIN");
        if (button < 0) {
            /* Read error — turn LED off for safety and keep going */
            safe_write(LED_PIN, 0, "LED_PIN");
            led_state = 0;
            prev_button = 0;
            gpioDelay(10000);  /* 10 ms back-off */
            continue;
        }

        if (button == 1 && prev_button == 0) {
            /* Button just pressed — toggle LED */
            led_state = !led_state;
            if (safe_write(LED_PIN, led_state, "LED_PIN") != 0) {
                break;
            }
        }

        prev_button = button;
        gpioDelay(BLINK_DELAY_US);
    }

    /* Clean shutdown */
    safe_write(LED_PIN, 0, "LED_PIN");
    gpioTerminate();
    return EXIT_SUCCESS;
}

