/*
 * LSM303DLHC impact detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA  -> GPIO2  (I2C bus 1 SDA)
 *   LSM303DLHC SCL  -> GPIO3  (I2C bus 1 SCL)
 *   LSM303DLHC VCC  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *   Impact LED/indicator on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o impact_detect impact_detect.c -lm -lpigpio -lrt
 *   (pigpio must be installed and the program run as root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define LSM303_ADDR          0x19          /* SA0 tied to GND */
#define ACCEL_CTRL_REG1      0x20
#define ACCEL_CTRL_REG2      0x21
#define ACCEL_OUT_X_L        0x28
#define ACCEL_OUT_X_H        0x29
#define ACCEL_OUT_Y_L        0x2A
#define ACCEL_OUT_Y_H        0x2B
#define ACCEL_OUT_Z_L        0x2C
#define ACCEL_OUT_Z_H        0x2D

#define IMPACT_GPIO           17
#define DEFAULT_THRESHOLD    2.0f          /* G */
#define LOG_FILE             "impact_log.txt"
#define POLL_DELAY_US        100000        /* 10 Hz */
#define IMPACT_PULSE_US      50000         /* 50 ms */

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static int  g_impact_gpio = -1;
static FILE *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_impact_gpio >= 0) {
        gpioWrite(g_impact_gpio, 0);
        gpioSetMode(g_impact_gpio, PI_INPUT);
        g_impact_gpio = -1;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Read 6 bytes of accelerometer data ---- */
static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(g_i2c_handle, ACCEL_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed for accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    return 0;
}

/* ---- Convert raw LSB to G ---- */
static float convert_to_g(int16_t raw)
{
    /* ±2 g range, 12-bit left-justified → 1 LSB = 1/256 g */
    return (float)raw / 256.0f;
}

/* ---- Compute magnitude of G-force vector ---- */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ---- Log data to file ---- */
static void log_data(float x, float y, float z, float magnitude)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, X: %.3f G, Y: %.3f G, Z: %.3f G, Magnitude: %.3f G\n",
            timestamp, x, y, z, magnitude);
    fflush(g_log_file);
}

/* ---- Trigger impact interrupt ---- */
static void trigger_impact(void)
{
    if (gpioWrite(IMPACT_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: failed to set impact GPIO HIGH\n");
        return;
    }
    gpioDelay(IMPACT_PULSE_US);
    if (gpioWrite(IMPACT_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: failed to set impact GPIO LOW\n");
    }
}

/* ---- Parse threshold from command-line argument ---- */
static float parse_threshold(int argc, char *argv[])
{
    if (argc > 1) {
        char *endptr;
        float threshold = strtof(argv[1], &endptr);
        if (*endptr != '\0' || threshold <= 0.0f) {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return -1.0f;
        }
        return threshold;
    }
    return DEFAULT_THRESHOLD;
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    float threshold = parse_threshold(argc, argv);
    if (threshold < 0.0f) {
        fprintf(stderr, "Using default threshold: %.2f G\n", DEFAULT_THRESHOLD);
        threshold = DEFAULT_THRESHOLD;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: could not open I2C device at address 0x%02X on bus %d\n",
                LSM303_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure accelerometer: ±2 g, 50 Hz, normal mode */
    if (i2cWriteByteData(g_i2c_handle, ACCEL_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error: could not write to ACCEL_CTRL_REG1\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c_handle, ACCEL_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error: could not write to ACCEL_CTRL_REG2\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure impact GPIO */
    g_impact_gpio = gpioGetMode(IMPACT_GPIO);
    if (g_impact_gpio == PI_INPUT) {
        gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    } else if (g_impact_gpio != PI_OUTPUT) {
        fprintf(stderr, "Error: GPIO %d is not available for output\n", IMPACT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(IMPACT_GPIO, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: could not open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n",
           threshold);

    /* Main polling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_accelerometer(&raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Error: accelerometer read failed, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float x = convert_to_g(raw_x);
        float y = convert_to_g(raw_y);
        float z = convert_to_g(raw_z);
        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > threshold) {
            printf("Impact detected! Magnitude: %.3f G\n", magnitude);
            log_data(x, y, z, magnitude);
            trigger_impact();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

