#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x48
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_ALS_LSB 0x00
#define REG_ALS_MSB 0x01
#define REG_RED_LSB 0x02
#define REG_RED_MSB 0x03
#define REG_GREEN_LSB 0x04
#define REG_GREEN_MSB 0x05
#define REG_BLUE_LSB 0x06
#define REG_BLUE_MSB 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_16bit(uint8_t lsb_reg, uint8_t msb_reg, uint16_t *value) {
    uint8_t lsb, msb;
    if (read_register(lsb_reg, &lsb) < 0) return -1;
    if (read_register(msb_reg, &msb) < 0) return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_16bit(REG_ALS_LSB, REG_ALS_MSB, als) < 0) return -1;
    if (read_16bit(REG_RED_LSB, REG_RED_MSB, red) < 0) return -1;
    if (read_16bit(REG_GREEN_LSB, REG_GREEN_MSB, green) < 0) return -1;
    if (read_16bit(REG_BLUE_LSB, REG_BLUE_MSB, blue) < 0) return -1;
    return 0;
}

static void control_led_brightness(uint16_t als_value) {
    int pwm_value = (int)((als_value / 65535.0) * PWM_RANGE);
