#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ register definitions (verified against datasheet) ---- */
#define FXOS8700_ADDRESS        0x1D   /* SA0 tied to GND on Adafruit breakout */
#define FXOS8700_WHO_AM_I       0x0D
#define FXOS8700_WHO_AM_I_VAL   0xC7
#define FXOS8700_CTRL_REG1      0x2A
#define FXOS8700_CTRL_REG2      0x2B
#define FXOS8700_XYZ_DATA_CFG   0x0E
#define FXOS8700_OUT_X_MSB      0x01

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define IMPACT_THRESHOLD        2.0f   /* g */
#define SAMPLE_INTERVAL_US      50000  /* 50 ms */
#define LOG_FILE                "impact_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers with error checking ---- */
static int fxos_write_reg(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X)\n", reg, val);
        return -1;
    }
    return 0;
}

static int fxos_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u)\n", reg, len);
        return -1;
    }
    if ((uint32_t)n != len) {
        fprintf(stderr, "I2C block read short: got %d of %u\n", n, len);
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int fxos8700_init(int handle)
{
    int id = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (id != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG1, 0x00) < 0)
        return -1;

    /* ±2 g range */
    if (fxos_write_reg(handle, FXOS8700_XYZ_DATA_CFG, 0x00) < 0)
        return -1;

    /* Active mode, 200 Hz ODR (CTRL_REG1 = 0x01) */
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG1, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration (raw 16-bit, two's complement) ---- */
static int fxos8700_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (fxos_read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Compute acceleration magnitude in g ---- */
static float accel_magnitude_g(int16_t x, int16_t y, int16_t z)
{
    float xg = (float)x / 4096.0f;   /* ±2 g range: 4096 LSB/g */
    float yg = (float)y / 4096.0f;
    float zg = (float)z / 4096.0f;
    return sqrtf(xg * xg + yg * yg + zg * zg);
}

/* ---- Log impact event ---- */
static void log_impact(int16_t x, int16_t y, int16_t z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d,%d,%d,%.3f\n", ts, x, y, z, mag);
    } else {
        fprintf(fp, "(time-error),%d,%d,%d,%.3f\n", x, y, z, mag);
    }

    fclose(fp);
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, FXOS8700_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos8700_init(g_i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700CQ impact monitor running. Threshold: %.1f g. Press Ctrl-C to exit.\n",
           IMPACT_THRESHOLD);

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (fxos8700_read_accel(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error — continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float mag = accel_magnitude_g(x, y, z);

        if (mag > IMPACT_THRESHOLD) {
            log_impact(x, y, z, mag);
            printf("Impact detected: magnitude = %.3f g (x=%d y=%d z=%d)\n",
                   mag, x, y, z);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

