    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, len) != len)
        return -1;
    return 0;
}

static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 100 Hz output data rate, all axes enabled */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error: cannot write CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    /* CTRL_REG4: default full-scale 245 dps, continuous update */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: cannot write CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, L3G4200D_OUT_X_L, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int gyro_calibrate(int fd, gyro_offsets_t *offs)
{
    int16_t x, y, z;
    float sx = 0.0f, sy = 0.0f, sz = 0.0f;

    printf("Calibrating gyroscope (keep sensor stationary)...\n");
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (gyro_read_raw(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read error at sample %d: %s\n",
                    i, strerror(errno));
            return -1;
        }
        sx += (float)x;
        sy += (float)y;
        sz += (float)z;
        usleep(1000);
    }

    offs->x = sx / CALIB_SAMPLES;
    offs->y = sy / CALIB_SAMPLES;
    offs->z = sz / CALIB_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f Y=%.2f Z=%.2f\n",
           offs->x, offs->y, offs->z);
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z)
{
    if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS ||
        fabsf(z) > THRESHOLD_DPS) {
        fprintf(stderr, "ALERT: Gyro exceeds threshold! X=%.2f Y=%.2f Z=%.2f\n",
                x, y, z);
        fprintf(g_log_fp, "ALERT: Gyro exceeds threshold! X=%.2f Y=%.2f Z=%.2f\n",
                x, y, z);
        fflush(g_log_fp);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x6B) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (gyro_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    if (gyro_calibrate(g_i2c_fd, NULL) < 0) {
        fprintf(stderr, "Gyroscope calibration failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t rx, ry, rz;
        if (gyro_read_raw(g_i2c_fd, &rx, &ry, &rz) < 0) {
            fprintf(stderr, "Read error: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        gyro_offsets_t offs = {0.0f, 0.0f, 0.0f};
        if (gyro_calibrate(g_i2c_fd, &offs) < 0) {
            fprintf(stderr, "Calibration error: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float cx = (float)rx - offs.x;
        float cy = (float)ry - offs.y;
        float cz = (float)rz - offs.z;

        log_data(g_log_fp, cx, cy, cz);
        check_threshold(cx, cy, cz);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

