#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (0x53 when ALT address pin is low) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAX1      0x33
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAY1      0x35
#define ADXL345_DATAZ0      0x36
#define ADXL345_DATAZ1      0x37

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Acceleration threshold in g */
#define ACCEL_THRESHOLD 2.0f

/* Full-resolution, ±2 g range: 4 mg/LSB → 1 g = 256 LSB */
#define G_PER_LSB 256.0f

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_byte(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode before configuration */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full-resolution, ±2 g range, right-justified, 4-wire SPI off */
    if (i2c_write_byte(handle, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Data rate = 100 Hz (0x0A) */
    if (i2c_write_byte(handle, 0x2C, 0x0A) != 0)
        return -1;

    /* Enable measurement mode */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g)                                               */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t x0, x1, y0, y1, z0, z1;

    if (i2c_read_byte(handle, ADXL345_DATAX0, &x0) != 0) return -1;
    if (i2c_read_byte(handle, ADXL345_DATAX1, &x1) != 0) return -1;
    if (i2c_read_byte(handle, ADXL345_DATAY0, &y0) != 0) return -1;
    if (i2c_read_byte(handle, ADXL345_DATAY1, &y1) != 0) return -1;
    if (i2c_read_byte(handle, ADXL345_DATAZ0, &z0) != 0) return -1;
    if (i2c_read_byte(handle, ADXL345_DATAZ1, &z1) != 0) return -1;

    int16_t raw_x = (int16_t)((x1 << 8) | x0);
    int16_t raw_y = (int16_t)((y1 << 8) | y0);
    int16_t raw_z = (int16_t)((z1 << 8) | z0);

    *x = (float)raw_x / G_PER_LSB;
    *y = (float)raw_y / G_PER_LSB;
    *z = (float)raw_z / G_PER_LSB;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log acceleration data                                               */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }

            /* Threshold check on any axis */
            if (fabsf(x) > ACCEL_THRESHOLD ||
                fabsf(y) > ACCEL_THRESHOLD ||
                fabsf(z) > ACCEL_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            /* Read failure: turn LED off and log the error */
            gpioWrite(LED_PIN, 0);
            fprintf(stderr, "Read failure, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
