#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC registers ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_accel = -1;
static int g_i2c_mag   = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Initialize LSM303DLHC ----
 * Returns 0 on success, -1 on failure.
 */
static int init_lsm303(void)
{
    /* Open I2C for accelerometer */
    g_i2c_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_accel < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer (addr 0x%02X): %d\n",
                LSM303_ACCEL_ADDR, g_i2c_accel);
        return -1;
    }

    /* Open I2C for magnetometer */
    g_i2c_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (g_i2c_mag < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer (addr 0x%02X): %d\n",
                LSM303_MAG_ADDR, g_i2c_mag);
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
        return -1;
    }

    /* Configure accelerometer: 50 Hz, +/-2 g, normal mode */
    if (i2cWriteByteData(g_i2c_accel, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    /* Configure magnetometer: continuous conversion mode */
    if (i2cWriteByteData(g_i2c_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

/* ---- Read accelerometer data ----
 * Returns 0 on success, -1 on failure.
 */
static int read_accel(float *x, float *y, float *z)
{
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(g_i2c_accel, LSM303_ACCEL_OUT_X_L_A, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    /* Convert to g: +/-2 g range, 16-bit signed, 1 mg/LSB */
    *x = (float)raw_x / 1000.0f;
    *y = (float)raw_y / 1000.0f;
    *z = (float)raw_z / 1000.0f;

    return 0;
}

/* ---- Read magnetometer data ----
 * Returns 0 on success, -1 on failure.
 */
static int read_mag(float *x, float *y, float *z)
{
    char buf[6];
    int16_t raw_x, raw_z;  /* OUT_X_H_M / OUT_X_L_M / OUT_Z_H_M / OUT_Z_L_M */

    if (i2cReadI2CBlockData(g_i2c_mag, LSM303_MAG_OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_z = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    /* buf[4] / buf[5] are OUT_Y_H_M / OUT_Y_L_M */

    /* Convert to gauss: +/-4 gauss range, 16-bit signed, 1 mG/LSB */
    *x = (float)raw_x / 1000.0f;
    *y = (float)((int16_t)((buf[4] << 8) | (uint8_t)buf[5])) / 1000.0f;
    *z = (float)raw_z / 1000.0f;

    return 0;
}

/* ---- Tilt-compensated heading (degrees) ---- */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));

    float cr = cosf(roll);
    float sr = sinf(roll);
    float cp = cosf(pitch);
    float sp = sinf(pitch);

    float xh = mx * cp + mz * sp;
    float yh = mx * sr * sp + my * cr - mz * sr * cp;

    float heading = atan2f(yh, xh) * 180.0f / (float)M_PI;
    if (heading < 0.0f) heading += 360.0f;

    return heading;
}

/* ---- Log data to file ----
 * Returns 0 on success, -1 on failure.
 */
static int log_data(float heading, float ax, float ay, float az,
                    float mx, float my, float mz)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening compass_log.txt for appending\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing compass_log.txt\n");
        return -1;
    }

    return 0;
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (g_i2c_accel >= 0) {
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
    }
    if (g_i2c_mag >= 0) {
        i2cClose(g_i2c_mag);
        g_i2c_mag = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize LSM303DLHC */
    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303DLHC initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new */
    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading,accel_x_g,accel_y_g,accel_z_g,mag_x_g,mag_y_g,mag_z_g\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Warning: could not create compass_log.txt\n");
        }
    } else {
        fclose(fp);
    }

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accel(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accelerometer read failed; skipping sample\n");
            gpioDelay(100000); /* 100 ms */
            continue;
        }

        if (read_mag(&mx, &my, &mz) != 0) {
            fprintf(stderr, "Magnetometer read failed; skipping sample\n");
            gpioDelay(100000);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);

        if (log_data(heading, ax, ay, az, mx, my, mz) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

