    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize LSM303DLHC */
    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303DLHC initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new */
    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "timestamp,heading,accel_x_g,accel_y_g,accel_z_g,mag_x_g,mag_y_g,mag_z_g\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Warning: could not create compass_log.txt\n");
        }
    } else {
        fclose(fp);
    }

    /* Main sampling loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accel(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accelerometer read failed; skipping sample\n");
            gpioDelay(100000); /* 100 ms */
            continue;
        }

        if (read_mag(&mx, &my, &mz) != 0) {
            fprintf(stderr, "Magnetometer read failed; skipping sample\n");
            gpioDelay(100000);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);

        if (log_data(heading, ax, ay, az, mx, my, mz) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

