/* Write a 16-bit register address + 1 byte of data using pigpio's i2cWriteI2CBlockData. */
static int vl6180x_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

/* Read N bytes starting at a 16-bit register address. */
static int vl6180x_read_block(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    return i2cReadI2CBlockData(handle, addr[0], (char *)data, len);
}

