#define DOOR_THRESHOLD 100      /* mm */

/* VL6180X register addresses */
#define REG_IDENTIFICATION_MODEL_ID      0x000
#define REG_SYSTEM_FRESH_OUT_OF_RESET    0x016
#define REG_SYSRANGE_START               0x018
#define REG_RESULT_RANGE_VAL             0x062
#define REG_RESULT_INTERRUPT_STATUS      0x04D
#define REG_SYSTEM_INTERRUPT_CLEAR       0x015

#define EXPECTED_MODEL_ID 0xB4

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte of data using pigpio's i2cWriteI2CBlockData. */
static int vl6180x_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

/* Read N bytes starting at a 16-bit register address. */
static int vl6180x_read_block(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    return i2cReadI2CBlockData(handle, addr[0], (char *)data, len);
}

static int vl6180x_init(int handle)
{
    uint8_t model_id = 0;

    if (vl6180x_read_block(handle, REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: cannot read MODEL_ID register (I2C bus error or sensor absent).\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected MODEL_ID 0x%02X (expected 0x%02X). Sensor not present?\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Read fresh-out-of-reset so we can confirm the sensor is ready. */
    uint8_t fresh = 0;
    if (vl6180x_read_block(handle, REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh, 1) < 0) {
        fprintf(stderr, "Error: cannot read FRESH_OUT_OF_RESET register.\n");
        return -1;
    }
    if (fresh != 0x01) {
        fprintf(stderr, "Warning: sensor not fresh out of reset (0x%02X). Continuing anyway.\n", fresh);
