/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU Ultrasonic MEMS Microphone TDOA Logger
 *
 * Wiring:
 *   I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *   Sensor 1:  I2C address 0x40
 *   Sensor 2:  I2C address 0x41
 *   Data out:  left channel -> sensor 1, right channel -> sensor 2
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o audio_log audio_log.c -li2c -lm
 *
 * Run:
 *   ./audio_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SENSOR1_ADDR     0x40
#define SENSOR2_ADDR     0x41
#define SAMPLE_PERIOD_US 10000          /* 10 ms */
#define LOG_FILE         "audio_log.dat"

/* IMP23ABSU 16-bit read: write 0x00 (dummy) then read 2 bytes */
#define IMP23ABSU_READ_CMD 0x00

static volatile sig_atomic_t g_running = 1;
static int  g_fd1 = -1;
static int  g_fd2 = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a 16-bit signed sample from the IMP23ABSU.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor(int fd, int16_t *out)
{
    uint8_t cmd = IMP23ABSU_READ_CMD;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes (%s)\n",
                r, sizeof(buf), strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(struct timespec *ts)
{
    if (clock_gettime(CLOCK_REALTIME, ts) != 0) {
        perror("clock_gettime");
        ts->tv_sec  = 0;
        ts->tv_nsec = 0;
    }
}

/* ------------------------------------------------------------------ */
/* TDOA computation                                                     */
/* ------------------------------------------------------------------ */
static double compute_tdoa(const struct timespec *t1,
                           const struct timespec *t2)
{
    double dt = (double)(t2->tv_sec  - t1->tv_sec)
              + (double)(t2->tv_nsec - t1->tv_nsec) / 1.0e9;
    return dt;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const struct timespec *ts,
                    int16_t s1, int16_t s2, double tdoa)
{
    if (fprintf(fp, "%ld.%09ld,%d,%d,%.9f\n",
                (long)ts->tv_sec, ts->tv_nsec,
                s1, s2, tdoa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_fd1 >= 0) {
        close(g_fd1);
        g_fd1 = -1;
    }
    if (g_fd2 >= 0) {
        close(g_fd2);
        g_fd2 = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handler();

    g_fd1 = i2c_open(I2C_BUS, SENSOR1_ADDR);
    if (g_fd1 < 0) {
        return EXIT_FAILURE;
    }
    g_fd2 = i2c_open(I2C_BUS, SENSOR2_ADDR);
    if (g_fd2 < 0) {
        close(g_fd1);
        g_fd1 = -1;
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sampling IMP23ABSU microphones on %s (bus 1).\n", I2C_BUS);
    printf("Sensor 1: 0x%02X | Sensor 2: 0x%02X | Log: %s\n",
           SENSOR1_ADDR, SENSOR2_ADDR, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        struct timespec ts1, ts2;
        int16_t s1 = 0, s2 = 0;
        int ok1 = 0, ok2 = 0;

        get_timestamp(&ts1);
        if (read_sensor(g_fd1, &s1) == 0) {
            ok1 = 1;
        } else {
            fprintf(stderr, "Sensor 1 read error — skipping sample.\n");
        }

        get_timestamp(&ts2);
        if (read_sensor(g_fd2, &s2) == 0) {
            ok2 = 1;
        } else {
            fprintf(stderr, "Sensor 2 read error — skipping sample.\n");
        }

        if (ok1 && ok2) {
            double tdoa = compute_tdoa(&ts1, &ts2);
            if (log_data(g_log, &ts1, s1, s2, tdoa) != 0) {
                fprintf(stderr, "Logging failed — continuing.\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

