/*
 * ADIS16488A IMU SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16488A CS  -> GPIO8  (SPI0 CE0, BCM 8)
 *   ADIS16488A SCLK-> GPIO11 (SPI0 SCLK, BCM 11)
 *   ADIS16488A DOUT-> GPIO9  (SPI0 MISO,  BCM 9)
 *   ADIS16488A DIN -> GPIO10 (SPI0 MOSI, BCM 10)
 *   ADIS16488A VDD -> 3.3 V
 *   ADIS16488A GND -> GND
 *
 * SPI: 1 MHz, mode 3 (CPOL=1, CPHA=1), 16-bit words.
 * Stall time between read request and data transfer >= 40 us.
 * Sampling interval 100 ms.  Gyro: 0.005 deg/sec/LSB.
 * Accelerometer: 0.00025 g/LSB.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        16
#define SPI_MODE        3
#define SPI_STALL_US    40U
#define SAMPLE_PERIOD_MS 100
#define CSV_FILENAME    "imu_data.csv"

/* ADIS16488A register addresses (7-bit) */
#define REG_GYRO_XOUT    0x04
#define REG_GYRO_YOUT    0x06
#define REG_GYRO_ZOUT    0x08
#define REG_ACCEL_XOUT   0x0A
#define REG_ACCEL_YOUT   0x0C
#define REG_ACCEL_ZOUT   0x0E

/* Sensitivities */
#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_csv_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv_fp != NULL) {
        fflush(g_csv_fp);
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

