    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * ADIS16488A SPI read sequence:
 *   1. Send a 16-bit command word: [0, addr]  (MSB = 0 => read)
 *   2. Stall >= 40 us
 *   3. Read a 16-bit data word
 *   4. Stall >= 40 us
 *   5. Repeat for each register
 *
 * Returns 0 on success, -1 on SPI error.
 */
static int read_register(uint8_t addr, int16_t *out)
{
    uint8_t tx[2] = { 0x00, (uint8_t)(addr & 0x7F) };
    uint8_t rx[2] = { 0, 0 };
    struct spi_ioc_transfer tr;
    int ret;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 2;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_STALL_US;

