        return -1;
    }

    /* Phase 2: read data */
    ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_MESSAGE) - data");
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data conversion                                                     */
/* ------------------------------------------------------------------ */
static void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z,
                         int16_t accel_x, int16_t accel_y, int16_t accel_z,
                         float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az)
{
    *gx = (float)gyro_x * GYRO_SENSITIVITY;
    *gy = (float)gyro_y * GYRO_SENSITIVITY;
    *gz = (float)gyro_z * GYRO_SENSITIVITY;
