    *ay = (float)accel_y * ACCEL_SENSITIVITY;
    *az = (float)accel_z * ACCEL_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float gx, float gy, float gz,
                    float ax, float ay, float az)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

    if (fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, ms, gx, gy, gz, ax, ay, az) < 0) {
        perror("fprintf");
        return -1;
    }
