        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (atexit(cleanup) != 0) {
        perror("atexit");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(CSV_FILENAME, "w");
    if (g_csv_fp == NULL) {
        perror("fopen(" CSV_FILENAME ")");
        return EXIT_FAILURE;
    }

    if (fprintf(g_csv_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n") < 0) {
