        return EXIT_FAILURE;
    }
    if (fflush(g_csv_fp) != 0) {
        perror("fflush(header)");
        return EXIT_FAILURE;
    }

    printf("ADIS16488A logging started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;
        float gx, gy, gz, ax, ay, az;

        bool read_failed = false;

        if (read_register(REG_GYRO_XOUT, &gyro_x) != 0) read_failed = true;
        if (read_register(REG_GYRO_YOUT, &gyro_y) != 0) read_failed = true;
        if (read_register(REG_GYRO_ZOUT, &gyro_z) != 0) read_failed = true;
        if (read_register(REG_ACCEL_XOUT, &accel_x) != 0) read_failed = true;
        if (read_register(REG_ACCEL_YOUT, &accel_y) != 0) read_failed = true;
        if (read_register(REG_ACCEL_ZOUT, &accel_z) != 0) read_failed = true;

        if (read_failed) {
            fprintf(stderr, "SPI read error — skipping sample.\n");
        } else {
