                         &gx, &gy, &gz, &ax, &ay, &az);

            if (log_data(g_csv_fp, gx, gy, gz, ax, ay, az) != 0) {
                fprintf(stderr, "CSV write error — continuing.\n");
            }
        }

        /* Non-blocking delay so signals are processed promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(10000); /* 10 ms × 10 = 100 ms */
    }

    printf("\nShutting down cleanly.\n");
    return EXIT_SUCCESS;
}

