/*
 * ADIS16448 IMU SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16448 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM 9, SPI0 MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 * Run:    sudo ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

/* ---- ADIS16448 constants (per datasheet) ---- */
#define ADIS16448_REG_GLOB_CMD   0x02
#define ADIS16448_REG_GLOB_STATUS 0x04
#define ADIS16448_REG_GXOUT      0x08
#define ADIS16448_REG_GYOUT      0x0A
#define ADIS16448_REG_GZOUT      0x0C
#define ADIS16448_REG_AXOUT      0x0E
#define ADIS16448_REG_AYOUT      0x10
#define ADIS16448_REG_AZOUT      0x12

#define ADIS16448_GYRO_SCALE    0.02f   /* dps per LSB */
#define ADIS16448_ACCEL_SCALE   0.00025f /* g per LSB */

#define SPI_BUS              0
#define SPI_DEVICE           "/dev/spidev0.0"
#define SPI_SPEED_HZ         1000000   /* 1 MHz */
#define SPI_MODE             3         /* SPI mode 3: CPOL=1, CPHA=1 */
#define SPI_BITS_PER_WORD    8
#define SAMPLE_PERIOD_US     100000    /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single 16-bit register from the ADIS16448.
 * The ADIS16448 uses a two-cycle read protocol:
 *   Cycle 1: send [reg | 0x80], 0x00, 0x00  -> response is ignored
 *   Cycle 2: send 0x00, 0x00, 0x00          -> data returned in rx[1..2]
 * Returns 0 on success, -1 on SPI error.
 */
static int adis16448_read_reg16(int spi_fd, uint8_t reg, int16_t *out)
{
    uint8_t tx1[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx1[3] = { 0 };
    uint8_t tx2[3] = { 0x00, 0x00, 0x00 };
    uint8_t rx2[3] = { 0 };

    struct spi_ioc_transfer tr1 = {
        .tx_buf        = (unsigned long)tx1,
        .rx_buf        = (unsigned long)rx1,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };
    struct spi_ioc_transfer tr2 = {
        .tx_buf        = (unsigned long)tx2,
        .rx_buf        = (unsigned long)rx2,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr1) < 0) {
        fprintf(stderr, "SPI read phase 1 failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr2) < 0) {
        fprintf(stderr, "SPI read phase 2 failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx2[1] << 8) | rx2[2]);
    return 0;
}

static void log_data(float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    printf("Gyro: X=%.3f, Y=%.3f, Z=%.3f dps  |  Accel: X=%.6f, Y=%.6f, Z=%.6f g\n",
           gx, gy, gz, ax, ay, az);
    fflush(stdout);
}

int main(void)
{
    int spi_fd = -1;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio (also sets up GPIO bank and clock) --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup_gpio;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    /* --- Configure SPI bits per word --- */
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    /* --- Configure SPI max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto cleanup_spi;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw_gx, raw_gy, raw_gz;
        int16_t raw_ax, raw_ay, raw_az;

        if (adis16448_read_reg16(spi_fd, ADIS16448_REG_GXOUT, &raw_gx) < 0) {
            fprintf(stderr, "Gyro X read failed; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis16448_read_reg16(spi_fd, ADIS16448_REG_GYOUT, &raw_gy) < 0) {
            fprintf(stderr, "Gyro Y read failed; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis16448_read_reg16(spi_fd, ADIS16448_REG_GZOUT, &raw_gz) < 0) {
            fprintf(stderr, "Gyro Z read failed; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis16448_read_reg16(spi_fd, ADIS16448_REG_AXOUT, &raw_ax) < 0) {
            fprintf(stderr, "Accel X read failed; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis16448_read_reg16(spi_fd, ADIS16448_REG_AYOUT, &raw_ay) < 0) {
            fprintf(stderr, "Accel Y read failed; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis16448_read_reg16(spi_fd, ADIS16448_REG_AZOUT, &raw_az) < 0) {
            fprintf(stderr, "Accel Z read failed; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

