 *   ADIS16448 DOUT-> GPIO9  (BCM 9, SPI MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM 10, SPI MOSI)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * SPI: channel 0, 1 MHz, Mode 0 (CPOL=0, CPHA=0), 16-bit words.
 * Read sequence: two 16-bit transfers per register.
 *   Transfer 1: send register address (bit 15 set) -> response (dummy).
 *   Transfer 2: send 0x0001 -> receive 16-bit data.
 *   Data is scaled: gyro 0.05 deg/s/LSB, accel 0.00025 g/LSB.
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 constants (per datasheet) ---- */
#define ADIS16448_REG_GYRO_XOUT 0x04
#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCEL_XOUT 0x0A
#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

#define ADIS16448_READ_BIT 0x8000  /* bit 15 of any register address */
#define ADIS16448_DUMMY 0x0001     /* dummy value for second transfer */

#define GYRO_SCALE 0.05f          /* deg/s per LSB  */
#define ACCEL_SCALE 0.00025f      /* g per LSB     */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000       /* 1 MHz */
#define SPI_FLAGS   0             /* Mode 0, active-low CE */

#define SAMPLE_PERIOD_US 100000   /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one register using the two-cycle SPI protocol.
 * Returns 0 on success, -1 on SPI error, -2 on invalid register.     */
static int adis16448_read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];

    /* ---- First transfer: send read command, get dummy response ---- */
    tx[0] = (char)(ADIS16448_READ_BIT | (reg & 0x3F));
    tx[1] = 0x00;

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed (reg 0x%02X, first phase)\n", reg);
        return -1;
    }

    /* ---- Stall time: ADIS16448 needs >= 40 us between phases ---- */
    gpioDelay(50);  /* 50 us > 40 us */

    /* ---- Second transfer: send dummy, get data ---- */
    tx[0] = (char)ADIS16448_DUMMY;
    tx[1] = 0x00;

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed (reg 0x%02X, second phase)\n", reg);
        return -1;
    }

    /* Data is returned big-endian in rx[0]..rx[1] */
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
