    if (adis16448_read_register(ADIS16448_REG_GYRO_XOUT, &raw) != 0)
        return -1;
    *gyro_x = (float)raw * GYRO_SCALE;

    if (adis16448_read_register(ADIS16448_REG_GYRO_YOUT, &raw) != 0)
        return -1;
    *gyro_y = (float)raw * GYRO_SCALE;

    if (adis16448_read_register(ADIS16448_REG_GYRO_ZOUT, &raw) != 0)
        return -1;
    *gyro_z = (float)raw * GYRO_SCALE;

    if (adis16448_read_register(ADIS16448_REG_ACCEL_XOUT, &raw) != 0)
        return -1;
    *accel_x = (float)raw * ACCEL_SCALE;

    if (adis16448_read_register(ADIS16448_REG_ACCEL_YOUT, &raw) != 0)
        return -1;
    *accel_y = (float)raw * ACCEL_SCALE;

    if (adis16448_read_register(ADIS16448_REG_ACCEL_ZOUT, &raw) != 0)
        return -1;
    *accel_z = (float)raw * ACCEL_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started. Press Ctrl-C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro:  X=%.3f deg/s  Y=%.3f deg/s  Z=%.3f deg/s\n",
                   gx, gy, gz);
            printf("Accel: X=%.6f g   Y=%.6f g   Z=%.6f g\n\n",
                   ax, ay, az);
        } else {
            fprintf(stderr, "IMU read error — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

