#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 register definitions (verified against datasheet) ---- */
#define ADXL345_I2C_ADDR        0x53
#define ADXL345_DEVID           0x00
#define ADXL345_POWER_CTL       0x2D
#define ADXL345_DATA_FORMAT     0x31
#define ADXL345_DATAX0          0x32
#define ADXL345_DATAX1          0x33
#define ADXL345_DATAY0          0x34
#define ADXL345_DATAY1          0x35
#define ADXL345_DATAZ0          0x36
#define ADXL345_DATAZ1          0x37
#define ADXL345_BW_RATE         0x2C

#define ADXL345_DEVID_EXPECTED  0xE5
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_DATA_FORMAT_FULL_RES 0x0B  /* ±2 g, full resolution, right-justified */

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define LED_GPIO                17
#define ACCELERATION_THRESHOLD  2.5f   /* g */
#define SCALE_FACTOR            256.0f /* LSB per g in full-resolution mode */
#define POLL_INTERVAL_US        10000  /* 10 ms */
#define LED_ON_DURATION_US      500000 /* 500 ms */

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Safe to call even if pigpio was not initialised */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialise pigpio and the LED GPIO                                  */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d low.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345                                              */
/* ------------------------------------------------------------------ */
static int init_adxl345(void)
{
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADXL345_I2C_ADDR, i2c_handle);
        return -1;
    }

    /* Verify device identity */
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr,
                "Error: DEVID mismatch (got 0x%02X, expected 0x%02X). "
                "Sensor not present or wrong device.\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL standby.\n");
        return -1;
    }

    /* Full-resolution, ±2 g range, right-justified */
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, ADXL345_DATA_FORMAT_FULL_RES) < 0) {
        fprintf(stderr, "Error: failed to write DATA_FORMAT.\n");
        return -1;
    }

    /* Output data rate = 100 Hz (0x0A) */
    if (i2cWriteByteData(i2c_handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: failed to write BW_RATE.\n");
        return -1;
    }

    /* Enter measurement mode */
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, ADXL345_POWER_CTL_MEASURE) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL measure.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data and convert to g                 */
/* ------------------------------------------------------------------ */
static int read_acceleration(float *x, float *y, float *z)
{
    char raw[6];

    int n = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw, 6);
    if (n != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 6).\n", n);
        return -1;
    }

    int16_t x_raw = (int16_t)(((uint16_t)(uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint16_t)(uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint16_t)(uint8_t)raw[5] << 8) | (uint8_t)raw[4]);

    *x = (float)x_raw / SCALE_FACTOR;
    *y = (float)y_raw / SCALE_FACTOR;
    *z = (float)z_raw / SCALE_FACTOR;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute magnitude of acceleration vector                            */
/* ------------------------------------------------------------------ */
static float magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log impact event to file                                            */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Impact: X=%.2f g, Y=%.2f g, Z=%.2f g, |a|=%.2f g\n",
            ts, x, y, z, mag);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_adxl345() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) < 0) {
            fprintf(stderr, "Warning: read failed, retrying in 10 ms.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float mag = magnitude(x, y, z);

        if (mag > ACCELERATION_THRESHOLD) {
            printf("Impact detected! |a| = %.2f g\n", mag);
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DURATION_US);
            gpioWrite(LED_GPIO, 0);
            log_impact(x, y, z, mag);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

