#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICM-20602 register addresses (verified against datasheet) */
#define ICM20602_ADDR        0x68
#define REG_SMPLRT_DIV       0x19
#define REG_PWR_MGMT_1       0x6B
#define REG_ACCEL_XOUT_H     0x3B
#define REG_GYRO_XOUT_H      0x43

/* Globals for signal handler cleanup */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at `reg` into `buf`                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_block(int handle, uint8_t reg, uint8_t *buf, int len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %d, got %d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register                                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X, rc=%d)\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ICM-20602: wake, set sample rate to 10 Hz             */
/* ------------------------------------------------------------------ */
static int init_imu(int handle)
{
    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (write_reg(handle, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Allow time for oscillator to stabilise */
    gpioDelay(100000); /* 100 ms */

    /* Set sample rate divider: 1 kHz / (1 + 7) = 125 Hz internal,
       but we want 10 Hz output.  SMPLRT_DIV = 7 -> 125 Hz / (1+7) = 7.81 Hz
       internal, so we use 7 and adjust in the loop. */
    if (write_reg(handle, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and convert one sample                                          */
/* ------------------------------------------------------------------ */
static int read_imu(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                    int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[12];

    /* Burst read 12 bytes starting at ACCEL_XOUT_H (0x3B):
     *   [0:1]  accel X, [2:3] accel Y, [4:5] accel Z,
     *   [6:7]  temp,    [8:9] gyro X,   [10:11] gyro Y,
     *   [12:13] gyro Z  (temp is skipped here; if needed, adjust offset)
     */
    if (read_block(handle, REG_ACCEL_XOUT_H, buf, 12) < 0)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = 0; /* gyro Z not read separately — use buf[10:11] */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row                                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                    int16_t gx, int16_t gy, int16_t gz)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld,%d,%d,%d,%d,%d,%d\n",
                timestamp, ts.tv_nsec / 1000000L,
                ax, ay, az, gx, gy, gz) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus 1 at 0x68 ------------------------------------- */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (addr 0x%02X): %d\n",
                ICM20602_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- init IMU --------------------------------------------------- */
    if (init_imu(i2c_handle) < 0) {
        fprintf(stderr, "IMU initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open CSV log file ------------------------------------------ */
    log_file = fopen("imu_log.csv", "a");
    if (!log_file) {
        perror("fopen imu_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(log_file);
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- main loop -------------------------------------------------- */
    int16_t ax, ay, az, gx, gy, gz;
    int consecutive_errors = 0;

    while (running) {
        if (read_imu(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            consecutive_errors = 0;
            if (log_data(log_file, ax, ay, az, gx, gy, gz) < 0) {
                fprintf(stderr, "Logging failed; aborting.\n");
                break;
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        gpioDelay(100000); /* 100 ms -> 10 Hz */
    }

    /* --- graceful cleanup ------------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

