#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define MMA8451Q_ADDR  0x1A
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x1A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define LED_GPIO       17
#define ACCEL_THRESHOLD 2.0f   /* g */
#define SCALE_FACTOR   1024.0f /* counts per g at default ±2 g range */
#define POLL_DELAY_US  100000  /* 100 ms */
#define LED_ON_US      500000  /* 500 ms */

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Safe to call even if not initialised */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Read 6 bytes of acceleration data ---- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int  rc;

    rc = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ---- Verify sensor identity ---- */
static int verify_sensor(void)
{
    int id = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* ---- Log an impact event ---- */
static void log_impact(int16_t x, int16_t y, int16_t z)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    time(&t);
    localtime_r(&t, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s - Impact: X=%d, Y=%d, Z=%d\n", ts, x, y, z);
    fflush(log_file);
}

/* ---- Main ---- */
int main(void)
{
    int16_t x, y, z;
    float   mag;

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, MMA8451Q_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (verify_sensor() != 0) {
        fprintf(stderr, "MMA8451Q not detected on bus %d addr 0x%02X\n",
                I2C_BUS, MMA8451Q_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable accelerometer: 8 Hz ODR, normal mode, XYZ axes enabled */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MMA8451Q impact monitor running. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            mag = sqrtf((float)x * x + (float)y * y + (float)z * z) / SCALE_FACTOR;
            if (mag > ACCEL_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
                log_impact(x, y, z);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

