static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr,
                "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X).\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby before configuring */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/-2g, right-justified */
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Free-fall interrupt on X, Y, Z axes */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x40) != 0)
        return -1;

    /* Map all interrupts to INT1 */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) != 0)
        return -1;

    /* Free-fall threshold = 2g (0x03) */
    if (i2c_write_reg8(fd, ADXL345_INT1_THRESH, 0x03) != 0)
        return -1;

    /* Free-fall duration = 1 sample (0x01) */
    if (i2c_write_reg8(fd, ADXL345_INT1_DURATION, 0x01) != 0)
        return -1;

    /* Standby -> measurement mode */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (write(fd, (uint8_t[]){ ADXL345_DATAX0 }, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                ADXL345_DATAX0, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read of 6-byte accel block failed: %s\n",
                strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", ts_str, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void freefall_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    /* pigpio already holds the main loop mutex; single-threaded context */
    static int in_freefall = 0;
    static int16_t x, y, z;

    if (level == 1) {
        in_freefall = 1;
    } else if (level == 0 && in_freefall) {
        in_freefall = 0;

        if (read_accel(g_i2c_fd, &x, &y, &z) == 0) {
            log_sample(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration during free-fall.\n");
        }
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby before closing */
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed.\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input with pull-up (INT1 is open-drain) */
    if (gpioSetMode(GPIO_INT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", GPIO_INT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(GPIO_INT_PIN, PI_PUD_UP);

    /* Register alert callback (rising edge = free-fall event) */
    if (gpioSetAlertFuncEx(GPIO_INT_PIN, freefall_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert on GPIO%d.\n", GPIO_INT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("freefall_log.csv", "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open freefall_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* Main loop: sleep until signal received */
    while (g_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

