/*
 * LSM6DSR IMU Fall-Detection Logger for Raspberry Pi 3 Model B+
 * I2C bus 1, SDA=GPIO2, SCL=GPIO3 (BCM)
 * Logs CSV: timestamp,ax,ay,az,gx,gy,gz,fall_state
 * Build: gcc -O2 -Wall -o fall_detect fall_detect.c -lm -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- LSM6DSR register definitions ---- */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_L_XL  0x28

#define LSM6DSR_WHO_AM_I_VAL 0x6A

/* ---- Fall-detection thresholds ---- */
#define FREEFALL_THRESHOLD_G  0.2f
#define IMPACT_THRESHOLD_G    2.5f
#define FREEFALL_TIME_WINDOW  1.0f   /* seconds */
#define SAMPLE_PERIOD_US      9600   /* 104 Hz */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C short read at reg 0x%02X: got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ---- Sensor data structure ---- */
typedef struct {
    float ax, ay, az;
    float gx, gy, gz;
} sensor_data_t;

/* ---- Fall-state machine ---- */
typedef enum { STATE_IDLE, STATE_FREEFALL, STATE_IMPACT } fall_state_t;

static fall_state_t fall_state = STATE_IDLE;
static struct timespec freefall_start = {0, 0};
static bool freefall_active = false;

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

/* ---- CSV logging ---- */
static void log_data(const sensor_data_t *d, fall_state_t state) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%d\n",
            ts, d->ax, d->ay, d->az, d->gx, d->gy, d->gz, state);
    fflush(g_log);
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int handle) {
    uint8_t who = 0;
    if (i2c_read_reg(handle, LSM6DSR_WHO_AM_I, &who, 1) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* ±2 g, 104 Hz ODR (0x40) */
    if (i2c_write_reg(handle, LSM6DSR_CTRL1_XL, 0x40) < 0) return -1;
    /* ±250 dps, 104 Hz ODR (0x40) */
    if (i2c_write_reg(handle, LSM6DSR_CTRL2_G, 0x40) < 0) return -1;
    return 0;
}

/* ---- Read 6 bytes of accel/gyro data ---- */
static int read_sensor_data(int handle, sensor_data_t *out) {
    uint8_t buf[6];
    if (i2c_read_reg(handle, LSM6DSR_OUTX_L_XL, buf, 6) < 0) return -1;

    int16_t raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_az = (int16_t)((buf[5] << 8) | buf[4]);

    int16_t raw_gx = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_gy = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_gz = (int16_t)((buf[11] << 8) | buf[10]);

    /* ±2 g range → 16384 LSB/g */
    out->ax = (float)raw_ax / 16384.0f;
    out->ay = (float)raw_ay / 16384.0f;
    out->az = (float)raw_az / 16384.0f;
    /* ±250 dps range → 131 LSB/dps */
    out->gx = (float)raw_gx / 131.0f;
    out->gy = (float)raw_gy / 131.0f;
    out->gz = (float)raw_gz / 131.0f;
    return 0;
}

/* ---- Update fall state machine ---- */
static void update_fall_state(const sensor_data_t *d) {
    float mag = sqrtf(d->ax * d->ax + d->ay * d->ay + d->az * d->az);

    if (mag < FREEFALL_THRESHOLD_G) {
        if (!freefall_active) {
            freefall_active = true;
            freefall_start = *clock_gettime(NULL);
        } else {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            double elapsed = (now.tv_sec - freefall_start.tv_sec) +
                             (now.tv_nsec - freefall_start.tv_nsec) / 1e9;
            if (mag > IMPACT_THRESHOLD_G && elapsed <= FREEFALL_TIME_WINDOW) {
                fall_state = STATE_IMPACT;
            } else {
                fall_state = STATE_FREEFALL;
            }
        }
    } else {
        fall_state = STATE_IDLE;
        freefall_active = false;
    }
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_log) { fclose(g_log); g_log = NULL; }
    if (g_i2c_handle >= 0) { i2cClose(g_i2c_handle); g_i2c_handle = -1; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, 0x69, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen("motion_log.txt", "a");
    if (!g_log) {
        perror("fopen motion_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps,fall_state\n");
    fflush(g_log);

    while (g_running) {
        sensor_data_t d;
        if (read_sensor_data(g_i2c_handle, &d) < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        update_fall_state(&d);
        log_data(&d, fall_state);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

