        if (read_sensor_data(g_i2c_handle, &d) < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        update_fall_state(&d);
        log_data(&d, fall_state);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
