/*
 * ADIS16266 Gyroscope Logger for Raspberry Pi 3 Model B+
 * SPI0 CE0 (GPIO8), Mode 3 (CPOL=1, CPHA=1), 1 MHz, 16-bit register reads.
 * Logs angular-rate data to gyro_log.csv at 10 ms intervals.
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c -lpigpio -lrt
 * Run:   sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16266 register map (subset) ---- */
#define ADIS16266_REG_WHO_AM_I      0x00
#define ADIS16266_REG_GLOB_CMD      0x04
#define ADIS16266_REG_GLOB_STATUS   0x05
#define ADIS16266_REG_TEMP_OUT      0x08
#define ADIS16266_REG_GYRO_OUT_X    0x0A
#define ADIS16266_REG_GYRO_OUT_Y    0x0C
#define ADIS16266_REG_GYRO_OUT_Z    0x0E

#define ADIS16266_WHO_AM_I_VAL      0x01
#define ADIS16266_GLOB_CMD_RESET    0x80
#define ADIS16266_GLOB_CMD_START    0x01

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz */
#define SPI_FLAGS   0x3              /* Mode 3: CPOL=1, CPHA=1 */
#define SAMPLE_US   10000            /* 10 ms */
#define LOG_FILE    "gyro_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266.                          */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int adis16266_read_reg(int handle, uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    /* Read command: OR address with bit 7 */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register on the ADIS16266.                           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adis16266_write_reg(int handle, uint8_t reg, int16_t val)
{
    char tx[2];
    char rx[2];

    /* Write command: clear bit 7 */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)(val & 0xFF);

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write transfer failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adis16266_init(int handle)
{
    int16_t who;

    /* Reset the device */
    if (adis16266_write_reg(handle, ADIS16266_REG_GLOB_CMD,
                            ADIS16266_GLOB_CMD_RESET) != 0)
        return -1;

    gpioDelay(10000);  /* 10 ms settle after reset */

    /* Verify identity */
    if (adis16266_read_reg(handle, ADIS16266_REG_WHO_AM_I, &who) != 0)
        return -1;

    if (who != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    /* Start autonomous mode */
    if (adis16266_write_reg(handle, ADIS16266_REG_GLOB_CMD,
                            ADIS16266_GLOB_CMD_START) != 0)
        return -1;

    gpioDelay(10000);  /* 10 ms for first sample */
    return 0;
}

/* ------------------------------------------------------------------ */
static int adis16266_read_gyro(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg(handle, ADIS16266_REG_GYRO_OUT_X, &raw_x) != 0)
        return -1;
    if (adis16266_read_reg(handle, ADIS16266_REG_GYRO_OUT_Y, &raw_y) != 0)
        return -1;
    if (adis16266_read_reg(handle, ADIS16266_REG_GYRO_OUT_Z, &raw_z) != 0)
        return -1;

    /* Scale factor: 0.0305 deg/sec per LSB (from datasheet) */
    *x = (float)raw_x * 0.0305f;
    *y = (float)raw_y * 0.0305f;
    *z = (float)raw_z * 0.0305f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open SPI ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz, flags 0x%02X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file once ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,angular_rate_x,angular_rate_y,angular_rate_z\n");
        fflush(g_log_file);
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- init sensor ---- */
    if (adis16266_init(g_spi_handle) != 0) {
        fprintf(stderr, "ADIS16266 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16266 initialised. Logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        float x, y, z;

        if (adis16266_read_gyro(g_spi_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
            printf("X: %.4f  Y: %.4f  Z: %.4f  deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Gyro read error — continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

