#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* GY-50 L3G4200D I2C address (SA0 tied to VDD on the breakout) */
#define GYRO_ADDR 0x6A

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28
#define OUT_X_H    0x29
#define OUT_Y_L    0x2A
#define OUT_Y_H    0x2B
#define OUT_Z_L    0x2C
#define OUT_Z_H    0x2D

/* Expected chip ID */
#define L3G4200D_ID 0xD3

/* Sensitivity: 8.75 mdps/LSB => 1 / 8.75 = 0.11428571 (1/114.285) */
#define GYRO_SENSITIVITY 114.285f

#define SAMPLE_PERIOD_US 10000  /* 10 ms */
#define I2C_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        usleep(1000);
    }
    return -1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        usleep(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Gyroscope operations                                                */
/* ------------------------------------------------------------------ */
static int gyro_init(int handle)
{
    uint8_t id = 0;

    /* Verify chip ID */
    if (i2c_read_block(handle, WHO_AM_I, &id, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register: sensor absent or bus error.\n");
        return -1;
    }
    if (id != L3G4200D_ID) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                id, L3G4200D_ID);
        return -1;
    }

    /* CTRL_REG1: 100 Hz output data rate, normal mode, all axes enabled */
    if (i2c_write_byte(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1.\n");
        return -1;
    }

    /* CTRL_REG4: full-scale ±250 dps, continuous update, block data update disabled */
    if (i2c_write_byte(handle, CTRL_REG4, 0x80) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

static int gyro_read(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_block(handle, OUT_X_L, buf, 6) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus 1, addr 0x%02X): %s\n",
                GYRO_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("gyro_log.csv", "w");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "Timestamp,X,Y,Z\n");
    fflush(g_log_file);

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Gyroscope read failed; continuing.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

