#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

static void log_event(FILE *log_file, const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s – %s\n", timestamp, message);
        fflush(log_file);
    }
}

int main(void)
{
    FILE *log_file = NULL;
    int ret = EXIT_SUCCESS;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: could not open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input with internal pull-up */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl-C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* Main polling loop */
    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n",
                    FLAME_SENSOR_GPIO);
            log_event(log_file, "ERROR: sensor read failure");
        } else {
            const char *flame_detected_str =
                (sensor_value == 0) ? "YES" : "NO";

            printf("Flame detected: %s\n", flame_detected_str);

            if (sensor_value == 0) {
                log_event(log_file, flame_detected_str);
                printf("FLAME DETECTED!\n");
            } else {
                log_event(log_file, flame_detected_str);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return ret;
}

