#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S0001_ADDR   0x50
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */
#define CSV_FILENAME   "vibration_log.csv"

/* D7S-0001 register addresses (16-bit, big-endian on the bus) */
#define REG_X_LSB      0x04
#define REG_X_MSB      0x05
#define REG_Y_LSB      0x06
#define REG_Y_MSB      0x07
#define REG_Z_LSB      0x08
#define REG_Z_MSB      0x09
#define REG_STATUS     0x0A
#define REG_CTRL       0x0B

/* Status-register bits */
#define STATUS_ERR     0x01
#define STATUS_BUSY    0x02

/* CTRL register bits */
#define CTRL_START     0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a 16-bit register address (big-endian on the bus). */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg8(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a 16-bit register address (big-endian on the bus). */
static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "i2c_read_reg8(0x%04X): write addr: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%04X): read data: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers. */
static int i2c_read_reg16(int fd, uint16_t reg_lsb, int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* Initialise the D7S-0001: clear any latched error, then start measurements. */
static int d7s_init(int fd)
{
    uint8_t status;
    if (i2c_read_reg8(fd, REG_STATUS, &status) < 0)
        return -1;
    if (status & STATUS_ERR) {
        fprintf(stderr, "D7S-0001: status error flag set (0x%02X)\n", status);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_CTRL, 0x00) < 0)
        return -1;
    usleep(10000);  /* allow registers to settle */
    if (i2c_write_reg8(fd, REG_CTRL, CTRL_START) < 0)
        return -1;
    usleep(10000);  /* first conversion takes ~10 ms */
    return 0;
}

/* Read X, Y, Z acceleration. Returns 0 on success, -1 on error. */
static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t status;
    if (i2c_read_reg8(fd, REG_STATUS, &status) < 0)
        return -1;
    if (status & STATUS_BUSY) {
        fprintf(stderr, "D7S-0001: measurement busy (status=0x%02X)\n", status);
        return -1;
    }
    if (status & STATUS_ERR) {
        fprintf(stderr, "D7S-0001: status error flag set (0x%02X)\n", status);
        return -1;
    }
    if (i2c_read_reg16(fd, REG_X_LSB, x) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, y) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, z) < 0)
        return -1;
    return 0;
}

/* Append one CSV line. Returns 0 on success, -1 on error. */
static int log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to CSV: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() on CSV: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S0001_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                D7S0001_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Sensor-absent / bus-error detection */
    uint8_t probe;
    if (i2c_read_reg8(g_i2c_fd, REG_STATUS, &probe) < 0) {
        fprintf(stderr, "D7S-0001 not responding at 0x%02X on %s\n",
                D7S0001_ADDR, I2C_BUS);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S-0001 initialisation failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILENAME, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_csv);
    if (pos == 0) {
        if (fprintf(g_csv, "Timestamp,X,Y,Z\n") < 0 || fflush(g_csv) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(g_csv);
            g_csv = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
    }

    printf("Logging D7S-0001 vibration data to %s (Ctrl+C to stop)\n", CSV_FILENAME);

    while (g_running) {
        int16_t x, y, z;
        if (d7s_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_sample(g_csv, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample\n");
        }
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

