#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_sensor_data(FILE *fp, int sensor1_value, int sensor2_value) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    long milliseconds = ts.tv_nsec / 1000000L;

    if (fprintf(fp, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
                timestamp, milliseconds, sensor1_value, sensor2_value) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d: %s\n",
                SENSOR_1_GPIO, strerror(errno));
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d: %s\n",
                SENSOR_2_GPIO, strerror(errno));
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d: %s\n",
                SENSOR_1_GPIO, strerror(errno));
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d: %s\n",
                SENSOR_2_GPIO, strerror(errno));
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring DRV5032 Hall sensors on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (program_running) {
        int sensor1_value = gpioRead(SENSOR_1_GPIO);
        int sensor2_value = gpioRead(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "gpioRead error: sensor1=%d, sensor2=%d\n",
                    sensor1_value, sensor2_value);
            break;
        }

        if (log_sensor_data(fp, sensor1_value, sensor2_value) != 0) {
            fprintf(stderr, "Failed to log sensor data.\n");
            break;
        }

        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("Conveyor halted!\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (fclose(fp) != 0) {
        perror("fclose");
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

