#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1D
#define LIS3MDL_WHO_AM_I 0x0F
#define LIS3MDL_WHO_AM_I_VAL 0x3D
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG2 0x21
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L  0x28
#define LIS3MDL_OUT_X_H  0x29
#define LIS3MDL_OUT_Y_L  0x2A
#define LIS3MDL_OUT_Y_H  0x2B
#define LIS3MDL_OUT_Z_L  0x2C
#define LIS3MDL_OUT_Z_H  0x2D

#define METAL_THRESHOLD 800.0f
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LIS3MDL_WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG1, 0x70) < 0) return -1;
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG4, 0x0C) < 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Z_H, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *cal_x, float *cal_y, float *cal_z) {
    *cal_x = (float)raw_x * 0.146f;
    *cal_y = (float)raw_y * 0.146f;
    *cal_z = (float)raw_z * 0.146f;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_data(FILE *fp, float x, float y, float z, float magnitude) {
    fprintf(fp, "%.2f,%.2f,%.2f,%.2f\n", x, y, z, magnitude);
    fflush(fp);
}

static void check_metal_detection(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "METAL DETECTED at %s (mag=%.2f mG)\n", ts, magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (init_lis3mdl(g_i2c_fd) == 0) break;
        retries++;
        if (retries < MAX_RETRIES) usleep(100000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "LIS3MDL init failed after %d retries\n", MAX_RETRIES);
        close(g_i2c_fd);
        return 1;
    }

    g_log_file = fopen("magnetic_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at 10 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        float cal_x, cal_y, cal_z, magnitude;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        magnitude = calculate_magnitude(cal_x, cal_y, cal_z);

        log_data(g_log_file, cal_x, cal_y, cal_z, magnitude);
        check_metal_detection(magnitude);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) fclose(g_log_file);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

