/*
 * ADXL354B Vibration Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B CS  -> GPIO8  (SPI0 CE0)
 *   ADXL354B SDO -> GPIO9  (SPI0 MISO)
 *   ADXL354B SDA -> GPIO10 (SPI0 MOSI)
 *   ADXL354B SCL -> GPIO11 (SPI0 SCLK)
 *   ADXL354B VDD -> 3.3 V
 *   ADXL354B GND -> GND
 *
 * Build: gcc -O2 -Wall -o vibration_monitor vibration_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        0

#define LOG_FILE        "vibration_log.txt"
#define SAMPLE_DELAY_MS 100
#define MAX_RETRIES     3

/* ADXL354B register addresses */
#define REG_DEVID_AD    0x00
#define REG_PARTID      0x02
#define REG_XDATA_L     0x08
#define REG_XDATA_H     0x09
#define REG_YDATA_L     0x0A
#define REG_YDATA_H     0x0B
#define REG_ZDATA_L     0x0C
#define REG_ZDATA_H     0x0D
#define REG_STATUS      0x0E
#define REG_POWER_CTRL  0x2C
#define REG_SOFT_RESET  0x1F

#define EXPECTED_PARTID 0x0B

/* Status register bits */
#define STATUS_STABLE   0x01
#define STATUS_RUN      0x02

/* Power control register bits */
#define POWER_CTRL_RUN   0x01

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 2) == 0) {
            *value = rx[1];
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int spi_write_register(uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0, 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 2) == 0)
            return 0;
        usleep(1000);
    }
    return -1;
}

static int spi_read_block(uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t tx[len + 1];
    uint8_t rx[len + 1];

    memset(tx, 0, sizeof(tx));
    tx[0] = (uint8_t)(reg | 0x80 | 0x40); /* read + multi-byte */

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, len + 1) == 0) {
            memcpy(buf, rx + 1, len);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int adxl354b_reset(void)
{
    if (spi_write_register(REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(1000);

    if (spi_write_register(REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(1000);

    return 0;
}

static int adxl354b_init(void)
{
    uint8_t partid = 0;

    if (spi_read_register(REG_PARTID, &partid) < 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != EXPECTED_PARTID) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n",
                partid, EXPECTED_PARTID);
        return -1;
    }

    if (adxl354b_reset() < 0) {
        fprintf(stderr, "Reset failed\n");
        return -1;
    }

    if (spi_write_register(REG_POWER_CTRL, 0x00) < 0) {
        fprintf(stderr, "Failed to clear RUN bit\n");
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        uint8_t status = 0;
        if (spi_read_register(REG_STATUS, &status) < 0) {
            fprintf(stderr, "Failed to read status\n");
            return -1;
        }
        if (status & STATUS_STABLE)
            break;
        usleep(1000);
    }
    if (!(status & STATUS_STABLE)) {
        fprintf(stderr, "Sensor not stable\n");
        return -1;
    }

    if (spi_write_register(REG_POWER_CTRL, POWER_CTRL_RUN) < 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        return -1;
    }
    usleep(1000);

    return 0;
}

static int read_acceleration(int32_t *x, int32_t *y, int32_t *z)
{
    uint8_t data[6];

    if (spi_read_block(REG_XDATA_L, data, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    int32_t x_raw = ((int32_t)data[1] << 8) | data[0];
    int32_t y_raw = ((int32_t)data[3] << 8) | data[2];
    int32_t z_raw = ((int32_t)data[5] << 8) | data[4];

    /* 20-bit left-justified two's complement */
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    *x = x_raw; *y = y_raw; *z = z_raw;
    return 0;
}

static void log_data(int32_t x, int32_t y, int32_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(g_log_fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto cleanup;
    }

    if (adxl354b_init() < 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        goto cleanup;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int32_t x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

cleanup:
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_SUCCESS;
}

