/*
 * ADIS16362 IMU SPI reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADIS16362 CS  -> GPIO 8  (BCM 8, SPI CE0)
 *   ADIS16362 SCLK-> GPIO 11 (BCM 11, SPI SCLK)
 *   ADIS16362 DOUT-> GPIO 9  (BCM 9, SPI MISO)
 *   ADIS16362 DIN -> GPIO 10 (BCM 10, SPI MOSI)
 *   ADIS16362 VDD -> 3.3 V
 *   ADIS16362 GND -> GND
 *
 * SPI: 1 MHz, Mode 3 (active-high clock, sampled on trailing edge).
 * Read protocol: send [0x80 | addr], 0x00, then read 16 bits.
 * Scale: gyro 0.05 deg/sec/LSB, accel 0.0025 g/LSB.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_BAUD       1000000          /* 1 MHz */
#define SPI_FLAGS      0x3              /* Mode 3: active-high clock, MSB first */
#define CS_PIN         8                /* BCM 8 = CE0 */
#define SAMPLE_US      10000            /* 10 ms -> ~100 Hz */
#define GYRO_LSB_DEG   0.05f
#define ACCEL_LSB_G    0.0025f

#define REG_GLOB_CMD   0x00
#define REG_GYRO_XOUT  0x04
#define REG_ACCEL_XOUT 0x08

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362                          */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, int16_t *out)
{
    char tx[3] = { (char)(0x80 | (reg & 0x3F)), 0x00, 0x00 };
    char rx[3] = { 0, 0, 0 };

    if (spiXfer(handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of 6 registers (gyro + accel)                          */
/* ------------------------------------------------------------------ */
static int read_block(int handle, int16_t gyro[3], int16_t accel[3])
{
    char tx[24] = { 0 };
    char rx[24] = { 0 };

    for (int i = 0; i < 6; i++) {
        tx[i * 3]     = (char)(0x80 | (REG_GYRO_XOUT + i & 0x3F));
        tx[i * 3 + 1] = 0x00;
        tx[i * 3 + 2] = 0x00;
    }

    if (spiXfer(handle, tx, rx, 24) != 24) {
        fprintf(stderr, "SPI block transfer failed\n");
        return -1;
    }

    for (int i = 0; i < 3; i++) {
        gyro[i]  = (int16_t)(((uint8_t)rx[i * 3 + 1] << 8) | (uint8_t)rx[i * 3 + 2]);
        accel[i] = (int16_t)(((uint8_t)rx[i * 3 + 3] << 8) | (uint8_t)rx[i * 3 + 4]);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row                                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const struct timespec *ts,
                     float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts->tv_sec, ts->tv_nsec,
            gx, gy, gz, ax, ay, az);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- CSV open ---- */
    g_log_file = fopen("imu_log.csv", "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    /* ---- signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- main loop ---- */
    int16_t gyro[3], accel[3];
    struct timespec ts;

    while (g_running) {
        if (read_block(g_spi_handle, gyro, accel) != 0) {
            /* SPI error already reported; skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        float gx = (float)gyro[0] * GYRO_LSB_DEG;
        float gy = (float)gyro[1] * GYRO_LSB_DEG;
        float gz = (float)gyro[2] * GYRO_LSB_DEG;
        float ax = (float)accel[0] * ACCEL_LSB_G;
        float ay = (float)accel[1] * ACCEL_LSB_G;
        float az = (float)accel[2] * ACCEL_LSB_G;

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_data(g_log_file, &ts, gx, gy, gz, ax, ay, az);

        gpioDelay(SAMPLE_US);
    }

    /* ---- graceful shutdown ---- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

