#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_sensor_data(int s1, int s2) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "unknown-time");
    }

    printf("[%s] Sensor 1 (GPIO%d): %s | Sensor 2 (GPIO%d): %s\n",
           timestamp, SENSOR_1_PIN,
           (s1 == 0) ? "OBSTACLE" : "CLEAR",
           SENSOR_2_PIN,
           (s2 == 0) ? "OBSTACLE" : "CLEAR");
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(SENSOR_1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(SENSOR_2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "ky032_sensor1") < 0) {
        perror("gpiod_line_request_input(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "ky032_sensor2") < 0) {
        perror("gpiod_line_request_input(line2)");
        goto cleanup;
    }

    printf("KY032 IR obstacle-avoidance sensor polling started.\n");
    printf("  Sensor 1: GPIO%d | Sensor 2: GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading GPIO lines (s1=%d, s2=%d).\n", v1, v2);
            break;
        }

        log_sensor_data(v1, v2);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

