/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * SPI0 CE0 (GPIO8, BCM 8)  ->  /dev/spidev0.0
 * SPI Mode 3 (CPOL=1, CPHA=1), 1 MHz, MSB first
 * Two-transfer read: [addr|0x80] [reg] -> [data_lo, data_hi]
 * Scale factor: 0.02 deg/sec per LSB
 *
 * Build:  gcc -O2 -Wall -o adis16266 adis16266.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define GYRO_REG_XGYRO_OUT  0x04
#define GYRO_REG_YGYRO_OUT  0x06
#define GYRO_REG_ZGYRO_OUT  0x08

#define GYRO_SCALE_FACTOR  0.02f   /* deg/sec per LSB */

#define SAMPLE_PERIOD_MS   100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
