#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR register addresses (from datasheet) */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_L_XL  0x28

/* Expected device ID */
#define LSM6DSR_WHO_AM_I_VAL 0x6A

/* pigpio I2C handle */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown (Ctrl+C)                          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialize the LSM6DSR                                               */
/* ------------------------------------------------------------------ */
static bool init_lsm6dsr(void)
{
    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read of WHO_AM_I failed (pigpio error %d).\n", who);
        return false;
    }
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return false;
    }

    /* Accelerometer: 100 Hz, +/- 2 g, normal mode */
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1_XL.\n");
        return false;
    }

    /* Gyroscope: 100 Hz, 245 dps, normal mode */
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error: failed to write CTRL2_G.\n");
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer and gyroscope data                   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static bool read_imu_data(int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buffer[6];

    /* Burst read 6 bytes starting at OUTX_L_G (accelerometer data
       follows gyroscope data in the 6DSR). */
    int n = i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 6);
    if (n != 6) {
        fprintf(stderr, "Error: I2C burst read returned %d bytes (expected 6).\n", n);
        return false;
    }

    /* LSM6DSR data order: G X Y Z, then X Y Z (accelerometer) */
    *gx = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *gy = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *gz = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    *ax = (int16_t)((buffer[7] << 8) | (uint8_t)buffer[6]);
    *ay = (int16_t)((buffer[9] << 8) | (uint8_t)buffer[8]);
    *az = (int16_t)((buffer[11] << 8) | (uint8_t)buffer[10]);

    return true;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x69 (SA0 tied high on LSM6DSR) */
    i2c_handle = i2cOpen(1, 0x69, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (pigpio error %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (!init_lsm6dsr()) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR ready. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_imu_data(&ax, &ay, &az, &gx, &gy, &gz)) {
            printf("%d %d %d %d %d %d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: read failed, continuing.\n");
        }

        /* Sleep 100 ms; gpioDelay is a pigpio busy-wait-free sleep */
        gpioDelay(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

