/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int fxos8700_init(int handle)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (i2c_read_reg(handle, FXOS8700_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read FXOS8700 ID register.\n");
        return -1;
    }
    if (id != FXOS8700_ID_VALUE) {
        fprintf(stderr, "FXOS8700 not detected (ID=0x%02X, expected 0x%02X).\n",
                id, FXOS8700_ID_VALUE);
        return -1;
    }
    printf("FXOS8700 detected (ID=0x%02X).\n", id);

    /* Standby mode so configuration changes take effect */
    if (i2c_write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

