#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DEVID 0x00
#define ADXL345_DEVID_VALUE 0xE5

#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_adxl345(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: ADXL345 not found (DEVID=0x%02X, expected 0x%02X).\n", devid, ADXL345_DEVID_VALUE);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to POWER_CTL register.\n");
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write to POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_DATAX0, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read acceleration data.\n");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_d = (double)x;
    double y_d = (double)y;
    double z_d = (double)z;
    double tilt = atan2(y_d, sqrt(x_d * x_d + z_d * z_d)) * 180.0 / M_PI;
    if (tilt < 0) tilt = -tilt;
    return tilt;
}

static void log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt angle exceeded threshold: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    if (init_adxl345(fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("ADXL345 initialized. Monitoring tilt...\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
            usleep(100000);
            continue;
        }

        double tilt_angle = calculate_tilt_angle(x, y, z);
        printf("Tilt Angle: %.2f degrees\n", tilt_angle);

        if (tilt_angle > TILT_THRESHOLD) {
            log_tilt_event(tilt_angle);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00);
    close(fd);
    return 0;
}

