#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_DURATION_S 5
#define PAUSE_DURATION_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d.\n", SENSOR_PIN);
        return -1;
    }
    return value;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold: %ld high readings in %d s.\n",
           SENSOR_PIN, threshold, WINDOW_DURATION_S);
    fflush(stdout);

    while (g_running) {
