/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12 V electromagnetic door locks via TIP120-driven 5 V
 * active-HIGH relay modules on GPIO17 (Door A) and GPIO27 (Door B).
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define CODE_MIN    100000
#define CODE_MAX    999999
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(void)
{
    return (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
}

static int unlock_door(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(HIGH)");
        return -1;
    }
    sleep(UNLOCK_SEC);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOW)");
        return -1;
    }
    return 0;
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(access_log.txt)");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    srand((unsigned)time(NULL));

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(gpiochip4)");
        return EXIT_FAILURE;
    }

    struct gpiod_line *door_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *door_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(door_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(door_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_B_PIN)");
        gpiod_line_release(door_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Door access control system started.\n");
    printf("Door A: GPIO%d | Door B: GPIO%d\n", DOOR_A_PIN, DOOR_B_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int code = generate_code();
        printf("Generated code: %d\n", code);

        printf("Enter code: ");
        fflush(stdout);

        char input[8];
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            perror("fgets()");
            continue;
        }

        input[strcspn(input, "\n")] = '\0';

        if (input[0] == '\0') {
            printf("Invalid input. Please enter a code.\n");
            continue;
        }

        if (input[0] != '0' || input[1] != '0') {
            printf("Invalid code format. Must start with 00.\n");
            continue;
        }

        if (strlen(input) != 6) {
            printf("Invalid code length. Must be 6 digits.\n");
            continue;
        }

        for (int i = 0; input[i] != '\0'; i++) {
            if (!isdigit((unsigned char)input[i])) {
                printf("Invalid code. Must contain only digits.\n");
                goto retry;
            }
        }

        if (strcmp(input, "000000") == 0) {
            printf("Admin code entered. Unlocking doors for 5 seconds.\n");
            if (unlock_door(door_a) < 0) {
                fprintf(stderr, "Failed to unlock Door A.\n");
            }
            if (unlock_door(door_b) < 0) {
                fprintf(stderr, "Failed to unlock Door B.\n");
            }
            continue;
        }

        if (strcmp(input, "000000") != 0 && strcmp(input, "123456") == 0) {
            printf("Default code entered. Unlocking doors for 5 seconds.\n");
            if (unlock_door(door_a) < 0) {
                fprintf(stderr, "Failed to unlock Door A.\n");
            }
            if (unlock_door(door_b) < 0) {
                fprintf(stderr, "Failed to unlock Door B.\n");
            }
            continue;
        }

        if (strcmp(input, "000000") != 0 && strcmp(input, "123456") != 0) {
            printf("Access denied.\n");
            continue;
        }

        if (strcmp(input, "000000") == 0) {
            printf("Access granted. Logging to file.\n");
            if (log_access(input) < 0) {
                fprintf(stderr, "Failed to log access.\n");
            }
        } else if (strcmp(input, "123456") == 0) {
            printf("Access granted. Logging to file.\n");
            if (log_access(input) < 0) {
                fprintf(stderr, "Failed to log access.\n");
            }
        }

        printf("Generated code: %d\n", code);
        printf("Enter code: ");
        fflush(stdout);

    retry:
        fflush(stdout);
    }

    /* Ensure doors are locked on exit */
    gpiod_line_set_value(door_a, 0);
    gpiod_line_set_value(door_b, 0);

    gpiod_line_release(door_a);
    gpiod_line_release(door_b);
    gpiod_chip_close(chip);

    printf("Door access control system stopped.\n");
    return EXIT_SUCCESS;
}

