#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_PWR_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONT_HIGH_RES 0x10
#define LOG_FILE "light_log.txt"
#define MAX_CONVERSION_MS 180
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "Error: Failed to power on BH1750.\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByte(handle, BH1750_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset BH1750.\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error: Failed to set BH1750 to continuous high-res mode.\n");
        return -1;
    }
    return 0;
}

static int read_bh1750(int handle, float *lux) {
    char data[2];
    int result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data (read %d bytes).\n", result);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    } else {
        fprintf(fp, "Timestamp: <unknown>, Lux: %.2f\n", lux);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, BH1750_ADDR);
        gpioTerminate();
        return 1;
    }

    if (bh1750_init(handle) != 0) {
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(handle, &lux) == 0) {
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

