static void play_tone(int frequency) {
    if (frequency <= 0) {
        gpioPWM(PWM_PIN, 0);
        return;
    }
    int range = 1000000 / frequency;
    if (range < 2) range = 2;
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioSetPWMrange(PWM_PIN, range);
    gpioPWM(PWM_PIN, range / 2);
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
}

