/*
 * LSM303DLHC magnetometer reader with PWM LED feedback on Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303DLHC SDA  -> Pi SDA1  (GPIO2 / physical pin 3)
 *   LSM303DLHC SCL  -> Pi SCL1  (GPIO3 / physical pin 5)
 *   LSM303DLHC VCC  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *   LED anode       -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_led mag_led.c -lpigpio -lrt -lm
 *   (pigpio must be installed and the user must be in the 'gpio' group.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define LSM303_ADDR      0x19          /* SA0 tied to VCC on LSM303DLHC */
#define MAG_REG_X_OUT_L  0x08          /* first magnetometer data register */
#define MAG_REG_CTRL_REG1 0x20
#define CTRL_REG1_VAL    0x70          /* temp comp, 80 Hz, normal mode */
#define LED_GPIO         17
#define PWM_RANGE        255
#define PWM_FREQ         1000          /* Hz */
#define SAMPLE_PERIOD_US 100000        /* 100 ms */
#define MAX_CONSEC_ERR   10

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Prototypes ---- */
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len);
static int  read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z);
static void set_led_brightness(int gpio, int brightness);
static void log_error(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/*  I2C helpers                                                       */
/* ------------------------------------------------------------------ */

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(fd, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len)
{
    if (i2cWriteDevice(fd, (char *)&reg, 1) != 1) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    if (i2cReadDevice(fd, (char *)buf, len) != (int)len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Magnetometer                                                       */
/* ------------------------------------------------------------------ */

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (i2c_read_block(fd, MAG_REG_X_OUT_L, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/*  LED control                                                         */
/* ------------------------------------------------------------------ */

static void set_led_brightness(int gpio, int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    if (gpioPWM(gpio, brightness) != 0)
        log_error("gpioPWM failed");
}

/* ------------------------------------------------------------------ */
/*  Error logging                                                      */
/* ------------------------------------------------------------------ */

static void log_error(const char *msg)
{
    if (g_log_fp) {
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        fprintf(g_log_fp, "[%s] ERROR: %s\n", ts, msg);
        fflush(g_log_fp);
    }
    fprintf(stderr, "ERROR: %s\n", msg);
}

/* ------------------------------------------------------------------ */
/*  Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    set_led_brightness(LED_GPIO, 0);

    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    int16_t x, y, z;
    int consecutive_errors = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen("mag_led.log", "a");
    if (!g_log_fp) {
        perror("fopen(mag_led.log)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_fd = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (g_i2c_fd < 0) {
        log_error("i2cOpen failed (sensor absent or bus error)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- configure magnetometer ---- */
    if (i2c_write_reg(g_i2c_fd, MAG_REG_CTRL_REG1, CTRL_REG1_VAL) != 0) {
        log_error("Failed to configure magnetometer");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- configure LED GPIO for PWM ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("gpioSetMode failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        log_error("gpioSetPWMrange failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        log_error("gpioSetPWMfrequency failed");
        cleanup();
        return EXIT_FAILURE;
    }
    set_led_brightness(LED_GPIO, 0);

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_error("Program started");

    /* ---- main loop ---- */
    while (g_running) {
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            consecutive_errors = 0;

            /* Z-axis magnitude */
            double mag = sqrt((double)x * x + (double)y * y + (double)z * z);

            /* Map 0..32760 (max 12-bit signed) to 0..255 */
            int brightness = (int)((mag / 32760.0) * PWM_RANGE);
            if (brightness < 0)   brightness = 0;
            if (brightness > PWM_RANGE) brightness = PWM_RANGE;

            set_led_brightness(LED_GPIO, brightness);

            if (g_log_fp) {
                time_t now = time(NULL);
                struct tm tm_buf;
                struct tm *t = localtime_r(&now, &tm_buf);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
                fprintf(g_log_fp, "[%s] X=%6d Y=%6d Z=%6d  mag=%.2f  brightness=%d\n",
                        ts, x, y, z, mag, brightness);
                fflush(g_log_fp);
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                log_error("Too many consecutive I2C errors; aborting");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    log_error("Program exiting");
    cleanup();
    return EXIT_SUCCESS;
}

