#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* HMC5883L I2C address (ADDR pin tied to GND) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

/* Configuration values */
#define HMC5883L_CONFIG_A_VAL 0x70  /* 8-average, 15 Hz, normal power */
#define HMC5883L_CONFIG_B_VAL 0x20  /* 1.3 Gauss gain */
#define HMC5883L_MODE_VAL    0x00  /* Continuous measurement */

/* Sampling parameters */
#define SAMPLE_PERIOD_US 500000   /* 500 ms */
#define NUM_SAMPLES      100      /* Running-average window */

/* Globals for signal-handler cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X, len=%u): %d\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C short read (reg=0x%02X): got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HMC5883L initialization                                             */
/* ------------------------------------------------------------------ */
static int hmc5883l_init(int handle)
{
    if (i2c_write_byte(handle, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VAL) < 0)
        return -1;
    if (i2c_write_byte(handle, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VAL) < 0)
        return -1;
    if (i2c_write_byte(handle, HMC5883L_MODE, HMC5883L_MODE_VAL) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw magnetometer data                                          */
/* ------------------------------------------------------------------ */
static int hmc5883l_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    /* Read 6 bytes starting at DATA_X_MSB: X(2), Z(2), Y(2) */
    if (i2c_read_block(handle, HMC5883L_DATA_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Running-average offset computation                                   */
/* ------------------------------------------------------------------ */
static void update_offsets(int16_t x, int16_t y, int16_t z,
                           double *x_off, double *y_off, double *z_off)
{
    static double x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;
    static int    count = 0;

    x_sum -= *x;
    y_sum -= *y;
    z_sum -= *z;

    x_sum += x;
    y_sum += y;
    z_sum += z;

    *x_off = x_sum / (double)(count + 1);
    *y_off = y_sum / (double)(count + 1);
    *z_off = z_sum / (double)(count + 1);

    count++;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    g_i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n",
                HMC5883L_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize magnetometer */
    if (hmc5883l_init(g_i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(100000);  /* 100 ms */

    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    double x_off = 0.0, y_off = 0.0, z_off = 0.0;

    printf("HMC5883L running-average offset correction started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (hmc5883l_read_raw(g_i2c_handle, &x, &y, &z) == 0) {
            update_offsets(x, y, z, &x_off, &y_off, &z_off);
            printf("X: %7d  Y: %7d  Z: %7d  |  X_off: %+.2f  Y_off: %+.2f  Z_off: %+.2f\n",
                   x, y, z, x_off, y_off, z_off);
        } else {
            fprintf(stderr, "Read error — continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

