/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO 2 (physical pin 3, I2C bus 1)
 *   LSM303D SCL  -> GPIO 3 (physical pin 5, I2C bus 1)
 *   LSM303D INT1 -> GPIO 23 (physical pin 16, rising edge triggers dump)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Run:
 *   ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register definitions (verified against datasheet) ---- */
#define LSM303D_ADDR            0x19
#define LSM303D_REG_ID          0x0F
#define LSM303D_REG_CTRL1       0x20
#define LSM303D_REG_CTRL2       0x21
#define LSM303D_REG_OUT_X_L_A   0x28
#define LSM303D_REG_OUT_X_H_A   0x29
#define LSM303D_REG_OUT_Y_L_A   0x2A
#define LSM303D_REG_OUT_Y_H_A   0x2B
#define LSM303D_REG_OUT_Z_L_A   0x2C
#define LSM303D_REG_OUT_Z_H_A   0x2D

#define LSM303D_ID_VALUE        0x49
#define LSM303D_CTRL1_VAL       0x57   /* 0b0101 0111: 12-bit, 50 Hz, normal mode */
#define LSM303D_CTRL2_VAL       0x00   /* 0b0000 0000: no interrupts, no reset */
#define LSM303D_INT1_VAL        0x00   /* 0b0000 0000: no interrupt */

#define ACCEL_SENSITIVITY_MG    0.061f  /* mg per LSB */
#define INTERRUPT_THRESHOLD_MG 2000.0f
#define BUFFER_SIZE             64
#define DUMP_COUNT              10

/* ---- Globals for signal handler and cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_int1 = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buffer[BUFFER_SIZE];
static int            g_head = 0;   /* next write slot */
static int            g_count = 0; /* valid samples */

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer read ---- */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, LSM303D_REG_OUT_X_L_A, &xl) ||
        i2c_read_reg8(fd, LSM303D_REG_OUT_X_H_A, &xh) ||
        i2c_read_reg8(fd, LSM303D_REG_OUT_Y_L_A, &yl) ||
        i2c_read_reg8(fd, LSM303D_REG_OUT_Y_H_A, &yh) ||
        i2c_read_reg8(fd, LSM303D_REG_OUT_Z_L_A, &zl) ||
        i2c_read_reg8(fd, LSM303D_REG_OUT_Z_H_A, &zh))
        return -1;

    int16_t rx = (int16_t)((xh << 8) | xl);
    int16_t ry = (int16_t)((yh << 8) | yl);
    int16_t rz = (int16_t)((zh << 8) | zl);

    *x = rx * ACCEL_SENSITIVITY_MG;
    *y = ry * ACCEL_SENSITIVITY_MG;
    *z = rz * ACCEL_SENSITIVITY_MG;
    return 0;
}

/* ---- Buffer management ---- */
static void buffer_add(int16_t x, int16_t y, int16_t z)
{
    g_buffer[g_head].x = x;
    g_buffer[g_head].y = y;
    g_buffer[g_head].z = z;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE) g_count++;
}

static void buffer_dump_last10(void)
{
    int start = (g_head - DUMP_COUNT + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d samples ---\n", DUMP_COUNT);
    for (int i = 0; i < DUMP_COUNT; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] X=%6d  Y=%6d  Z=%6d  mg\n",
               i, g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_REG_CTRL1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int1) {
        gpiod_line_release(g_int1);
        g_int1 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    uint8_t id = 0;
    if (i2c_read_reg8(g_i2c_fd, LSM303D_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read ID register: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (id != LSM303D_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X) - wrong device?\n",
                id, LSM303D_ID_VALUE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    printf("LSM303D detected (ID = 0x%02X)\n", id);

    /* ---- Configure accelerometer ---- */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_REG_CTRL1, LSM303D_CTRL1_VAL) != 0 ||
        i2c_write_reg8(g_i2c_fd, LSM303D_REG_CTRL2, LSM303D_CTRL2_VAL) != 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request INT1 line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_int1 = gpiod_chip_get_line(g_chip, 23);
    if (!g_int1) {
        fprintf(stderr, "Cannot get GPIO line 23: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1, "lsm303d_mon") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO 23: %s\n",
                strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Cannot install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring acceleration (INT1 on GPIO 23). Press Ctrl-C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /* Poll for interrupt event with 100 ms timeout */
        int ret = gpiod_line_event_wait(g_int1, &(struct timespec){0, 100000000});
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            /* Timeout - no event; just sample */
            float x, y, z;
            if (read_accel(g_i2c_fd, &x, &y, &z) == 0) {
                buffer_add((int16_t)(x / ACCEL_SENSITIVITY_MG),
                           (int16_t)(y / ACCEL_SENSITIVITY_MG),
                           (int16_t)(z / ACCEL_SENSITIVITY_MG));
            } else {
                fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
            }
            continue;
        }

        /* Event detected - read and dump */
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(g_int1, &ev) < 0) {
            fprintf(stderr, "Cannot read GPIO event: %s\n", strerror(errno));
            continue;
        }

        float x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) == 0) {
            buffer_add((int16_t)(x / ACCEL_SENSITIVITY_MG),
                       (int16_t)(y / ACCEL_SENSITIVITY_MG),
                       (int16_t)(z / ACCEL_SENSITIVITY_MG));
            buffer_dump_last10();
        } else {
            fprintf(stderr, "Warning: I2C read failed after interrupt\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

