#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS       500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_delay_ms(unsigned ms)
{
    struct timespec req = { ms / 1000, (long)(ms % 1000) * 1000000L };
    struct timespec rem;
    while (nanosleep(&req, &rem) < 0 && errno == EINTR) {
        req = rem;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SOLENOID_1_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure both solenoids are de-energized at startup. */
    if (safe_write(SOLENOID_1_PIN, 0) < 0 || safe_write(SOLENOID_2_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        safe_write(SOLENOID_1_PIN, 0);
        safe_write(SOLENOID_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int rc = EXIT_SUCCESS;

    while (g_running) {
        if (safe_write(active_pin, 1) < 0) {
            rc = EXIT_FAILURE;
            break;
        }
        active_pin = (active_pin == SOLENOID_1_PIN) ? SOLENOID_2_PIN : SOLENOID_1_PIN;

        if (!g_running) {
            break;
        }

        if (safe_write(active_pin, 0) < 0) {
            rc = EXIT_FAILURE;
            break;
        }

        if (!g_running) {
            break;
        }

        if (safe_delay_ms(DELAY_MS) < 0) {
            rc = EXIT_FAILURE;
            break;
        }
    }

    /* Clean shutdown: de-energize both solenoids and release pigpio. */
    safe_write(SOLENOID_1_PIN, 0);
    safe_write(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return rc;
}

