#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define TIMEOUT_SEC 5
#define RELAY_PULSE_SEC 2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d LOW\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d LOW\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_code(const char *port, char *code, int max_len) {
    int handle = serOpen(port, 9600, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", port, strerror(errno));
        return -1;
    }
    int idx = 0;
    int elapsed = 0;
    while (idx < max_len && elapsed < TIMEOUT_SEC && g_running) {
        int avail = serDataAvailable(handle);
        if (avail < 0) {
            fprintf(stderr, "serDataAvailable failed on %s\n", port);
            serClose(handle);
            return -1;
        }
        if (avail > 0) {
            int c = serReadByte(handle);
            if (c < 0) {
                fprintf(stderr, "serReadByte failed on %s\n", port);
                serClose(handle);
                return -1;
            }
            if (c >= '0' && c <= '9') {
                code[idx++] = (char)c;
            } else {
                idx = 0;
            }
        } else {
            gpioDelay(10000);
            elapsed++;
        }
    }
    serClose(handle);
    if (elapsed >= TIMEOUT_SEC) {
        fprintf(stderr, "Timeout reading code from %s\n", port);
        return -1;
    }
    code[idx] = '\0';
    return 0;
}

static int verify_code(const char *code) {
    if (strlen(code) != CODE_LENGTH) {
        fprintf(stderr, "Code length mismatch: %d\n", strlen(code));
        return -1;
    }
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (code[i] != EXPECTED_CODE[i]) {
            fprintf(stderr, "Code mismatch: expected '%c', got '%c'\n", EXPECTED_CODE[i], code[i]);
            return -1;
        }
    }
    return 0;
}

static int compare_codes(const char *a, const char *b) {
    int len_a = (int)strlen(a);
    int len_b = (int)strlen(b);
    int len = (len_a < len_b) ? len_a : len_b;
    for (int i = 0; i < len; i++) {
        if (a[i] != b[i]) return 0;
    }
    return (len_a == len_b) ? 1 : 0;
}

static int activate_locks(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    gpioDelay(RELAY_PULSE_SEC * 1000000);
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", LOCK2_GPIO);
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }
    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];
    while (g_running) {
        if (read_code("/dev/serial0", code1, CODE_LENGTH) == 0) {
            if (read_code("/dev/serial1", code2, CODE_LENGTH) == 0) {
                if (compare_codes(code1, code2) == 1 && verify_code(code1) == 0) {
                    printf("Codes match. Activating locks.\n");
                    if (activate_locks() != 0) {
                        fprintf(stderr, "Lock activation failed.\n");
                    } else {
                        printf("Locks deactivated.\n");
                    }
                } else {
                    fprintf(stderr, "Authentication failed.\n");
                }
            }
        }
        gpioDelay(100000);
    }
    cleanup_gpio();
    return EXIT_SUCCESS;
}

