/*
 * PIR-triggered door strike relay controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> physical GPIO4  (BCM 4, active-HIGH)
 *   - Door strike relay    -> physical GPIO17 (BCM 17, active-HIGH)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_strike pir_strike.c -lgpiod
 *
 * Run:
 *   sudo ./pir_strike   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN        4
#define RELAY_PIN      17
#define POLL_MS        50
#define RELAY_HOLD_MS  1000
#define MALFUNCTION_S  10

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
    if (priority == LOG_ERR)
        fprintf(stderr, "[syslog] %s\n", msg);
}

static void relay_log(int state)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;

    if (localtime_r(&now, &tmv))
        strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(ts, sizeof ts, "?");

    char msg[128];
    snprintf(msg, sizeof msg, "Relay %s (state=%d)", state ? "ACTIVATED" : "DE-ENERGIZED", state);
    syslog(LOG_INFO, "%s", msg);
}

static void failsafe(struct gpiod_line *relay)
{
    log_event(LOG_WARNING,
              "Failsafe: PIR held HIGH for >10 s — de-energizing relay and shutting down.");

    if (gpiod_line_set_value(relay, 0) < 0)
        log_event(LOG_ERR, "Failsafe: failed to de-energize relay.");

    relay_log(0);

    log_event(LOG_INFO, "Shutting down.");
    closelog();
    exit(EXIT_FAILURE);
}

int main(void)
{
    openlog("pir_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event(LOG_ERR, "sigaction failed: ");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_event(LOG_ERR, "gpiod_chip_open_by_name failed: ");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir) {
        log_event(LOG_ERR, "gpiod_chip_get_line(PIR) failed: ");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay) {
        log_event(LOG_ERR, "gpiod_chip_get_line(RELAY) failed: ");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir, "pir_strike") < 0) {
        log_event(LOG_ERR, "gpiod_line_request_input(PIR) failed: ");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "pir_strike", 0) < 0) {
        log_event(LOG_ERR, "gpiod_line_request_output(RELAY) failed: ");
        goto cleanup;
    }

    log_event(LOG_INFO, "PIR strike controller started.");

    time_t pir_start = 0;
    int relay_state = 0;

    while (g_running) {
        int val = gpiod_line_get_value(pir);
        if (val < 0) {
            log_event(LOG_ERR, "gpiod_line_get_value(PIR) failed: ");
            break;
        }

        if (val == 1) {
            if (pir_start == 0)
                pir_start = time(NULL);

            if (pir_start + MALFUNCTION_S <= time(NULL)) {
                failsafe(relay);
            }

            if (!relay_state) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    log_event(LOG_ERR, "gpiod_line_set_value(RELAY,1) failed: ");
                    break;
                }
                relay_state = 1;
                relay_log(1);
            }

            struct timespec ts = { RELAY_HOLD_MS / 1000, (RELAY_HOLD_MS % 1000) * 1000000L };
            nanosleep(&ts, NULL);
        } else {
            if (pir_start) {
                pir_start = 0;
                log_event(LOG_INFO, "PIR motion ended.");
            }
            if (relay_state) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    log_event(LOG_ERR, "gpiod_line_set_value(RELAY,0) failed: ");
                    break;
                }
                relay_state = 0;
                relay_log(0);
            }
        }

        struct timespec poll_ts = { 0, POLL_MS * 1000000L };
        nanosleep(&poll_ts, NULL);
    }

cleanup:
    if (relay) {
        if (gpiod_line_set_value(relay, 0) < 0)
            log_event(LOG_ERR, "cleanup: failed to de-energize relay: ");
        gpiod_line_release(relay);
    }
    if (pir)
        gpiod_line_release(pir);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

