#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_COUNT 4
#define RELAY_ON_TIME_SEC 300
#define RELAY_OFF_TIME_SEC 60
#define TIMER_INTERVAL_SEC 60

static volatile sig_atomic_t g_running = 1;

static const int relay_pins[RELAY_COUNT] = {
    RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN
};

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        log_msg(LOG_ERR, "Failed to write to GPIO pin");
        return -1;
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void cleanup(void) {
    deactivate_all_relays();
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_msg(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            log_msg(LOG_ERR, "Failed to set GPIO mode");
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            log_msg(LOG_ERR, "Failed to initialise relay to OFF");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, NULL, NULL) != 0) {
        log_msg(LOG_ERR, "Failed to set timer");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

