#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

#define RELAY1_INTERVAL_SEC 2
#define RELAY2_INTERVAL_SEC 3
#define RELAY3_INTERVAL_SEC 5
#define RELAY4_INTERVAL_SEC 7

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_relay(int gpio, int state)
{
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed: %s\n",
                gpio, state, strerror(errno));
        return -1;
    }
    return 0;
}

static int toggle_relay(int gpio, int interval_sec)
{
    if (set_relay(gpio, 1) != 0)
        return -1;

    struct timespec start, now;
    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        set_relay(gpio, 0);
        return -1;
    }

    while (g_running) {
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
            set_relay(gpio, 0);
            return -1;
        }
        double elapsed = (now.tv_sec - start.tv_sec)
                       + (now.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed >= (double)interval_sec)
            break;

        struct timespec sleep_ts = { 0, 100 * 1000 * 1000 }; /* 100 ms */
        nanosleep(&sleep_ts, NULL);
    }

    if (set_relay(gpio, 0) != 0)
        return -1;

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int gpios[] = { RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO };
    int intervals[] = {
        RELAY1_INTERVAL_SEC, RELAY2_INTERVAL_SEC,
        RELAY3_INTERVAL_SEC, RELAY4_INTERVAL_SEC
    };
    int num_relays = (int)(sizeof(gpios) / sizeof(gpios[0]));

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_relay(gpios[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise relay on GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Relay control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < num_relays && g_running; i++) {
            if (toggle_relay(gpios[i], intervals[i]) != 0) {
                fprintf(stderr, "Error: toggle_relay failed for GPIO %d\n", gpios[i]);
                goto cleanup;
            }
        }
    }

cleanup:
    for (int i = 0; i < num_relays; i++)
        set_relay(gpios[i], 0);
    gpioTerminate();
    printf("\nRelay control stopped.\n");
    return EXIT_SUCCESS;
}

