        return -1;
    }
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", ts) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sound sensor pin %d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started on GPIO%d. Relay on GPIO%d. Press Ctrl+C to exit.\n", SOUND_SENSOR_PIN, RELAY_PIN);

    while (running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);
        if (sound_detected < 0) {
            fprintf(stderr, "Error reading sound sensor pin %d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_detected) {
            printf("Sound detected! Activating relay for 3 seconds.\n");
            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate relay on pin %d\n", RELAY_PIN);
                break;
            }
            if (log_timestamp(LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to log timestamp.\n");
            }
            gpioDelay(RELAY_ACTIVE_US);
            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay on pin %d\n", RELAY_PIN);
                break;
            }
            printf("Relay deactivated.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

