#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define GYRO_SCALE 131.0
#define THRESHOLD 50.0
#define BUFFER_SIZE 100

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_GYRO_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;
    return 0;
}

void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) buffer->count++;
}

float calculate_magnitude(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

void check_threshold(circular_buffer_t *buffer, float threshold) {
    for (int i = 0; i < buffer->count; i++) {
        int idx = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        float mag = calculate_magnitude(buffer->data[idx]);
        if (mag > threshold) {
            printf("Threshold exceeded! Magnitude: %.2f\n", mag);
        }
    }
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to select I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return 1;
    }

    circular_buffer_t gyro_buffer = {0};
    gyro_data_t gyro_data;

    while (running) {
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            add_to_buffer(&gyro_buffer, gyro_data);
            check_threshold(&gyro_buffer, THRESHOLD);
        } else {
            fprintf(stderr, "Failed to read gyro data, retrying...\n");
        }
        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

