/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 @ 9600 baud (TXD=GPIO14, RXD=GPIO15, BCM)
 * Reads 9-byte response, validates checksum, logs to co2_log.json
 * Errors go to co2_error.log.  Clean shutdown on SIGINT/SIGTERM.
 *
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/stat.h>

#include <the_driver.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_INTERVAL_S  5
#define RESPONSE_TIMEOUT_MS 1000
#define RESPONSE_SIZE     9
#define POLL_TIMEOUT_MS  100

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helpers                                                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01 00:00:00");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    snprintf(buf, len, "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
             tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
             tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
             ts.tv_nsec / 1000);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s\n", ts, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                         */
/* ------------------------------------------------------------------ */
static int uart_open(void)
{
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        log_error("open() failed for UART device");
        return -1;
    }

    /* Clear O_NONBLOCK for blocking reads on the MH-Z19B */
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0 || fcntl(fd, F_SETFL, flags & ~O_NONBLOCK) < 0) {
        log_error("fcntl() failed to clear O_NONBLOCK");
        close(fd);
        return -1;
    }

    /* 9600 baud, 8N1, raw mode */
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr() failed");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  CS8 | CREAD | CLOCAL;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;   /* raw: no deadline */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr() failed");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/*
 * Send the 9-byte MH-Z19B request sequence:
 *   0x3F, 0x86, 0x00, 0x00, 0x00, 0x31, 0x00, 0x00, 0x00
 * Returns 0 on success, -1 on error.
 */
static int send_request(int fd)
{
    const uint8_t req[RESPONSE_SIZE] = {
        0x3F, 0x86, 0x00, 0x00, 0x00, 0x31, 0x00, 0x00, 0x00
    };

    ssize_t n = write(fd, req, RESPONSE_SIZE);
    if (n < 0) {
        log_error("write() failed sending request");
        return -1;
    }
    if ((size_t)n != RESPONSE_SIZE) {
        log_error("write() short write");
        return -1;
    }
    tcdrain(fd);
    return 0;
}

/*
 * Read exactly RESPONSE_SIZE bytes with timeout.
 * Returns 0 on success, -1 on timeout or error.
 */
static int read_response(int fd, uint8_t *buf)
{
    size_t total = 0;
    while (total < RESPONSE_SIZE) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv;
        tv.tv_sec  = POLL_TIMEOUT_MS / 1000;
        tv.tv_usec = (POLL_TIMEOUT_MS % 1000) * 1000;

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            log_error("select() error");
            return -1;
        }
        if (rv == 0) {
            log_error("select() timeout waiting for response");
            return -1;
        }

        ssize_t n = read(fd, buf + total, RESPONSE_SIZE - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_error("read() error");
            return -1;
        }
        if (n == 0) {
            log_error("read() returned 0 (EOF)");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/*
 * Validate the 9-byte response:
 *   [0..6] : 2-byte big-endian CO2 ppm, 2-byte big-endian PPM (same),
 *   [7]    : 1-byte checksum
 *   [8]    : 1-byte status (0x00 = OK, 0xFF = error)
 * Returns 0 on success, -1 on checksum mismatch, -2 on status error.
 */
static int validate_response(const uint8_t *resp)
{
    uint16_t co2_raw = ((uint16_t)resp[0] << 8) | resp[1];
    uint16_t co2_ppm = ((uint16_t)resp[2] << 8) | resp[3];
    uint8_t  checksum = resp[6];
    uint8_t  status   = resp[7];

    if (status != 0x00) {
        if (status == 0xFF) {
            log_error("MH-Z19B reported status 0xFF (error)");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "MH-Z19B status 0x%02X unexpected", status);
            log_error(msg);
        }
        return -2;
    }

    uint8_t calc = 0;
    for (int i = 0; i < 6; i++)
        calc += resp[i];
    if (calc != checksum) {
        char msg[80];
        snprintf(msg, sizeof(msg),
                 "Checksum mismatch: calc=0x%02X recv=0x%02X",
                 calc, checksum);
        log_error(msg);
        return -1;
    }

    if (co2_raw != co2_ppm) {
        char msg[80];
        snprintf(msg, sizeof(msg),
                 "CO2 raw=0x%04X ppm=0x%04X - inconsistent",
                 co2_raw, co2_ppm);
        log_error(msg);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                         */
/* ------------------------------------------------------------------ */
static int log_co2(int ppm, int error)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp) {
        fprintf(g_log_fp,
                "{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
                ts, ppm, error);
        fflush(g_log_fp);
    }
    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
           ts, ppm, error);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_uart_fd = uart_open();
    if (g_uart_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 monitor started.  UART=%s  Log=%s  Err=%s\n",
           UART_DEVICE, LOG_FILE, ERROR_LOG_FILE);

    while (g_running) {
        if (send_request(g_uart_fd) != 0) {
            log_error("Failed to send request");
            sleep(READ_INTERVAL_S);
            continue;
        }

        uint8_t resp[RESPONSE_SIZE];
        if (read_response(g_uart_fd, resp) != 0) {
            log_error("Failed to read response");
            sleep(READ_INTERVAL_S);
            continue;
        }

        int ppm = -1;
        int err = 0;
        int rc = validate_response(resp);
        if (rc == 0) {
            ppm = (int)resp[2];   /* byte 3 of the 9-byte frame */
        } else if (rc == -1) {
            err = 1;
        } else {
            err = 1;
        }

        log_co2(ppm, err);

        /* Sleep READ_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < READ_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

