#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <string.h>

/* HMC5883L I2C address (ADDR pin tied to GND) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

/* GPIO pin for alert output (BCM numbering) */
#define ALERT_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Hard iron compensation offsets */
#define HARD_IRON_X_OFFSET 100.0f
#define HARD_IRON_Y_OFFSET (-50.0f)

/* Target heading in degrees */
#define TARGET_HEADING 90.0f

/* Deviation threshold in degrees */
#define DEVIATION_THRESHOLD 10.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;
static float heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
static float calculate_heading(int16_t x, int16_t y);
static void apply_hard_iron_compensation(float *heading);
static void add_to_circular_buffer(float heading);
static bool check_deviation(float heading);
static void trigger_alert(bool alert);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

/* Initialize I2C communication with HMC5883L */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device (pigpio error %d): %s\n",
                i2c_handle, strerror(errno));
        return -1;
    }

    /* Configure HMC5883L: 8-average, 15 Hz, normal measurement mode */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register: %s\n", strerror(errno));
        return -1;
    }

    /* Set gain to 1.3 Gauss (0x20) */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register: %s\n", strerror(errno));
        return -1;
    }

    /* Set continuous measurement mode (0x00) */
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read magnetometer data from HMC5883L */
static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from DATA_X_MSB (0x03) */
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    /* HMC5883L outputs X, Z, Y in that order */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Calculate heading in degrees from X and Y axes */
static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

/* Apply hard iron compensation to the heading */
static void apply_hard_iron_compensation(float *heading) {
    *heading -= HARD_IRON_X_OFFSET;
    *heading -= HARD_IRON_Y_OFFSET;
    if (*heading < 0.0f) {
        *heading += 360.0f;
    } else if (*heading >= 360.0f) {
        *heading -= 360.0f;
    }
}

/* Add heading to the circular buffer */
static void add_to_circular_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Check if the heading deviation exceeds the threshold */
static bool check_deviation(float heading) {
    float deviation = fabsf(heading - TARGET_HEADING);
    if (deviation > 180.0f) {
        deviation = 360.0f - deviation;
    }
    return deviation > DEVIATION_THRESHOLD;
}

/* Trigger alert on GPIO pin */
static void trigger_alert(bool alert) {
    gpioWrite(ALERT_PIN, alert ? 1 : 0);
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO17 as output */
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handling for Ctrl+C and termination */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading;

    printf("Starting HMC5883L heading monitor. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Read magnetometer data */
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            /* Calculate heading */
            heading = calculate_heading(x, y);

            /* Apply hard iron compensation */
            apply_hard_iron_compensation(&heading);

            /* Add heading to circular buffer */
            add_to_circular_buffer(heading);

            /* Check deviation from target heading */
            bool alert = check_deviation(heading);

            /* Trigger alert */
            trigger_alert(alert);

            printf("Heading: %.2f degrees, Alert: %s\n", heading, alert ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

