#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDR             0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE  0x10
#define BH1750_CONV_TIME_MS      120
#define RED_GPIO                 17
#define GREEN_GPIO               27
#define BLUE_GPIO                22
#define LUX_THRESHOLD_RED        50
#define LUX_THRESHOLD_GREEN      150
#define LUX_THRESHOLD_BLUE       300
#define LOG_FILE                 "lighting_log.txt"
#define I2C_BUS                  "/dev/i2c-1"
#define POLL_INTERVAL_US         1000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(RED_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RED_GPIO, 0) != 0 ||
        gpioWrite(GREEN_GPIO, 0) != 0 ||
        gpioWrite(BLUE_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing initial GPIO states\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out)
{
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to BH1750: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_lamp(float lux)
{
    int red   = (lux < LUX_THRESHOLD_RED)   ? 1 : 0;
    int green = (lux < LUX_THRESHOLD_GREEN) ? 1 : 0;
    int blue  = (lux < LUX_THRESHOLD_BLUE)  ? 1 : 0;

    if (gpioWrite(RED_GPIO,   red) != 0 ||
        gpioWrite(GREEN_GPIO, green) != 0 ||
        gpioWrite(BLUE_GPIO,  blue) != 0) {
        fprintf(stderr, "Error writing to GPIO\n");
    }
}

static void log_data(FILE *fp, float lux, int red, int green, int blue)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%d,%d,%d\n", ts, lux, red, green, blue);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_fp, "# Session start\n");
    fflush(g_log_fp);

    while (g_running) {
        float lux = 0.0f;
        if (read_bh1750(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle\n");
        } else {
            control_lamp(lux);
            int red = gpioRead(RED_GPIO);
            int green = gpioRead(GREEN_GPIO);
            int blue = gpioRead(BLUE_GPIO);
            log_data(g_log_fp, lux, red, green, blue);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    fprintf(g_log_fp, "# Session end\n");
    fflush(g_log_fp);
    cleanup();
    return 0;
}

