/*
 * Raspberry Pi 3 Model B+ — Dual L298N DC Motor Control with Proportional Speed
 *
 * Wiring (BCM numbering):
 *   Motor A: IN1 -> GPIO17, IN2 -> GPIO18
 *   Motor B: IN3 -> GPIO22, IN4 -> GPIO23
 *
 * PWM: 1 kHz, duty 0-255
 * Loop: 100 ms
 * Proportional control: distance < 50 cm -> forward; distance >= 50 cm -> backward
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control 30 70
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

/* ---- PWM parameters ---- */
#define PWM_FREQUENCY 1000          /* Hz */
#define PWM_RANGE     255           /* duty 0-255 */

/* ---- Control parameters ---- */
#define LOOP_DELAY_US 100000        /* 100 ms */
#define DISTANCE_THRESHOLD_CM 50.0f

/* ---- Graceful shutdown ---- */
static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- Motor helpers ---- */

/*
 * Drive a motor forward: IN1 high, IN2 high (PWM duty).
 * Returns 0 on success, -1 on GPIO write failure.
 */
static int motor_forward(int in1, int in2, int duty)
{
    if (gpioWrite(in1, 1) < 0) return -1;
    if (gpioWrite(in2, 1) < 0) return -1;
    if (gpioPWM(in2, duty) < 0) return -1;
    return 0;
}

/*
 * Drive a motor backward: IN1 low, IN2 low (PWM duty).
 * Returns 0 on success, -1 on GPIO write failure.
 */
static int motor_backward(int in1, int in2, int duty)
{
    if (gpioWrite(in1, 0) < 0) return -1;
    if (gpioWrite(in2, 0) < 0) return -1;
    if (gpioPWM(in2, duty) < 0) return -1;
    return 0;
}

/*
 * Stop a motor: both inputs low.
 * Returns 0 on success, -1 on GPIO write failure.
 */
static int motor_stop(int in1, int in2)
{
    return gpioWrite(in1, 0) < 0 ? -1 : gpioWrite(in2, 0) < 0 ? -1 : 0;
}

/*
 * Set all four motor pins to a safe (low) state.
 */
static void motor_safe_shutdown(void)
{
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
}

/*
 * Initialize pigpio and configure motor pins.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    /* Ensure motors are stopped at startup */
    motor_safe_shutdown();

    /* Configure PWM on the two PWM-capable pins (IN2 and IN4) */
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", MOTOR_A_IN2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", MOTOR_B_IN4);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", MOTOR_A_IN2);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", MOTOR_B_IN4);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/*
 * Drive both motors with proportional speed control.
 * distance_cm: pre-sampled distance for each motor (10-100 cm).
 * Returns 0 on success, -1 on GPIO failure.
 */
static int control_motors(int distance_a, int distance_b)
{
    float error_a = (float)distance_a - DISTANCE_THRESHOLD_CM;
    float error_b = (float)distance_b - DISTANCE_THRESHOLD_CM;

    int duty_a = (int)(error_a * 5.0f);          /* 0-255 */
    int duty_b = (int)(error_b * 5.0f);          /* 0-255 */

    if (duty_a < 0) duty_a = 0;
    if (duty_a > PWM_RANGE) duty_a = PWM_RANGE;
    if (duty_b < 0) duty_b = 0;
    if (duty_b > PWM_RANGE) duty_b = PWM_RANGE;

    /* Forward when both distances are below threshold */
    if (distance_a < DISTANCE_THRESHOLD_CM && distance_b < DISTANCE_THRESHOLD_CM) {
        if (motor_forward(MOTOR_A_IN1, MOTOR_A_IN2, duty_a) < 0) return -1;
        if (motor_forward(MOTOR_B_IN3, MOTOR_B_IN4, duty_b) < 0) return -1;
    }
    /* Backward when either distance exceeds threshold */
    else {
        if (motor_backward(MOTOR_A_IN1, MOTOR_A_IN2, duty_a) < 0) return -1;
        if (motor_backward(MOTOR_B_IN3, MOTOR_B_IN4, duty_b) < 0) return -1;
    }

    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motorA_cm> <distance_motorB_cm>\n", argv[0]);
        fprintf(stderr, "  distances must be 10-100 cm\n");
        return EXIT_FAILURE;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < 10 || distance_a > 100) {
        fprintf(stderr, "Error: distance for motor A out of range (10-100 cm).\n");
        return EXIT_FAILURE;
    }
    if (distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: distance for motor B out of range (10-100 cm).\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Motor control started.  Distance A: %d cm, Distance B: %d cm\n",
           distance_a, distance_b);
    printf("Press Ctrl+C to stop.\n");

    while (!g_terminate) {
        if (control_motors(distance_a, distance_b) < 0) {
            fprintf(stderr, "Warning: GPIO error during motor control.\n");
            motor_safe_shutdown();
            break;
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful cleanup */
    motor_safe_shutdown();
    gpioTerminate();
    printf("\nMotor control stopped. GPIO cleaned up.\n");
    return EXIT_SUCCESS;
}

