/*
 * Solar Panel Tilt Tracker for Raspberry Pi 5
 * Reads MPU-6050 accelerometer data over I2C, drives a servo via sysfs PWM,
 * and logs position to a file.
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM 2, I2C1 SDA)
 *   MPU-6050 SCL -> GPIO3 (BCM 3, I2C1 SCL)
 *   Servo signal -> GPIO18 (BCM 18, PWM0 on pwmchip2)
 *
 * Build: gcc -O2 -Wall -o solar_tracker solar_tracker.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B

/* Servo PWM chip and channel */
#define PWM_CHIP 2
#define PWM_CHANNEL 0

/* I2C bus */
#define I2C_BUS "/dev/i2c-1"

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPU-6050 initialization                                             */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    /* Wake up the device: clear SLEEP bit (bit 6) */
    if (i2c_write_byte(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms settle time */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data                                             */
/* ------------------------------------------------------------------ */
static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_REG_ACCEL_XOUT_H, buf, 6) < 0)
        return -1;

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw accelerometer data to pitch and roll                  */
/* ------------------------------------------------------------------ */
static void calc_pitch_roll(int16_t ax, int16_t ay, int16_t az,
                            float *pitch, float *roll)
{
    /* Accelerometer sensitivity: 16384 LSB/g (default full-scale ±2g) */
    const float a_x = (float)ax / 16384.0f;
    const float a_y = (float)ay / 16384.0f;
    const float a_z = (float)az / 16384.0f;

    *pitch = atan2f(a_x, sqrtf(a_y * a_y + a_z * a_z)) * 180.0f / M_PI;
    *roll  = atan2f(-a_y, a_z) * 180.0f / M_PI;
}

/* ------------------------------------------------------------------ */
/* Servo control via sysfs PWM                                          */
/* ------------------------------------------------------------------ */
static int set_servo_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    /* Convert angle (0-180) to pulse width (500-2500 us) */
    int pulse_width = 500 + (int)((float)angle / 180.0f * 2000.0f);

    char path[128];
    snprintf(path, sizeof(path),
             "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    int period_fd = open(path, O_WRONLY);
    if (period_fd < 0) {
        fprintf(stderr, "Cannot open period file: %s\n", strerror(errno));
        return -1;
    }
    if (dprintf(period_fd, "%d", pulse_width) < 0) {
        fprintf(stderr, "Cannot set period: %s\n", strerror(errno));
        close(period_fd);
        return -1;
    }
    close(period_fd);

    snprintf(path, sizeof(path),
             "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int duty_fd = open(path, O_WRONLY);
    if (duty_fd < 0) {
        fprintf(stderr, "Cannot open duty_cycle file: %s\n", strerror(errno));
        return -1;
    }
    if (dprintf(duty_fd, "%d", pulse_width) < 0) {
        fprintf(stderr, "Cannot set duty_cycle: %s\n", strerror(errno));
        close(duty_fd);
        return -1;
    }
    close(duty_fd);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Position API (simulated; replace with real API in production)       */
/* ------------------------------------------------------------------ */
static int get_position(float pitch, float roll)
{
    /* Simulated position calculation */
    float position = 0.0f;
