/* ------------------------------------------------------------------ */
/* I2C initialization with exponential backoff                          */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    int retries = 5;
    int delay_ms = 100;

    while (retries > 0) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C bus %s: %s. Retrying in %d ms...\n",
                    I2C_BUS, strerror(errno), delay_ms);
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
