        uint8_t whoami;
        if (i2c_read_burst(i2c_fd, 0x75, &whoami, 1) < 0) {
            fprintf(stderr, "MPU-6050 not responding at 0x%02X. Retrying in %d ms...\n",
                    MPU6050_ADDR, delay_ms);
            close(i2c_fd);
            i2c_fd = -1;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
