        /* Initialize sensor */
        if (mpu6050_init(i2c_fd) < 0) {
            fprintf(stderr, "MPU-6050 initialization failed. Retrying in %d ms...\n",
                    delay_ms);
            close(i2c_fd);
            i2c_fd = -1;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
        }

