        return 0;
    }

    fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
