static void set_relay_state(int relay_index, int state) {
    if (relay_index < 0 || relay_index >= NUM_RELAYS) return;
    if (gpioPWM(relay_pins[relay_index], state) < 0) {
        fprintf(stderr, "Failed to set PWM state on GPIO%d\n", relay_pins[relay_index]);
    }
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(i, 0);
    }
    gpioTerminate();
}

static int read_schedule(const char *filename, int schedule[][4]) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    int line_num = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        line_num++;
        char *token = strtok(line, ";");
        if (token == NULL) continue;
        char *endptr;
        long time = strtol(token, &endptr, 10);
        if (endptr == token) {
            fprintf(stderr, "Invalid time format on line %d\n", line_num);
            continue;
        }
        token = strtok(NULL, ";");
        if (token == NULL) {
            fprintf(stderr, "Missing relay number on line %d\n", line_num);
            continue;
        }
        int relay = atoi(token);
        if (relay < 0 || relay >= NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number '%d' on line %d\n", relay, line_num);
            continue;
        }
        token = strtok(NULL, ";");
        if (token == NULL) {
            fprintf(stderr, "Missing on/off value on line %d\n", line_num);
            continue;
        }
        int on_off = (strcmp(token, "on") == 0) ? 1 : 0;
        schedule[line_num - 1][0] = (int)time;
        schedule[line_num - 1][1] = relay;
        schedule[line_num - 1][2] = on_off;
        schedule[line_num - 1][3] = 0; /* fade_duration */
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error reading schedule file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static void fade_lamp(int relay_index, int target_state, int duration) {
    if (relay_index < 0 || relay_index >= NUM_RELAYS) return;
    int current_state = gpioRead(relay_pins[relay_index]);
    if (current_state < 0) {
        fprintf(stderr, "Failed to read current state on GPIO%d\n", relay_pins[relay_index]);
        return;
    }
    int step_delay = duration / 100;
    if (step_delay < 1) step_delay = 1;
    for (int i = 0; i <= 100 && running; i++) {
        int duty = (target_state == current_state) ? i : 100 - i;
        if (gpioPWM(relay_pins[relay_index], duty) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO%d\n", relay_pins[relay_index]);
            return;
        }
        gpioDelay(step_delay * 1000);
        current_state = gpioRead(relay_pins[relay_index]);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read current state on GPIO%d\n", relay_pins[relay_index]);
            return;
        }
    }
    if (!running) {
        set_relay_state(relay_index, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    int schedule[NUM_RELAYS][4];
    if (read_schedule(SCHEDULE_FILE, schedule) < 0) {
        cleanup_gpio();
        return 1;
    }

    time_t current_time;
    while (running) {
        time(&current_time);
        int current_hour = time(NULL) % 86400 / 3600;
        int current_minute = (time(NULL) % 86400 / 60) % 60;
        int current_second = time(NULL) % 60;

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (schedule[i][3] == 0) {
                int next_time = schedule[i][0];
                int next_hour = next_time / 3600;
                int next_minute = (next_time % 3600) / 60;
                int next_second = next_time % 60;

                if (current_hour == next_hour && current_minute == next_minute && current_second == next_second) {
                    if (schedule[i][2] == 1) {
                        fade_lamp(i, 100, schedule[i][3]);
                    } else {
                        fade_lamp(i, 0, schedule[i][3]);
                    }
                    schedule[i][3] = 0;
                }
            }
        }

        sleep(1);
    }

    cleanup_gpio();
    return 0;
}

