/*
 * Rudimentary theremin using an HC-SR04 ultrasonic distance sensor.
 *
 * Wiring (Raspberry Pi Zero W, BCM numbering):
 *   GPIO23 (BCM) -> HC-SR04 TRIG (3.3 V logic-level safe)
 *   GPIO24 (BCM) <- HC-SR04 ECHO (3.3 V logic-level safe)
 *   GPIO18 (BCM) -> PWM buzzer (e.g., 1 kΩ series resistor to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US  30000       /* 30 ms max echo wait (~5 m round-trip) */
#define LOOP_DELAY_US    20000       /* 20 ms -> ~50 Hz */
#define MIN_CYCLE_MS     60          /* 60 ms between measurements */
#define MIN_FREQ_HZ      200
#define MAX_FREQ_HZ      800
#define MAX_DISTANCE_CM  100.0

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 helpers                                                     */
/* ------------------------------------------------------------------ */
/*
 * Measure distance in centimetres.
 * Returns:
 *   >= 0  on success (distance in cm)
 *   -1.0  on timeout (no echo received)
 *   -2.0  on GPIO read error
 */
static double measure_distance(void)
{
    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -2.0;
    }
    gpioDelay(5);                       /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -2.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -2.0;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t elapsed = echo_end - echo_start;
    /* speed of sound ~343 m/s => cm = (us * 1e-6 * 34300) / 2 */
    double distance = (elapsed * 1e-6 * 34300.0) / 2.0 / 10000.0; /* cm */
    return distance;
}

/* ------------------------------------------------------------------ */
/* Frequency mapping                                                   */
/* ------------------------------------------------------------------ */
static int map_distance_to_frequency(double distance)
{
    if (distance < 0.0) {
        return 0;
    }
    if (distance > MAX_DISTANCE_CM) {
        distance = MAX_DISTANCE_CM;
    }
    /* Inverse mapping: closer -> higher frequency */
    double freq = MAX_FREQ_HZ - (distance * (MAX_FREQ_HZ - MIN_FREQ_HZ) / MAX_DISTANCE_CM);
    if (freq < MIN_FREQ_HZ) {
        freq = MIN_FREQ_HZ;
    }
    if (freq > MAX_FREQ_HZ) {
        freq = MAX_FREQ_HZ;
    }
    return (int)freq;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void set_buzzer_frequency(int frequency)
{
    if (frequency <= 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {   /* ~50 % duty cycle */
        fprintf(stderr, "Error: gpioPWM(%d, 128) failed\n", BUZZER_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    uint32_t last_cycle_start = 0;

    while (g_running) {
        uint32_t now = gpioTick();
        uint32_t elapsed_since_last = now - last_cycle_start;
        if (elapsed_since_last < (uint32_t)(MIN_CYCLE_MS * 1000)) {
            /* Sleep until the minimum cycle time has elapsed */
            uint32_t remaining = (uint32_t)(MIN_CYCLE_MS * 1000) - elapsed_since_last;
            gpioDelay(remaining);
            continue;
        }
        last_cycle_start = now;

        double distance = measure_distance();

        if (distance < 0.0) {
            /* Sensor error: silence the buzzer */
            set_buzzer_frequency(0);
        } else {
            int frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

