#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_FREQ   1000          /* 1 kHz hardware PWM clock */
#define PWM_RANGE  255           /* 8-bit resolution */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Map a value in [0, 1] to a PWM duty cycle in [0, PWM_RANGE].         */
/* For a common-anode LED, a higher duty cycle (closer to PWM_RANGE)    */
/* means the LED is OFF (less current through the anode); a duty of 0   */
/* means the LED is at full brightness.                                 */
/* ------------------------------------------------------------------ */
static int map_proximity_to_duty(float proximity)
{
    if (proximity < 0.0f)   proximity = 0.0f;
    if (proximity > 1.0f)   proximity = 1.0f;
    return (int)(PWM_RANGE * (1.0f - proximity));
}

/* ------------------------------------------------------------------ */
/* Set the RGB LED color using pigpio hardware-PWM writes.              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT,  &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM pins ---- */
    int pins[3] = { RED_PIN, GREEN_PIN, BLUE_PIN };
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO%d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Set PWM frequency and range ---- */
    for (int i = 0; i < 3; i++) {
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Ensure LED starts OFF ---- */
    if (set_led_color(0, 0, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LED to OFF state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Simulated proximity wave: sine over time ---- */
    const double dt = 0.01;   /* 10 ms -> 100 Hz update rate */
    const double t0  = 0.0;

    /* ---- Main loop ---- */
    while (g_running) {
        double t = t0 + (double)(gpioTick() / 1000000.0);   /* seconds since startup */
        float proximity = 0.5f * (1.0f + sinf(2.0 * M_PI * 5.0 * t));  /* 0.0 .. 1.0 */

        int red   = map_proximity_to_duty(proximity);
        int green = map_proximity_to_duty(proximity);
        int blue  = map_proximity_to_duty(proximity);

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "Warning: gpioPWM write failed; continuing.\n");
        }

        gpioDelay((unsigned)(dt * 1000000.0));   /* microseconds */
    }

    /* ---- Graceful shutdown ---- */
    set_led_color(0, 0, 0);   /* best-effort LED off */
    gpioTerminate();
    return EXIT_SUCCESS;
}

