#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define TONE_DUTY 500000   /* 50 % of 1e6 */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;

static const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    static uint32_t last_tick = 0;
    if (tick - last_tick < DEBOUNCE_US) return;
    last_tick = tick;
    button_pressed = 1;
}

static int play_tone(int freq, int duration_us) {
    if (freq <= 0) return -1;
    if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", freq);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, TONE_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", BUZZER_PIN, TONE_DUTY);
        return -1;
    }
    gpioDelay(duration_us);
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, 0) failed\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static int play_melody(void) {
    for (int i = 0; i < melody_len; i++) {
        if (!running) return 0;
        if (play_tone(melody[i], 200000) < 0) return -1;
        if (play_tone(0, 200000) < 0) return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction failed");
        gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO%d) to play the melody.\n", BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed! Playing melody...\n");
            if (play_melody() < 0) {
                fprintf(stderr, "Error: melody playback failed\n");
            }
        }
        gpioDelay(10000); /* 10 ms poll */
    }

    /* Clean shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

