#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_MAG_ADDR 0x19
#define LSM303_CTRL_REG1 0x20
#define LSM303_CTRL_REG2 0x21
#define LSM303_CTRL_REG3 0x22
#define LSM303_CTRL_REG4 0x23
#define LSM303_OUT_X_H_M 0x28
#define LSM303_OUT_X_L_M 0x29
#define LSM303_OUT_Y_H_M 0x2A
#define LSM303_OUT_Y_L_M 0x2B
#define LSM303_OUT_Z_H_M 0x2C
#define LSM303_OUT_Z_L_M 0x2D

#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lsm303(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_MAG_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303_CTRL_REG1, 0x1F) < 0) {
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303_CTRL_REG2, 0x20) < 0) {
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303_CTRL_REG3, 0x00) < 0) {
        close(fd);
        return -1;
    }
    if (i2c_write_reg8(fd, LSM303_CTRL_REG4, 0x0C) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xh, xl, yh, yl, zh, zl;
    if (i2c_read_reg8(fd, LSM303_OUT_X_H_M, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_OUT_X_L_M, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_OUT_Y_H_M, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_OUT_Y_L_M, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_OUT_Z_H_M, &zh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_OUT_Z_L_M, &zl) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static float calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    float cal_x = (float)raw_x - X_OFFSET;
    float cal_y = (float)raw_y - Y_OFFSET;
    float cal_z = (float)raw_z - Z_OFFSET;
    return sqrtf(cal_x * cal_x + cal_y * cal_y + cal_z * cal_z);
}

static float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static const char *determine_direction(float heading) {
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading < 67.5f) return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    return "NW";
}

static int log_data(FILE *fp, float x, float y, float z, float heading) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, %.2f, %.2f, %.2f, %.2f\n", ts, x, y, z, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = init_lsm303();
    if (g_i2c_fd < 0) {
        return 1;
    }

    int need_header = 0;
    {
        FILE *check = fopen("mag_log.csv", "r");
        if (check == NULL) {
            need_header = 1;
        } else {
            fseek(check, 0, SEEK_END);
            if (ftell(check) == 0) need_header = 1;
            fclose(check);
        }
    }

    g_log_fp = fopen("mag_log.csv", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (need_header) {
        fprintf(g_log_fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(g_log_fp);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Magnetometer read failed; skipping sample.\n");
        } else {
            float calibrated = calibrate_magnetometer(raw_x, raw_y, raw_z);
            float heading = calculate_heading(calibrated * sinf(M_PI / 180.0f), calibrated * cosf(M_PI / 180.0f));
            const char *dir = determine_direction(heading);
            printf("Heading: %.2f degrees (%s)\n", heading, dir);
            if (log_data(g_log_fp, raw_x, raw_y, raw_z, heading) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }
        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

