        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (need_header) {
        fprintf(g_log_fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(g_log_fp);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Magnetometer read failed; skipping sample.\n");
        } else {
            float calibrated = calibrate_magnetometer(raw_x, raw_y, raw_z);
            float heading = calculate_heading(calibrated * sinf(M_PI / 180.0f), calibrated * cosf(M_PI / 180.0f));
            const char *dir = determine_direction(heading);
            printf("Heading: %.2f degrees (%s)\n", heading, dir);
            if (log_data(g_log_fp, raw_x, raw_y, raw_z, heading) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }
        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

