#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define LOG_FILE "irrigation_log.txt"
#define NUM_RELAYS 4
#define POLL_INTERVAL 10

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Failed to initialise GPIO%d high\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_soil_moisture(void)
{
    return rand() % 101;
}

static int control_relay(int relay_number, int moisture_level)
{
    if (moisture_level < MOISTURE_THRESHOLD) {
        if (gpioWrite(relay_pins[relay_number - 1], 0) < 0) {
            fprintf(stderr, "Failed to activate relay %d\n", relay_number);
            return -1;
        }
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
        if (g_log_fp != NULL) {
            fprintf(g_log_fp, "%s - Relay %d activated (moisture: %d)\n",
                    timestamp, relay_number, moisture_level);
            fflush(g_log_fp);
        } else {
            fprintf(stderr, "Log file not open\n");
        }
        sleep(IRRIGATION_DURATION);
        if (gpioWrite(relay_pins[relay_number - 1], 1) < 0) {
            fprintf(stderr, "Failed to deactivate relay %d\n", relay_number);
            return -1;
        }
        if (g_log_fp != NULL) {
            fprintf(g_log_fp, "%s - Relay %d deactivated\n", timestamp, relay_number);
            fflush(g_log_fp);
        }
    }
    return 0;
}

static void cleanup(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void)
{
    srand((unsigned int)time(NULL));
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(g_log_fp);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(g_log_fp);
        return 1;
    }

    if (initialize_gpio() < 0) {
        fclose(g_log_fp);
        return 1;
    }

    while (g_running) {
        int moisture_level = read_soil_moisture();
        printf("Soil moisture level: %d\n", moisture_level);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (g_running) {
                control_relay(i + 1, moisture_level);
            }
        }
        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

