#define VALVE_GPIO        17
#define NOZZLE_GPIO       18

#define MOISTURE_THRESHOLD 50
#define NOZZLE_STEPS       5
#define NOZZLE_STEP_DELAY  2
#define SPRAY_HOLD         5
#define VALVE_OPEN_US      1500   /* 90 degrees */
#define VALVE_CLOSE_US     500    /* 0 degrees  */
#define RETRY_COUNT        3
#define RETRY_DELAY_MS     100
#define CYCLE_DELAY_MS     5
#define SIMULATED_DELAY_MS 1000

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Set a servo to the given angle (0–180 degrees).
 * Returns 0 on success, -1 on failure after retries.
 */
static int set_servo_angle(int gpio, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle %d for GPIO %d\n", angle, gpio);
        return -1;
    }

    int pulse_us = 500 + (angle * 2000) / 180; /* 500–2500 us */

    for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
        int rc = the_driver_library_servo_set_angle(gpio, pulse_us);
        if (rc == 0)
            return 0;

        fprintf(stderr,
                "Servo set_angle failed on GPIO %d (pulse %d us), attempt %d/%d, rc=%d\n",
                gpio, pulse_us, attempt + 1, RETRY_COUNT, rc);

        if (attempt < RETRY_COUNT - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

/*
 * Stop a servo by setting its pulse width to 0.
 * Returns 0 on success, -1 on failure after retries.
 */
static int stop_servo(int gpio)
{
    for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
        int rc = the_driver_library_servo_stop(gpio);
        if (rc == 0)
            return 0;

        fprintf(stderr,
                "Servo stop failed on GPIO %d, attempt %d/%d, rc=%d\n",
                gpio, attempt + 1, RETRY_COUNT, rc);

        if (attempt < RETRY_COUNT - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Nozzle sweep                                                        */
/* ------------------------------------------------------------------ */

static void nozzle_sweep(int nozzle_gpio)
{
    int nozzle_angles[NOZZLE_STEPS] = {0, 45, 90, 135, 180};
    int pulse_us[NOZZLE_STEPS]       = {500, 1000, 1500, 2000, 2500};

    for (int i = 0; i < NOZZLE_STEPS; ++i) {
        if (!g_running)
            break;

        if (set_servo_angle(nozzle_gpio, nozzle_angles[i]) != 0) {
            fprintf(stderr,
                    "Warning: nozzle position %d/%d failed; continuing\n",
                    i + 1, NOZZLE_STEPS);
            continue;
        }

        printf("Nozzle at %d degrees\n", nozzle_angles[i]);

        for (int s = 0; s < NOZZLE_STEP_DELAY && g_running; ++s)
            usleep(100 * 1000); /* 100 ms */
    }
}

/* ------------------------------------------------------------------ */
/* Valve control                                                       */
/* ------------------------------------------------------------------ */

static void control_valve(int valve_gpio)
{
    printf("Opening valve...\n");
    if (set_servo_angle(valve_gpio, 90) != 0) {
        fprintf(stderr, "Error: failed to open valve on GPIO %d\n", valve_gpio);
        return;
    }

    for (int s = 0; s < SPRAY_HOLD && g_running; ++s)
        usleep(100 * 1000); /* 100 ms */

    printf("Closing valve...\n");
    if (set_servo_angle(valve_gpio, 0) != 0) {
        fprintf(stderr, "Warning: failed to close valve on GPIO %d\n", valve_gpio);
        return;
