            if (set_servo_angle(VALVE_GPIO, 0) != 0) {
                fprintf(stderr, "Error: failed to close valve servo.\n");
                break;
            }

            for (int s = 0; s < CYCLE_DELAY_MS && g_running; ++s)
                usleep(100 * 1000); /* 100 ms */
        } else {
