#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_CONFIG    0x1B
#define SAMPLE_HZ      10
#define SAMPLE_DELAY_US (1000000 / SAMPLE_HZ)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    *x = combine_bytes(buf[0], buf[1]);
    *y = combine_bytes(buf[2], buf[3]);
    *z = combine_bytes(buf[4], buf[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050 at 0x%02X\n", MPU6050_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("gyro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 logging started at 10 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(fp, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data, continuing...\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

