#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

/* L293D IN1..IN4 inputs (BCM numbering) */
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

/* Button inputs (active-low, internal pull-up) */
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000   /* 3 ms */
#define DEBOUNCE_US 200000   /* 200 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* De-energize all four coils */
static void coils_off(void)
{
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/* Full-step excitation: IN1=1 IN2=0 IN3=1 IN4=0 */
static void step_forward(void)
{
    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 1);
    gpioWrite(IN4, 0);
}

/* Full-step excitation: IN1=0 IN2=1 IN3=0 IN4=1 */
static void step_backward(void)
{
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 1);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 1);
}

/* Rotate 'steps' full steps in the given direction; de-energize on return */
static int rotate(int steps, int direction)
{
    for (int i = 0; i < steps; i++) {
        if (direction == 1) {
            step_forward();
        } else {
            step_backward();
        }
        gpioDelay(STEP_DELAY_US);
        coils_off();
    }
    return 0;
}

/* Read a button with internal pull-up; returns 1 if pressed (active low) */
static int button_pressed(int gpio)
{
    return (gpioRead(gpio) == 0);
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- L293D coil pins as outputs, default LOW --- */
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    coils_off();

    /* --- Button pins as inputs with pull-up --- */
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    /* --- Signal handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Door control ready. Press LOCK (GPIO24) to lock, UNLOCK (GPIO23) to unlock.\n");
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        if (button_pressed(LOCK_BUTTON)) {
            printf("Locking door...\n");
            if (rotate(STEPS_PER_ROTATION, 1) != 0) {
                fprintf(stderr, "Error: lock rotation failed\n");
            }
            gpioDelay(DEBOUNCE_US);
            coils_off();
        } else if (button_pressed(UNLOCK_BUTTON)) {
            printf("Unlocking door...\n");
            if (rotate(STEPS_PER_ROTATION, 0) != 0) {
                fprintf(stderr, "Error: unlock rotation failed\n");
            }
            gpioDelay(DEBOUNCE_US);
            coils_off();
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    coils_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

