#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define MEASURE_INTERVAL_US 60000   /* 60 ms between measurements */
#define ECHO_TIMEOUT_US 50000       /* 50 ms timeout for echo edges */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure the duration (in microseconds) of a level held on `pin`.
 * Returns the duration on success, or -1 on timeout.
 */
static long measure_level_us(int pin, int level, uint32_t timeout_us)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for the pin to reach the desired level */
    deadline = gpioTick() + timeout_us;
    while (gpioRead(pin) != level) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for the pin to leave the level */
    deadline = gpioTick() + timeout_us;
    while (gpioRead(pin) == level) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static void log_distance(long distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_fp) {
        fprintf(log_fp, "%s, Distance: %ld cm\n", timestamp, distance);
        fflush(log_fp);
    }
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise TRIGGER_PIN %d low\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Generate 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN %d high\n", TRIGGER_PIN);
            log_distance(-1);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }
        gpioDelay(10);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN %d low\n", TRIGGER_PIN);
            log_distance(-1);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }

        /* Measure echo pulse width */
        long pulse_duration = measure_level_us(ECHO_PIN, 1, ECHO_TIMEOUT_US);
        if (pulse_duration < 0) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            log_distance(-1);
        } else {
            /* Speed of sound = 343 m/s = 0.0343 cm/us; round trip / 2 */
            long distance = (pulse_duration * 0.0343) / 2;
            log_distance(distance);
        }

        /* Wait before next measurement */
        gpioDelay(MEASURE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

