#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

/* VL53L1X I2C default address (SDA=GPIO2, SCL=GPIO3 on RPi 4) */
#define VL53L1X_ADDR 0x29

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_I2C_SLAVE_DEVICE_MODEL  0x0011
#define VL53L1X_REG_SYSTEM_MODE_START      0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS    0x0014
#define VL53L1X_REG_RESULT_DISTANCE        0x0096

/* GPIO pin for relay control (BCM numbering) */
#define RELAY_PIN 18

/* Threshold distance in cm */
#define DISTANCE_THRESHOLD 50

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 100000

/* Maximum consecutive errors before aborting */
#define MAX_CONSECUTIVE_ERRORS 10

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register on the VL53L1X (big-endian over I2C)        */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) < 0) {
        fprintf(stderr, "Error writing reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the VL53L1X                             */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, buf, 2) < 0) {
        fprintf(stderr, "Error selecting reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor                                        */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint16_t model_id = 0;

    /* Read model ID to confirm sensor is present */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_MODEL, &model_id) < 0) {
        fprintf(stderr, "VL53L1X not responding on I2C bus 1, addr 0x%02X\n", VL53L1X_ADDR);
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Unexpected model ID 0x%04X (expected 0xEACC)\n", model_id);
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from the VL53L1X                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;
    uint16_t dist   = 0;
    int      attempts = 0;

    /* Start a single measurement */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0001) < 0)
        return -1;

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    do {
        if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
            return -1;
        if (++attempts > 100) {
            fprintf(stderr, "Timeout waiting for VL53L1X data-ready\n");
            return -1;
        }
        gpioDelay(5000); /* 5 ms */
    } while ((status & 0x0001) == 0);

    /* Read distance (mm) */
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the relay based on distance                                 */
/* ------------------------------------------------------------------ */
static void control_relay(int distance_mm)
{
    int relay_state = (distance_mm <= (DISTANCE_THRESHOLD * 10)) ? 1 : 0;
    if (gpioWrite(RELAY_PIN, relay_state) < 0) {
        fprintf(stderr, "Warning: failed to write relay pin %d\n", RELAY_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t distance_mm = 0;
    int     consecutive_errors = 0;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts LOW */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    /* Open I2C bus 1 at the VL53L1X default address */
    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1, addr 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X initialised. Reading distance every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);

    /* Main polling loop */
    while (g_running) {
        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
            consecutive_errors = 0;
            printf("Distance: %u mm\n", distance_mm);
            control_relay(distance_mm);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error (%d/%d)\n", consecutive_errors, MAX_CONSECUTIVE_ERRORS);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

