/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules are connected to GPIO17, GPIO18, GPIO27, GPIO22
 * (BCM numbering, physical pins 11, 12, 13, 15).  Each relay is driven
 * with active-low logic: GPIO HIGH  -> relay OFF
 *                             GPIO LOW  -> relay ON
 *
 * The system cycles through the relays once every 24 hours, watering each
 * for 5 seconds.  A full cycle is logged to watering_log.txt at its start.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    sudo ./watering   (root needed for /dev/gpiochip0 on older kernels)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_SEC    5
#define CYCLE_SEC       86400          /* 24 hours */
#define POLL_SEC        60
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int water_relay(struct gpiod_line *line, int pin, int duration_sec)
{
    /* Active-low: LOW energises the relay. */
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "set_value(pin %u, LOW) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }

    /* Sleep in 1-second increments so we can respond to signals promptly. */
    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "set_value(pin %u, HIGH) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(\"gpiochip0\") failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as output, initial value HIGH (relay OFF). */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "request_output(pin %u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Automated plant watering system started.\n");
    printf("Relays on GPIO17, GPIO18, GPIO27, GPIO22.  Watering every %d s "
           "for %d s.  Ctrl+C to exit.\n", POLL_SEC, WATERING_SEC);

    while (g_running) {
        if (log_cycle_start() != 0)
            fprintf(stderr, "Warning: cycle start not logged.\n");

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (water_relay(lines[i], relay_pins[i], WATERING_SEC) != 0) {
                fprintf(stderr, "Watering failed on GPIO %u.\n",
                        relay_pins[i]);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int s = 0; s < POLL_SEC && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

