                fprintf(stderr, "Watering failed on GPIO %u.\n",
                        relay_pins[i]);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int s = 0; s < POLL_SEC && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

