#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define SUNRISE_DURATION 1800  /* 30 minutes in seconds */
#define PWM_FREQUENCY 1000      /* 1 kHz */
#define PWM_RANGE 255

/* BCM GPIO numbers for the four SRD-05VDC relay modules */
static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Log a message with a timestamp to the log file */
static void log_message(const char *message) {
    if (log_file == NULL) {
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

/* Initialize the pigpio library and configure the relay pins as outputs */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO%d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    /* Set PWM frequency and range for all relay pins */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: Failed to set PWM range on GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

/* Gradually increase the intensity of the relays over the sunrise duration */
static void sunrise_simulation(void) {
    int step_delay = SUNRISE_DURATION / NUM_RELAYS;
    int duty_cycle = 0;

    log_message("Sunrise simulation started.");

    for (int i = 0; i < NUM_RELAYS && running; i++) {
        if (gpioPWM(relay_pins[i], duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO%d\n", relay_pins[i]);
            log_message("Error: Failed to set PWM duty cycle.");
            running = 0;
            break;
        }

        log_message("Increasing intensity on relay 1.");

        duty_cycle += (PWM_RANGE / NUM_RELAYS);
        if (duty_cycle > PWM_RANGE) {
            duty_cycle = PWM_RANGE;
        }

        gpioDelay(step_delay * 1000); /* Convert seconds to microseconds */
    }

    if (running) {
        log_message("Sunrise simulation complete.");
    }
}

/* Gradually decrease the intensity of the relays over the sunset duration */
static void sunset_simulation(void) {
    int step_delay = SUNRISE_DURATION / NUM_RELAYS;
    int duty_cycle = PWM_RANGE;

    log_message("Sunset simulation started.");

    for (int i = 0; i < NUM_RELAYS && running; i++) {
        if (gpioPWM(relay_pins[i], duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle on GPIO%d\n", relay_pins[i]);
            log_message("Error: Failed to set PWM duty cycle.");
            running = 0;
            break;
        }

        log_message("Decreasing intensity on relay 1.");

        duty_cycle -= (PWM_RANGE / NUM_RELAYS);
        if (duty_cycle < 0) {
            duty_cycle = 0;
        }

        gpioDelay(step_delay * 1000); /* Convert seconds to microseconds */
    }

    if (running) {
        log_message("Sunset simulation complete.");
    }
}

/* Cleanup resources before exiting */
static void cleanup(void) {
    log_message("Cleaning up resources.");

    /* Turn off all relays */
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }

    /* Terminate pigpio */
    gpioTerminate();

    /* Close the log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    /* Open the log file in append mode */
    log_file = fopen("smart_lighting.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed. Exiting.");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_message("Smart lighting system started.");

    /* Run sunrise simulation */
    sunrise_simulation();

    /* Keep the lights on for a while */
    for (int i = 0; i < 60 && running; i++) {
        gpioDelay(1000000); /* 1 second */
    }

    /* Run sunset simulation */
    sunset_simulation();

    /* Cleanup and exit */
    cleanup();
    return EXIT_SUCCESS;
}

