#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define MPU6050_ADDR   0x68
#define GYRO_XOUT_H    0x43
#define GYRO_YOUT_H    0x45
#define GYRO_ZOUT_H    0x47
#define LED_PIN        17
#define THRESHOLD      250.0f   /* deg/s */
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD_US 50000  /* 50 ms -> 20 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static int  init_i2c(void);
static int  read_gyro(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *cb, float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- I2C initialization ---- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* ---- Gyroscope read ---- */
static int read_gyro(float *x, float *y, float *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data block\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / 131.0f;   /* deg/s */
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(circular_buffer_t *cb, float x, float y, float z)
{
    clock_gettime(CLOCK_MONOTONIC, &cb->data[cb->head].timestamp);
    cb->data[cb->head].x = x;
    cb->data[cb->head].y = y;
    cb->data[cb->head].z = z;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* ---- Threshold check ---- */
static void check_threshold(float x, float y, float z)
{
    if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    float x, y, z;
    int reinit_attempts = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    gyro_buffer.head  = 0;
    gyro_buffer.count = 0;

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU6050 gyroscope reader started. Sampling at 20 Hz.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (read_gyro(&x, &y, &z) == 0) {
            add_to_buffer(&gyro_buffer, x, y, z);
            check_threshold(x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Gyroscope read failed. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
            reinit_attempts++;
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

