/*
 * MPU-9250 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Reads X, Y, Z angular rates over SPI (/dev/spidev0.0) and logs them to
 * gyro_log.txt.  Uses libgpiod to manually control CE0 (GPIO8) so that the
 * MPU-9250 chip-select line is asserted only during transfers.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c -lgpiod
 *
 * Wiring:
 *   MPU-9250 SCLK  -> GPIO11 (SPI0 SCLK)
 *   MPU-9250 CS    -> GPIO8  (SPI0 CE0, manually driven via libgpiod)
 *   MPU-9250 DOUT  -> GPIO9  (SPI0 MISO)
 *   MPU-9250 DIN   -> GPIO10 (SPI0 MOSI)
 *   MPU-9250 VDD   -> 3.3 V
 *   MPU-9250 GND   -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ---- Configuration ---- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0

#define GPIO_CHIP         "/dev/gpiochip0"
#define GPIO_CS_OFFSET    8          /* BCM GPIO8 = physical pin 24 = SPI0 CE0 */

#define LOG_FILE          "gyro_log.txt"
#define SAMPLE_PERIOD_NS  10000000L  /* 10 ms */
#define MAX_RETRIES       3

/* MPU-9250 register addresses (from datasheet) */
#define REG_SMPLRT_DIV    0x19
#define REG_PWR_MGMT_1    0x6B
#define REG_GYRO_CONFIG   0x1B
#define REG_GYRO_XOUT_H   0x43
#define REG_GYRO_YOUT_H   0x45
#define REG_GYRO_ZOUT_H   0x47

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_cs_line = NULL;
static FILE    *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- SPI transfer with manual CS ---- */
static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;  /* we manage CS manually */

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Read a single register ---- */
static int read_register(int fd, uint8_t reg, uint8_t *val)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };
    return spi_transfer(fd, tx, rx, 2);
}

/* ---- Write a single register ---- */
static int write_register(int fd, uint8_t reg, uint8_t val)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), val };
    uint8_t rx[2] = { 0, 0 };
    return spi_transfer(fd, tx, rx, 2);
}

/* ---- Read 6 bytes starting at a register (auto-increment) ---- */
static int read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t tx[7] = { (uint8_t)(reg | 0x80 | 0x40), 0, 0, 0, 0, 0, 0 };
    uint8_t rx[7] = { 0 };
    return spi_transfer(fd, tx, rx, len + 1);
}

/* ---- Initialize MPU-9250 ---- */
static int init_mpu9250(int fd)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (write_register(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);  /* 100 ms settle */

    /* Sample rate divider = 0 (1 kHz / (1 + 0) = 1 kHz internal) */
    if (write_register(fd, REG_SMPLRT_DIV, 0x00) < 0)
        return -1;

    /* Gyro full-scale range = +/- 250 deg/s (FS_SEL = 0) */
    if (write_register(fd, REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read gyroscope data ---- */
static int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (read_block(fd, REG_GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Log one record ---- */
static int log_record(FILE *fp, const struct timespec *ts,
                      int16_t x, int16_t y, int16_t z)
{
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d\n",
                (long)ts->tv_sec, ts->tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request CS line ---- */
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_cs_line = gpiod_chip_get_line(g_chip, GPIO_CS_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_CS_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Cannot request CS line as output: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize MPU-9250 ---- */
    if (init_mpu9250(g_spi_fd) < 0) {
        fprintf(stderr, "MPU-9250 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-9250 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_NS);
            continue;
        }

        int16_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_gyro(g_spi_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            usleep(1000);
        }

        if (ok) {
            if (log_record(g_log_fp, &ts, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed after %d retries; continuing.\n",
                    MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_NS);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

