#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      4000000    /* 4 MHz (MPU-6050 supports up to 20 MHz) */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LED_PIN        17         /* BCM 17, physical pin 11 */
#define BUFFER_SIZE    64
#define THRESHOLD      200.0f     /* deg/s */
#define SAMPLE_PERIOD  100000     /* microseconds (100 ms) */
#define BLINK_ON_US    500000     /* 500 ms */
#define BLINK_OFF_US   500000     /* 500 ms */

/* ---- Data structures ---- */
typedef struct {
    time_t timestamp;
    float  x;
    float  y;
    float  z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t gyro_buffer;

/* ---- Prototypes ---- */
static int  init_spi(void);
static int  read_gyro(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *cb, float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void blink_led(void);
static void signal_handler(int sig);
static void cleanup(void);
static void print_buffer(const circular_buffer_t *cb);

/* ---- SPI init ---- */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

/* ---- Read 14 bytes from MPU-6050 (WHO_AM_I + PWR_MGMT_1 + GYRO_XOUT_H) ---- */
static int read_gyro(float *x, float *y, float *z) {
    char tx[14] = {0};
    char rx[14] = {0};

    /* WHO_AM_I: 0x68, PWR_MGMT_1: 0x6B, GYRO_XOUT_H: 0x43 */
    tx[0] = 0x68; tx[1] = 0x6B; tx[2] = 0x43;
    tx[3] = 0x00; tx[4] = 0x00; tx[5] = 0x00;
    tx[6] = 0x00; tx[7] = 0x00; tx[8] = 0x00;
    tx[9]  = 0x00; tx[10] = 0x00; tx[11] = 0x00;
    tx[12] = 0x00; tx[13] = 0x00;

    int ret = spiXfer(spi_handle, tx, rx, 14);
    if (ret != 14) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 14)\n", ret);
        return -1;
    }

    /* WHO_AM_I: bit 7 should be 0 (device present) */
    if (rx[0] & 0x80) {
        fprintf(stderr, "Error: MPU-6050 not detected (WHO_AM_I=0x%02X)\n",
                (uint8_t)rx[0]);
        return -1;
    }

    /* GYRO_XOUT_H (rx[7]), GYRO_XOUT_L (rx[8]) */
    int16_t raw_x = (int16_t)(((uint8_t)rx[7] << 8) | (uint8_t)rx[8]);
    int16_t raw_y = (int16_t)(((uint8_t)rx[9] << 8) | (uint8_t)rx[10]);
    int16_t raw_z = (int16_t)(((uint8_t)rx[11] << 8) | (uint8_t)rx[12]);

