/*
 * MPU-6050 Tilt Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC  -> Pi 3.3 V (Pin 1)
 *   MPU-6050 GND  -> Pi GND  (Pin 9)
 *   MPU-6050 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   MPU-6050 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *   LED anode    -> Pi GPIO21 (Pin 40) via 330 ohm resistor
 *   LED cathode  -> Pi GND
 *
 * Build:  gcc -O2 -Wall -o tilt_monitor tilt_monitor.c -lm -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define MPU6050_ADDR   0x68          /* AD0 tied to GND */
#define LED_GPIO       21            /* BCM numbering */
#define SAMPLE_US      100000        /* 100 ms */
#define TILT_THRESHOLD 45.0          /* degrees */

/* MPU-6050 registers */
#define REG_SMPLRT_DIV   0x19
#define REG_CONFIG       0x1A
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_PWR_MGMT_1   0x6B

/* Sensitivities at +/- 2 g and 250 deg/s */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

/* ---- Globals for cleanup ---- */
static int  g_i2c  = -1;
static bool g_pigpio_inited = false;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nSIGINT received — shutting down...\n");
    if (g_pigpio_inited) {
        gpioWrite(LED_GPIO, 0);
        if (g_i2c >= 0) i2cClose(g_i2c);
        gpioTerminate();
        g_pigpio_inited = false;
    }
    exit(0);
}

/* ---- Helpers ---- */
static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

static void log_data(float roll, float pitch)
{
    char ts[32];
    timestamp_str(ts, sizeof(ts));
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        perror("fopen tilt_log.txt");
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, roll, pitch);
    fclose(fp);
}

/* ---- Sensor read ---- */
static bool read_sensor(float *ax, float *ay, float *az,
                         float *gx, float *gy, float *gz)
{
    char buf[6];

    /* Accelerometer X/Y/Z (big-endian, 14-bit left-justified) */
    if (i2cReadI2CBlockData(g_i2c, REG_ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read of accel data failed\n");
        return false;
    }

    int16_t raw_ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    int16_t raw_ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    int16_t raw_az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);

    /* Gyroscope X/Y/Z (big-endian, 16-bit) */
    if (i2cReadI2CBlockData(g_i2c, 0x43, buf, 4) != 4) {
        fprintf(stderr, "Error: I2C read of gyro data failed\n");
        return false;
    }

    int16_t raw_gx = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    int16_t raw_gy = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    int16_t raw_gz = (int16_t)((buf[4]  << 8) | (uint8_t)buf[3]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;

    return true;
}

static void calc_tilt(float ax, float ay, float az, float *roll, float *pitch)
{
    *roll  = atan2f(ay, az) * 180.0f / (float)M_PI;
    *pitch = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / (float)M_PI;
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* LED GPIO setup */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C */
    g_i2c = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }

    /* Wake up MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(g_i2c, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: could not wake MPU-6050\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }
    gpioDelay(100000);  /* 100 ms settle */

    /* Configure registers */
    if (i2cWriteByteData(g_i2c, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: could not set sample rate divider\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c, REG_GYRO_CONFIG,  0x00) < 0) {
        fprintf(stderr, "Error: could not set gyro range\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c, REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: could not set accel range\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 tilt monitor running. Press Ctrl+C to exit.\n");

    while (1) {
        float ax, ay, az, gx, gy, gz;
        if (!read_sensor(&ax, &ay, &az, &gx, &gy, &gz)) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float roll, pitch;
        calc_tilt(ax, ay, az, &roll, &pitch);

        printf("Roll: %7.2f  Pitch: %7.2f\n", roll, pitch);
        log_data(roll, pitch);

        int led_state = (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) ? 1 : 0;
        gpioWrite(LED_GPIO, led_state);

        gpioDelay(SAMPLE_US);
    }

    /* Unreachable, but kept for completeness */
    i2cClose(g_i2c);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    g_pigpio_inited = false;
    return EXIT_SUCCESS;
}

