        fprintf(stderr, "Error: I2C read of gyro data failed\n");
        return false;
    }

    int16_t raw_gx = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    int16_t raw_gy = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    int16_t raw_gz = (int16_t)((buf[4]  << 8) | (uint8_t)buf[3]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;

    return true;
}

static void calc_tilt(float ax, float ay, float az, float *roll, float *pitch)
{
    *roll  = atan2f(ay, az) * 180.0f / (float)M_PI;
    *pitch = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / (float)M_PI;
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* LED GPIO setup */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C */
    g_i2c = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }

    /* Wake up MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(g_i2c, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: could not wake MPU-6050\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }
    gpioDelay(100000);  /* 100 ms settle */

    /* Configure registers */
    if (i2cWriteByteData(g_i2c, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: could not set sample rate divider\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c, REG_GYRO_CONFIG,  0x00) < 0) {
        fprintf(stderr, "Error: could not set gyro range\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c, REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: could not set accel range\n");
        i2cClose(g_i2c);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 tilt monitor running. Press Ctrl+C to exit.\n");

    while (1) {
        float ax, ay, az, gx, gy, gz;
        if (!read_sensor(&ax, &ay, &az, &gx, &gy, &gz)) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float roll, pitch;
        calc_tilt(ax, ay, az, &roll, &pitch);

        printf("Roll: %7.2f  Pitch: %7.2f\n", roll, pitch);
        log_data(roll, pitch);

        int led_state = (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) ? 1 : 0;
        gpioWrite(LED_GPIO, led_state);

        gpioDelay(SAMPLE_US);
    }

    /* Unreachable, but kept for completeness */
    i2cClose(g_i2c);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    g_pigpio_inited = false;
    return EXIT_SUCCESS;
}

