#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define LED_PIN        17
#define PROX_THRESHOLD 100
#define LOG_FILE       "biometric_log.txt"
#define READ_INTERVAL  100000   /* microseconds */
#define RETRY_DELAY    10000    /* microseconds */
#define MAX_RETRIES    3

/* Si1145 / Si1182 register map (8-bit addresses) */
#define REG_PART_ID        0x00
#define REG_HW_KEY         0x07
#define REG_MEAS_RATE      0x08
#define REG_ALS_RATE       0x09
#define REG_PS_RATE        0x0A
#define REG_ALS_IR_ADCMUX  0x0F
#define REG_PS1_ADCMUX     0x10
#define REG_PS2_ADCMUX     0x11
#define REG_PS3_ADCMUX     0x12
#define REG_ALS_VIS_DATA0  0x22
#define REG_ALS_VIS_DATA1  0x23
#define REG_PS1_DATA0      0x24
#define REG_PS1_DATA1      0x25
#define REG_PS2_DATA0      0x26
#define REG_PS2_DATA1      0x27
#define REG_PS3_DATA0      0x28
#define REG_PS3_DATA1      0x29

#define HW_KEY_VAL         0x17
#define PART_ID_VAL        0x45

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si1145_init(int fd)
{
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, PART_ID_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_HW_KEY, HW_KEY_VAL) < 0)
        return -1;

    /* Measurement rate: 0 = manual / single-shot */
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, REG_ALS_RATE, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, REG_PS_RATE, 0x00) < 0)
        return -1;

    /* ALS IR ADC MUX: large IR photodiode */
    if (i2c_write_reg8(fd, REG_ALS_IR_ADCMUX, 0x00) < 0)
        return -1;
    /* PS1 ADC MUX: large IR photodiode */
    if (i2c_write_reg8(fd, REG_PS1_ADCMUX, 0x00) < 0)
        return -1;
    /* PS2 ADC MUX: large IR photodiode */
    if (i2c_write_reg8(fd, REG_PS2_ADCMUX, 0x00) < 0)
        return -1;
    /* PS3 ADC MUX: large IR photodiode */
    if (i2c_write_reg8(fd, REG_PS3_ADCMUX, 0x00) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(int fd, uint16_t *als, uint16_t *prox)
{
    uint8_t als_lo = 0, als_hi = 0, prox_lo = 0, prox_hi = 0;

    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &als_lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA1, &als_hi) < 0) return -1;
    *als = ((uint16_t)als_hi << 8) | als_lo;

    if (i2c_read_reg8(fd, REG_PS1_DATA0, &prox_lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS1_DATA1, &prox_hi) < 0) return -1;
    *prox = ((uint16_t)prox_hi << 8) | prox_lo;

    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t prox)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, als, prox);
    fflush(fp);
}

static void control_led(int state)
{
    int pin = LED_PIN;
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return;
    }
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, state);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si1145 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t als = 0, prox = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor_data(g_i2c_fd, &als, &prox) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY);
        }

        if (ok) {
            log_data(g_log_fp, als, prox);
            control_led(prox > PROX_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts\n", MAX_RETRIES);
        }

        usleep(READ_INTERVAL);
    }

    /* Graceful shutdown */
    control_led(0);
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

