/* ADXRS290 register addresses (from datasheet) */
#define ADXRS290_REG_XGYRO_OUT  0x04
#define ADXRS290_REG_YGYRO_OUT  0x06

/* SPI configuration */
#define SPI_CHANNEL  0          /* CE0 on GPIO8 (BCM) */
#define SPI_SPEED    1000000    /* 1 MHz */
#define SPI_FLAGS    0          /* Mode 0: CPOL=0, CPHA=0 */

/* Sampling */
#define SAMPLE_PERIOD_US  10000  /* 10 ms -> ~100 Hz */
#define MAX_RETRIES       3

/* Globals for cleanup */
static int  spi_handle = -1;
static FILE *fp        = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI                                                      */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single register (16-bit, little-endian)                       */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: spiXfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read both gyro axes                                                 */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate)
{
    if (read_register(ADXRS290_REG_XGYRO_OUT, x_rate) != 0)
        return -1;
    if (read_register(ADXRS290_REG_YGYRO_OUT, y_rate) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                               */
/* ------------------------------------------------------------------ */
static int log_data(FILE *f, int16_t x_rate, int16_t y_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(f, "%s.%06ld,%d,%d\n",
                timestamp, ts.tv_nsec / 1000,
                x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(f) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

