#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17

#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_US   2000000  /* 2 seconds */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Log a seismic event with an ISO-8601 timestamp                      */
/* ------------------------------------------------------------------ */
static void log_seismic_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Alert callback — fires once when both sensors are HIGH for          */
/* SEISMIC_THRESHOLD_MS milliseconds                                  */
/* ------------------------------------------------------------------ */
static void alert_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t last_tick = 0;
    static int      both_high = 0;

    if (level == 1) {
        if (gpioRead(SENSOR_1_PIN) == 1 && gpioRead(SENSOR_2_PIN) == 1) {
            both_high = 1;
            last_tick = tick;
        }
    } else if (level == 0) {
        both_high = 0;
    }

    if (both_high) {
        uint32_t elapsed = tick - last_tick;  /* pigpio tick is uint32_t */

        if (elapsed >= (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
            if (gpioWrite(ALERT_PIN, 1) == 0) {
                log_seismic_event();
                gpioDelay(ALERT_DURATION_US);
                gpioWrite(ALERT_PIN, 0);
            }
            both_high = 0;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("seismic_events.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs with pull-down ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    /* ---- Configure alert pin as output, initially LOW ---- */
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin mode\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    /* ---- Register alert callback on both edges ---- */
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, alert_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, alert_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert callbacks\n");
        gpioWrite(ALERT_PIN, 0);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        gpioWrite(ALERT_PIN, 0);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop — sleep until signal ---- */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    fclose(g_log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

