#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define GYRO_XOUT_H    0x04       /* ADXRS290 X-axis data register */
#define GYRO_XOUT_L    0x05
#define GYRO_CTRL_REG1 0x10       /* control register 1 */
#define GYRO_CTRL_REG2 0x11       /* control register 2 */
#define GYRO_STATUS    0x27       /* status register */
#define GYRO_STATUS_XRDY 0x80     /* X data ready bit */
#define GYRO_CTRL1_XGAIN 0x40    /* X-axis gain = 1 */
#define GYRO_CTRL1_MODE 0x01      /* mode = 1 (continuous) */
#define GYRO_CTRL2_DLPF 0x00      /* digital LPF = 0 */
#define GYRO_CTRL2_INT  0x00      /* interrupt disabled */
#define GYRO_CTRL2_EN  0x00      /* gyro enabled */
#define GYRO_CTRL1_VAL  (GYRO_CTRL1_MODE | GYRO_CTRL1_XGAIN)
#define GYRO_CTRL2_VAL  (GYRO_CTRL2_EN)
#define GYRO_STATUS_VAL 0x00
#define GYRO_DATA_MASK  0x03      /* low 2 bits of status */
#define GYRO_DATA_READY (1 << 7)
#define GYRO_READ_DELAY_US 1000   /* 1 ms between reads */
#define GYRO_INIT_DELAY_US 10000  /* 10 ms settle */
#define BUFFER_SIZE      100
#define THRESHOLD_DEG_S  20.0f
#define LED_PIN          17
#define SAMPLE_PERIOD_US 100000   /* 100 ms */

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float gyro_x_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* ---- Globals ---- */
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;
static circular_buffer_t gyro_buffer;
static bool led_state = false;

/* ---- Prototypes ---- */
static int  spi_read_register(uint8_t reg, uint8_t *value);
static int  spi_write_register(uint8_t reg, uint8_t value);
static int  adxrs290_init(void);
static int  adxrs290_read_gyro(float *gyro_x_rate);
static void buffer_init(circular_buffer_t *buf);
static void buffer_add(circular_buffer_t *buf, const gyro_data_t *data);
static void buffer_print(const circular_buffer_t *buf);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- SPI helpers ---- */
static int spi_read_register(uint8_t reg, uint8_t *value)
{
    char tx[2], rx[2];
    tx[0] = (char)(reg | 0x80);  /* MSB = 1 for read */
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read error on reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value)
{
    char tx[2];
    tx[0] = (char)(reg & 0x7F);  /* MSB = 0 for write */
    tx[1] = (char)value;

    if (spiWrite(spi_handle, tx, 2) != 2) {
        fprintf(stderr, "SPI write error on reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ---- ADXRS290 driver ---- */
static int adxrs290_init(void)
{
    uint8_t ctrl1, ctrl2, status;

    /* Read back CTRL_REG1 to confirm device is present */
    if (spi_read_register(GYRO_CTRL_REG1, &ctrl1) != 0)
        return -1;
    if (spi_read_register(GYRO_CTRL_REG2, &ctrl2) != 0)
        return -1;
    if (spi_read_register(GYRO_STATUS, &status) != 0)
        return -1;

    if ((status & GYRO_DATA_MASK) != GYRO_DATA_READY) {
        fprintf(stderr, "ADXRS290 not ready (status=0x%02X)\n", status);
        return -1;
    }

    /* Disable gyro, then configure */
    if (spi_write_register(GYRO_CTRL_REG1, 0x00) != 0)
        return -1;
    if (spi_write_register(GYRO_CTRL_REG2, GYRO_CTRL2_VAL) != 0)
        return -1;
    if (spi_write_register(GYRO_CTRL_REG1, GYRO_CTRL1_VAL) != 0)
        return -1;

    gpioDelay(GYRO_INIT_DELAY_US);
    return 0;
}

static int adxrs290_read_gyro(float *gyro_x_rate)
{
    uint8_t xh, xl;
    int16_t raw;

    if (spi_read_register(GYRO_XOUT_H, &xh) != 0)
        return -1;
    if (spi_read_register(GYRO_XOUT_L, &xl) != 0)
        return -1;

    raw = (int16_t)((xh << 8) | xl);
    *gyro_x_rate = (float)raw / 32768.0f * 250.0f;  /* deg/s */
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->tail  = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, const gyro_data_t *data)
{
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = *data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

