        localtime_r(&buf->data[idx].timestamp.tv_sec, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("  [%d] %s.%03ld  gyro_x_rate = %.2f deg/s\n",
               idx, ts, buf->data[idx].timestamp.tv_nsec / 1000000L,
               buf->data[idx].gyro_x_rate);
    }
    pthread_mutex_unlock(&buf->mutex);
}

/* ---- Signal handling ---- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

/* ---- Main ---- */
int main(void)
{
    float gyro_x_rate;
    gyro_data_t data;
    struct timespec sleep_time = {0, SAMPLE_PERIOD_US * 1000L};

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED */
    gpioSetMode(LED_PIN, PI_OUTPUT);
