/*
 * Smart Sunset Simulator for Raspberry Pi Zero W
 * Three dimmable lamps on GPIO17, GPIO18, GPIO27 (BCM 11, 12, 13)
 * Fades each lamp from 100% to 0% over a user-specified total duration.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset sunset.c -lpigpio -lrt
 * Run:    sudo ./sunset 3600
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_LAMPS      3
#define PWM_RANGE      255          /* 8-bit resolution */
#define PWM_FREQ_HZ    100          /* 100 Hz hardware PWM */
#define MIN_DURATION   1            /* seconds */
#define MAX_DURATION   3600         /* seconds */

static const int lamp_pins[NUM_LAMPS] = {17, 18, 27};

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void all_lamps_off(void)
{
    for (int i = 0; i < NUM_LAMPS; i++)
        gpioPWM(lamp_pins[i], 0);
}

static void cleanup(void)
{
    all_lamps_off();
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  total_duration: %d - %d seconds\n", MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: invalid duration '%s'\n", argv[1]);
        return EXIT_FAILURE;
    }
    if (duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be between %d and %d seconds\n",
                MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    install_signal_handlers();

    /* ---- configure lamp pins as hardware PWM outputs ---- */
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (gpioSetMode(lamp_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", lamp_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(lamp_pins[i], PWM_FREQ_HZ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", lamp_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(lamp_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", lamp_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        /* Start at full brightness */
        if (gpioPWM(lamp_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d, %d) initialisation failed\n",
                    lamp_pins[i], PWM_RANGE);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Smart Sunset Simulator started.\n");
    printf("  Total duration : %ld s\n", duration);
    printf("  Lamp pins      : GPIO17, GPIO18, GPIO27\n");
    printf("  PWM frequency  : %d Hz, range : 0-%d\n", PWM_FREQ_HZ, PWM_RANGE);
    printf("Press Ctrl+C to exit early.\n");
    fflush(stdout);

    /* ---- main fade loop ---- */
    for (int i = 0; i < NUM_LAMPS && g_running; i++) {
        int pin = lamp_pins[i];

        printf("\n--- Fading lamp %d (GPIO%d) ---\n", i + 1, pin);
        fflush(stdout);

        /* Fade from 100% to 0% */
        for (int duty = PWM_RANGE; duty >= 0 && g_running; duty--) {
            if (gpioPWM(pin, duty) != 0) {
                fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n", pin, duty);
            }
            /* Sleep in small increments so SIGINT is responsive */
            for (int s = 0; s < 10 && g_running; s++)
                usleep(50 * 1000);  /* 50 ms */
        }

        if (!g_running) {
            printf("  Fade interrupted by signal.\n");
            break;
        }

        if (gpioPWM(pin, 0) != 0)
            fprintf(stderr, "Warning: gpioPWM(%d, 0) failed\n", pin);

        printf("  Lamp %d off.\n", i + 1);
        fflush(stdout);
    }

    /* ---- final status ---- */
    if (!g_running) {
        printf("\nSimulation terminated by signal.\n");
    } else {
        printf("Simulation complete.\n");
    }
    printf("All lamps off. pigpio terminated.\n");
    fflush(stdout);

    cleanup();
    return EXIT_SUCCESS;
}

