#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define POLL_DELAY_US 50000  /* 50 ms */
#define DEBOUNCE_READS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_flame_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_alert(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate buzzer\n");
        return -1;
    }
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate LED\n");
        gpioWrite(BUZZER_PIN, 0);
        return -1;
    }
    return 0;
}

static int deactivate_alert(void) {
