/*
 * Pneumatic dispensing system controller for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - Two 12 V push-pull solenoids driven through TIP120 Darlington transistors.
 *   - Solenoid 1 -> GPIO17 (BCM)
 *   - Solenoid 2 -> GPIO27 (BCM)
 *
 * Behavior:
 *   Dispenses every 5 s in a continuous loop.
 *   Solenoid 1 ON for 500 ms, then Solenoid 2 ON for 500 ms.
 *   Both solenoids OFF after the dispense cycle.
 *
 * Logging:
 *   Timestamp, solenoid pins, and duration (ms) appended to dispense_log.txt.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o dispense dispense.c -lthe_driver
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <the_driver.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_S  5
#define LOG_FILE_NAME       "dispense_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on Ctrl+C                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a dispense event to the log file                             */
/* ------------------------------------------------------------------ */
static int log_dispense_event(int s1_pin, int s2_pin, int duration_ms)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, GPIO%d, GPIO%d, %d ms\n",
                timestamp, s1_pin, s2_pin, duration_ms) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate a solenoid for the given duration (ms)                      */
/* ------------------------------------------------------------------ */
static int activate_solenoid(int pin, int duration_ms)
{
    if (the_driver_set_pin_state(pin, THE_DRIVER_PIN_STATE_ON) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d ON\n", pin);
        return -1;
    }

    /* the_driver_call() blocks for the given duration in milliseconds */
    if (the_driver_call(duration_ms) != 0) {
        fprintf(stderr, "Error: the_driver_call() failed on GPIO%d\n", pin);
        the_driver_set_pin_state(pin, THE_DRIVER_PIN_STATE_OFF);
        return -1;
    }

    if (the_driver_set_pin_state(pin, THE_DRIVER_PIN_STATE_OFF) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d OFF\n", pin);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Dispense one cycle: solenoid 1 ON 500 ms, then solenoid 2 ON 500 ms  */
/* ------------------------------------------------------------------ */
static int dispense_cycle(void)
{
    if (activate_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION_MS / 2) != 0) {
        return -1;
    }

    if (activate_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION_MS / 2) != 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize the driver library */
    if (the_driver_init() != 0) {
        fprintf(stderr, "Error: the_driver_init() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 and GPIO27 as outputs */
    if (the_driver_set_pin_direction(SOLENOID_1_PIN, THE_DRIVER_PIN_DIRECTION_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        the_driver_terminate();
        return EXIT_FAILURE;
    }

    if (the_driver_set_pin_direction(SOLENOID_2_PIN, THE_DRIVER_PIN_DIRECTION_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        the_driver_terminate();
        return EXIT_FAILURE;
    }

    /* Ensure both solenoids are OFF at start */
    if (the_driver_set_pin_state(SOLENOID_1_PIN, THE_DRIVER_PIN_STATE_OFF) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW\n", SOLENOID_1_PIN);
        the_driver_terminate();
        return EXIT_FAILURE;
    }

    if (the_driver_set_pin_state(SOLENOID_2_PIN, THE_DRIVER_PIN_STATE_OFF) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW\n", SOLENOID_2_PIN);
        the_driver_terminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        the_driver_terminate();
        return EXIT_FAILURE;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");
    printf("Dispensing every %d s, each cycle %d ms (s1 ON %d ms, s2 ON %d ms).\n",
           DISPENSE_INTERVAL_S, DISPENSE_DURATION_MS,
           DISPENSE_DURATION_MS / 2, DISPENSE_DURATION_MS / 2);

    while (g_running) {
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Error: dispense cycle failed, continuing...\n");
        }

        /* Sleep for the interval between dispense cycles */
        if (the_driver_call(DISPENSE_INTERVAL_S * 1000) != 0) {
            fprintf(stderr, "Error: the_driver_call() failed during sleep\n");
        }
    }

    /* Graceful shutdown: deactivate both solenoids */
    the_driver_set_pin_state(SOLENOID_1_PIN, THE_DRIVER_PIN_STATE_OFF);
    the_driver_set_pin_state(SOLENOID_2_PIN, THE_DRIVER_PIN_STATE_OFF);

    the_driver_terminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

