#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* Motor A */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* L298N Enable pins */
#define MOTOR_ENABLE_A 24
#define MOTOR_ENABLE_B 25

/* PID parameters */
#define KP 0.5
#define KI 0.1
#define KD 0.01

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_AVOIDANCE_THRESHOLD 20.0

/* PWM range */
#define PWM_RANGE 255

/* PID loop period (ms) */
#define PID_PERIOD_MS 50

/* Global variables */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* PID state */
typedef struct {
    double integral;
    double previous_error;
} PIDState;

static PIDState pid_a = {0.0, 0.0};
static PIDState pid_b = {0.0, 0.0};

/* Function prototypes */
static int initialize_gpio(void);
static void cleanup_gpio(void);
static void signal_handler(int signal);
static int pid_control(double setpoint, double actual, PIDState *pid, double *output);
static void set_motor_speed(int motor_a_speed, int motor_b_speed);
static int read_distance_sensor(void);
static double calculate_tilt_error(void);
static void log_data(double tilt_error, int distance, int motor_a_speed, int motor_b_speed);
static void obstacle_avoidance(int distance, int motor_a_speed, int motor_b_speed);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initializes the pigpio library and sets GPIO modes */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set motor control pins as outputs */
    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENABLE_A, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENABLE_B, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    /* Enable both motors (EN pins must be HIGH for PWM to work) */
    if (gpioWrite(MOTOR_ENABLE_A, 1) != 0 || gpioWrite(MOTOR_ENABLE_B, 1) != 0) {
        fprintf(stderr, "Failed to enable motors\n");
        gpioTerminate();
        return 1;
    }

    /* Set PWM range for all motor pins */
    if (gpioSetPWMrange(MOTOR_A_FORWARD, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_A_BACKWARD, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_FORWARD, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_BACKWARD, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

