#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int relay_state = 0;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        fprintf(stderr, "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF (LOW) */
    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW (code %d).\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Touch GPIO%d to toggle relay on GPIO%d.\n", TOUCH_SENSOR_PIN, RELAY_PIN);

    while (running) {
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_detected < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", TOUCH_SENSOR_PIN, touch_detected);
            break;
        }

        if (touch_detected == 1) {
            relay_state = !relay_state;
            ret = gpioWrite(RELAY_PIN, relay_state);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to write GPIO%d (code %d).\n", RELAY_PIN, ret);
                break;
            }
            printf("Touch detected! Relay toggled to %s.\n", relay_state ? "ON" : "OFF");
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000);  /* 10 ms polling interval */
    }

    /* Cleanup: ensure relay is OFF and terminate pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

