/*
 * mood_light.c — ALSA audio-driven RGB mood light for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lm -lpigpio -lrt
 * Run:    sudo ./mood_light [sensitivity_scale]
 *
 * Wiring (common-cathode RGB LED, current-limiting resistors on each leg):
 *   Red   -> GPIO17 (BCM) via 330 ohm
 *   Green -> GPIO18 (BCM) via 330 ohm
 *   Blue  -> GPIO27 (BCM) via 330 ohm
 *   LED + -> 3.3 V (Pi pin 1)
 *   LED - -> GND  (Pi pin 6)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define SAMPLE_RATE      8000
#define PERIOD_SIZE      1024          /* frames per period (buffer size) */
#define BUFFER_FRAMES    (PERIOD_SIZE * 10) /* 10 ms worth of frames */
#define ALSA_DEVICE      "default"
#define DEFAULT_SENSITIVITY 1.0

/* ----------------------------- ALSA types (conditional) ----------------- */
#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
typedef snd_pcm_t pcm_handle_t;
typedef snd_pcm_hw_params_t hw_params_t;
#else
typedef int pcm_handle_t;
typedef int hw_params_t;
#endif

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static double g_sensitivity = DEFAULT_SENSITIVITY;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
#ifdef ALSA_AVAILABLE
static int  init_alsa(pcm_handle_t *handle);
static int  read_audio_buffer(pcm_handle_t handle, short *buffer, int frames);
static double calculate_rms(const short *buffer, int frames);
static void map_rms_to_color(double rms, double sensitivity);
static void set_led_color(int red, int green, int blue);
#else
static int  init_alsa(pcm_handle_t *handle);
static int  read_audio_buffer(pcm_handle_t handle, short *buffer, int frames);
static double calculate_rms(const short *buffer, int frames);
static void map_rms_to_color(double rms, double sensitivity);
static void set_led_color(int red, int green, int blue);
#endif

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    /* Turn off the LED first so the light goes dark immediately */
    set_led_color(0, 0, 0);

    /* Release pigpio resources */
    gpioTerminate();

#ifdef ALSA_AVAILABLE
    /* Release the ALSA handle */
    pcm_handle_t handle;
    if (pcm_handle_t *h = (pcm_handle_t *)&g_alsa_handle) {
        snd_pcm_close(*h);
    }
#endif

    fprintf(stderr, "\nCleanup complete. Exiting.\n");
}

/* ----------------------------- ALSA init ---------------------------------- */
#ifdef ALSA_AVAILABLE
static int init_alsa(pcm_handle_t *handle)
{
    int err;

    err = snd_pcm_open(handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error opening ALSA device '%s': %s\n",
                ALSA_DEVICE, snd_strerror(err));
        return -1;
    }

    hw_params_t hp;
    snd_pcm_hw_params_alloca(&hp);

    err = snd_pcm_hw_params_any(handle, &hp);
    if (err < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*handle);
        return -1;
    }

    err = snd_pcm_hw_params_set_access(handle, &hp, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*handle);
        return -1;
    }

    err = snd_pcm_hw_params_set_format(handle, &hp, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error setting sample format: %s\n", snd_strerror(err));
        snd_pcm_close(*handle);
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(handle, &hp, SAMPLE_RATE, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*handle);
        return -1;
    }

