static int init_alsa(pcm_handle_t *handle)
{
    (void)handle;
    fprintf(stderr, "ALSA not available; simulating sine-wave audio.\n");
    return 0;
}
#endif

/* ----------------------------- Read audio buffer -------------------------- */
#ifdef ALSA_AVAILABLE
static int read_audio_buffer(pcm_handle_t handle, short *buffer, int frames)
{
    int err = snd_pcm_readi(handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun (EPIPE). Reinitializing...\n");
        snd_pcm_prepare(handle);
        return -1;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "ALSA device suspended (ESTRPIPE). Resuming...\n");
        snd_pcm_drain(handle);
        snd_pcm_prepare(handle);
        return -1;
    }
    if (err < 0) {
        fprintf(stderr, "ALSA read error: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}
#else
static int read_audio_buffer(pcm_handle_t handle, short *buffer, int frames)
{
    (void)handle;
    (void)buffer;
    (void)frames;
    return 0;
}
#endif

/* ----------------------------- RMS ---------------------------------------- */
static double calculate_rms(const short *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / (double)frames);
}

/* ----------------------------- Color mapping ------------------------------ */
static void map_rms_to_color(double rms, double sensitivity)
{
    /* Non-linear mapping: 0 -> black, 1.0 -> white */
    double norm = rms / (sensitivity * 32768.0);   /* 32768 = 2^15 */
    if (norm < 0.0) norm = 0.0;
    if (norm > 1.0) norm = 1.0;

    int red   = (int)(norm * 255.0);
    int green = (int)((1.0 - norm) * 255.0);
    int blue  = 0;

    set_led_color(red, green, blue);
