/* pigpio I2C handle */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a TCS34725 register */
static int tcs34725_write_byte(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a byte from a TCS34725 register */
static int tcs34725_read_byte(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Initialize the TCS34725 sensor */
static int tcs34725_init(void) {
    uint8_t id = 0;

    /* Verify sensor identity */
    if (tcs34725_read_byte(TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (tcs34725_write_byte(TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        return -1;
    }
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Set integration time to 154 ms */
    if (tcs34725_write_byte(TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        return -1;
    }

    /* Enable RGBC ADC */
    if (tcs34725_write_byte(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        return -1;
    }

    return 0;
}

/* Read color values from the TCS34725 sensor */
static int tcs34725_read_color(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t cl, ch, rl, rh, gl, gh, bl, bh;

    if (tcs34725_read_byte(TCS34725_CDATAL, &cl) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_CDATAH, &ch) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_RDATAL, &rl) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_RDATAH, &rh) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_GDATAL, &gl) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_GDATAH, &gh) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_BDATAL, &bl) < 0) return -1;
    if (tcs34725_read_byte(TCS34725_BDATAH, &bh) < 0) return -1;

    *c = ((uint16_t)ch << 8) | cl;
    *r = ((uint16_t)rh << 8) | rl;
    *g = ((uint16_t)gh << 8) | gl;
    *b = ((uint16_t)bh << 8) | bl;

    return 0;
}

/* Log color data to a CSV file */
static int log_color_data(FILE *fp, uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)rawtime, c, r, g, b) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    uint16_t c, r, g, b;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TCS34725 address */
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the TCS34725 sensor */
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the CSV file for logging */
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write the CSV header */
    if (fprintf(fp, "timestamp,c,r,g,b\n") < 0) {
        fprintf(stderr, "Error writing CSV header\n");
        fclose(fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(fp);

    /* Register signal handlers for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (!terminate) {
        /* Read color values from the sensor */
        if (tcs34725_read_color(&c, &r, &g, &b) == 0) {
            /* Log the color data to the CSV file */
            if (log_color_data(fp, c, r, g, b) != 0) {
                fprintf(stderr, "Error logging color data\n");
            }
        } else {
            fprintf(stderr, "Error reading color data\n");
        }

        /* Wait 500 ms before the next reading */
        gpioDelay(500000); /* 500 ms in microseconds */
    }

    /* Clean up resources on exit */
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

