#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 17040

#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_all_relays(int state) {
    gpioWrite(RELAY1_PIN, state);
    gpioWrite(RELAY2_PIN, state);
    gpioWrite(RELAY3_PIN, state);
    gpioWrite(RELAY4_PIN, state);
}

static void cleanup(void) {
    set_all_relays(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQ);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQ);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQ);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQ);

    set_all_relays(0);

    while (running) {
        /* Sunrise: 0% -> 100% over 3600 seconds */
        for (int i = 0; i <= SUNRISE_DURATION && running; i++) {
            int duty = (int)(((float)i / SUNRISE_DURATION) * PWM_RANGE);
            gpioPWM(RELAY1_PIN, duty);
            gpioPWM(RELAY2_PIN, duty);
            gpioPWM(RELAY3_PIN, duty);
            gpioPWM(RELAY4_PIN, duty);
            gpioDelay(1000000 / (SUNRISE_DURATION / SUNRISE_DURATION));
        }

        /* Daytime: 100% -> 100% over 21600 seconds */
        for (int i = 0; i <= DAYTIME_DURATION && running; i++) {
            gpioPWM(RELAY1_PIN, PWM_RANGE);
            gpioPWM(RELAY2_PIN, PWM_RANGE);
            gpioPWM(RELAY3_PIN, PWM_RANGE);
            gpioPWM(RELAY4_PIN, PWM_RANGE);
            gpioDelay(1000000 / (DAYTIME_DURATION / DAYTIME_DURATION));
        }

        /* Sunset: 100% -> 0% over 3600 seconds */
        for (int i = 0; i <= SUNSET_DURATION && running; i++) {
            int duty = (int)(((float)SUNSET_DURATION - i) / SUNSET_DURATION * PWM_RANGE);
            gpioPWM(RELAY1_PIN, duty);
            gpioPWM(RELAY2_PIN, duty);
            gpioPWM(RELAY3_PIN, duty);
            gpioPWM(RELAY4_PIN, duty);
            gpioDelay(1000000 / (SUNSET_DURATION / SUNSET_DURATION));
        }

        /* Nighttime: 0% -> 0% over 17040 seconds */
        for (int i = 0; i <= NIGHTTIME_DURATION && running; i++) {
            gpioPWM(RELAY1_PIN, 0);
            gpioPWM(RELAY2_PIN, 0);
            gpioPWM(RELAY3_PIN, 0);
            gpioPWM(RELAY4_PIN, 0);
            gpioDelay(1000000 / (NIGHTTIME_DURATION / NIGHTTIME_DURATION));
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

