#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static int read_sensor(void) {
    int val = gpioRead(SENSOR_GPIO);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", SENSOR_GPIO);
        return -1;
    }
    return val;
}

static int debounce(int *last_trigger_ms) {
    int val = read_sensor();
    if (val < 0) return -1;
    if (val == 0) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error: time() failed.\n");
            return -1;
        }
        int current_ms = (int)(now % 1000);
        if (current_ms - *last_trigger_ms >= DEBOUNCE_MS) {
            *last_trigger_ms = current_ms;
            return 1;
        }
    }
    return 0;
}

static int capture_video(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return -1;
    }
    struct tm *tm_info = localtime(&now);
    if (tm_info == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }
    char filename[64];
    strftime(filename, sizeof(filename), VIDEO_DIR "%Y%m%d_%H%M%S.h264", tm_info);

    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d -w 640 -h 480 -fps 30",
             filename, VIDEO_DURATION_SEC * 1000);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid.\n");
        return -1;
    }
    if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n", WEXITSTATUS(result));
        return -1;
    }
    if (WIFSIGNALED(result)) {
        fprintf(stderr, "Error: raspivid killed by signal %d.\n", WTERMSIG(result));
        return -1;
    }
    return 0;
}

static int log_motion(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return -1;
    }
    struct tm *tm_info = localtime(&now);
    if (tm_info == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(log_fp, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        fclose(log_fp);
        log_fp = NULL;
        return -1;
    }
    if (fclose(log_fp) != 0) {
        fprintf(stderr, "Error: failed to close log file: %s\n", strerror(errno));
        log_fp = NULL;
        return -1;
    }
    log_fp = NULL;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    int last_trigger_ms = 0;
    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        int motion = debounce(&last_trigger_ms);
        if (motion < 0) {
            fprintf(stderr, "Error: sensor read failed, exiting.\n");
            break;
        }
        if (motion) {
            printf("Motion detected!\n");
            if (capture_video() != 0) {
                fprintf(stderr, "Error: video capture failed.\n");
            }
            if (log_motion() != 0) {
                fprintf(stderr, "Error: motion logging failed.\n");
            }
        }
        gpioDelay(10000);
    }

    gpioTerminate();
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    printf("Exiting cleanly.\n");
    return 0;
}

