#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Sensitivity scale factor for +/- 250 deg/s range */
#define GYRO_SCALE 131.0f

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms = 100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Max consecutive read failures before re-initialization */
#define MAX_READ_FAILURES 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPU-6050 register                               */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an MPU-6050 register                             */
/* ------------------------------------------------------------------ */
static int mpu_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake, configure gyro range, verify identity*/
/* ------------------------------------------------------------------ */
static int mpu6050_init(int handle)
{
    uint8_t who_am_i = 0;

    /* Read WHO_AM_I to confirm device presence */
    if (mpu_read_reg(handle, MPU6050_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (mpu_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050.\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization after wake-up */

    /* Configure gyro full-scale range to +/- 250 deg/s (FS_SEL = 0) */
    if (mpu_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure gyro range.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyro data and convert to deg/s                     */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    int rc = i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one sample to the CSV log file                               */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + (ts.tv_nsec / 1000000LL);

    if (fprintf(fp, "%lld,%.3f,%.3f,%.3f\n", timestamp_ms, x, y, z) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Re-initialize the MPU-6050 after a failure                           */
/* ------------------------------------------------------------------ */
static int reinitialize_mpu6050(int handle)
{
    if (handle >= 0) {
        i2cClose(handle);
        handle = -1;
    }

    gpioDelay(100000); /* 100 ms cool-off before retry */

    handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %d\n", handle);
        return -1;
    }

    if (mpu6050_init(handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 re-initialization failed.\n");
        i2cClose(handle);
        handle = -1;
        return -1;
    }

    return handle;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;
    int consecutive_failures = 0;
    int handle = -1;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to MPU-6050 */
    handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (mpu6050_init(handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error: fopen gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,X_degps,Y_degps,Z_degps\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_gyro_data(handle, &x, &y, &z) == 0) {
            consecutive_failures = 0;
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: Gyro read failure (%d/%d).\n",
                    consecutive_failures, MAX_READ_FAILURES);

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max consecutive read failures reached. "
                                "Attempting re-initialization...\n");
                handle = reinitialize_mpu6050(handle);
                if (handle < 0) {
                    fprintf(stderr, "Error: Re-initialization failed. "
                                    "Continuing to retry...\n");
                } else {
                    consecutive_failures = 0;
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

