#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static const int relay_pins[4] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d HIGH\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 100;
}

static int control_relay(int pin, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", pin);
        return -1;
    }
    return state;
}

static int log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_fp, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp, moisture_level,
                relay1_state ? "ON" : "OFF",
                relay2_state ? "ON" : "OFF",
                relay3_state ? "ON" : "OFF",
                relay4_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (g_running) {
        int moisture_level = read_moisture_sensor();
        int relay1_state = control_relay(RELAY1_PIN, moisture_level);
        int relay2_state = control_relay(RELAY2_PIN, moisture_level);
        int relay3_state = control_relay(RELAY3_PIN, moisture_level);
        int relay4_state = control_relay(RELAY4_PIN, moisture_level);

        if (relay1_state < 0 || relay2_state < 0 || relay3_state < 0 || relay4_state < 0) {
            fprintf(stderr, "Error: GPIO write failure during main loop\n");
            break;
        }

        if (log_data(moisture_level, relay1_state, relay2_state, relay3_state, relay4_state) < 0) {
            fprintf(stderr, "Error: logging failed\n");
            break;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

