#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (documented by Analog Devices) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 register addresses */
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0    0x32
#define ADXL345_DATAX1    0x33
#define ADXL345_DATAY0    0x34
#define ADXL345_DATAY1    0x35
#define ADXL345_DATAZ0    0x36
#define ADXL345_DATAZ1    0x37

/* Free-fall threshold: 0.2 g (20 mg) */
#define FREEFALL_THRESHOLD 0.2f

/* GPIO pin for alarm (BCM numbering) */
#define ALARM_GPIO 27

/* Polling interval in microseconds (100 ms) */
#define POLL_INTERVAL_US 100000

/* Confirmation delay in microseconds (0.5 s) */
#define CONFIRM_DELAY_US 500000

/* Alarm hold time in microseconds (5 s) */
#define ALARM_HOLD_US 5000000

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register                               */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a block of 6 bytes starting at DATAX0                            */
/* ------------------------------------------------------------------ */
static int adxl_read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];

    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed: %d (expected 6)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint8_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)(((uint8_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)(((uint8_t)buffer[5] << 8) | (uint8_t)buffer[4]);

    /* Convert to g: 4 mg/LSB = 0.004 g/LSB */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Detect free-fall: all three axes below threshold                    */
/* ------------------------------------------------------------------ */
static bool is_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* ------------------------------------------------------------------ */
/* Log a free-fall event to freefall.log                                 */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        perror("Error opening freefall.log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "TIMESTAMP_ERROR,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Trigger alarm on GPIO27 for ALARM_HOLD_US seconds                   */
/* ------------------------------------------------------------------ */
static void trigger_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: failed to set alarm GPIO high\n");
        return;
    }
    gpioDelay(ALARM_HOLD_US);
    if (gpioWrite(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: failed to set alarm GPIO low\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Power control register: set bit D3 (0x08) to enter measurement mode */
    if (adxl_write_reg(g_i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set ADXL345 measurement mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO as output, initially low */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 free-fall monitor started. Press Ctrl+C to exit.\n");

    bool freefall_detected = false;
    uint32_t freefall_start_tick = 0;

    while (g_running) {
        float x, y, z;

        if (adxl_read_acceleration(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (is_freefall(x, y, z)) {
            if (!freefall_detected) {
                freefall_detected = true;
                freefall_start_tick = gpioTick();
                printf("Free-fall detected (x=%.3f, y=%.3f, z=%.3f) — waiting for confirmation...\n",
                       x, y, z);
            } else {
                uint32_t elapsed = gpioTick() - freefall_start_tick;
                if (elapsed >= CONFIRM_DELAY_US) {
                    printf("Free-fall confirmed (x=%.3f, y=%.3f, z=%.3f) — triggering alarm...\n",
                           x, y, z);
                    log_freefall(x, y, z);
                    trigger_alarm();
                    freefall_detected = false;
                }
            }
        } else {
            freefall_detected = false;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

