#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MAX_DISTANCE_CM 23.2
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define INTER_TRIGGER_DELAY_US 200000
#define ECHO_TIMEOUT_NS 100000000L

static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile bool      g_echo_seen  = false;
static volatile bool      g_new_pulse  = false;
static volatile bool      g_running    = true;
static FILE               *g_log_file  = NULL;
static bool                g_first     = true;

static void echo_rising_edge(int gpio, int level, uint32_t tick, void *userdata);
static void echo_falling_edge(int gpio, int level, uint32_t tick, void *userdata);
static void trigger_sensor(void);
static void log_distance(double distance);
static void signal_handler(int sig);
static void cleanup(void);

static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

static void echo_rising_edge(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    g_pulse_start = tick;
    g_echo_seen   = false;
    g_new_pulse   = true;
}

static void echo_falling_edge(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;
    g_pulse_end = tick;
    g_echo_seen = true;
}

static void trigger_sensor(void)
{
    g_pulse_start = 0;
    g_pulse_end   = 0;
    g_echo_seen   = false;
    g_new_pulse   = false;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
    }
}

static void log_distance(double distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%llu,%lf\n", (unsigned long long)timestamp_ns, distance);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

static void cleanup(void)
{
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIGGER_PIN, NULL, NULL);
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    pthread_mutex_destroy(&g_mutex);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
