        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%llu,%lf\n", (unsigned long long)timestamp_ns, distance);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

