/*
 * LIS3DH Impact Detector for Raspberry Pi 5
 *
 * Reads an Adafruit LIS3DH accelerometer on I2C bus 1 and sounds a buzzer
 * on GPIO17 (BCM) when an impact is detected.
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_detector impact_detector.c -lm -lpigpio -lrt
 * Run:    sudo ./impact_detector [freefall_g] [impact_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

/* ---- LIS3DH register definitions (verified against datasheet) ---- */
#define LIS3DH_ADDR        0x19          /* SA0 tied to GND on Adafruit breakout */
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

#define LIS3DH_WHO_AM_I_VAL 0x33

/* ---- Defaults ---- */
#define DEFAULT_FREEFALL_G  0.2f
#define DEFAULT_IMPACT_G    1.5f
#define DEFAULT_I2C_BUS     1
#define DEFAULT_BUZZER_GPIO 17
#define DEFAULT_SAMPLE_US   10000   /* 10 ms */
#define DEFAULT_I2C_RETRIES 3

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_i2c_bus    = DEFAULT_I2C_BUS;
static int g_buzzer_gpio = DEFAULT_BUZZER_GPIO;
static float g_freefall_g = DEFAULT_FREEFALL_G;
static float g_impact_g   = DEFAULT_IMPACT_G;
static int   g_i2c_retries = DEFAULT_I2C_RETRIES;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers with retry ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < g_i2c_retries; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *val = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, g_i2c_retries, rc);
        gpioDelay(1000); /* 1 ms back-off */
    }
    return -1;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    for (int attempt = 0; attempt < g_i2c_retries; attempt++) {
        int rc = i2cWriteByteData(handle, reg, val);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, g_i2c_retries, rc);
        gpioDelay(1000);
    }
    return -1;
}

/* ---- Sensor init ---- */
static int init_lis3dh(int handle)
{
    uint8_t who;
    if (i2c_read_reg(handle, LIS3DH_REG_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL1: 0x77 -> 12-bit mode, normal data rate, all axes enabled */
    if (i2c_write_reg(handle, LIS3DH_REG_CTRL1, 0x77) != 0) return -1;

    /* CTRL4: 0x00 -> no high-resolution, no FIFO, no interrupts */
    if (i2c_write_reg(handle, LIS3DH_REG_CTRL4, 0x00) != 0) return -1;

    return 0;
}

/* ---- Read acceleration (raw 12-bit left-justified) ---- */
static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg(handle, LIS3DH_REG_OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg(handle, LIS3DH_REG_OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg(handle, LIS3DH_REG_OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg(handle, LIS3DH_REG_OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg(handle, LIS3DH_REG_OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg(handle, LIS3DH_REG_OUT_Z_H, &zh) != 0) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

/* ---- Convert raw to g (12-bit, +/- 2 g range) ---- */
static float raw_to_g(int16_t raw)
{
    /* 12-bit left-justified: shift right 4 to get signed 12-bit value */
    int16_t signed_val = (int16_t)(raw >> 4);
    return (float)signed_val / 4096.0f;  /* 4096 counts/g in +/- 2 g mode */
}

/* ---- Impact detection ---- */
static bool detect_impact(float xg, float yg, float zg, float freefall_g, float impact_g)
{
    float mag = sqrtf(xg * xg + yg * yg + zg * zg);
    return (mag < freefall_g) && (mag > impact_g);
}

/* ---- Buzzer control ---- */
static void activate_buzzer(int gpio, int duration_ms)
{
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Warning: failed to set buzzer HIGH\n");
        return;
    }
    gpioDelay(duration_ms * 1000);  /* pigpio microseconds */
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Warning: failed to set buzzer LOW\n");
    }
}

/* ---- Parse command-line arguments ---- */
static void parse_arguments(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "b:g:f:i:h")) != -1) {
        switch (opt) {
            case 'b': g_i2c_bus = atoi(optarg); break;
            case 'g': g_freefall_g = (float)atof(optarg); break;
            case 'i': g_impact_g = (float)atof(optarg); break;
            case 'h':
            default:
                fprintf(stderr,
                        "Usage: %s [-b i2c_bus] [-g freefall_g] [-i impact_g]\n"
                        "  -b i2c_bus   I2C bus number (default %d)\n"
                        "  -g freefall_g Free-fall threshold in g (default %.2f)\n"
                        "  -i impact_g  Impact threshold in g (default %.2f)\n",
                        argv[0], DEFAULT_I2C_BUS, DEFAULT_FREEFALL_G, DEFAULT_IMPACT_G);
                exit(EXIT_FAILURE);
        }
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_buzzer_gpio >= 0) {
        gpioWrite(g_buzzer_gpio, 0);
        gpioSetMode(g_buzzer_gpio, PI_INPUT);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    parse_arguments(argc, argv);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(g_buzzer_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", g_buzzer_gpio);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(g_buzzer_gpio, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(g_i2c_bus, LIS3DH_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %d\n",
                g_i2c_bus, LIS3DH_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lis3dh(g_i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LIS3DH impact detector running.  Free-fall < %.2f g,  Impact > %.2f g\n",
           g_freefall_g, g_impact_g);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_acceleration(g_i2c_handle, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Read error — continuing\n");
            gpioDelay(100000);  /* 100 ms back-off */
            continue;
        }

        float xg = raw_to_g(raw_x);
        float yg = raw_to_g(raw_y);
        float zg = raw_to_g(raw_z);

        if (detect_impact(xg, yg, zg, g_freefall_g, g_impact_g)) {
            printf("Impact detected! X=%.3f Y=%.3f Z=%.3f g\n", xg, yg, zg);
            activate_buzzer(g_buzzer_gpio, 1000);
        }

        gpioDelay(g_sample_us);  /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

