/*
 * LIS3DH High-Acceleration Monitor for Raspberry Pi 5
 *
 * Reads acceleration from one LIS3DH over I2C at 10 Hz and logs any
 * axis exceeding a user-specified threshold to /var/log/high_acceleration.log.
 * On the Pi 5 the LIS3DH is on the default I2C bus 1 (GPIO2/3).
 *
 * Build:  gcc -O2 -Wall -Wextra -o high_accel high_accel.c -li2c
 * Run:    sudo ./high_accel [-a 0x1D] [-t 2.0]
 *
 * Defaults:  I2C address = 0x1D  (SA0 tied to GND)
 *            Threshold   = 2.0 g
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3DH register map ---- */
#define LIS3DH_REG_WHO_AM_I   0x0F
#define LIS3DH_REG_CTRL1      0x20
#define LIS3DH_REG_CTRL4      0x23
#define LIS3DH_REG_OUT_X_L    0x28
#define LIS3DH_REG_OUT_X_H    0x29
#define LIS3DH_REG_OUT_Y_L    0x2A
#define LIS3DH_REG_OUT_Y_H    0x2B
#define LIS3DH_REG_OUT_Z_L    0x2C
#define LIS3DH_REG_OUT_Z_H    0x2D

#define LIS3DH_WHO_AM_I_VAL   0x33
#define LIS3DH_DEFAULT_ADDR   0x1D
#define I2C_BUS               "/dev/i2c-1"

/* ---- Configuration ---- */
#define DEFAULT_THRESHOLD_G   2.0f
#define DEFAULT_I2C_ADDR      LIS3DH_DEFAULT_ADDR
#define LOG_FILE              "/var/log/high_acceleration.log"
#define SAMPLE_PERIOD_MS      100
#define MAX_SENSITIVITY_G     2.0f   /* ±2 g range  */
#define MIN_SENSITIVITY_G     0.0f
#define MIN_THRESHOLD_G       0.001f /* guard against division by zero */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lis3dh(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LIS3DH_REG_WHO_AM_I, &who) < 0)
        return -1;
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL1: 0x57 -> 12-bit HR mode, 100 Hz ODR, normal power */
    if (i2c_write_reg8(fd, LIS3DH_REG_CTRL1, 0x57) < 0)
        return -1;

    /* CTRL4: 0x00 -> ±2 g full-scale, high-resolution disabled */
    if (i2c_write_reg8(fd, LIS3DH_REG_CTRL4, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration ---- */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, LIS3DH_REG_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3DH_REG_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3DH_REG_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3DH_REG_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3DH_REG_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3DH_REG_OUT_Z_H, &zh) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    /* 12-bit left-justified: shift right 4 to get signed 12-bit value */
    raw_x >>= 4;
    raw_y >>= 4;
    raw_z >>= 4;

    /* ±2 g range -> 4096 LSB/g (12-bit, 1 mg/LSB) */
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

/* ---- Threshold check ---- */
static int check_threshold(float x, float y, float z, float threshold)
{
    return (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold);
}

/* ---- Logging ---- */
static void log_event(float x, float y, float z, float threshold)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d  X:%.3f  Y:%.3f  Z:%.3f  > %.2f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, threshold);
    } else {
