#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_LED_PIN 22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_DURATION_US 2000000

#define LINE_DETECTED 0
#define NO_LINE_DETECTED 1

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

static SensorData sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void check_line_and_alert(void) {
    static int no_line_count = 0;
    int center = sensor_buffer[buffer_index].center;

    if (center == NO_LINE_DETECTED) {
        no_line_count++;
        if (no_line_count >= 5) {
            gpioWrite(ALERT_LED_PIN, 1);
            gpioDelay(ALERT_DURATION_US);
            gpioWrite(ALERT_LED_PIN, 0);
            no_line_count = 0;
        }
    } else {
        no_line_count = 0;
    }
}

static void move_forward(void) {
    printf("Moving forward...\n");
}

static void turn_left(void) {
    printf("Turning left...\n");
}

static void turn_right(void) {
    printf("Turning right...\n");
}

static void stop_robot(void) {
    printf("Stopping...\n");
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_DOWN);

    if (gpioWrite(ALERT_LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize alert LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, stopping robot\n");
            stop_robot();
            break;
        }

        add_to_buffer(left, center, right);
        check_line_and_alert();

        if (left == LINE_DETECTED) {
            turn_left();
        } else if (right == LINE_DETECTED) {
            turn_right();
        } else if (center == LINE_DETECTED) {
            move_forward();
        } else {
            stop_robot();
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(ALERT_LED_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

