#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int server_fd = -1;
static int client_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket");
        return -1;
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    return 0;
}

static void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        /* Strip trailing whitespace for case-insensitive comparison */
        buffer[strcspn(buffer, " \t\r\n")] = '\0';

        if (strcasecmp(buffer, "ON") == 0) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value");
                log_event("ERROR: Failed to set GPIO high");
            } else {
                log_event("Relay activated");
            }
        } else if (strcasecmp(buffer, "OFF") == 0) {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                log_event("ERROR: Failed to set GPIO low");
            } else {
                log_event("Relay deactivated");
            }
        } else {
            log_event("Invalid command received");
        }
    }
    if (bytes_received < 0) {
        perror("recv");
        log_event("ERROR: recv failed");
    }
    close(client_socket);
    client_fd = -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_event("ERROR: GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_event("GPIO initialized successfully");

    if (init_socket() < 0) {
        log_event("ERROR: Socket initialization failed");
        cleanup_gpio();
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_event("Socket initialized successfully");

    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            log_event("ERROR: accept failed");
            continue;
        }
        client_fd = client_socket;
        printf("Connection accepted from %s:%d\n",
               inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_socket);
    }

    printf("\nShutting down...\n");
    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    log_event("Server shutting down");
    cleanup_gpio();
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
    }
    return EXIT_SUCCESS;
}

