/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid-flow monitor with safety relay.
 *
 * Wiring:
 *   Sensor 1  SDA -> GPIO 2 (I2C bus 1 SDA), SCL -> GPIO 3, VDD 3V3, GND
 *   Sensor 2  SDA -> GPIO 2, SCL -> GPIO 3, VDD 3V3, GND
 *   Relay     IN  -> GPIO 18 (BCM), VCC 3V3, GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x60          /* SLF3S-1300F default I2C address */
#define SENSOR2_ADDR         0x61          /* second sensor (common on some boards) */
#define FLOW_THRESHOLD       5.0f          /* ml/min – relay energises below this */
#define RELAY_GPIO           18            /* BCM pin for safety relay */
#define POLL_DELAY_US        100000        /* 100 ms between readings */
#define LOG_FILE             "flow_log.txt"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;   /* handle for sensor 1  */
static int  g_i2c_h2 = -1;   /* handle for sensor 2  */
static int  g_relay_pin = -1;

/* ----------------------------- Prototypes -------------------------------- */
static uint8_t  crc8(const uint8_t *data, int len);
static int      read_flow_rate(int handle, float *flow_out);
static void     log_flow_data(float f1, float f2);
static void     cleanup(void);
static void     signal_handler(int sig);

/* ----------------------------- CRC-8 (Sensirion) -------------------------- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- Read flow --------------------------------- */
/*
 * Send the two-byte start-measurement command (0x3608), then read 3 bytes
 * (MSB, LSB, CRC).  Returns 0 on success and stores the flow rate in *flow_out.
 */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    uint8_t buf[3];

    /* Send start-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[WARN] i2cWriteDevice failed on handle %d\n", handle);
        return -1;
    }

    /* Small delay so the sensor can clock out the measurement */
    gpioDelay(2000);  /* 2 ms */

    /* Read 3 bytes: MSB, LSB, CRC */
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[WARN] i2cReadDevice returned %d (expected 3) on handle %d\n",
                n, handle);
        return -1;
    }

    /* CRC validation */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d (calc=0x%02X rx=0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Convert raw 16-bit big-endian value to ml/min */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_out = (float)raw / 100.0f;   /* 10-bit resolution, 100 counts/ml/min */
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen log");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char ts_str[40];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(ts_str);
    snprintf(ts_str + len, sizeof(ts_str) - len, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%.2f,%.2f\n", ts_str, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_relay_pin >= 0) {
        gpioWrite(g_relay_pin, 0);   /* de-energise relay */
        g_relay_pin = -1;
    }
    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C handles --- */
    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen sensor 1 (0x%02X) failed: %d\n",
                SENSOR1_ADDR, g_i2c_h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen sensor 2 (0x%02X) failed: %d\n",
                SENSOR2_ADDR, g_i2c_h2);
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure relay GPIO --- */
    g_relay_pin = RELAY_GPIO;
    if (gpioSetMode(g_relay_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", g_relay_pin);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(g_relay_pin, 0) != 0) {   /* start de-energised */
        fprintf(stderr, "[FATAL] gpioWrite(%d, 0) failed\n", g_relay_pin);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started.  Sensor1=0x%02X  Sensor2=0x%02X  Relay=GPIO%d  "
           "Threshold=%.1f ml/min  Poll=%d ms\n",
           SENSOR1_ADDR, SENSOR2_ADDR, RELAY_GPIO, FLOW_THRESHOLD, POLL_DELAY_US / 1000);

    /* --- main loop --- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        bool ok1 = (read_flow_rate(g_i2c_h1, &f1) == 0);
        bool ok2 = (read_flow_rate(g_i2c_h2, &f2) == 0);

        if (ok1 && ok2) {
