#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT_1_PIN 23
#define MOTOR_INPUT_2_PIN 24

#define POLL_INTERVAL_US 200000
#define MOTOR_RUN_TIME_US 5000000
#define DRY_COUNT_THRESHOLD 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%u, %u) failed", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud)
{
    if (gpioSetPullUpDown(pin, pud) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%u, %u) failed", pin, pud);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (safe_set_mode(RAIN_SENSOR_PIN, PI_INPUT) < 0) return -1;
    if (safe_set_mode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(MOTOR_INPUT_1_PIN, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(MOTOR_INPUT_2_PIN, PI_OUTPUT) < 0) return -1;

    if (safe_set_pull(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) return -1;

    if (safe_write(MOTOR_ENABLE_PIN, 0) < 0) return -1;
    if (safe_write(MOTOR_INPUT_1_PIN, 0) < 0) return -1;
    if (safe_write(MOTOR_INPUT_2_PIN, 0) < 0) return -1;

    syslog(LOG_INFO, "GPIO initialised: rain=BCM%u, motor=ENA%u IN1%u IN2%u",
           RAIN_SENSOR_PIN, MOTOR_ENABLE_PIN, MOTOR_INPUT_1_PIN, MOTOR_INPUT_2_PIN);
    return 0;
}

static int read_rain_sensor(void)
{
    int level = gpioRead(RAIN_SENSOR_PIN);
    if (level < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed", RAIN_SENSOR_PIN);
        return -1;
    }
    return level;
}

static int control_motor(int enable, int in1, int in2)
{
    if (safe_write(MOTOR_ENABLE_PIN, enable) < 0) return -1;
    if (safe_write(MOTOR_INPUT_1_PIN, in1) < 0) return -1;
    if (safe_write(MOTOR_INPUT_2_PIN, in2) < 0) return -1;
    return 0;
}

static void cleanup_motor(void)
{
    (void)control_motor(0, 0, 0);
}

static void cleanup_gpio(void)
{
    cleanup_motor();
    gpioTerminate();
}

static void log_event(const char *msg)
{
    syslog(LOG_INFO, "%s", msg);
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialisation failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    int dry_count = 0;
    int last_rain_state = 1; /* assume dry (high) at startup */

    log_event("Rain sensor monitoring started.");

    while (program_running) {
        int rain_state = read_rain_sensor();
        if (rain_state < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain_state != last_rain_state) {
            if (rain_state == 0) {
                /* Falling edge: sensor went wet (DO low) */
                dry_count = 0;
            } else {
                /* Rising edge: sensor went dry (DO high) */
                dry_count++;
                if (dry_count >= DRY_COUNT_THRESHOLD) {
                    dry_count = 0;
                    log_event("Rain detected (dry-to-wet transition). Closing window.");

                    if (control_motor(1, 1, 0) < 0) {
                        log_event("ERROR: Failed to start motor.");
                    } else {
                        log_event("Motor started. Closing window.");

                        /* Hold motor for 5 seconds using usleep (no busy-wait) */
                        unsigned int elapsed = 0;
                        while (program_running && elapsed < MOTOR_RUN_TIME_US) {
                            gpioDelay(100000); /* 100 ms slices */
                            elapsed += 100000;
                        }

                        if (control_motor(0, 0, 0) < 0) {
                            log_event("ERROR: Failed to stop motor.");
                        } else {
                            log_event("Motor stopped. Window closed.");
                        }
                    }
                    /* Reset threshold counter to avoid immediate retrigger */
                    dry_count = 0;
                }
            }
            last_rain_state = rain_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down gracefully.");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

