/*
 * door_lock.c — Raspberry Pi GPIO control of a hobby servo door lock.
 *
 * Wiring (BCM numbering):
 *   GPIO 18 (physical pin 12) — servo signal line
 *   GPIO 21 (physical pin 40) — lock button to GND (internal pull-up)
 *   GPIO 22 (physical pin 15) — unlock button to GND (internal pull-up)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000   /* 2 ms pulse -> locked position */
#define UNLOCK_PULSE_US 1000  /* 1 ms pulse  -> unlocked position */
#define STOP_PULSE_US   0     /* 0 us pulse   -> servo off     */

#define POLL_DELAY_US   10000  /* 10 ms poll interval */
#define DEBOUNCE_US     50000  /* 50 ms debounce after release */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
