#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_S 60
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(FILE *fp, const char *event_type, int duration_s) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_floodlight(FILE *fp) {
    printf("Motion detected! Activating floodlight for %d seconds...\n", FLOODLIGHT_DURATION_S);

    if (log_event(fp, "FLOODLIGHT_ACTIVATED", 0) != 0) {
        fprintf(stderr, "Failed to log activation event.\n");
        return -1;
    }

    if (g_running) {
        sleep(FLOODLIGHT_DURATION_S);
    } else {
        printf("Interrupted before floodlight duration elapsed.\n");
    }

    if (log_event(fp, "FLOODLIGHT_DEACTIVATED", FLOODLIGHT_DURATION_S) != 0) {
        fprintf(stderr, "Failed to log deactivation event.\n");
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *fp = NULL;
    int ret = 1;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write to floodlight pin %d\n", FLOODLIGHT_PIN);
            break;
        }

        if (gpioRead(PIR_PIN) == 1) {
            if (activate_floodlight(fp) != 0) {
                break;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off floodlight during shutdown\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    printf("Security system stopped.\n");
    return ret;
}

