#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPR121 I2C address (datasheet: 0x24 when ADDR pin low) */
#define MPR121_ADDR 0x24

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ELECTRODE_CONFIG0 0x5E
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

/* GPIO pin for relay (BCM numbering) */
#define RELAY_PIN 17

/* Debounce time in milliseconds */
#define DEBOUNCE_MS 200

/* Polling interval in microseconds (100 Hz) */
#define POLL_INTERVAL_US 10000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* MPR121 initialization                                               */
/* ------------------------------------------------------------------ */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Baseline filtering – rising edge */
    if (mpr121_write_reg(MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_RISE, 0x00) < 0) return -1;

    /* Baseline filtering – falling edge */
    if (mpr121_write_reg(MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_FALL, 0x00) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT = 0.5 µs, SFI = 4 samples */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    /* Auto-config: enable, 64 samples, 0.5 µs CDT */
    if (mpr121_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 0xB4) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static void relay_set(int state)
{
    if (gpioWrite(RELAY_PIN, state) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", RELAY_PIN, state);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    relay_set(0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPR121 address */
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                MPR121_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading TOUCHSTATUS_L */
    int touch_status = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (touch_status < 0) {
        fprintf(stderr, "MPR121 not responding on 0x%02X – check wiring\n", MPR121_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and set to OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    relay_set(0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay control started. Touch electrode 0 to toggle relay.\n");
    printf("Press Ctrl+C to exit.\n");

    bool relay_state = false;
    uint32_t last_touch_ms = 0;

    while (running) {
        int touch_status = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
        if (touch_status < 0) {
            fprintf(stderr, "I2C read error – continuing\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick() / 1000; /* milliseconds */

        /* Check electrode 0 (bit 0) */
        if (touch_status & 0x01) {
            if (now - last_touch_ms > DEBOUNCE_MS) {
                relay_state = !relay_state;
                relay_set(relay_state ? 1 : 0);
                printf("Relay %s\n", relay_state ? "ON" : "OFF");
                last_touch_ms = now;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

