#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdarg.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PIR_PIN 4
#define SERVO_PIN 17
#define PORT 5000
#define LOG_FILE "security.log"
#define MAX_BUFFER 1024
#define SERVO_FREQ 50
#define SERVO_RANGE 20000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    char timestamp[32];
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    syslog(priority, "%s: ", timestamp);
    vfprintf(stderr, format, args);
    syslog(priority, "%s\n", timestamp);
    if (log_file) {
        fprintf(log_file, "%s: ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
    va_end(args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int generate_pulse(int pulse_width) {
    if (pulse_width < 0) pulse_width = 0;
    if (pulse_width > SERVO_RANGE) pulse_width = SERVO_RANGE;
    return (pulse_width * 1000000) / SERVO_RANGE;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse_width = (int)((angle / 180.0) * SERVO_RANGE);
    int duty_cycle = generate_pulse(pulse_width);
    if (gpioServo(SERVO_PIN, duty_cycle) < 0) {
        log_message(LOG_ERR, "gpioServo failed for pin %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }
    log_message(LOG_INFO, "Servo set to angle: %d, pulse_width: %d, duty_cycle: %d", angle, pulse_width, duty_cycle);
    return 0;
}

static int read_pir_sensor(void) {
    int pir_value = gpioRead(PIR_PIN);
    if (pir_value < 0) {
        log_message(LOG_ERR, "gpioRead failed for pin %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }
    log_message(LOG_INFO, "PIR sensor value: %d", pir_value);
    return pir_value;
}

static int handle_client(int client_socket) {
    char buffer[MAX_BUFFER];
    ssize_t bytes_received = recv(client_socket, buffer, MAX_BUFFER - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        return -1;
    }
    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
        return 0;
    }
    buffer[bytes_received] = '\0';
    log_message(LOG_INFO, "Received: %s", buffer);

    char *command = strtok(buffer, " \r\n");
    if (!command) {
        log_message(LOG_WARNING, "Empty command received");
        send(client_socket, "Invalid command", 16, 0);
        return 0;
    }

    if (strcmp(command, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            send(client_socket, "Error reading PIR sensor", 24, 0);
        } else {
            char response[16];
            snprintf(response, sizeof(response), "PIR:%d", pir_value);
            send(client_socket, response, strlen(response), 0);
        }
    } else if (strncmp(command, "the library's API call ", 24) == 0) {
        int angle = atoi(command + 24);
        if (set_servo_angle(angle) == 0) {
            send(client_socket, "Servo angle set", 16, 0);
        } else {
            send(client_socket, "Error setting servo angle", 22, 0);
        }
    } else {
        send(client_socket, "Invalid command", 16, 0);
    }

    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        return -1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_message(LOG_ERR, "gpioSetMode failed for PIR pin %d: %s", PIR_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "gpioSetMode failed for servo pin %d: %s", SERVO_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (server_fd != -1) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting security server...");

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
    }

    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed, exiting");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "sigaction failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        log_message(LOG_ERR, "socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            if (running && errno != EINTR) {
                log_message(LOG_ERR, "accept failed: %s", strerror(errno));
            }
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        log_message(LOG_INFO, "Connection accepted from %s:%d", client_ip, ntohs(client_address.sin_port));

        handle_client(client_socket);

        close(client_socket);
    }

    log_message(LOG_INFO, "Shutting down security server...");
    cleanup();
    return 0;
}

