#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_H  0x10
#define BH1750_CONT_L  0x20
#define BH1750_ONE_T   0x20
#define BH1750_ONE_T_L 0x80
#define BH1750_MEAS_MS 120
#define LUX_THRESHOLD  150
#define GROW_LIGHT_PIN 23
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_MS     2000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GROW_LIGHT_PIN, 0);
    gpioTerminate();
}

static int init_bh1750(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(g_i2c_handle, BH1750_PWR_ON, 0x01) < 0) {
        fprintf(stderr, "Error powering on BH1750\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(g_i2c_handle, BH1750_RESET, 0x07) < 0) {
        fprintf(stderr, "Error resetting BH1750\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(g_i2c_handle, BH1750_CONT_H, 0x10) < 0) {
        fprintf(stderr, "Error setting BH1750 continuous high-res mode\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_lux(float *lux_out)
{
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C handle invalid\n");
        return -1;
    }

    if (i2cWriteByteData(g_i2c_handle, BH1750_ONE_T, BH1750_ONE_T_L) < 0) {
        fprintf(stderr, "Error triggering one-time measurement\n");
        return -1;
    }

    gpioDelay(BH1750_MEAS_MS * 1000);

