static int log_data(float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

static int control_grow_light(float lux)
{
    int target = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GROW_LIGHT_PIN, target) < 0) {
        fprintf(stderr, "Error writing to grow-light pin\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GROW_LIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting grow-light pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(GROW_LIGHT_PIN, 0);

    if (init_bh1750() != 0) {
        fprintf(stderr, "BH1750 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        float lux = 0.0f;

        if (read_lux(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            if (control_grow_light(lux) != 0) {
                fprintf(stderr, "Grow-light control failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        gpioDelay(SAMPLE_MS * 1000);
    }

    cleanup();
    return 0;
}

