/*
 * Raspberry Pi 3 Model B+ — Load-cell weight monitor with solenoid lock.
 *
 * Hardware:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lpigpio -lrt
 *   (run as root, or ensure pigpiod is not running)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <syslog.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define HX711_DOUT_PIN    23
#define HX711_SCK_PIN     24
#define SOLENOID_PIN      25

#define DEFAULT_THRESHOLD_G  1000.0f
#define DEFAULT_DURATION_MS   200
#define DEFAULT_SCALE_FACTOR  1.0f

#define TARE_SAMPLES        10
#define POLL_SAMPLES        5
#define POLL_INTERVAL_US    500000   /* 500 ms */
#define HX711_TIMEOUT_US    1000000  /* 1 s  */
#define HX711_MAX_RETRIES   3

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static double g_scale_factor = DEFAULT_SCALE_FACTOR;
static int   g_threshold_g   = DEFAULT_THRESHOLD_G;
static int   g_duration_ms   = DEFAULT_DURATION_MS;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ HX711 driver ----------------------------- */

/*
 * Read 24-bit two's-complement data from the HX711.
 * Returns 0 on success (value stored in *out), -1 on timeout / error.
 */
static int hx711_read(int32_t *out)
{
    if (out == NULL)
        return -1;

    /* Wait for DOUT to go LOW (data ready). */
    uint32_t waited = 0;
    while (gpioRead(HX711_DOUT_PIN) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711: DOUT stuck HIGH (timeout)");
            return -1;
        }
        gpioDelay(100);  /* 100 us */
        waited += 100;
    }

    /* Clock out 24 data bits MSB-first. */
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            syslog(LOG_ERR, "HX711: SCK high write failed");
            return -1;
        }
        gpioDelay(1);  /* >=0.2 us HX711 min */

        value <<= 1;
        if (gpioRead(HX711_DOUT_PIN) == 1)
            value |= 1;

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            syslog(LOG_ERR, "HX711: SCK low write failed");
            return -1;
        }
        gpioDelay(1);
    }

    /* 25th clock pulse selects Channel A / gain 128 for the next reading. */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        syslog(LOG_ERR, "HX711: 25th SCK high failed");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        syslog(LOG_ERR, "HX711: 25th SCK low failed");
        return -1;
    }
    gpioDelay(1);

    /* Sign-extend 24-bit two's complement to 32-bit. */
    if (value & 0x800000)
        value |= 0xFF000000;

    *out = value;
    return 0;
}

/* ------------------------------ Solenoid --------------------------------- */

static void solenoid_activate(int duration_ms)
{
    if (gpioWrite(SOLENOID_PIN, 1) < 0)
        syslog(LOG_ERR, "Solenoid: failed to set HIGH");
    else {
        syslog(LOG_INFO, "Solenoid activated for %d ms", duration_ms);
        gpioDelay(duration_ms * 1000);
        if (gpioWrite(SOLENOID_PIN, 0) < 0)
            syslog(LOG_ERR, "Solenoid: failed to set LOW");
        else
            syslog(LOG_INFO, "Solenoid deactivated");
    }
}

/* ------------------------------ Tare ------------------------------------- */

static int hx711_tare(double *tare_value)
{
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < TARE_SAMPLES; i++) {
        int32_t raw;
        if (hx711_read(&raw) == 0) {
            sum += (double)raw;
            valid++;
        }
        gpioDelay(10000);  /* 10 ms between samples */
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Tare: no valid HX711 readings");
        return -1;
    }

    *tare_value = sum / valid;
    syslog(LOG_INFO, "Tare complete: average raw = %.2f", *tare_value);
    return 0;
}

/* ------------------------------ Weight ----------------------------------- */

static float hx711_read_weight(double tare_value)
{
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < POLL_SAMPLES; i++) {
        int32_t raw;
        if (hx711_read(&raw) == 0) {
            sum += (double)raw;
            valid++;
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Weight read: no valid HX711 samples");
        return 0.0f;
    }

    double raw = sum / valid;
    return (float)((raw - tare_value) * g_scale_factor);
}

/* ------------------------------ Argument parsing ------------------------- */

static void parse_arguments(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:h")) != -1) {
        switch (opt) {
        case 't':
            g_threshold_g = atoi(optarg);
            if (g_threshold_g <= 0) {
                fprintf(stderr, "Threshold must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 's':
            g_scale_factor = atof(optarg);
            if (g_scale_factor <= 0.0) {
                fprintf(stderr, "Scale factor must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 'd':
            g_duration_ms = atoi(optarg);
            if (g_duration_ms <= 0) {
                fprintf(stderr, "Duration must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold_g] [-s scale_factor] [-d duration_ms]\n",
                    argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

/* ------------------------------ Main ------------------------------------- */

int main(int argc, char *argv[])
{
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    parse_arguments(argc, argv);

    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure GPIO directions. */
    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_SCK_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN,  PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Ensure solenoid is OFF at startup. */
    if (gpioWrite(SOLENOID_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to initialise solenoid to LOW");

    /* Tare the load cell. */
    double tare_value = 0.0;
    if (hx711_tare(&tare_value) != 0) {
        syslog(LOG_ERR, "Tare failed; exiting");
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started (threshold=%.1f g, scale=%.2f, duration=%d ms)",
           g_threshold_g, g_scale_factor, g_duration_ms);

    /* Main monitoring loop. */
    while (g_running) {
        float weight = hx711_read_weight(tare_value);

        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > g_threshold_g) {
            syslog(LOG_WARNING, "Threshold exceeded (%.2f g > %.1f g)",
                   weight, g_threshold_g);
            solenoid_activate(g_duration_ms);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown. */
    syslog(LOG_INFO, "Shutting down");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

