    if (gpioWrite(SOLENOID_PIN, 1) < 0)
        syslog(LOG_ERR, "Solenoid: failed to set HIGH");
    else {
        syslog(LOG_INFO, "Solenoid activated for %d ms", duration_ms);
        gpioDelay(duration_ms * 1000);
        if (gpioWrite(SOLENOID_PIN, 0) < 0)
            syslog(LOG_ERR, "Solenoid: failed to set LOW");
        else
            syslog(LOG_INFO, "Solenoid deactivated");
    }
}

/* ------------------------------ Tare ------------------------------------- */

static int hx711_tare(double *tare_value)
{
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < TARE_SAMPLES; i++) {
        int32_t raw;
        if (hx711_read(&raw) == 0) {
            sum += (double)raw;
            valid++;
        }
        gpioDelay(10000);  /* 10 ms between samples */
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Tare: no valid HX711 readings");
        return -1;
    }

    *tare_value = sum / valid;
    syslog(LOG_INFO, "Tare complete: average raw = %.2f", *tare_value);
    return 0;
}

/* ------------------------------ Weight ----------------------------------- */

static float hx711_read_weight(double tare_value)
{
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < POLL_SAMPLES; i++) {
        int32_t raw;
        if (hx711_read(&raw) == 0) {
            sum += (double)raw;
            valid++;
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "Weight read: no valid HX711 samples");
        return 0.0f;
    }

    double raw = sum / valid;
    return (float)((raw - tare_value) * g_scale_factor);
}

/* ------------------------------ Argument parsing ------------------------- */

static void parse_arguments(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:h")) != -1) {
        switch (opt) {
        case 't':
            g_threshold_g = atoi(optarg);
            if (g_threshold_g <= 0) {
                fprintf(stderr, "Threshold must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 's':
            g_scale_factor = atof(optarg);
            if (g_scale_factor <= 0.0) {
                fprintf(stderr, "Scale factor must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 'd':
            g_duration_ms = atoi(optarg);
            if (g_duration_ms <= 0) {
                fprintf(stderr, "Duration must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold_g] [-s scale_factor] [-d duration_ms]\n",
                    argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

/* ------------------------------ Main ------------------------------------- */

int main(int argc, char *argv[])
{
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    parse_arguments(argc, argv);

    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure GPIO directions. */
    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_SCK_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN,  PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Ensure solenoid is OFF at startup. */
    if (gpioWrite(SOLENOID_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to initialise solenoid to LOW");

    /* Tare the load cell. */
    double tare_value = 0.0;
    if (hx711_tare(&tare_value) != 0) {
        syslog(LOG_ERR, "Tare failed; exiting");
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started (threshold=%.1f g, scale=%.2f, duration=%d ms)",
           g_threshold_g, g_scale_factor, g_duration_ms);

    /* Main monitoring loop. */
    while (g_running) {
        float weight = hx711_read_weight(tare_value);

        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > g_threshold_g) {
            syslog(LOG_WARNING, "Threshold exceeded (%.2f g > %.1f g)",
                   weight, g_threshold_g);
            solenoid_activate(g_duration_ms);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown. */
    syslog(LOG_INFO, "Shutting down");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

