/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lpigpio -lmosquitto
 * Run:    sudo ./relay_controller
 *
 * Hardware:
 *   - Relay module (active-high or active-low, suitable for 3.3 V logic)
 *   - IN  -> GPIO17 (BCM 17, physical pin 11)
 *   - VCC -> 3.3 V (physical pin 1)
 *   - GND -> GND  (physical pin 9)
 *
 * MQTT:
 *   Broker:  localhost   Port: 1883   Topic: home/lights/control   QoS: 0
 *   Payload: "ON" or "OFF" (case-sensitive) — anything else is ignored.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS   "localhost"
#define MQTT_BROKER_PORT      1883
#define MQTT_CLIENT_ID        "relay_controller_1"
#define MQTT_TOPIC            "home/lights/control"
#define MQTT_KEEPALIVE        60
#define GPIO_RELAY            17
#define RECONNECT_DELAY_SEC   5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO %d", GPIO_RELAY);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {   /* relay OFF at startup */
        syslog(LOG_ERR, "gpioWrite failed for GPIO %d", GPIO_RELAY);
        gpioTerminate();
        return -1;
    }
    syslog(LOG_INFO, "GPIO %d configured as output, relay OFF", GPIO_RELAY);
    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure relay is de-energized before terminating pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_RELAY, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_connect(void)
{
    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        return -1;
    }
    syslog(LOG_INFO, "Connected to MQTT broker at %s:%d",
           MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
    return 0;
}

static void mqtt_disconnect(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    syslog(LOG_INFO, "MQTT client destroyed");
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata,
                                  const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message on topic %s", message ? message->topic : "NULL");
        return;
    }

    /* Treat payload as NUL-terminated string */
    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_RELAY, 1) == 0) {
            syslog(LOG_INFO, "Relay energized (GPIO %d HIGH)", GPIO_RELAY);
        } else {
            syslog(LOG_ERR, "Failed to set GPIO %d HIGH", GPIO_RELAY);
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_RELAY, 0) == 0) {
            syslog(LOG_INFO, "Relay de-energized (GPIO %d LOW)", GPIO_RELAY);
        } else {
            syslog(LOG_ERR, "Failed to set GPIO %d LOW", GPIO_RELAY);
        }
    } else {
        syslog(LOG_ERR, "Invalid MQTT payload: \"%s\"", payload);
    }
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected, subscribing to %s", MQTT_TOPIC);
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_subscribe failed: %s",
                   mosquitto_strerror(rc));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect callback error: %s",
               mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == 0) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_ERR, "MQTT disconnected with error: %s",
               mosquitto_strerror(rc));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller");

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    /* GPIO initialization */
    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    /* MQTT initialization */
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(g_mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(g_mosq, mqtt_message_callback);

    if (mqtt_connect() != 0) {
        gpio_cleanup();
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        closelog();
        return EXIT_FAILURE;
    }

    /* Main MQTT loop */
    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            /* Wait before retrying to avoid tight error loop */
            sleep(RECONNECT_DELAY_SEC);
            if (g_running) {
                if (mqtt_connect() != 0) {
                    syslog(LOG_ERR, "Reconnect failed, retrying in %d s",
                           RECONNECT_DELAY_SEC);
                }
            }
        }
    }

    /* Graceful shutdown */
    syslog(LOG_INFO, "Shutting down relay controller");
    gpio_cleanup();
    mqtt_disconnect();
    mosquitto_lib_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

