 * Each servo is held at its target pulse width for 3 s, then released.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_move servo_move.c -lpigpio -lrt
 * Run:    sudo ./servo_move
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define PWM_FREQ_HZ   50          /* 50 Hz -> 20 ms period */
#define PWM_RANGE     1000        /* 0..1000 -> 0..1000 us */
#define HOLD_SEC      3           /* hold each position for 3 s */

/* Target pulse widths in microseconds (0-1000 map to 0-100% duty) */
#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

