/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - DRV8833 H-bridge on the GPIO bus:
 *       GPIO 17 (BCM) -> DRV8833 IN1 (Motor A PWM)
 *       GPIO 18 (BCM) -> DRV8833 IN2 (Motor A direction)
 *       GPIO 22 (BCM) -> DRV8833 IN3 (Motor B PWM)
 *       GPIO 23 (BCM) -> DRV8833 IN4 (Motor B direction)
 *   - Quadrature encoder A: phase A on GPIO 4, phase B on GPIO 5
 *   - Quadrature encoder B: phase A on GPIO 6, phase B on GPIO 12
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_control motor_control.c -lpigpio -lrt -lpthread
 * Run:
 *   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN    17
#define MOTOR_A_DIR_PIN    18
#define MOTOR_B_PWM_PIN    22
#define MOTOR_B_DIR_PIN    23

#define ENCODER_A_PHASE_A  4
#define ENCODER_A_PHASE_B  5
#define ENCODER_B_PHASE_A  6
#define ENCODER_B_PHASE_B  12

/* ---- Control parameters ---- */
#define TARGET_RPM         50.0
#define PWM_FREQUENCY      10000   /* 10 kHz */
#define PWM_RANGE          255
#define TICKS_PER_REV      64      /* encoder ticks per revolution */
#define CONTROL_PERIOD_US  100000  /* 100 ms */
#define STALL_TIMEOUT_S    2.0

/* ---- PI controller gains ---- */
#define KP                 0.5
#define KI                 0.1

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static volatile int g_encoder_a_ticks = 0;
static volatile int g_encoder_b_ticks = 0;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_direction(int dir_pin, bool forward);
static void set_motor_pwm(int pwm_pin, int duty);
static int  calculate_pwm_duty(float error, float integral, float dt);
static void check_stall(int a_ticks, int b_ticks);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor control pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder input pins with pull-down resistors */
    if (gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ENCODER_A_PHASE_A, PI_PUD_DOWN);
    gpioSetPullUpDown(ENCODER_A_PHASE_B, PI_PUD_DOWN);
    gpioSetPullUpDown(ENCODER_B_PHASE_A, PI_PUD_DOWN);
    gpioSetPullUpDown(ENCODER_B_PHASE_B, PI_PUD_DOWN);

    /* Initialize PWM on the two PWM pins */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);

    /* Initialize direction pins to a safe (braked) state */
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);

    /* Register ISR callbacks for both encoders (rising edge only) */
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0,
                         encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0,
                         encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A phase B.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0,
                         encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0,
                         encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B phase B.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to stop.\n");

    /* PI controller state */
    float integral_a = 0.0f;
    float integral_b = 0.0f;
    uint32_t last_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();
        uint32_t elapsed_us = now - last_tick;  /* wraps correctly */
        last_tick = now;

        if (elapsed_us < (uint32_t)CONTROL_PERIOD_US) {
            gpioDelay(CONTROL_PERIOD_US - elapsed_us);
        }

        /* Atomically read and reset encoder tick counts */
        int a_ticks = 0, b_ticks = 0;
        __sync_lock_test_and_set(&g_encoder_a_ticks, a_ticks);
        __sync_lock_test_and_set(&g_encoder_b_ticks, b_ticks);

        float dt = (float)elapsed_us / 1.0e6f;

        /* Calculate error (target - measured) */
        float error_a = TARGET_RPM - (float)b_ticks / (float)TICKS_PER_REV * 60.0f;
        float error_b = TARGET_RPM - (float)a_ticks / (float)TICKS_PER_REV * 60.0f;

        /* PI controller */
        integral_a += error_a * dt;
        integral_b += error_b * dt;

        int duty_a = calculate_pwm_duty(error_a, integral_a, dt);
        int duty_b = calculate_pwm_duty(error_b, integral_b, dt);

        /* Clamp duty cycle to valid range */
        if (duty_a < 0)   duty_a = 0;
        if (duty_a > PWM_RANGE) duty_a = PWM_RANGE;
        if (duty_b < 0)   duty_b = 0;
        if (duty_b > PWM_RANGE) duty_b = PWM_RANGE;

        /* Drive motors: hold one input high, PWM the other for forward motion */
        set_motor_direction(MOTOR_A_DIR_PIN, true);
        set_motor_pwm(MOTOR_A_PWM_PIN, duty_a);
        set_motor_direction(MOTOR_B_DIR_PIN, true);
        set_motor_pwm(MOTOR_B_PWM_PIN, duty_b);

        /* Stall detection: no ticks for STALL_TIMEOUT_S seconds */
        check_stall(a_ticks, b_ticks);

        printf("Motor A: RPM=%.2f  PWM=%d | Motor B: RPM=%.2f  PWM=%d\n",
               (float)a_ticks / (float)TICKS_PER_REV * 60.0f, duty_a,
               (float)b_ticks / (float)TICKS_PER_REV * 60.0f, duty_b);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    __sync_fetch_and_add(&g_encoder_a_ticks, 1);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    __sync_fetch_and_add(&g_encoder_b_ticks, 1);
}

/* ------------------------------------------------------------------ */
static void set_motor_direction(int dir_pin, bool forward)
{
    gpioWrite(dir_pin, forward ? 1 : 0);
}

static void set_motor_pwm(int pwm_pin, int duty)
{
    gpioPWM(pwm_pin, duty);
}

/* ------------------------------------------------------------------ */
static int calculate_pwm_duty(float error, float integral, float dt)
{
    float output = KP * error + KI * integral;
    int duty = (int)(output + 0.5f);
    return duty;
}

static void check_stall(int a_ticks, int b_ticks)
{
    static uint32_t stall_start_a = 0, stall_start_b = 0;
    static bool     stall_active_a = false, stall_active_b = false;

    if (a_ticks == 0) {
        if (!stall_active_a) {
            stall_active_a = true;
            stall_start_a  = gpioTick();
            printf("Warning: Motor A stall detected (no ticks for %.0f s).\n",
                   (gpioTick() - stall_start_a) / 1.0e6f);
        }
    } else {
        stall_active_a = false;
    }

    if (b_ticks == 0) {
        if (!stall_active_b) {
            stall_active_b = true;
            stall_start_b  = gpioTick();
            printf("Warning: Motor B stall detected (no ticks for %.0f s).\n",
                   (gpioTick() - stall_start_b) / 1.0e6f);
        }
    } else {
        stall_active_b = false;
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motors */
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);

    /* Unregister ISRs */
    gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_A_PHASE_B, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_PHASE_B, RISING_EDGE, 0, NULL, NULL);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

