#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_SETTLE_MS 180
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static int read_lux(float *lux) {
    if (i2cWriteByte(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing mode command to BH1750\n");
        return -1;
    }

    gpioDelay(BH1750_SETTLE_MS * 1000);

    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from BH1750 (read %d bytes)\n", bytes_read);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to relay GPIO %d\n", RELAY_GPIO);
    }
}

static void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n",
            timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0 || init_gpio() != 0 || init_log() != 0) {
        cleanup();
        return 1;
    }

    int relay_state = 0;
    int first_reading = 1;

    while (running) {
        float lux = 0.0f;

        if (read_lux(&lux) == 0) {
            if (first_reading) {
                relay_state = (lux < LUX_THRESHOLD_DUSK) ? 1 : 0;
                control_relay(relay_state);
                first_reading = 0;
            } else {
                if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                    relay_state = 1;
                    control_relay(relay_state);
                } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                    relay_state = 0;
                    control_relay(relay_state);
                }
            }
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Sensor read failed; turning off relay for safety.\n");
            control_relay(0);
            log_data(-1.0f, 0);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

