#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN    27
#define FLOW_THRESHOLD  5.0
#define HYSTERESIS      0.5
#define SAMPLE_PERIOD   1.0
#define DEBOUNCE_US     1000000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static pthread_mutex_t g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile int g_pulse_count = 0;
static volatile uint32_t g_last_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    if (!g_log) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log);
    }
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 1) {
        uint32_t last = g_last_tick;
        if (tick > last) {
            g_pulse_count++;
            g_last_tick = tick;
        }
    }
}

static double calculate_lpm(void) {
    double elapsed = (double)(gpioTick() - g_last_tick) / 1000000.0;
    if (elapsed <= 0.0) return 0.0;
    int pulses = g_pulse_count;
    g_pulse_count = 0;
    return (pulses / elapsed) * 60.0;
}

static int control_solenoid(double lpm) {
    static int solenoid_state = 1;
    if (lpm > FLOW_THRESHOLD && solenoid_state == 1) {
        if (gpioWrite(SOLENOID_PIN, 0) == 0) {
            solenoid_state = 0;
            log_event("Solenoid closed (flow > threshold)");
        }
