static FILE *g_log = NULL;
static pthread_mutex_t g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile int g_pulse_count = 0;
static volatile uint32_t g_last_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    if (!g_log) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
