#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_OFFSET 0.0
#define CONFIG_FILE "config.ini"
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define MAX_BUFFER_SIZE 1024
#define HX711_TIMEOUT 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_RANGE 1000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static double offset = DEFAULT_OFFSET;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s: %s. Using defaults.\n", filename, strerror(errno));
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key && value) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "offset") == 0) {
                offset = atof(value);
            }
        }
    }
    fclose(fp);
    return 0;
}

static int read_hx711(int *raw_value) {
    int timeout = 0;
    while (gpioRead(DATA_PIN) == 1) {
        if (timeout++ > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 timeout waiting for DATA to go LOW.\n");
            return -1;
        }
        gpioDelay(1);
    }
    int value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(DATA_PIN)) {
            value++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);
    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    *raw_value = value;
    return 0;
}

static double get_weight(int raw_value) {
    return ((double)raw_value - offset) / calibration_factor;
}

static int dispense(double target_weight) {
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (target_weight / 100.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width to %d.\n", pulse_width);
        return -1;
    }
    gpioDelay(1000000);
    return 0;
}

static int read_actual_weight(double *actual_weight) {
    int raw_value;
    if (read_hx711(&raw_value) != 0) {
        return -1;
    }
    *actual_weight = get_weight(raw_value);
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open dispensing_log.json: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message ? error_message : "None");
    fclose(fp);
    return 0;
}

static int send_response(int client_socket, double actual_weight) {
    char buffer[MAX_BUFFER_SIZE];
    snprintf(buffer, sizeof(buffer), "Actual weight: %.2f grams", actual_weight);
    if (send(client_socket, buffer, strlen(buffer), 0) < 0) {
        fprintf(stderr, "Error: Failed to send response: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int setup_server(int port) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Could not create socket: %s\n", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error: Could not set SO_REUSEADDR: %s\n", strerror(errno));
        close(server_fd);
        return -1;
    }
    struct sockaddr_in address = {0};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: Could not bind socket: %s\n", strerror(errno));
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Could not listen on socket: %s\n", strerror(errno));
        close(server_fd);
        return -1;
    }
    return server_fd;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Warning: Using default calibration factor and offset.\n");
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioWrite(SCK_PIN, 0);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, 0);

    server_fd = setup_server(SERVER_PORT);
    if (server_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Server listening on %s:%d...\n", SERVER_IP, SERVER_PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t addrlen = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Error: Accept failed: %s\n", strerror(errno));
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_address.sin_port));

        char buffer[MAX_BUFFER_SIZE];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Error: Receive failed: %s\n", strerror(errno));
            close(client_socket);
            continue;
        }
        if (bytes_received == 0) {
            printf("Client disconnected.\n");
            close(client_socket);
            continue;
        }
        buffer[bytes_received] = '\0';
        double target_weight;
        if (sscanf(buffer, "%lf", &target_weight) != 1) {
            fprintf(stderr, "Error: Invalid data received: %s\n", buffer);
            const char *err_msg = "Invalid data format";
            send(client_socket, err_msg, strlen(err_msg), 0);
            close(client_socket);
            continue;
        }

        double actual_weight;
        if (dispense(target_weight) != 0) {
            fprintf(stderr, "Error: Dispensing failed.\n");
            const char *err_msg = "Dispensing failed";
            send(client_socket, err_msg, strlen(err_msg), 0);
            close(client_socket);
            continue;
        }

        if (read_actual_weight(&actual_weight) != 0) {
            fprintf(stderr, "Error: Failed to read actual weight.\n");
            const char *err_msg = "Failed to read actual weight";
            send(client_socket, err_msg, strlen(err_msg), 0);
            close(client_socket);
            continue;
        }

        if (send_response(client_socket, actual_weight) != 0) {
            close(client_socket);
            continue;
        }

        if (log_dispensing_event(target_weight, actual_weight, NULL) != 0) {
            fprintf(stderr, "Warning: Failed to log dispensing event.\n");
        }

        close(client_socket);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (server_fd >= 0) {
        close(server_fd);
    }
    return 0;
}

