        socklen_t addrlen = sizeof(client_address);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            fprintf(stderr, "Error: Accept failed: %s\n", strerror(errno));
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_address.sin_port));

        char buffer[MAX_BUFFER_SIZE];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Error: Receive failed: %s\n", strerror(errno));
            close(client_socket);
            continue;
        }
        if (bytes_received == 0) {
            printf("Client disconnected.\n");
            close(client_socket);
            continue;
        }
        buffer[bytes_received] = '\0';
        double target_weight;
        if (sscanf(buffer, "%lf", &target_weight) != 1) {
            fprintf(stderr, "Error: Invalid data received: %s\n", buffer);
            const char *err_msg = "Invalid data format";
            send(client_socket, err_msg, strlen(err_msg), 0);
            close(client_socket);
            continue;
        }

        double actual_weight;
        if (dispense(target_weight) != 0) {
            fprintf(stderr, "Error: Dispensing failed.\n");
            const char *err_msg = "Dispensing failed";
            send(client_socket, err_msg, strlen(err_msg), 0);
            close(client_socket);
            continue;
        }

        if (read_actual_weight(&actual_weight) != 0) {
            fprintf(stderr, "Error: Failed to read actual weight.\n");
            const char *err_msg = "Failed to read actual weight";
            send(client_socket, err_msg, strlen(err_msg), 0);
            close(client_socket);
            continue;
        }

        if (send_response(client_socket, actual_weight) != 0) {
            close(client_socket);
            continue;
        }

        if (log_dispensing_event(target_weight, actual_weight, NULL) != 0) {
            fprintf(stderr, "Warning: Failed to log dispensing event.\n");
        }

        close(client_socket);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (server_fd >= 0) {
        close(server_fd);
    }
    return 0;
}

