#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed: %s\n",
                RELAY_PIN, state, strerror(errno));
        return -1;
    }
    relay_state = state;
    log_relay_state(state);
    return 0;
}

static int toggle_relay(void) {
    int current = relay_state;
    if (current == 0) {
        if (set_relay(1) != 0) return -1;
    } else {
        if (set_relay(0) != 0) return -1;
    }
    return 0;
}

static int parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            char *endptr = NULL;
            long val = strtol(argv[i + 1], &endptr, 10);
            if (*endptr != '\0' || val <= 0 || val > 60000) {
                fprintf(stderr, "Error: invalid debounce value '%s'\n", argv[i + 1]);
                return -1;
            }
            debounce_ms = (int)val;
            printf("Debounce set to %d ms\n", debounce_ms);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (parse_arguments(argc, argv) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed: %s\n",
                TOUCH_SENSOR_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                RELAY_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed: %s\n",
                RELAY_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Monitoring TTP223 touch sensor on GPIO %d. Relay on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    fflush(stdout);

    int last_touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                TOUCH_SENSOR_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                    TOUCH_SENSOR_PIN, strerror(errno));
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            if (toggle_relay() != 0) {
                break;
            }
            gpioDelay(debounce_ms * 1000);
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    if (set_relay(0) != 0) {
        fprintf(stderr, "Error: failed to turn relay OFF during shutdown\n");
    }

    gpioTerminate();
    printf("\nClean exit.\n");
    return EXIT_SUCCESS;
}

