/*
 * servo_angle.c — Raspberry Pi 4/5 servo angle control via keyboard.
 *
 * Wiring:
 *   GPIO18 (BCM 18, physical pin 12) — servo signal line
 *   5 V (pin 2 or 4) — servo power (external 5 V recommended)
 *   GND (pin 6)     — servo GND and common ground
 *
 * Servo: SG90, pulse range 500–2500 µs, 50 Hz.
 * Angle 0° → 500 µs, 180° → 2500 µs.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_angle servo_angle.c -lpigpio -lrt
 * Run:    sudo ./servo_angle
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 */
#define SERVO_MIN_US   500         /* SG90 minimum pulse width  */
#define SERVO_MAX_US   2500        /* SG90 maximum pulse width  */
#define SERVO_MIN_ANGLE 0          /* valid angle range         */
#define SERVO_MAX_ANGLE 180
#define ANGLE_STEP      10
#define PWM_FREQ_HZ     50          /* 20 ms period              */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Terminal raw mode                                                    */
/* ------------------------------------------------------------------ */
static int set_terminal_raw(struct termios *old_term)
{
    struct termios new_term;
    if (tcgetattr(STDIN_FILENO, &new_term) != 0) {
        perror("tcgetattr");
        return -1;
    }

    /* 0.5 s inter-character timeout, no echo, no canonical processing. */
    new_term.c_cc[VMIN]  = 0;
    new_term.c_cc[VTIME] = 5;
    new_term.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);
    new_term.c_iflag &= ~(IXON | IXOFF | IXANY);
    new_term.c_oflag &= ~OPOST;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_term) != 0) {
        perror("tcsetattr");
        return -1;
    }

    *old_term = new_term;
    return 0;
}

static void restore_terminal(struct termios *old_term)
{
    if (old_term != NULL) {
        tcsetattr(STDIN_FILENO, TCSANOW, old_term);
    }
}

/* ------------------------------------------------------------------ */
/* Servo angle helpers                                                 */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_us(int angle)
{
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    return SERVO_MIN_US +
           (int)((long)(angle - SERVO_MIN_ANGLE) *
                 (SERVO_MAX_US - SERVO_MIN_US) /
                 (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
}

static int set_servo_pulse(int pulse_us)
{
    int rc = gpioServo(SERVO_PIN, pulse_us);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed on pin %d: %s\n",
                SERVO_PIN, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int angle = 90;          /* start at 90° (1500 µs) */
    int pulse_us = angle_to_pulse_us(angle);
    int rc;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- terminal raw mode ---- */
    struct termios old_term;
    if (tcgetattr(STDIN_FILENO, &old_term) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_terminal_raw(&old_term) != 0) {
        restore_terminal(&old_term);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo angle control (GPIO%d, %d Hz).  Press '+' or '-' "
           "to adjust, 'q' to quit.\n", SERVO_PIN, PWM_FREQ_HZ);
    printf("Current angle: %d°  (pulse %d µs)\n", angle, pulse_us);
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        int c = getchar();

        if (c == EOF) {
            /* stdin closed — graceful exit. */
            break;
        }

        if (c == '+') {
            angle += ANGLE_STEP;
            if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
            pulse_us = angle_to_pulse_us(angle);
            if (set_servo_pulse(pulse_us) != 0) {
                restore_terminal(&old_term);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Angle: %d°  (pulse %d µs)\n", angle, pulse_us);
            fflush(stdout);
        } else if (c == '-') {
            angle -= ANGLE_STEP;
            if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
            pulse_us = angle_to_pulse_us(angle);
            if (set_servo_pulse(pulse_us) != 0) {
                restore_terminal(&old_term);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Angle: %d°  (pulse %d µs)\n", angle, pulse_us);
            fflush(stdout);
        } else if (c == 'q' || c == 'Q') {
            break;
        }
        /* Any other key: ignore. */

        /* Small sleep to avoid busy-waiting. */
        usleep(10000);  /* 10 ms */
    }

    /* ---- cleanup ---- */
    rc = gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
    if (rc < 0) {
        fprintf(stderr, "gpioServo(stop) failed: %s\n",
                pigpio_error(rc));
    }

    restore_terminal(&old_term);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

