#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000
#define HOLD_THRESHOLD_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int hold_counter = 0;
    int hold_active = 0;
    time_t hold_start = 0;

    while (running) {
        int touch_value = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_value == 1) {
            if (!hold_active) {
                hold_counter = 0;
                hold_active = 1;
                hold_start = time(NULL);
            } else {
                hold_counter++;
            }

            if (hold_counter > (HOLD_THRESHOLD_S * 10)) {
                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to write relay OFF\n");
                    break;
                }
                printf("Sensor held HIGH for > %d s - relay forced OFF\n", HOLD_THRESHOLD_S);
                hold_active = 0;
            }
        } else {
            if (hold_active) {
                hold_counter = 0;
                hold_active = 0;
            }
            if (relay_state == 1) {
                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to write relay OFF\n");
                    break;
                }
                relay_state = 0;
                printf("Relay turned OFF\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

