#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define PWM_FREQ           1000   /* Hz */
#define SAMPLE_PERIOD_US   100000 /* 100 ms */
#define LOG_FILE           "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback — called on every rising edge of the flow sensor pin  */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                           */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin %d as output.\n",
                VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set enable pin %d as output.\n",
                VALVE_ENABLE_PIN);
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flow sensor pin %d as input.\n",
                FLOW_SENSOR_PIN);
        return -1;
    }

    /* Start with valve closed (PWM 0) and enable line low */
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM on pin %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write enable pin %d.\n",
                VALVE_ENABLE_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure hardware PWM on the valve PWM pin                         */
/* ------------------------------------------------------------------ */
static int configure_pwm(void)
{
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on pin %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the CSV log file and write a header if it is a new file        */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    /* If the file is empty, write a header */
    long pos = ftell(g_log_fp);
    if (pos == 0) {
        fprintf(g_log_fp, "timestamp_ms,flow_rate_lpm,valve_position_pct\n");
        fflush(g_log_fp);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse the target flow rate from the command line                    */
/* ------------------------------------------------------------------ */
static int parse_target_flow_rate(int argc, char *argv[], float *target_lpm)
{
    if (argc < 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_LPM>\n", argv[0]);
        fprintf(stderr, "  Example: %s -t 10.5\n", argv[0]);
        return -1;
    }

    char *t = argv[1];
    if (strcmp(t, "-t") != 0) {
        fprintf(stderr, "Error: missing or invalid target flow rate argument.\n");
        return -1;
    }

    if (argc < 3) {
        fprintf(stderr, "Error: target flow rate value is required.\n");
        return -1;
    }

    char *endptr = NULL;
    float val = strtof(argv[2], &endptr);
    if (endptr == argv[2] || *endptr != '\0') {
        fprintf(stderr, "Error: invalid target flow rate value (must be a number).\n");
        return -1;
    }

    *target_lpm = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute a proportional controller output in the range 0–255        */
/* ------------------------------------------------------------------ */
static int compute_valve_position(float flow_rate, float target_lpm)
{
    float error = target_lpm - flow_rate;
    float position = (Kp * error) + 127.5f;

    if (position < 0.0f) position = 0.0f;
    if (position > 255.0f) position = 255.0f;

    return (int)position;
}

/* ------------------------------------------------------------------ */
/* Set the valve PWM duty cycle and enable line                        */
/* ------------------------------------------------------------------ */
static int set_valve_position(int position)
{
    if (gpioPWM(VALVE_PWM_PIN, position) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle on pin %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to enable valve on pin %d.\n",
                VALVE_ENABLE_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(float flow_rate, int valve_position)
{
    if (g_log_fp == NULL) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Warning: clock_gettime failed: %s\n",
                strerror(errno));
        return;
    }

    long timestamp_ms = (long)(ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);

    if (fprintf(g_log_fp, "%ld,%.2f,%d\n", timestamp_ms, flow_rate,
                valve_position) < 0) {
        fprintf(stderr, "Warning: fprintf to log file failed: %s\n",
                strerror(errno));
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush of log file failed: %s\n",
                strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Graceful shutdown — safe to call from any cleanup path             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop valve flow first for safety */
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to stop PWM during cleanup.\n");
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 0) < 0) {
