    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR for flow sensor rising edges */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on pin %d.\n",
                FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n",
           target_flow_rate);
    printf("Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        /* Sample flow rate every 100 ms */
        gpioDelay(SAMPLE_PERIOD_US);

        int pulses = g_pulse_count;
        g_pulse_count = 0;

        /* Convert pulses to L/min over 100 ms window */
        float flow_rate = (float)pulses * (1000.0f / 100.0f) / 60.0f;

        /* Compute valve position */
        int valve_position = compute_valve_position(flow_rate, target_flow_rate);

        /* Apply valve command */
        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Error: failed to set valve position.\n");
            break;
