#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22
#define RFID_CHANNEL 0
#define RFID_SPEED 100000
#define DEBOUNCE_US 50000
#define UNLOCK_DURATION_US 5000000
#define LOG_FILE "/var/log/door_access.log"
#define MAX_RETRIES 4
#define TAG_LENGTH 10
#define MAX_TAG_LENGTH 32
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rfid_tag(char *tag, int tag_len) {
    char buf[32];
    int bytes_read = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        bytes_read = spiRead(spi_handle, buf, sizeof(buf));
        if (bytes_read > 0) {
            if (bytes_read >= TAG_LENGTH) {
                memcpy(tag, buf, TAG_LENGTH);
                return 0;
            }
            return -1;
        }
        if (bytes_read < 0) {
            return -1;
        }
        gpioDelay(1000);
    }
    return -1;
}

static int verify_tag(const char *tag) {
    if (strlen(tag) != TAG_LENGTH) return -1;
    for (int i = 0; i < TAG_LENGTH; i++) {
        if (tag[i] < '0' || tag[i] > '9') return -1;
    }
    return 0;
}

static void unlock_locks(void) {
    gpioWrite(LOCK_1_PIN, 0);
    gpioWrite(LOCK_2_PIN, 0);
    gpioDelay(UNLOCK_DURATION_US);
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
    if (log_file) {
        log_message("Cleanup: locks re-engaged, SPI closed, exiting.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LOCK_1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK_2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        log_message("Failed to set GPIO modes");
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        log_message("Failed to set pull-up on button pin");
        cleanup();
        return 1;
    }

    spi_handle = spiOpen(RFID_CHANNEL, RFID_SPEED, 0);
    if (spi_handle < 0) {
        log_message("Failed to open SPI interface");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Door access control system started.");

    int button_state = 1;
    int last_button_state = 1;
    uint32_t last_debounce_time = 0;

    while (running) {
        char rfid_tag[TAG_LENGTH + 1];
        rfid_tag[TAG_LENGTH] = '\0';

        int read_result = read_rfid_tag(rfid_tag, TAG_LENGTH);
        if (read_result == 0) {
            if (verify_tag(rfid_tag) == 0) {
                log_message("Valid RFID tag detected.");
                button_state = 1;
                last_button_state = 1;
                last_debounce_time = gpioTick();
                while (running && button_state == 1) {
                    gpioDelay(10000);
                    button_state = gpioRead(BUTTON_PIN);
                }
                if (button_state == 0) {
                    log_message("Button pressed, unlocking doors.");
                    unlock_locks();
                    log_message("Doors unlocked.");
                } else {
                    log_message("Button not pressed, doors not unlocked.");
                }
            } else {
                log_message("Invalid RFID tag.");
            }
        } else if (read_result == -1) {
            log_message("RFID read failure.");
        } else {
            log_message("No tag present (all zeros).");
        }

        if (button_state != last_button_state) {
            uint32_t now = gpioTick();
            if ((now - last_debounce_time) > DEBOUNCE_US) {
                last_debounce_time = now;
                if (button_state == 0) {
                    button_state = 1;
                }
            }
        }
        last_button_state = button_state;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

