#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define MPR121_ADDR 0x38
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int mpr121_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Stop mode (ECR = 0) before configuration */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x00) < 0) return -1;

    /* Filtering / rise/fall configuration */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1; /* FFI=6, CDC=16 */
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1; /* CDT=0.5us, SFI=4 */

    if (mpr121_write_reg(handle, MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_FALL, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + 2 * i, 0x0C) < 0) return -1; /* touch threshold */
        if (mpr121_write_reg(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; /* release threshold */
    }

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    int lo = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    int hi = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    } else {
        fprintf(fp, "(unknown time): %s\n", event);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
