    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPR121 initialized. Polling every %d ms. Press Ctrl-C to exit.\n",
           POLL_DELAY_US / 1000);

    bool relay_state = false;
    uint16_t prev_touch = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "I2C read error; retrying next cycle\n");
