static int mpr121_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Stop mode (ECR = 0) before configuration */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x00) < 0) return -1;

    /* Filtering / rise/fall configuration */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1; /* FFI=6, CDC=16 */
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1; /* CDT=0.5us, SFI=4 */

