    if (mpr121_write_reg(handle, MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_FALL, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + 2 * i, 0x0C) < 0) return -1; /* touch threshold */
        if (mpr121_write_reg(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; /* release threshold */
    }

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;

