#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define PAUSE_BETWEEN_VALVES_MS 5000
#define PAUSE_AFTER_VALVE2_MS 10000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fflush(fp);
    }
    printf("%s: %s\n", ts, msg);
}

static int set_valve(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        log_event(g_log_fp, "ERROR: Failed to set GPIO HIGH");
        return -1;
    }
    log_event(g_log_fp, "Valve activated");
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) != 0) {
        log_event(g_log_fp, "ERROR: Failed to set GPIO LOW");
        return -1;
    }
    log_event(g_log_fp, "Valve deactivated");
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event(g_log_fp, "Water distribution system started");

    while (g_running) {
        if (set_valve(VALVE1_GPIO, VALVE1_DURATION_MS) != 0) {
            log_event(g_log_fp, "ERROR: Valve 1 activation failed");
            break;
        }
        if (!g_running) break;
        gpioDelay(PAUSE_BETWEEN_VALVES_MS * 1000);
        if (!g_running) break;

        if (set_valve(VALVE2_GPIO, VALVE2_DURATION_MS) != 0) {
            log_event(g_log_fp, "ERROR: Valve 2 activation failed");
            break;
        }
        if (!g_running) break;
        gpioDelay(PAUSE_AFTER_VALVE2_MS * 1000);
    }

    log_event(g_log_fp, "Water distribution system stopped");
    cleanup();
    return EXIT_SUCCESS;
}

