#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPR121 I2C address (ADDR pin tied to GND) */
#define MPR121_ADDR 0x00

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELE0_TTH      0x41
#define MPR121_ELE0_RTH      0x42
#define MPR121_MHD_F         0x2B
#define MPR121_NHD_F         0x2C
#define MPR121_NCL_F         0x2D
#define MPR121_FDL_F         0x2E
#define MPR121_MHD_R         0x2F
#define MPR121_NHD_R         0x30
#define MPR121_NCL_R         0x31
#define MPR121_FDL_R         0x32
#define MPR121_E0R_T0        0x41
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E
#define MPR121_SOFTRESET     0x80

/* GPIO pin for relay control (BCM numbering) */
#define RELAY_PIN 17

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, value, rc);
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* MPR121 initialization                                               */
/* ------------------------------------------------------------------ */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Stop mode before configuration */
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0)
        return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_ELE0_TTH + 2 * i, 0x0F) < 0)
            return -1;
        if (mpr121_write_reg(MPR121_ELE0_RTH + 2 * i, 0x0A) < 0)
            return -1;
    }

    /* Filter / charge configuration */
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0xFF) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x02) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0)
        return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0)
        return -1;

    /* CDT = 0.5 µs, SFI = 4 samples, ESI = 4 ms */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0)
        return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0)
        return -1;

    gpioDelay(100000); /* 100 ms stabilization */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 12-bit touch status                                            */
/* ------------------------------------------------------------------ */
static int mpr121_read_touch_status(void)
{
    int lo = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (lo < 0)
        return -1;

    int hi = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (hi < 0)
        return -1;

    return (hi << 8) | lo;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put MPR121 into stop mode */
        (void)i2cWriteByteData(g_i2c_handle, MPR121_ECR, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPR121 address */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    bool relay_state = false;

    while (g_running) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
