#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN      17
#define RELAY_PIN    18
#define UNLOCK_MS    500
#define POLL_MS      50
#define RATE_LIMIT_S 2

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    if (!g_log) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fflush(g_log);
}

static void cleanup(void) {
    if (g_log) {
        log_event("Program terminated");
        fclose(g_log);
        g_log = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR pin %d as input.\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on PIR pin %d.\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay pin %d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log = fopen("door_events.log", "a");
    if (!g_log) {
        perror("Error opening log file");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring PIR on GPIO %d, relay on GPIO %d. Press Ctrl+C to exit.\n",
           PIR_PIN, RELAY_PIN);

    int last_state = gpioRead(PIR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: failed to read initial PIR state.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    time_t last_unlock = 0;

    while (g_running) {
        int cur = gpioRead(PIR_PIN);
        if (cur < 0) {
            fprintf(stderr, "Warning: gpioRead failed on pin %d.\n", PIR_PIN);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (cur == 1 && last_state == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
            } else if (difftime(now, last_unlock) >= RATE_LIMIT_S) {
                if (gpioWrite(RELAY_PIN, 1) == 0) {
                    log_event("Motion detected, unlocking door strike");
                    printf("Motion detected, unlocking door strike\n");
                    gpioDelay(UNLOCK_MS * 1000);
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "Warning: failed to turn off relay.\n");
                    }
                    last_unlock = now;
                } else {
                    fprintf(stderr, "Error: failed to activate relay.\n");
                }
            } else {
                log_event("Motion detected, rate-limited - ignored");
                printf("Motion detected, rate-limited - ignored\n");
            }
        }

        last_state = cur;
        gpioDelay(POLL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

