#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_1_PIN 17
#define MOTOR_2_PIN 27
#define MIN_PATTERNS 5
#define MAX_PATTERNS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int generate_pattern(int *pattern, int *durations) {
    int num_steps = (rand() % (MAX_PATTERNS - MIN_PATTERNS + 1)) + MIN_PATTERNS;
    if (num_steps < MIN_PATTERNS || num_steps > MAX_PATTERNS) return -1;

    for (int i = 0; i < num_steps; i++) {
        pattern[i] = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        durations[i] = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }
    return num_steps;
}

static int play_pattern(const int *pattern, const int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        if (gpioPWM(MOTOR_1_PIN, pattern[i]) < 0) {
            fprintf(stderr, "Error setting PWM for Motor 1\n");
            return -1;
        }
        if (gpioPWM(MOTOR_2_PIN, pattern[i]) < 0) {
            fprintf(stderr, "Error setting PWM for Motor 2\n");
            return -1;
        }
        gpioDelay(durations[i] * 1000);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR_2_PIN);
        gpioTerminate();
        return 1;
    }

    srand((unsigned int)time(NULL));
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        gpioTerminate();
        return 1;
    }

    int *pattern = malloc(MAX_PATTERNS * sizeof(int));
    int *durations = malloc(MAX_PATTERNS * sizeof(int));
    if (!pattern || !durations) {
        fprintf(stderr, "Memory allocation failed\n");
        free(pattern);
        free(durations);
        gpioTerminate();
        return 1;
    }

    while (!shutdown_flag) {
        int num_steps = generate_pattern(pattern, durations);
        if (num_steps < 0) {
            fprintf(stderr, "Error generating pattern\n");
            continue;
        }
        if (play_pattern(pattern, durations, num_steps) < 0) {
            fprintf(stderr, "Error playing pattern\n");
        }
    }

    gpioPWM(MOTOR_1_PIN, 0);
    gpioPWM(MOTOR_2_PIN, 0);
    free(pattern);
    free(durations);
    gpioTerminate();
    return 0;
}

