#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    long value = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 1) {
        if (++timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low.\n");
            return -1;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = value;
    return 0;
}

static double calculate_weight(long raw_value, double scale_factor, double offset) {
    return ((double)raw_value - offset) / scale_factor;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *offset) {
    long sum = 0;
    int valid = 0;

    printf("Starting calibration. Please ensure no weight is on the scale.\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        long raw_value;
        if (read_hx711(data_pin, clock_pin, &raw_value) == 0) {
            sum += raw_value;
            valid++;
        } else {
            fprintf(stderr, "Warning: HX711 read failed during calibration (attempt %d).\n", i + 1);
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "Error: No valid readings during calibration.\n");
        return -1;
    }

    *offset = (double)sum / valid;
    printf("Calibration complete. Offset: %.2f\n", *offset);
    return 0;
}

static int load_calibration_data(const char *filename, double *scale_factor, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale_factor, offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data format in %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %.2f, offset = %.2f\n", *scale_factor, *offset);
    return 0;
}

static int save_calibration_data(const char *filename, double scale_factor, double offset) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("Error opening calibration file for writing");
        return -1;
    }

    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved to %s\n", filename);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration_data(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        printf("Using default calibration values: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &offset) != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        long raw_value;
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "Error reading HX711. Skipping iteration.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = calculate_weight(raw_value, scale_factor, offset);

        if (log_weight(weight) != 0) {
            fprintf(stderr, "Error logging weight.\n");
        }

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight threshold exceeded! Engaging solenoid.\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

