#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define RAIN_THRESHOLD 3
#define MOTOR_PWM_FREQUENCY 1000
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150
#define MOTOR_RUN_TIME_MS 5000
#define SENSOR_CHECK_INTERVAL_S 60
#define POST_MOTOR_DELAY_S 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }
    }
    return (low_count >= RAIN_THRESHOLD) ? 0 : 1;
}

static int control_motor(int direction, int speed) {
    int in1, in2;
    if (direction == 1) {
        in1 = 1;
        in2 = 0;
    } else if (direction == -1) {
        in1 = 0;
        in2 = 1;
    } else {
        in1 = 0;
        in2 = 0;
        return 0;
    }

    if (gpioWrite(MOTOR_IN1_PIN, in1) < 0) {
        syslog(LOG_ERR, "Failed to write to IN1 pin");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, in2) < 0) {
        syslog(LOG_ERR, "Failed to write to IN2 pin");
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, speed) < 0) {
        syslog(LOG_ERR, "Failed to set PWM");
        return -1;
    }
    return 0;
}

static void stop_motor(void) {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set PWM pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, MOTOR_PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Window control system started");

    while (program_running) {
        int rain = read_rain_sensor();
        if (rain == 0) {
            log_event("Rain detected");
            if (control_motor(1, MOTOR_PWM_DUTY) == 0) {
                gpioDelay(MOTOR_RUN_TIME_MS * 1000);
                stop_motor();
                log_event("Motor stopped");
            } else {
                log_event("Motor control failed");
            }
            for (int i = 0; i < POST_MOTOR_DELAY_S && program_running; i++) {
                sleep(1);
            }
        } else if (rain == 1) {
            log_event("No rain detected");
        } else {
            log_event("Sensor read error");
        }

        for (int i = 0; i < SENSOR_CHECK_INTERVAL_S && program_running; i++) {
            sleep(1);
        }
    }

    stop_motor();
    gpioTerminate();
    log_event("Window control system stopped");
    closelog();
    return 0;
}

