#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define TIMEOUT_US 100000
#define SOLENOID_UNLOCK_TIME 5

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    int32_t data = 0;
    int timeout = 0;

    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_CLOCK_PIN, 0);

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);

    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data line low\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *out = data;
    return 0;
}

static double calculate_weight(int32_t raw) {
    return (double)raw / calibration_factor;
}

static int save_calibration(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%.6f\n", factor);
    fclose(fp);
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found. Please calibrate first.\n");
        return -1;
    }
    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int calibrate_hx711(void) {
    int32_t raw;
    double known_weight;

    printf("Place a known weight on the load cell and enter the weight in kg: ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input for known weight\n");
        return -1;
    }
    while (getchar() != '\n');

    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "Failed to read HX711 during calibration\n");
        return -1;
    }

    if (raw == 0) {
        fprintf(stderr, "Calibration failed: raw value is zero. Check wiring.\n");
        return -1;
    }

    calibration_factor = (double)raw / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);

    if (save_calibration(calibration_factor) != 0) {
        fprintf(stderr, "Failed to save calibration factor\n");
        return -1;
    }
    return 0;
}

static int log_security_event(double weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening security log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

static void unlock_solenoid(void) {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1);
    gpioDelay(SOLENOID_UNLOCK_TIME * 1000000);
    gpioWrite(SOLENOID_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (load_calibration() != 0) {
        if (calibrate_hx711() != 0) {
            gpioTerminate();
            return 1;
        }
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw;
        if (read_hx711(&raw) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        double weight = calculate_weight(raw);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded: %.2f kg\n", weight);
            if (log_security_event(weight) != 0) {
                fprintf(stderr, "Failed to log security event\n");
            }
            unlock_solenoid();
        }

        gpioDelay(100000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Weight monitoring stopped.\n");
    return 0;
}

