    (void)sig;
    running = 0;
}

/* Initialize pigpio and configure GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure buzzer is off at startup */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state on GPIO%d.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read PIR sensor state; returns 0 or 1, or -1 on error */
static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", PIR_PIN, value);
        return -1;
    }
    return value;
}

