static void activate_buzzer(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn on buzzer on GPIO%d.\n", BUZZER_PIN);
        return;
    }
    usleep(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off buzzer on GPIO%d.\n", BUZZER_PIN);
    }
}

