static void log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
            fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        } else {
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
