        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open motion_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl-C to exit.\n");

    /* Main loop */
    while (running) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            /* Sensor read error — keep running but report it */
            fprintf(stderr, "Warning: PIR sensor read failed, continuing...\n");
        } else if (pir_value == 1) {
            printf("Motion detected!\n");
            activate_buzzer();
            log_motion_event();
        }

        usleep(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

