#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define CONFIG_FILE      "watering.conf"
#define GPIO_CHIP_NAME   "gpiochip0"
#define VALVE_GPIO       18          /* BCM 18 */
#define MIN_DURATION     1
#define MAX_DURATION     3600
#define DEFAULT_DURATION 60

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — just set the flag so the main loop can exit cleanly */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read watering duration from CONFIG_FILE.
 * Returns >= 0 on success, -1 on error. */
/* ------------------------------------------------------------------ */
static int read_watering_duration(const char *filename, int *out_duration)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading configuration file: %s\n",
                    strerror(errno));
        } else {
            fprintf(stderr, "Configuration file is empty.\n");
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Parse duration=<seconds> */
    char *eq = strchr(line, '=');
    if (eq == NULL) {
        fprintf(stderr, "Configuration file must contain a 'duration' key.\n");
        return -1;
    }
    eq++;                       /* point at the value */
    char *endptr = NULL;
    errno = 0;
    long val = strtol(eq, &endptr, 10);
    if (errno != 0 || endptr == eq) {
        fprintf(stderr, "Invalid duration value in configuration file.\n");
        return -1;
    }

    int duration = (int)val;
    if (duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr,
                "Duration out of range (%d-%d seconds). Using default %d.\n",
                MIN_DURATION, MAX_DURATION, DEFAULT_DURATION);
        duration = DEFAULT_DURATION;
    }

    *out_duration = duration;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Interruptible sleep that returns early when g_running is cleared   */
/* ------------------------------------------------------------------ */
static void interruptible_sleep(int seconds)
{
    for (int remaining = seconds; remaining > 0 && g_running; remaining--) {
        time_sleep((double)remaining);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request BCM 18 as output --- */
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(VALVE_GPIO, PI_PUD_OFF);

    /* Ensure valve is off at startup */
    if (gpioWrite(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d to LOW: %s\n",
                VALVE_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Watering system started. GPIO %d (BCM) active-low valve control.\n",
           VALVE_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Read configuration --- */
    int duration = DEFAULT_DURATION;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default watering duration: %d seconds.\n",
                duration);
    } else {
        printf("Watering duration: %d seconds\n", duration);
    }

    /* --- Activate valve (active-low: high = energise) --- */
    if (gpioWrite(VALVE_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate valve (GPIO %d HIGH): %s\n",
                VALVE_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Valve ON\n");

    /* --- Wait for the configured duration, interruptible --- */
    interruptible_sleep(duration);

    /* --- Deactivate valve --- */
    if (gpioWrite(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate valve (GPIO %d LOW): %s\n",
                VALVE_GPIO, strerror(errno));
    }
    printf("Valve OFF\n");

    /* --- Release GPIO and terminate pigpio --- */
    gpioTerminate();
    printf("Watering system stopped.\n");

    return EXIT_SUCCESS;
}

