/*
 * Line-following robot for Raspberry Pi Zero W
 * Sensor : Keywish 3-Way Infrared Tracking Sensor (active-low digital)
 * Driver : L298N dual H-bridge (four PWM inputs)
 * Library: pigpio (modern, actively maintained, supports hardware PWM)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 (left)  -> GPIO4
 *   Sensor 2 (mid)   -> GPIO17
 *   Sensor 3 (right) -> GPIO27
 *   Motor A+          -> GPIO22 (PWM)
 *   Motor A-          -> GPIO23 (PWM)
 *   Motor B+          -> GPIO24 (PWM)
 *   Motor B-          -> GPIO25 (PWM)
 *
 * Build:  gcc -O2 -Wall -o line_follower line_follower.c -lpigpio -lrt
 * Run:    sudo ./line_follower
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define SENSOR_LEFT   4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT  27
#define MOTOR_A_PWM   22
#define MOTOR_A_IN1   23
#define MOTOR_A_IN2   24
#define MOTOR_B_PWM   25

/* ---- Control parameters ---- */
#define BASE_SPEED     150          /* 0-255 range */
#define PWM_FREQ_HZ    1000         /* 1 kHz hardware PWM */
#define SAMPLE_US      10000        /* 10 ms between samples */
#define LOG_FILE       "trace_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets a flag and stops motors */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers — pigpio PWM is 0-255 range, so speeds are integers   */
/* ------------------------------------------------------------------ */
static void motor_a_stop(void)
{
    gpioPWM(MOTOR_A_PWM, 0);
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
}

static void motor_b_stop(void)
{
    gpioPWM(MOTOR_B_PWM, 0);
    gpioWrite(MOTOR_B_IN1, 0);
    gpioWrite(MOTOR_B_IN2, 0);
}

/* ------------------------------------------------------------------ */
/* Control law — returns motor speeds in 0-255 range                    */
/* ------------------------------------------------------------------ */
static void control_law(int s1, int s2, int s3, int *left_speed, int *right_speed)
{
    if (s1 == 0 && s2 == 0 && s3 == 0) {
        *left_speed = 0;
        *right_speed = 0;
    } else if (s1 == 0 && s2 == 0) {
        *left_speed = BASE_SPEED / 2;
        *right_speed = BASE_SPEED / 2;
    } else if (s2 == 0) {
        *left_speed = BASE_SPEED;
        *right_speed = BASE_SPEED;
    } else if (s1 == 0) {
        *left_speed = BASE_SPEED;
        *right_speed = 0;
    } else if (s3 == 0) {
        *left_speed = 0;
        *right_speed = BASE_SPEED;
    } else {
        *left_speed = 0;
        *right_speed = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Logging — ISO 8601 timestamp, sensor states, motor speeds           */
/* ------------------------------------------------------------------ */
static void log_data(int s1, int s2, int s3, int left_speed, int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log) {
        fprintf(g_log, "%s,s1=%d,s2=%d,s3=%d,left=%d,right=%d\n",
                ts, s1, s2, s3, left_speed, right_speed);
        fflush(g_log);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all pigpio resources and close log file           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_a_stop();
    motor_b_stop();

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int left_speed, right_speed;
    int s1, s2, s3;

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor inputs (active-low: 0 = line detected) ---- */
    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_MIDDLE, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set sensor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor PWM outputs ---- */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency ---- */
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Ensure motors are stopped at start ---- */
    motor_a_stop();
    motor_b_stop();

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp,s1,s2,s3,left_speed,right_speed\n");
    fflush(g_log);

    printf("Line follower running. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        s1 = gpioRead(SENSOR_LEFT);
        s2 = gpioRead(SENSOR_MIDDLE);
        s3 = gpioRead(SENSOR_RIGHT);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Warning: sensor read error (s1=%d s2=%d s3=%d)\n",
                    s1, s2, s3);
            gpioDelay(SAMPLE_US);
            continue;
        }

        control_law(s1, s2, s3, &left_speed, &right_speed);

        /* Drive motors */
        if (left_speed > 0) {
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_A_IN2, 0);
            gpioPWM(MOTOR_A_PWM, left_speed);
        } else if (left_speed < 0) {
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 1);
            gpioPWM(MOTOR_A_PWM, -left_speed);
        } else {
            motor_a_stop();
        }

        if (right_speed > 0) {
            gpioWrite(MOTOR_B_IN1, 1);
            gpioWrite(MOTOR_B_IN2, 0);
            gpioPWM(MOTOR_B_PWM, right_speed);
        } else if (right_speed < 0) {
            gpioWrite(MOTOR_B_IN1, 0);
            gpioWrite(MOTOR_B_IN2, 1);
            gpioPWM(MOTOR_B_PWM, -right_speed);
        } else {
            motor_b_stop();
        }

        log_data(s1, s2, s3, left_speed, right_speed);

        gpioDelay(SAMPLE_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

