code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_H  0x10
#define BH1750_CONT_L  0x20
#define BH1750_ONE_T   0x80
#define BH1750_ONE_H   0xA0
#define BH1750_ONE_L   0xB0
#define BH1750_ONE_T_L 0xE0
#define BH1750_MEAS_MS 180
#define LUX_THRESHOLD  150
#define RELAY_GPIO     23
#define LOG_FILE       "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int bh1750_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    return 0;
}

static int bh1750_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (bh1750_write(fd, BH1750_PWR_ON) < 0) return -1;
    if (bh1750_write(fd, BH1750_RESET) < 0) return -1;
    if (bh1750_write(fd, BH1750_CONT_H | BH1750_ONE_T) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (bh1750_read(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("Error: Failed to write relay GPIO");
        return;
    }
    log_event(state ? "Grow lamp ON" : "Grow lamp OFF");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error initializing BH1750 sensor\n");
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    int relay_state = 0;
    while (g_running) {
        float lux;
        if (bh1750_read_lux(g_i2c_fd, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
        } else {
            log_event("Error: Failed to read lux from sensor");
        }
        gpioDelay(BH1750_MEAS_MS * 1000);
    }

