#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_OPEN_PULSE_WIDTH 1000
#define SERVO_CLOSED_PULSE_WIDTH 2000

#define DEBOUNCE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set LOCK_BUTTON_PIN %d as input\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_BUTTON_PIN %d as input\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on LOCK_BUTTON_PIN %d\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on UNLOCK_BUTTON_PIN %d\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_servo_angle(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    }
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d\n", pulse_width);
    }
}

static void lock_door(void) {
    printf("Locking door...\n");
    set_servo_angle(SERVO_OPEN_PULSE_WIDTH);
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    set_servo_angle(SERVO_CLOSED_PULSE_WIDTH);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    int last_lock_state = 1;
    int last_unlock_state = 1;

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_state = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed\n");
            break;
        }

        if (lock_state == 0 && last_lock_state == 1) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }
        last_lock_state = lock_state;

        if (unlock_state == 0 && last_unlock_state == 1) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }
        last_unlock_state = unlock_state;

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

