static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %u (level %u)\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud) {
    if (gpioSetPullUpDown(pin, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_output(unsigned pin) {
    if (safe_set_mode(pin, PI_OUTPUT) < 0) return -1;
    if (safe_set_pull(pin, PI_PUD_OFF) < 0) return -1;
    return 0;
}

static int safe_input(unsigned pin) {
    if (safe_set_mode(pin, PI_INPUT) < 0) return -1;
    if (safe_set_pull(pin, PI_PUD_OFF) < 0) return -1;
    return 0;
}

static int motor_on(unsigned pin) {
    return safe_write(pin, 1);
}

static int motor_off(unsigned pin) {
    return safe_write(pin, 0);
}

static int motor_pulse(unsigned pin, int duration_ms) {
    if (motor_on(pin) < 0) return -1;
    gpioDelay(duration_ms * 1000);
    if (motor_off(pin) < 0) return -1;
    return 0;
}

static int run_sequence(void) {
    if (motor_pulse(MOTOR1_PIN, MOTOR1_DURATION_MS) < 0) return -1;
    if (motor_pulse(MOTOR2_PIN, MOTOR2_DURATION_MS) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_output(MOTOR1_PIN) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_output(MOTOR2_PIN) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (run_sequence() < 0) {
            fprintf(stderr, "Error: motor pulse failed, exiting\n");
            break;
        }
    }

    /* Ensure motors are off before terminating */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("Haptic feedback system stopped.\n");
    return EXIT_SUCCESS;
}

