/*
 * sound_alarm.c — Raspberry Pi 5 sound-triggered alarm
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c -lzmq
 * Run:    ./sound_alarm [sound_sensor|alarm_node]
 *
 * Wiring (BCM numbering):
 *   LM393 sound sensor  DO  -> GPIO17 (active-low: 0 = sound detected)
 *   Alarm LED           +   -> GPIO27 (with appropriate current-limiting
 *   Alarm LED           -   -> resistor to GND)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#include <zmq.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    27

#define ZMQ_PORT         5555
#define ZMQ_TOPIC        "SOUND_ALERTS"
#define ZMQ_ADDR         "tcp://*"
#define ZMQ_CLIENT_ADDR  "tcp://localhost"

#define POLL_INTERVAL_US 10000          /* 10 ms */
#define ALARM_DURATION_S 1               /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_export(unsigned int pin)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("open(/sys/class/gpio/export)");
        return -1;
    }
    if (dprintf(fd, "%u", pin) < 0) {
        perror("dprintf export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(unsigned int pin)
{
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("open(/sys/class/gpio/unexport)");
        return -1;
    }
    if (dprintf(fd, "%u", pin) < 0) {
        perror("dprintf unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(unsigned int pin, const char *dir)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open(direction)");
        return -1;
    }
    if (dprintf(fd, "%s", dir) < 0) {
        perror("dprintf direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(unsigned int pin, int value)
{
    char path[64];
    char val = value ? '1' : '0';
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open(value)");
        return -1;
    }
    if (dprintf(fd, "%c", val) < 0) {
        perror("dprintf value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_get_value(unsigned int pin)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/value", pin);
