            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (zmq_bind(zmq_sock, ZMQ_ADDR) != 0) {
            zmq_close_all(zmq_sock, zmq_ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
