               ZMQ_ADDR, ZMQ_PORT, ZMQ_TOPIC);
    } else {
        zmq_sock = zmq_socket_new(zmq_ctx, ZMQ_SUB);
        if (!zmq_sock) {
            zmq_ctx_destroy(zmq_ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (zmq_connect(zmq_sock, ZMQ_CLIENT_ADDR) != 0) {
            zmq_close_all(zmq_sock, zmq_ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (zmq_subscribe(zmq_sock, ZMQ_TOPIC) != 0) {
            zmq_close_all(zmq_sock, zmq_ctx);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("Alarm node mode: subscribed to %s:%d (%s)\n",
               ZMQ_CLIENT_ADDR, ZMQ_PORT, ZMQ_TOPIC);
    }

