    char message[256];
    int alarm_active = 0;

    while (g_running) {
        if (strcmp(mode, "sound_sensor") == 0) {
            int sound = gpio_get_value(SOUND_SENSOR_PIN);
            if (sound < 0) {
                fprintf(stderr, "Failed to read sound sensor\n");
                break;
