            if (sound == 0) {  /* active-low: 0 = sound detected */
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
                snprintf(message, sizeof(message),
                         "Sound detected at %s", ts);
                if (zmq_send(zmq_sock, message, strlen(message), 0) < 0) {
                    fprintf(stderr, "Failed to send alert\n");
                } else {
                    printf("Sent alert: %s\n", message);
                }
            }
        } else {
            int rc = zmq_recv_message(zmq_sock, message, sizeof(message));
            if (rc == 0) {
                printf("Received alert: %s\n", message);
                if (!alarm_active) {
                    if (gpio_set_value(ALARM_LED_PIN, 1) == 0) {
                        alarm_active = 1;
