                    } else {
                        fprintf(stderr, "Failed to activate alarm LED\n");
                    }
                }
            } else if (rc == EINTR) {
                /* interrupted by signal — re-check g_running */
            } else {
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    if (alarm_active) {
        gpio_set_value(ALARM_LED_PIN, 0);
    }
    gpio_unexport(SOUND_SENSOR_PIN);
    gpio_unexport(ALARM_LED_PIN);
    gpiod_chip_close(chip);
    zmq_close_all(zmq_sock, zmq_ctx);
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

