#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 68
#define MAX_PULSE_US 1000000

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

/* NEC timing constants (microseconds) */
#define NEC_HDR_MARK   9000
#define NEC_HDR_SPACE  4500
#define NEC_BIT_MARK   560
#define NEC_ONE_SPACE  1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE  2250
#define NEC_TOL        300

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Pulse capture                                                        */
/* ------------------------------------------------------------------ */
typedef struct {
    uint32_t pulse[MAX_PULSES];
    int      count;
} pulse_data_t;

static pulse_data_t pulses;

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 0) {
        pulses.pulse[pulses.count] = tick;
        pulses.count++;
    }
}

/* ------------------------------------------------------------------ */
/* NEC decode                                                          */
/* ------------------------------------------------------------------ */
static bool decode_nec(const pulse_data_t *p, uint32_t *command)
{
    if (p->count < 34) {
        syslog(LOG_ERR, "NEC: too few pulses (%d)", p->count);
        return false;
    }

    /* Header: mark + space */
    if (p->pulse[0] < NEC_HDR_MARK - NEC_TOL || p->pulse[0] > NEC_HDR_MARK + NEC_TOL) {
        syslog(LOG_ERR, "NEC: invalid header mark %u us", p->pulse[0]);
        return false;
    }
    if (p->pulse[1] < NEC_HDR_SPACE - NEC_TOL || p->pulse[1] > NEC_HDR_SPACE + NEC_TOL) {
        syslog(LOG_ERR, "NEC: invalid header space %u us", p->pulse[1]);
        return false;
    }

    uint32_t addr = 0, inv_addr = 0, cmd = 0, inv_cmd = 0;
    for (int i = 0; i < 8; i++) {
        int mark = p->pulse[2 + i * 2];
        int space = p->pulse[3 + i * 2];

        if (mark < NEC_BIT_MARK - NEC_TOL || mark > NEC_BIT_MARK + NEC_TOL) {
            syslog(LOG_ERR, "NEC: bit %d mark out of range %u us", i, mark);
            return false;
        }

        if (space > NEC_ONE_SPACE - NEC_TOL && space < NEC_ONE_SPACE + NEC_TOL) {
            addr |= (1u << i);
        } else if (space > NEC_ZERO_SPACE - NEC_TOL && space < NEC_ZERO_SPACE + NEC_TOL) {
            /* zero bit */
        } else {
            syslog(LOG_ERR, "NEC: bit %d space out of range %u us", i, space);
            return false;
        }
    }

    for (int i = 0; i < 8; i++) {
        int mark = p->pulse[18 + i * 2];
        int space = p->pulse[19 + i * 2];

        if (mark < NEC_BIT_MARK - NEC_TOL || mark > NEC_BIT_MARK + NEC_TOL) {
            syslog(LOG_ERR, "NEC: inv bit %d mark out of range %u us", i, mark);
            return false;
        }

        if (space > NEC_ONE_SPACE - NEC_TOL && space < NEC_ONE_SPACE + NEC_TOL) {
            inv_addr |= (1u << i);
        } else if (space > NEC_ZERO_SPACE - NEC_TOL && space < NEC_ZERO_SPACE + NEC_TOL) {
            /* zero bit */
        } else {
            syslog(LOG_ERR, "NEC: inv bit %d space out of range %u us", i, space);
            return false;
        }
    }

    for (int i = 0; i < 16; i++) {
        int mark = p->pulse[34 + i * 2];
        int space = p->pulse[35 + i * 2];

        if (mark < NEC_BIT_MARK - NEC_TOL || mark > NEC_BIT_MARK + NEC_TOL) {
            syslog(LOG_ERR, "NEC: cmd bit %d mark out of range %u us", i, mark);
            return false;
        }

        if (space > NEC_ONE_SPACE - NEC_TOL && space < NEC_ONE_SPACE + NEC_TOL) {
            cmd |= (1u << i);
        } else if (space > NEC_ZERO_SPACE - NEC_TOL && space < NEC_ZERO_SPACE + NEC_TOL) {
            /* zero bit */
        } else {
            syslog(LOG_ERR, "NEC: cmd bit %d space out of range %u us", i, space);
            return false;
        }
    }

    for (int i = 0; i < 16; i++) {
        int mark = p->pulse[50 + i * 2];
        int space = p->pulse[51 + i * 2];

        if (mark < NEC_BIT_MARK - NEC_TOL || mark > NEC_BIT_MARK + NEC_TOL) {
            syslog(LOG_ERR, "NEC: inv cmd bit %d mark out of range %u us", i, mark);
            return false;
        }

