        fprintf(stderr, "BH1750 power-on write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    unsigned char data[2];
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    unsigned int raw = ((unsigned int)data[0] << 8) | data[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux[NUM_SENSORS])
{
    char buffer[256];
    int len = snprintf(buffer, sizeof(buffer),
                       "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f",
                       1, lux[0], 2, lux[1], 3, lux[2], 4, lux[3]);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed or truncated\n");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "inet_pton(%s): invalid address\n", MULTICAST_ADDR);
        return -1;
    }

    if (sendto(g_udp_sock, buffer, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_fds[i] = init_i2c(i + 1);
        if (g_i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize sensor %d\n", i + 1);
            for (int j = 0; j < i; j++)
                close(g_i2c_fds[j]);
            return EXIT_FAILURE;
        }
    }

    g_udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_sock < 0) {
        perror("socket");
        for (int i = 0; i < NUM_SENSORS; i++)
            close(g_i2c_fds[i]);
        return EXIT_FAILURE;
    }

    while (!g_terminate) {
        float lux[NUM_SENSORS];
        int ok[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            lux[i] = NAN;
            ok[i] = 0;
        }

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_terminate)
                break;
            if (read_bh1750(g_i2c_fds[i], &lux[i]) == 0) {
                ok[i] = 1;
            } else {
                fprintf(stderr, "Sensor %d read failed; using NaN\n", i + 1);
            }
        }

        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_fds[i] >= 0)
            close(g_i2c_fds[i]);
    }
    if (g_udp_sock >= 0)
        close(g_udp_sock);

    return EXIT_SUCCESS;
}

