#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "airflow_log.txt"
#define READ_RETRIES   3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD  1

/* AWM7300V 14-bit flow value occupies the lower 14 bits of the 16-bit word.
 * Bits [15:2] = flow, bits [1:0] = status/parity. */
#define FLOW_MASK      0x3FFF
#define STATUS_MASK    0xC000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

static int i2c_set_slave(int fd, uint8_t addr)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Issue a zero-length write to generate a start condition, then read 2 bytes.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_2bytes(int fd, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, buf, 0) < 0) {
        /* ENXIO typically means the slave is not present. */
        if (errno == ENXIO)
            return -2;  /* sensor absent */
        fprintf(stderr, "I2C write (start): %s\n", strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "I2C read: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read: short read (%zd bytes)\n", n);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_airflow(uint16_t *flow_out)
{
    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        int rc = i2c_read_2bytes(g_i2c_fd, flow_out);
        if (rc == 0)
            return 0;
        if (rc == -2) {
            /* Sensor absent — log and continue. */
            return -2;
        }
        if (attempt < READ_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static float extract_flow(uint16_t raw)
{
    uint16_t flow = raw & FLOW_MASK;
    /* Bits [13:0] are the 14-bit flow value; shift right 2. */
    return (float)flow >> 2;
}

static void log_airflow(FILE *fp, float flow)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f SLPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    uint8_t slave = 0x48;  /* AWM7300V default I2C address */
    if (i2c_set_slave(g_i2c_fd, slave) < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw;
        int rc = read_airflow(&raw);

        if (rc == 0) {
            float flow = extract_flow(raw);
            log_airflow(g_log_fp, flow);
            printf("Flow: %.2f SLPM\n", flow);
        } else if (rc == -2) {
            fprintf(stderr, "Sensor absent (0x%02X not responding).\n", slave);
        } else {
            fprintf(stderr, "I2C read failed after %d retries.\n", READ_RETRIES);
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

