/*
 * AS7341 10-Channel Light/Color Sensor - Plant Health Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Adafruit AS7341 (I2C address 0x60)
 *
 * Reads all 10 spectral channels (F1-F8, Clear, NIR) every 5 s,
 * computes a simplified lux approximation, and logs to
 * spectral_log.csv with timestamps.
 *
 * Build:  gcc -O2 -Wall -Wextra -o as7341_plant as7341_plant.c
 * Run:    ./as7341_plant   (user must have i2c enabled and /dev/i2c-1 created)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 constants (from Adafruit datasheet) ---- */
#define AS7341_ADDR        0x60
#define AS7341_ID          0x00
#define AS7341_ID_VAL      0x41   /* AS7341 part ID */

#define AS7341_ENABLE      0x80
#define AS7341_ENABLE_PON  0x01
#define AS7341_ENABLE_SP_EN 0x02

#define AS7341_CFG6        0x08
#define AS7341_CFG6_SMUX   0x0F   /* 0x0F = 8 channels, auto-increment */

#define AS7341_CH_LIST     0x30
#define AS7341_CH_LIST_F1  0x31
#define AS7341_CH_LIST_F2  0x32
#define AS7341_CH_LIST_F3  0x33
#define AS7341_CH_LIST_F4  0x34
#define AS7341_CH_LIST_F5  0x35
#define AS7341_CH_LIST_F6  0x36
#define AS7341_CH_LIST_F7  0x37
#define AS7341_CH_LIST_F8  0x38
#define AS7341_CH_LIST_CLEAR 0x39
#define AS7341_CH_LIST_NIR  0x3A

#define AS7341_ALS_DATA   0x20
#define AS7341_ALS_DATA_LOW 0x21
#define AS7341_ALS_DATA_HIGH 0x22

#define I2C_BUS           "/dev/i2c-1"
#define LOG_FILE          "spectral_log.csv"
#define SAMPLE_PERIOD_S   5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- Sensor operations ---- */
static int as7341_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_ID, &id) != 0) {
        fprintf(stderr, "Cannot read AS7341 ID register - sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_ID_VAL) {
        fprintf(stderr, "Unexpected AS7341 ID: 0x%02X (expected 0x%02X).\n",
                id, AS7341_ID_VAL);
        return -1;
    }
    printf("AS7341 detected (ID = 0x%02X).\n", id);

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms power-up delay */

    /* Configure SMUX: 8 channels, auto-increment */
    if (i2c_write_reg8(fd, AS7341_CFG6, AS7341_CFG6_SMUX) != 0)
        return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_ENABLE,
                       AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    return 0;
}

static int as7341_read_spectral(int fd, uint16_t ch[10])
{
    /* Trigger a single measurement by setting SP_EN with PON already set */
    if (i2c_write_reg8(fd, AS7341_ENABLE,
                       AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    /* Wait for conversion to complete (max ~6.5 ms for 8 channels) */
    usleep(7000);

    /* Read each channel (low byte first, then high byte) */
    for (int i = 0; i < 10; i++) {
        uint16_t val = 0;
        uint8_t  reg = (i < 8) ? (uint8_t)(AS7341_CH_LIST + i)
                              : (uint8_t)(AS7341_CH_LIST_F1 + (i - 8));
        if (i2c_read_reg16(fd, reg, &val) != 0)
            return -1;
        ch[i] = val;
    }
    return 0;
}

/* ---- Lux approximation (simplified) ---- */
static float as7341_lux_approx(const uint16_t ch[10])
{
    /* Clear channel intensity is a proxy for ambient light */
    float clear = (float)ch[8];
    float sum   = 0.0f;
    for (int i = 0; i < 8; i++)
        sum += (float)ch[i];

    /* Lux ≈ Clear × (Sum / Clear) × scaling factor */
    return clear * (sum / clear) * 0.1f;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, const uint16_t ch[10], float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            ts,
            ch[0], ch[1], ch[2], ch[3], ch[4], ch[5], ch[6], ch[7], ch[8], lux);
    fflush(fp);
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (as7341_init(fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        goto cleanup;
    }

    /* Open log file */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(fp);
    }

    printf("Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    /* Main sampling loop */
    while (g_running) {
        uint16_t ch[10];
        float lux;

        if (as7341_read_spectral(fd, ch) != 0) {
            fprintf(stderr, "Spectral read failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        lux = as7341_lux_approx(ch);

        if (log_data(fp, ch, lux) != 0) {
            fprintf(stderr, "Log write failed.\n");
        }

        printf("F1=%u F2=%u F3=%u F4=%u F5=%u F6=%u F7=%u F8=%u Clear=%u NIR=%u Lux=%.2f\n",
               ch[0], ch[1], ch[2], ch[3], ch[4], ch[5], ch[6], ch[7], ch[8], lux, lux);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp)  fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

