#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <getopt.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x50
#define DEFAULT_LOG_FILE "seismic_data.csv"
#define DEFAULT_INTERVAL 1.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define I2C_BUS "/dev/i2c-1"

/* D7S register addresses (verified against datasheet) */
#define D7S_REG_X_LSB 0x02
#define D7S_REG_X_MSB 0x03
#define D7S_REG_Y_LSB 0x04
#define D7S_REG_Y_MSB 0x05
#define D7S_REG_Z_LSB 0x06
#define D7S_REG_Z_MSB 0x07
#define D7S_REG_CTRL 0x08
#define D7S_REG_STATUS 0x09

/* CTRL register: 0x00 = power down, 0x01 = normal mode, 0x02 = high range */
#define D7S_CTRL_NORMAL 0x01

static volatile sig_atomic_t program_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static FILE *error_log = NULL;
static double interval = DEFAULT_INTERVAL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static char log_filename[256] = DEFAULT_LOG_FILE;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (error_log) {
        fprintf(error_log, "%s: %s (errno: %s)\n", ts, message, strerror(errno));
        fflush(error_log);
    }
    fprintf(stderr, "%s: %s (errno: %s)\n", ts, message, strerror(errno));
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int init_d7s(int fd) {
    uint8_t status;
    if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0) {
        log_error("Cannot read D7S status register - sensor may be absent");
        return -1;
    }
    if (status & 0x01) {
        log_error("D7S is in sleep mode; waking up");
        if (i2c_write_reg8(fd, D7S_REG_CTRL, D7S_CTRL_NORMAL) < 0) {
            log_error("Failed to set D7S to normal mode");
            return -1;
        }
        usleep(10000);
    }
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg8(fd, D7S_REG_X_LSB, &x_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_X_MSB, &x_msb) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_LSB, &y_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Y_MSB, &y_msb) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_LSB, &z_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_REG_Z_MSB, &z_msb) < 0) return -1;

    raw_x = (int16_t)((x_msb << 8) | x_lsb);
    raw_y = (int16_t)((y_msb << 8) | y_lsb);
    raw_z = (int16_t)((z_msb << 8) | z_lsb);

    /* D7S sensitivity: 1 mg/LSB = 0.001 g/LSB */
    *x = (float)raw_x * 0.001f;
    *y = (float)raw_y * 0.001f;
    *z = (float)raw_z * 0.001f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log) {
        fflush(error_log);
        fclose(error_log);
        error_log = NULL;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atof(optarg);
                if (interval <= 0.0) {
                    fprintf(stderr, "Invalid interval; using default %.1f s\n", DEFAULT_INTERVAL);
                    interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                strncpy(log_filename, optarg, sizeof(log_filename) - 1);
                log_filename[sizeof(log_filename) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f csv_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    error_log = fopen("seismic_error.log", "a");
    if (!error_log) {
        fprintf(stderr, "Warning: cannot open error log; errors will go to stderr\n");
    }

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        log_error("Cannot open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "# timestamp,x_g,y_g,z_g\n");
    fflush(log_file);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Cannot open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Cannot set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_d7s(i2c_fd) < 0) {
        log_error("D7S initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging acceleration data to %s every %.1f s. Press Ctrl+C to stop.\n", log_filename, interval);

    while (program_running) {
        float x, y, z;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && program_running; attempt++) {
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                success = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (success) {
            log_data(log_file, x, y, z);
        } else {
            log_error("Failed to read acceleration after retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < (int)(interval * 10.0) && program_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

