    raw_y = (int16_t)((y_msb << 8) | y_lsb);
    raw_z = (int16_t)((z_msb << 8) | z_lsb);

    /* D7S sensitivity: 1 mg/LSB = 0.001 g/LSB */
    *x = (float)raw_x * 0.001f;
    *y = (float)raw_y * 0.001f;
    *z = (float)raw_z * 0.001f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log) {
        fflush(error_log);
        fclose(error_log);
        error_log = NULL;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atof(optarg);
                if (interval <= 0.0) {
                    fprintf(stderr, "Invalid interval; using default %.1f s\n", DEFAULT_INTERVAL);
                    interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                strncpy(log_filename, optarg, sizeof(log_filename) - 1);
                log_filename[sizeof(log_filename) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f csv_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    error_log = fopen("seismic_error.log", "a");
    if (!error_log) {
        fprintf(stderr, "Warning: cannot open error log; errors will go to stderr\n");
    }

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        log_error("Cannot open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "# timestamp,x_g,y_g,z_g\n");
    fflush(log_file);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Cannot open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Cannot set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_d7s(i2c_fd) < 0) {
        log_error("D7S initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging acceleration data to %s every %.1f s. Press Ctrl+C to stop.\n", log_filename, interval);

    while (program_running) {
        float x, y, z;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && program_running; attempt++) {
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                success = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (success) {
            log_data(log_file, x, y, z);
        } else {
            log_error("Failed to read acceleration after retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < (int)(interval * 10.0) && program_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

