#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_H  0x10
#define BH1750_CONV_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: got %zd bytes, expected 2: %s\n", n, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    if (i2c_write(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write(fd, BH1750_RESET) < 0) return -1;
    if (i2c_write(fd, BH1750_CONT_H) < 0) return -1;

    usleep(BH1750_CONV_MS * 1000);

    uint16_t raw;
    if (i2c_read16(fd, &raw) < 0) return -1;

    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    int ttl = MULTICAST_TTL;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sockfd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buf[32];
    int len = snprintf(buf, sizeof(buf), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "snprintf failed\n");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, buf, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux;
        if (read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in 1 s...\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Multicast send failed\n");
            }
        }
        sleep(1);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

