/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 * Reads TLV frames, extracts range/velocity, and logs to CSV.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar radar.c -lm
 * Run:    ./radar
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <math.h>

#define UART_DEVICE      "/dev/ttyS0"
#define BAUD_RATE        B921600
#define CSV_FILE         "radar_data.csv"
#define READ_BUF_SIZE    4096
#define FRAME_BUF_SIZE   65536
#define MAGIC_WORD       {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08}
#define MAGIC_WORD_LEN   8
#define TLV_HEADER_LEN   8
#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE  2
#define MAX_OBJECTS        100
#define MAX_RANGE_M        100.0f
#define MAX_VEL_MPS        50.0f

/* TI mmWave SDK frame structures (little-endian, as transmitted) */
typedef struct {
    uint32_t magic[2];          /* 0x0102, 0x0304, 0x0506, 0x0708 */
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) frame_header_t;

typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) tlv_header_t;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    int16_t  x;
    int16_t  y;
    int16_t  z;
} __attribute__((packed)) detected_obj_t;

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_csv_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;   /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_csv_fp) {
        fflush(g_csv_fp);
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
}

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(stderr, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
}

static int find_magic(const uint8_t *buf, int len)
{
    for (int i = 0; i <= len - MAGIC_WORD_LEN; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_WORD_LEN) == 0)
            return i;
    }
    return -1;
}

static int read_exact(int fd, uint8_t *buf, int need)
{
    int got = 0;
    while (got < need) {
        ssize_t n = read(fd, buf + got, need - got);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) {
            log_error("UART read returned 0 (device disconnected?)");
            return -1;
        }
        got += (int)n;
    }
    return got;
}

static int read_frame(int fd, uint8_t *frame, int *frame_len)
{
    int hdr_len = (int)sizeof(frame_header_t);
    int hdr_got = read_exact(fd, frame, hdr_len);
    if (hdr_got < 0) return -1;
    if (hdr_got < hdr_len) {
        /* partial header — discard remainder of partial magic word */
        int discard = hdr_got < MAGIC_WORD_LEN ? hdr_got : MAGIC_WORD_LEN;
        lseek(fd, discard, SEEK_CUR);
        return -1;
    }

    frame_header_t *fh = (frame_header_t *)frame;
    uint32_t total_len = fh->total_packet_len;
    if (total_len < hdr_len || total_len > FRAME_BUF_SIZE) {
        log_error("Invalid total packet length");
        return -1;
    }

    int need = (int)total_len;
    if (need > FRAME_BUF_SIZE) need = FRAME_BUF_SIZE; /* cap to buffer */

    int got = read_exact(fd, frame + hdr_len, need);
    if (got < 0) return -1;
    if (got < need) {
        /* partial frame — keep what we have and resync */
        int discard = got < MAGIC_WORD_LEN ? got : MAGIC_WORD_LEN;
        lseek(fd, discard, SEEK_CUR);
        return -1;
    }

    *frame_len = total_len;
    return 0;
}

static int process_frame(const uint8_t *frame, int frame_len)
{
    if (frame_len < (int)sizeof(frame_header_t)) {
        log_error("Frame too short for header");
        return -1;
    }

    frame_header_t *fh = (frame_header_t *)frame;
    uint32_t num_tlvs = fh->num_tlvs;
    uint32_t num_obj  = fh->num_detected_obj;

    if (num_tlvs == 0 || num_obj == 0) {
        log_error("Zero TLVs or objects in frame");
        return -1;
    }

    int offset = (int)sizeof(frame_header_t);
    int obj_idx = 0;

    for (uint32_t t = 0; t < num_tlvs; t++) {
        if (offset + (int)sizeof(tlv_header_t) > frame_len) {
            log_error("TLV header out of bounds");
            return -1;
        }

        tlv_header_t *tlv = (tlv_header_t *)(frame + offset);
        uint32_t tlv_type = tlv->type;
        uint32_t tlv_len  = tlv->length;

        offset += sizeof(tlv_header_t);

        if (offset + (int)tlv_len > frame_len) {
            log_error("TLV payload out of bounds");
            return -1;
        }

        if (tlv_type == TLV_TYPE_DETECTED_POINTS) {
            if (tlv_len < (uint32_t)(num_obj * sizeof(detected_obj_t))) {
                log_error("Detected points TLV too short");
                return -1;
            }

            const detected_obj_t *objs =
                (const detected_obj_t *)(frame + offset);

            for (uint32_t i = 0; i < num_obj; i++) {
                float range_m  = (float)objs[i].range_idx * 0.0438f; /* ~0.0438 m/idx */
                float vel_mps  = (float)objs[i].doppler_idx * 0.0503f; /* ~0.0503 m/s/idx */

                if (range_m > MAX_RANGE_M || vel_mps > MAX_VEL_MPS) {
                    log_error("Out-of-range object");
                    continue;
                }

                if (fprintf(g_csv_fp, "%ld,%d,%.3f,%.3f\n",
                            (long)time(NULL), obj_idx, range_m, vel_mps) < 0) {
                    log_error("fprintf to CSV failed");
                    return -1;
                }
                obj_idx++;
            }
        }

        offset += tlv_len;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        log_error("UART initialization failed");
        return 1;
    }

    g_csv_fp = fopen(CSV_FILE, "a");
    if (!g_csv_fp) {
        log_error("fopen CSV failed");
        close(g_uart_fd);
        g_uart_fd = -1;
        return 1;
    }

    fprintf(g_csv_fp, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(g_csv_fp);

    uint8_t *frame = malloc(FRAME_BUF_SIZE);
    if (!frame) {
        log_error("malloc failed");
        cleanup();
        return 1;
    }

    fprintf(stderr, "AWR1642 radar reader started on %s @ 921600 baud.\n", UART_DEVICE);
    fprintf(stderr, "Logging to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (g_running) {
        int frame_len = 0;
        if (read_frame(g_uart_fd, frame, &frame_len) < 0) {
            if (!g_running) break;
            continue;
        }

        if (process_frame(frame, frame_len) < 0) {
            if (!g_running) break;
            continue;
        }

        fflush(g_csv_fp);
    }

    free(frame);
    cleanup();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

