#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 512
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_SEC 0.1

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (tcflush(fd, TCIOFLUSH) != 0) {
        fprintf(stderr, "Warning: tcflush failed: %s\n", strerror(errno));
    }

    return fd;
}

static int parse_line(const char *line, float *timestamp, float *range) {
    char *endptr = NULL;
    errno = 0;
    float ts = strtof(line, &endptr);
    if (errno != 0 || endptr == line || *endptr != ',') {
        return -1;
    }
    const char *range_str = endptr + 1;
    errno = 0;
    float r = strtof(range_str, &endptr);
    if (errno != 0 || endptr == range_str || (*endptr != '\n' && *endptr != '\0')) {
        return -1;
    }
    *timestamp = ts;
    *range = r;
    return 0;
}

static void log_detection(float timestamp, float range) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp_str[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[256];

    while (program_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int sel = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }

        if (sel == 0) {
            fprintf(stderr, "UART read timeout — sensor may be absent or bus error.\n");
            continue;
        }

        ssize_t bytes_read = read(uart_fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            continue;
        }

        read_buf[bytes_read] = '\0';

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                float timestamp, range;
                if (parse_line(line_buf, &timestamp, &range) == 0) {
                    log_detection(timestamp, range);
                } else {
                    fprintf(stderr, "Invalid data: '%s'\n", line_buf);
                }

                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line too long, discarding.\n");
                    line_len = 0;
                }
            }
        }
    }

    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

